alter table public.strain_scorecard add constraint strain_scorecard_sells_well_check CHECK ((sells_well = ANY (ARRAY['strong'::text, 'steady'::text, 'slow'::text, 'unknown'::text])));
alter table public.strain_scorecard add constraint strain_scorecard_status_check CHECK ((status = ANY (ARRAY['favoured'::text, 'keep_for_variety'::text, 'trial'::text, 'retire'::text, 'unreviewed'::text])));
alter table public.suppliers add constraint suppliers_bought_as_check CHECK ((bought_as = ANY (ARRAY['not yet set'::text, 'sound material'::text, 'failed for remediation'::text, 'biomass for extraction'::text, 'our own licence'::text])));
alter table public.task_dependencies add constraint task_dependencies_dep_type_check CHECK ((dep_type = ANY (ARRAY['finish_to_start'::text, 'start_to_start'::text, 'finish_to_finish'::text])));
alter table public.task_dependencies add constraint task_dependencies_no_self_reference CHECK ((task_id IS DISTINCT FROM depends_on_id));
alter table public.tasks add constraint tasks_priority_check CHECK ((priority = ANY (ARRAY['P0'::text, 'P1'::text, 'P2'::text, 'P3'::text])));
alter table public.tasks add constraint tasks_status_check CHECK ((status = ANY (ARRAY['todo'::text, 'in_progress'::text, 'done'::text, 'blocked'::text])));
alter table public.templates add constraint templates_category_check CHECK ((category = ANY (ARRAY['Financial'::text, 'Planning'::text, 'Inventory'::text, 'Production'::text, 'Sales'::text, 'Marketing'::text, 'Compliance'::text, 'HR'::text])));
alter table public.templates add constraint templates_complexity_check CHECK ((complexity = ANY (ARRAY['beginner'::text, 'intermediate'::text, 'advanced'::text])));
alter table public.templates add constraint templates_template_type_check CHECK ((template_type = ANY (ARRAY['space'::text, 'folder'::text, 'list'::text, 'task'::text, 'doc'::text, 'view'::text, 'whiteboard'::text, 'form'::text])));
alter table public.tg_overrides add constraint override_must_be_attributed CHECK (((set_by IS NOT NULL) OR (length(btrim(COALESCE(set_by_name, ''::text))) >= 3)));
alter table public.tg_overrides add constraint reason_is_meaningful CHECK ((length(btrim(reason)) >= 10));
alter table public.third_party_purchases add constraint third_party_purchases_material_class_check CHECK ((material_class = ANY (ARRAY['trim'::text, 'flower'::text, 'concentrate'::text, 'seed'::text, 'clone'::text, 'other'::text])));
alter table public.third_party_purchases add constraint third_party_purchases_quantity_check CHECK ((quantity > (0)::numeric));
alter table public.third_party_purchases add constraint third_party_purchases_status_check CHECK ((status = ANY (ARRAY['received'::text, 'quarantine'::text, 'released'::text, 'allocated'::text, 'in_production'::text, 'finished'::text, 'rejected'::text])));
alter table public.time_entries add constraint time_entries_check CHECK (((clock_out IS NULL) OR (clock_in IS NULL) OR (clock_out > clock_in)));
alter table public.time_entries add constraint time_entries_source_check CHECK ((source = ANY (ARRAY['kiosk'::text, 'scanner'::text, 'mobile'::text, 'web'::text, 'payroll_import'::text, 'manual'::text])));
alter table public.time_off_requests add constraint time_off_requests_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'approved'::text, 'denied'::text, 'cancelled'::text, 'withdrawn'::text])));
alter table public.turnaround_policies add constraint turnaround_policies_applies_to_check CHECK ((applies_to = ANY (ARRAY['purchased'::text, 'manufactured'::text, 'grown'::text, 'any'::text])));
alter table public.turnaround_policies add constraint turnaround_policies_scope_check CHECK ((scope = ANY (ARRAY['default'::text, 'category'::text, 'sku'::text, 'item'::text, 'brand'::text])));
alter table public.ui_labels add constraint ui_labels_kind_check CHECK ((kind = ANY (ARRAY['page_title'::text, 'section'::text, 'button'::text, 'field'::text, 'tooltip'::text, 'empty_state'::text, 'label'::text, 'help'::text])));
alter table public.user_settings add constraint user_settings_theme_check CHECK ((theme = ANY (ARRAY['dark'::text, 'light'::text])));
alter table public.valuation_overrides add constraint valuation_overrides_check CHECK (((package_tag IS NOT NULL) OR (harvest_name IS NOT NULL)));
alter table public.vendor_notes add constraint vendor_notes_category_check CHECK ((category = ANY (ARRAY['general'::text, 'pricing'::text, 'terms'::text, 'quality'::text, 'delivery'::text, 'order'::text])));
alter table public.verification_checks add constraint process_check_declares_in_flight CHECK (((measures_a_process = false) OR ((in_flight_rule IS NOT NULL) AND (length(in_flight_rule) >= 40))));
