CREATE OR REPLACE FUNCTION public.f_can_see_page(p_user uuid, p_view_key text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with me as (
    select u.role::text as role, coalesce(r.rank, 0) as rank
    from app_users u left join app_roles r on r.role = u.role::text
    where u.user_id = p_user
  ),
  page as (
    select nr.view_key, nr.category,
           coalesce(sp.min_rank, 0) as needs_rank,
           coalesce(pc.is_shared, false) as shared
    from nav_registry nr
    left join sensitive_page_policy sp on sp.view_key = nr.view_key
    left join page_category_policy  pc on pc.category = nr.category
    where nr.view_key = p_view_key and nr.enabled
  )
  select exists (
    select 1 from page p, me
    -- DEPTH: rank must clear the page's sensitivity
    where me.rank >= p.needs_rank
    -- BREADTH: the category is shared, or granted to this user
      and (p.shared
           or exists (select 1 from user_department_access d
                      where d.user_id = p_user and d.category = p.category)
           -- owner and executive are not department-bound
           or me.rank >= 90)
  );
$function$
;
CREATE OR REPLACE FUNCTION public.f_check_reason(p_action text, p_code text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_review_date date DEFAULT NULL::date, p_second_approver text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare pol reason_policy; rc reason_code_catalog; valid text;
begin
  select * into pol from reason_policy where action_key = p_action;
  if not found then
    raise exception 'No reason policy exists for the action "%". Add a row to reason_policy first, so the rule is visible in Settings rather than buried in code.', p_action
      using errcode = 'check_violation';
  end if;

  if not pol.enforced then return; end if;

  select string_agg(code, ', ' order by sort_order) into valid
  from reason_code_catalog
  where active and (applies_to = '{}' or p_action = any(applies_to));

  if pol.require_code then
    if coalesce(p_code,'') = '' then
      raise exception '%', 'A reason CODE is required to ' || lower(pol.label) || '.' ||
        chr(10) || 'Valid codes: ' || coalesce(valid,'(none active)') ||
        chr(10) || 'Why: a code can be counted and trended across months. Free text cannot.'
        using errcode = 'check_violation';
    end if;
    select * into rc from reason_code_catalog where code = p_code and active;
    if not found then
      raise exception '%', '"' || p_code || '" is not an active reason code.' ||
        chr(10) || 'Valid codes: ' || coalesce(valid,'(none active)')
        using errcode = 'check_violation';
    end if;
    if rc.applies_to <> '{}' and not (p_action = any(rc.applies_to)) then
      raise exception '%', 'Reason code "' || p_code || '" does not apply to ' || pol.label ||
        '. It is restricted to: ' || array_to_string(rc.applies_to, ', ')
        using errcode = 'check_violation';
    end if;
  end if;

  if (pol.require_note or coalesce(rc.requires_note,false))
     and length(trim(coalesce(p_note,''))) < pol.min_note_chars then
    raise exception '%', 'A written reason of at least ' || pol.min_note_chars ||
      ' characters is required to ' || lower(pol.label) || '. You gave ' ||
      length(trim(coalesce(p_note,''))) || '.' || chr(10) ||
      'Why: in six months nobody will remember what a two-word note meant. Say what differs and what you decided.'
      using errcode = 'check_violation';
  end if;

  if (pol.require_review_date or coalesce(rc.requires_review_date,false)) and p_review_date is null then
    raise exception '%', 'A review date is required to ' || lower(pol.label) ||
      '. This is postponing, not closing - it must come back on a date somebody owns.'
      using errcode = 'check_violation';
  end if;

  if pol.require_second_approver and coalesce(p_second_approver,'') = '' then
    raise exception '%', 'A second approver is required to ' || lower(pol.label) ||
      '. Separation of duties: the person proposing cannot be the only person agreeing.'
      using errcode = 'check_violation';
  end if;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_clear_ai_key()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_role text;
begin
  select role::text into v_role from app_users where user_id = auth.uid();
  if v_role is null or v_role not in ('owner','executive') then
    return jsonb_build_object('ok', false, 'message', 'Only an owner or an executive can remove the company key.');
  end if;
  update app_secrets set value = '' where key = 'ANTHROPIC_API_KEY';
  return jsonb_build_object('ok', true,
    'message', 'Removed. Questions fall back to the desktop bridge, which is free and slower.');
end $function$
;
CREATE OR REPLACE FUNCTION public.f_close_finding(p_fingerprint text, p_closed_by text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r finding_remediation; proof bigint; proof_at timestamptz;
begin
  select * into r from finding_remediation where fingerprint = p_fingerprint;
  if not found then
    raise exception 'No finding with fingerprint %', p_fingerprint using errcode='no_data_found';
  end if;
  if r.state = 'closed' then
    return 'Already closed at ' || r.closed_at;
  end if;

  select cl.id, cl.ran_at into proof, proof_at
  from conformance_ledger cl
  where cl.verdict = 'PASS'
    and cl.ran_at > r.raised_at
    and cl.subject_kind = r.subject_kind
    and cl.subject_ref  = r.subject_ref
    and (r.policy_key is null or cl.policy_key = r.policy_key)
  order by cl.ran_at desc
  limit 1;

  if proof is null then
    raise exception '%', 'CANNOT CLOSE ' || p_fingerprint || E'.\n' ||
      'Closure requires the check that raised this finding to PASS again, recorded in ' ||
      'conformance_ledger after ' || r.raised_at || '. No such row exists.' || E'\n' ||
      'Claiming a fix is not evidence; the check passing is. Re-run the checker for ' ||
      coalesce(r.subject_kind,'?') || ' / ' || coalesce(r.subject_ref,'?') ||
      ' and try again.' || E'\n' ||
      'If this finding should stand as an accepted risk instead, set state=''accepted_risk'' ' ||
      'with 40+ characters of accepted_reason and a named accepted_by.'
      using errcode = 'check_violation';
  end if;

  update finding_remediation
     set state = 'closed', closed_at = now(), closed_by_ledger_id = proof,
         claimed_by = coalesce(p_closed_by, claimed_by), updated_at = now()
   where fingerprint = p_fingerprint;

  return 'Closed. Proof: conformance_ledger row ' || proof || ' PASSED at ' || proof_at || '.';
end $function$
;
CREATE OR REPLACE FUNCTION public.f_company_key(p_name text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select nullif(btrim(regexp_replace(
    regexp_replace(lower(coalesce(p_name,'')),
      '\s*[-,]?\s*(inc|inc\.|llc|l\.l\.c\.|corp|corp\.|corporation|company|co|ltd|limited)\b\.?', '', 'g'),
    '[^a-z0-9]+', ' ', 'g')), '');
$function$
;
CREATE OR REPLACE FUNCTION public.f_concentrate_rate_per_lb(p_item text)
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(
    (select m.dollars_per_gram * 453.592 from public.concentrate_rate_map m
      where p_item ilike m.match_pattern order by m.sort limit 1),
    (select g.badder_crude_per_pound from public.v_cost_of_goods g))
$function$
;
CREATE OR REPLACE FUNCTION public.f_copy_role(p_from text, p_new_key text, p_new_label text, p_rank integer DEFAULT NULL::integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  if exists (select 1 from app_roles where role = p_new_key) then
    return 'A role called ' || p_new_key || ' already exists. Pick another key.';
  end if;
  if not exists (select 1 from app_roles where role = p_from) then
    return 'No role called ' || p_from || ' to copy from.';
  end if;
  insert into app_roles (role, label, rank, built_in)
  select p_new_key, p_new_label, coalesce(p_rank, rank), false from app_roles where role = p_from;
  insert into role_permissions (role, action, allowed)
  select p_new_key, action, allowed from role_permissions where role = p_from;
  insert into nav_role_visibility (view_key, role, visible)
  select view_key, p_new_key, visible from nav_role_visibility where role = p_from;
  get diagnostics n = row_count;
  return 'Created ' || p_new_label || ' from ' || p_from || ' with '
    || (select count(*) from role_permissions where role = p_new_key)::text || ' permissions and '
    || n::text || ' page grants. Edit it freely - built-in roles stay untouched.';
end $function$
;
CREATE OR REPLACE FUNCTION public.f_date_default(p_user uuid, p_view_key text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
  select jsonb_build_object(
    'preset_key', coalesce(
        (select p.preset_key from user_page_date_default p
          where p.user_id = p_user and p.view_key = p_view_key),
        (select u.default_date_preset from user_settings u where u.user_id = p_user),
        (select case when r.date_column is null then 'all' else 'this_month' end
           from report_registry r
           join nav_registry n on n.table_ref = r.fact_view
          where n.view_key = p_view_key limit 1),
        'this_month'),
    'custom_from', (select p.custom_from from user_page_date_default p
                     where p.user_id = p_user and p.view_key = p_view_key),
    'custom_to',   (select p.custom_to from user_page_date_default p
                     where p.user_id = p_user and p.view_key = p_view_key),
    'scope', coalesce((select u.date_default_scope from user_settings u
                        where u.user_id = p_user), 'remember_last'),
    'source', case
       when exists (select 1 from user_page_date_default p
                     where p.user_id = p_user and p.view_key = p_view_key)
            then 'this user, this page'
       when exists (select 1 from user_settings u
                     where u.user_id = p_user and u.default_date_preset is not null)
            then 'this user, everywhere'
       else 'page default' end
  );
$function$
;
CREATE OR REPLACE FUNCTION public.f_detect_tag_column(p_source uuid)
 RETURNS TABLE(sheet_column text, rows_tested integer, tags_matched integer, matched_metrc integer, confidence text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with sample as (select data from public.sheet_rows where source_id = p_source limit 300),
  cols as (select distinct k from sample, lateral jsonb_object_keys(data) k),
  scored as (
    select c.k as col,
      count(*) as rows_tested,
      count(*) filter (where trim(s.data ->> c.k) ~ '^1A4[A-Z0-9]{21}$') as tags_matched,
      count(*) filter (where exists (
        select 1 from public.metrc_packages p
        where p.raw->>'Label' = trim(s.data ->> c.k))) as matched_metrc
    from cols c cross join sample s group by c.k)
  select col, rows_tested, tags_matched, matched_metrc,
    case
      when matched_metrc::numeric / nullif(rows_tested,0) >= 0.8 then 'CERTAIN — matches real Metrc package tags'
      when tags_matched::numeric / nullif(rows_tested,0) >= 0.8 then 'LIKELY — correct tag format but not found in Metrc'
      when tags_matched > 0 then 'POSSIBLE — some values look like tags'
      else 'NO' end
  from scored where tags_matched > 0 or matched_metrc > 0
  order by matched_metrc desc, tags_matched desc;
$function$
;
CREATE OR REPLACE FUNCTION public.f_document_url(p_storage_path text, p_download boolean DEFAULT false)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case when p_storage_path is null then null else
    'https://fxetuqjryttnypgepsru.supabase.co/functions/v1/document?path='
    || p_storage_path || case when p_download then '&download=1' else '' end
  end;
$function$
;
CREATE OR REPLACE FUNCTION public.f_drain_punch_queue(p_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; v_emp uuid; v_entry uuid; v_src text;
        v_ok int := 0; v_dup int := 0; v_bad int := 0; v_err int := 0;
begin
  for r in select * from public.punch_queue
            where status='queued' order by punched_at limit p_limit
  loop
    select id into v_emp from public.employees
     where (r.login_id is not null and upper(login_id) = upper(r.login_id))
        or (r.badge_code is not null and badge_code = r.badge_code);

    if v_emp is null then
      update public.punch_queue set status='rejected', error='no matching employee',
             attempts = attempts + 1 where id = r.id;
      v_bad := v_bad + 1; continue;
    end if;

    if exists (select 1 from public.time_entries t
                where t.employee_id = v_emp
                  and (abs(extract(epoch from (t.clock_in - r.punched_at))) < 60
                    or abs(extract(epoch from (coalesce(t.clock_out, r.punched_at) - r.punched_at))) < 60)) then
      update public.punch_queue set status='duplicate' where id = r.id;
      v_dup := v_dup + 1; continue;
    end if;

    select coalesce(d.kind,'kiosk') into v_src
    from public.punch_devices d where d.id = r.device_id;
    if v_src not in ('kiosk','scanner') then v_src := 'kiosk'; end if;

    begin
      select f.entry_id into v_entry
      from public.f_punch(v_emp, r.kind, v_src, r.device_id,
                          r.lat, r.lon, r.accuracy_m, r.punched_at) f;
      update public.punch_queue set status='applied', time_entry_id = v_entry,
             attempts = attempts + 1, error = null where id = r.id;
      v_ok := v_ok + 1;
    exception when others then
      update public.punch_queue
         set status = case when attempts + 1 >= 5 then 'rejected' else 'queued' end,
             error = SQLERRM, attempts = attempts + 1 where id = r.id;
      v_err := v_err + 1;
    end;
  end loop;
  return jsonb_build_object('applied', v_ok, 'duplicates', v_dup,
                            'no_match', v_bad, 'errored', v_err);
end $function$
;
CREATE OR REPLACE FUNCTION public.f_employee_capacity_upd()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_emp   uuid;
  v_days  integer;
  v_per   numeric;
  v_start time := time '07:00';
begin
  if not public.f_can_decide_hr() then
    raise exception 'Not permitted to change work schedules. Owner, HR or admin only.'
      using errcode = '42501';
  end if;

  select id into v_emp from public.employees where employee_code = old.employee_code;
  if v_emp is null then
    raise exception 'No employee with code %', old.employee_code;
  end if;

  if new.payroll_target_hours is distinct from old.payroll_target_hours then
    update public.employees set weekly_target_hours = new.payroll_target_hours where id = v_emp;
  end if;

  -- Capacity is a SUM over employee_work_schedules, so a new weekly total
  -- has to be distributed back across days. Even split over the requested
  -- day count, Monday first. Anyone needing uneven days edits the
  -- underlying rows directly — this is the sane default, not the only way.
  if new.weekly_capacity_hours is distinct from old.weekly_capacity_hours
     or new.days_per_week is distinct from old.days_per_week then

    v_days := coalesce(new.days_per_week, old.days_per_week, 5);
    if v_days < 1 or v_days > 7 then
      raise exception 'Days per week must be 1 to 7, got %', v_days;
    end if;
    if coalesce(new.weekly_capacity_hours,0) <= 0 then
      raise exception 'Weekly capacity must be greater than zero';
    end if;

    v_per := round(new.weekly_capacity_hours::numeric / v_days, 2);
    if v_per > 24 then
      raise exception 'That is % hours per day across % days', v_per, v_days;
    end if;

    delete from public.employee_work_schedules where employee_id = v_emp;
    insert into public.employee_work_schedules (employee_id, weekday, start_time, end_time)
    select v_emp, g, v_start, v_start + (v_per || ' hours')::interval
    from generate_series(1, v_days) g;
  end if;

  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_employee_login_id_bi()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.login_id is null and new.full_name is not null then
    begin
      new.login_id := public.f_next_login_id(new.full_name);
    exception when others then
      new.login_id := null;   -- unparseable name: leave it for HR rather than block the hire
    end;
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_endpoint_allowed(p_licence text, p_endpoint text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(
    (select allowed from metrc_endpoint_capability
      where licence = p_licence and endpoint = p_endpoint),
    true);   -- unknown combinations are permitted; only explicit denials block
$function$
;
