   where licence = p_licence and endpoint = p_endpoint and not allowed;
$function$
;
CREATE OR REPLACE FUNCTION public.f_explain_late(p_time_entry_id uuid, p_reason_code text, p_explanation text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_t public.time_entries%rowtype; v_occ uuid;
begin
  select * into v_t from public.time_entries where id = p_time_entry_id;
  if v_t.id is null then raise exception 'No such punch.'; end if;
  if coalesce(v_t.late_minutes,0) <= 0 then
    return jsonb_build_object('ok', true, 'note', 'not late — nothing to explain');
  end if;
  if v_t.work_date <> current_date then
    raise exception 'A reason can only be given on the day. Ask HR to correct an older punch.';
  end if;
  if length(btrim(coalesce(p_explanation,''))) < 4 or coalesce(p_reason_code,'') = '' then
    raise exception 'A reason code and a short explanation are both required.';
  end if;

  select id into v_occ from public.attendance_occurrences
   where employee_id = v_t.employee_id and work_date = v_t.work_date and kind = 'late'
   order by created_at desc limit 1;

  if v_occ is not null then
    update public.attendance_occurrences
       set reason_code = p_reason_code,
           explanation = btrim(p_explanation),
           status = 'awaiting_explanation'
     where id = v_occ;
  else
    insert into public.attendance_occurrences
      (employee_id, work_date, kind, minutes, reason_code, explanation, points, status, time_entry_id)
    select v_t.employee_id, v_t.work_date, 'late', v_t.late_minutes,
           p_reason_code, btrim(p_explanation),
           (select points_late from public.attendance_policy limit 1),
           'awaiting_explanation', v_t.id
    returning id into v_occ;
  end if;

  return jsonb_build_object('ok', true, 'occurrence_id', v_occ,
    'note', 'Recorded. A manager decides whether it is excused — an explanation is '
            'not self-approval, and the points stand until someone rules on them.');
end $function$
;
CREATE OR REPLACE FUNCTION public.f_facility_type(p_licence text)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select lt.facility_type
  from licence_type_prefix lt
  where upper(btrim(coalesce(p_licence,''))) like lt.prefix || '%'
  order by length(lt.prefix) desc
  limit 1
$function$
;
CREATE OR REPLACE FUNCTION public.f_fiscal_year_start(p_on date DEFAULT CURRENT_DATE)
 RETURNS date
 LANGUAGE sql
 STABLE
AS $function$
  select make_date(
    case when extract(month from p_on)::int >= coalesce((select value::int from configurations
                                                          where key='fiscal_year_start_month'), 1)
         then extract(year from p_on)::int else extract(year from p_on)::int - 1 end,
    coalesce((select value::int from configurations where key='fiscal_year_start_month'), 1),
    1);
$function$
;
CREATE OR REPLACE FUNCTION public.f_guard_claim()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_exp date; v_name text; v_date date;
begin
  select e.badge_expires, e.full_name into v_exp, v_name
  from public.employees e where e.id = new.employee_id;
  select o.work_date into v_date from public.open_shifts o where o.id = new.open_shift_id;

  if v_exp is not null and v_date is not null and v_exp < v_date then
    raise exception
      'Cannot claim that shift: % has an agent registration that expires on %, before the shift on %.',
      v_name, v_exp, v_date using errcode='23514';
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_guard_offboarding_close()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_open text; v_name text;
begin
  if new.status <> 'complete' or coalesce(old.status,'') = 'complete' then
    return new;
  end if;

  select e.full_name into v_name from public.employees e where e.id = new.employee_id;

  select string_agg(s.title, '; ' order by s.ordinal) into v_open
  from public.lifecycle_progress p
  join public.lifecycle_steps s on s.id = p.step_id
  where p.employee_id = new.employee_id and s.phase = 'offboarding'
    and s.blocks_close and s.active and p.done_at is null and p.na_reason is null;

  if v_open is not null then
    raise exception
      'Cannot close the departure for %: outstanding obligations — %. Mark each done, or record why it does not apply.',
      coalesce(v_name,'this employee'), v_open using errcode='23514';
  end if;

  -- Belt and braces on the two that carry a deadline, whether or not a
  -- checklist row was ever raised for this person.
  if new.ccc_deactivated_on is null then
    raise exception
      'Cannot close: the Cannabis Agent Registration has not been deactivated in Metrc. An active registration for someone who has left is a finding.'
      using errcode='23514';
  end if;
  if new.system_access_revoked_on is null then
    raise exception
      'Cannot close: system access has not been revoked. Termination must revoke at the identity layer.'
      using errcode='23514';
  end if;

  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_guard_schedulable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_exp date; v_badge text; v_name text; v_status text; v_req text; v_steps text;
begin
  select e.badge_expires, e.metrc_agent_badge, e.full_name, e.status::text
    into v_exp, v_badge, v_name, v_status
  from public.employees e where e.id = new.employee_id;

  if v_name is null then
    raise exception 'No employee record for that id.' using errcode='23503';
  end if;
  if v_status <> 'active' then
    raise exception 'Cannot schedule %: they are not an active employee.', v_name
      using errcode='23514';
  end if;
  if v_badge is null and v_exp is null then
    raise exception
      'Cannot schedule %: no Cannabis Agent Registration on file. A person without a registration cannot legally be on the floor.',
      v_name using errcode='23514';
  end if;
  if v_exp is not null and v_exp < new.work_date then
    raise exception
      'Cannot schedule % on %: their agent registration expired on %. They cannot legally work that day.',
      v_name, new.work_date, v_exp using errcode='23514';
  end if;

  select string_agg(cr.name, ', ') into v_req
  from public.employee_compliance ec
  join public.compliance_requirements cr on cr.id = ec.requirement_id
  where ec.employee_id = new.employee_id and cr.blocks_work and cr.active
    and (ec.status = 'expired'
         or (ec.status = 'held' and ec.expires_on is not null and ec.expires_on < new.work_date));
  if v_req is not null then
    raise exception 'Cannot schedule % on %: expired requirement — %.',
      v_name, new.work_date, v_req using errcode='23514';
  end if;

  -- NEW: onboarding steps marked blocks_start must be done before this person
  -- can be scheduled at all. I-9, agent registration, gowning SOP, PIN.
  select string_agg(s.title, '; ' order by s.ordinal) into v_steps
  from public.lifecycle_progress p
  join public.lifecycle_steps s on s.id = p.step_id
  where p.employee_id = new.employee_id and s.phase = 'onboarding'
    and s.blocks_start and s.active and p.done_at is null and p.na_reason is null;

  if v_steps is not null then
    raise exception
      'Cannot schedule %: onboarding is not complete. Outstanding — %.',
      v_name, v_steps using errcode='23514';
  end if;

  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_hr_audit_pack(p_from date, p_to date)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'period', jsonb_build_object('from', p_from, 'to', p_to, 'generated_at', now()),
    'agents', (select jsonb_agg(jsonb_build_object(
        'name', full_name, 'employee_code', employee_code,
        'agent_licence', metrc_agent_badge, 'expires', badge_expires,
        'status', status::text,
        'valid_through_period', (badge_expires is not null and badge_expires >= p_to)))
      from public.employees where status::text = 'active'),
    'licences_expiring_in_period', (select count(*) from public.employees
       where status::text='active' and badge_expires between p_from and p_to),
    'training_evidence', (select jsonb_agg(jsonb_build_object(
        'employee', full_name, 'document', title, 'version', version,
        'signed_at', signed_at, 'state', state))
      from public.v_document_compliance),
    'documents_unsigned', (select count(*) from public.v_document_compliance where state <> 'signed'),
    'incidents', (select jsonb_agg(jsonb_build_object(
        'reference', incident_no, 'occurred', occurred_at, 'kind', kind,
        'severity', severity, 'osha_recordable', osha_recordable,
        'ccc_reportable', ccc_reportable, 'status', status))
      from public.hr_incidents where occurred_at::date between p_from and p_to),
    'osha_recordable_count', (select count(*) from public.hr_incidents
       where occurred_at::date between p_from and p_to and osha_recordable),
    'ccc_reportable_count', (select count(*) from public.hr_incidents
       where occurred_at::date between p_from and p_to and ccc_reportable),
    'offboarding_obligations_open', (select count(*) from public.v_offboarding_open),
    'lifecycle_legal_outstanding', (select count(*) from public.v_lifecycle_open where is_legal)
  );
$function$
;
CREATE OR REPLACE FUNCTION public.f_hr_deliver_all()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare m record; v_people int; v_batch int; v_msgs int := 0; v_rows int := 0; v_skipped int := 0;
begin
  if not public.f_can_decide_hr() then
    raise exception 'Not permitted to deliver HR messages.' using errcode='42501';
  end if;

  for m in
    select * from public.hr_message
     where approved_at is not null and sent_at is null and cancelled_at is null
     order by created_at
  loop
    insert into public.hr_message_recipient (message_id, employee_id)
    select m.id, r from public.f_resolve_audience(m.audience, m.employee_id) r
    on conflict (message_id, employee_id) do nothing;
    get diagnostics v_people = row_count;

    if v_people = 0 and not exists (
         select 1 from public.hr_message_recipient where message_id = m.id) then
      -- An audience nobody matches is a drafting error, not a delivery. Leave it
      -- unsent and report it rather than marking it done.
      v_skipped := v_skipped + 1;
      continue;
    end if;

    update public.hr_message_recipient
       set delivered_at = now()
     where message_id = m.id and delivered_at is null;
    get diagnostics v_batch = row_count;
    v_rows := v_rows + v_batch;

    update public.hr_message set sent_at = now() where id = m.id;
    v_msgs := v_msgs + 1;
  end loop;

  return jsonb_build_object('messages_sent', v_msgs, 'recipients', v_rows,
                            'skipped_no_audience', v_skipped);
end $function$
;
CREATE OR REPLACE FUNCTION public.f_hr_deliver_approved(p_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_sent int := 0; v_skipped int := 0;
begin
  with ready as (
    select m.id, m.employee_id, m.subject, m.body
    from hr_message m
    where m.approved_by is not null
      and m.approved_at is not null
      and m.sent_at is null
      and m.cancelled_at is null
      and m.employee_id is not null      -- audience sends are not built yet
    order by m.approved_at
    limit greatest(p_limit, 0)
  ), put as (
    insert into messages (user_id, author, body)
    select r.employee_id, 'Human Resources',
           r.subject || E'\n\n' || r.body
    from ready r
    returning 1
  ), done as (
    update hr_message m set sent_at = now()
    where m.id in (select id from ready)
    returning 1
  )
  select count(*) into v_sent from done;

  /* Said out loud rather than silently left behind. An approved message to a
     whole department cannot be delivered yet, and a count that quietly excluded
     them would read as "everything sent". */
  select count(*) into v_skipped
  from hr_message
  where approved_by is not null and sent_at is null and cancelled_at is null
    and employee_id is null;

  return jsonb_build_object(
    'sent', v_sent,
    'waiting_on_audience_delivery', v_skipped,
    'note', case when v_skipped > 0
      then 'Approved messages addressed to a department or role are NOT sent - audience delivery is not built. They are approved and waiting, not lost.'
      else 'Nothing outstanding.' end,
    'at', now());
end $function$
;
CREATE OR REPLACE FUNCTION public.f_hr_external_done(p_id uuid, p_external_id text, p_external_url text, p_error text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.hr_external_task
     set status = case when p_error is null then 'pushed' else 'failed' end,
         external_id = coalesce(p_external_id, external_id),
         external_url = coalesce(p_external_url, external_url),
         pushed_at = case when p_error is null then now() else pushed_at end,
         error = p_error
   where id = p_id;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_hr_external_next(p_limit integer DEFAULT 20)
 RETURNS SETOF hr_external_task
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  return query
  update public.hr_external_task t
     set status='claimed', attempts = coalesce(t.attempts,0)+1
   where t.id in (
     select id from public.hr_external_task
      where status in ('pending','failed') and coalesce(attempts,0) < 5
      order by created_at limit p_limit
      for update skip locked)
  returning t.*;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_hr_queue_to_workspace(p_queue_id uuid, p_list_name text, p_due_on date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare q record; v_role text; v_id uuid;
begin
  select role::text into v_role from app_users where user_id = auth.uid();
  if v_role is null or v_role not in ('owner','executive','hr') then
    return jsonb_build_object('ok', false,
      'message', 'Only an owner, an executive or Human Resources can put an item into the workspace.');
  end if;

  select * into q from hr_review_queue where id = p_queue_id;
  if not found then
    return jsonb_build_object('ok', false, 'message', 'No such queue item.');
  end if;

  if q.status <> 'approved' or q.decided_by is null then
    return jsonb_build_object('ok', false,
      'message', 'That item has not been approved by a person. ClickUp is a shared workspace - a task there is visible to everyone, so it is a publication, not a note. Approve it first.',
      'status', q.status);
  end if;

  if exists (select 1 from hr_external_task t
             where t.queue_id = p_queue_id and t.status in ('pending','pushed')) then
    return jsonb_build_object('ok', false,
      'message', 'A task has already been raised for this item. Raising a second one splits the trail: two tasks, two comment threads, and no single place that says what was done.');
  end if;

  insert into hr_external_task (queue_id, target, list_hint, title, body, due_on, approved_by)
  values (p_queue_id, 'clickup', p_list_name,
          coalesce(q.headline, 'Human Resources item'),
          coalesce(q.edited_body, q.draft_body, q.rationale, ''),
          coalesce(p_due_on, q.defer_until::date),
          q.decided_by)
  returning id into v_id;

  return jsonb_build_object('ok', true, 'id', v_id,
    'message', 'Queued for the workspace. It is pushed by hr-clickup-push, and until it succeeds it is visible in v_hr_delivery_backlog rather than silently pending.');
end $function$
;
