CREATE OR REPLACE FUNCTION public.f_item_documents(p_tag text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
select jsonb_build_object(
  'package_tag', p_tag,
  'bucket',      'metrc-documents',
  'how_to_link', 'supabase.storage.from(bucket).createSignedUrl(storage_path, ttl) at click time. The FILE is permanent - these records are kept and can be sent years later. Never store or cache a URL.',
  'coa', coalesce((
     select jsonb_agg(jsonb_build_object(
              'document_id',        x.metrc_id,
              'storage_path',       x.storage_path,
              'file_name',          'COA ' || p_tag || '.pdf',
              'inherited',          x.link_depth > 0,
              'certificate_on',     x.certificate_on,
              'lab',                x.lab,
              'cultivator',         x.client_name,
              'cultivator_license', x.client_license,
              'report_id',          x.lab_report_id,
              -- REGULATORY validity of the test result, not of the link
              'coa_valid_until',    x.valid_until,
              'coa_expired',        (x.valid_until is not null and x.valid_until < current_date))
            order by x.link_depth, x.metrc_id)
     from (
       select distinct on (d.metrc_id)
              d.metrc_id, d.storage_path, l.link_depth,
              nullif(split_part(l.link_basis, 'INHERITED from ', 2), '') as certificate_on,
              e.client_name, e.client_license, e.lab_report_id,
              (select max(r.lab_facility) from metrc_lab_results r
                where r.package_tag = d.package_tag) as lab,
              (select max((r.raw->>'ExpirationDateTime')::date) from metrc_lab_results r
                where r.package_tag = d.package_tag) as valid_until
       from v_document_package_link l
       join metrc_documents d on d.id = l.document_id
       left join coa_extract e on e.document_id = d.metrc_id::text
       where l.package_tag = p_tag and l.doc_type = 'coa'
       order by d.metrc_id, l.link_depth
     ) x), '[]'::jsonb),
  'manifests', coalesce((
     select jsonb_agg(jsonb_build_object(
              'manifest_number', y.manifest_number,
              'storage_path',    y.storage_path,
              'file_name',       'Manifest ' || y.manifest_number || '.pdf',
              'direction',       y.direction,
              'shipper',         y.shipper,
              'recipient',       y.recipient,
              'created',         y.created)
            order by y.created desc nulls last, y.manifest_number)
     from (
       select distinct on (d.manifest_number)
              d.manifest_number, d.storage_path, t.direction,
              t.raw->>'ShipperFacilityName'     as shipper,
              t.raw->>'RecipientFacilityName'   as recipient,   -- null on all outgoing
              (t.raw->>'CreatedDateTime')::date as created
       from v_document_package_link l
       join metrc_documents d on d.id = l.document_id
       left join metrc_transfers t on t.manifest_number = d.manifest_number
       where l.package_tag = p_tag and l.doc_type = 'manifest'
       order by d.manifest_number
     ) y), '[]'::jsonb)
);
$function$
;
CREATE OR REPLACE FUNCTION public.f_item_flag_badge(p_entity_type text, p_entity_key text)
 RETURNS TABLE(flags integer, worst_severity text, needs_a_person boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select count(*)::int,
         case min(case f.severity when 'critical' then 1 when 'elevated' then 2 else 3 end)
              when 1 then 'critical' when 2 then 'elevated' when 3 then 'watch' else null end,
         coalesce(bool_or(f.severity in ('critical','elevated')), false)
  from v_item_flags f
  where f.entity_type = p_entity_type and f.entity_key = p_entity_key;
$function$
;
CREATE OR REPLACE FUNCTION public.f_item_flags(p_entity_type text, p_entity_key text)
 RETURNS TABLE(severity text, headline text, detail text, why text, what_to_do text, source text, source_ref text, raised_on date, context text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select f.severity, f.headline, f.detail, f.why, f.what_to_do,
         f.source, f.source_ref, f.raised_on, f.context
  from v_item_flags f
  where f.entity_type = p_entity_type and f.entity_key = p_entity_key
  order by case f.severity when 'critical' then 1 when 'elevated' then 2 else 3 end,
           f.raised_on desc;
$function$
;
CREATE OR REPLACE FUNCTION public.f_lab_value(p_tag text, p_prefix text)
 RETURNS TABLE(value numeric, test_name text, result_date date)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with direct as (
    select r.result as value, r.test_name, r.result_date
    from metrc_lab_results r
    where r.package_tag = p_tag
      and r.test_name ilike p_prefix || '%'
      and r.test_name not ilike '%DO NOT USE%'
      and r.result is not null
    order by (r.test_name ilike '%Retest%'), r.result_date desc nulls last
    limit 1
  ), summed as (
    -- only for terpenes, and only when no total line exists
    select round(sum(r.result), 3) as value,
           'Sum of ' || count(*) || ' individual terpenes on the certificate' as test_name,
           max(r.result_date) as result_date
    from metrc_lab_results r
    where p_prefix ilike 'Total Terpenes%'
      and r.package_tag = p_tag
      and r.result is not null
      and r.test_name not ilike '%DO NOT USE%'
      and r.test_name not ilike 'Total%'
      and (r.test_name ilike any (array[
            'Alpha-Bisabolol%','Alpha-Humulene%','Alpha-Pinene%','Alpha-Terpinene%',
            'Beta-Caryophyllene%','Beta-Myrcene%','Beta-Pinene%','Caryophyllene Oxide%',
            'Limonene%','Linalool%','Nerolidol%','Terpinolene%','Other Terpenes%',
            'Gamma-Terpinene%','Eucalyptol%','Camphene%','Geraniol%','Guaiol%',
            'Isopulegol%','p-Cymene%','3-Carene%','Ocimene%']))
    having count(*) > 0
  )
  select * from direct
  union all
  select * from summed where not exists (select 1 from direct)
  limit 1;
$function$
;
CREATE OR REPLACE FUNCTION public.f_licence_in_set(p_licence text, p_set text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case when p_licence is null or p_set is null then false
         else exists (
           select 1 from unnest(string_to_array(p_set, ',')) x
           where btrim(x) = btrim(p_licence))
         end;
$function$
;
CREATE OR REPLACE FUNCTION public.f_login_id_parts(p_full_name text)
 RETURNS TABLE(surname text, first_i text, middle_i text)
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select
    upper(regexp_replace(split_part(p_full_name, ',', 1), '[^A-Za-z]', '', 'g')),
    upper(left(regexp_replace(split_part(btrim(split_part(p_full_name, ',', 2)), ' ', 1),
          '[^A-Za-z]', '', 'g'), 1)),
    upper(left(regexp_replace(coalesce(nullif(split_part(btrim(split_part(p_full_name, ',', 2)), ' ', 2), ''), ''),
          '[^A-Za-z]', '', 'g'), 1))
$function$
;
CREATE OR REPLACE FUNCTION public.f_material_origin(p_tag text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
with recursive seed as (
  select tag, raw from metrc_packages where tag = p_tag
  order by license limit 1                       -- dedupe: one row per tag
),
walk as (
  select s.tag, s.raw, 0 as depth from seed s
  union
  select c.tag, c.raw, w.depth + 1
    from walk w
    join lateral (
      select trim(s) as src
      from unnest(string_to_array(coalesce(w.raw->>'SourcePackageLabels',''), ',')) s
      where trim(s) <> ''
    ) l on true
    join lateral (
      select tag, raw from metrc_packages m where m.tag = l.src order by m.license limit 1
    ) c on true
   where w.depth < 12
),
roots as (
  select w.raw,
         coalesce(nullif(w.raw->>'ReceivedFromFacilityLicenseNumber',''),
                  nullif(w.raw->>'ItemFromFacilityLicenseNumber','')) as origin_lic,
         coalesce(nullif(w.raw->>'ReceivedFromFacilityName',''),
                  nullif(w.raw->>'ItemFromFacilityName','')) as origin_name
    from walk w
   where nullif(w.raw->>'ReceivedFromManifestNumber','') is not null
      or coalesce(w.raw->>'SourcePackageLabels','') = ''
      or not exists (select 1 from metrc_packages c
                      where c.tag = any(string_to_array(replace(w.raw->>'SourcePackageLabels',' ',''), ',')))
)
select jsonb_build_object(
  'package_tag',       p_tag,
  'lineage_packages',  (select count(*) from walk),
  'max_depth',         (select max(depth) from walk),
  'origin_licences',   (select coalesce(jsonb_agg(distinct origin_lic) filter (where origin_lic is not null), '[]'::jsonb) from roots),
  'origin_names',      (select coalesce(jsonb_agg(distinct origin_name) filter (where origin_name is not null), '[]'::jsonb) from roots),
  'inbound_manifests', (select coalesce(jsonb_agg(distinct raw->>'ReceivedFromManifestNumber')
                                  filter (where nullif(raw->>'ReceivedFromManifestNumber','') is not null), '[]'::jsonb) from walk),
  'source_harvests',   (select coalesce(jsonb_agg(distinct raw->>'SourceHarvestNames')
                                  filter (where nullif(raw->>'SourceHarvestNames','') is not null), '[]'::jsonb) from walk),
  'all_ours',          (select bool_and(f_is_ours(origin_lic)) from roots where origin_lic is not null),
  'any_outside',       (select bool_or(not f_is_ours(origin_lic)) from roots where origin_lic is not null),
  'item_field_says',   (select raw->>'ItemFromFacilityLicenseNumber' from seed)
);
$function$
;
CREATE OR REPLACE FUNCTION public.f_my_employee_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select employee_id from public.app_users where user_id = auth.uid()
$function$
;
CREATE OR REPLACE FUNCTION public.f_my_notifications()
 RETURNS TABLE(source text, unread bigint, newest timestamp with time zone, what text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select 'inventory_alerts'::text, count(*)::bigint, max(i.last_seen),
         'Inventory alerts still open'::text
    from inventory_alerts i where i.resolved_at is null
  union all
  select 'critical_findings', count(*)::bigint, max(w.observed_at),
         'Critical findings not yet resolved'
    from watchdog_findings w where w.severity = 'critical'
  union all
  /* alert_outbox routes by role, not by person */
  select 'alert_outbox', count(*)::bigint, max(a.created_at),
         'Alerts raised for your role and not yet read'
    from alert_outbox a
    where a.read_at is null and a.resolved_at is null
      and (a.role is null or a.role = (select u.role::text from app_users u where u.user_id = auth.uid()))
  union all
  select 'messages', count(*)::bigint, max(m.created_at),
         'Messages addressed to you'
    from messages m where m.user_id = auth.uid()
$function$
;
CREATE OR REPLACE FUNCTION public.f_next_login_id(p_full_name text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare p record; v_base text; v_try text; v_n int := 1;
begin
  select * into p from public.f_login_id_parts(p_full_name);
  if p.surname = '' or p.first_i = '' then
    raise exception 'Cannot derive a login ID from "%" — expected "Last, First M"', p_full_name;
  end if;

  v_base := p.first_i || p.middle_i || left(p.surname, 1);
  v_try  := v_base;
  while exists (select 1 from public.employees where login_id = v_try) loop
    v_n := v_n + 1;
    v_try := v_base || v_n::text;
  end loop;
  return v_try;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_offboarding_due()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.final_pay_due_on is null then
    new.final_pay_due_on := case when new.voluntary then null else new.last_day end;
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_one_home_per_figure()
 RETURNS TABLE(figure text, canonical_table text, canonical_rows bigint, obsolete_table text, obsolete_rows bigint, verdict text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r record; n bigint; c bigint;
begin
  for r in
    select 'potency and terpenes'::text as fig, 'metrc_lab_results'::text as canon,
           'lab_result_values'::text as obsolete
    union all
    select 'certificates of analysis', 'metrc_documents', 'coa_documents'
  loop
    execute format('select count(*) from %I', r.canon) into c;
    execute format('select count(*) from %I', r.obsolete) into n;
    figure := r.fig; canonical_table := r.canon; canonical_rows := c;
    obsolete_table := r.obsolete; obsolete_rows := n;
    verdict := case
      when n > 0 then 'TWO HOMES - ' || r.obsolete || ' has been repopulated'
      when c = 0 then 'CANONICAL TABLE IS EMPTY'
      else 'ok' end;
    return next;
  end loop;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_operation(p_licence text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select coalesce((select operation from licence_profile where licence = p_licence),
                  case when p_licence is null then 'Unassigned' else p_licence end);
$function$
;
CREATE OR REPLACE FUNCTION public.f_override(p_table text, p_key text, p_field text, p_fallback text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select coalesce((select o.new_value from tg_overrides o
                   where o.target_table=p_table and o.row_key=p_key
                     and o.field_name=p_field and o.active
                   order by o.set_at desc limit 1), p_fallback)
$function$
;
CREATE OR REPLACE FUNCTION public.f_override_num(p_table text, p_key text, p_field text, p_fallback numeric DEFAULT NULL::numeric)
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select coalesce((select o.numeric_value from tg_overrides o
                   where o.target_table=p_table and o.row_key=p_key
                     and o.field_name=p_field and o.active and o.numeric_value is not null
                   order by o.set_at desc limit 1), p_fallback)
$function$
;
CREATE OR REPLACE FUNCTION public.f_package_documents(p_tag text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  with pkg as (
    select nullif(p.raw->>'ReceivedFromManifestNumber','') as inbound_manifest
    from metrc_packages p where p.tag = p_tag limit 1
  )
  select jsonb_build_object(
    'package_tag', p_tag,
    'coa', coalesce((
      select jsonb_agg(jsonb_build_object(
               'document_id', d.metrc_id, 'url', d.download_url,
               'kilobytes', round(d.byte_size / 1024.0),
               'lab', (select max(r.lab_facility) from metrc_lab_results r
                       where r.package_tag = p_tag and r.document_file_id::text = d.metrc_id),
               'tested_on', (select max(r.result_date) from metrc_lab_results r
                             where r.package_tag = p_tag and r.document_file_id::text = d.metrc_id),
               'expires', d.url_expires_at)
             order by d.fetched_at desc)
      from metrc_documents d
      where d.doc_type='coa' and d.package_tag = p_tag and d.storage_path is not null),
      '[]'::jsonb),
    'manifests', coalesce((
      select jsonb_agg(jsonb_build_object(
               'manifest_number', d.manifest_number, 'url', d.download_url,
               'kilobytes', round(d.byte_size / 1024.0), 'expires', d.url_expires_at))
      from metrc_documents d, pkg
      where d.doc_type='manifest' and d.storage_path is not null
        and d.manifest_number = pkg.inbound_manifest),
      '[]'::jsonb));
$function$
;
CREATE OR REPLACE FUNCTION public.f_package_is_ours(p_tag text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select case
    when g is null                                          then 'unknown'
    when (g->>'all_ours')::boolean                          then 'ours'
    when (g->>'any_outside')::boolean
         and jsonb_array_length(coalesce(g->'origin_licences','[]'::jsonb)) <= 1
                                                            then 'third_party'
    when (g->>'any_outside')::boolean                       then 'blended'
    else 'unknown'
  end
  from (select f_material_origin(p_tag) as g) x;
$function$
;
CREATE OR REPLACE FUNCTION public.f_payroll_forecast_upd()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_emp  uuid;
  v_cur  public.employee_rates%rowtype;
begin
  if not public.f_can_decide_hr() then
    raise exception 'Not permitted to change pay. Owner, HR or admin only.'
      using errcode = '42501';
  end if;

  select id into v_emp from public.employees where employee_code = old.employee_code;
  if v_emp is null then
    raise exception 'No employee with code %', old.employee_code;
  end if;

  -- Planned hours live on the employee, not the rate.
  if new.planned_hours is distinct from old.planned_hours then
    if new.planned_hours < 0 or new.planned_hours > 80 then
      raise exception 'Planned hours must be between 0 and 80, got %', new.planned_hours;
    end if;
    update public.employees set weekly_target_hours = new.planned_hours where id = v_emp;
  end if;

  -- Rate or basis change → effective-dated roll.
  if new.rate is distinct from old.rate or new.basis is distinct from old.basis then
    if new.rate is null or new.rate <= 0 then
      raise exception 'Rate must be greater than zero, got %', new.rate;
    end if;

    select * into v_cur from public.employee_rates
    where employee_id = v_emp
      and effective_from <= current_date
      and (effective_to is null or effective_to >= current_date)
    order by effective_from desc limit 1;

    if v_cur.effective_from = current_date then
      -- Already changed today; correct that row rather than stack duplicates.
      update public.employee_rates
         set rate = new.rate, basis = new.basis, approved_by = auth.uid()
       where id = v_cur.id;
    else
      update public.employee_rates
         set effective_to = current_date - 1
       where id = v_cur.id;

      insert into public.employee_rates
        (employee_id, basis, rate, ot_multiplier, burden_pct,
         effective_from, effective_to, approved_by, note)
      values
        (v_emp, new.basis, new.rate,
         coalesce(v_cur.ot_multiplier, 1.5), coalesce(v_cur.burden_pct, 0),
         current_date, null, auth.uid(),
         format('Changed from %s %s via Payroll Forecast', v_cur.rate, v_cur.basis));
    end if;
  end if;

  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_post_schedule(p_draft_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_d public.schedule_drafts%rowtype; v_n int := 0; v_open int := 0;
begin
  if not public.f_can_decide_hr() then
    raise exception 'Only a person with scheduling rights may post a schedule.'
      using errcode = '42501';
  end if;

  select * into v_d from public.schedule_drafts where id = p_draft_id;
  if v_d.id is null then raise exception 'No such draft.'; end if;
  if v_d.status = 'posted' then raise exception 'That draft is already posted.'; end if;

  /* Replace only the window this draft covers, only for its department.
     Anything outside is untouched — posting Packaging must not wipe Cultivation. */
  delete from public.employee_schedules s
   where s.work_date between v_d.covers_from and v_d.covers_to
     and (v_d.department_id is null or s.department_id = v_d.department_id);

  insert into public.employee_schedules
    (employee_id, work_date, shift_template_id, department_id, zone, planned_start, planned_end, status, note)
  select l.employee_id, l.work_date, l.shift_template_id,
         coalesce(l.department_id, v_d.department_id), z.name,
         l.planned_start, l.planned_end, 'scheduled', l.note
  from public.schedule_draft_lines l
  left join public.zones z on z.id = l.zone_id
  where l.draft_id = p_draft_id and l.employee_id is not null and not l.is_open_shift;
  get diagnostics v_n = row_count;

  insert into public.open_shifts
    (draft_id, work_date, zone_id, department_id, shift_template_id,
     planned_start, planned_end, reason, posted_by)
  select p_draft_id, l.work_date, l.zone_id, coalesce(l.department_id, v_d.department_id),
         l.shift_template_id, l.planned_start, l.planned_end,
         coalesce(l.note,'Open shift'), auth.uid()
  from public.schedule_draft_lines l
  where l.draft_id = p_draft_id and l.is_open_shift;
  get diagnostics v_open = row_count;

  update public.schedule_drafts
     set status='posted', posted_by=auth.uid(), posted_at=now() where id=p_draft_id;
  update public.schedule_drafts
     set status='superseded' where id = v_d.supersedes_id and status <> 'superseded';

  return jsonb_build_object('posted_shifts', v_n, 'open_shifts', v_open,
                            'from', v_d.covers_from, 'to', v_d.covers_to);
end $function$
;
CREATE OR REPLACE FUNCTION public.f_potency_status(p_thc numeric, p_terp numeric, p_state text)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select case
    when p_thc is not null then 'THC ' || p_thc || '%'
      || coalesce(', terpenes ' || p_terp || '%', ', terpenes not reported')
    when p_state in ('SubmittedForTesting','TestingInProgress') then
      'PENDING — the sample is at the laboratory. Values appear here the moment the result is recorded.'
    when p_state = 'NotSubmitted' then
      'NO TESTING PLANNED YET — nothing has been sent, so there is nothing to report.'
    else
      'NOT AVAILABLE — Metrc''s package interface carries no potency values, only the testing state '
      || 'and dates. THC, TAC, terpenes and the certificate come from the Metrc Lab Results report, '
      || 'which has not been imported yet. Import it and every past record fills in automatically.'
  end $function$
;
CREATE OR REPLACE FUNCTION public.f_price_per_lb(p_category text)
 RETURNS TABLE(rate numeric, basis text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare v_rate numeric; v_basis text; c text := lower(coalesce(p_category,''));
begin
  -- 1. real transacted price, when the units exist to compute it
  select round(sum(t.shipper_wholesale_price)/nullif(sum(f_to_pounds(t.shipped_qty, t.shipped_uom)),0),2)
    into v_rate
  from metrc_rpt_package_transfers t
  where t.shipper_wholesale_price > 0
    and t.shipped_uom is not null
    and f_is_weight(t.shipped_uom)
    and lower(coalesce(t.category,'')) = c;

  if v_rate is not null and v_rate between 50 and 5000 then
    return query select v_rate, 'measured — what we actually sold this category for'::text;
    return;
  end if;

  -- 2. the standards register
  if c like '%bud%' or c like '%flower%' then
    v_rate := f_rule_at('target_cost_per_lb'); v_basis := 'standards register — flower rate';
  elsif c like '%trim%' or c like '%shake%' then
    v_rate := 300; v_basis := 'standards register — trim rate';
  elsif c like '%fresh%' or c like '%frozen%' or c like '%biomass%' then
    v_rate := 119.77; v_basis := 'standards register — fresh frozen rate';
  elsif c like '%concentrate%' or c like '%rosin%' or c like '%vape%' then
    v_rate := f_rule_at('target_cost_per_lb'); v_basis := 'standards register — flower rate used as a stand-in; no concentrate rate is recorded';
  else
    v_rate := f_rule_at('target_cost_per_lb'); v_basis := 'standards register — general rate, category not recognised';
  end if;

  if v_rate is null or v_rate not between 50 and 5000 then
    return query select null::numeric, 'NO RATE AVAILABLE — this cannot be priced and must not be guessed'::text;
  else
    return query select v_rate, v_basis || ' (ESTIMATE, not a transacted price)';
  end if;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_printed_decimals(p_text text)
 RETURNS integer
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select least(
    case when p_text ~ '\.\d+\s*$' then length(rtrim(split_part(btrim(p_text), '.', 2)))
         else 0 end,
    coalesce(f_rule('reconcile_max_decimals')::int, 4));
$function$
;
CREATE OR REPLACE FUNCTION public.f_punch(p_employee_id uuid, p_kind text, p_source text DEFAULT 'web'::text, p_device_id uuid DEFAULT NULL::uuid, p_lat numeric DEFAULT NULL::numeric, p_lon numeric DEFAULT NULL::numeric, p_accuracy_m numeric DEFAULT NULL::numeric, p_at timestamp with time zone DEFAULT now())
 RETURNS TABLE(entry_id uuid, action text, late_minutes integer, occurrence_id uuid, message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_date date := (p_at at time zone 'America/New_York')::date;
  v_open public.time_entries%rowtype;
  v_planned time; v_grace integer; v_late integer := null;
  v_points numeric(3,1); v_occ uuid := null; v_entry uuid;
  v_kind text; v_mins numeric; v_lunch integer; v_hours numeric;
begin
  select grace_minutes, points_late into v_grace, v_points
  from public.attendance_policy where id;

  select * into v_open from public.time_entries
  where employee_id = p_employee_id and clock_out is null
  order by clock_in desc limit 1;

  if p_kind is null then
    v_kind := case when v_open.id is null then 'in' else 'out' end;
  elsif p_kind in ('in','out') then
    v_kind := p_kind;
  else
    raise exception 'f_punch: p_kind must be in, out, or null to infer — got %', p_kind;
  end if;

  if v_kind = 'in' then
    if v_open.id is not null then
      return query select v_open.id, 'already_in'::text, null::integer, null::uuid,
        'Already clocked in. Clock out first.'::text;
      return;
    end if;

    select planned_start into v_planned from public.employee_schedules
    where employee_id = p_employee_id and work_date = v_date
    order by planned_start limit 1;

    if v_planned is not null then
      v_late := greatest(0, ceil(extract(epoch from
        ((p_at at time zone 'America/New_York')::time - v_planned)) / 60.0)::integer);
      if v_late <= v_grace then v_late := 0; end if;
    end if;

    insert into public.time_entries
      (employee_id, work_date, clock_in, source, device_id,
       punch_lat, punch_lon, punch_accuracy_m, late_minutes, exception_code)
    values
      (p_employee_id, v_date, p_at, p_source, p_device_id,
       p_lat, p_lon, p_accuracy_m, v_late,
       case when coalesce(v_late,0) > 0 then 'late' else null end)
    returning id into v_entry;

    if coalesce(v_late,0) > 0 then
      insert into public.attendance_occurrences
        (employee_id, work_date, kind, minutes, points, status, time_entry_id)
      values (p_employee_id, v_date, 'late', v_late, v_points, 'awaiting_explanation', v_entry)
      returning id into v_occ;
    end if;

    return query select v_entry, 'clocked_in'::text, v_late, v_occ,
      case when coalesce(v_late,0) > 0
        then format('Clocked in %s minutes late. This is an attendance occurrence '
                    'worth %s points and may result in a disciplinary warning. '
                    'If you have an excusable reason, state it now.', v_late, v_points)
        else 'Clocked in.' end::text;
    return;
  end if;

  if v_open.id is null then
    return query select null::uuid, 'not_in'::text, null::integer, null::uuid,
      'No open punch to close.'::text;
    return;
  end if;

  v_mins := extract(epoch from (p_at - v_open.clock_in)) / 60.0;

  -- A second tap within a few seconds is the same tap. Say so and change
  -- nothing, rather than erroring or recording a zero-length shift.
  if v_mins < 0.084 then                              -- about five seconds
    return query select v_open.id, 'ignored_double_tap'::text, v_open.late_minutes, null::uuid,
      'Already registered a moment ago — you are still clocked in.'::text;
    return;
  end if;

  v_lunch := least(coalesce(v_open.unpaid_lunch_min, 0), greatest(floor(v_mins)::int, 0));
  v_hours := greatest(round((v_mins - v_lunch) / 60.0, 2), 0);

  update public.time_entries
     set clock_out = p_at, unpaid_lunch_min = v_lunch, productive_hours = v_hours,
         exception_code = case when v_mins < 1 then 'mispunch' else exception_code end
   where id = v_open.id
  returning id into v_entry;

  return query select v_entry, 'clocked_out'::text, v_open.late_minutes, null::uuid,
    case when v_mins < 1
      then 'Clocked out — that shift was under a minute. Flagged as a mis-punch for HR to correct.'
      else format('Clocked out. %s hours.', v_hours) end::text;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_punch_badge(p_badge_code text, p_device_id uuid, p_kind text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_emp uuid; v_name text;
        v_entry uuid; v_action text; v_late integer; v_occ uuid; v_msg text;
begin
  if not exists (select 1 from public.punch_devices
                  where id = p_device_id and active and kind = 'scanner') then
    raise exception 'This scanner is not registered or has been deactivated.';
  end if;
  select id, full_name into v_emp, v_name from public.employees
   where badge_code = btrim(p_badge_code) and status::text = 'active';
  if v_emp is null then raise exception 'Badge not recognised.' using errcode='42501'; end if;
  update public.punch_devices set last_seen_at = now() where id = p_device_id;

  select f.entry_id, f.action, f.late_minutes, f.occurrence_id, f.message
    into v_entry, v_action, v_late, v_occ, v_msg
  from public.f_punch(v_emp, p_kind, 'scanner', p_device_id, null, null, null, now()) f;

  return jsonb_build_object('time_entry_id', v_entry, 'action', v_action,
    'late_minutes', coalesce(v_late,0), 'occurrence_id', v_occ,
    'message', v_msg, 'full_name', v_name);
end $function$
;
CREATE OR REPLACE FUNCTION public.f_punch_import(p_rows jsonb, p_device_id uuid, p_source_system text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r jsonb; v_emp uuid; v_ok int := 0; v_skip int := 0; v_err jsonb := '[]'::jsonb;
begin
  if not public.f_can_decide_hr() then
    raise exception 'Not permitted to import punches.' using errcode='42501';
  end if;
  for r in select * from jsonb_array_elements(p_rows) loop
    select id into v_emp from public.employees
     where employee_code = (r->>'employee_code') or upper(login_id) = upper(r->>'login_id');
    if v_emp is null then
      v_skip := v_skip + 1;
      v_err := v_err || jsonb_build_object('row', r, 'why', 'no matching employee');
      continue;
    end if;
    insert into public.time_entries
      (employee_id, work_date, clock_in, clock_out, unpaid_lunch_min,
       source, device_id, source_ref, created_at)
    values
      (v_emp, (r->>'work_date')::date, (r->>'clock_in')::timestamptz,
       nullif(r->>'clock_out','')::timestamptz, coalesce((r->>'unpaid_lunch_min')::int,0),
       'payroll_import', p_device_id, p_source_system || ':' || coalesce(r->>'ref',''), now());
    v_ok := v_ok + 1;
  end loop;
  return jsonb_build_object('imported', v_ok, 'skipped', v_skip, 'errors', v_err);
end $function$
;
CREATE OR REPLACE FUNCTION public.f_punch_kiosk(p_login_id text, p_pin text, p_device_id uuid, p_kind text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_emp uuid; v_name text; v_login text; v_dev public.punch_devices%rowtype;
  v_entry uuid; v_action text; v_late integer; v_occ uuid; v_msg text;
begin
  select * into v_dev from public.punch_devices
   where id = p_device_id and active and kind = 'kiosk';
  if v_dev.id is null then
    raise exception 'This terminal is not registered or has been deactivated.';
  end if;

  select e.id, e.full_name, e.login_id into v_emp, v_name, v_login
  from public.employees e
  where upper(e.login_id) = upper(btrim(p_login_id))
    and e.pin_hash is not null
    and e.pin_hash = extensions.crypt(p_pin, e.pin_hash)
    and e.status::text = 'active';

  if v_emp is null then
    raise exception 'That ID and PIN do not match an active employee.' using errcode='42501';
  end if;

  update public.punch_devices set last_seen_at = now() where id = p_device_id;

  select f.entry_id, f.action, f.late_minutes, f.occurrence_id, f.message
    into v_entry, v_action, v_late, v_occ, v_msg
  from public.f_punch(v_emp, p_kind, 'kiosk', p_device_id, null, null, null, now()) f;

  return jsonb_build_object(
    'time_entry_id', v_entry, 'action', v_action,
    'late_minutes', coalesce(v_late,0), 'occurrence_id', v_occ,
    'message', v_msg, 'full_name', v_name, 'login_id', v_login);
end $function$
;
CREATE OR REPLACE FUNCTION public.f_punch_phone(p_lat numeric, p_lon numeric, p_accuracy_m numeric, p_kind text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_emp uuid; v_site text;
        v_entry uuid; v_action text; v_late integer; v_occ uuid; v_msg text;
begin
  v_emp := public.f_my_employee_id();
  if v_emp is null then raise exception 'No employee record for this login.' using errcode='42501'; end if;
  if p_lat is null or p_lon is null then raise exception 'Location is required for a phone punch.'; end if;

  select s.name into v_site from (
    select name, 6371000 * acos(least(1, greatest(-1,
             cos(radians(p_lat))*cos(radians(lat))*cos(radians(lon)-radians(p_lon))
             + sin(radians(p_lat))*sin(radians(lat))))) as d, radius_m
    from public.punch_sites where active and lat is not null and lon is not null
  ) s where s.d <= s.radius_m order by s.d limit 1;

  if v_site is null then
    raise exception 'You are not at a work site. Phone punches are only accepted on site.'
      using errcode='42501';
  end if;

  select f.entry_id, f.action, f.late_minutes, f.occurrence_id, f.message
    into v_entry, v_action, v_late, v_occ, v_msg
  from public.f_punch(v_emp, p_kind, 'mobile', null, p_lat, p_lon, p_accuracy_m, now()) f;

  return jsonb_build_object('time_entry_id', v_entry, 'action', v_action,
    'late_minutes', coalesce(v_late,0), 'occurrence_id', v_occ,
    'message', v_msg, 'site', v_site);
end $function$
;
CREATE OR REPLACE FUNCTION public.f_quantity_text(p_qty numeric, p_uom text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case
    when p_qty is null then null
    when f_is_weight(p_uom)
      then trim(to_char(round(f_to_pounds(p_qty, p_uom), 2), 'FM999G999G990D99')) || ' lb'
    when p_qty = trunc(p_qty)
      then trim(to_char(p_qty, 'FM999G999G990')) || ' ' || p_uom
    else trim(to_char(p_qty, 'FM999G999G990D99')) || ' ' || p_uom
  end;
$function$
;
CREATE OR REPLACE FUNCTION public.f_raise_correction(p_about text, p_was_wrong text, p_what_is_true text, p_evidence text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id bigint;
begin
  if coalesce(btrim(p_what_is_true), '') = '' then
    return jsonb_build_object('ok', false,
      'message', 'A correction needs to say what IS true, not only that something was wrong. "That is wrong" trains nothing.');
  end if;
  insert into brain_correction (about, was_wrong, what_is_true, evidence)
  values (p_about, p_was_wrong, p_what_is_true, p_evidence)
  returning id into v_id;
  return jsonb_build_object('ok', true, 'id', v_id,
    'message', 'Recorded. It changes nothing until an owner approves it - then every assistant carries it, everywhere, permanently.');
end $function$
;
CREATE OR REPLACE FUNCTION public.f_rate_basis(p_stream text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  select case
    when r.stream is null then 'No rate is set for this stream, so the central fallback of $'
      || coalesce((select c.value::text from conversion_factors c where c.key='target_cost_per_lb'),'0')
      || ' per pound was used. That figure belongs to no stream in particular.'
    when r.confirmed then '$' || r.dollars_per_pound || ' per pound for ' || r.stream
      || ', set by ' || coalesce(r.set_by,'unknown') || ' on ' || to_char(r.set_at,'DD Mon YYYY')
      || '. Basis: ' || r.basis || '.'
    else 'UNCONFIRMED — $' || r.dollars_per_pound || ' per pound for ' || r.stream
      || ' is an inherited default nobody has set. This figure is an estimate. Open Valuation Rates.'
  end
  from (select * from valuation_rates where stream = p_stream
        order by effective_from desc limit 1) r
  right join (select 1) x on true;
$function$
;
CREATE OR REPLACE FUNCTION public.f_rate_for(p_stream text DEFAULT NULL::text, p_tag text DEFAULT NULL::text)
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select coalesce(
    (select o.dollars_per_pound from public.valuation_overrides o
      where p_tag is not null and o.package_tag = p_tag order by o.set_at desc limit 1),
    (select g.badder_crude_per_pound from public.v_cost_of_goods g where p_stream = 'Concentrate'),
    nullif((select r.dollars_per_pound from public.valuation_rates r
      where r.stream = p_stream and r.effective_from <= current_date
      order by r.effective_from desc limit 1), 0),
    0) $function$
;
CREATE OR REPLACE FUNCTION public.f_reconcile_advice(p_report text, p_field text, p_ours text, p_theirs text, p_ours_n numeric, p_theirs_n numeric, p_file_as_of date)
 RETURNS TABLE(recommendation text, reasoning text, confidence text)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare pct numeric; prec record; tol numeric; dp int; pct_limit numeric;
begin
  -- 1. one side is empty: filling a blank is safe, blanking a value is not
  if p_ours is null and p_theirs is not null then
    return query select 'accept_file',
      'We hold nothing for this field and the file has a value. Filling a blank cannot lose '
      || 'anything.', 'certain'; return;
  end if;
  if p_theirs is null and p_ours is not null then
    return query select 'keep_ours',
      'The file is blank here and we hold a value. A blank in an export usually means the column '
      || 'was not ticked, not that the value is gone. Never overwrite a figure with nothing.',
      'certain'; return;
  end if;
  if p_ours is null and p_theirs is null then
    return query select 'keep_ours', 'Both are empty.', 'certain'; return;
  end if;

  -- 2. the precedence policy already decides some fields outright
  select * into prec from source_precedence
  where field_key = p_report || '.' || p_field or field_key = p_field limit 1;
  if prec.winner = 'report' then
    return query select 'accept_file',
      'Policy: the report is the source of record for this field. ' || prec.why, 'certain'; return;
  elsif prec.winner = 'api' then
    return query select 'keep_ours',
      'Policy: the API is the source of record for this field, and a report is a snapshot. '
      || prec.why, 'certain'; return;
  end if;

  -- 3. numeric
  if p_ours_n is not null and p_theirs_n is not null then
    -- Tolerance follows the precision the FILE printed, not a fixed constant.
    -- A report that prints whole pounds cannot evidence a tenth of a pound.
    dp  := f_printed_decimals(p_theirs);
    tol := coalesce(f_rule('reconcile_rounding_half_ulp'), 0.5) * power(10::numeric, -dp);
    pct_limit := coalesce(f_rule('reconcile_restatement_pct'), 1);
    pct := case when p_ours_n <> 0
                then abs(100.0*(p_theirs_n - p_ours_n)/abs(p_ours_n)) else null end;

    if abs(p_theirs_n - p_ours_n) < tol then
      return query select 'keep_ours',
        'The two agree to within rounding. The file prints this field to '
        || dp || ' decimal place' || case when dp = 1 then '' else 's' end
        || ', so it cannot evidence a difference smaller than ' || tol || '.', 'certain'; return;
    end if;

    -- A zero is a MEASUREMENT until someone says otherwise. This database holds
    -- 72 fresh-frozen harvests (5,448 lb wet) whose zero moisture loss is real:
    -- they were packaged wet and never dried. An earlier version of this branch
    -- accepted the file over our zero at 'likely' confidence with no human in
    -- the loop, which would have silently overwritten every one of them.
    -- Both directions of a zero disagreement now go to a person.
    if p_ours_n = 0 and p_theirs_n <> 0 then
      return query select 'needs_a_person',
        'We hold zero and the file has ' || p_theirs || '. A zero can be a value that was never '
        || 'populated, or a real measured nought - this business has 72 fresh-frozen harvests '
        || 'where zero moisture loss is correct. The two cannot be told apart from the numbers '
        || 'alone, so someone has to say which this is.', 'needs_a_person'; return;
    end if;
    if p_theirs_n = 0 and p_ours_n <> 0 then
      return query select 'keep_ours',
        'The file says zero where we hold ' || p_ours || '. A zero in an export is far more often a '
        || 'missing column than a real nought, and accepting it would silently erase a figure.',
        'needs_a_person'; return;
    end if;

    if pct is not null and pct < pct_limit then
      return query select 'accept_file',
        'The file differs by ' || round(pct,2) || '%, under the ' || pct_limit
        || '% restatement threshold, so this reads as Metrc restating the figure rather than '
        || 'correcting it. Taking the file keeps us aligned at low risk. (That threshold is '
        || 'provisional and not yet evidenced.)', 'likely'; return;
    end if;

    return query select 'needs_a_person',
      'The file says ' || p_theirs || ' where we hold ' || p_ours || ' - a difference of '
      || round(p_theirs_n - p_ours_n, 4) || coalesce(' (' || round(pct,1) || '%)', '')
      || '. That is too large to be rounding and too small to be obviously wrong, so it needs '
      || 'someone who knows what happened to this record.', 'needs_a_person'; return;
  end if;

  -- 4. text: a longer value is usually more complete, but never assume
  if length(coalesce(p_theirs,'')) > length(coalesce(p_ours,'')) then
    return query select 'needs_a_person',
      'Both hold text and they differ. The file''s value is longer ("' || left(p_theirs,40)
      || '" against "' || left(p_ours,40) || '"), which often means more complete - but a longer '
      || 'string is not evidence, so this is a judgement call.', 'needs_a_person'; return;
  end if;
  return query select 'needs_a_person',
    'Both hold text and they differ: we have "' || left(p_ours,40) || '", the file has "'
    || left(p_theirs,40) || '".', 'needs_a_person';
end $function$
;
CREATE OR REPLACE FUNCTION public.f_record_lab_turnarounds()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int; lim numeric := f_rule('lab_turnaround_max_days');
begin
  insert into lab_turnaround_log (package_tag, product, category, strain, source_harvest,
    went_out_on, came_back_on, days_out, testing_state, pounds, breached)
  select distinct on (package_tag) package_tag, product, category, strain, source_harvest,
    went_out_for_testing_on, came_back_on, days_out_at_the_laboratory, testing_state, pounds,
    coalesce(days_out_at_the_laboratory, current_date - went_out_for_testing_on) > lim
  from v_lab_turnaround_packages where went_out_for_testing_on is not null
  order by package_tag, came_back_on desc nulls last
  on conflict (package_tag) do update set came_back_on = excluded.came_back_on,
    days_out = excluded.days_out, testing_state = excluded.testing_state, breached = excluded.breached;
  get diagnostics n = row_count; return n;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_refresh_document_search()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_before bigint; v_after bigint;
begin
  select count(*) into v_before from document_search;

  insert into document_search (id, doc_type, package_tag, manifest_number,
                               license, download_url, storage_path, search_text)
  select d.id, d.doc_type, d.package_tag, d.manifest_number, d.license,
         d.download_url, d.storage_path,
         lower(concat_ws(' ', d.doc_type, d.package_tag, d.manifest_number, d.license))
  from metrc_documents d
  on conflict (id) do update
    set doc_type = excluded.doc_type,
        package_tag = excluded.package_tag,
        manifest_number = excluded.manifest_number,
        license = excluded.license,
        download_url = excluded.download_url,
        storage_path = excluded.storage_path;

  /* A document whose row disappeared upstream must disappear here too. */
  delete from document_search ds
  where not exists (select 1 from metrc_documents d where d.id = ds.id);

  update document_search ds set item_name = p.item_name
  from (select distinct on (tag) tag, item_name from metrc_packages
        where tag is not null order by tag) p
  where p.tag = ds.package_tag
    and ds.item_name is distinct from p.item_name;

  update document_search ds
  set customer = m.destination_facility, strain = m.strain
  from (select distinct on (manifest_number::text)
               manifest_number::text as mn, destination_facility, strain
        from metrc_rpt_package_transfers
        where manifest_number is not null
        order by manifest_number::text, as_of_date desc nulls last) m
  where m.mn = ds.manifest_number
    and (ds.customer is distinct from m.destination_facility
         or ds.strain is distinct from m.strain);

  update document_search
  set search_text = lower(concat_ws(' ', doc_type, package_tag, manifest_number,
                                    license, item_name, strain, shipper, customer));

  select count(*) into v_after from document_search;
  return jsonb_build_object('before', v_before, 'after', v_after,
                            'added', greatest(v_after - v_before, 0),
                            'refreshed_at', now());
end $function$
;
CREATE OR REPLACE FUNCTION public.f_requeue_stalled_bridge_jobs()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_requeued int; v_failed int; v_infra int;
begin
  with dead as (
    update ai_bridge_jobs
    set status = 'error',
        error = 'Given up after 3 attempts. The bridge claimed this and stopped before answering each time - the desktop may be crashing on this particular question.',
        answered_at = now()
    where status = 'running' and claimed_at < now() - interval '10 minutes' and attempts >= 3
    returning 1)
  select count(*) into v_failed from dead;

  with back as (
    update ai_bridge_jobs
    set status = 'pending', claimed_at = null, requeued_at = now(), attempts = attempts + 1
    where status = 'running' and claimed_at < now() - interval '10 minutes' and attempts < 3
    returning 1)
  select count(*) into v_requeued from back;

  /* Deliberately narrow. These three strings are the desktop failing to START
     its worker - not a model that ran and answered badly. A broader match would
     re-run genuinely failed questions for ever and bill the owner's patience for
     it. */
  with infra as (
    update ai_bridge_jobs
    set status = 'pending', claimed_at = null, answered_at = null,
        requeued_at = now(), attempts = attempts + 1, error = null
    where status = 'error'
      and attempts < 3
      and answered_at > now() - interval '24 hours'
      and (error ilike '%cannot find the path specified%'
           or error ilike '%is not recognized as an internal or external command%'
           or error ilike '%Could not start Claude Code%')
    returning 1)
  select count(*) into v_infra from infra;

  return jsonb_build_object('requeued_stalled', v_requeued,
                            'requeued_infrastructure', v_infra,
                            'given_up', v_failed, 'at', now());
end $function$
;
CREATE OR REPLACE FUNCTION public.f_resolve_audience(p_audience text, p_employee_id uuid)
 RETURNS SETOF uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select e.id from public.employees e
  where e.status::text = 'active'
    and (
      (p_employee_id is not null and e.id = p_employee_id)
      or (p_employee_id is null and lower(coalesce(p_audience,'')) in ('all','company','everyone'))
      or (p_employee_id is null and exists (
            select 1 from public.departments d
            where d.id in (e.primary_department_id, e.secondary_department_id)
              and lower(d.name) = lower(p_audience)))
      or (p_employee_id is null and exists (
            select 1 from public.roles_catalog rc
            where rc.id in (e.primary_role_id, e.secondary_role_id)
              and lower(rc.name) = lower(p_audience)))
      or (p_employee_id is null and exists (
            select 1 from public.employee_schedules s
            where s.employee_id = e.id and s.work_date >= current_date
              and lower(btrim(s.zone)) = lower(p_audience)))
      or (p_employee_id is null and lower(coalesce(p_audience,'')) = 'on shift now' and exists (
            select 1 from public.time_entries t
            where t.employee_id = e.id and t.clock_in is not null and t.clock_out is null))
    );
$function$
;
CREATE OR REPLACE FUNCTION public.f_rpt_date(v text)
 RETURNS date
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
begin
  if v is null or btrim(v) = '' then return null; end if;
  -- Excel serial (days since 1899-12-30)
  if v ~ '^[0-9]+(\.[0-9]+)?$' and f_rpt_num(v) between 20000 and 60000 then
    return date '1899-12-30' + (f_rpt_num(v))::int;
  end if;
  begin return v::date; exception when others then return null; end;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_rpt_lb(v text)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when v is null or v = '' then null
    when v ilike '%kg%' then f_rpt_num(v) * 2.20462
    when v ilike '%lb%' then f_rpt_num(v)
    when v ilike '%oz%' then f_rpt_num(v) / 16.0
    when v ilike '%mg%' then f_rpt_num(v) / 453592.0
    else f_rpt_num(v) / 453.592          -- Metrc defaults to grams
  end;
$function$
;
CREATE OR REPLACE FUNCTION public.f_rpt_num(v text)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select nullif(substring(replace(coalesce(v,''), ',', '') from '-?\d+(?:\.\d+)?'), '')::numeric;
$function$
;
CREATE OR REPLACE FUNCTION public.f_rpt_price(v text, p_side text DEFAULT 'S'::text)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select nullif((regexp_match(replace(coalesce(v,''), ',', ''),
                 '(-?\d+(?:\.\d+)?)\s*' || p_side))[1], '')::numeric;
$function$
;
CREATE OR REPLACE FUNCTION public.f_rpt_unit(v text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select lower(nullif(btrim((regexp_match(coalesce(v,''), '([A-Za-z]+)\s*$'))[1]), ''));
$function$
;
CREATE OR REPLACE FUNCTION public.f_rule(p_key text)
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$ select value from public.conversion_factors where key = p_key $function$
;
CREATE OR REPLACE FUNCTION public.f_rule_at(p_key text, p_when timestamp with time zone DEFAULT now())
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  select h.value from conversion_factor_history h
  where h.key = p_key
    and h.valid_from <= p_when
    and (h.valid_to is null or h.valid_to > p_when)
  order by h.valid_from desc limit 1
$function$
;
CREATE OR REPLACE FUNCTION public.f_sentinel_check()
 RETURNS TABLE(source_key text, label text, last_seen timestamp with time zone, silent_minutes integer, allowed_minutes integer, verdict text, why_it_matters text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare e record; seen timestamptz; mins integer;
begin
  for e in select * from sentinel_expectation where enabled order by source_key loop
    seen := null;

    /* Probes are fixed here rather than stored as SQL in the config table: a threshold
       is configuration, an executable query is code, and putting code in a config table
       is how a config table becomes an attack surface. */
    begin
      if e.source_key = 'metrc_sync' then
        select max(coalesce(finished_at, started_at)) into seen from metrc_sync_runs;
      elsif e.source_key = 'watchdog' then
        select max(ran_at) into seen from watchdog_runs;
      elsif e.source_key = 'platform_state' then
        select max(taken_at) into seen from platform_state;
      elsif e.source_key = 'page_canary' then
        select max(ran_at) into seen from canary_runs;
      end if;
    exception when others then
      /* A probe that cannot run must SAY SO, never pass quietly. A sentinel that
         swallows its own error reports silence as health - the precise failure it
         exists to catch, wearing the costume of a working check. */
      source_key := e.source_key; label := e.label; last_seen := null;
      silent_minutes := null; allowed_minutes := e.max_silence_minutes;
      verdict := 'PROBE BROKEN: ' || sqlerrm;
      why_it_matters := e.why_it_matters;
      return next;
      continue;
    end;

    mins := case when seen is null then null
                 else floor(extract(epoch from (now() - seen)) / 60)::integer end;

    source_key := e.source_key;
    label := e.label;
    last_seen := seen;
    silent_minutes := mins;
    allowed_minutes := e.max_silence_minutes;
    why_it_matters := e.why_it_matters;
    verdict := case
      when seen is null then 'NEVER SPOKEN'
      when mins > e.max_silence_minutes then 'SILENT'
      else 'ok' end;
    return next;
  end loop;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_set_ai_key(p_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_role text;
begin
  select role::text into v_role from app_users where user_id = auth.uid();
  if v_role is null or v_role not in ('owner','executive') then
    return jsonb_build_object('ok', false,
      'message', 'Only an owner or an executive can set the company key.');
  end if;

  if p_key is null or btrim(p_key) = '' then
    return jsonb_build_object('ok', false,
      'message', 'That was empty. To remove the key deliberately, use the Remove button.');
  end if;

  /* A pasted key routinely arrives with a trailing space or a newline from the
     clipboard, and an invisible character is a very expensive thing to debug at
     the far end of an HTTP call. */
  insert into app_secrets (key, value)
  values ('ANTHROPIC_API_KEY', btrim(p_key))
  on conflict (key) do update set value = excluded.value;

  return jsonb_build_object('ok', true,
    'message', 'Saved for the whole company. Every assistant on the platform uses it from the next question - nobody sets this again, and signing out does not clear it.');
end $function$
;
CREATE OR REPLACE FUNCTION public.f_set_punch_pin(p_employee_id uuid, p_pin text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
begin
  if not public.f_can_decide_hr() then
    raise exception 'Not permitted to set a PIN. Owner, HR or admin only.' using errcode='42501';
  end if;
  if p_pin !~ '^[0-9]{4,8}$' then raise exception 'A PIN must be 4 to 8 digits.'; end if;
  update public.employees
     set pin_hash = extensions.crypt(p_pin, extensions.gen_salt('bf', 10)), pin_set_at = now()
   where id = p_employee_id;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_severity_rank(p text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$ select case p when 'critical' then 1 when 'elevated' then 2 when 'watch' then 3 else 9 end $function$
;
CREATE OR REPLACE FUNCTION public.f_start_lifecycle(p_employee_id uuid, p_phase text, p_anchor date DEFAULT CURRENT_DATE)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n integer;
begin
  if not public.f_can_decide_hr() then
    raise exception 'Not permitted to start a lifecycle checklist.' using errcode='42501';
  end if;
  insert into public.lifecycle_progress (employee_id, step_id, phase, due_on)
  select p_employee_id, s.id, s.phase, p_anchor + coalesce(s.due_offset_days,0)
  from public.lifecycle_steps s
  where s.phase = p_phase and s.active
  on conflict (employee_id, step_id) do nothing;
  get diagnostics n = row_count;
  return n;
end $function$
;
CREATE OR REPLACE FUNCTION public.f_stock_status(p_state text, p_finished boolean)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when p_state = 'intransit' then 'In transit'
    when p_state = 'inactive' or coalesce(p_finished,false) then 'Sold or closed'
    when p_state = 'active' then 'Still on hand'
    else 'Not recorded' end;
$function$
;
CREATE OR REPLACE FUNCTION public.f_strain_from_item(p_item text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  with a as (
    select trim(split_part(regexp_replace(coalesce(p_item,''), '^M[0-9]+:\s*', ''), '|', 1)) as s
  ),
  b as (
    select case when s ~ ' - ' then trim(split_part(s, ' - ', 2)) else trim(s) end as c from a
  ),
  c as (
    select regexp_replace(c, '^Twisted Growers\s+', 'TG ', 'i') as c from b
  ),
  d as (
    -- \y, not \b. Size first ("... Flower 3.5g" -> "... Flower"), then the form.
    select regexp_replace(
             regexp_replace(c, '\s+[0-9]+(\.[0-9]+)?\s*(g|mg|oz|lb)s?\y.*$', '', 'i'),
             '(\s+(raw\s+preroll|pre-?roll|bulk\s+shake/trim|bulk\s+flower|bulk\s+smalls|bulk|'
          || 'vape\s+oil|distillate|shake|trim|smalls|flower|buds?|joints?|gummies|gummy|'
          || 'concentrate|cartridges?|carts?|edibles?|tincture|wax|badder|live\s+resin))+\s*$',
             '', 'i') as c
    from c
  )
  select case
           when trim(c) = '' then null
           when lower(trim(c)) ~ ('^(tg\s*)?(bulk|gummy|gummies|raw preroll|preroll|pre-roll|joints?|'
                || 'distillate|vape oil|shake|trim|smalls|flower|bud|buds|biomass|kief|rosin|'
                || 'concentrate|cartridge|carts?|edible|tincture|wax|badder|live resin|mixed pheno)$')
             then null
           else trim(c)
         end
  from d;
$function$
;
CREATE OR REPLACE FUNCTION public.f_test_status(p_state text, p_submitted date, p_result date)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when p_state in ('SubmittedForTesting','TestingInProgress') then
      'OUT FOR TESTING — sent ' || coalesce(p_submitted::text,'date not recorded')
      || coalesce(', ' || (current_date - p_submitted)::text || ' days ago','')
    when p_state = 'NotSubmitted' then 'NO TESTING PLANNED YET — never sent to a laboratory'
    when p_state in ('TestPassed','RetestPassed') then
      'PASSED — result recorded ' || coalesce(p_result::text,'date not recorded')
    when p_state in ('TestFailed','RetestFailed') then
      'FAILED — result recorded ' || coalesce(p_result::text,'date not recorded')
    when p_state is null then 'NO TESTING STATE RECORDED IN METRC'
    else p_state || ' — recorded ' || coalesce(p_result::text,'no result date') end $function$
;
CREATE OR REPLACE FUNCTION public.f_to_pounds(qty numeric, uom text)
 RETURNS numeric
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case lower(coalesce(uom,''))
    when 'g' then qty / 453.592
    when 'grams' then qty / 453.592
    when 'kg' then qty * 2.20462
    when 'kilograms' then qty * 2.20462
    when 'mg' then qty / 453592.0
    when 'oz' then qty / 16.0
    when 'ounces' then qty / 16.0
    when 'lb' then qty
    when 'lbs' then qty
    when 'pounds' then qty
    else null            -- 'ea', 'each', anything countable: NOT a weight
  end $function$
;
CREATE OR REPLACE FUNCTION public.f_uom_label(p_uom text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case lower(coalesce(p_uom,''))
    when 'each'   then 'Units'
    when 'ea'     then 'Units'
    when 'grams'  then 'Grams'
    when 'g'      then 'Grams'
    when 'pounds' then 'Pounds'
    when 'lb'     then 'Pounds'
    when 'kilograms' then 'Kilograms'
    when 'kg'     then 'Kilograms'
    when 'ounces' then 'Ounces'
    when 'oz'     then 'Ounces'
    when 'milligrams' then 'Milligrams'
    when 'mg'     then 'Milligrams'
    else coalesce(nullif(p_uom,''),'not recorded') end;
$function$
;
