CREATE OR REPLACE FUNCTION public.tg_report_as_of(p_stated date, p_rows jsonb, p_date_fields text[], p_uploaded timestamp with time zone)
 RETURNS TABLE(as_of date, source text)
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare best date; f text; d date;
begin
  if p_stated is not null then
    return query select p_stated, 'stated by the person uploading'; return;
  end if;
  foreach f in array coalesce(p_date_fields, '{}')
  loop
    select max(f_rpt_date(r->>f)) into d from jsonb_array_elements(p_rows) r;
    if d is not null and (best is null or d > best) then best := d; end if;
  end loop;
  if best is not null then
    return query select best, 'latest event date inside the file'; return;
  end if;
  return query select p_uploaded::date, 'UPLOAD DATE - the file carried no date, so this is a guess';
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_require_double_check()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_ok       boolean;
  v_proposed boolean;
begin
  -- Terminal states: the finding is being declared over.
  if new.state in ('closed','not_a_problem') then

    if length(btrim(coalesce(new.override_reason,''))) >= 25 then
      if not f_caller_is_admin() then
        raise exception
          'Only an administrator may override the independent check on %.', new.finding_key
          using hint = 'Have a second agent verify the closure instead.';
      end if;
      new.override_by := coalesce(new.override_by, current_app_role());
      new.override_at := coalesce(new.override_at, now());
      return new;
    end if;

    select exists (
      select 1 from finding_closure c
      where c.finding_key = new.finding_key and c.verdict = 'agrees'
    ) into v_ok;

    if not v_ok then
      raise exception
        'Finding % cannot be closed: no independent second check agrees with the closure.',
        new.finding_key
        using hint = 'Insert a finding_closure row with your proof, then have a DIFFERENT '
                     'agent derive the same fact another way and set verdict = agrees. '
                     'An administrator may instead set override_reason (25 characters or more), '
                     'which closes it but records that nobody verified it.';
    end if;
  end if;

  -- Claiming a fix is weaker than closing, but it still may not be a bare assertion.
  if new.state in ('fixed_in_os','fixed_in_metrc') then
    select exists (
      select 1 from finding_closure c
      where c.finding_key = new.finding_key and c.verdict <> 'disagrees'
    ) into v_proposed;

    if not v_proposed and length(btrim(coalesce(new.override_reason,''))) < 25 then
      raise exception
        'Finding % cannot be marked % without a closure record carrying the proof.',
        new.finding_key, new.state
        using hint = 'Insert a finding_closure row stating the claim, how it was derived, '
                     'and the SQL that proves it.';
    end if;
  end if;

  return new;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_resolve_challenge(p_id bigint, p_verdict text, p_finding text, p_changed text, p_by text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_key text;
begin
  if length(coalesce(p_finding,'')) < 20 then
    raise exception 'Resolving a challenge needs a written finding of at least twenty characters.';
  end if;
  update metric_challenges set verdict=p_verdict, agent_finding=p_finding, what_changed=p_changed,
    resolved_at=now(), resolved_by=p_by where id=p_id returning metric_key into v_key;
  update metric_provenance set
    status = case p_verdict when 'CONFIRMED CORRECT' then 'VERIFIED' when 'CORRECTED' then 'VERIFIED'
                            when 'WITHDRAWN' then 'WITHDRAWN' else 'DISPUTED' end,
    last_verified_at = now(), last_verified_by = p_by, updated_at = now()
  where metric_key = v_key;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_review_import(p_import uuid DEFAULT NULL::uuid, p_reviewer text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare total int := 0; failed int := 0; f jsonb := '[]'::jsonb; r record;
        verdict text; who text; imp_report text; imp_by text; imp_check text;
begin
  who := coalesce(p_reviewer, auth.uid()::text, 'reviewer');
  if p_import is not null then
    select report_type, imported_by, count_check into imp_report, imp_by, imp_check
    from metrc_report_imports where id = p_import;
    if imp_report is null then return jsonb_build_object('ok', false, 'error', 'No such import.'); end if;
    if imp_by is not null and imp_by = who then
      return jsonb_build_object('ok', false,
        'error', 'The account that ran this import cannot also certify it. Review must come from '
              || 'a different agent or person.');
    end if;
  end if;

  for r in select * from tg_run_import_checks(null) loop
    total := total + 1;
    if not r.r_passed then
      failed := failed + 1;
      f := f || jsonb_build_object('check', r.r_check_key, 'title', r.r_title, 'level', r.r_level,
                                   'severity', r.r_severity, 'failures', r.r_failures,
                                   'examples', r.r_examples);
    end if;
  end loop;

  if imp_check like 'FAILED%' then
    failed := failed + 1;
    f := f || jsonb_build_object('check','rowcount',
                'title','Row count against the file''s own stated total',
                'level',1,'severity','critical','failures',1,'examples',to_jsonb(imp_check));
  end if;

  verdict := case when failed = 0 then 'certified'
    when exists (select 1 from jsonb_array_elements(f) e where e->>'severity'='critical') then 'rejected'
    else 'needs_a_person' end;

  insert into import_review (import_id, report_key, reviewed_by, checks_run, checks_failed,
                             verdict, findings, note)
  values (p_import, imp_report, who, total, failed, verdict, f,
    case verdict when 'certified' then 'Every check passed against the file, the mapping, the API and the scorecard.'
                 when 'rejected'  then 'A critical check failed. The figures must not be relied on until resolved.'
                 else 'Something needs a person to look at it.' end);

  if verdict <> 'certified' then
    insert into agent_findings (agent, severity, headline, detail, scope, action, drill_to, fingerprint)
    values ('QA & Independent Verification',
            case when verdict='rejected' then 'critical' else 'elevated' end,
            'Import review ' || verdict || ': ' || coalesce(imp_report,'all reports'),
            failed || ' of ' || total || ' checks failed. ' || f::text,
            'import_review','Open Metrc Report Imports and resolve before trusting the figures.',
            'metrc_report_imports','review:' || coalesce(p_import::text,'global'))
    on conflict do nothing;
  end if;

  return jsonb_build_object('ok', verdict='certified', 'verdict', verdict,
    'checks_run', total, 'checks_failed', failed, 'reviewed_by', who, 'findings', f);
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_route_findings(p_by text DEFAULT 'tg_route_findings'::text)
 RETURNS TABLE(source text, routed integer, to_catchall integer)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  return query
  with candidate as (
    -- pile 1: the unified findings spine
    select f.finding_key,
           f.source::text                       as src,
           coalesce(f.department,'')            as dept,
           coalesce(f.severity,'elevated')      as sev,
           coalesce(f.what,'')                  as headline
    from v_findings f
    where f.resolved_at is null
      and not coalesce(f.is_duplicate,false)
    union all
    -- pile 2: the discrepancy register, which the spine does not carry
    select 'disc:'||d.discrepancy_key,
           'discrepancy',
           coalesce(d.class,''),
           'elevated',
           coalesce(d.subject,'')
    from discrepancy_register d
    where d.resolved_at is null
  ),
  unrouted as (
    select c.* from candidate c
    where not exists (select 1 from finding_state s where s.finding_key = c.finding_key)
  ),
  picked as (
    select u.*,
           (select r.route_key from finding_route r
             where r.enabled
               and (r.applies_to = u.src or r.applies_to = '*')
               and (r.match_department is null or r.match_department = u.dept)
               and (r.match_pattern    is null or u.headline ~* r.match_pattern)
             order by r.priority, r.route_key
             limit 1) as route_key
    from unrouted u
  ),
  ins as (
    insert into finding_state
      (finding_key, state, source, owning_agent, route_key, due_by,
       routed_by, routed_at, changed_by, note)
    select p.finding_key, 'open', p.src, r.owning_agent, r.route_key,
           now() + make_interval(hours => case p.sev
                                            when 'critical' then r.hours_critical
                                            when 'watch'    then r.hours_watch
                                            else                 r.hours_elevated end),
           p_by, now(), p_by,
           'routed to '||r.owning_agent||' by rule '||r.route_key
    from picked p join finding_route r on r.route_key = p.route_key
    returning finding_state.source, finding_state.route_key
  )
  select i.source, count(*)::integer,
         count(*) filter (where i.route_key = 'catchall')::integer
  from ins i group by i.source;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_run_import_checks(p_only text DEFAULT NULL::text)
 RETURNS TABLE(r_check_key text, r_title text, r_level integer, r_severity text, r_failures integer, r_passed boolean, r_examples jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c record; n int; ex jsonb;
begin
  for c in select ic.* from import_check ic
           where ic.enabled and (p_only is null or ic.check_key = p_only)
           order by ic.level, ic.check_key
  loop
    begin
      execute format('select coalesce(jsonb_agg(x), ''[]''::jsonb)
                        from (select * from (%s) s limit 5) x', c.sql_expression) into ex;
      execute format('select count(*) from (%s) s', c.sql_expression) into n;
      insert into import_check_run (check_key, ran_by, failures, passed, examples)
      values (c.check_key, coalesce(auth.uid()::text,'system'), n, n = 0, ex);
      r_check_key := c.check_key; r_title := c.title; r_level := c.level;
      r_severity := c.severity; r_failures := n; r_passed := (n = 0); r_examples := ex;
      return next;
    exception when others then
      insert into import_check_run (check_key, ran_by, failures, passed, error)
      values (c.check_key, coalesce(auth.uid()::text,'system'), -1, false, sqlerrm);
      r_check_key := c.check_key; r_title := c.title; r_level := c.level;
      r_severity := 'critical'; r_failures := -1; r_passed := false;
      r_examples := jsonb_build_object('check_could_not_run', sqlerrm);
      return next;
    end;
  end loop;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_save_finding(p_key text, p_source text, p_headline text, p_snapshot jsonb, p_disposition text DEFAULT 'saved_for_later'::text, p_plan text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_owner text DEFAULT NULL::text, p_due date DEFAULT NULL::date, p_dollars numeric DEFAULT NULL::numeric)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
declare fid uuid;
begin
  insert into finding_plans (finding_key, finding_source, headline, snapshot, plan, disposition,
    disposition_reason, owner_assigned, due_on, dollars, created_by)
  values (p_key, p_source, p_headline, p_snapshot, p_plan, p_disposition,
    p_reason, p_owner, p_due, p_dollars, auth.uid()::text)
  returning id into fid;
  -- putting it on the to-do list creates a real task
  if p_disposition = 'on_todo_list' then
    insert into tasks (title, description, status, priority, due_on, created_by)
    values (p_headline, coalesce(p_plan,'') || ' [from a Chief Executive finding]', 'todo',
      case when coalesce(p_dollars,0) > 100000 then 'P0' else 'P1' end, p_due, auth.uid());
  end if;
  return fid;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_selftest_backfill_sweep(p_by text DEFAULT 'tg_selftest'::text)
 RETURNS TABLE(case_name text, passed boolean, actual text)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  k text := 'selftest:backfill';
  j text := 'selftest:backfill-fresh';
  v text;
  n integer;
begin
  create temp table if not exists _bf(case_name text, expected text, actual text, passed boolean)
    on commit drop;
  delete from _bf;

  delete from agent_findings where fingerprint in
    ('backfill_stalled:'||k,'backfill_uncountable:'||k,'backfill_overrunning:'||k,
     'backfill_stalled:'||j,'backfill_uncountable:'||j,'backfill_overrunning:'||j);
  delete from backfill_watch where job_key in (k, j, k||':nofloorreason');

  -- CASE 1-3: a backlog genuinely flat for eight days
  insert into backfill_watch(job_key, what_it_drains, remaining_sql, accepted_floor)
  values (k, 'a self-test backlog that deliberately never drains', 'select 5', 0);
  insert into backfill_reading(job_key, remaining, read_at, read_by)
  values (k, 5, now() - interval '8 days', p_by), (k, 5, now() - interval '4 days', p_by);

  select s.verdict into v from tg_backfill_sweep(p_by) s where s.job_key = k;
  insert into _bf values ('a backlog flat for eight days reads STALLED','STALLED',coalesce(v,'(none)'), v='STALLED');

  select count(*) into n from agent_findings where fingerprint='backfill_stalled:'||k and resolved_at is null;
  insert into _bf values ('STALLED raises a finding','1 finding', n||' findings', n=1);

  update backfill_watch set remaining_sql='select 1' where job_key=k;
  select s.verdict into v from tg_backfill_sweep(p_by) s where s.job_key = k;
  select count(*) into n from agent_findings where fingerprint='backfill_stalled:'||k and resolved_at is null;
  insert into _bf values ('once it drains the finding stands down','DRAINING and 0 open',
                          coalesce(v,'?')||' and '||n||' open', v='DRAINING' and n=0);

  -- CASE 4: THE REGRESSION. Two equal readings minutes apart are NOT a seven-day stall.
  -- This is the defect that shipped on 9 Aug 2026 and was fixed the same hour: a verdict
  -- about seven days of history being drawn from minutes of it.
  insert into backfill_watch(job_key, what_it_drains, remaining_sql, accepted_floor)
  values (j, 'a self-test backlog with no history behind it yet', 'select 4', 0);
  perform tg_backfill_sweep(p_by);                       -- first reading
  select s.verdict into v from tg_backfill_sweep(p_by) s where s.job_key = j;   -- second, seconds later
  select count(*) into n from agent_findings where fingerprint='backfill_stalled:'||j and resolved_at is null;
  insert into _bf values ('two equal readings minutes apart are NOT a stall',
                          'TOO SOON TO SAY and 0 findings',
                          coalesce(v,'?')||' and '||n||' findings',
                          v='TOO SOON TO SAY' and n=0);

  -- CASE 5: a floor above zero without evidence is refused
  begin
    insert into backfill_watch(job_key, what_it_drains, remaining_sql, accepted_floor)
    values (k||':nofloorreason','a self-test backlog with an unexplained floor','select 9', 9);
    insert into _bf values ('an unexplained floor is refused','refused','ALLOWED IT',false);
  exception when others then
    insert into _bf values ('an unexplained floor is refused','refused',left(sqlerrm,55),true);
  end;

  insert into guard_selftest(guard_key, case_name, expected, actual, passed, ran_by)
  select 'backfill_sweep', s.case_name, s.expected, s.actual, s.passed, p_by from _bf s;

  delete from agent_findings where fingerprint in
    ('backfill_stalled:'||k,'backfill_uncountable:'||k,'backfill_overrunning:'||k,
     'backfill_stalled:'||j,'backfill_uncountable:'||j,'backfill_overrunning:'||j);
  delete from backfill_watch where job_key in (k, j, k||':nofloorreason');

  return query select s.case_name, s.passed, s.actual from _bf s;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_selftest_double_check(p_by text DEFAULT 'tg_selftest'::text)
 RETURNS TABLE(case_name text, passed boolean, actual text)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  k text := 'selftest:double-check';
  r record;
  function_result text;
begin
  create temp table if not exists _st(case_name text, expected text, actual text, passed boolean)
    on commit drop;
  delete from _st;

  -- clean slate
  delete from finding_closure where finding_key = k;
  delete from finding_state   where finding_key = k;

  insert into finding_state(finding_key, state, source, changed_by, note)
  values (k, 'open', 'selftest', p_by, 'self-test row, deleted at the end of this function');

  -- 1. bare closure must be refused
  begin
    update finding_state set state='closed', note='trying to close with no proof at all', changed_by=p_by
    where finding_key=k;
    insert into _st values ('closing with no closure record','refused','ALLOWED IT',false);
  exception when others then
    insert into _st values ('closing with no closure record','refused',left(sqlerrm,60),true);
  end;

  insert into finding_closure(finding_key, proposed_by, claim, how_derived, proof_sql)
  values (k,'agent-alpha',
          'the self-test finding is no longer true and can be closed',
          'counted the underlying rows and found none remaining',
          'select count(*) from finding_state where finding_key = ''selftest:double-check''');

  -- 2. proposed but unverified must still be refused
  begin
    update finding_state set state='closed', note='proposed but nobody has checked it', changed_by=p_by
    where finding_key=k;
    insert into _st values ('closing on a proposal nobody verified','refused','ALLOWED IT',false);
  exception when others then
    insert into _st values ('closing on a proposal nobody verified','refused',left(sqlerrm,60),true);
  end;

  -- 3. the same agent cannot second its own work
  begin
    update finding_closure set second_by='agent-alpha', second_at=now(),
           second_how_derived='I checked my own work again and it still looks right',
           second_proof_sql='select 1 -- a different query', verdict='agrees'
    where finding_key=k;
    insert into _st values ('agent seconds its own closure','refused','ALLOWED IT',false);
  exception when others then
    insert into _st values ('agent seconds its own closure','refused',left(sqlerrm,60),true);
  end;

  -- 4. re-running the first agent's query is not an independent derivation
  begin
    update finding_closure set second_by='agent-beta', second_at=now(),
           second_how_derived='ran exactly the same query the first agent ran',
           second_proof_sql='select count(*) from finding_state where finding_key = ''selftest:double-check''',
           verdict='agrees'
    where finding_key=k;
    insert into _st values ('second agent re-runs the same SQL','refused','ALLOWED IT',false);
  exception when others then
    insert into _st values ('second agent re-runs the same SQL','refused',left(sqlerrm,60),true);
  end;

  -- 5. a genuine independent check, by someone else, another way
  begin
    update finding_closure set second_by='agent-beta', second_at=now(),
           second_how_derived='derived it from the history table instead of the state table',
           second_proof_sql='select count(*) from finding_state_history where finding_key = ''selftest:double-check''',
           second_value=0, verdict='agrees'
    where finding_key=k;
    update finding_state set state='closed', note='independently verified by agent-beta', changed_by=p_by
    where finding_key=k;
    select state into function_result from finding_state where finding_key=k;
    insert into _st values ('independently verified closure','allowed',coalesce(function_result,'(gone)'),
                            function_result = 'closed');
  exception when others then
    insert into _st values ('independently verified closure','allowed','REFUSED: '||left(sqlerrm,50),false);
  end;

  insert into guard_selftest(guard_key, case_name, expected, actual, passed, ran_by)
  select 'double_check_on_closure', s.case_name, s.expected, s.actual, s.passed, p_by from _st s;

  delete from finding_closure where finding_key = k;
  delete from finding_state   where finding_key = k;

  return query select s.case_name, s.passed, s.actual from _st s;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_selftest_report_upload_nag(p_by text DEFAULT 'tg_selftest'::text)
 RETURNS TABLE(case_name text, passed boolean, actual text)
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_before integer;
  v_after  integer;
  v_second integer;
  r        record;
  v_fp     text;
  v_state  text;
begin
  create temp table if not exists _rn(case_name text, expected text, actual text, passed boolean)
    on commit drop;
  delete from _rn;

  -- 1. IDEMPOTENCY: a second run must raise nothing new.
  select count(*) into v_before from agent_findings
   where fingerprint like 'report_upload_overdue:%' and resolved_at is null;
  perform tg_raise_report_upload_findings(p_by);
  select count(*) into v_after from agent_findings
   where fingerprint like 'report_upload_overdue:%' and resolved_at is null;
  insert into _rn values ('re-running raises no duplicates', 'no change',
                          v_before||' -> '||v_after, v_before = v_after);

  -- 2. COVERAGE: every overdue row in the view has an open finding.
  select count(*) into v_second
  from v_report_upload_due d
  where not d.received and d.days_late > 0
    and not exists (
      select 1 from agent_findings f
      where f.fingerprint = 'report_upload_overdue:'||d.report_key||':'||d.licence||':'||d.period_label
        and f.resolved_at is null);
  insert into _rn values ('every overdue upload has an open finding', '0 uncovered',
                          v_second||' uncovered', v_second = 0);

  -- 3. STAND-DOWN: plant a finding against an upload that HAS been received and
  --    prove the next run closes it. Uses a real received row, not a mock.
  select d.report_key, d.licence, d.period_label into r
  from v_report_upload_due d where d.received limit 1;

  if r.report_key is null then
    insert into _rn values ('a received upload stands the finding down',
                            'tested', 'SKIPPED - no received row to test against', false);
  else
    v_fp := 'report_upload_overdue:'||r.report_key||':'||r.licence||':'||r.period_label;
    delete from agent_findings where fingerprint = v_fp and detail like '%SELF-TEST%';
    insert into agent_findings
      (agent, severity, headline, detail, scope, action, drill_to, fingerprint)
    values ('Metrc & Compliance','watch',
            'SELF-TEST row for the report-upload stand-down path',
            'SELF-TEST. Planted against an upload that has already been received, to prove '
            || 'the nag stands down. Removed at the end of this function.',
            r.licence, 'none - self test', 'none', v_fp);

    perform tg_raise_report_upload_findings(p_by);

    select case when resolved_at is null then 'STILL OPEN' else 'resolved' end into v_state
    from agent_findings where fingerprint = v_fp and detail like '%SELF-TEST%';

    insert into _rn values ('a received upload stands the finding down', 'resolved',
                            coalesce(v_state,'(row vanished)'), coalesce(v_state,'') = 'resolved');

    delete from agent_findings where fingerprint = v_fp and detail like '%SELF-TEST%';
  end if;

  insert into guard_selftest(guard_key, case_name, expected, actual, passed, ran_by)
  select 'report_upload_nag', s.case_name, s.expected, s.actual, s.passed, p_by from _rn s;

  return query select s.case_name, s.passed, s.actual from _rn s;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_send_alert_emails(p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare cfg jsonb; v_enabled boolean; v_fn text; v_addresses int; v_queued int; v_dispatched int := 0;
begin
  select value into cfg from configurations where key = 'alert_email';
  v_enabled := coalesce((cfg->>'enabled')::boolean, false);
  v_fn      := nullif(btrim(coalesce(cfg->>'send_function','')), '');

  select count(*) into v_queued from alert_outbox
   where channel='email' and sent_at is null and dispatched_at is null and resolved_at is null;
  select count(*) into v_addresses from v_alert_email_recipients;

  if not v_enabled then
    return jsonb_build_object('ok', true, 'dispatched', 0, 'queued', v_queued,
      'state', 'email_not_configured', 'why', cfg->>'why_off', 'to_turn_on', cfg->>'to_turn_on');
  end if;
  if v_fn is null then
    return jsonb_build_object('ok', false, 'dispatched', 0, 'queued', v_queued,
      'state', 'enabled_but_no_send_function',
      'why', 'alert_email.enabled is true but send_function is not set, so there is nothing to call.');
  end if;
  if v_addresses = 0 then
    return jsonb_build_object('ok', false, 'dispatched', 0, 'queued', v_queued,
      'state', 'enabled_but_no_addresses',
      'why', 'Nobody has an email address on file. Add rows to alert_recipient.');
  end if;

  -- pg_net is asynchronous: it returns a request id, not a result. So this records
  -- that the send was HANDED OVER. sent_at stays null until tg_confirm_alert_emails
  -- sees a 2xx come back. Stamping sent_at here would be claiming delivery on the
  -- strength of having tried, which is the same error as marking a flag fixed.
  with to_send as (
    select o.id, o.subject, o.body, o.severity, r.email, r.full_name
    from alert_outbox o
    join v_alert_email_recipients r on r.role = o.role
    where o.channel='email' and o.sent_at is null and o.dispatched_at is null
      and o.resolved_at is null
    order by case o.severity when 'critical' then 1 when 'elevated' then 2 else 3 end, o.created_at
    limit p_limit
  ), called as (
    select t.id, tg_call_function(v_fn, jsonb_build_object(
             'to', t.email, 'name', t.full_name, 'subject', t.subject,
             'body', t.body, 'severity', t.severity)) as request_id
    from to_send t
  ), stamped as (
    update alert_outbox o
       set dispatched_at = now(), send_request_id = c.request_id
      from called c where c.id = o.id
      returning 1)
  select count(*) into v_dispatched from stamped;

  return jsonb_build_object('ok', true, 'dispatched', v_dispatched,
    'queued_before', v_queued, 'addresses', v_addresses,
    'state', 'dispatched - not yet confirmed delivered',
    'next', 'tg_confirm_alert_emails() marks them sent only when the provider answers 2xx.');
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_sentinel_sweep()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_run bigint; r record; n integer := 0; problems text := '';
begin
  insert into watchdog_runs default values returning id into v_run;

  for r in select * from f_sentinel_check() where verdict <> 'ok' loop
    n := n + 1;
    problems := problems || r.label || ' (' || r.verdict ||
      case when r.silent_minutes is not null
           then ', silent ' || r.silent_minutes || 'm of ' || r.allowed_minutes || 'm allowed'
           else '' end || '); ';
  end loop;

  if n > 0 then
    insert into watchdog_findings (run_id, fingerprint, severity, what, where_it_is,
      who_is_accountable, when_it_started, why_it_matters, how_it_was_detected, what_to_do,
      the_arithmetic, record_count, drill, search_text)
    values (v_run, 'sentinel_source_silent', 'critical',
      n || ' monitored source(s) have STOPPED SPEAKING: ' || rtrim(problems, '; '),
      'sentinel_expectation vs the live run tables', 'Whoever owns the silent job',
      'Since the source last reported',
      'Silence is the failure every other check misses. A dead job reports nothing, and nothing looks exactly like nothing wrong - the Metrc sync was dead for 7 hours 16 minutes on 7 Aug 2026 while every dashboard reported success. This is the only check that treats absence of news as news.',
      'Compared each source''s most recent run against its owner-set max_silence_minutes in sentinel_expectation.',
      'Find why the job stopped. Do NOT simply restart it and close this - a job that died once with no alarm will die again. Record the cause in issue_decisions.',
      rtrim(problems, '; '), n, 'settings', 'sentinel silent dead job heartbeat')
    on conflict (fingerprint) where (fingerprint is not null) do update set
      severity = excluded.severity, what = excluded.what,
      the_arithmetic = excluded.the_arithmetic, record_count = excluded.record_count,
      run_id = excluded.run_id;
  end if;

  return n;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_set_my_key(p_provider text, p_key text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into ai_user_access (user_id, own_key_provider, own_key, enabled, updated_at)
  values (auth.uid(), nullif(p_provider,''), nullif(p_key,''), true, now())
  on conflict (user_id) do update
    set own_key_provider = nullif(p_provider,''), own_key = nullif(p_key,''), updated_at = now();
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_set_secret(p_key text, p_value text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists (select 1 from app_users u where u.user_id=auth.uid() and u.role='owner') then
    raise exception 'Only an owner can set a key.';
  end if;
  insert into app_secrets (key, value, updated_by, updated_at)
  values (p_key, p_value, auth.uid(), now())
  on conflict (key) do update set value=excluded.value, updated_by=auth.uid(), updated_at=now();
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_set_sync_system()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.system is null or new.system = 'metrc' then
    select m.system into new.system from sync_system_map m
     where new.endpoint = m.endpoint_pattern
        or new.endpoint like m.endpoint_pattern || '%';
    if new.system is null then new.system := 'metrc'; end if;
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_snapshot_dashboards()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  refresh materialized view concurrently mv_department_dashboard;
  insert into dashboard_snapshots (taken_on, department, kpi, value, unit)
  select current_date, department, kpi, value, unit from mv_department_dashboard
  on conflict (taken_on, department, kpi) do update set value = excluded.value;
  get diagnostics n = row_count;
  return n;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_snapshot_inventory(p_day date DEFAULT NULL::date)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d date := coalesce(p_day, (now() at time zone 'America/New_York')::date); n int;
begin
  delete from inventory_snapshot where taken_on = d;   -- re-runnable for today only
  insert into inventory_snapshot
    (taken_on, license, tag, item_name, category, strain, quantity, uom, pounds,
     location, lab_state, packaged_on, origin, stock_status, source_state)
  select d, p.license, p.tag, p.item_name,
         p.raw #>> '{Item,ProductCategoryName}', p.raw #>> '{Item,StrainName}',
         p.quantity, p.uom,
         case when f_is_weight(p.uom) then f_to_pounds(p.quantity, p.uom) end,
         p.location, p.lab_testing_state, p.packaged_on,
         case when coalesce(p.raw->>'ItemFromFacilityLicenseNumber','')
                   = any (array['MC281714','MP281909']) then 'Grown by us' else 'Bought in' end,
         f_stock_status(p.source_state, p.finished), p.source_state
  from metrc_packages p
  where p.source_state <> 'inactive';   -- what was actually held that day
  get diagnostics n = row_count;
  return d::text || ': ' || n::text || ' packages recorded';
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_stamp_facility_contact()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  new.updated_at := now();
  new.updated_by := coalesce(auth.uid()::text, new.updated_by);
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_stamp_import_period()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.period_start is null then
    select tg_import_period(t.cadence, new.imported_at) into new.period_start
    from metrc_report_types t where t.report_key = new.report_type;
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_sweep_discrepancies()
 RETURNS TABLE(out_class text, out_found integer, out_newly_raised integer, out_resolved integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_new int; v_res int;
begin
  create temp table _raw on commit drop as
  select 'strain'::text as class,
         'strain:' || d.package_tag || ':' || d.manifest_number as discrepancy_key,
         'Package ' || d.package_tag || ' on manifest ' || d.manifest_number as subject,
         'Metrc item name'::text as source_a, d.item_name_says as source_a_says,
         'Metrc strain field'::text as source_b, d.strain_column_says as source_b_says,
         'COA — the certificate names the strain that was tested'::text as resolved_by_doc,
         (select dc.storage_path from metrc_documents dc
           where dc.package_tag = d.package_tag and dc.doc_type ilike '%coa%' limit 1) as document_link
  from v_strain_conflicts d
  union all
  select 'ownership', 'ownership:' || o.tag,
         'Package ' || o.tag || ' — ' || left(o.item_name, 50),
         'Platform item field', case when o.platform_says_ours then 'ours' else 'third party' end,
         'Package lineage in Metrc',
         case when o.lineage_says_ours then 'ours'
              else 'third party — ' || coalesce(o.origins->>0,'origin not named') end,
         'Inbound manifest — it names who shipped it to us',
         (select dm.storage_path from metrc_documents dm
           where dm.manifest_number = (o.arrived_on->>0) and dm.doc_type ilike '%manifest%' limit 1)
  from v_ownership_misattribution o where o.verdict <> 'agrees'
  union all
  select 'missing_contents', 'contents:' || g.manifest_number,
         'Manifest ' || g.manifest_number || ' ' || g.direction || ' — '
           || coalesce(g.recipient, g.shipper, 'counterparty not named'),
         'Metrc transfer record', coalesce(g.packages_metrc_says::text,'?') || ' packages on board',
         'Package line export', '0 lines held',
         'Manifest PDF — it lists every package on the shipment',
         g.manifest_document
  from v_manifest_line_gaps g
  union all
  -- NEW: the verification framework's own disagreements.
  select 'verification', 'verify:' || v.check_key,
         v.title || ' — ' || round(l.pct_apart, 2) || '% apart',
         v.source_a_label, l.value_a::text,
         v.source_b_label, l.value_b::text,
         coalesce(v.what_it_proves, 'Two derivations of the same fact disagree.'),
         null
  from verification_checks v
  join lateral (
    select value_a, value_b, pct_apart, verdict
    from verification_runs r where r.check_key = v.check_key
    order by r.ran_at desc limit 1
  ) l on true
  where l.verdict ilike '%disagree%';

  create temp table _cur on commit drop as
  select distinct on (discrepancy_key) * from _raw order by discrepancy_key, document_link nulls last;

  insert into discrepancy_register as r
    (discrepancy_key, class, subject, source_a, source_a_says, source_b, source_b_says,
     resolved_by_doc, document_link, first_seen, last_seen)
  select c.discrepancy_key, c.class, c.subject, c.source_a, c.source_a_says,
         c.source_b, c.source_b_says, c.resolved_by_doc, c.document_link, now(), now()
  from _cur c
  on conflict (discrepancy_key) do update
    set last_seen = now(),
        document_link = coalesce(excluded.document_link, r.document_link),
        source_a_says = excluded.source_a_says,
        source_b_says = excluded.source_b_says,
        subject       = excluded.subject,
        resolved_at = null,
        resolution_note = case when r.resolved_at is not null
          then 'Reopened ' || to_char(now(),'DD Mon HH24:MI') || ' — it disagreed again. Previous note: '
            || coalesce(r.resolution_note,'(none)') else r.resolution_note end;
  get diagnostics v_new = row_count;

  update discrepancy_register r
     set resolved_at = now(), resolved_by = coalesce(r.resolved_by,'sweep'),
         resolution_note = coalesce(r.resolution_note,
           'The sources agree again as at ' || to_char(now(),'DD Mon YYYY HH24:MI')
           || '. Recorded, not deleted — this is the audit trail of what was wrong and when.')
   where r.resolved_at is null
     and not exists (select 1 from _cur c2 where c2.discrepancy_key = r.discrepancy_key);
  get diagnostics v_res = row_count;

  return query select c3.class::text, count(*)::int, v_new, v_res from _cur c3 group by c3.class;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_sweep_unknowns()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v int := 0;
begin
  insert into suppliers (origin_license, supplier_name, first_received)
  select p.raw->>'ItemFromFacilityLicenseNumber', min(nullif(p.raw->>'ReceivedFromFacilityName','')), min(p.packaged_on)
  from metrc_packages p
  where coalesce(p.raw->>'ItemFromFacilityLicenseNumber','') <> ''
  group by 1
  on conflict (origin_license) do nothing;

  update suppliers set bought_as='our own licence', set_by='system', set_at=now()
  where origin_license in ('MC281714','MP281909') and bought_as='not yet set';

  insert into open_questions (question_key, area, question, why_it_matters, what_is_blocked, exposure_lb)
  select 'supplier_intent:'||s.origin_license, 'Purchasing',
    'What do we buy from '||coalesce(s.supplier_name,'licence '||s.origin_license)||'? Sound material, failed material bought at a discount to remediate, or biomass for extraction?',
    'Until this is answered the platform cannot tell a supplier quality problem from a deliberate discounted purchase, so it will not count either as a loss and every cost figure on that material is unreliable.',
    'Loss reporting and cost per pound on '||coalesce(s.supplier_name, s.origin_license),
    (select round(sum(pounds),1) from v_stock_on_hand v where v.origin_license = s.origin_license)
  from suppliers s where s.bought_as = 'not yet set'
  on conflict (question_key) do update set last_seen=now(), exposure_lb=excluded.exposure_lb;

  insert into open_questions (question_key, area, question, why_it_matters, what_is_blocked, exposure_lb)
  select 'supplier_unnamed:'||v.origin_license, 'Purchasing',
    'Who is licence '||v.origin_license||'? We hold material from them with no supplier name recorded.',
    'We cannot raise a quality issue, negotiate, or account for material when we do not know who sold it to us.',
    'Supplier accountability', round(sum(v.pounds),1)
  from v_stock_on_hand v
  where v.origin <> 'Grown by us' and coalesce(v.supplier,'') in ('','(supplier not recorded)')
  group by v.origin_license
  on conflict (question_key) do update set last_seen=now(), exposure_lb=excluded.exposure_lb;

  insert into open_questions (question_key, area, question, why_it_matters, what_is_blocked)
  select 'factor:'||c.key, 'Measurement',
    'What is the real value for "'||c.label||'"? It is on a default of '||c.value||' '||coalesce(c.unit,'')||'.',
    c.what_it_means, 'Every figure calculated from this factor'
  from conversion_factors c where c.set_by like 'default%'
  on conflict (question_key) do update set last_seen=now();

  insert into open_questions (question_key, area, question, why_it_matters, what_is_blocked, exposure_lb)
  select 'limit:'||l.stream, 'Inventory control',
    'What is the maximum '||l.stream||' we should ever hold, in pounds?',
    'Without a ceiling nothing can warn us we are over-stocked or holding material too long.',
    'Over-stock alerting on '||l.stream,
    (select round(sum(pounds),1) from v_stock_on_hand v where v.stream = l.stream)
  from storage_limits l where l.max_lb is null
  on conflict (question_key) do update set last_seen=now(), exposure_lb=excluded.exposure_lb;

  update open_questions q set status='answered', answered_at=now()
  where q.status='open' and (
    (q.question_key like 'supplier_intent:%' and exists (select 1 from suppliers s where 'supplier_intent:'||s.origin_license=q.question_key and s.bought_as<>'not yet set'))
    or (q.question_key like 'factor:%' and exists (select 1 from conversion_factors c where 'factor:'||c.key=q.question_key and c.set_by not like 'default%'))
    or (q.question_key like 'limit:%' and exists (select 1 from storage_limits l where 'limit:'||l.stream=q.question_key and l.max_lb is not null))
  );

  select count(*) into v from open_questions where status='open';
  return v;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_sync_review()
 RETURNS TABLE(raised text, detail text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare rec record; v_run_id bigint;
begin
  insert into watchdog_runs (ran_at, ran_by, notes)
  values (now(), 'tg_sync_review', 'automated review of sync health')
  returning id into v_run_id;

  for rec in
    select endpoint, license, count(*) att,
           count(*) filter (where status='error') err,
           max(left(error,160)) last_err
    from metrc_sync_runs
    where started_at > now() - interval '24 hours'
    group by 1,2
    having count(*) filter (where status='error')::numeric / nullif(count(*),0) > 0.2
  loop
    insert into watchdog_findings
      (run_id, fingerprint, severity, what, where_it_is, who_is_accountable,
       when_it_started, why_it_matters, how_it_was_detected, what_to_do, the_arithmetic)
    values (v_run_id, 'sync-failing:'||rec.endpoint||':'||coalesce(rec.license,'-'),
      case when rec.err = rec.att then 'critical' else 'elevated' end,
      'Sync "'||rec.endpoint||'" is failing on licence '||coalesce(rec.license,'?'),
      'Metrc sync · '||rec.endpoint, 'Vincent',
      (select min(started_at)::text from metrc_sync_runs m
        where m.endpoint=rec.endpoint and m.status='error'),
      case when rec.err = rec.att
        then 'Every single run failed. Whatever this endpoint feeds is stale or empty, and no page will say so.'
        else 'Partial failure means the data is incomplete in ways nothing else will reveal.' end,
      'Reviewed metrc_sync_runs over the last 24 hours and compared errors to attempts.',
      case when rec.last_err ilike '%401%'
        then 'Metrc is refusing the credentials. Check the API key is authorised for this licence AND this endpoint - Metrc permissions are per endpoint, not just per licence.'
        else 'Read the error text and fix the cause. Do not disable the sync - a disabled sync is a silent one.' end,
      rec.err||' of '||rec.att||' runs failed in 24 hours = '
        ||round(100.0*rec.err/rec.att)||' percent. Last error: '||coalesce(rec.last_err,'none'))
    on conflict do nothing;
    raised := 'sync failing'; detail := rec.endpoint||' / '||coalesce(rec.license,'-'); return next;
  end loop;

  for rec in
    select display_name, status, agent_key from v_agent_health
    where status in ('OVERDUE','NEVER RAN') and enabled
  loop
    insert into watchdog_findings
      (run_id, fingerprint, severity, what, where_it_is, who_is_accountable,
       why_it_matters, how_it_was_detected, what_to_do)
    values (v_run_id, 'agent-silent:'||rec.agent_key,
      case when rec.status='NEVER RAN' then 'critical' else 'elevated' end,
      rec.display_name||' — '||rec.status,
      'Agent registry · '||rec.agent_key, 'Vincent',
      'An agent that has stopped looks exactly like an agent with nothing to report. Silence is the failure we cannot see.',
      'Compared each agent''s last run against the interval declared in agent_registry.',
      'Find out whether it is broken or was switched off deliberately. If deliberate, disable it in agent_registry so it stops reporting as overdue.')
    on conflict do nothing;
    raised := rec.status; detail := rec.display_name; return next;
  end loop;

  for rec in
    select endpoint, license, count(*) n from metrc_sync_runs
    where started_at > now() - interval '24 hours'
      and status='ok' and coalesce(records,0)=0
    group by 1,2 having count(*) >= 5
  loop
    insert into watchdog_findings
      (run_id, fingerprint, severity, what, where_it_is, who_is_accountable,
       why_it_matters, how_it_was_detected, what_to_do)
    values (v_run_id, 'sync-empty:'||rec.endpoint||':'||coalesce(rec.license,'-'), 'watch',
      'Sync "'||rec.endpoint||'" reports success but returns no records',
      'Metrc sync · '||rec.endpoint, 'Vincent',
      'A sync that succeeds with nothing in it reads as healthy on every dashboard. It may be correct - or it may be pointed at the wrong window.',
      'Counted runs in the last 24 hours with status ok and zero records.',
      'Confirm there genuinely is nothing new. If there should be, check the date window and the licence.')
    on conflict do nothing;
    raised := 'sync empty'; detail := rec.endpoint; return next;
  end loop;

  update watchdog_runs w
     set findings_raised = (select count(*) from watchdog_findings f where f.run_id = v_run_id)
   where w.id = v_run_id;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_task_from_dashboard(p_title text, p_description text, p_department text, p_kpi text, p_value numeric, p_unit text, p_drill text, p_assignee bigint, p_due date, p_priority text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id bigint;
begin
  if coalesce(length(trim(p_title)),0) < 5 then
    raise exception 'A task needs a title of at least five characters.';
  end if;
  insert into tasks (title, description, status, priority, assignee_employee_id, due_on,
                     department, source_view, source_kpi, source_value, source_unit,
                     source_snapshot, created_by)
  values (p_title, p_description, 'open', coalesce(p_priority,'normal'), p_assignee, p_due,
          p_department, p_drill, p_kpi, p_value, p_unit,
          jsonb_build_object('kpi',p_kpi,'value',p_value,'unit',p_unit,'department',p_department,
                             'captured_at', now(), 'drill', p_drill),
          auth.uid())
  returning id into v_id;
  return v_id;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_touch_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin new.updated_at := now(); return new; end $function$
;
CREATE OR REPLACE FUNCTION public.tg_trace(p_term text)
 RETURNS TABLE(event_date date, phase text, event text, subject text, identifier text, quantity numeric, uom text, location text, status text, counterparty text, document_link text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$                               -- call it sees the same chain
begin
  return query
  select pl.planted_on, '1 Plant', 'Plant tagged in ' || coalesce(pl.room,'(no room)'),
    coalesce(pl.strain,'(no strain)'), pl.tag, 1::numeric, 'plant', pl.room,
    case pl.source_state when 'inactive' then 'Harvested or retired' else initcap(pl.source_state) end,
    null::text, null::text
  from metrc_plants pl
  where pl.tag ilike '%'||p_term||'%' or pl.strain ilike '%'||p_term||'%' or pl.room ilike '%'||p_term||'%'
  union all
  select pb.planted_on, '1 Plant', 'Batch started: ' || pb.name, coalesce(pb.strain,'(no strain)'), pb.name,
    coalesce(pb.count,0)::numeric, 'plants', 'Propagation', initcap(coalesce(pb.source_state,'')), null, null
  from metrc_plant_batches pb
  where pb.name ilike '%'||p_term||'%' or pb.strain ilike '%'||p_term||'%'
  union all
  select h.harvest_start, '2 Harvest', 'Takedown: ' || h.name,
    coalesce(h.raw->>'SourceStrainNames', h.name), h.name,
    coalesce((h.raw->>'TotalWetWeight')::numeric,0), coalesce(h.raw->>'UnitOfWeightName','g'),
    coalesce(h.raw->>'DryingLocationName','(no room)'),
    coalesce((h.raw->>'PlantCount'),'0') || ' plants harvested', null, null
  from metrc_harvests h
  where h.name ilike '%'||p_term||'%' or coalesce(h.raw->>'SourceStrainNames','') ilike '%'||p_term||'%'
     or coalesce(h.raw->>'DryingLocationName','') ilike '%'||p_term||'%'
  union all
  select h.harvest_start, '3 Loss', 'Waste recorded against ' || h.name,
    coalesce(h.raw->>'SourceStrainNames', h.name), h.name,
    coalesce((h.raw->>'TotalWasteWeight')::numeric,0), coalesce(h.raw->>'UnitOfWeightName','g'),
    coalesce(h.raw->>'DryingLocationName','(no room)'), 'Waste', null, null
  from metrc_harvests h
  where (h.name ilike '%'||p_term||'%' or coalesce(h.raw->>'SourceStrainNames','') ilike '%'||p_term||'%')
    and coalesce((h.raw->>'TotalWasteWeight')::numeric,0) > 0
  union all
  select p.packaged_on, '4 Package', 'Package created: ' || coalesce(p.item_name,'(unnamed)'),
    coalesce(nullif(p.raw->>'SourceHarvestNames',''),'(no source harvest)'), p.tag,
    coalesce(p.quantity,0), coalesce(p.uom,'ea'), coalesce(p.location,'(no location)'),
    case when (p.raw->>'IsOnHold')::boolean then 'ON HOLD'
         when p.source_state='intransit' then 'In transit'
         when p.source_state='inactive' then 'Closed or sold'
         else coalesce(p.lab_testing_state,'In inventory') end,
    null, null
  from metrc_packages p
  where p.tag ilike '%'||p_term||'%' or coalesce(p.item_name,'') ilike '%'||p_term||'%'
     or coalesce(p.raw->>'SourceHarvestNames','') ilike '%'||p_term||'%'
     or coalesce(p.location,'') ilike '%'||p_term||'%'
  union all
  -- BOUGHT IN: where it came from, taken off the inbound manifest. For third-party
  -- material this IS the origin - the grow record sits with the supplier.
  select (p.raw->>'ReceivedDateTime')::date, '2 Harvest',
    'Bought in from ' || coalesce(nullif(p.raw->>'ItemFromFacilityName',''),
                                  nullif(p.raw->>'ReceivedFromFacilityName',''),'(supplier not named)'),
    'Origin is the supplier, not our grow. Certificate and manifest below are its history.',
    coalesce(nullif(p.raw->>'ReceivedFromManifestNumber',''), p.tag),
    coalesce(p.quantity,0), coalesce(p.uom,'ea'), coalesce(p.location,''),
    'BOUGHT IN under licence ' || coalesce(p.raw->>'ItemFromFacilityLicenseNumber','(not recorded)'),
    coalesce(nullif(p.raw->>'ItemFromFacilityName',''), nullif(p.raw->>'ReceivedFromFacilityName','')),
    md.download_url
  from metrc_packages p
  left join lateral (select * from metrc_documents m where m.doc_type='manifest'
      and m.manifest_number = nullif(p.raw->>'ReceivedFromManifestNumber','') limit 1) md on true
  where (p.tag ilike '%'||p_term||'%')
    and coalesce(p.raw->>'ItemFromFacilityLicenseNumber','') <> all (array['MC281714','MP281909'])
  union all
  -- TEST SCORES: the headline numbers, not every analyte
  select r.result_date, '5 Laboratory', 'RESULT — ' || r.test_name,
    coalesce(r.lab_facility,'(laboratory not recorded)'), r.package_tag,
    r.result, coalesce(nullif(r.units,''),'%'), coalesce(r.lab_facility,''),
    case when r.passed is true then 'Passed' when r.passed is false then 'FAILED' else 'Recorded' end,
    r.lab_facility,
    (select d.download_url from metrc_documents d
      where d.doc_type='coa' and d.metrc_id = r.document_file_id and d.download_url is not null limit 1)
  from metrc_lab_results r
  where r.package_tag ilike '%'||p_term||'%'
    and (r.test_name ilike 'Total THC%' or r.test_name ilike 'Total CBD%'
         or r.test_name ilike 'Total Terpenes%' or r.test_name ilike 'Total Cannabinoids%')
    and r.test_name not ilike '%Retest%'
  union all
  -- CERTIFICATE on file, as its own event with the download
  select d.fetched_at::date, '5 Laboratory', 'Certificate of Analysis on file',
    coalesce(lr.lab_facility,'(laboratory not recorded)'), d.package_tag,
    null::numeric, '', coalesce(lr.lab_facility,''),
    'Click Open to download, print or send', lr.lab_facility, d.download_url
  from metrc_documents d
  left join lateral (select * from metrc_lab_results r2 where r2.document_file_id = d.metrc_id limit 1) lr on true
  where d.doc_type='coa' and d.download_url is not null and d.package_tag ilike '%'||p_term||'%'
  union all
  -- MANIFESTS, in and out. Outgoing is the sale.
  select t.created_on, '6 Transfer',
    case when t.direction='outgoing' then 'SOLD — manifest ' || t.manifest_number
         else 'Received on manifest ' || t.manifest_number end,
    coalesce(t.recipient, t.shipper, '(counterparty not recorded)'), t.manifest_number,
    coalesce((t.raw->>'PackageCount')::numeric,0), 'packages',
    coalesce(t.shipper,''),
    case when t.direction='outgoing'
         then 'Sold to ' || coalesce(t.recipient,'(customer not recorded)')
              || coalesce(' · invoice ' || nullif(t.raw->'_delivery'->>'InvoiceNumber',''),'')
         else initcap(t.direction) end,
    coalesce(t.recipient, t.shipper),
    coalesce(md2.download_url,
             case when t.raw->>'Id' is not null
                  then 'https://ma.metrc.com/reports/transfers/'||(t.raw->>'Id')||'/manifest' end)
  from metrc_transfers t
  left join lateral (select * from metrc_documents m2 where m2.doc_type='manifest'
      and m2.manifest_number = t.manifest_number and m2.download_url is not null limit 1) md2 on true
  where t.manifest_number ilike '%'||p_term||'%'
     or coalesce(t.recipient,'') ilike '%'||p_term||'%' or coalesce(t.shipper,'') ilike '%'||p_term||'%'
     or exists (select 1 from metrc_packages p3
                where (p3.tag ilike '%'||p_term||'%' or coalesce(p3.raw->>'SourceHarvestNames','') ilike '%'||p_term||'%')
                  and t.raw::text like '%'||p3.tag||'%')
     or exists (select 1 from metrc_packages p4
                where p4.tag ilike '%'||p_term||'%'
                  and nullif(p4.raw->>'ReceivedFromManifestNumber','') = t.manifest_number)
  union all
  select a.created_at::date, '7 Allocation', 'Requested by ' || coalesce(a.requester_name,'someone') || ': ' || a.material_name,
    a.material_name, 'Request #' || a.request_no, a.quantity, a.uom, a.destination,
    upper(a.status) || case when a.decider_name is not null then ' by ' || a.decider_name else '' end
      || case when a.decision_reason is not null then ' - ' || a.decision_reason else '' end,
    a.decider_name, null
  from allocation_requests a
  where a.material_name ilike '%'||p_term||'%' or coalesce(a.source_ref,'') ilike '%'||p_term||'%'
     or coalesce(a.strain,'') ilike '%'||p_term||'%'
  order by 1 nulls last, 2;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_track_finding_state()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  insert into finding_state_history (finding_key, from_state, to_state, note, changed_by)
  values (new.finding_key, case when tg_op='UPDATE' then old.state end,
          new.state, new.note, new.changed_by);
  new.changed_at := now();
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_track_rule_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op = 'UPDATE' and new.value is not distinct from old.value then
    return new;                       -- wording changed, not the number
  end if;
  update conversion_factor_history
     set valid_to = now(), superseded_by = coalesce(new.set_by,'unknown')
   where key = new.key and valid_to is null;
  insert into conversion_factor_history
    (key, value, unit, set_by, where_it_came_from, valid_from)
  values (new.key, new.value, new.unit, new.set_by, new.where_it_came_from, now());
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_transfers_missing_licence(p_limit integer DEFAULT 100)
 RETURNS TABLE(license text, manifest_number text, direction text, recipient text, raw jsonb)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select t.license, t.manifest_number, t.direction, t.recipient, t.raw
  from metrc_transfers t
  where coalesce(t.raw->'_delivery'->>'RecipientFacilityLicenseNumber',
                 t.raw->>'RecipientFacilityLicenseNumber') is null
  order by t.manifest_number
  limit p_limit;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_unpost_reconciliation(p_run uuid, p_by text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare run record; t record; r record; v_reversed int := 0; v_withdrawn int := 0;
        where_sql text; i int;
begin
  if coalesce(btrim(p_by),'') = '' then
    raise exception 'Who is unposting? A reversal with no name attached is not a decision.';
  end if;
  if length(btrim(coalesce(p_reason,''))) < 15 then
    raise exception 'A reason of at least 15 characters is required to unpost. Reversing a posted reconciliation without saying why leaves the next reader guessing.';
  end if;

  select * into run from import_reconciliation_run where id = p_run;
  if not found then raise exception 'No reconciliation run %.', p_run; end if;
  if run.posted_at is null and not exists (
       select 1 from import_reconciliation where run_id = p_run and posted_at is not null) then
    raise exception 'Run % has nothing posted to reverse.', p_run;
  end if;

  select * into t from metrc_report_types where report_key = run.report_key;

  for r in select * from import_reconciliation where run_id = p_run and posted_at is not null loop
    where_sql := '';
    for i in 1 .. coalesce(array_length(t.key_cols,1), 0) loop
      where_sql := where_sql || case when i > 1 then ' and ' else '' end
                || format('%I = %L', t.key_cols[i], split_part(r.row_key, '|', i));
    end loop;

    -- Put the value back to what we held before the posting. Only rows that were
    -- actually changed need restoring; a keep_ours posting never altered the data.
    if r.decision = 'accept_file' then
      execute format('update %I set %I = %L where %s',
                     r.target_table, r.field_name, r.value_we_hold, where_sql);
    end if;

    -- Overrides are WITHDRAWN, not deleted. The record that a decision was once
    -- made, and then reversed, is itself worth keeping (rule H2).
    update tg_overrides
       set active = false, withdrawn_at = now(), withdrawn_by = auth.uid()
     where target_table = r.target_table and row_key = r.row_key
       and field_name = r.field_name and active;
    get diagnostics i = row_count;
    v_withdrawn := v_withdrawn + i;

    update import_reconciliation set posted_at = null where id = r.id;
    v_reversed := v_reversed + 1;
  end loop;

  -- Any correction raised by the posting stays open. It records a real divergence
  -- that was observed; unposting does not un-observe it.
  update import_reconciliation_run
     set unposted_at = now(), unposted_by = p_by, posted_at = null, posted_by = null,
         note = coalesce(note || ' · ', '') || 'Unposted by ' || p_by || ': ' || btrim(p_reason)
   where id = p_run;

  return jsonb_build_object('ok', true, 'rows_reversed', v_reversed,
    'overrides_withdrawn', v_withdrawn,
    'note', 'Values restored and overrides withdrawn. Any metrc_corrections raised by the posting stay open - the divergence was real when it was seen, and unposting does not undo that.');
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_verify()
 RETURNS TABLE(check_key text, verdict text, value_a numeric, value_b numeric, pct_apart numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c record; a numeric; b numeric; diff numeric; pct numeric; v text; msg text; v_run bigint;
begin
  insert into watchdog_runs (ran_at, ran_by, notes)
  values (now(), 'tg_verify', 'independent verification: two derivations per fact')
  returning id into v_run;

  for c in select * from verification_checks where enabled order by check_key loop
    a := null; b := null; msg := null;
    begin
      execute c.source_a_sql into a;
      execute c.source_b_sql into b;
      diff := coalesce(a,0) - coalesce(b,0);
      pct  := case when coalesce(b,0)=0 and coalesce(a,0)=0 then 0
                   when coalesce(b,0)=0 then 100
                   else abs(diff)/abs(b)*100 end;
      v := case when pct <= c.tolerance_pct then 'agree' else 'DISAGREE' end;
    exception when others then
      v := 'error'; msg := left(sqlerrm,160); pct := null; diff := null;
    end;

    insert into verification_runs (check_key, value_a, value_b, difference, pct_apart, verdict, note)
    values (c.check_key, a, b, diff, pct, v, msg);

    if v <> 'agree' then
      insert into watchdog_findings
        (run_id, fingerprint, severity, what, where_it_is, who_is_accountable,
         why_it_matters, how_it_was_detected, what_to_do, the_arithmetic)
      values (v_run, 'verify:'||c.check_key,
        case when v='error' then 'elevated' else c.severity end,
        case when v='error' then c.title||' — the check itself failed to run'
             else c.title||' — the two sources disagree' end,
        'Verification · '||c.check_key, c.owner, c.what_it_proves,
        'Derived the same fact two independent ways and compared. '||c.source_a_label||' against '||c.source_b_label||'.',
        case when v='error'
          then 'The verification could not run: '||coalesce(msg,'?')||'. A check that cannot run proves nothing.'
          else 'Find out which source is right before anyone quotes either figure. Do not average them.' end,
        case when v='error' then 'check errored: '||coalesce(msg,'?')
             else c.source_a_label||' = '||coalesce(a::text,'null')||' · '
                  ||c.source_b_label||' = '||coalesce(b::text,'null')||' · apart by '
                  ||round(coalesce(pct,0),2)||'% (tolerance '||c.tolerance_pct||'%). '
                  ||'This is a reconciliation gap, NOT money at risk - it carries no dollar figure by design.' end)
      on conflict do nothing;
    end if;

    tg_verify.check_key := c.check_key; tg_verify.verdict := v;
    tg_verify.value_a := a; tg_verify.value_b := b;
    tg_verify.pct_apart := round(coalesce(pct,0),2);
    return next;
  end loop;

  update watchdog_runs w set findings_raised =
    (select count(*) from watchdog_findings f where f.run_id = v_run) where w.id = v_run;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_verify_import_group(p_imports uuid[], p_stated integer, p_stored integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare verdict text;
begin
  verdict := tg_check_row_count(p_stated, p_stored, p_stored);
  update metrc_report_imports
  set stated_total = p_stated, count_check = verdict
  where id = any (p_imports);
  return jsonb_build_object('ok', verdict not like 'FAILED%', 'count_check', verdict,
    'chunks', array_length(p_imports,1), 'stated', p_stated, 'stored', p_stored);
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_watchdog_forensic()
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_run bigint; v_start timestamptz := clock_timestamp(); v_cost numeric;
  v_raised int := 0; v_lb numeric := 0; v_usd numeric := 0;
begin
  select value into v_cost from conversion_factors where key='target_cost_per_lb';
  insert into watchdog_runs (ran_by) values ('scheduled sweep') returning id into v_run;

  -- ── Never submitted for testing ──────────────────────────────────
  insert into watchdog_findings (run_id, fingerprint, severity, what, where_it_is, who_is_accountable,
    when_it_started, why_it_matters, how_it_was_detected, what_to_do, the_arithmetic, evidence, record_count, pounds, dollars, drill, search_text)
  select v_run, 'untested:'||s.stream, 'critical',
    round(sum(s.pounds),1)||' lb of '||lower(s.stream)||' has never been submitted for laboratory testing',
    string_agg(distinct s.location||' ('||s.license||')', '; '),
    'Quality and Compliance',
    'Oldest package was created '||max(s.oldest_packaged)::text||', '||max(s.oldest_days)||' days ago',
    'Untested product cannot legally be sold. It is capital that cannot move and an inspection exposure.',
    'Swept every package in Metrc where LabTestingState is NotSubmitted and quantity is above zero.',
    'Submit it for testing, or record a disposition against it in Metrc.',
    sum(s.packages)||' packages x '||round(sum(s.pounds),1)||' lb x $'||v_cost||' per lb = $'||round(sum(s.pounds)*v_cost),
    jsonb_agg(jsonb_build_object('stream',s.stream,'license',s.license,'location',s.location,
      'packages',s.packages,'pounds',s.pounds,'oldest_days',s.oldest_days,'oldest_packaged',s.oldest_packaged)),
    sum(s.packages)::int, round(sum(s.pounds),1), round(sum(s.pounds)*v_cost), 'lab_results',
    'never submitted testing untested '||s.stream||' '||string_agg(distinct s.location,' ')||' '||string_agg(distinct s.license,' ')
  from v_stock_on_hand s where s.lab_state='NotSubmitted' group by s.stream having sum(s.pounds) > 0.5;

  -- ── Our own material that failed ─────────────────────────────────
  insert into watchdog_findings (run_id, fingerprint, severity, what, where_it_is, who_is_accountable,
    when_it_started, why_it_matters, how_it_was_detected, what_to_do, the_arithmetic, evidence, record_count, pounds, dollars, drill, search_text)
  select v_run, 'ourfail:'||s.stream, 'critical',
    round(sum(s.pounds),1)||' lb of '||lower(s.stream)||' we grew ourselves failed laboratory testing',
    string_agg(distinct s.location||' ('||s.license||')', '; '),
    'Cultivation and Quality',
    'Oldest failed package '||max(s.oldest_days)||' days old, created '||max(s.oldest_packaged)::text,
    'We grew it, packaged it and it failed. This is a genuine loss and a process failure to trace back to a room, a dry time or a handling step.',
    'Swept every package where LabTestingState is TestFailed and the originating licence is one of ours.',
    'Find the root cause, then decide remediate or destroy and record the disposition in Metrc.',
    sum(s.packages)||' packages x '||round(sum(s.pounds),1)||' lb x $'||v_cost||' = $'||round(sum(s.pounds)*v_cost),
    jsonb_agg(jsonb_build_object('stream',s.stream,'location',s.location,'strains',s.strains,
      'packages',s.packages,'pounds',s.pounds,'oldest_days',s.oldest_days)),
    sum(s.packages)::int, round(sum(s.pounds),1), round(sum(s.pounds)*v_cost), 'failed_testing_by_origin',
    'failed testing our own '||s.stream||' '||string_agg(distinct s.location,' ')
  from v_stock_on_hand s where s.lab_state='TestFailed' and s.origin='Grown by us' group by s.stream;

  -- ── Harvests that do not reconcile ───────────────────────────────
  insert into watchdog_findings (run_id, fingerprint, severity, what, where_it_is, who_is_accountable,
    when_it_started, why_it_matters, how_it_was_detected, what_to_do, the_arithmetic, evidence, record_count, pounds, drill, search_text)
  select v_run, 'massbal:'||m.harvest, 'critical',
    'Harvest '||m.harvest||' does not reconcile - '||abs(m.reconciliation_gap_lb)||' lb unexplained',
    m.room, 'Cultivation - whoever recorded the weights',
    'Harvest cut '||m.harvest_start::text||coalesce(', closed '||m.finished::text,''),
    'Wet weight must equal packaged plus recorded waste plus evaporated moisture. A gap means a weight was entered wrong or product left without being recorded.',
    'Compared wet minus packaged minus waste against the current weight Metrc holds independently, flagging any gap over two percent.',
    'Find which of the four figures is wrong and correct it in Metrc.',
    m.the_arithmetic, to_jsonb(m), 1, abs(m.reconciliation_gap_lb), 'moisture_accounting',
    'mass balance reconcile '||m.harvest||' '||m.room||' '||coalesce(m.strain,'')
  from v_moisture_accounting m
  where m.finished is not null and abs(coalesce(m.reconciliation_gap_lb,0)) > greatest(2, m.wet_lb*0.02);

  -- ── Storage limits breached ──────────────────────────────────────
  insert into watchdog_findings (run_id, fingerprint, severity, what, where_it_is, who_is_accountable,
    when_it_started, why_it_matters, how_it_was_detected, what_to_do, the_arithmetic, evidence, pounds, dollars, drill, search_text)
  select v_run, 'limit:'||l.stream, 'elevated',
    l.stream||' is '||lower(l.status),
    coalesce(l.location,'all locations'), 'Vincent - limits are his to set and enforce',
    'Oldest package '||l.oldest_days||' days old',
    'Without a ceiling nothing warns us we are over-stocked or holding material past its useful life. Capital sits and quality falls.',
    'Compared live pounds on hand and oldest package age against the ceilings set on the Storage Limits page.',
    'Move it, sell it, process it, or raise the limit deliberately and record who decided.',
    coalesce(l.on_hand_lb,0)||' lb on hand'||coalesce(' against a '||l.max_lb||' lb ceiling','')||
      coalesce(', oldest '||l.oldest_days||' days against a '||l.max_age_days||' day limit',''),
    to_jsonb(l), l.on_hand_lb, round(l.on_hand_lb*v_cost), 'storage_limit_status',
    'storage limit '||l.stream||' '||l.status
  from v_storage_limit_status l
  where l.status in ('OVER THE STORAGE LIMIT','MATERIAL OLDER THAN THE LIMIT','APPROACHING THE LIMIT');

  -- ── Purchased material sitting untouched ─────────────────────────
  insert into watchdog_findings (run_id, fingerprint, severity, what, where_it_is, who_is_accountable,
    when_it_started, why_it_matters, how_it_was_detected, what_to_do, evidence, record_count, drill, search_text)
  select v_run, 'tpsitting:'||t.supplier, 'elevated',
    count(*)||' purchased packages from '||t.supplier||' received and never drawn from',
    string_agg(distinct t.location, '; '), 'Purchasing and Manufacturing',
    'Oldest received '||max(t.received_on)::text||', '||max(t.days_since_received)||' days ago',
    'Purchased material sitting still is cash already spent and not yet earned back, and it ages while it waits.',
    'Traced every purchased package from its inbound manifest and checked whether any quantity has been drawn.',
    'Process it or sell it, or explain why it is being held.',
    jsonb_agg(jsonb_build_object('tag',t.tag,'item',t.item_name,'received_on',t.received_on,
      'qty',t.qty_received,'remaining',t.qty_remaining,'days',t.days_since_received)),
    count(*)::int, 'third_party_lifecycle',
    'third party sitting untouched '||t.supplier
  from v_third_party_lifecycle t where t.position like 'SITTING%' group by t.supplier;

  -- ── Laboratory turnaround ────────────────────────────────────────
  insert into watchdog_findings (run_id, fingerprint, severity, what, where_it_is, who_is_accountable,
    when_it_started, why_it_matters, how_it_was_detected, what_to_do, the_arithmetic, evidence, record_count, drill, search_text)
  select v_run, 'labslow:'||coalesce(t.category,'unknown'), 'watch',
    'Laboratory turnaround on '||t.category||' reached '||t.slowest_turnaround_days||' days',
    'External laboratory', 'Quality - whoever manages the laboratory relationship',
    'Measured across '||t.packages||' packages on record',
    'Every day waiting on a result is a day the product cannot be sold. Slow turnaround is working capital sitting idle.',
    'Measured the gap between the date each package was submitted and the date its result was recorded in Metrc.',
    'Chase the laboratory, and consider a second laboratory for overflow.',
    'average '||coalesce(t.avg_turnaround_days,0)||' days, worst '||t.slowest_turnaround_days||', '||t.took_over_14_days||' over 14 days',
    to_jsonb(t), t.packages, 'lab_turnaround_summary',
    'laboratory turnaround slow '||t.category
  from v_lab_turnaround_summary t where coalesce(t.slowest_turnaround_days,0) > 14;

  -- ── Questions left unanswered ────────────────────────────────────
  insert into watchdog_findings (run_id, fingerprint, severity, what, where_it_is, who_is_accountable,
    when_it_started, why_it_matters, how_it_was_detected, what_to_do, evidence, pounds, dollars, drill, search_text)
  select v_run, 'question:'||q.question_key, 'elevated',
    'Unanswered '||q.days_open||' days: '||q.question,
    q.area, 'Vinny or Vincent', 'First raised '||q.first_raised::text,
    coalesce(q.why_it_matters,'Blocks reporting'), 'Raised automatically when the platform found a fact nobody had recorded.',
    'Answer it. Until then every figure it feeds is unreliable.',
    to_jsonb(q), q.exposure_lb, q.exposure_dollars, 'open_questions',
    'unanswered question '||q.area||' '||q.question
  from v_open_questions q where q.days_open > 3;

  select count(*), coalesce(sum(pounds),0), coalesce(sum(dollars),0)
    into v_raised, v_lb, v_usd
  from watchdog_findings where run_id = v_run;

  update watchdog_runs
     set duration_ms = extract(milliseconds from (clock_timestamp() - v_start))::int,
         findings_raised = v_raised, total_pounds_flagged = v_lb, total_dollars_flagged = v_usd
   where id = v_run;

  perform tg_inventory_watch();
  return v_run;
end $function$
;
CREATE OR REPLACE FUNCTION public.tg_watchdog_search(q text)
 RETURNS SETOF v_watchdog_log
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select * from v_watchdog_log
  where to_tsvector('english', coalesce(search_text,'')||' '||what||' '||coalesce(where_it_is,'')||' '||coalesce(who_is_accountable,''))
        @@ plainto_tsquery('english', q)
     or what ilike '%'||q||'%' or coalesce(where_it_is,'') ilike '%'||q||'%'
     or coalesce(evidence::text,'') ilike '%'||q||'%'
  order by observed_at desc;
$function$
;
CREATE OR REPLACE FUNCTION public.tg_watchdog_upsert_by_fingerprint()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare existing_id bigint;
begin
  if new.fingerprint is null then
    return new;                      -- no identity, treat as a new finding
  end if;

  select id into existing_id
  from watchdog_findings
  where fingerprint = new.fingerprint
  limit 1;

  if existing_id is null then
    return new;                      -- genuinely new
  end if;

  /* Seen before. Refresh it in place, keeping when_it_started and the original
     observed_at as the first sighting. Never create a second row. */
  update watchdog_findings w set
    observed_at        = greatest(w.observed_at, coalesce(new.observed_at, now())),
    severity           = coalesce(new.severity, w.severity),
    what               = coalesce(new.what, w.what),
    where_it_is        = coalesce(new.where_it_is, w.where_it_is),
    who_is_accountable = coalesce(new.who_is_accountable, w.who_is_accountable),
    why_it_matters     = coalesce(new.why_it_matters, w.why_it_matters),
    how_it_was_detected= coalesce(new.how_it_was_detected, w.how_it_was_detected),
    what_to_do         = coalesce(new.what_to_do, w.what_to_do),
    the_arithmetic     = coalesce(new.the_arithmetic, w.the_arithmetic),
    evidence           = coalesce(new.evidence, w.evidence),
    record_count       = coalesce(new.record_count, w.record_count),
    pounds             = coalesce(new.pounds, w.pounds),
    dollars            = coalesce(new.dollars, w.dollars),
    drill              = coalesce(new.drill, w.drill),
    run_id             = coalesce(new.run_id, w.run_id)
  where w.id = existing_id;

  return null;                       -- swallow the insert; the update stands
end $function$
;
CREATE OR REPLACE FUNCTION public.trg_automap_on_import()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not exists (select 1 from sheet_column_map where source_id = new.source_id and role='package_tag') then
    perform f_automap_tag_column(new.source_id);
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.trg_cost_input_history()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if tg_op='UPDATE' and new.value is distinct from old.value then
    insert into cost_input_history(key, old_value, new_value, changed_by)
    values (new.key, old.value, new.value, new.updated_by);
    new.updated_at := now();
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.trg_metrc_correction_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.fixed_in_metrc and not old.fixed_in_metrc then
    if new.fixed_by is null or length(trim(new.fixed_by)) < 2 then
      raise exception 'Name who fixed it in Metrc before closing this.';
    end if;
    if new.verification_note is null or length(trim(new.verification_note)) < 20 then
      raise exception 'Record what was actually done in Metrc — the manifest number, support ticket or adjustment reference — in at least twenty characters. This cannot be closed on a tick alone.';
    end if;
    new.fixed_on := coalesce(new.fixed_on, current_date);
  end if;
  if old.fixed_in_metrc and not new.fixed_in_metrc then
    raise exception 'A correction that was verified as fixed in Metrc cannot be quietly reopened. Raise a new correction instead.';
  end if;
  return new;
end $function$
;

-- ==========================================================================
-- VIEWS — created in dependency order
-- ==========================================================================

create materialized view if not exists public.mv_package_documents as
 SELECT tag AS package_tag,
    license,
    ( SELECT count(*) AS count
           FROM metrc_documents d
          WHERE d.doc_type = 'coa'::text AND d.package_tag = p.tag AND d.storage_path IS NOT NULL) AS coa_count,
    ( SELECT count(DISTINCT r.document_file_id) AS count
           FROM metrc_lab_results r
          WHERE r.package_tag = p.tag AND r.document_file_id IS NOT NULL) AS coa_expected,
    ( SELECT count(*) AS count
           FROM metrc_lab_results r
          WHERE r.package_tag = p.tag) AS lab_result_rows,
    ( SELECT max(r.lab_facility) AS max
           FROM metrc_lab_results r
          WHERE r.package_tag = p.tag) AS lab,
    ( SELECT max(r.result_date) AS max
           FROM metrc_lab_results r
          WHERE r.package_tag = p.tag) AS tested_on,
    lab_testing_state
   FROM metrc_packages p;
create materialized view if not exists public.mv_package_harvest as
 SELECT DISTINCT btrim(hn.hn) AS harvest_name,
    p.id AS package_id,
    p.quantity,
    p.packaged_on,
    p.raw ->> 'LabTestingState'::text AS lab_state,
    p.raw #>> '{Item,ProductCategoryName}'::text[] AS category
   FROM metrc_packages p
     CROSS JOIN LATERAL unnest(string_to_array(COALESCE(p.raw ->> 'SourceHarvestNames'::text, ''::text), ','::text)) hn(hn)
  WHERE btrim(hn.hn) <> ''::text;
create or replace view public.v_access_preview as
 SELECT r.role,
    r.rank,
    pc.category,
    pc.is_shared,
    count(*) FILTER (WHERE COALESCE(sp.min_rank, 0) <= r.rank) AS pages_they_would_see,
    count(*) FILTER (WHERE COALESCE(sp.min_rank, 0) > r.rank) AS pages_rank_blocks,
    count(*) AS pages_in_category
   FROM app_roles r
     CROSS JOIN page_category_policy pc
     JOIN nav_registry nr ON nr.category = pc.category AND nr.enabled
     LEFT JOIN sensitive_page_policy sp ON sp.view_key = nr.view_key
  WHERE (r.role IN ( SELECT unnest(enum_range(NULL::app_role))::text AS unnest))
  GROUP BY r.role, r.rank, pc.category, pc.is_shared
  ORDER BY r.rank DESC, pc.category;
create or replace view public.v_adjustment_conflicts as
 WITH g AS (
         SELECT metrc_rpt_adjustments.package_tag,
            metrc_rpt_adjustments.adjusted_on,
            metrc_rpt_adjustments.reason,
            count(*) AS rows_held,
            count(DISTINCT metrc_rpt_adjustments.quantity) AS distinct_quantities,
            count(DISTINCT metrc_rpt_adjustments.import_id) AS distinct_imports,
            min(metrc_rpt_adjustments.imported_at) AS first_seen,
            max(metrc_rpt_adjustments.imported_at) AS last_seen
           FROM metrc_rpt_adjustments
          GROUP BY metrc_rpt_adjustments.package_tag, metrc_rpt_adjustments.adjusted_on, metrc_rpt_adjustments.reason
         HAVING count(DISTINCT metrc_rpt_adjustments.quantity) > 1
        )
 SELECT a.package_tag,
    a.adjusted_on,
    a.reason,
    a.item,
    a.item_category,
    a.quantity,
    a.uom,
    a.note,
    a.adjusted_by,
    a.imported_at,
    a.import_id,
    a.licence,
    g.rows_held,
    g.distinct_quantities,
        CASE
            WHEN g.distinct_imports = 1 THEN 'Genuinely separate adjustments - the same file listed both. Keep both.'::text
            ELSE 'LIKELY A CORRECTION - a later import restated this adjustment with a different '::text || 'quantity. Both rows are kept so nothing is lost; decide which stands.'::text
        END AS reading,
    g.distinct_imports > 1 AS needs_a_decision,
    a.quantity - first_value(a.quantity) OVER (PARTITION BY a.package_tag, a.adjusted_on, a.reason ORDER BY a.imported_at) AS change_from_first
   FROM metrc_rpt_adjustments a
     JOIN g ON g.package_tag = a.package_tag AND g.adjusted_on = a.adjusted_on AND g.reason = a.reason
  ORDER BY g.distinct_imports DESC, a.package_tag, a.adjusted_on, a.imported_at;
create or replace view public.v_admin_permissions as
 SELECT r.role AS role_key,
    r.label AS role_label,
    r.rank,
    r.built_in,
    p.category AS permission_group,
    NULLIF(replace(p.category, 'Area: '::text, ''::text), p.category) AS business_area,
    p.action AS permission_key,
    p.label AS permission_label,
    p.description,
    COALESCE(rp.allowed, false) AS granted,
    rp.role IS NOT NULL AS explicitly_set,
    ( SELECT count(*) AS count
           FROM nav_role_visibility v
          WHERE v.role = r.role AND v.visible) AS pages_this_role_can_open,
    'Toggle with: insert into role_permissions(role,action,allowed) values (...) on conflict (role,action) do update set allowed = excluded.allowed. Built-in roles should be COPIED to a new role rather than edited.'::text AS how_to_change,
    'PERMISSION is what you may DO. PAGE VISIBILITY is what you may SEE. Both are required - a role holding view_finance with no page grant gets a menu missing the page it needs.'::text AS note
   FROM app_roles r
     CROSS JOIN permission_catalog p
     LEFT JOIN role_permissions rp ON rp.role = r.role AND rp.action = p.action;
create or replace view public.v_admin_settings as
 SELECT 'fiscal_year_start_month'::text AS setting_key,
    'Fiscal year starts in'::text AS label,
    'Company'::text AS section,
    COALESCE(( SELECT configurations.value #>> '{}'::text[]
           FROM configurations
          WHERE configurations.key = 'fiscal_year_start_month'::text), '1'::text) AS current_value,
    to_char(to_date(COALESCE(( SELECT configurations.value #>> '{}'::text[]
           FROM configurations
          WHERE configurations.key = 'fiscal_year_start_month'::text), '1'::text), 'MM'::text)::timestamp with time zone, 'FMMonth'::text) AS shows_as,
    'number 1-12'::text AS value_type,
    '1 (January)'::text AS default_value,
    f_fiscal_year_start()::text AS takes_effect_as,
    'Every fiscal preset on the platform: This Fiscal Year, This Fiscal Year-to-date and Last Fiscal Year. Changing it changes what those three mean on all 518 report pages at once.'::text AS what_it_affects,
    'QuickBooks holds this under Account and Settings > Advanced. It is a company fact, not a code constant - never hardcode it.'::text AS note
UNION ALL
 SELECT 'default_date_preset'::text AS setting_key,
    'Default date range'::text AS label,
    'Reports'::text AS section,
    COALESCE(( SELECT configurations.value #>> '{}'::text[]
           FROM configurations
          WHERE configurations.key = 'default_date_preset'::text), 'this_month_td'::text) AS current_value,
    COALESCE(( SELECT p.label
           FROM date_range_presets p
          WHERE p.preset_key = (( SELECT configurations.value #>> '{}'::text[]
                   FROM configurations
                  WHERE configurations.key = 'default_date_preset'::text))), 'This Month-to-date'::text) AS shows_as,
    'one of date_range_presets.preset_key'::text AS value_type,
    'this_month_td (This Month-to-date)'::text AS default_value,
    COALESCE(( SELECT p.label
           FROM date_range_presets p
          WHERE p.preset_key = (( SELECT configurations.value #>> '{}'::text[]
                   FROM configurations
                  WHERE configurations.key = 'default_date_preset'::text))), 'This Month-to-date'::text) AS takes_effect_as,
    'What a report opens on when neither the user nor the page has set anything. Users still override it per page or globally; this is only the floor.'::text AS what_it_affects,
    'The QuickBooks convention for activity reports. Snapshot pages - stock on hand, ageing, registries - stay on Today, because applying a RANGE to a balance changes what the number means.'::text AS note
UNION ALL
 SELECT 'fresh_frozen_wet_to_dry'::text AS setting_key,
    'Fresh frozen wet-to-dry ratio'::text AS label,
    'Cultivation'::text AS section,
    COALESCE(( SELECT configurations.value #>> '{}'::text[]
           FROM configurations
          WHERE configurations.key = 'fresh_frozen_wet_to_dry'::text), '4.5'::text) AS current_value,
    COALESCE(( SELECT configurations.value #>> '{}'::text[]
           FROM configurations
          WHERE configurations.key = 'fresh_frozen_wet_to_dry'::text), '4.5'::text) AS shows_as,
    'number'::text AS value_type,
    '4.5'::text AS default_value,
    COALESCE(( SELECT configurations.value #>> '{}'::text[]
           FROM configurations
          WHERE configurations.key = 'fresh_frozen_wet_to_dry'::text), '4.5'::text) AS takes_effect_as,
    'Every dry-equivalent figure. 603.9 lb of fresh frozen becomes 134.2 lb at 4.5. Measured across our own 380 harvests it is 4.17; the briefing says 5.03.'::text AS what_it_affects,
    'The three sources disagree and the owner has not ruled. Report the ratio used alongside any dry-equivalent figure.'::text AS note;
create or replace view public.v_agent_agreement as
 WITH by_subject AS (
         SELECT agent_claims.subject,
            count(*) AS claims,
            count(DISTINCT agent_claims.agent) AS agents,
            count(DISTINCT agent_claims.claimed_value) AS distinct_values,
            min(agent_claims.claimed_value) AS lowest,
            max(agent_claims.claimed_value) AS highest,
            max(agent_claims.live_value) AS live_now,
            string_agg(DISTINCT (agent_claims.agent || ' says '::text) || COALESCE(agent_claims.claimed_value::text, agent_claims.claimed_text, '?'::text), '  |  '::text ORDER BY ((agent_claims.agent || ' says '::text) || COALESCE(agent_claims.claimed_value::text, agent_claims.claimed_text, '?'::text))) AS positions,
            string_agg(DISTINCT agent_claims.status, ', '::text) AS verdicts
           FROM agent_claims
          GROUP BY agent_claims.subject
        )
 SELECT subject,
    agents,
    claims,
    positions,
    lowest,
    highest,
        CASE
            WHEN highest IS NOT NULL AND lowest IS NOT NULL AND lowest <> 0::numeric THEN round(abs(highest - lowest) / abs(lowest) * 100::numeric, 1)
            ELSE NULL::numeric
        END AS pct_apart,
    live_now,
    verdicts,
        CASE
            WHEN agents < 2 THEN 'UNCORROBORATED - only one agent has looked at this'::text
            WHEN distinct_values <= 1 THEN 'AGREED - every agent reached the same number'::text
            ELSE ((('DISAGREE - '::text || distinct_values) || ' different answers from '::text) || agents) || ' agents'::text
        END AS agreement,
        CASE
            WHEN distinct_values > 1 THEN 'THE ISSUE: agents disagree on the same question. Report BOTH figures with both methods. Never average, never pick silently - the disagreement IS the finding.'::text
            ELSE NULL::text
        END AS what_is_wrong
   FROM by_subject;
create or replace view public.v_agent_health as
 WITH sync_ev AS (
         SELECT
                CASE
                    WHEN metrc_sync_runs.endpoint ~~* 'transfers%'::text THEN 'sync:transfers'::text
                    WHEN metrc_sync_runs.endpoint ~~* 'packages%'::text THEN 'sync:packages'::text
                    WHEN metrc_sync_runs.endpoint ~~* 'harvests%'::text OR metrc_sync_runs.endpoint ~~* 'plants%'::text OR metrc_sync_runs.endpoint ~~* 'plantbatches%'::text THEN 'sync:cultivation'::text
                    WHEN metrc_sync_runs.endpoint = ANY (ARRAY['items'::text, 'strains'::text, 'locations'::text]) THEN 'sync:reference'::text
                    WHEN metrc_sync_runs.endpoint ~~* 'sales%'::text THEN 'sync:sales'::text
                    ELSE NULL::text
                END AS agent_key,
            max(metrc_sync_runs.started_at) AS last_run,
            count(*) FILTER (WHERE metrc_sync_runs.started_at > (now() - '24:00:00'::interval)) AS runs_24h,
            count(*) FILTER (WHERE metrc_sync_runs.status = 'error'::text AND metrc_sync_runs.started_at > (now() - '24:00:00'::interval)) AS errors_24h,
            sum(metrc_sync_runs.records) FILTER (WHERE metrc_sync_runs.status = 'ok'::text AND metrc_sync_runs.started_at > (now() - '24:00:00'::interval)) AS records_24h,
            max(metrc_sync_runs.error) FILTER (WHERE metrc_sync_runs.status = 'error'::text) AS last_error
           FROM metrc_sync_runs
          GROUP BY (
                CASE
                    WHEN metrc_sync_runs.endpoint ~~* 'transfers%'::text THEN 'sync:transfers'::text
                    WHEN metrc_sync_runs.endpoint ~~* 'packages%'::text THEN 'sync:packages'::text
                    WHEN metrc_sync_runs.endpoint ~~* 'harvests%'::text OR metrc_sync_runs.endpoint ~~* 'plants%'::text OR metrc_sync_runs.endpoint ~~* 'plantbatches%'::text THEN 'sync:cultivation'::text
                    WHEN metrc_sync_runs.endpoint = ANY (ARRAY['items'::text, 'strains'::text, 'locations'::text]) THEN 'sync:reference'::text
                    WHEN metrc_sync_runs.endpoint ~~* 'sales%'::text THEN 'sync:sales'::text
                    ELSE NULL::text
                END)
        ), watch_ev AS (
         SELECT
                CASE agent_findings.agent
                    WHEN 'Allocation control'::text THEN 'watch:allocation'::text
                    WHEN 'Cash velocity'::text THEN 'watch:cash'::text
                    WHEN 'Compliance watch'::text THEN 'watch:compliance'::text
                    WHEN 'Room turnaround'::text THEN 'watch:room'::text
                    WHEN 'Schedule discipline'::text THEN 'watch:schedule'::text
                    WHEN 'Loss and yield'::text THEN 'watch:loss'::text
                    ELSE 'watch:sales'::text
                END AS agent_key,
            max(agent_findings.detected_at) AS last_run,
            count(*) AS produced
           FROM agent_findings
          GROUP BY (
                CASE agent_findings.agent
                    WHEN 'Allocation control'::text THEN 'watch:allocation'::text
                    WHEN 'Cash velocity'::text THEN 'watch:cash'::text
                    WHEN 'Compliance watch'::text THEN 'watch:compliance'::text
                    WHEN 'Room turnaround'::text THEN 'watch:room'::text
                    WHEN 'Schedule discipline'::text THEN 'watch:schedule'::text
                    WHEN 'Loss and yield'::text THEN 'watch:loss'::text
                    ELSE 'watch:sales'::text
                END)
        UNION ALL
         SELECT 'watch:watchdog'::text,
            max(watchdog_runs.ran_at) AS max,
            count(*) AS count
           FROM watchdog_runs
        UNION ALL
         SELECT 'watch:custody'::text,
            max(custody_alert_log.captured_at) AS max,
            count(*) AS count
           FROM custody_alert_log
        UNION ALL
         SELECT 'watch:inventory'::text,
            max(inventory_alerts.last_seen) AS max,
            count(*) AS count
           FROM inventory_alerts
        UNION ALL
         SELECT 'maint:canary'::text,
            max(canary_runs.ran_at) AS max,
            count(*) AS count
           FROM canary_runs
        ), ev AS (
         SELECT sync_ev.agent_key,
            sync_ev.last_run,
            sync_ev.runs_24h,
            sync_ev.errors_24h,
            sync_ev.records_24h,
            sync_ev.last_error,
            NULL::bigint AS produced
           FROM sync_ev
          WHERE sync_ev.agent_key IS NOT NULL
        UNION ALL
         SELECT watch_ev.agent_key,
            watch_ev.last_run,
            NULL::bigint,
            NULL::bigint,
            NULL::bigint,
            NULL::text,
            watch_ev.produced
           FROM watch_ev
        )
 SELECT r.agent_key,
    r.display_name,
    r.kind,
    r.what_it_watches,
    r.why_it_matters,
    r.owner,
    r.expected_every_mins,
    r.verified_by,
    r.enabled,
    e.last_run,
    round(EXTRACT(epoch FROM now() - e.last_run) / 60::numeric)::integer AS minutes_since_run,
    e.runs_24h,
    e.errors_24h,
    e.records_24h,
    e.produced,
    "left"(COALESCE(e.last_error, ''::text), 140) AS last_error,
        CASE
            WHEN NOT r.enabled THEN 'off'::text
            WHEN e.last_run IS NULL THEN 'NEVER RAN'::text
            WHEN r.expected_every_mins IS NOT NULL AND e.last_run < (now() - make_interval(mins => r.expected_every_mins * 2)) THEN 'OVERDUE'::text
            WHEN COALESCE(e.runs_24h, 0::bigint) > 0 AND (e.errors_24h::numeric / e.runs_24h::numeric) > 0.2 THEN 'FAILING'::text
            ELSE 'ok'::text
        END AS status,
        CASE
            WHEN e.last_run IS NULL THEN 'Registered but has never produced anything. Either it has never run or it writes somewhere we are not looking.'::text
            WHEN r.expected_every_mins IS NOT NULL AND e.last_run < (now() - make_interval(mins => r.expected_every_mins * 2)) THEN ((('Expected every '::text || r.expected_every_mins) || ' minutes. Last ran '::text) || round(EXTRACT(epoch FROM now() - e.last_run) / 3600::numeric)) || ' hours ago. Silence here is not good news.'::text
            WHEN COALESCE(e.runs_24h, 0::bigint) > 0 AND (e.errors_24h::numeric / e.runs_24h::numeric) > 0.2 THEN ((e.errors_24h || ' of '::text) || e.runs_24h) || ' runs failed in 24 hours.'::text
            ELSE NULL::text
        END AS note
   FROM agent_registry r
     LEFT JOIN ev e ON e.agent_key = r.agent_key;
create or replace view public.v_agentmapper_queue as
 SELECT id,
    first_seen,
    last_seen,
    times_seen,
    file_name,
    licence,
    row_count,
    columns,
    closest_report,
    closest_missing,
    state,
    proposal ->> 'report_key'::text AS proposed_key,
    proposal ->> 'title'::text AS proposed_title,
    proposal ->> 'target_table'::text AS proposed_table,
    proposal ->> 'what_it_adds'::text AS proposed_what_it_adds,
    jsonb_array_length(COALESCE(proposal -> 'signature_cols'::text, '[]'::jsonb)) AS proposed_signature_count,
    ( SELECT count(*) AS count
           FROM jsonb_object_keys(COALESCE(metrc_report_unmapped.proposal -> 'column_map'::text, '{}'::jsonb)) jsonb_object_keys(jsonb_object_keys)) AS proposed_column_count,
    proposal,
    proposed_by,
    proposed_at,
    decided_by,
    decided_at,
    decision_note,
        CASE state
            WHEN 'new'::text THEN 'Waiting for the Metrc & Compliance agent to propose a mapping'::text
            WHEN 'proposed'::text THEN 'Ready for an administrator to approve'::text
            WHEN 'approved'::text THEN 'Mapped - re-upload the file and it will import'::text
            ELSE 'Rejected'::text
        END AS what_happens_next
   FROM metrc_report_unmapped
  ORDER BY (
        CASE state
            WHEN 'proposed'::text THEN 1
            WHEN 'new'::text THEN 2
            ELSE 3
        END), last_seen DESC;
create or replace view public.v_ai_access_status as
 SELECT user_id,
    display_name,
    enabled,
    daily_call_limit,
    monthly_call_limit,
        CASE
            WHEN uses_local_model THEN 'Own local model - costs the company nothing'::text
            WHEN COALESCE(own_key, ''::text) <> ''::text THEN ('Own '::text || COALESCE(own_key_provider, 'provider'::text)) || ' key - bills to them, costs the company nothing'::text
            ELSE 'Company allowance - billed to the company'::text
        END AS how_they_are_billed,
        CASE
            WHEN COALESCE(own_key, ''::text) = ''::text THEN NULL::text
            ELSE ("left"(own_key, 7) || '…'::text) || "right"(own_key, 4)
        END AS key_masked,
    ( SELECT count(*) AS count
           FROM ai_usage_log l
          WHERE l.user_id = a.user_id AND l.created_at >= date_trunc('month'::text, now()) AND l.answered_by = 'model'::text) AS model_calls_this_month,
    ( SELECT round(COALESCE(sum(l.cost_usd), 0::numeric), 4) AS round
           FROM ai_usage_log l
          WHERE l.user_id = a.user_id AND l.created_at >= date_trunc('month'::text, now())) AS cost_this_month_usd,
    updated_at
   FROM ai_user_access a
  ORDER BY display_name;
create or replace view public.v_ai_cost_position as
 SELECT
        CASE
            WHEN ( SELECT ai_settings.paid_model_enabled
               FROM ai_settings
              WHERE ai_settings.id = 1) THEN 'PAID MODEL IS ON'::text
            ELSE 'PAID MODEL IS OFF - the platform costs nothing to run'::text
        END AS status,
    ( SELECT ai_settings.hard_monthly_cost_cap_usd
           FROM ai_settings
          WHERE ai_settings.id = 1) AS monthly_cap_usd,
    ( SELECT round(COALESCE(sum(ai_usage_log.cost_usd), 0::numeric), 2) AS round
           FROM ai_usage_log
          WHERE ai_usage_log.created_at >= date_trunc('month'::text, now())) AS spent_this_month_usd,
    ( SELECT count(*) AS count
           FROM ai_usage_log
          WHERE ai_usage_log.created_at >= date_trunc('month'::text, now()) AND ai_usage_log.answered_by = 'model'::text) AS paid_calls_this_month,
    'Every page, report, dashboard, drill-down, scheduled sweep and suggestion button is a database query. Those cost nothing and are not affected by this setting.'::text AS what_is_always_free,
    'Only a free-form typed question can ever cost money, and only while the paid model is switched on and under the cap.'::text AS what_could_ever_cost;
create or replace view public.v_ai_spend as
 SELECT to_char(date_trunc('month'::text, created_at), 'YYYY-MM'::text) AS month,
    count(*) AS calls,
    count(*) FILTER (WHERE answered_by = 'database'::text) AS answered_free_by_database,
    count(*) FILTER (WHERE answered_by = 'model'::text) AS answered_by_model,
    sum(input_tokens) AS input_tokens,
    sum(output_tokens) AS output_tokens,
    round(sum(cost_usd), 2) AS cost_usd,
    round(avg(cost_usd) FILTER (WHERE answered_by = 'model'::text), 4) AS avg_cost_per_model_call,
    ( SELECT ai_settings.hard_monthly_cost_cap_usd
           FROM ai_settings
          WHERE ai_settings.id = 1) AS monthly_cap_usd,
    round((( SELECT ai_settings.hard_monthly_cost_cap_usd
           FROM ai_settings
          WHERE ai_settings.id = 1)) - sum(cost_usd), 2) AS cap_remaining_usd
   FROM ai_usage_log
  GROUP BY (to_char(date_trunc('month'::text, created_at), 'YYYY-MM'::text))
  ORDER BY (to_char(date_trunc('month'::text, created_at), 'YYYY-MM'::text)) DESC;
create or replace view public.v_ai_spend_today as
 SELECT count(*) AS calls_today,
    count(*) FILTER (WHERE answered_by = 'database'::text) AS free_today,
    round(COALESCE(sum(cost_usd), 0::numeric), 4) AS cost_today,
    ( SELECT round(COALESCE(sum(ai_usage_log_1.cost_usd), 0::numeric), 2) AS round
           FROM ai_usage_log ai_usage_log_1
          WHERE ai_usage_log_1.created_at >= date_trunc('month'::text, now())) AS cost_this_month,
    ( SELECT ai_settings.hard_monthly_cost_cap_usd
           FROM ai_settings
          WHERE ai_settings.id = 1) AS cap
   FROM ai_usage_log
  WHERE created_at >= date_trunc('day'::text, now());
create or replace view public.v_ai_usage_summary as
 SELECT COALESCE(u.display_name, u.user_id::text) AS person,
    count(*) FILTER (WHERE l.created_at >= CURRENT_DATE) AS calls_today,
    count(*) FILTER (WHERE l.created_at >= date_trunc('month'::text, now())) AS calls_this_month,
    round(COALESCE(sum(l.cost_usd) FILTER (WHERE l.created_at >= date_trunc('month'::text, now())), 0::numeric), 2) AS cost_this_month,
    COALESCE(a.daily_call_limit, ( SELECT ai_settings.default_daily_calls
           FROM ai_settings
          WHERE ai_settings.id = 1)) AS daily_limit,
    COALESCE(a.monthly_call_limit, ( SELECT ai_settings.default_monthly_calls
           FROM ai_settings
          WHERE ai_settings.id = 1)) AS monthly_limit,
    a.enabled,
    a.allowed_features
   FROM ai_usage_log l
     RIGHT JOIN ai_user_access a ON a.user_id = l.user_id
     LEFT JOIN ai_user_access u ON u.user_id = a.user_id
  GROUP BY (COALESCE(u.display_name, u.user_id::text)), a.daily_call_limit, a.monthly_call_limit, a.enabled, a.allowed_features;
create or replace view public.v_alert_email_recipients as
 SELECT r.role,
    r.full_name,
    r.email,
    'alert_recipient'::text AS from_where,
    r.is_platform_user
   FROM alert_recipient r
  WHERE r.active AND COALESCE(btrim(r.email), ''::text) <> ''::text
UNION ALL
 SELECT COALESCE(u.role::text, 'member'::text) AS role,
    COALESCE(u.display_name, au.email::text) AS full_name,
    au.email::text AS email,
    'auth.users (platform login)'::text AS from_where,
    true AS is_platform_user
   FROM auth.users au
     LEFT JOIN app_users u ON u.user_id = au.id
  WHERE au.email IS NOT NULL AND NOT (EXISTS ( SELECT 1
           FROM alert_recipient r
          WHERE lower(btrim(r.email)) = lower(au.email::text) AND r.active));
create or replace view public.v_allocation_queue as
 SELECT id,
    request_no,
    status,
    requester_name,
    requester_department,
    decider_name,
    decided_at,
    decision_reason,
    material_name,
    strain,
    stream,
    source_kind,
    source_ref,
    quantity,
    uom,
    pounds,
    destination,
    purpose,
    needed_by,
    priority,
    created_at,
    CURRENT_DATE - created_at::date AS days_waiting,
        CASE
            WHEN status = 'pending'::text AND needed_by IS NOT NULL AND needed_by < CURRENT_DATE THEN 'PAST ITS NEEDED-BY DATE and still not decided'::text
            WHEN status = 'pending'::text AND (CURRENT_DATE - created_at::date) > 7 THEN 'WAITING OVER A WEEK - this material cannot move until it is decided'::text
            WHEN status = 'pending'::text THEN 'Awaiting Vincent'::text
            WHEN status = 'approved'::text THEN (('Approved by '::text || COALESCE(decider_name, '?'::text)) || ' on '::text) || COALESCE(decided_at::date::text, '?'::text)
            WHEN status = 'denied'::text THEN 'Denied - '::text || COALESCE(decision_reason, 'no reason recorded'::text)
            ELSE status
        END AS "position"
   FROM allocation_requests r
  ORDER BY (
        CASE status
            WHEN 'pending'::text THEN 0
            ELSE 1
        END), (
        CASE
            WHEN needed_by IS NOT NULL AND needed_by < CURRENT_DATE THEN 0
            ELSE 1
        END), created_at;
create or replace view public.v_apex_entity_status as
 WITH counts AS (
         SELECT apex_raw.entity,
            count(*) AS rows_stored,
            max(apex_raw.fetched_at) AS newest_row
           FROM apex_raw
          GROUP BY apex_raw.entity
        ), lastrun AS (
         SELECT DISTINCT ON (apex_sync_run.entity) apex_sync_run.entity,
            apex_sync_run.status,
            apex_sync_run.started_at,
            apex_sync_run.rows_written,
            apex_sync_run.error
           FROM apex_sync_run
          ORDER BY apex_sync_run.entity, apex_sync_run.started_at DESC
        )
 SELECT e.entity,
    e.kind,
    e.endpoint,
    e.api_version,
    e.required,
    e.supports_delta,
    e.min_interval_minutes,
    w.last_success_at,
    w.consecutive_errors,
    COALESCE(c.rows_stored, 0::bigint) AS rows_stored,
    c.newest_row,
    r.status AS last_status,
    r.started_at AS last_attempt,
    r.rows_written AS last_rows,
    "left"(r.error, 300) AS last_error,
        CASE
            WHEN w.last_success_at IS NULL THEN true
            ELSE (EXTRACT(epoch FROM now() - w.last_success_at) / 60::numeric) >= e.min_interval_minutes::numeric
        END AS due,
        CASE
            WHEN w.last_success_at IS NULL THEN 'never pulled'::text
            ELSE GREATEST(0::numeric, e.min_interval_minutes::numeric - floor(EXTRACT(epoch FROM now() - w.last_success_at) / 60::numeric))::integer || ' min until due'::text
        END AS due_text
   FROM apex_entity e
     LEFT JOIN apex_watermark w ON w.entity = e.entity
     LEFT JOIN counts c ON c.entity = e.entity
     LEFT JOIN lastrun r ON r.entity = e.entity;
create or replace view public.v_auditor_heartbeat as
 SELECT c.checker_key,
    c.title,
    c.tier,
    c.runs_where,
    c.expected_interval,
    c.enabled,
    l.last_run,
        CASE
            WHEN l.last_run IS NULL THEN NULL::interval
            ELSE now() - l.last_run
        END AS since_last_run,
    c.fixture_proves_it_fails,
        CASE
            WHEN NOT c.enabled THEN 'DISABLED'::text
            WHEN l.last_run IS NULL THEN 'NEVER RUN'::text
            WHEN c.expected_interval IS NULL THEN 'ON DEMAND'::text
            WHEN (now() - l.last_run) > (c.expected_interval * 2::double precision) THEN 'DARK'::text
            WHEN (now() - l.last_run) > c.expected_interval THEN 'LATE'::text
            ELSE 'ALIVE'::text
        END AS heartbeat,
        CASE
            WHEN l.last_run IS NULL AND c.enabled THEN ('Registered, enabled, and has NEVER produced a verdict. A dark check is '::text || 'indistinguishable from a passing one. verification-suite sat active on a '::text) || 'twice-daily schedule and never fired once, and nothing noticed.'::text
            WHEN NOT c.fixture_proves_it_fails THEN ('Has run, but nobody has ever seen it FAIL on a deliberate fixture. Unproven '::text || 'checks can be vacuous -- the schema baseline gate printed PASS for a day '::text) || 'while production drifted 16 tables, because it only read a clock.'::text
            ELSE NULL::text
        END AS why_it_matters
   FROM checker_registry c
     LEFT JOIN ( SELECT conformance_ledger.checker_key,
            max(conformance_ledger.ran_at) AS last_run
           FROM conformance_ledger
          GROUP BY conformance_ledger.checker_key) l ON l.checker_key = c.checker_key;
create or replace view public.v_bridge_performance as
 WITH j AS (
         SELECT date_trunc('hour'::text, ai_bridge_jobs.created_at) AS hour,
            ai_bridge_jobs.status,
            ai_bridge_jobs.seconds,
            EXTRACT(epoch FROM ai_bridge_jobs.claimed_at - ai_bridge_jobs.created_at) AS waited_to_start
           FROM ai_bridge_jobs
          WHERE ai_bridge_jobs.created_at > (now() - '7 days'::interval)
        )
 SELECT hour,
    count(*) AS questions,
    count(*) FILTER (WHERE status = 'done'::text) AS answered,
    count(*) FILTER (WHERE status = 'error'::text) AS failed,
    count(*) FILTER (WHERE status = 'running'::text) AS still_running,
    round(avg(seconds) FILTER (WHERE status = 'done'::text))::integer AS avg_seconds,
    round(percentile_cont(0.50::double precision) WITHIN GROUP (ORDER BY (seconds::double precision)) FILTER (WHERE status = 'done'::text))::integer AS p50_seconds,
    round(percentile_cont(0.95::double precision) WITHIN GROUP (ORDER BY (seconds::double precision)) FILTER (WHERE status = 'done'::text))::integer AS p95_seconds,
    max(seconds) FILTER (WHERE status = 'done'::text) AS slowest_seconds,
    round(avg(waited_to_start))::integer AS avg_queue_wait_seconds
   FROM j
  GROUP BY hour
  ORDER BY hour DESC;
create or replace view public.v_bridge_status as
 SELECT machine,
    last_seen,
    version,
    (now() - last_seen) < '00:01:30'::interval AS online,
    round(EXTRACT(epoch FROM now() - last_seen))::integer AS seconds_since,
    (last_seen AT TIME ZONE 'America/New_York'::text) AS last_seen_et,
        CASE
            WHEN (now() - last_seen) < '00:01:30'::interval THEN 'Answering on '::text || machine
            WHEN (now() - last_seen) < '01:00:00'::interval THEN (('Stopped '::text || round(EXTRACT(epoch FROM now() - last_seen) / 60::numeric)) || ' minutes ago on '::text) || machine
            ELSE (('Last reported in '::text || to_char((last_seen AT TIME ZONE 'America/New_York'::text), 'DD Mon HH24:MI'::text)) || ' on '::text) || machine
        END AS verdict,
    ( SELECT count(*) AS count
           FROM ai_bridge_jobs j
          WHERE j.status = 'pending'::text) AS waiting,
    ( SELECT count(*) AS count
           FROM ai_bridge_jobs j
          WHERE j.status = 'running'::text) AS in_progress
   FROM ai_bridge_heartbeat h;
create or replace view public.v_business_rules as
 SELECT key,
    label,
    value,
    unit,
    what_it_means,
    where_it_came_from,
    set_by,
    updated_at::date AS set_on,
    ( SELECT count(*) AS count
           FROM information_schema.views v
          WHERE v.table_schema::name = 'public'::name AND pg_get_viewdef(quote_ident(v.table_name::text)::regclass::oid, true) ~~* (('%'::text || c.key) || '%'::text)) AS places_using_it,
        CASE
            WHEN set_by ~~ 'default%'::text THEN 'NOT YET SET BY ANYONE — this is a default. Every figure derived from it is an estimate.'::text
            ELSE ((('Set by '::text || set_by) || ' on '::text) || to_char(updated_at, 'DD Mon YYYY'::text)) || '.'::text
        END AS standing
   FROM conversion_factors c
  ORDER BY key;
create or replace view public.v_c3a_document_coverage as
 WITH pages AS (
         SELECT n.view_key,
            n.label,
            n.category,
            n.subcategory,
            n.table_ref
           FROM nav_registry n
          WHERE n.enabled AND n.table_ref IS NOT NULL
        ), cols AS (
         SELECT p.view_key,
            p.label,
            p.category,
            p.subcategory,
            p.table_ref,
            bool_or(c.column_name::name = ANY (ARRAY['package_tag'::name, 'tag'::name])) AS is_item_level,
            bool_or(c.column_name::name ~~* '%certificate%'::text OR c.column_name::name ~~* '%coa%'::text) AS has_certificate,
            bool_or(c.column_name::name ~~* '%manifest%'::text) AS has_manifest
           FROM pages p
             JOIN information_schema.columns c ON c.table_schema::name = 'public'::name AND c.table_name::name = p.table_ref
          GROUP BY p.view_key, p.label, p.category, p.subcategory, p.table_ref
        )
 SELECT view_key,
    label,
    category,
    subcategory,
    table_ref,
    has_certificate,
    has_manifest,
        CASE
            WHEN has_certificate AND has_manifest THEN 'COMPLIES'::text
            WHEN has_certificate THEN 'BREACH — certificate only, no manifest'::text
            WHEN has_manifest THEN 'BREACH — manifest only, no certificate'::text
            ELSE 'BREACH — neither document reachable from the row'::text
        END AS c3a,
        CASE
            WHEN has_certificate AND has_manifest THEN NULL::text
            ELSE ('C3a: an item row must carry both documents, openable from the row. '::text || 'Where one is absent the row states WHICH reason — never a blank, never a dash. '::text) || 'f_package_documents(tag) already returns both with a signed link; reuse it, do not rebuild it.'::text
        END AS what_to_do
   FROM cols
  WHERE is_item_level;
create or replace view public.v_catalogue_items as
 SELECT license AS licence,
    f_operation(license) AS operation,
    metrc_id,
    name AS item,
    category,
    unit_of_measure,
    strain,
    f_uom_label(unit_of_measure) AS unit_label,
    ( SELECT count(*) AS count
           FROM metrc_packages p
          WHERE p.license = i.license AND p.item_name = i.name) AS packages_using_it,
    synced_at,
    concat_ws(' '::text, name, COALESCE(category, ''::text), COALESCE(strain, ''::text), license, f_operation(license), raw ->> 'ProductCategoryType'::text, NULLIF(raw ->> 'Description'::text, ''::text), NULLIF(raw ->> 'ItemBrandName'::text, ''::text)) AS search_text,
    'M'::text || lpad(metrc_id::text, 11, '0'::text) AS item_number,
    regexp_replace(name, '^M\d+:\s*'::text, ''::text) AS item_name,
    raw ->> 'ProductCategoryType'::text AS item_type,
    raw ->> 'QuantityType'::text AS quantity_type,
    raw ->> 'DefaultLabTestingState'::text AS default_lab_testing_state,
    raw ->> 'ApprovalStatus'::text AS approval,
    NULLIF(raw ->> 'ApprovalStatusDateTime'::text, ''::text)::timestamp with time zone AS approval_date,
    NULLIF(raw ->> 'CreatedDateTime'::text, ''::text)::timestamp with time zone AS created_date,
    NULLIF(raw ->> 'ItemBrandName'::text, ''::text) AS item_brand_name,
    NULLIF(raw ->> 'IsUsed'::text, ''::text)::boolean AS in_use,
    NULLIF(raw ->> 'UnitThcPercent'::text, ''::text)::numeric AS unit_thc_percent,
    NULLIF(raw ->> 'UnitThcContent'::text, ''::text)::numeric AS unit_thc_content,
    NULLIF(raw ->> 'UnitThcContentUnitOfMeasureName'::text, ''::text) AS unit_thc_content_uom,
    NULLIF(raw ->> 'UnitThcContentDose'::text, ''::text)::numeric AS unit_thc_content_dose,
    NULLIF(raw ->> 'UnitThcAPercent'::text, ''::text)::numeric AS unit_thca_percent,
    NULLIF(raw ->> 'UnitThcAContent'::text, ''::text)::numeric AS unit_thca_content,
    NULLIF(raw ->> 'UnitCbdPercent'::text, ''::text)::numeric AS unit_cbd_percent,
    NULLIF(raw ->> 'UnitCbdContent'::text, ''::text)::numeric AS unit_cbd_content,
    NULLIF(raw ->> 'UnitCbdContentUnitOfMeasureName'::text, ''::text) AS unit_cbd_content_uom,
    NULLIF(raw ->> 'UnitCbdContentDose'::text, ''::text)::numeric AS unit_cbd_content_dose,
    NULLIF(raw ->> 'UnitCbdAPercent'::text, ''::text)::numeric AS unit_cbda_percent,
    NULLIF(raw ->> 'UnitCbdAContent'::text, ''::text)::numeric AS unit_cbda_content,
    NULLIF(raw ->> 'UnitVolume'::text, ''::text)::numeric AS unit_volume,
    NULLIF(raw ->> 'UnitVolumeUnitOfMeasureName'::text, ''::text) AS unit_volume_uom,
    NULLIF(raw ->> 'UnitWeight'::text, ''::text)::numeric AS unit_weight,
    NULLIF(raw ->> 'UnitWeightUnitOfMeasureName'::text, ''::text) AS unit_weight_uom,
    NULLIF(raw ->> 'UnitQuantity'::text, ''::text)::numeric AS unit_quantity,
    NULLIF(raw ->> 'UnitQuantityUnitOfMeasureName'::text, ''::text) AS unit_quantity_uom,
    NULLIF(raw ->> 'NumberOfDoses'::text, ''::text)::numeric AS number_of_doses,
    NULLIF(raw ->> 'ServingSize'::text, ''::text) AS serving_size,
    NULLIF(raw ->> 'IsExpirationDateRequired'::text, ''::text)::boolean AS expiration_date_required,
    NULLIF(raw ->> 'IsSellByDateRequired'::text, ''::text)::boolean AS sell_by_date_required,
    NULLIF(raw ->> 'IsUseByDateRequired'::text, ''::text)::boolean AS use_by_date_required,
    NULLIF(raw ->> 'HasExpirationDate'::text, ''::text)::boolean AS has_expiration_date,
    NULLIF(raw ->> 'HasSellByDate'::text, ''::text)::boolean AS has_sell_by_date,
    NULLIF(raw ->> 'HasUseByDate'::text, ''::text)::boolean AS has_use_by_date,
    NULLIF(raw ->> 'Description'::text, ''::text) AS description,
    NULLIF(raw ->> 'PublicIngredients'::text, ''::text) AS public_ingredients,
    NULLIF(raw ->> 'AdministrationMethod'::text, ''::text) AS administration_method,
    NULLIF(raw ->> 'Allergens'::text, ''::text) AS allergens,
    NULLIF(raw ->> 'ProcessingJobCategoryName'::text, ''::text) AS processing_job_category,
    NULLIF(raw ->> 'ProcessingJobTypeName'::text, ''::text) AS processing_job_type,
    NULLIF(raw ->> 'LabTestBatchNames'::text, ''::text) AS lab_test_batch_names,
    NULLIF(raw ->> 'StrainId'::text, ''::text)::bigint AS strain_metrc_id,
        CASE
            WHEN jsonb_typeof(raw -> 'ProductImages'::text) = 'array'::text THEN jsonb_array_length(raw -> 'ProductImages'::text)
            ELSE 0
        END AS product_images,
        CASE
            WHEN jsonb_typeof(raw -> 'LabelImages'::text) = 'array'::text THEN jsonb_array_length(raw -> 'LabelImages'::text)
            ELSE 0
        END AS label_images,
        CASE
            WHEN jsonb_typeof(raw -> 'PackagingImages'::text) = 'array'::text THEN jsonb_array_length(raw -> 'PackagingImages'::text)
            ELSE 0
        END AS packaging_images
   FROM metrc_items i;
create or replace view public.v_catalogue_locations as
 SELECT license AS licence,
    f_operation(license) AS operation,
    metrc_id,
    name AS location,
    location_type,
    ( SELECT count(*) AS count
           FROM metrc_packages p
          WHERE p.license = l.license AND p.location = l.name) AS packages_here,
    ( SELECT count(*) AS count
           FROM metrc_plants p
          WHERE p.license = l.license AND p.room = l.name) AS plants_here,
    synced_at,
    concat_ws(' '::text, name, COALESCE(location_type, ''::text), license, f_operation(license)) AS search_text,
    NULLIF(raw ->> 'LocationTypeId'::text, ''::text)::bigint AS location_type_metrc_id,
    NULLIF(raw ->> 'ForPlantBatches'::text, ''::text)::boolean AS can_hold_plant_batches,
    NULLIF(raw ->> 'ForPlants'::text, ''::text)::boolean AS can_hold_plants,
    NULLIF(raw ->> 'ForHarvests'::text, ''::text)::boolean AS can_hold_harvests,
    NULLIF(raw ->> 'ForPackages'::text, ''::text)::boolean AS can_hold_packages
   FROM metrc_locations l;
create or replace view public.v_catalogue_strains as
 SELECT license AS licence,
    f_operation(license) AS operation,
    metrc_id,
    name AS strain,
    testing_status,
    thc_level,
    cbd_level,
    ( SELECT count(*) AS count
           FROM metrc_items i
          WHERE i.license = s.license AND i.strain = s.name) AS items_using_it,
    ( SELECT count(*) AS count
           FROM metrc_plants p
          WHERE p.license = s.license AND p.strain = s.name) AS plants,
    synced_at,
    concat_ws(' '::text, name, license, f_operation(license), NULLIF(raw ->> 'Genetics'::text, ''::text)) AS search_text,
    NULLIF(raw ->> 'Genetics'::text, ''::text) AS genetics,
    NULLIF(raw ->> 'IndicaPercentage'::text, ''::text)::numeric AS indica_percent,
    NULLIF(raw ->> 'SativaPercentage'::text, ''::text)::numeric AS sativa_percent,
    NULLIF(raw ->> 'IsUsed'::text, ''::text)::boolean AS in_use
   FROM metrc_strains s;
create or replace view public.v_ceo_recommendations as
 SELECT severity,
    agent,
    headline,
    detail,
    scope,
    COALESCE(dollars, 0::numeric) AS dollars_at_stake,
    action AS recommended_action,
    drill_to,
    detected_at
   FROM agent_findings
  WHERE resolved_at IS NULL
  ORDER BY (COALESCE(dollars, 0::numeric)) DESC, (
        CASE severity
            WHEN 'critical'::text THEN 0
            WHEN 'elevated'::text THEN 1
            ELSE 2
        END), detected_at DESC;
create or replace view public.v_certificate_disagreement as
 WITH RECURSIVE edges AS (
         SELECT DISTINCT ON (p.tag) p.tag,
            p.raw ->> 'SourcePackageLabels'::text AS srcs
           FROM metrc_packages p
          ORDER BY p.tag, p.license
        ), walk AS (
         SELECT e.tag AS package_tag,
            e.tag AS ancestor,
            0 AS depth,
            e.srcs
           FROM edges e
        UNION
         SELECT w.package_tag,
            s.tag,
            w.depth + 1,
            s.srcs
           FROM walk w
             JOIN LATERAL ( SELECT TRIM(BOTH FROM x.x) AS lbl
                   FROM unnest(string_to_array(COALESCE(w.srcs, ''::text), ','::text)) x(x)
                  WHERE TRIM(BOTH FROM x.x) <> ''::text) l ON true
             JOIN edges s ON s.tag = l.lbl
          WHERE w.depth < 6
        ), cert AS (
         SELECT coa_extract.package_tag,
            max(coa_extract.client_license) AS lic,
            max(coa_extract.client_name) AS nm
           FROM coa_extract
          WHERE coa_extract.package_tag IS NOT NULL AND coa_extract.client_license IS NOT NULL
          GROUP BY coa_extract.package_tag
        UNION
         SELECT l.package_tag,
            max(e.client_license) AS max,
            max(e.client_name) AS max
           FROM metrc_lab_results l
             JOIN coa_extract e ON e.document_id = l.document_file_id
          WHERE l.document_file_id IS NOT NULL AND l.package_tag IS NOT NULL AND e.client_license IS NOT NULL
          GROUP BY l.package_tag
        ), all_certs AS (
         SELECT w.package_tag,
            w.depth,
            w.ancestor,
            c.lic,
            c.nm
           FROM walk w
             JOIN cert c ON c.package_tag = w.ancestor
        )
 SELECT package_tag,
    count(DISTINCT lic) AS distinct_clients,
    min(depth) FILTER (WHERE f_any_ours(lic)) AS nearest_ours_depth,
    min(depth) FILTER (WHERE NOT f_any_ours(lic)) AS nearest_outside_depth,
    string_agg(DISTINCT ((((nm || ' ('::text) || lic) || ' @ depth '::text) || depth) || ')'::text, ' | '::text ORDER BY (((((nm || ' ('::text) || lic) || ' @ depth '::text) || depth) || ')'::text)) AS certificates,
    bool_or(f_any_ours(lic)) AS some_say_ours,
    bool_or(NOT f_any_ours(lic)) AS some_say_outside,
    'THE ISSUE: certificates in this package''s lineage name DIFFERENT clients. Depth is a tie-break, not a reason. A near certificate says who tested THIS package - often us, on material we bought. A deep one is closer to who grew it. Neither is automatically right.'::text AS what_is_wrong,
    'Read both certificates before recording ownership. Report both figures; never average and never let the ordering decide.'::text AS what_to_do
   FROM all_certs a
  GROUP BY package_tag
 HAVING count(DISTINCT lic) > 1;
create or replace view public.v_certificate_resolved as
 WITH RECURSIVE edges AS (
         SELECT DISTINCT ON (p.tag) p.tag,
            p.raw ->> 'SourcePackageLabels'::text AS srcs
           FROM metrc_packages p
          ORDER BY p.tag, p.license
        ), walk AS (
         SELECT e.tag AS package_tag,
            e.tag AS ancestor,
            0 AS depth,
            e.srcs
           FROM edges e
        UNION
         SELECT w.package_tag,
            s.tag,
            w.depth + 1,
            s.srcs
           FROM walk w
             JOIN LATERAL ( SELECT TRIM(BOTH FROM x.x) AS lbl
                   FROM unnest(string_to_array(COALESCE(w.srcs, ''::text), ','::text)) x(x)
                  WHERE TRIM(BOTH FROM x.x) <> ''::text) l ON true
             JOIN edges s ON s.tag = l.lbl
          WHERE w.depth < 6
        ), cert AS (
         SELECT coa_extract.package_tag,
            max(coa_extract.client_license) AS lic,
            max(coa_extract.client_name) AS nm,
            max(coa_extract.lab_report_id) AS rpt,
            count(*) AS n
           FROM coa_extract
          WHERE coa_extract.package_tag IS NOT NULL
          GROUP BY coa_extract.package_tag
        UNION ALL
         SELECT l.package_tag,
            max(e.client_license) AS max,
            max(e.client_name) AS max,
            max(e.lab_report_id) AS max,
            count(*) AS count
           FROM metrc_lab_results l
             JOIN coa_extract e ON e.document_id = l.document_file_id
          WHERE l.document_file_id IS NOT NULL AND l.package_tag IS NOT NULL
          GROUP BY l.package_tag
        ), cert1 AS (
         SELECT cert.package_tag,
            max(cert.lic) AS lic,
            max(cert.nm) AS nm,
            max(cert.rpt) AS rpt,
            sum(cert.n) AS n
           FROM cert
          GROUP BY cert.package_tag
        ), hit AS (
         SELECT w.package_tag,
            w.depth,
            c.lic,
            c.nm,
            c.rpt,
            w.ancestor,
            row_number() OVER (PARTITION BY w.package_tag ORDER BY w.depth) AS rn
           FROM walk w
             JOIN cert1 c ON c.package_tag = w.ancestor
        )
 SELECT package_tag,
    depth AS found_at_depth,
    ancestor AS certificate_on_package,
    lic AS cert_license,
    nm AS cert_client,
    rpt AS cert_report,
        CASE
            WHEN depth = 0 THEN 'DIRECT'::text
            ELSE (('INHERITED via '::text || depth) || ' repack'::text) ||
            CASE
                WHEN depth > 1 THEN 's'::text
                ELSE ''::text
            END
        END AS certificate_link
   FROM hit h
  WHERE rn = 1;
create or replace view public.v_check_trust as
 SELECT COALESCE(d.check_key, c.checker_key) AS check_key,
    c.title,
    c.enabled,
    COALESCE(c.fixture_proves_it_fails, false) AS proven_it_can_fail,
    count(d.id) FILTER (WHERE d.fixed_at IS NULL) AS open_defects,
    count(d.id) FILTER (WHERE d.fixed_at IS NOT NULL) AS fixed_defects,
    max(d.found_at) FILTER (WHERE d.fixed_at IS NULL) AS newest_open_defect,
        CASE
            WHEN count(d.id) FILTER (WHERE d.fixed_at IS NULL) > 0 THEN 'UNTRUSTED - known defect, read its output with the defect in hand'::text
            WHEN NOT COALESCE(c.fixture_proves_it_fails, false) THEN 'UNPROVEN - nobody has ever watched this check fail, so nobody knows it can'::text
            ELSE 'trusted'::text
        END AS trust
   FROM checker_registry c
     FULL JOIN check_defect d ON d.check_key = c.checker_key
  GROUP BY (COALESCE(d.check_key, c.checker_key)), c.title, c.enabled, c.fixture_proves_it_fails;
create or replace view public.v_checks_missing_in_flight as
 SELECT check_key,
    title,
    severity,
    tolerance_pct,
    measures_a_process,
    settles_within,
        CASE
            WHEN measures_a_process AND settles_within IS NULL THEN 'PROCESS CHECK WITH NO SETTLING PERIOD - counts in-flight work as failed'::text
            WHEN measures_a_process AND tolerance_pct = 0::numeric AND settles_within IS NULL THEN 'ZERO TOLERANCE on a metric that cannot reach zero while anything is in flight'::text
            ELSE 'declared'::text
        END AS state,
    in_flight_rule
   FROM verification_checks
  WHERE measures_a_process
  ORDER BY (settles_within IS NULL) DESC, check_key;
create or replace view public.v_coa_document_kind as
 SELECT document_id,
    package_tag,
    characters,
        CASE
            WHEN total_thc IS NOT NULL THEN 'potency - read'::text
            WHEN total_cbd IS NOT NULL OR total_terpenes IS NOT NULL OR total_cannabinoids IS NOT NULL THEN 'potency - partly read'::text
            WHEN microbiology IS NOT NULL OR mycotoxins IS NOT NULL OR heavy_metals IS NOT NULL OR pesticides IS NOT NULL OR solvents IS NOT NULL OR pathogens IS NOT NULL OR water_activity IS NOT NULL THEN 'safety screen - no potency expected'::text
            WHEN COALESCE(characters, 0) = 0 THEN 'no text extracted'::text
            ELSE 'unclassified - needs a person'::text
        END AS document_kind,
    total_thc,
    parse_error
   FROM coa_extract c;
create or replace view public.v_coa_register as
 SELECT license,
    package_tag,
    item_name,
    quantity,
    uom,
    location,
    lab_testing_state,
    packaged_on,
    source_harvest,
    tests_recorded,
    tests_failed,
    thc_result,
    cbd_result,
    tested_on,
    laboratory,
    coa_link,
    coa_status,
    source_state,
    f_stock_status(source_state, NULL::boolean) AS stock_status
   FROM ( SELECT p.license,
            p.tag AS package_tag,
            p.item_name,
            p.quantity,
            p.uom,
            p.location,
            p.lab_testing_state,
            p.packaged_on,
            NULLIF(p.raw ->> 'SourceHarvestNames'::text, ''::text) AS source_harvest,
            ( SELECT count(*) AS count
                   FROM metrc_lab_results r
                  WHERE r.package_tag = p.tag) AS tests_recorded,
            ( SELECT count(*) AS count
                   FROM metrc_lab_results r
                  WHERE r.package_tag = p.tag AND r.passed IS FALSE) AS tests_failed,
            ( SELECT round(max(r.result), 2) AS round
                   FROM metrc_lab_results r
                  WHERE r.package_tag = p.tag AND COALESCE(r.test_name, r.test_type) ~~* '%THC%'::text) AS thc_result,
            ( SELECT round(max(r.result), 2) AS round
                   FROM metrc_lab_results r
                  WHERE r.package_tag = p.tag AND COALESCE(r.test_name, r.test_type) ~~* '%CBD%'::text) AS cbd_result,
            ( SELECT max(r.result_date) AS max
                   FROM metrc_lab_results r
                  WHERE r.package_tag = p.tag) AS tested_on,
            ( SELECT string_agg(DISTINCT r.lab_facility, ', '::text) AS string_agg
                   FROM metrc_lab_results r
                  WHERE r.package_tag = p.tag) AS laboratory,
            ( SELECT max(r.coa_link) AS max
                   FROM metrc_lab_results r
                  WHERE r.package_tag = p.tag) AS coa_link,
                CASE
                    WHEN p.lab_testing_state = 'TestPassed'::text THEN 'Passed - sellable'::text
                    WHEN p.lab_testing_state = 'TestFailed'::text THEN 'FAILED - do not sell'::text
                    WHEN p.lab_testing_state = ANY (ARRAY['SubmittedForTesting'::text, 'AwaitingConfirmation'::text, 'TestingInProgress'::text]) THEN 'Awaiting result'::text
                    WHEN (( SELECT count(*) AS count
                       FROM metrc_lab_results r
                      WHERE r.package_tag = p.tag)) = 0 THEN 'No Certificate of Analysis on file'::text
                    ELSE COALESCE(p.lab_testing_state, 'Not submitted'::text)
                END AS coa_status,
            p.source_state
           FROM metrc_packages p
          WHERE p.source_state = ANY (ARRAY['active'::text, 'onhold'::text, 'intransit'::text])
          ORDER BY p.packaged_on DESC NULLS LAST) q;
create or replace view public.v_coa_unparsed as
 SELECT metrc_id,
    storage_path,
    package_tag
   FROM metrc_documents d
  WHERE doc_type = 'coa'::text AND storage_path IS NOT NULL AND NOT (EXISTS ( SELECT 1
           FROM coa_extract e
          WHERE e.document_id = d.metrc_id AND e.client_parsed_at IS NOT NULL))
  ORDER BY metrc_id;
create or replace view public.v_conformance_coverage as
 WITH subjects AS (
         SELECT 'table'::text AS subject_kind,
            c_1.relname AS subject_ref
           FROM pg_class c_1
             JOIN pg_namespace n ON n.oid = c_1.relnamespace
          WHERE n.nspname = 'public'::name AND c_1.relkind = 'r'::"char"
        UNION ALL
         SELECT 'view'::text,
            c_1.relname
           FROM pg_class c_1
             JOIN pg_namespace n ON n.oid = c_1.relnamespace
          WHERE n.nspname = 'public'::name AND (c_1.relkind = ANY (ARRAY['v'::"char", 'm'::"char"]))
        UNION ALL
         SELECT 'metric'::text,
            metric_registry.metric_key
           FROM metric_registry
          WHERE metric_registry.active
        UNION ALL
         SELECT 'policy'::text,
            policy_registry.policy_key
           FROM policy_registry
          WHERE policy_registry.active
        ), checked AS (
         SELECT conformance_ledger.subject_kind,
            conformance_ledger.subject_ref,
            max(conformance_ledger.ran_at) AS last_verdict_at,
            count(*) AS verdicts,
            count(*) FILTER (WHERE conformance_ledger.verdict = ANY (ARRAY['FAIL'::text, 'DISAGREE'::text])) AS open_problems
           FROM conformance_ledger
          GROUP BY conformance_ledger.subject_kind, conformance_ledger.subject_ref
        )
 SELECT s.subject_kind,
    s.subject_ref,
    COALESCE(c.verdicts, 0::bigint) AS verdicts,
    c.last_verdict_at,
    COALESCE(c.open_problems, 0::bigint) AS open_problems,
        CASE
            WHEN c.subject_ref IS NULL THEN 'NEVER CHECKED'::text
            ELSE 'covered'::text
        END AS coverage
   FROM subjects s
     LEFT JOIN checked c ON c.subject_kind = s.subject_kind AND c.subject_ref = s.subject_ref;
create or replace view public.v_control_tower as
 SELECT 'late_or_at_risk_orders'::text AS metric,
    count(*)::numeric AS value
   FROM sales_orders
  WHERE (sales_orders.status = ANY (ARRAY['open'::text, 'confirmed'::text])) AND sales_orders.promised_ship_on < CURRENT_DATE
UNION ALL
 SELECT 'unconfirmed_open_orders'::text AS metric,
    count(*) AS value
   FROM sales_orders
  WHERE sales_orders.status = 'open'::text
UNION ALL
 SELECT 'testing_overdue'::text AS metric,
    count(*) AS value
   FROM test_requests
  WHERE (test_requests.status = ANY (ARRAY['planned'::test_status, 'submitted'::test_status, 'at_lab'::test_status])) AND test_requests.submit_due_on < CURRENT_DATE
UNION ALL
 SELECT 'lots_rts_missing_coa'::text AS metric,
    count(*) AS value
   FROM lots
  WHERE lots.status = 'ready_to_ship'::lot_status AND lots.coa_id IS NULL
UNION ALL
 SELECT 'lots_expired_sellable'::text AS metric,
    count(*) AS value
   FROM lots
  WHERE lots.expires_on < CURRENT_DATE AND (lots.status = ANY (ARRAY['ready_to_ship'::lot_status, 'packaging'::lot_status, 'packaging_queue'::lot_status]))
UNION ALL
 SELECT 'pending_allocations'::text AS metric,
    count(*) AS value
   FROM allocations
  WHERE allocations.approval = 'pending'::approval_status
UNION ALL
 SELECT 'blocked_work_orders'::text AS metric,
    count(*) AS value
   FROM work_orders w
  WHERE (w.status = ANY (ARRAY['ready'::wo_status, 'released'::wo_status])) AND NOT (EXISTS ( SELECT 1
           FROM allocations a
          WHERE a.work_order_id = w.id AND a.release = 'released'::release_status))
UNION ALL
 SELECT 'harvest_mass_balance_exceptions'::text AS metric,
    count(*) AS value
   FROM harvest_grades
  WHERE harvest_grades.dry_input_g > 0::numeric AND abs(harvest_grades.variance_g) > 0.01
UNION ALL
 SELECT 'licenses_expiring_60d'::text AS metric,
    count(*) AS value
   FROM licenses
  WHERE licenses.status = 'active'::text AND licenses.expires_on <= (CURRENT_DATE + 60)
UNION ALL
 SELECT 'open_p0_actions'::text AS metric,
    count(*) AS value
   FROM actions_register
  WHERE actions_register.priority = 'P0'::text AND actions_register.status <> 'complete'::text
UNION ALL
 SELECT 'metrc_reconciliation_open'::text AS metric,
    count(*) AS value
   FROM reconciliation_exceptions
  WHERE reconciliation_exceptions.status = 'open'::text
UNION ALL
 SELECT 'days_since_cash_update'::text AS metric,
    COALESCE(EXTRACT(day FROM now() - (( SELECT max(cash_snapshots.as_of)::timestamp with time zone AS max
           FROM cash_snapshots))), 999::numeric) AS value;
create or replace view public.v_cost_of_goods as
 WITH i AS (
         SELECT cost_inputs.key,
            cost_inputs.value
           FROM cost_inputs
        ), v AS (
         SELECT ( SELECT i.value
                   FROM i
                  WHERE i.key = 'run_size_g'::text) AS run_g,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'trim_cost_per_lb'::text) AS trim_lb,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'extraction_labor'::text) AS ext_lab,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'solvent_cost'::text) AS solvent,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'proc_labor_badder'::text) AS lab_badder,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'proc_labor_diamonds'::text) AS lab_diamond,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'crude_yield_pct'::text) AS crude_pct,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'diamond_yield_pct'::text) AS dia_pct,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'liquid_diamond_factor'::text) AS ld_f,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'ld_extra_cost'::text) AS ld_extra,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'badder_packaging'::text) AS b_pack,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'badder_fill_1g'::text) AS b_fill1,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'badder_fill_35g'::text) AS b_fill35,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'badder_package'::text) AS b_lab,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'badder_rd_test'::text) AS b_rd,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'badder_compliance'::text) AS b_comp,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'vape_terp_05'::text) AS t05,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'vape_terp_10'::text) AS t10,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'vape_hardware'::text) AS v_hw,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'vape_packaging'::text) AS v_pack,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'vape_fill'::text) AS v_fill,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'vape_package'::text) AS v_lab,
            ( SELECT i.value
                   FROM i
                  WHERE i.key = 'vape_compliance'::text) AS v_comp
        ), calc AS (
         SELECT v.run_g,
            v.trim_lb,
            v.ext_lab,
            v.solvent,
            v.lab_badder,
            v.lab_diamond,
            v.crude_pct,
            v.dia_pct,
            v.ld_f,
            v.ld_extra,
            v.b_pack,
            v.b_fill1,
            v.b_fill35,
            v.b_lab,
            v.b_rd,
            v.b_comp,
            v.t05,
            v.t10,
            v.v_hw,
            v.v_pack,
            v.v_fill,
            v.v_lab,
            v.v_comp,
            v.trim_lb / 454::numeric AS trim_g,
            v.run_g * (v.trim_lb / 454::numeric) AS batch_cost,
            v.crude_pct * v.run_g AS crude_g
           FROM v
        ), c2 AS (
         SELECT calc.run_g,
            calc.trim_lb,
            calc.ext_lab,
            calc.solvent,
            calc.lab_badder,
            calc.lab_diamond,
            calc.crude_pct,
            calc.dia_pct,
            calc.ld_f,
            calc.ld_extra,
            calc.b_pack,
            calc.b_fill1,
            calc.b_fill35,
            calc.b_lab,
            calc.b_rd,
            calc.b_comp,
            calc.t05,
            calc.t10,
            calc.v_hw,
            calc.v_pack,
            calc.v_fill,
            calc.v_lab,
            calc.v_comp,
            calc.trim_g,
            calc.batch_cost,
            calc.crude_g,
            (calc.batch_cost + calc.ext_lab + calc.solvent) / NULLIF(calc.crude_g, 0::numeric) AS crude_cost_g,
            calc.crude_g * calc.dia_pct AS diamond_g,
            calc.crude_g * (1::numeric - calc.dia_pct) AS rem_crude_g
           FROM calc
        ), c3 AS (
         SELECT c2.run_g,
            c2.trim_lb,
            c2.ext_lab,
            c2.solvent,
            c2.lab_badder,
            c2.lab_diamond,
            c2.crude_pct,
            c2.dia_pct,
            c2.ld_f,
            c2.ld_extra,
            c2.b_pack,
            c2.b_fill1,
            c2.b_fill35,
            c2.b_lab,
            c2.b_rd,
            c2.b_comp,
            c2.t05,
            c2.t10,
            c2.v_hw,
            c2.v_pack,
            c2.v_fill,
            c2.v_lab,
            c2.v_comp,
            c2.trim_g,
            c2.batch_cost,
            c2.crude_g,
            c2.crude_cost_g,
            c2.diamond_g,
            c2.rem_crude_g,
            (c2.diamond_g * c2.crude_cost_g + c2.lab_diamond) / NULLIF(c2.diamond_g, 0::numeric) AS diamond_per_g,
            (c2.diamond_g * c2.crude_cost_g + c2.lab_diamond + c2.ld_extra) / NULLIF(c2.diamond_g * c2.ld_f, 0::numeric) AS ld_per_g,
            (c2.rem_crude_g * c2.crude_cost_g + c2.lab_badder) / NULLIF(c2.rem_crude_g, 0::numeric) AS crude_per_g
           FROM c2
        )
 SELECT round(crude_cost_g, 4) AS crude_cost_per_gram,
    round(crude_per_g, 4) AS badder_crude_per_gram,
    round(crude_per_g * 454::numeric) AS badder_crude_per_pound,
    round(diamond_per_g, 4) AS diamond_per_gram,
    round(ld_per_g, 4) AS liquid_diamond_per_gram,
    round(ld_per_g * 454::numeric) AS liquid_diamond_per_pound,
    round(crude_per_g * 1::numeric + b_pack + b_fill1 + b_lab + b_rd + b_comp, 2) AS badder_1g_unit_cost,
    round(crude_per_g * 3.5 + b_pack + b_fill35 + b_lab + b_rd + b_comp, 2) AS badder_35g_unit_cost,
    round(ld_per_g / 2::numeric + t05 + v_hw + v_pack + v_fill + v_lab + v_comp, 2) AS vape_05g_unit_cost,
    round(ld_per_g + t10 + v_hw + v_pack + v_fill + v_lab + v_comp, 2) AS vape_10g_unit_cost,
    round(batch_cost, 2) AS batch_cost,
    round(crude_g, 1) AS crude_grams_per_batch,
    'Every figure recomputes from the Production Cost Calculator inputs. Change a cost there and '::text || 'these change, and so does the value of every package of this type on the platform.'::text AS note
   FROM c3;
create or replace view public.v_countable_inventory as
 SELECT tag AS package_tag,
    "left"(item_name, 55) AS item_name,
    license,
    uom AS unit_of_measure,
    quantity AS units,
    f_quantity_text(quantity, uom) AS how_much,
    source_state,
    raw ->> 'LocationName'::text AS location,
    raw ->> 'ItemFromFacilityName'::text AS item_defined_by,
    f_is_weight(uom) AS is_weight_based,
    'THE ISSUE: this item is counted, not weighed. Any figure built on pounds alone excludes it entirely and the total will be wrong without saying so.'::text AS what_is_wrong,
    'Report units and pounds SEPARATELY, or use f_quantity_text(). Never publish a row with no quantity on it, and never add units to pounds.'::text AS what_to_do
   FROM ( SELECT DISTINCT ON (metrc_packages.tag) metrc_packages.tag,
            metrc_packages.item_name,
            metrc_packages.license,
            metrc_packages.uom,
            metrc_packages.quantity,
            metrc_packages.source_state,
            metrc_packages.raw
           FROM metrc_packages
          ORDER BY metrc_packages.tag, metrc_packages.license) p
  WHERE NOT f_is_weight(uom) AND (source_state = ANY (ARRAY['active'::text, 'onhold'::text])) AND COALESCE(quantity, 0::numeric) > 0::numeric;
create or replace view public.v_cron_health as
 WITH hist AS (
         SELECT round(EXTRACT(epoch FROM now() - min(job_run_details.start_time)) / 3600.0, 1) AS log_hours
           FROM cron.job_run_details
        ), born AS (
         SELECT j_1.jobid,
            ( SELECT to_timestamp(min(m.version), 'YYYYMMDDHH24MISS'::text) AS to_timestamp
                   FROM supabase_migrations.schema_migrations m
                  WHERE m.statements::text ~~ (('%'::text || j_1.jobname) || '%'::text) AND m.statements::text ~~* '%cron.schedule%'::text) AS created_at
           FROM cron.job j_1
        ), runs AS (
         SELECT j_1.jobid,
            j_1.jobname,
            j_1.schedule,
            j_1.active,
            count(d.runid) FILTER (WHERE d.start_time > (now() - '24:00:00'::interval)) AS runs_24h,
            count(d.runid) FILTER (WHERE d.start_time > (now() - '24:00:00'::interval) AND d.status <> 'succeeded'::text) AS failed_24h,
            count(d.runid) AS runs_ever,
            max(d.start_time) AS last_start,
            max(d.start_time) FILTER (WHERE d.status = 'succeeded'::text) AS last_success,
            (array_agg(d.return_message ORDER BY d.start_time DESC) FILTER (WHERE d.status <> 'succeeded'::text))[1] AS last_error
           FROM cron.job j_1
             LEFT JOIN cron.job_run_details d ON d.jobid = j_1.jobid
          GROUP BY j_1.jobid, j_1.jobname, j_1.schedule, j_1.active
        ), j AS (
         SELECT r.jobid,
            r.jobname,
            r.schedule,
            r.active,
            r.runs_24h,
            r.failed_24h,
            r.runs_ever,
            r.last_start,
            r.last_success,
            r.last_error,
            b.created_at,
            round(EXTRACT(epoch FROM now() - b.created_at) / 3600.0, 1) AS age_hours
           FROM runs r
             LEFT JOIN born b ON b.jobid = r.jobid
        )
 SELECT j.jobname,
    j.schedule,
    j.active,
    j.runs_24h,
    j.failed_24h,
        CASE
            WHEN j.runs_24h = 0 THEN NULL::numeric
            ELSE round(100.0 * j.failed_24h::numeric / j.runs_24h::numeric, 1)
        END AS failure_pct_24h,
    (j.last_start AT TIME ZONE 'America/New_York'::text) AS last_run_et,
    (j.last_success AT TIME ZONE 'America/New_York'::text) AS last_success_et,
        CASE
            WHEN j.last_success IS NULL THEN NULL::numeric
            ELSE round(EXTRACT(epoch FROM now() - j.last_success) / 3600.0, 1)
        END AS hours_since_success,
        CASE
            WHEN NOT j.active THEN 'TURNED OFF'::text
            WHEN j.runs_ever = 0 AND j.age_hours IS NOT NULL AND j.age_hours < 24::numeric AND j.schedule !~ '^\*/'::text THEN ('TOO NEW TO JUDGE — created '::text || j.age_hours) || ' hours ago and has not come round yet. First run is still ahead of it.'::text
            WHEN j.runs_ever = 0 AND j.schedule ~ '\* \* [0-7]$'::text THEN ('NOT DUE YET — runs weekly, and no run of it falls inside the '::text || h.log_hours) || ' hours of history held'::text
            WHEN j.runs_ever = 0 AND j.schedule ~ '^\*/'::text THEN ('NEVER RUN — it repeats through the day, so it has had many chances in the '::text || h.log_hours) || ' hours of history held. Nothing is purging the log.'::text
            WHEN j.runs_ever = 0 AND h.log_hours >= 48::numeric THEN ((('NEVER RUN — daily, scheduled since '::text || COALESCE(to_char(j.created_at, 'DD Mon'::text), 'a date nobody recorded'::text)) || ', and at least two of its times fall inside the '::text) || h.log_hours) || ' hours of history held'::text
            WHEN j.runs_ever = 0 THEN ('NEVER RUN — but the log only covers '::text || h.log_hours) || ' hours, so it may simply not have come round yet'::text
            WHEN j.last_success IS NULL THEN 'NEVER SUCCEEDED — every attempt has failed'::text
            WHEN j.failed_24h = 0 THEN 'HEALTHY'::text
            WHEN j.failed_24h = j.runs_24h THEN 'FAILING EVERY RUN'::text
            ELSE ((('FAILING INTERMITTENTLY — '::text || j.failed_24h) || ' of '::text) || j.runs_24h) || ' runs in 24h'::text
        END AS verdict,
        CASE
            WHEN NOT j.active THEN 6
            WHEN j.last_success IS NULL AND j.last_start IS NOT NULL THEN 1
            WHEN j.failed_24h = j.runs_24h AND j.runs_24h > 0 THEN 1
            WHEN j.runs_ever = 0 AND j.age_hours IS NOT NULL AND j.age_hours < 24::numeric AND j.schedule !~ '^\*/'::text THEN 5
            WHEN j.runs_ever = 0 AND j.schedule ~ '\* \* [0-7]$'::text THEN 5
            WHEN j.runs_ever = 0 AND (j.schedule ~ '^\*/'::text OR h.log_hours >= 48::numeric) THEN 2
            WHEN j.runs_ever = 0 THEN 4
            WHEN j.failed_24h > 0 THEN 3
            ELSE 5
        END AS rank,
    "left"(COALESCE(j.last_error, ''::text), 300) AS last_error,
    h.log_hours AS log_covers_hours,
    (j.created_at AT TIME ZONE 'America/New_York'::text) AS scheduled_since_et
   FROM j
     CROSS JOIN hist h;
create or replace view public.v_cross_source_reconciliation as
 WITH revenue AS (
         SELECT 'Wholesale revenue'::text AS fact,
            'dollars'::text AS unit,
            'metrc_rpt_wholesale.amount'::text AS source_a,
            'metrc_rpt_package_transfers.shipper_wholesale_price'::text AS source_b,
            ( SELECT round(sum(w.amount)) AS round
                   FROM metrc_rpt_wholesale w
                  WHERE NOT COALESCE(w.voided, false) AND (w.manifest_number IN ( SELECT metrc_rpt_package_transfers.manifest_number
                           FROM metrc_rpt_package_transfers))) AS overlap_a,
            ( SELECT round(sum(t.shipper_wholesale_price)) AS round
                   FROM metrc_rpt_package_transfers t
                  WHERE (t.manifest_number IN ( SELECT w2.manifest_number
                           FROM metrc_rpt_wholesale w2
                          WHERE NOT COALESCE(w2.voided, false)))) AS overlap_b,
            ( SELECT count(*) AS count
                   FROM ( SELECT metrc_rpt_wholesale.manifest_number
                           FROM metrc_rpt_wholesale
                        EXCEPT
                         SELECT metrc_rpt_package_transfers.manifest_number
                           FROM metrc_rpt_package_transfers) x) AS only_in_a,
            ( SELECT count(*) AS count
                   FROM ( SELECT metrc_rpt_package_transfers.manifest_number
                           FROM metrc_rpt_package_transfers
                        EXCEPT
                         SELECT metrc_rpt_wholesale.manifest_number
                           FROM metrc_rpt_wholesale) y) AS only_in_b,
            ( SELECT round(sum(w.amount)) AS round
                   FROM metrc_rpt_wholesale w
                  WHERE NOT COALESCE(w.voided, false) AND NOT (w.manifest_number IN ( SELECT metrc_rpt_package_transfers.manifest_number
                           FROM metrc_rpt_package_transfers))) AS value_not_covered
        ), harvest_wet AS (
         SELECT 'Harvest wet weight'::text AS "?column?",
            'lb'::text AS "?column?",
            'metrc_harvests.wet_weight (grams, API)'::text AS "?column?",
            'metrc_rpt_harvests.wet_lb (pounds, report)'::text AS "?column?",
            round((( SELECT sum(metrc_harvests.wet_weight) AS sum
                   FROM metrc_harvests)) / 453.592, 1) AS round,
            round(( SELECT sum(metrc_rpt_harvests.wet_lb) AS sum
                   FROM metrc_rpt_harvests), 1) AS round,
            ( SELECT count(*) AS count
                   FROM ( SELECT metrc_harvests.name
                           FROM metrc_harvests
                        EXCEPT
                         SELECT metrc_rpt_harvests.harvest_name
                           FROM metrc_rpt_harvests) x) AS count,
            ( SELECT count(*) AS count
                   FROM ( SELECT metrc_rpt_harvests.harvest_name
                           FROM metrc_rpt_harvests
                        EXCEPT
                         SELECT metrc_harvests.name
                           FROM metrc_harvests) y) AS count,
            NULL::numeric AS "numeric"
        ), harvest_pkgs AS (
         SELECT 'Harvest package count'::text AS "?column?",
            'packages'::text AS "?column?",
            'metrc_harvests.package_count (API)'::text AS "?column?",
            'metrc_rpt_harvests.package_count (report)'::text AS "?column?",
            ( SELECT sum(metrc_harvests.package_count) AS sum
                   FROM metrc_harvests) AS sum,
            round(( SELECT sum(metrc_rpt_harvests.package_count) AS sum
                   FROM metrc_rpt_harvests)) AS round,
            0 AS "?column?",
            0 AS "?column?",
            NULL::numeric AS "numeric"
        ), harvest_rows AS (
         SELECT 'Harvests held'::text AS "?column?",
            'harvests'::text AS "?column?",
            'metrc_harvests (API)'::text AS "?column?",
            'metrc_rpt_harvests (report)'::text AS "?column?",
            ( SELECT count(*) AS count
                   FROM metrc_harvests) AS count,
            ( SELECT count(*) AS count
                   FROM metrc_rpt_harvests) AS count,
            ( SELECT count(*) AS count
                   FROM ( SELECT metrc_harvests.name
                           FROM metrc_harvests
                        EXCEPT
                         SELECT metrc_rpt_harvests.harvest_name
                           FROM metrc_rpt_harvests) x) AS count,
            ( SELECT count(*) AS count
                   FROM ( SELECT metrc_rpt_harvests.harvest_name
                           FROM metrc_rpt_harvests
                        EXCEPT
                         SELECT metrc_harvests.name
                           FROM metrc_harvests) y) AS count,
            NULL::numeric AS "numeric"
        ), all_facts AS (
         SELECT revenue.fact,
            revenue.unit,
            revenue.source_a,
            revenue.source_b,
            revenue.overlap_a,
            revenue.overlap_b,
            revenue.only_in_a,
            revenue.only_in_b,
            revenue.value_not_covered
           FROM revenue
        UNION ALL
         SELECT harvest_wet."?column?",
            harvest_wet."?column?_1" AS "?column?",
            harvest_wet."?column?_2" AS "?column?",
            harvest_wet."?column?_3" AS "?column?",
            harvest_wet.round,
            harvest_wet.round_1 AS round,
            harvest_wet.count,
            harvest_wet.count_1 AS count,
            harvest_wet."numeric"
           FROM harvest_wet harvest_wet("?column?", "?column?_1", "?column?_2", "?column?_3", round, round_1, count, count_1, "numeric")
        UNION ALL
         SELECT harvest_pkgs."?column?",
            harvest_pkgs."?column?_1" AS "?column?",
            harvest_pkgs."?column?_2" AS "?column?",
            harvest_pkgs."?column?_3" AS "?column?",
            harvest_pkgs.sum,
            harvest_pkgs.round,
            harvest_pkgs."?column?_4" AS "?column?",
            harvest_pkgs."?column?_5" AS "?column?",
            harvest_pkgs."numeric"
           FROM harvest_pkgs harvest_pkgs("?column?", "?column?_1", "?column?_2", "?column?_3", sum, round, "?column?_4", "?column?_5", "numeric")
        UNION ALL
         SELECT harvest_rows."?column?",
            harvest_rows."?column?_1" AS "?column?",
            harvest_rows."?column?_2" AS "?column?",
            harvest_rows."?column?_3" AS "?column?",
            harvest_rows.count,
            harvest_rows.count_1 AS count,
            harvest_rows.count_2 AS count,
            harvest_rows.count_3 AS count,
            harvest_rows."numeric"
           FROM harvest_rows harvest_rows("?column?", "?column?_1", "?column?_2", "?column?_3", count, count_1, count_2, count_3, "numeric")
        )
 SELECT fact,
    unit,
    source_a,
    source_b,
    overlap_a,
    overlap_b,
    overlap_b - overlap_a AS value_difference,
        CASE
            WHEN overlap_a IS NULL OR overlap_a = 0::numeric THEN NULL::numeric
            ELSE round(100.0 * (overlap_b - overlap_a) / abs(overlap_a), 3)
        END AS value_pct,
    only_in_a,
    only_in_b,
    value_not_covered,
        CASE
            WHEN overlap_a IS NULL OR overlap_b IS NULL THEN 'CANNOT COMPARE'::text
            WHEN overlap_a = overlap_b AND COALESCE(only_in_a, 0::bigint) = 0 AND COALESCE(only_in_b, 0::bigint) = 0 THEN 'RECONCILED — identical, and both sources cover the same population'::text
            WHEN overlap_a = overlap_b THEN 'VALUES AGREE — but the sources cover different populations, see only_in_a / only_in_b'::text
            WHEN abs(overlap_b - overlap_a) < 1::numeric THEN 'RECONCILED — agree to within rounding'::text
            ELSE 'DISAGREES — the same fact has two different values on the SAME population. This is a bug.'::text
        END AS verdict
   FROM all_facts
  ORDER BY fact;
create or replace view public.v_customer_history as
 SELECT customer,
    customer_license,
    manifests,
    packages_bought,
    first_order,
    last_order,
    days_since_last_order,
    unconfirmed_manifests,
    license,
    first_order AS first_order_date
   FROM ( SELECT COALESCE(metrc_transfers.recipient, '(not recorded)'::text) AS customer,
            metrc_transfers.raw ->> 'RecipientFacilityLicenseNumber'::text AS customer_license,
            count(*)::numeric AS manifests,
            sum(COALESCE((metrc_transfers.raw ->> 'PackageCount'::text)::numeric, 0::numeric)) AS packages_bought,
            min(metrc_transfers.created_on) AS first_order,
            max(metrc_transfers.created_on) AS last_order,
            (CURRENT_DATE - max(metrc_transfers.created_on))::numeric AS days_since_last_order,
            count(*) FILTER (WHERE (metrc_transfers.raw ->> 'ReceivedDateTime'::text) IS NULL)::numeric AS unconfirmed_manifests,
            metrc_transfers.license
           FROM metrc_transfers
          WHERE metrc_transfers.direction = 'outgoing'::text
          GROUP BY (COALESCE(metrc_transfers.recipient, '(not recorded)'::text)), (metrc_transfers.raw ->> 'RecipientFacilityLicenseNumber'::text), metrc_transfers.license
          ORDER BY (sum(COALESCE((metrc_transfers.raw ->> 'PackageCount'::text)::numeric, 0::numeric))) DESC) q;
create or replace view public.v_customer_manifests as
 SELECT created_on AS shipped_on,
    manifest_number,
    recipient AS customer,
    raw ->> 'RecipientFacilityLicenseNumber'::text AS customer_license,
    COALESCE((raw ->> 'PackageCount'::text)::numeric, 0::numeric) AS packages,
    COALESCE((raw ->> 'ReceivedPackageCount'::text)::numeric, 0::numeric) AS packages_received,
    (raw ->> 'ReceivedDateTime'::text)::date AS received_on,
        CASE
            WHEN (raw ->> 'ReceivedDateTime'::text) IS NOT NULL THEN 'Delivered and confirmed'::text
            WHEN created_on < (CURRENT_DATE - 3) THEN 'NOT CONFIRMED RECEIVED'::text
            ELSE 'In transit'::text
        END AS delivery_status,
    raw ->> 'TransporterFacilityName'::text AS transporter,
    raw ->> 'DriverName'::text AS driver,
    raw ->> 'VehicleLicensePlateNumber'::text AS vehicle_plate,
    COALESCE(( SELECT d.download_url
           FROM metrc_documents d
          WHERE d.doc_type = 'manifest'::text AND d.manifest_number = t.manifest_number AND d.download_url IS NOT NULL
         LIMIT 1),
        CASE
            WHEN (raw ->> 'Id'::text) IS NOT NULL THEN ('https://ma.metrc.com/reports/transfers/'::text || (raw ->> 'Id'::text)) || '/manifest'::text
            ELSE NULL::text
        END) AS manifest_download,
    ( SELECT count(*) AS count
           FROM metrc_packages p
          WHERE t.raw::text ~~ (('%'::text || p.tag) || '%'::text)) AS packages_matched,
    ( SELECT string_agg(DISTINCT p.item_name, ' · '::text) AS string_agg
           FROM metrc_packages p
          WHERE t.raw::text ~~ (('%'::text || p.tag) || '%'::text)) AS products_on_manifest,
    ( SELECT string_agg(DISTINCT d.download_url, ' | '::text) AS string_agg
           FROM metrc_documents d
          WHERE d.doc_type = 'coa'::text AND d.download_url IS NOT NULL AND (EXISTS ( SELECT 1
                   FROM metrc_packages p2
                  WHERE p2.tag = d.package_tag AND t.raw::text ~~ (('%'::text || p2.tag) || '%'::text)))) AS certificate_of_analysis_links,
    ( SELECT count(DISTINCT r.package_tag) AS count
           FROM metrc_lab_results r
          WHERE (EXISTS ( SELECT 1
                   FROM metrc_packages p3
                  WHERE p3.tag = r.package_tag AND t.raw::text ~~ (('%'::text || p3.tag) || '%'::text)))) AS packages_with_certificate,
    license,
    ( SELECT count(*) AS count
           FROM metrc_documents d
          WHERE d.doc_type = 'manifest'::text AND d.manifest_number = t.manifest_number AND d.storage_path IS NOT NULL) AS manifest_copy_held,
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM metrc_documents d
              WHERE d.doc_type = 'manifest'::text AND d.manifest_number = t.manifest_number AND d.download_url IS NOT NULL)) THEN 'Ready to download, print or send'::text
            ELSE 'Not downloaded yet - pulls overnight'::text
        END AS document_status
   FROM metrc_transfers t
  WHERE direction = 'outgoing'::text
  ORDER BY created_on DESC NULLS LAST;
create or replace view public.v_dashboard_tasks as
 SELECT t.id,
    t.title,
    t.description,
    t.status,
    t.priority,
    e.full_name AS assigned_to,
    d.name AS assignee_department,
    t.department AS raised_from,
    t.source_kpi,
    t.source_value,
    t.source_unit,
    t.source_view AS drill,
    t.due_on,
    t.due_on - CURRENT_DATE AS days_until_due,
        CASE
            WHEN t.due_on < CURRENT_DATE AND t.status <> 'done'::text THEN ('OVERDUE by '::text || (CURRENT_DATE - t.due_on)) || ' days'::text
            WHEN t.status = 'done'::text THEN 'Done '::text || COALESCE(t.completed_at::date::text, ''::text)
            WHEN t.due_on IS NULL THEN 'No due date set'::text
            ELSE ('Due in '::text || (t.due_on - CURRENT_DATE)) || ' days'::text
        END AS "position",
    t.created_at::date AS raised_on,
    CURRENT_DATE - t.created_at::date AS days_open,
    t.source_snapshot
   FROM tasks t
     LEFT JOIN employees e ON e.id = t.assignee_employee_id
     LEFT JOIN departments d ON d.id = e.primary_department_id
  WHERE t.source_kpi IS NOT NULL
  ORDER BY (
        CASE t.status
            WHEN 'open'::text THEN 0
            ELSE 1
        END), t.due_on;
create or replace view public.v_dashboard_trend as
 SELECT department,
    kpi,
    array_agg(value ORDER BY taken_on) AS series,
    array_agg(taken_on ORDER BY taken_on) AS days,
    count(*) AS points,
    (array_agg(value ORDER BY taken_on DESC))[1] AS latest,
    (array_agg(value ORDER BY taken_on DESC))[2] AS previous
   FROM dashboard_snapshots
  WHERE taken_on >= (CURRENT_DATE - 30)
  GROUP BY department, kpi;
create or replace view public.v_department_coverage_week as
 WITH span AS (
         SELECT LEAST(COALESCE(( SELECT min(zone_staffing_requirements.effective_from) AS min
                   FROM zone_staffing_requirements), CURRENT_DATE), COALESCE(( SELECT min(employee_schedules.work_date) AS min
                   FROM employee_schedules), CURRENT_DATE), COALESCE(( SELECT min(time_entries.work_date) AS min
                   FROM time_entries), CURRENT_DATE)) AS from_date,
            GREATEST(COALESCE(( SELECT max(COALESCE(zone_staffing_requirements.effective_to, CURRENT_DATE + 28)) AS max
                   FROM zone_staffing_requirements), CURRENT_DATE), COALESCE(( SELECT max(employee_schedules.work_date) AS max
                   FROM employee_schedules), CURRENT_DATE), COALESCE(( SELECT max(time_entries.work_date) AS max
                   FROM time_entries), CURRENT_DATE)) AS to_date
        ), days AS (
         SELECT d_1.d::date AS work_date
           FROM span,
            LATERAL generate_series(span.from_date::timestamp with time zone, span.to_date::timestamp with time zone, '1 day'::interval) d_1(d)
          WHERE (EXISTS ( SELECT 1
                   FROM zone_staffing_requirements))
        ), required AS (
         SELECT dy.work_date,
            COALESCE(r.department_id, z.department_id) AS department_id,
            sum(r.headcount_required) AS heads_required,
            sum(r.headcount_required::numeric * r.hours_per_head) AS hours_required,
            string_agg(DISTINCT r.driver, ', '::text) AS drivers
           FROM days dy
             JOIN zone_staffing_requirements r ON r.effective_from <= dy.work_date AND (r.effective_to IS NULL OR r.effective_to >= dy.work_date) AND (r.weekday IS NULL OR r.weekday = EXTRACT(dow FROM dy.work_date)::integer)
             LEFT JOIN zones z ON z.id = r.zone_id
          WHERE COALESCE(r.department_id, z.department_id) IS NOT NULL
          GROUP BY dy.work_date, (COALESCE(r.department_id, z.department_id))
        ), scheduled AS (
         SELECT s.work_date,
            s.department_id,
            count(DISTINCT s.employee_id) AS heads_scheduled,
            sum(EXTRACT(epoch FROM s.planned_end - s.planned_start) / 3600.0) AS hours_scheduled
           FROM employee_schedules s
          WHERE s.department_id IS NOT NULL AND COALESCE(s.status, 'planned'::text) <> 'cancelled'::text
          GROUP BY s.work_date, s.department_id
        ), actual AS (
         SELECT t.work_date,
            e.primary_department_id AS department_id,
            count(DISTINCT t.employee_id) AS heads_actual,
            sum(COALESCE(t.productive_hours, 0::numeric)) AS hours_actual
           FROM time_entries t
             JOIN employees e ON e.id = t.employee_id
          WHERE e.primary_department_id IS NOT NULL
          GROUP BY t.work_date, e.primary_department_id
        )
 SELECT date_trunc('week'::text, COALESCE(rq.work_date, sc.work_date, ac.work_date)::timestamp with time zone)::date AS week_start,
    d.id AS department_id,
    d.name AS department,
    count(*) FILTER (WHERE rq.heads_required IS NOT NULL) AS days_with_a_requirement,
    sum(COALESCE(rq.heads_required, 0::bigint)) AS heads_required,
    sum(COALESCE(sc.heads_scheduled, 0::bigint)) AS heads_scheduled,
    sum(COALESCE(ac.heads_actual, 0::bigint)) AS heads_actual,
    round(sum(COALESCE(rq.hours_required, 0::numeric)), 1) AS hours_required,
    round(sum(COALESCE(sc.hours_scheduled, 0::numeric)), 1) AS hours_scheduled,
    round(sum(COALESCE(ac.hours_actual, 0::numeric)), 1) AS hours_actual,
    sum(COALESCE(rq.heads_required, 0::bigint) - COALESCE(sc.heads_scheduled, 0::bigint)) AS head_days_short_on_the_rota,
    round(sum(COALESCE(rq.hours_required, 0::numeric) - COALESCE(ac.hours_actual, 0::numeric)), 1) AS hours_short_actually_worked,
    string_agg(DISTINCT rq.drivers, ', '::text) AS set_by,
        CASE
            WHEN sum(COALESCE(rq.heads_required, 0::bigint)) = 0::numeric THEN 'NO REQUIREMENT SET'::text
            WHEN sum(COALESCE(sc.heads_scheduled, 0::bigint)) < sum(COALESCE(rq.heads_required, 0::bigint)) THEN 'SHORT ON THE ROTA'::text
            WHEN sum(COALESCE(ac.heads_actual, 0::bigint)) < sum(COALESCE(rq.heads_required, 0::bigint)) THEN 'ROTA FULL BUT DID NOT TURN UP'::text
            ELSE 'COVERED'::text
        END AS verdict,
        CASE
            WHEN sum(COALESCE(rq.heads_required, 0::bigint)) = 0::numeric THEN 'No coverage requirement exists for this department in this week, so short-staffing '::text || 'CANNOT be detected. This is not the same as being fully staffed.'::text
            ELSE NULL::text
        END AS why_it_cannot_be_judged
   FROM departments d
     LEFT JOIN required rq ON rq.department_id = d.id
     LEFT JOIN scheduled sc ON sc.department_id = d.id AND sc.work_date = rq.work_date
     LEFT JOIN actual ac ON ac.department_id = d.id AND ac.work_date = COALESCE(rq.work_date, sc.work_date)
  WHERE COALESCE(rq.work_date, sc.work_date, ac.work_date) IS NOT NULL
  GROUP BY (date_trunc('week'::text, COALESCE(rq.work_date, sc.work_date, ac.work_date)::timestamp with time zone)::date), d.id, d.name
  ORDER BY (date_trunc('week'::text, COALESCE(rq.work_date, sc.work_date, ac.work_date)::timestamp with time zone)::date) DESC, d.name;
create or replace view public.v_department_labour as
 WITH punch AS (
         SELECT t.employee_id,
            t.work_date,
            s.department_id,
            btrim(s.zone) AS zone,
            s.shift_template_id,
            st.name AS shift,
            EXTRACT(epoch FROM t.clock_out - t.clock_in) / 3600.0 - COALESCE(t.unpaid_lunch_min, 0)::numeric / 60.0 AS hours,
            t.late_minutes,
            t.early_minutes,
            r.rate,
            COALESCE(r.ot_multiplier, 1.5) AS otm,
            COALESCE(r.burden_pct, 0::numeric) AS burden
           FROM time_entries t
             LEFT JOIN employee_schedules s ON s.employee_id = t.employee_id AND s.work_date = t.work_date
             LEFT JOIN shift_templates st ON st.id = s.shift_template_id
             LEFT JOIN LATERAL ( SELECT r2.id,
                    r2.employee_id,
                    r2.basis,
                    r2.rate,
                    r2.ot_multiplier,
                    r2.burden_pct,
                    r2.effective_from,
                    r2.effective_to,
                    r2.approved_by,
                    r2.note,
                    r2.effective_from_date
                   FROM employee_rates r2
                  WHERE r2.employee_id = t.employee_id AND r2.effective_from <= t.work_date AND (r2.effective_to IS NULL OR r2.effective_to >= t.work_date)
                  ORDER BY r2.effective_from DESC
                 LIMIT 1) r ON true
          WHERE t.clock_in IS NOT NULL AND t.clock_out IS NOT NULL
        )
 SELECT d.id AS department_id,
    COALESCE(d.name, 'Unassigned'::text) AS department,
    p.work_date,
    date_trunc('week'::text, p.work_date::timestamp with time zone)::date AS week_start,
    date_trunc('month'::text, p.work_date::timestamp with time zone)::date AS month_start,
    COALESCE(p.shift, 'Unscheduled'::text) AS shift,
    p.zone,
    count(DISTINCT p.employee_id) AS heads,
    round(sum(p.hours), 2) AS hours,
    round(avg(p.hours), 2) AS avg_hours_per_head,
    round(sum(LEAST(p.hours, 8::numeric)), 2) AS straight_hours,
    round(sum(GREATEST(p.hours - 8::numeric, 0::numeric)), 2) AS ot_hours,
    round(sum(LEAST(p.hours, 8::numeric) * p.rate * (1::numeric + p.burden)), 2) AS straight_cost_loaded,
    round(sum(GREATEST(p.hours - 8::numeric, 0::numeric) * p.rate * p.otm * (1::numeric + p.burden)), 2) AS ot_cost_loaded,
    round(sum((LEAST(p.hours, 8::numeric) + GREATEST(p.hours - 8::numeric, 0::numeric) * p.otm) * p.rate * (1::numeric + p.burden)), 2) AS total_cost_loaded,
    round(sum((LEAST(p.hours, 8::numeric) + GREATEST(p.hours - 8::numeric, 0::numeric) * p.otm) * p.rate * (1::numeric + p.burden)) / NULLIF(sum(p.hours), 0::numeric), 2) AS cost_per_hour,
    count(*) FILTER (WHERE COALESCE(p.late_minutes, 0) > 0) AS late_punches,
    round(avg(NULLIF(p.late_minutes, 0)), 1) AS avg_late_minutes,
    count(*) FILTER (WHERE COALESCE(p.early_minutes, 0) > (( SELECT attendance_policy.early_punch_minutes
           FROM attendance_policy
         LIMIT 1))) AS early_punches_over_window
   FROM punch p
     LEFT JOIN departments d ON d.id = p.department_id
  GROUP BY d.id, d.name, p.work_date, p.shift, p.zone;
create or replace view public.v_department_task_kpis as
 SELECT COALESCE(tasks.department, 'Command'::text) AS dept,
    90 AS ord,
    'Open tasks from this dashboard'::text AS kpi,
    count(*) FILTER (WHERE tasks.status <> 'done'::text)::numeric AS value,
    'tasks'::text AS unit,
        CASE
            WHEN count(*) FILTER (WHERE tasks.status <> 'done'::text) > 0 THEN 'warn'::text
            ELSE 'good'::text
        END AS tone,
    'dashboard_tasks'::text AS drill,
    'raised from a tile here'::text AS sub
   FROM tasks
  WHERE tasks.source_kpi IS NOT NULL
  GROUP BY (COALESCE(tasks.department, 'Command'::text))
UNION ALL
 SELECT COALESCE(tasks.department, 'Command'::text) AS dept,
    91 AS ord,
    'Tasks overdue'::text AS kpi,
    count(*) FILTER (WHERE tasks.due_on < CURRENT_DATE AND tasks.status <> 'done'::text)::numeric AS value,
    'tasks'::text AS unit,
        CASE
            WHEN count(*) FILTER (WHERE tasks.due_on < CURRENT_DATE AND tasks.status <> 'done'::text) > 0 THEN 'bad'::text
            ELSE 'good'::text
        END AS tone,
    'dashboard_tasks'::text AS drill,
    'past their due date'::text AS sub
   FROM tasks
  WHERE tasks.source_kpi IS NOT NULL
  GROUP BY (COALESCE(tasks.department, 'Command'::text));
create or replace view public.v_discrepancy_clock as
 WITH routed AS (
         SELECT r.discrepancy_key,
            r.class,
            r.subject,
            r.source_a,
            r.source_a_says,
            r.source_b,
            r.source_b_says,
            r.resolved_by_doc,
            r.document_link,
            r.first_seen,
            r.last_seen,
            r.resolved_at,
            r.resolved_by,
            r.resolution_note,
            r.assigned_to,
            r.assigned_at,
                CASE r.class
                    WHEN 'strain'::text THEN 'Compliance'::text
                    WHEN 'ownership'::text THEN 'Inventory'::text
                    WHEN 'missing_contents'::text THEN 'Compliance'::text
                    WHEN 'verification'::text THEN 'Unassigned'::text
                    ELSE NULL::text
                END AS dept
           FROM discrepancy_register r
        )
 SELECT d.discrepancy_key,
    d.class,
        CASE d.class
            WHEN 'strain'::text THEN 'Strain — the item name and the strain field disagree'::text
            WHEN 'ownership'::text THEN 'Ownership — the platform and the package lineage disagree'::text
            WHEN 'missing_contents'::text THEN 'Contents — a shipment moved with no record of what was on it'::text
            WHEN 'verification'::text THEN 'Verification — two derivations of the same fact disagree'::text
            ELSE d.class
        END AS what_disagrees,
    d.subject,
    d.source_a,
    d.source_a_says,
    d.source_b,
    d.source_b_says,
    d.resolved_by_doc,
    d.document_link,
        CASE
            WHEN d.document_link IS NOT NULL THEN 'The document is on file — open it and the answer is there.'::text
            WHEN d.class = 'verification'::text THEN 'No document settles this. Both numbers come from our own records; the query behind each is on the check.'::text
            ELSE 'The document that settles this has not been fetched from Metrc yet.'::text
        END AS can_it_be_settled_now,
    (d.first_seen AT TIME ZONE 'America/New_York'::text) AS tracking_started,
    CURRENT_DATE - d.first_seen::date AS days_tracked,
    d.assigned_to,
    (d.resolved_at AT TIME ZONE 'America/New_York'::text) AS resolved_at,
        CASE
            WHEN d.resolved_at IS NOT NULL THEN 'RESOLVED'::text
            WHEN (CURRENT_DATE - d.first_seen::date) > 7 THEN 'BREACH — past the one-week rule'::text
            WHEN (CURRENT_DATE - d.first_seen::date) >= 5 THEN ('DUE — '::text || (7 - (CURRENT_DATE - d.first_seen::date))) || ' days left'::text
            ELSE 'within the week'::text
        END AS clock,
        CASE
            WHEN d.resolved_at IS NOT NULL THEN 5
            WHEN (CURRENT_DATE - d.first_seen::date) > 7 THEN 1
            WHEN d.class = 'verification'::text THEN 2
            WHEN (CURRENT_DATE - d.first_seen::date) >= 5 THEN 3
            ELSE 4
        END AS rank,
        CASE
            WHEN o.owner_name IS NULL AND d.assigned_to IS NULL AND d.resolved_at IS NULL THEN 'NOBODY IS ASSIGNED and no department owner is on file.'::text
            WHEN d.assigned_to IS NULL AND d.resolved_at IS NULL THEN ('Falls to the department owner by default — nobody has taken it personally. Every '::text || 'department in finding_owners currently resolves to the same person, so this is one '::text) || 'person holding all of it, not a routed workload.'::text
            ELSE NULL::text
        END AS ownership_gap,
    d.dept AS department,
    COALESCE(d.assigned_to, o.owner_name) AS accountable,
    o.escalates_to
   FROM routed d
     LEFT JOIN finding_owners o ON o.department = d.dept;
create or replace view public.v_discrepancy_readiness as
 SELECT subject,
    count(*) FILTER (WHERE settled_it) AS sources_that_settled_it,
    ( SELECT count(*) AS count
           FROM discrepancy_source
          WHERE discrepancy_source.mandatory) AS rungs_required,
    count(DISTINCT source_key) AS rungs_checked,
    ( SELECT string_agg(d.source_name, ', '::text ORDER BY d.rung) AS string_agg
           FROM discrepancy_source d
          WHERE d.mandatory AND NOT (d.source_key IN ( SELECT i.source_key
                   FROM discrepancy_investigation i
                  WHERE i.subject = s.subject))) AS not_yet_tried,
    bool_or(settled_it) AS already_answered
   FROM discrepancy_investigation s
  GROUP BY subject;
create or replace view public.v_document_compliance as
 SELECT d.id AS document_id,
    d.title,
    d.kind,
    d.version,
    d.requires_signature,
    e.id AS employee_id,
    e.employee_code,
    e.full_name,
    dep.name AS department,
    a.due_on,
    ack.signed_at,
    ack.read_at,
    ack.signature_name,
    ( SELECT count(*) AS count
           FROM hr_document_sections s
          WHERE s.document_id = d.id) AS sections,
    ( SELECT count(*) AS count
           FROM hr_document_progress p
             JOIN hr_document_sections s2 ON s2.id = p.section_id
          WHERE s2.document_id = d.id AND p.employee_id = e.id) AS sections_read,
        CASE
            WHEN ack.signed_at IS NOT NULL THEN 'signed'::text
            WHEN ack.read_at IS NOT NULL THEN 'read, not signed'::text
            WHEN (EXISTS ( SELECT 1
               FROM hr_document_progress p2
                 JOIN hr_document_sections s3 ON s3.id = p2.section_id
              WHERE s3.document_id = d.id AND p2.employee_id = e.id)) THEN 'in progress'::text
            WHEN a.due_on IS NOT NULL AND a.due_on < CURRENT_DATE THEN 'overdue'::text
            ELSE 'not started'::text
        END AS state
   FROM hr_documents d
     JOIN hr_document_assignments a ON a.document_id = d.id
     JOIN employees e ON a.employee_id = e.id OR a.role_id IS NOT NULL AND (e.primary_role_id = a.role_id OR e.secondary_role_id = a.role_id) OR a.department_id IS NOT NULL AND (e.primary_department_id = a.department_id OR e.secondary_department_id = a.department_id)
     LEFT JOIN departments dep ON dep.id = e.primary_department_id
     LEFT JOIN hr_document_acknowledgements ack ON ack.document_id = d.id AND ack.employee_id = e.id AND ack.document_version = d.version
  WHERE d.retired_at IS NULL AND e.status::text = 'active'::text;
create or replace view public.v_document_library as
 SELECT d.doc_type,
        CASE d.doc_type
            WHEN 'coa'::text THEN 'Certificate of Analysis'::text
            ELSE 'Manifest'::text
        END AS document,
    COALESCE(d.manifest_number, d.package_tag) AS reference,
    d.package_tag,
    d.manifest_number,
    p.item_name,
    p.location AS current_location,
    t.shipper,
    t.recipient AS customer,
    t.direction,
    t.created_on AS manifest_date,
    lr.lab_facility,
    lr.result_date AS tested_on,
    d.storage_path,
    d.byte_size,
    round(d.byte_size::numeric / 1024.0)::integer AS kilobytes,
    d.file_hash,
    d.license,
    d.fetched_at,
    COALESCE(d.fetch_error, 'held'::text) AS state,
    concat_ws(' '::text, d.manifest_number, d.package_tag, p.item_name, t.recipient, t.shipper, lr.lab_facility) AS search_text,
    d.download_url AS open_download_print,
        CASE
            WHEN d.download_url IS NOT NULL THEN 'Ready - click to open, print or send'::text
            WHEN d.fetch_error IS NOT NULL THEN 'Could not be retrieved: '::text || d.fetch_error
            ELSE 'Stored, link pending'::text
        END AS document_status,
    d.url_expires_at
   FROM metrc_documents d
     LEFT JOIN metrc_packages p ON p.tag = d.package_tag
     LEFT JOIN LATERAL ( SELECT x.id,
            x.license,
            x.manifest_number,
            x.direction,
            x.shipper,
            x.recipient,
            x.created_on,
            x.raw,
            x.synced_at
           FROM metrc_transfers x
          WHERE x.manifest_number = d.manifest_number
          ORDER BY (
                CASE
                    WHEN x.direction = 'outgoing'::text THEN 0
                    ELSE 1
                END), x.created_on DESC
         LIMIT 1) t ON true
     LEFT JOIN LATERAL ( SELECT r.id,
            r.license,
            r.package_tag,
            r.test_type,
            r.result,
            r.passed,
            r.result_date,
            r.raw,
            r.synced_at,
            r.package_id,
            r.test_name,
            r.units,
            r.notes,
            r.lab_facility,
            r.document_file_id,
            r.coa_link
           FROM metrc_lab_results r
          WHERE r.document_file_id = d.metrc_id
          ORDER BY r.result_date DESC NULLS LAST
         LIMIT 1) lr ON true;
create or replace view public.v_employee_capacity as
 SELECT e.employee_code,
    e.full_name,
    COALESCE(rc.name, '—'::text) AS "position",
    COALESCE(d.name, '—'::text) AS department,
        CASE
            WHEN s.days IS NULL THEN 'Company default'::text
            ELSE 'Custom'::text
        END AS schedule_source,
    COALESCE(s.days, ( SELECT jsonb_array_length(configurations.value -> 'workweek'::text) AS jsonb_array_length
           FROM configurations
          WHERE configurations.key = 'workspace_work_schedule'::text)) AS days_per_week,
    round(COALESCE(s.weekly_hours, ( SELECT (configurations.value ->> 'weekly_capacity_hours'::text)::numeric AS "numeric"
           FROM configurations
          WHERE configurations.key = 'workspace_work_schedule'::text)), 1) AS weekly_capacity_hours,
    e.weekly_target_hours AS payroll_target_hours,
    e.status
   FROM employees e
     LEFT JOIN ( SELECT employee_work_schedules.employee_id,
            count(*)::integer AS days,
            sum(EXTRACT(epoch FROM employee_work_schedules.end_time - employee_work_schedules.start_time) / 3600.0) AS weekly_hours
           FROM employee_work_schedules
          GROUP BY employee_work_schedules.employee_id) s ON s.employee_id = e.id
     LEFT JOIN roles_catalog rc ON rc.id = e.primary_role_id
     LEFT JOIN departments d ON d.id = e.primary_department_id
  WHERE e.terminated_on IS NULL
  ORDER BY e.full_name;
create or replace view public.v_failed_provenance as
 WITH p AS (
         SELECT pk.tag,
            pk.item_name,
            pk.quantity,
            pk.uom,
            pk.license,
            pk.location,
            pk.packaged_on,
            pk.raw #>> '{Item,StrainName}'::text[] AS strain,
            pk.raw #>> '{Item,ProductCategoryName}'::text[] AS category,
            NULLIF(pk.raw ->> 'ItemFromFacilityName'::text, ''::text) AS made_by,
            pk.raw ->> 'ItemFromFacilityLicenseNumber'::text AS made_by_license,
            NULLIF(pk.raw ->> 'ReceivedFromFacilityName'::text, ''::text) AS shipped_by,
            pk.raw ->> 'ReceivedFromFacilityLicenseNumber'::text AS shipper_license,
            NULLIF(pk.raw ->> 'SourceHarvestNames'::text, ''::text) AS source_harvest,
            NULLIF(pk.raw ->> 'ReceivedFromManifestNumber'::text, ''::text) AS inbound_manifest,
            NULLIF(pk.raw ->> 'SourceProductionBatchNumbers'::text, ''::text) AS production_batch,
            NULLIF(pk.raw ->> 'SourcePackageLabels'::text, ''::text) AS made_from_packages,
            (pk.raw ->> 'ReceivedDateTime'::text)::date AS received_on,
            (pk.raw ->> 'LabTestingStateDate'::text)::date AS submitted_on,
            (pk.raw ->> 'LabTestingRecordedDate'::text)::date AS result_on,
            (pk.raw ->> 'LabTestResultExpirationDateTime'::text)::date AS coa_expires,
            pk.raw ->> 'ProductRequiresRemediation'::text AS requires_remediation
           FROM metrc_packages pk
          WHERE (pk.raw ->> 'LabTestingState'::text) = 'TestFailed'::text
        )
 SELECT p.tag AS package_tag,
    p.item_name,
    p.strain,
    p.category,
    round(p.quantity) AS quantity,
    p.uom,
    round(p.quantity / 453.592, 2) AS pounds,
    COALESCE(p.made_by, 'not recorded'::text) AS made_by,
    p.made_by_license,
        CASE
            WHEN COALESCE(p.made_by_license, ''::text) = ANY (ARRAY['MC281714'::text, 'MP281909'::text]) THEN 'US - Twisted Growers'::text
            ELSE 'THIRD PARTY'::text
        END AS ours_or_theirs,
    COALESCE(p.shipped_by, 'not applicable'::text) AS shipped_to_us_by,
    p.shipper_license,
    p.inbound_manifest,
    p.source_harvest,
    h.harvest_start AS harvest_cut_on,
    (h.raw ->> 'FinishedDate'::text)::date AS harvest_closed_on,
    COALESCE(NULLIF(h.raw ->> 'DryingLocationName'::text, ''::text), 'not recorded'::text) AS harvest_room,
    p.packaged_on AS package_created_on,
    p.received_on AS received_by_us_on,
    p.production_batch,
    p.made_from_packages,
    p.submitted_on AS submitted_for_testing_on,
    p.result_on AS result_recorded_on,
    p.result_on - p.submitted_on AS lab_turnaround_days,
    p.coa_expires AS coa_expires_on,
    p.requires_remediation,
    p.license AS held_under,
    p.location,
    CURRENT_DATE - p.packaged_on AS days_since_created,
        CASE
            WHEN h.harvest_start IS NOT NULL THEN p.packaged_on - h.harvest_start
            ELSE NULL::integer
        END AS days_cut_to_package,
        CASE
            WHEN COALESCE(p.made_by_license, ''::text) = ANY (ARRAY['MC281714'::text, 'MP281909'::text]) THEN (((((('We grew it'::text || COALESCE(' from harvest '::text || p.source_harvest, ''::text)) || COALESCE(' cut '::text || h.harvest_start::text, ''::text)) || COALESCE(' in '::text || NULLIF(h.raw ->> 'DryingLocationName'::text, ''::text), ''::text)) || ', packaged '::text) || p.packaged_on::text) || COALESCE(', submitted for testing '::text || p.submitted_on::text, ''::text)) || COALESCE(', failed '::text || p.result_on::text, ''::text)
            ELSE (((((('Made by '::text || COALESCE(p.made_by, 'licence '::text || COALESCE(p.made_by_license, 'unknown'::text))) || COALESCE(', shipped to us by '::text || p.shipped_by, ''::text)) || COALESCE(' on manifest '::text || p.inbound_manifest, ''::text)) || COALESCE(', received '::text || p.received_on::text, ''::text)) || ', packaged '::text) || p.packaged_on::text) || COALESCE(', failed '::text || p.result_on::text, ''::text)
        END AS the_chain
   FROM p
     LEFT JOIN metrc_harvests h ON h.name = split_part(COALESCE(p.source_harvest, ''::text), ','::text, 1)
  ORDER BY p.quantity DESC NULLS LAST;
create or replace view public.v_fg_metrc_check as
 WITH fg AS (
         SELECT product_inventory.id,
            product_inventory.category,
            product_inventory.current_status,
            product_inventory.production_batch,
            product_inventory.strain_flavor,
            NULLIF(regexp_replace(COALESCE(product_inventory.final_metrc_tag, product_inventory.bulk_metrc_tag), '\.0$'::text, ''::text), 'N/A'::text) AS tag_short,
            product_inventory.total_packaged,
            product_inventory.total_filled
           FROM product_inventory
        ), matched AS (
         SELECT f_1.id,
            count(m.id) AS metrc_matches,
            min(m.tag) AS metrc_tag,
            sum(m.quantity) AS metrc_quantity,
            min(m.uom) AS metrc_uom,
            min(m.lab_testing_state) AS lab_testing_state,
            bool_or(m.finished) AS metrc_finished
           FROM fg f_1
             LEFT JOIN metrc_packages m ON f_1.tag_short ~ '^[0-9]+$'::text AND m.tag ~~ ('%'::text || f_1.tag_short)
          GROUP BY f_1.id
        )
 SELECT f.category,
    f.current_status,
    f.production_batch,
    f.strain_flavor,
    f.tag_short AS sheet_tag,
    ma.metrc_matches,
    ma.metrc_tag,
    ma.metrc_quantity,
    ma.metrc_uom,
    ma.lab_testing_state,
    ma.metrc_finished,
    f.total_packaged,
    f.total_filled,
        CASE
            WHEN f.tag_short IS NULL OR f.tag_short !~ '^[0-9]+$'::text THEN 'NO TAG ON SHEET'::text
            WHEN ma.metrc_matches = 0 THEN 'TAG NOT IN SYNCED METRC'::text
            WHEN ma.metrc_matches > 1 THEN ('AMBIGUOUS - '::text || ma.metrc_matches) || ' METRC MATCHES'::text
            WHEN ma.metrc_finished THEN 'METRC SAYS FINISHED - SHEET STILL LISTS IT'::text
            ELSE 'MATCHED'::text
        END AS check_result
   FROM fg f
     JOIN matched ma ON ma.id = f.id
  ORDER BY (
        CASE
            WHEN ma.metrc_matches = 0 THEN 0
            WHEN ma.metrc_finished THEN 1
            ELSE 2
        END), f.category;
create or replace view public.v_finding_accountability as
 SELECT disposition,
    findings,
    dollars,
    past_due,
    oldest,
    newest,
    oldest AS oldest_date
   FROM ( SELECT finding_plans.disposition,
            count(*) AS findings,
            round(sum(COALESCE(finding_plans.dollars, 0::numeric)), 0) AS dollars,
            count(*) FILTER (WHERE finding_plans.due_on < CURRENT_DATE AND (finding_plans.disposition <> ALL (ARRAY['resolved'::text, 'ignored'::text]))) AS past_due,
            min(finding_plans.created_at)::date AS oldest,
            max(finding_plans.created_at)::date AS newest
           FROM finding_plans
          GROUP BY finding_plans.disposition
          ORDER BY (round(sum(COALESCE(finding_plans.dollars, 0::numeric)), 0)) DESC NULLS LAST) q;
create or replace view public.v_finding_alert_ready as
 SELECT id,
    fingerprint,
    severity,
    what,
    observed_at,
    who_is_accountable IS NOT NULL AND btrim(who_is_accountable) <> ''::text AS has_who,
    what IS NOT NULL AND btrim(what) <> ''::text AS has_what,
    when_it_started IS NOT NULL AND btrim(when_it_started) <> ''::text AS has_when,
    where_it_is IS NOT NULL AND btrim(where_it_is) <> ''::text AS has_where,
    why_it_matters IS NOT NULL AND btrim(why_it_matters) <> ''::text AS has_why,
    how_it_was_detected IS NOT NULL AND btrim(how_it_was_detected) <> ''::text AS has_how,
    solutions IS NOT NULL AND array_length(solutions, 1) >= 1 AS has_solutions,
    guard_recommendation IS NOT NULL AND btrim(guard_recommendation) <> ''::text AS has_recommendation,
    array_remove(ARRAY[
        CASE
            WHEN who_is_accountable IS NULL OR btrim(who_is_accountable) = ''::text THEN 'who'::text
            ELSE NULL::text
        END,
        CASE
            WHEN what IS NULL OR btrim(what) = ''::text THEN 'what'::text
            ELSE NULL::text
        END,
        CASE
            WHEN when_it_started IS NULL OR btrim(when_it_started) = ''::text THEN 'when'::text
            ELSE NULL::text
        END,
        CASE
            WHEN where_it_is IS NULL OR btrim(where_it_is) = ''::text THEN 'where'::text
            ELSE NULL::text
        END,
        CASE
            WHEN why_it_matters IS NULL OR btrim(why_it_matters) = ''::text THEN 'why'::text
            ELSE NULL::text
        END,
        CASE
            WHEN how_it_was_detected IS NULL OR btrim(how_it_was_detected) = ''::text THEN 'how'::text
            ELSE NULL::text
        END,
        CASE
            WHEN solutions IS NULL OR array_length(solutions, 1) IS NULL THEN 'solutions'::text
            ELSE NULL::text
        END,
        CASE
            WHEN guard_recommendation IS NULL OR btrim(guard_recommendation) = ''::text THEN 'recommendation'::text
            ELSE NULL::text
        END], NULL::text) AS missing,
        CASE
            WHEN who_is_accountable IS NULL OR btrim(who_is_accountable) = ''::text OR what IS NULL OR btrim(what) = ''::text OR when_it_started IS NULL OR btrim(when_it_started) = ''::text OR where_it_is IS NULL OR btrim(where_it_is) = ''::text OR why_it_matters IS NULL OR btrim(why_it_matters) = ''::text OR how_it_was_detected IS NULL OR btrim(how_it_was_detected) = ''::text OR solutions IS NULL OR array_length(solutions, 1) IS NULL OR guard_recommendation IS NULL OR btrim(guard_recommendation) = ''::text THEN false
            ELSE true
        END AS ready_to_send
   FROM watchdog_findings f;
create or replace view public.v_finding_history as
 SELECT created_at::date AS raised_on,
    finding_source,
    headline,
    disposition,
    disposition_reason,
    plan,
    owner_assigned,
    due_on,
    dollars,
    decided_by,
    decided_at::date AS decided_on,
        CASE disposition
            WHEN 'resolved'::text THEN 'Closed - '::text || COALESCE(disposition_reason, 'resolved'::text)
            WHEN 'ignored'::text THEN 'Deliberately ignored - '::text || COALESCE(disposition_reason, 'no reason recorded'::text)
            WHEN 'on_todo_list'::text THEN 'On the to-do list'::text ||
            CASE
                WHEN due_on IS NOT NULL THEN ', due '::text || due_on
                ELSE ''::text
            END
            WHEN 'saved_for_later'::text THEN 'Saved for later review'::text
            WHEN 'planned'::text THEN 'Plan written'::text ||
            CASE
                WHEN owner_assigned IS NOT NULL THEN ', assigned to '::text || owner_assigned
                ELSE ''::text
            END
            WHEN 'shared'::text THEN 'Shared with the team'::text
            ELSE 'Open, no decision recorded'::text
        END AS status_in_plain_english,
    snapshot,
    finding_key,
    id
   FROM finding_plans fp
  ORDER BY created_at DESC;
create or replace view public.v_findings as
 WITH raw AS (
         SELECT 'agent:'::text || f.id::text AS finding_key,
            'agent'::text AS source,
            COALESCE(NULLIF(f.agent, ''::text), 'Unassigned'::text) AS department,
            f.severity,
            f.headline AS what,
            f.scope AS where_it_is,
            NULL::text AS who_is_accountable,
            f.detail AS why_it_matters,
            f.action AS what_to_do,
            NULL::text AS the_arithmetic,
            NULL::text AS how_it_was_detected,
            NULL::text AS when_it_started,
                CASE
                    WHEN f.metric IS NOT NULL THEN (f.metric::text || ' '::text) || COALESCE(f.units, ''::text)
                    ELSE NULL::text
                END AS evidence,
            NULL::integer AS record_count,
            f.pounds,
            f.dollars,
            f.detected_at AS first_raised,
            f.detected_at AS last_seen,
            1 AS times_seen,
            f.resolved_at,
            f.resolution AS resolution_note,
            f.fingerprint,
            'agent:'::text || COALESCE(f.agent, '?'::text) AS pattern_key,
            f.drill_to AS drill
           FROM agent_findings f
        UNION ALL
         SELECT 'watchdog:'::text || w.id::text,
            'watchdog'::text,
            'Unassigned'::text,
            w.severity,
            w.what,
            w.where_it_is,
            w.who_is_accountable,
            w.why_it_matters,
            w.what_to_do,
            w.the_arithmetic,
            w.how_it_was_detected,
            w.when_it_started,
            w.evidence::text AS evidence,
            w.record_count,
            w.pounds,
            w.dollars,
            w.observed_at,
            w.observed_at,
            1,
            NULL::timestamp with time zone AS timestamptz,
            NULL::text AS text,
            w.fingerprint,
            'watchdog:'::text || "left"(COALESCE(w.how_it_was_detected, '?'::text), 80),
            w.drill
           FROM watchdog_findings w
        UNION ALL
         SELECT 'custody:'::text || c.id::text,
            'custody'::text,
            'Compliance'::text,
            c.severity,
            c.flag,
            concat_ws(' · '::text, NULLIF(c.item, ''::text), NULLIF(c.location, ''::text), NULLIF(c.identifier, ''::text)) AS concat_ws,
            NULL::text AS text,
            c.detail,
            NULL::text AS text,
            NULL::text AS text,
            NULL::text AS text,
            NULL::text AS text,
                CASE
                    WHEN c.quantity IS NOT NULL THEN (c.quantity::text || ' '::text) || COALESCE(c.uom, ''::text)
                    ELSE NULL::text
                END AS "case",
            NULL::integer AS int4,
                CASE
                    WHEN lower(COALESCE(c.uom, ''::text)) = ANY (ARRAY['lb'::text, 'lbs'::text, 'pound'::text, 'pounds'::text]) THEN c.quantity
                    ELSE NULL::numeric
                END AS "case",
            NULL::numeric AS "numeric",
            COALESCE(c.reference_date::timestamp with time zone, c.captured_at) AS "coalesce",
            c.captured_at,
            1,
            c.resolved_at,
            c.resolution_note,
            NULL::text AS text,
            'custody:'::text || COALESCE(c.flag, '?'::text),
            NULL::text AS text
           FROM custody_alert_log c
        UNION ALL
         SELECT 'inventory:'::text || i.id::text,
            'inventory'::text,
            COALESCE(NULLIF(i.area, ''::text), 'Inventory'::text) AS "coalesce",
            i.severity,
            i.headline,
            i.area,
            NULL::text AS text,
            i.detail,
            i.what_to_do,
            NULL::text AS text,
            NULL::text AS text,
            NULL::text AS text,
            NULL::text AS text,
            NULL::integer AS int4,
            i.pounds,
            i.dollars,
            i.first_raised,
            i.last_seen,
            COALESCE(i.times_seen, 1) AS "coalesce",
            i.resolved_at,
            i.resolution_note,
            i.fingerprint,
            'inventory:'::text || COALESCE(i.area, '?'::text),
            i.drill
           FROM inventory_alerts i
        ), marked AS (
         SELECT r.finding_key,
            r.source,
            r.department,
            r.severity,
            r.what,
            r.where_it_is,
            r.who_is_accountable,
            r.why_it_matters,
            r.what_to_do,
            r.the_arithmetic,
            r.how_it_was_detected,
            r.when_it_started,
            r.evidence,
            r.record_count,
            r.pounds,
            r.dollars,
            r.first_raised,
            r.last_seen,
            r.times_seen,
            r.resolved_at,
            r.resolution_note,
            r.fingerprint,
            r.pattern_key,
            r.drill,
                CASE
                    WHEN r.dollars IS NOT NULL AND r.pounds IS NOT NULL THEN (((r.severity || '|'::text) || r.dollars::text) || '|'::text) || r.pounds::text
                    ELSE NULL::text
                END AS merge_key
           FROM raw r
        ), ranked AS (
         SELECT m.finding_key,
            m.source,
            m.department,
            m.severity,
            m.what,
            m.where_it_is,
            m.who_is_accountable,
            m.why_it_matters,
            m.what_to_do,
            m.the_arithmetic,
            m.how_it_was_detected,
            m.when_it_started,
            m.evidence,
            m.record_count,
            m.pounds,
            m.dollars,
            m.first_raised,
            m.last_seen,
            m.times_seen,
            m.resolved_at,
            m.resolution_note,
            m.fingerprint,
            m.pattern_key,
            m.drill,
            m.merge_key,
                CASE
                    WHEN m.merge_key IS NULL THEN m.finding_key
                    WHEN min(m.source) OVER (PARTITION BY m.merge_key) = max(m.source) OVER (PARTITION BY m.merge_key) THEN m.finding_key
                    ELSE first_value(m.finding_key) OVER (PARTITION BY m.merge_key ORDER BY m.first_raised, m.finding_key)
                END AS canon
           FROM marked m
        )
 SELECT finding_key,
    source,
    department,
    severity,
    what,
    where_it_is,
    who_is_accountable,
    why_it_matters,
    what_to_do,
    the_arithmetic,
    how_it_was_detected,
    when_it_started,
    evidence,
    record_count,
    pounds,
    dollars,
    first_raised,
    last_seen,
    times_seen,
    resolved_at,
    resolution_note,
    fingerprint,
    pattern_key,
    drill,
        CASE
            WHEN resolved_at IS NULL THEN 'open'::text
            ELSE 'resolved'::text
        END AS state,
        CASE severity
            WHEN 'critical'::text THEN 1
            WHEN 'elevated'::text THEN 2
            WHEN 'watch'::text THEN 3
            ELSE 4
        END AS severity_rank,
    count(*) FILTER (WHERE first_raised >= (now() - '6 mons'::interval)) OVER (PARTITION BY pattern_key) AS occurrences_6mo,
        CASE severity
            WHEN 'critical'::text THEN 1
            ELSE 2
        END AS priority_band,
    canon AS canonical_key,
    canon <> finding_key AS is_duplicate,
        CASE
            WHEN canon <> finding_key THEN canon
            ELSE NULL::text
        END AS duplicate_of
   FROM ranked k;
create or replace view public.v_forensic_audit_history as
 SELECT run_at::date AS audit_date,
    run_type,
    count(*) FILTER (WHERE verdict = ANY (ARRAY['FAIL'::text, 'EXPOSURE'::text])) AS failures,
    count(*) FILTER (WHERE verdict = 'CLEAN'::text) AS clean,
    count(*) AS metrics_checked,
    round(sum(value) FILTER (WHERE unit = 'dollars'::text), 0) AS dollars_identified,
    string_agg(DISTINCT section, ', '::text) FILTER (WHERE verdict = ANY (ARRAY['FAIL'::text, 'EXPOSURE'::text])) AS failing_sections
   FROM forensic_audits
  GROUP BY (run_at::date), run_type
  ORDER BY (run_at::date) DESC;
create or replace view public.v_forensic_audit_latest as
 WITH runs AS (
         SELECT DISTINCT forensic_audits.run_at
           FROM forensic_audits
          ORDER BY forensic_audits.run_at DESC
         LIMIT 2
        ), cur AS (
         SELECT forensic_audits.id,
            forensic_audits.run_at,
            forensic_audits.run_type,
            forensic_audits.section,
            forensic_audits.metric,
            forensic_audits.value,
            forensic_audits.value_text,
            forensic_audits.unit,
            forensic_audits.responsible,
            forensic_audits.verdict,
            forensic_audits.evidence
           FROM forensic_audits
          WHERE forensic_audits.run_at = (( SELECT max(runs.run_at) AS max
                   FROM runs))
        ), prev AS (
         SELECT forensic_audits.id,
            forensic_audits.run_at,
            forensic_audits.run_type,
            forensic_audits.section,
            forensic_audits.metric,
            forensic_audits.value,
            forensic_audits.value_text,
            forensic_audits.unit,
            forensic_audits.responsible,
            forensic_audits.verdict,
            forensic_audits.evidence
           FROM forensic_audits
          WHERE forensic_audits.run_at = (( SELECT min(runs.run_at) AS min
                   FROM runs)) AND (( SELECT count(*) AS count
                   FROM runs)) > 1
        )
 SELECT c.section,
    c.metric,
    c.value,
    c.value_text,
    c.unit,
    c.responsible,
    c.verdict,
    c.evidence,
    p.value AS previous_value,
        CASE
            WHEN p.value IS NULL THEN 'first audit'::text
            WHEN c.value IS NULL THEN '—'::text
            WHEN c.value < p.value THEN 'improved by '::text || round(p.value - c.value, 1)
            WHEN c.value > p.value THEN 'WORSE by '::text || round(c.value - p.value, 1)
            ELSE 'unchanged'::text
        END AS movement,
    c.run_at
   FROM cur c
     LEFT JOIN prev p ON p.section = c.section AND p.metric = c.metric
  ORDER BY (
        CASE c.verdict
            WHEN 'FAIL'::text THEN 0
            WHEN 'EXPOSURE'::text THEN 1
            WHEN 'BELOW PAR'::text THEN 2
            WHEN 'CASH TIED UP'::text THEN 3
            WHEN 'NO AUTHORITY RECORDED'::text THEN 4
            ELSE 9
        END), c.section, c.metric;
create or replace view public.v_full_accountability as
 WITH harvested AS (
         SELECT to_char(metrc_harvests.harvest_start::timestamp with time zone, 'YYYY-MM'::text) AS month,
            date_trunc('month'::text, metrc_harvests.harvest_start::timestamp with time zone)::date AS month_date,
            metrc_harvests.license,
            sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) AS wet_g,
            sum(COALESCE((metrc_harvests.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric)) AS waste_g,
            sum(COALESCE((metrc_harvests.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric)) AS packaged_g,
            sum(COALESCE((metrc_harvests.raw ->> 'PlantCount'::text)::numeric, 0::numeric)) AS plants,
            count(*) AS harvests
           FROM metrc_harvests
          WHERE metrc_harvests.harvest_start IS NOT NULL
          GROUP BY (to_char(metrc_harvests.harvest_start::timestamp with time zone, 'YYYY-MM'::text)), (date_trunc('month'::text, metrc_harvests.harvest_start::timestamp with time zone)::date), metrc_harvests.license
        ), made AS (
         SELECT to_char(metrc_packages.packaged_on::timestamp with time zone, 'YYYY-MM'::text) AS month,
            metrc_packages.license,
            count(*) AS packages_made,
            count(*) FILTER (WHERE COALESCE(metrc_packages.raw ->> 'ProductCategoryName'::text, ''::text) ~~* '%flower%'::text) AS flower_pkgs,
            count(*) FILTER (WHERE COALESCE(metrc_packages.raw ->> 'ProductCategoryName'::text, ''::text) ~~* '%concentrate%'::text OR COALESCE(metrc_packages.item_name, ''::text) ~~* '%rosin%'::text OR COALESCE(metrc_packages.item_name, ''::text) ~~* '%hash%'::text OR COALESCE(metrc_packages.item_name, ''::text) ~~* '%distillate%'::text OR COALESCE(metrc_packages.item_name, ''::text) ~~* '%crude%'::text) AS concentrate_pkgs,
            count(*) FILTER (WHERE COALESCE(metrc_packages.raw ->> 'ProductCategoryName'::text, ''::text) ~~* '%vape%'::text OR COALESCE(metrc_packages.item_name, ''::text) ~~* '%cart%'::text OR COALESCE(metrc_packages.item_name, ''::text) ~~* '%vape%'::text) AS vape_pkgs,
            count(*) FILTER (WHERE COALESCE(metrc_packages.raw ->> 'ProductCategoryName'::text, ''::text) ~~* '%pre-roll%'::text OR COALESCE(metrc_packages.raw ->> 'ProductCategoryName'::text, ''::text) ~~* '%preroll%'::text OR COALESCE(metrc_packages.item_name, ''::text) ~~* '%preroll%'::text OR COALESCE(metrc_packages.item_name, ''::text) ~~* '%pre-roll%'::text) AS preroll_pkgs,
            sum(COALESCE((metrc_packages.raw ->> 'InitialQuantity'::text)::numeric, 0::numeric)) AS produced_qty,
            sum(COALESCE(metrc_packages.quantity, 0::numeric)) FILTER (WHERE metrc_packages.source_state = ANY (ARRAY['active'::text, 'onhold'::text])) AS still_on_hand,
            sum(COALESCE(metrc_packages.quantity, 0::numeric)) FILTER (WHERE metrc_packages.source_state = 'intransit'::text) AS in_transit_qty,
            sum(COALESCE((metrc_packages.raw ->> 'InitialQuantity'::text)::numeric, 0::numeric)) FILTER (WHERE metrc_packages.source_state = 'inactive'::text) AS closed_or_sold_qty,
            sum(COALESCE(metrc_packages.quantity, 0::numeric)) FILTER (WHERE metrc_packages.lab_testing_state = 'TestFailed'::text) AS failed_qty,
            sum(GREATEST(COALESCE((metrc_packages.raw ->> 'InitialQuantity'::text)::numeric, 0::numeric) - COALESCE(metrc_packages.quantity, 0::numeric), 0::numeric)) FILTER (WHERE metrc_packages.source_state = ANY (ARRAY['active'::text, 'onhold'::text])) AS unexplained_reduction
           FROM metrc_packages
          WHERE metrc_packages.packaged_on IS NOT NULL
          GROUP BY (to_char(metrc_packages.packaged_on::timestamp with time zone, 'YYYY-MM'::text)), metrc_packages.license
        ), sold AS (
         SELECT to_char(metrc_transfers.created_on::timestamp with time zone, 'YYYY-MM'::text) AS month,
            metrc_transfers.license,
            count(*) AS manifests_out,
            sum(COALESCE((metrc_transfers.raw ->> 'PackageCount'::text)::numeric, 0::numeric)) AS packages_shipped,
            count(*) FILTER (WHERE (metrc_transfers.raw ->> 'ReceivedDateTime'::text) IS NULL) AS manifests_unconfirmed
           FROM metrc_transfers
          WHERE metrc_transfers.direction = 'outgoing'::text AND metrc_transfers.created_on IS NOT NULL
          GROUP BY (to_char(metrc_transfers.created_on::timestamp with time zone, 'YYYY-MM'::text)), metrc_transfers.license
        )
 SELECT COALESCE(h.month, m.month, s.month) AS month,
    COALESCE(h.license, m.license, s.license) AS license,
    h.harvests,
    h.plants AS plants_harvested,
    round(h.wet_g / 453.592, 1) AS harvested_wet_lbs,
    round(h.waste_g / 453.592, 1) AS waste_lbs,
        CASE
            WHEN h.wet_g > 0::numeric THEN round(100.0 * h.waste_g / h.wet_g, 1)
            ELSE NULL::numeric
        END AS waste_pct,
    round(h.packaged_g / 453.592, 1) AS packaged_from_harvest_lbs,
    m.packages_made,
    m.flower_pkgs AS flower,
    m.concentrate_pkgs AS concentrates,
    m.vape_pkgs AS vapes,
    m.preroll_pkgs AS prerolls,
    round(m.produced_qty, 1) AS produced_qty,
    round(m.still_on_hand, 1) AS in_stock_qty,
    round(m.in_transit_qty, 1) AS in_transit_qty,
    round(m.closed_or_sold_qty, 1) AS sold_or_closed_qty,
    round(m.failed_qty, 1) AS failed_testing_qty,
    round(COALESCE(m.unexplained_reduction, 0::numeric), 1) AS unaccounted_qty,
    s.manifests_out,
    s.packages_shipped,
    s.manifests_unconfirmed,
        CASE
            WHEN COALESCE(m.unexplained_reduction, 0::numeric) > 0::numeric THEN ('DISCREPANCY - '::text || round(m.unexplained_reduction, 1)) || ' reduced with no recorded reason'::text
            WHEN COALESCE(s.manifests_unconfirmed, 0::bigint) > 0 THEN ('SHIPMENTS UNCONFIRMED - '::text || s.manifests_unconfirmed) || ' manifest(s) not confirmed received'::text
            WHEN COALESCE(m.failed_qty, 0::numeric) > 0::numeric THEN 'FAILED TESTING on hand - decide destruction or remediation'::text
            WHEN h.wet_g > 0::numeric AND (COALESCE(h.waste_g, 0::numeric) / NULLIF(h.wet_g, 0::numeric)) > 0.15 THEN 'HIGH WASTE - above 15 percent of wet weight'::text
            ELSE 'Accounted for'::text
        END AS accountability_status
   FROM harvested h
     FULL JOIN made m ON m.month = h.month AND m.license = h.license
     FULL JOIN sold s ON s.month = COALESCE(h.month, m.month) AND s.license = COALESCE(h.license, m.license)
  WHERE COALESCE(h.month, m.month, s.month) IS NOT NULL
  ORDER BY (COALESCE(h.month, m.month, s.month)) DESC, (COALESCE(h.license, m.license, s.license));
create or replace view public.v_hardcoded_thresholds as
 WITH defs AS (
         SELECT c.relname::text AS object_name,
                CASE c.relkind
                    WHEN 'v'::"char" THEN 'view'::text
                    WHEN 'm'::"char" THEN 'matview'::text
                    ELSE NULL::text
                END AS object_type,
            pg_get_viewdef(c.oid, true) AS body
           FROM pg_class c
             JOIN pg_namespace n ON n.oid = c.relnamespace
          WHERE n.nspname = 'public'::name AND (c.relkind = ANY (ARRAY['v'::"char", 'm'::"char"]))
        UNION ALL
         SELECT p.proname::text AS proname,
            'function'::text,
            pg_get_functiondef(p.oid) AS pg_get_functiondef
           FROM pg_proc p
             JOIN pg_namespace n ON n.oid = p.pronamespace
          WHERE n.nspname = 'public'::name AND p.prokind = 'f'::"char" AND NOT (EXISTS ( SELECT 1
                   FROM pg_depend d_1
                  WHERE d_1.objid = p.oid AND d_1.classid = 'pg_proc'::regclass::oid AND d_1.deptype = 'e'::"char"))
        )
 SELECT d.object_name,
    d.object_type,
    m.column_pattern AS compared_column,
    m.rule_key AS owner_set_rule,
    r.value AS rule_says,
    ((regexp_match(d.body, m.column_pattern || '\s*([<>=]{1,2})\s*([0-9]+(\.[0-9]+)?)'::text))[1] || ' '::text) || (regexp_match(d.body, m.column_pattern || '\s*([<>=]{1,2})\s*([0-9]+(\.[0-9]+)?)'::text))[2] AS hardcoded_as,
    m.why
   FROM defs d
     JOIN threshold_column_map m ON d.body ~ (m.column_pattern || '\s*[<>=]{1,2}\s*[0-9]'::text)
     JOIN conversion_factors r ON r.key = m.rule_key
  WHERE NOT d.body ~* (('f_rule\s*\(\s*'''::text || m.rule_key) || ''''::text) AND d.object_name <> 'v_hardcoded_thresholds'::text
  ORDER BY d.object_type, d.object_name;
create or replace view public.v_harvest_benchmark_note as
 SELECT 'Wet to packaged'::text AS measure,
    '20 to 25 percent'::text AS published_norm,
    'Fresh cannabis is 75-80 percent water. A 4:1 to 5:1 wet:dry ratio is the standard commercial expectation.'::text AS why,
    'Any month above about 30 percent means the wet weight was recorded low, not that yield was high.'::text AS how_to_read
UNION ALL
 SELECT 'Grams per square foot of canopy'::text AS measure,
    '35 g/sq ft start-up, 50 to 70 g/sq ft established'::text AS published_norm,
    'This is the benchmark commercial cultivators actually use, because it is independent of how many plants you put under the light.'::text AS why,
    'Grams per plant is NOT a valid benchmark - it is set by plant density and veg time, not by grower skill.'::text AS how_to_read
UNION ALL
 SELECT 'Plant density'::text AS measure,
    '0.65 to 1.0 flowering plants per square foot'::text AS published_norm,
    'Published bench-production range for indoor and greenhouse.'::text AS why,
    'At this density, 50 g/sq ft works out to roughly 50 to 75 grams per plant - not 130.'::text AS how_to_read;
create or replace view public.v_harvest_enforcement as
 SELECT pull_no,
    harvest_date,
    flower_room,
    room_cycle_no,
    room_cycle_days,
    facility_days_since_last_pull AS facility_gap_days,
        CASE
            WHEN harvest_date < CURRENT_DATE THEN 'past'::text
            WHEN harvest_date <= (CURRENT_DATE + 14) THEN 'upcoming'::text
            ELSE 'scheduled'::text
        END AS horizon,
    room_cycle_days IS NOT NULL AND room_cycle_days <> 56::numeric AS cycle_violation,
    facility_days_since_last_pull IS NOT NULL AND (facility_days_since_last_pull < 13::numeric OR facility_days_since_last_pull > 15::numeric) AS cadence_violation,
    (EXISTS ( SELECT 1
           FROM harvest_weights w
          WHERE w.harvest_date = p.harvest_date AND w.flower_room = p.flower_room)) AS weights_reported,
    harvest_date < CURRENT_DATE AND NOT (EXISTS ( SELECT 1
           FROM harvest_weights w
          WHERE w.harvest_date = p.harvest_date AND w.flower_room = p.flower_room)) AS overdue_reporting,
    (EXISTS ( SELECT 1
           FROM harvest_pulls p2
          WHERE p2.harvest_date = p.harvest_date AND p2.id <> p.id)) AS same_day_overlap,
    day2_replant_date,
    dry_start,
    dry_day_14,
    cultivars
   FROM harvest_pulls p
  ORDER BY harvest_date;
create or replace view public.v_harvest_mass_balance as
 SELECT harvest_date,
    flower_room,
    cultivar,
    actual_wet_lb,
    actual_dry_input_lb,
    grade_a_lb,
    grade_b_lb,
    grade_c_smalls_lb,
    trim_lb,
    fresh_frozen_dry_eq_lb,
    extraction_only_lb,
    samples_retain_lb,
    waste_destruction_lb,
    round(COALESCE(grade_a_lb, 0::numeric) + COALESCE(grade_b_lb, 0::numeric) + COALESCE(grade_c_smalls_lb, 0::numeric) + COALESCE(trim_lb, 0::numeric) + COALESCE(fresh_frozen_dry_eq_lb, 0::numeric) + COALESCE(extraction_only_lb, 0::numeric) + COALESCE(samples_retain_lb, 0::numeric) + COALESCE(waste_destruction_lb, 0::numeric), 3) AS total_accounted_lb,
        CASE
            WHEN COALESCE(actual_dry_input_lb, 0::numeric) > 0::numeric THEN round(actual_dry_input_lb - (COALESCE(grade_a_lb, 0::numeric) + COALESCE(grade_b_lb, 0::numeric) + COALESCE(grade_c_smalls_lb, 0::numeric) + COALESCE(trim_lb, 0::numeric) + COALESCE(fresh_frozen_dry_eq_lb, 0::numeric) + COALESCE(extraction_only_lb, 0::numeric) + COALESCE(samples_retain_lb, 0::numeric) + COALESCE(waste_destruction_lb, 0::numeric)), 3)
            ELSE NULL::numeric
        END AS unaccounted_variance_lb,
        CASE
            WHEN COALESCE(actual_dry_input_lb, 0::numeric) > 0::numeric THEN round(100.0 * (COALESCE(grade_a_lb, 0::numeric) + COALESCE(grade_b_lb, 0::numeric) + COALESCE(grade_c_smalls_lb, 0::numeric) + COALESCE(trim_lb, 0::numeric) + COALESCE(fresh_frozen_dry_eq_lb, 0::numeric) + COALESCE(extraction_only_lb, 0::numeric) + COALESCE(samples_retain_lb, 0::numeric) + COALESCE(waste_destruction_lb, 0::numeric)) / actual_dry_input_lb, 1)
            ELSE NULL::numeric
        END AS mass_balance_pct,
        CASE
            WHEN COALESCE(actual_dry_input_lb, 0::numeric) > 0::numeric THEN round(100.0 * (COALESCE(grade_a_lb, 0::numeric) + COALESCE(grade_b_lb, 0::numeric) + COALESCE(grade_c_smalls_lb, 0::numeric) + COALESCE(trim_lb, 0::numeric) + COALESCE(fresh_frozen_dry_eq_lb, 0::numeric) + COALESCE(extraction_only_lb, 0::numeric) + COALESCE(samples_retain_lb, 0::numeric)) / actual_dry_input_lb, 1)
            ELSE NULL::numeric
        END AS saleable_yield_pct,
        CASE
            WHEN COALESCE(actual_dry_input_lb, 0::numeric) > 0::numeric THEN round(100.0 * COALESCE(grade_a_lb, 0::numeric) / actual_dry_input_lb, 1)
            ELSE NULL::numeric
        END AS grade_a_pct,
        CASE
            WHEN COALESCE(actual_dry_input_lb, 0::numeric) > 0::numeric THEN round(100.0 * COALESCE(grade_b_lb, 0::numeric) / actual_dry_input_lb, 1)
            ELSE NULL::numeric
        END AS grade_b_pct,
        CASE
            WHEN COALESCE(actual_dry_input_lb, 0::numeric) > 0::numeric THEN round(100.0 * COALESCE(grade_c_smalls_lb, 0::numeric) / actual_dry_input_lb, 1)
            ELSE NULL::numeric
        END AS grade_c_pct,
        CASE
            WHEN COALESCE(actual_dry_input_lb, 0::numeric) > 0::numeric THEN round(100.0 * COALESCE(trim_lb, 0::numeric) / actual_dry_input_lb, 1)
            ELSE NULL::numeric
        END AS trim_pct,
        CASE
            WHEN COALESCE(canopy_sqft, 0::numeric) > 0::numeric AND COALESCE(actual_dry_input_lb, 0::numeric) > 0::numeric THEN round(actual_dry_input_lb * 453.592 / canopy_sqft, 1)
            ELSE NULL::numeric
        END AS actual_g_sqft,
    metrc_harvest_batch,
    qa_release_status,
    status,
    entered_by,
    verified_by,
    verified_date
   FROM harvest_weights
  ORDER BY harvest_date DESC;
create or replace view public.v_harvest_plan_vs_actual as
 WITH plan AS (
         SELECT p.pull_no,
            p.harvest_date,
            p.flower_room,
            p.cultivars,
            p.original_total_plants AS planned_plants,
            p.proj_harvest_weight_lbs AS planned_lbs,
            p.dry_day_14 AS dry_deadline
           FROM harvest_pulls p
        ), act AS (
         SELECT h.harvest_start,
            COALESCE(h.raw ->> 'DryingLocationName'::text, ''::text) AS room,
            sum((h.raw ->> 'PlantCount'::text)::numeric) AS actual_plants,
            sum(COALESCE((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) AS actual_wet_g,
            sum(COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric)) AS actual_packaged_g,
            sum(COALESCE((h.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric)) AS actual_waste_g,
            count(*) AS harvest_records,
            string_agg(DISTINCT h.name, ', '::text) AS harvests
           FROM metrc_harvests h
          WHERE h.harvest_start IS NOT NULL
          GROUP BY h.harvest_start, (COALESCE(h.raw ->> 'DryingLocationName'::text, ''::text))
        )
 SELECT pl.pull_no,
    pl.harvest_date AS planned_date,
    pl.flower_room,
    pl.cultivars,
    pl.planned_plants,
    round(pl.planned_lbs, 1) AS planned_lbs,
    a.harvest_start AS actual_date,
    a.room AS actual_room,
    a.harvests,
    a.actual_plants,
    round(a.actual_wet_g / 453.592, 1) AS actual_wet_lbs,
    round(a.actual_packaged_g / 453.592, 1) AS actual_packaged_lbs,
    round(a.actual_waste_g / 453.592, 1) AS actual_waste_lbs,
        CASE
            WHEN a.harvest_start IS NULL THEN 'NOT HARVESTED'::text
            WHEN a.harvest_start > pl.harvest_date THEN ('Late by '::text || (a.harvest_start - pl.harvest_date)) || ' days'::text
            WHEN a.harvest_start < pl.harvest_date THEN ('Early by '::text || (pl.harvest_date - a.harvest_start)) || ' days'::text
            ELSE 'On plan'::text
        END AS timing,
        CASE
            WHEN a.actual_plants IS NOT NULL AND pl.planned_plants > 0::numeric THEN round(100.0 * a.actual_plants / pl.planned_plants, 1)
            ELSE NULL::numeric
        END AS plants_pct_of_plan,
        CASE
            WHEN a.actual_packaged_g > 0::numeric AND pl.planned_lbs > 0::numeric THEN round(100.0 * (a.actual_packaged_g / 453.592) / pl.planned_lbs, 1)
            ELSE NULL::numeric
        END AS weight_pct_of_plan,
    pl.dry_deadline
   FROM plan pl
     LEFT JOIN act a ON a.harvest_start >= (pl.harvest_date - 4) AND a.harvest_start <= (pl.harvest_date + 10)
  ORDER BY pl.harvest_date DESC;
create or replace view public.v_harvest_pull_link as
 WITH h AS (
         SELECT mh.id,
            mh.name,
            mh.harvest_start,
            mh.wet_weight,
            mh.waste_weight,
            mh.package_count,
            "substring"(mh.name, '(\d{8})'::text) AS name_date_token,
            'F'::text || "substring"(regexp_replace(mh.name, '^.*\d{8}'::text, ''::text), '[fF] ?([1-4])'::text) AS room_actual,
            mh.name ~* '(^|[^a-z])FF([^a-z]|$)'::text AS is_fresh_frozen
           FROM metrc_harvests mh
        )
 SELECT h.id AS harvest_id,
    h.name AS harvest_name,
    h.harvest_start AS takedown_date,
    h.room_actual,
    p.flower_room AS room_planned,
    h.is_fresh_frozen,
    p.pull_no,
    p.harvest_date AS pull_planned_date,
    h.harvest_start - p.harvest_date AS days_from_planned_pull,
    p.planned_plants,
    p.projected_flower_after_ff_lb,
    h.wet_weight,
    h.package_count,
        CASE
            WHEN p.pull_no IS NOT NULL AND h.room_actual IS NULL THEN 'Linked on date. Room unknown - the name carries no room, which is true of all 2024 harvests, before the naming convention existed.'::text
            WHEN p.pull_no IS NOT NULL AND h.room_actual IS DISTINCT FROM p.flower_room THEN ((('Linked on date. ROOM DRIFTED - the plan expected '::text || p.flower_room) || ', the harvest name says '::text) || h.room_actual) || '. The rotation has moved; the date is what actually happened.'::text
            WHEN p.pull_no IS NOT NULL THEN 'Linked on date, and the room agrees with the plan.'::text
            WHEN h.harvest_start < '2026-01-01'::date THEN 'Not linked - harvest_plan_2026 covers 2026 only. This harvest predates the plan and no pull exists to attach it to.'::text
            WHEN h.harvest_start > (( SELECT max(harvest_plan_2026.harvest_date) AS max
               FROM harvest_plan_2026)) THEN 'Not linked - takedown is after the last planned pull of 2026.'::text
            ELSE ('NOT LINKED - no planned pull within the '::text || COALESCE(f_rule('pull_link_window_days'::text)::text, '?'::text)) || '-day matching window. Investigate: either a pull happened off-calendar, or the takedown date is wrong.'::text
        END AS link_note,
        CASE
            WHEN h.name_date_token IS NULL THEN 'Name carries no readable 8-digit date'::text
            WHEN to_date(h.name_date_token, 'YYYYMMDD'::text) <> h.harvest_start THEN ((('Name says '::text || h.name_date_token) || ', Metrc says '::text) || h.harvest_start) || ' - Metrc wins'::text
            ELSE NULL::text
        END AS name_date_disagreement
   FROM h
     LEFT JOIN LATERAL ( SELECT p2.pull_no,
            p2.harvest_date,
            p2.day_of_week,
            p2.flower_room,
            p2.room_cycle_no,
            p2.room_cycle_days,
            p2.facility_days_since_last_pull,
            p2.planned_plants,
            p2.projected_harvest_g,
            p2.projected_harvest_lb,
            p2.projected_fresh_frozen_lb,
            p2.projected_flower_after_ff_lb,
            p2.operating_est_room_plants,
            p2.tables,
            p2.plants_per_table,
            p2.source
           FROM harvest_plan_2026 p2
          WHERE abs(h.harvest_start - p2.harvest_date)::numeric <= COALESCE(f_rule('pull_link_window_days'::text), 7::numeric)
          ORDER BY (abs(h.harvest_start - p2.harvest_date)), p2.pull_no
         LIMIT 1) p ON true;
create or replace view public.v_harvest_reconciliation as
 WITH plan AS (
         SELECT harvest_schedule.harvest_date,
            harvest_schedule.flower_room,
            count(*) AS planned_cultivars,
            sum(harvest_schedule.plants) AS planned_plants,
            round(sum(harvest_schedule.projected_weight_lbs), 1) AS planned_lbs,
            round(sum(harvest_schedule.fresh_frozen_lbs), 1) AS planned_ff_lbs
           FROM harvest_schedule
          GROUP BY harvest_schedule.harvest_date, harvest_schedule.flower_room
        ), actual AS (
         SELECT metrc_harvests.harvest_start AS harvest_date,
            count(*) AS metrc_harvests,
            round(sum(metrc_harvests.wet_weight) / 453.592, 1) AS metrc_wet_lbs,
            round(sum(metrc_harvests.waste_weight) / 453.592, 1) AS metrc_waste_lbs,
            sum(metrc_harvests.package_count) AS metrc_packages,
            round(sum(COALESCE((metrc_harvests.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric)) / 453.592, 1) AS metrc_packaged_lbs,
            round(sum(COALESCE((metrc_harvests.raw ->> 'TotalRestoredWeight'::text)::numeric, 0::numeric)) / 453.592, 1) AS metrc_restored_lbs
           FROM metrc_harvests
          GROUP BY metrc_harvests.harvest_start
        )
 SELECT COALESCE(p.harvest_date, a.harvest_date) AS harvest_date,
    p.flower_room,
    p.planned_cultivars,
    p.planned_plants,
    p.planned_lbs,
    p.planned_ff_lbs,
    a.metrc_harvests,
    a.metrc_wet_lbs,
    a.metrc_waste_lbs,
    a.metrc_packaged_lbs,
    a.metrc_packages,
        CASE
            WHEN p.harvest_date IS NOT NULL AND a.harvest_date IS NULL AND p.harvest_date < CURRENT_DATE THEN 'MISSING IN METRC'::text
            WHEN p.harvest_date IS NOT NULL AND a.harvest_date IS NULL THEN 'SCHEDULED'::text
            WHEN p.harvest_date IS NULL THEN 'IN METRC, NOT PLANNED'::text
            WHEN a.metrc_wet_lbs IS NOT NULL AND p.planned_lbs > 0::numeric THEN ('RECONCILED '::text || round(100.0 * a.metrc_wet_lbs / p.planned_lbs)) || '% of plan'::text
            ELSE 'RECONCILED'::text
        END AS reconciliation,
        CASE
            WHEN a.metrc_wet_lbs IS NOT NULL AND p.planned_lbs > 0::numeric THEN round(a.metrc_wet_lbs - p.planned_lbs, 1)
            ELSE NULL::numeric
        END AS variance_lbs
   FROM plan p
     FULL JOIN actual a ON a.harvest_date = p.harvest_date
  ORDER BY (COALESCE(p.harvest_date, a.harvest_date)) DESC;
create or replace view public.v_harvest_report as
 SELECT name AS harvest,
    harvest_start AS cut_date,
    upper("substring"(regexp_replace(upper(name), '\s'::text, ''::text, 'g'::text), 'F[1-4]'::text)) AS room,
    COALESCE(NULLIF(raw ->> 'SourceStrainNames'::text, ''::text), '(not recorded)'::text) AS strain,
    (raw ->> 'PlantCount'::text)::integer AS plants,
    round(wet_weight / 453.592, 1) AS wet_lb,
    round(((raw ->> 'TotalPackagedWeight'::text)::numeric) / 453.592, 1) AS packaged_lb,
    round(((raw ->> 'TotalPackagedWeight'::text)::numeric) / NULLIF((raw ->> 'PlantCount'::text)::integer, 0)::numeric, 1) AS grams_per_plant,
    f_rule_at('harvest_goal_lb'::text, harvest_start::timestamp with time zone) AS goal_lb,
    round(((raw ->> 'TotalPackagedWeight'::text)::numeric) / 453.592 - f_rule_at('harvest_goal_lb'::text, harvest_start::timestamp with time zone), 1) AS vs_goal_lb,
        CASE
            WHEN (raw ->> 'FinishedDate'::text) IS NULL THEN 'STILL OPEN — cannot be judged yet'::text
            WHEN name ~~* '%FF%'::text OR COALESCE(raw ->> 'DryingLocationName'::text, ''::text) ~~* '%freezer%'::text THEN 'Fresh frozen — not judged against the dried flower goal'::text
            WHEN (((raw ->> 'TotalPackagedWeight'::text)::numeric) / 453.592) >= f_rule_at('harvest_goal_lb'::text, harvest_start::timestamp with time zone) THEN 'MET the goal'::text
            ELSE ('SHORT by '::text || round(f_rule_at('harvest_goal_lb'::text, harvest_start::timestamp with time zone) - ((raw ->> 'TotalPackagedWeight'::text)::numeric) / 453.592, 1)) || ' lb'::text
        END AS verdict,
    (raw ->> 'FinishedDate'::text)::date AS closed_on,
    COALESCE(raw ->> 'DryingLocationName'::text, '(not recorded)'::text) AS dried_in
   FROM metrc_harvests h
  WHERE wet_weight > 0::numeric;
create or replace view public.v_harvest_stage_map as
 SELECT license,
    harvest,
    harvest_type,
    room,
    sub_room,
    strains,
    plants,
    harvest_start,
    finished_on,
    stage,
    days_since_takedown,
    wet_weight,
    current_weight,
    waste_weight,
    packaged_weight,
    restored_weight,
    waste_pct,
    yield_pct,
    uom,
    packages_created,
    lab_state,
    packages_traced,
    source_state,
    f_stock_status(source_state, NULL::boolean) AS stock_status
   FROM ( SELECT h.license,
            h.name AS harvest,
            h.raw ->> 'HarvestType'::text AS harvest_type,
            h.raw ->> 'DryingLocationName'::text AS room,
            h.raw ->> 'DryingSublocationName'::text AS sub_room,
            h.raw ->> 'SourceStrainNames'::text AS strains,
            (h.raw ->> 'PlantCount'::text)::numeric AS plants,
            h.harvest_start,
            (h.raw ->> 'FinishedDate'::text)::date AS finished_on,
                CASE
                    WHEN (h.raw ->> 'ArchivedDate'::text) IS NOT NULL THEN 'Archived'::text
                    WHEN (h.raw ->> 'IsOnHold'::text)::boolean THEN 'ON HOLD'::text
                    WHEN (h.raw ->> 'IsOnInvestigation'::text)::boolean THEN 'UNDER INVESTIGATION'::text
                    WHEN (h.raw ->> 'FinishedDate'::text) IS NOT NULL THEN 'Finished'::text
                    WHEN COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) > 0::numeric THEN 'Packaging'::text
                    WHEN h.harvest_start IS NOT NULL AND h.harvest_start > (CURRENT_DATE - 10) THEN ('Drying (day '::text || ((CURRENT_DATE - h.harvest_start)::text)) || ' of 10-14)'::text
                    WHEN h.harvest_start IS NOT NULL THEN 'Curing / Trim'::text
                    ELSE 'Recorded'::text
                END AS stage,
                CASE
                    WHEN h.harvest_start IS NOT NULL THEN CURRENT_DATE - h.harvest_start
                    ELSE NULL::integer
                END AS days_since_takedown,
            (h.raw ->> 'TotalWetWeight'::text)::numeric AS wet_weight,
            (h.raw ->> 'CurrentWeight'::text)::numeric AS current_weight,
            (h.raw ->> 'TotalWasteWeight'::text)::numeric AS waste_weight,
            (h.raw ->> 'TotalPackagedWeight'::text)::numeric AS packaged_weight,
            (h.raw ->> 'TotalRestoredWeight'::text)::numeric AS restored_weight,
                CASE
                    WHEN COALESCE((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric) > 0::numeric THEN round(100.0 * COALESCE((h.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric) / ((h.raw ->> 'TotalWetWeight'::text)::numeric), 1)
                    ELSE NULL::numeric
                END AS waste_pct,
                CASE
                    WHEN COALESCE((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric) > 0::numeric THEN round(100.0 * COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) / ((h.raw ->> 'TotalWetWeight'::text)::numeric), 1)
                    ELSE NULL::numeric
                END AS yield_pct,
            h.raw ->> 'UnitOfWeightName'::text AS uom,
            (h.raw ->> 'PackageCount'::text)::numeric AS packages_created,
            h.raw ->> 'LabTestingState'::text AS lab_state,
            ( SELECT count(*) AS count
                   FROM metrc_packages p
                  WHERE p.license = h.license AND (p.raw ->> 'SourceHarvestNames'::text) ~~ (('%'::text || h.name) || '%'::text)) AS packages_traced,
            h.source_state
           FROM metrc_harvests h) q;
create or replace view public.v_hr_activity as
 SELECT 'punch_in'::text AS kind,
    t.clock_in AS at,
    t.employee_id,
    e.full_name,
    COALESCE(d.name, '—'::text) AS department,
    ('Clocked in via '::text || COALESCE(t.source, 'unknown'::text)) ||
        CASE
            WHEN COALESCE(t.late_minutes, 0) > 0 THEN (' — '::text || t.late_minutes) || ' min late'::text
            ELSE ''::text
        END AS detail,
        CASE
            WHEN COALESCE(t.late_minutes, 0) > 0 THEN 'warn'::text
            ELSE 'ok'::text
        END AS tone,
    t.id::text AS ref
   FROM time_entries t
     JOIN employees e ON e.id = t.employee_id
     LEFT JOIN departments d ON d.id = e.primary_department_id
  WHERE t.clock_in IS NOT NULL
UNION ALL
 SELECT 'punch_out'::text AS kind,
    t.clock_out AS at,
    t.employee_id,
    e.full_name,
    COALESCE(d.name, '—'::text) AS department,
    ('Clocked out — '::text || round(EXTRACT(epoch FROM t.clock_out - t.clock_in) / 3600.0 - COALESCE(t.unpaid_lunch_min, 0)::numeric / 60.0, 2)) || ' h worked'::text AS detail,
    'ok'::text AS tone,
    t.id::text AS ref
   FROM time_entries t
     JOIN employees e ON e.id = t.employee_id
     LEFT JOIN departments d ON d.id = e.primary_department_id
  WHERE t.clock_out IS NOT NULL
UNION ALL
 SELECT 'callout'::text AS kind,
    c.called_at AS at,
    c.employee_id,
    e.full_name,
    COALESCE(d.name, '—'::text) AS department,
    ('Called out — '::text || c.reason_code) ||
        CASE
            WHEN c.meets_notice THEN ' (proper notice)'::text
            ELSE ' (short notice)'::text
        END AS detail,
        CASE
            WHEN c.meets_notice THEN 'warn'::text
            ELSE 'bad'::text
        END AS tone,
    c.id::text AS ref
   FROM callouts c
     JOIN employees e ON e.id = c.employee_id
     LEFT JOIN departments d ON d.id = e.primary_department_id
UNION ALL
 SELECT 'occurrence'::text AS kind,
    o.created_at AS at,
    o.employee_id,
    e.full_name,
    COALESCE(d.name, '—'::text) AS department,
    (((o.kind || ' — '::text) || o.points) || ' points'::text) || COALESCE(' · '::text || o.reason_code, ''::text) AS detail,
    'bad'::text AS tone,
    o.id::text AS ref
   FROM attendance_occurrences o
     JOIN employees e ON e.id = o.employee_id
     LEFT JOIN departments d ON d.id = e.primary_department_id
UNION ALL
 SELECT 'claim'::text AS kind,
    sc.claimed_at AS at,
    sc.employee_id,
    e.full_name,
    COALESCE(d.name, '—'::text) AS department,
    'Claimed an open shift'::text ||
        CASE
            WHEN sc.would_be_overtime THEN ' — would be overtime'::text
            ELSE ''::text
        END AS detail,
        CASE
            WHEN sc.would_be_overtime THEN 'warn'::text
            ELSE 'ok'::text
        END AS tone,
    sc.id::text AS ref
   FROM shift_claims sc
     JOIN employees e ON e.id = sc.employee_id
     LEFT JOIN departments d ON d.id = e.primary_department_id
UNION ALL
 SELECT 'schedule_posted'::text AS kind,
    sd.posted_at AS at,
    NULL::uuid AS employee_id,
    COALESCE(u.email, 'a manager'::character varying) AS full_name,
    COALESCE(dd.name, 'All'::text) AS department,
    ((((('Posted '::text || sd.title) || ' ('::text) || sd.covers_from) || ' to '::text) || sd.covers_to) || ')'::text AS detail,
    'ok'::text AS tone,
    sd.id::text AS ref
   FROM schedule_drafts sd
     LEFT JOIN departments dd ON dd.id = sd.department_id
     LEFT JOIN auth.users u ON u.id = sd.posted_by
  WHERE sd.posted_at IS NOT NULL
UNION ALL
 SELECT 'document_signed'::text AS kind,
    a.signed_at AS at,
    a.employee_id,
    e.full_name,
    COALESCE(d.name, '—'::text) AS department,
    (('Signed '::text || doc.title) || ' v'::text) || a.document_version AS detail,
    'ok'::text AS tone,
    a.id::text AS ref
   FROM hr_document_acknowledgements a
     JOIN employees e ON e.id = a.employee_id
     JOIN hr_documents doc ON doc.id = a.document_id
     LEFT JOIN departments d ON d.id = e.primary_department_id
  WHERE a.signed_at IS NOT NULL
UNION ALL
 SELECT 'incident'::text AS kind,
    i.reported_at AS at,
    i.involved_employee AS employee_id,
    COALESCE(e.full_name, '—'::text) AS full_name,
    '—'::text AS department,
    ((upper(i.kind) || ' — '::text) || i.severity) ||
        CASE
            WHEN i.osha_recordable THEN ' · OSHA recordable'::text
            ELSE ''::text
        END AS detail,
        CASE
            WHEN i.severity = ANY (ARRAY['high'::text, 'critical'::text]) THEN 'bad'::text
            ELSE 'warn'::text
        END AS tone,
    i.id::text AS ref
   FROM hr_incidents i
     LEFT JOIN employees e ON e.id = i.involved_employee;
create or replace view public.v_hr_delivery_backlog as
 SELECT 'message'::text AS what,
    m.id::text AS id,
    m.subject AS title,
    m.approved_at,
    NULL::text AS error,
        CASE
            WHEN m.employee_id IS NULL THEN 'waiting: audience delivery not built'::text
            ELSE 'waiting to send'::text
        END AS standing
   FROM hr_message m
  WHERE m.approved_at IS NOT NULL AND m.sent_at IS NULL AND m.cancelled_at IS NULL
UNION ALL
 SELECT 'workspace task'::text AS what,
    t.id::text AS id,
    t.title,
    t.created_at AS approved_at,
    t.error,
        CASE t.status
            WHEN 'failed'::text THEN 'failed - '::text || COALESCE(t.error, 'no reason recorded'::text)
            ELSE 'waiting to push'::text
        END AS standing
   FROM hr_external_task t
  WHERE t.status = ANY (ARRAY['pending'::text, 'failed'::text])
  ORDER BY 4;
create or replace view public.v_hr_delivery_open as
 SELECT m.id,
    m.kind,
    m.subject,
    m.audience,
    m.approved_at,
    COALESCE(e.full_name, m.audience, 'unspecified'::text) AS intended,
    ( SELECT count(*) AS count
           FROM hr_message_recipient r
          WHERE r.message_id = m.id) AS recipients,
    ( SELECT count(*) AS count
           FROM hr_message_recipient r
          WHERE r.message_id = m.id AND r.delivered_at IS NOT NULL) AS delivered,
    ( SELECT count(*) AS count
           FROM hr_message_recipient r
          WHERE r.message_id = m.id AND r.read_at IS NOT NULL) AS read_count,
        CASE
            WHEN m.sent_at IS NOT NULL THEN 'sent'::text
            WHEN m.approved_at IS NULL THEN 'awaiting approval'::text
            WHEN NOT (EXISTS ( SELECT 1
               FROM f_resolve_audience(m.audience, m.employee_id) f_resolve_audience(f_resolve_audience))) THEN 'AUDIENCE MATCHES NOBODY'::text
            ELSE 'approved, waiting to send'::text
        END AS state
   FROM hr_message m
     LEFT JOIN employees e ON e.id = m.employee_id
  WHERE m.cancelled_at IS NULL;
create or replace view public.v_hr_document_standing as
 SELECT d.id AS document_id,
    d.title,
    d.kind,
    d.version,
    d.requires_signature,
    a.employee_id,
    a.due_on,
    ack.signed_at IS NOT NULL AS signed,
    ack.signed_at,
    ( SELECT count(*) AS count
           FROM hr_document_sections s
          WHERE s.document_id = d.id) AS sections,
    ( SELECT count(DISTINCT p.section_id) AS count
           FROM hr_document_progress p
          WHERE p.document_id = d.id AND p.employee_id = a.employee_id) AS sections_read,
        CASE
            WHEN ack.signed_at IS NOT NULL THEN 'done'::text
            WHEN a.due_on IS NOT NULL AND a.due_on < CURRENT_DATE THEN 'overdue'::text
            WHEN (( SELECT count(DISTINCT p.section_id) AS count
               FROM hr_document_progress p
              WHERE p.document_id = d.id AND p.employee_id = a.employee_id)) = 0 THEN 'not started'::text
            ELSE 'in progress'::text
        END AS standing
   FROM hr_documents d
     JOIN hr_document_assignments a ON a.document_id = d.id
     LEFT JOIN hr_document_acknowledgements ack ON ack.document_id = d.id AND ack.employee_id = a.employee_id AND ack.document_version = d.version
  WHERE d.retired_at IS NULL;
create or replace view public.v_hr_waiting_on_a_person as
 SELECT id,
    created_at,
    agent,
    kind,
    severity,
    agent_confidence,
    employee_id,
    headline,
    policy_basis,
    draft_body IS NOT NULL AS has_a_draft,
    defer_until,
        CASE
            WHEN severity = 'urgent'::text THEN 'Decide today'::text
            WHEN kind ~~* '%write%up%'::text OR kind ~~* '%discipl%'::text THEN 'Read every line - this becomes part of an employment record'::text
            WHEN agent_confidence = 'unsure'::text THEN 'The agent is not sure. Check it before approving.'::text
            ELSE 'Routine - but still a decision'::text
        END AS how_to_treat_it
   FROM hr_review_queue q
  WHERE status = 'waiting'::text AND (defer_until IS NULL OR defer_until <= now())
  ORDER BY (
        CASE severity
            WHEN 'urgent'::text THEN 0
            WHEN 'elevated'::text THEN 1
            ELSE 2
        END), (
        CASE
            WHEN agent_confidence = 'unsure'::text THEN 0
            ELSE 1
        END), created_at;
create or replace view public.v_import_outliers as
 WITH tot AS (
         SELECT 'wholesale_transfers'::text AS report,
            sum(metrc_rpt_wholesale.amount) AS total,
            count(*) AS rows
           FROM metrc_rpt_wholesale
          WHERE NOT metrc_rpt_wholesale.voided
        UNION ALL
         SELECT 'packages_transferred'::text,
            sum(metrc_rpt_package_transfers.shipper_wholesale_price) AS sum,
            count(*) AS count
           FROM metrc_rpt_package_transfers
          WHERE metrc_rpt_package_transfers.shipper_wholesale_price IS NOT NULL
        )
 SELECT 'wholesale_transfers'::text AS report,
    w.manifest_number AS reference,
    w.item AS detail,
    w.amount AS value,
    t.total,
    round(100.0 * w.amount / NULLIF(t.total, 0::numeric), 2) AS pct_of_total,
    'A single line carrying more than a twentieth of the total is usually a report footer that '::text || 'was read as a transaction, not a real sale.'::text AS why_it_matters
   FROM metrc_rpt_wholesale w
     CROSS JOIN ( SELECT tot.total
           FROM tot
          WHERE tot.report = 'wholesale_transfers'::text) t
  WHERE NOT w.voided AND w.amount > (0.05 * t.total)
UNION ALL
 SELECT 'packages_transferred'::text AS report,
    p.manifest_number AS reference,
    p.item AS detail,
    p.shipper_wholesale_price AS value,
    t.total,
    round(100.0 * p.shipper_wholesale_price / NULLIF(t.total, 0::numeric), 2) AS pct_of_total,
    'A single package priced above a twentieth of all wholesale value needs a second look.'::text AS why_it_matters
   FROM metrc_rpt_package_transfers p
     CROSS JOIN ( SELECT tot.total
           FROM tot
          WHERE tot.report = 'packages_transferred'::text) t
  WHERE p.shipper_wholesale_price > (0.05 * t.total)
  ORDER BY 6 DESC;
create or replace view public.v_intelligence_briefing as
 WITH ranked AS (
         SELECT f.id,
            f.run_id,
            f.observed_at,
            f.fingerprint,
            f.severity,
            f.what,
            f.where_it_is,
            f.who_is_accountable,
            f.when_it_started,
            f.why_it_matters,
            f.how_it_was_detected,
            f.what_to_do,
            f.the_arithmetic,
            f.evidence,
            f.record_count,
            f.pounds,
            f.dollars,
            f.drill,
            f.search_text,
            row_number() OVER (PARTITION BY f.fingerprint ORDER BY f.observed_at DESC) AS rn,
            min(f.observed_at) OVER (PARTITION BY f.fingerprint)::date AS first_found_on,
            count(*) OVER (PARTITION BY f.fingerprint) AS times_found
           FROM watchdog_findings f
        )
 SELECT severity,
    what AS finding,
    where_it_is,
    who_is_accountable,
    when_it_started,
    why_it_matters,
    how_it_was_detected,
    what_to_do,
    the_arithmetic,
    record_count AS records_affected,
    pounds,
    dollars,
    drill,
    observed_at::date AS found_on,
    first_found_on,
    times_found,
    CURRENT_DATE - first_found_on AS days_open,
    NULLIF((regexp_match((((COALESCE(when_it_started, ''::text) || ' '::text) || COALESCE(what, ''::text)) || ' '::text) || COALESCE(the_arithmetic, ''::text), '(\d+)\s*days?'::text))[1], ''::text)::integer AS material_oldest_days,
        CASE
            WHEN times_found = 1 AND (CURRENT_DATE - first_found_on) = 0 THEN (('First sweep to record this finding was '::text || to_char(first_found_on::timestamp with time zone, 'DD Mon YYYY'::text)) || ', so there is no earlier history to compare against yet. The age shown is the age '::text) || 'of the material itself, not of the finding.'::text
            ELSE ((('Raised '::text || to_char(first_found_on::timestamp with time zone, 'DD Mon YYYY'::text)) || ' and confirmed on '::text) || times_found) || ' sweeps since.'::text
        END AS history_note,
    evidence
   FROM ranked
  WHERE rn = 1 AND observed_at > (now() - '48:00:00'::interval)
  ORDER BY (
        CASE severity
            WHEN 'critical'::text THEN 1
            WHEN 'elevated'::text THEN 2
            ELSE 3
        END), (COALESCE(dollars, 0::numeric)) DESC;
create or replace view public.v_inventory_alert_history as
 SELECT severity,
    area,
    headline,
    detail,
    pounds,
    dollars,
    raised,
    resolved,
    days_to_resolve,
    resolved_by,
    resolution_note,
    times_seen,
    raised AS raised_date
   FROM ( SELECT inventory_alerts.severity,
            inventory_alerts.area,
            inventory_alerts.headline,
            inventory_alerts.detail,
            inventory_alerts.pounds,
            inventory_alerts.dollars,
            inventory_alerts.first_raised::date AS raised,
            inventory_alerts.resolved_at::date AS resolved,
            inventory_alerts.resolved_at::date - inventory_alerts.first_raised::date AS days_to_resolve,
            COALESCE(inventory_alerts.resolved_by, 'still open'::text) AS resolved_by,
            inventory_alerts.resolution_note,
            inventory_alerts.times_seen
           FROM inventory_alerts
          ORDER BY inventory_alerts.first_raised DESC) q;
create or replace view public.v_inventory_alerts as
 SELECT severity,
    area,
    headline,
    detail,
    what_to_do,
    drill,
    pounds,
    dollars,
    days_open,
    times_seen,
    raised,
    material_oldest_days,
    raised AS raised_date
   FROM ( SELECT inventory_alerts.severity,
            inventory_alerts.area,
            inventory_alerts.headline,
            inventory_alerts.detail,
            inventory_alerts.what_to_do,
            inventory_alerts.drill,
            inventory_alerts.pounds,
            inventory_alerts.dollars,
            CURRENT_DATE - inventory_alerts.first_raised::date AS days_open,
            inventory_alerts.times_seen,
            inventory_alerts.first_raised::date AS raised,
            NULLIF((regexp_match((COALESCE(inventory_alerts.detail, ''::text) || ' '::text) || COALESCE(inventory_alerts.headline, ''::text), '(\d+)\s*days?'::text))[1], ''::text)::integer AS material_oldest_days
           FROM inventory_alerts
          WHERE inventory_alerts.resolved_at IS NULL
          ORDER BY (
                CASE inventory_alerts.severity
                    WHEN 'critical'::text THEN 1
                    WHEN 'elevated'::text THEN 2
                    ELSE 3
                END), (COALESCE(inventory_alerts.dollars, 0::numeric)) DESC) q;
create or replace view public.v_inventory_reconciliation as
 WITH base AS (
         SELECT p.license,
            COALESCE(p.item_name, '(unnamed item)'::text) AS item,
            p.source_state,
            p.lab_testing_state,
            COALESCE(p.quantity, 0::numeric) AS qty,
            COALESCE((p.raw ->> 'InitialQuantity'::text)::numeric, COALESCE(p.quantity, 0::numeric)) AS initial_qty,
            (p.raw ->> 'IsOnHold'::text)::boolean AS on_hold,
            p.raw ->> 'ArchivedDate'::text AS archived
           FROM metrc_packages p
        )
 SELECT license,
    item,
    round(sum(initial_qty), 1) AS packaged_originally,
    round(sum(qty) FILTER (WHERE source_state = 'active'::text AND NOT COALESCE(on_hold, false)), 1) AS in_stock_sellable,
    round(sum(qty) FILTER (WHERE COALESCE(on_hold, false) OR source_state = 'onhold'::text), 1) AS on_hold,
    round(sum(qty) FILTER (WHERE source_state = 'intransit'::text), 1) AS in_transit,
    round(sum(initial_qty) FILTER (WHERE source_state = 'inactive'::text), 1) AS closed_or_sold,
    round(sum(qty) FILTER (WHERE lab_testing_state = 'TestFailed'::text), 1) AS failed_testing_held,
    round(sum(initial_qty - qty) FILTER (WHERE source_state = ANY (ARRAY['active'::text, 'onhold'::text])), 1) AS reduced_without_reason,
        CASE
            WHEN sum(initial_qty - qty) FILTER (WHERE source_state = ANY (ARRAY['active'::text, 'onhold'::text])) > 0::numeric THEN ('UNACCOUNTED - '::text || round(sum(initial_qty - qty) FILTER (WHERE source_state = ANY (ARRAY['active'::text, 'onhold'::text])), 1)) || ' reduced with no recorded reason'::text
            WHEN sum(qty) FILTER (WHERE lab_testing_state = 'TestFailed'::text) > 0::numeric THEN 'FAILED TESTING still on hand - decide destruction or remediation'::text
            WHEN sum(qty) FILTER (WHERE COALESCE(on_hold, false)) > 0::numeric THEN 'Quantity on hold in Metrc'::text
            ELSE 'Reconciled'::text
        END AS reconciliation_status
   FROM base
  GROUP BY license, item
  ORDER BY (
        CASE
            WHEN sum(initial_qty - qty) FILTER (WHERE source_state = ANY (ARRAY['active'::text, 'onhold'::text])) > 0::numeric THEN 0
            ELSE 1
        END), (sum(qty) FILTER (WHERE source_state = 'active'::text)) DESC NULLS LAST;
create or replace view public.v_inventory_room_proof as
 WITH held AS (
         SELECT p.tag,
            p.license,
            NULLIF(btrim(p.raw ->> 'LocationName'::text), ''::text) AS room,
            NULLIF(btrim(p.raw ->> 'SublocationName'::text), ''::text) AS sublocation,
            p.raw #>> '{Item,ProductCategoryName}'::text[] AS category,
            f_to_pounds((p.raw ->> 'Quantity'::text)::numeric, p.raw ->> 'UnitOfMeasureAbbreviation'::text) AS lb,
            (p.raw ->> 'Quantity'::text)::numeric AS qty,
            p.raw ->> 'UnitOfMeasureAbbreviation'::text AS uom
           FROM metrc_packages p
          WHERE COALESCE((p.raw ->> 'Quantity'::text)::numeric, 0::numeric) > 0::numeric AND COALESCE((p.raw ->> 'IsFinished'::text)::boolean, false) = false
        ), shared_names AS (
         SELECT metrc_locations.name
           FROM metrc_locations
          GROUP BY metrc_locations.name
         HAVING count(DISTINCT metrc_locations.license) > 1
        )
 SELECT h.tag,
    h.room,
    h.sublocation,
    h.category,
    round(h.lb, 2) AS lb,
    h.qty,
    h.uom,
        CASE
            WHEN h.room IS NULL THEN 'FAILS J7 - NO ROOM RECORDED. We hold this and cannot say where it is. Massachusetts law requires Metrc to carry the current room for every tagged package, so this is a recording failure or unaccounted material.'::text
            WHEN loc.metrc_id IS NULL THEN ((('FAILS J7 - room "'::text || h.room) || '" is not listed in metrc_locations for licence '::text) || COALESCE(h.license, '?'::text)) || '. The package names a room Metrc does not hold under that licence, so its location cannot be confirmed against the state record.'::text
            WHEN sn.name IS NOT NULL THEN ((((((('ROOM CONFIRMED - '::text || h.room) || ', '::text) || COALESCE(initcap(cl.kind), h.license)) || ' department ('::text) || h.license) || '), Metrc id '::text) || loc.metrc_id) || '. THIS NAME EXISTS IN BOTH DEPARTMENTS and is two physically different rooms. Never show or total it without the department.'::text
            WHEN h.sublocation IS NULL THEN ((((((('ROOM CONFIRMED - '::text || h.room) || ', '::text) || COALESCE(initcap(cl.kind), h.license)) || ' department ('::text) || h.license) || '), Metrc id '::text) || loc.metrc_id) || '. No sublocation recorded: the room is known, the shelf is not. A physical count needs the shelf (A3).'::text
            ELSE 'PASSES J7 - room and shelf both confirmed against Metrc.'::text
        END AS room_proof,
    h.room IS NULL OR loc.metrc_id IS NULL AS fails_j7,
    sn.name IS NOT NULL AS ambiguous_room,
    h.license,
    (h.room || ' — '::text) || COALESCE(initcap(cl.kind), 'licence '::text || COALESCE(h.license, 'unknown'::text)) AS room_qualified,
    loc.metrc_id AS room_metrc_id,
    cl.kind AS department,
    cl.label AS licence_label
   FROM held h
     LEFT JOIN metrc_locations loc ON loc.name = h.room AND loc.license = h.license
     LEFT JOIN shared_names sn ON sn.name = h.room
     LEFT JOIN company_licenses cl ON cl.license = h.license;
create or replace view public.v_inventory_summary as
 SELECT c.sheet_name AS product_line,
    p.strain_flavor AS product,
    p.production_batch AS batch,
    p.size_g AS size,
    p.current_status,
    COALESCE(p.total_packaged, p.total_units, 0::numeric) AS ending_units,
    round(COALESCE(p.total_packaged, p.total_units, 0::numeric) / NULLIF(COALESCE(p.case_size, c.units_per_case), 0::numeric), 1) AS ending_cases,
        CASE
            WHEN COALESCE(p.total_packaged, p.total_units, 0::numeric) < c.threshold_units THEN 'LOW'::text
            ELSE NULL::text
        END AS low_flag,
        CASE
            WHEN p.expiration_date IS NOT NULL AND p.expiration_date < (CURRENT_DATE + 30) THEN 'EXP <30d'::text
            ELSE NULL::text
        END AS expiry_flag,
    round((COALESCE(p.total_bulk, 0::numeric) + COALESCE(p.total_filled, 0::numeric)) / NULLIF(c.units_per_case, 0::numeric), 1) AS possible_cases,
    p.expiration_date,
    p.category
   FROM product_inventory p
     JOIN inventory_config c ON p.category = ANY (c.categories);
create or replace view public.v_inventory_valuation as
 SELECT license,
    category,
    item,
    packages,
    quantity_estimate,
    uom,
    cost_per_unit,
    value_at_cost,
    basis,
    confidence
   FROM tg_inventory_as_of(CURRENT_DATE) tg_inventory_as_of(license, category, item, packages, quantity_estimate, uom, cost_per_unit, value_at_cost, basis, confidence);
create or replace view public.v_inventory_value as
 WITH sums AS (
         SELECT
                CASE
                    WHEN product_inventory.category = 'solventless'::text THEN 'Solventless'::text
                    WHEN product_inventory.category = 'hydrocarbon'::text AND lower(COALESCE(product_inventory.product_description, ''::text)) ~~ '%cured%'::text THEN 'Hydrocarbon - Cured Badder'::text
                    WHEN product_inventory.category = 'hydrocarbon'::text THEN 'Hydrocarbon - Live Badder'::text
                    WHEN product_inventory.category = ANY (ARRAY['raw_preroll_1g'::text, 'raw_preroll_05g'::text]) THEN 'Raw Pre-rolls'::text
                    WHEN product_inventory.category = 'infused_preroll'::text THEN 'Infused Pre-rolls'::text
                    WHEN product_inventory.category = 'economy_infused'::text THEN 'Economy infused'::text
                    WHEN product_inventory.category = ANY (ARRAY['economy_raw_1g'::text, 'economy_raw_05g'::text]) THEN 'Economy Raw'::text
                    WHEN product_inventory.category = 'vaporizer'::text THEN 'Vapes'::text
                    ELSE NULL::text
                END AS level_label,
            sum(COALESCE(product_inventory.total_bulk, 0::numeric) + COALESCE(product_inventory.total_filled, 0::numeric) + COALESCE(product_inventory.total_packaged, 0::numeric) +
                CASE
                    WHEN product_inventory.category = 'economy_infused'::text THEN COALESCE(product_inventory.total_gram_equivalent, 0::numeric)
                    ELSE 0::numeric
                END) AS units,
            sum((COALESCE(product_inventory.total_bulk, 0::numeric) + COALESCE(product_inventory.total_filled, 0::numeric) + COALESCE(product_inventory.total_packaged, 0::numeric) +
                CASE
                    WHEN product_inventory.category = 'economy_infused'::text THEN COALESCE(product_inventory.total_gram_equivalent, 0::numeric)
                    ELSE 0::numeric
                END) *
                CASE
                    WHEN product_inventory.creation_date IS NOT NULL AND product_inventory.creation_date > (CURRENT_DATE - 90) THEN 1
                    ELSE 0
                END::numeric) AS units_0_90,
            sum((COALESCE(product_inventory.total_bulk, 0::numeric) + COALESCE(product_inventory.total_filled, 0::numeric) + COALESCE(product_inventory.total_packaged, 0::numeric) +
                CASE
                    WHEN product_inventory.category = 'economy_infused'::text THEN COALESCE(product_inventory.total_gram_equivalent, 0::numeric)
                    ELSE 0::numeric
                END) *
                CASE
                    WHEN product_inventory.creation_date IS NOT NULL AND product_inventory.creation_date <= (CURRENT_DATE - 90) AND product_inventory.creation_date > (CURRENT_DATE - 180) THEN 1
                    ELSE 0
                END::numeric) AS units_91_180,
            sum((COALESCE(product_inventory.total_bulk, 0::numeric) + COALESCE(product_inventory.total_filled, 0::numeric) + COALESCE(product_inventory.total_packaged, 0::numeric) +
                CASE
                    WHEN product_inventory.category = 'economy_infused'::text THEN COALESCE(product_inventory.total_gram_equivalent, 0::numeric)
                    ELSE 0::numeric
                END) *
                CASE
                    WHEN product_inventory.creation_date IS NOT NULL AND product_inventory.creation_date <= (CURRENT_DATE - 180) AND product_inventory.creation_date > (CURRENT_DATE - 270) THEN 1
                    ELSE 0
                END::numeric) AS units_181_270,
            sum((COALESCE(product_inventory.total_bulk, 0::numeric) + COALESCE(product_inventory.total_filled, 0::numeric) + COALESCE(product_inventory.total_packaged, 0::numeric) +
                CASE
                    WHEN product_inventory.category = 'economy_infused'::text THEN COALESCE(product_inventory.total_gram_equivalent, 0::numeric)
                    ELSE 0::numeric
                END) *
                CASE
                    WHEN product_inventory.creation_date IS NOT NULL AND product_inventory.creation_date <= (CURRENT_DATE - 270) THEN 1
                    ELSE 0
                END::numeric) AS units_271_plus
           FROM product_inventory
          GROUP BY (
                CASE
                    WHEN product_inventory.category = 'solventless'::text THEN 'Solventless'::text
                    WHEN product_inventory.category = 'hydrocarbon'::text AND lower(COALESCE(product_inventory.product_description, ''::text)) ~~ '%cured%'::text THEN 'Hydrocarbon - Cured Badder'::text
                    WHEN product_inventory.category = 'hydrocarbon'::text THEN 'Hydrocarbon - Live Badder'::text
                    WHEN product_inventory.category = ANY (ARRAY['raw_preroll_1g'::text, 'raw_preroll_05g'::text]) THEN 'Raw Pre-rolls'::text
                    WHEN product_inventory.category = 'infused_preroll'::text THEN 'Infused Pre-rolls'::text
                    WHEN product_inventory.category = 'economy_infused'::text THEN 'Economy infused'::text
                    WHEN product_inventory.category = ANY (ARRAY['economy_raw_1g'::text, 'economy_raw_05g'::text]) THEN 'Economy Raw'::text
                    WHEN product_inventory.category = 'vaporizer'::text THEN 'Vapes'::text
                    ELSE NULL::text
                END)
        )
 SELECT v.level_label AS inventory_level,
    v.value_per_unit,
    round(COALESCE(s.units, 0::numeric) * v.value_per_unit, 2) AS inventory_value,
    round(COALESCE(s.units_0_90, 0::numeric) * v.value_per_unit, 2) AS value_0_90_days,
    round(COALESCE(s.units_91_180, 0::numeric) * v.value_per_unit, 2) AS value_91_180_days,
    round(COALESCE(s.units_181_270, 0::numeric) * v.value_per_unit, 2) AS value_181_270_days,
    round(COALESCE(s.units_271_plus, 0::numeric) * v.value_per_unit, 2) AS value_271_plus_days,
    v.formula_note
   FROM inventory_values v
     LEFT JOIN sums s ON s.level_label = v.level_label;
create or replace view public.v_issue_failed_testing as
 SELECT license,
    tag AS package_tag,
    item_name,
    quantity,
    uom,
    location,
    packaged_on,
    CURRENT_DATE - packaged_on AS days_held,
    NULLIF(raw ->> 'SourceHarvestNames'::text, ''::text) AS source_harvest,
        CASE
            WHEN f_is_ours(raw ->> 'ItemFromFacilityLicenseNumber'::text) AND f_is_weight(uom) THEN round(f_to_pounds(quantity, uom) * (( SELECT cm.cost_per_pound
               FROM cost_model cm
              WHERE cm.scope = 'cultivation'::text
              ORDER BY cm.effective_from DESC
             LIMIT 1)), 0)
            ELSE NULL::numeric
        END AS value_at_cost,
    'THE ISSUE: this package failed laboratory testing and is still sitting in active inventory. It cannot legally be sold.'::text AS what_is_wrong,
    'Record the ruling in failed_material_disposition: bought_for_remediation, remediate_in_house, sell_for_remediation or destroy. Only destroy counts as a loss. Then record it in Metrc.'::text AS what_to_do,
        CASE
            WHEN f_is_weight(uom) THEN round(f_to_pounds(quantity, uom), 2)
            ELSE NULL::numeric
        END AS pounds,
        CASE
            WHEN f_is_ours(raw ->> 'ItemFromFacilityLicenseNumber'::text) THEN 'OURS'::text
            ELSE 'BOUGHT IN'::text
        END AS whose_material,
    raw ->> 'ItemFromFacilityName'::text AS made_by,
        CASE
            WHEN NOT f_is_weight(uom) THEN 'Countable item - no weight, so no pound value.'::text
            WHEN f_is_ours(raw ->> 'ItemFromFacilityLicenseNumber'::text) THEN 'Our cultivation cost per pound, from cost_model.'::text
            ELSE 'UNKNOWN. Bought in, most likely at a discount to remediate. material_purchases is empty, so what was paid exists nowhere. Our cultivation cost does NOT apply to someone else''s material.'::text
        END AS cost_basis
   FROM metrc_packages p
  WHERE lab_testing_state = 'TestFailed'::text AND (source_state = ANY (ARRAY['active'::text, 'onhold'::text])) AND NOT (EXISTS ( SELECT 1
           FROM failed_material_disposition fd
          WHERE fd.package_tag = p.tag AND fd.superseded_at IS NULL))
  ORDER BY (
        CASE
            WHEN f_is_ours(raw ->> 'ItemFromFacilityLicenseNumber'::text) AND f_is_weight(uom) THEN round(f_to_pounds(quantity, uom) * (( SELECT cm.cost_per_pound
               FROM cost_model cm
              WHERE cm.scope = 'cultivation'::text
              ORDER BY cm.effective_from DESC
             LIMIT 1)), 0)
            ELSE NULL::numeric
        END) DESC NULLS LAST;
create or replace view public.v_issue_unconfirmed_manifests as
 SELECT manifest_number,
    created_on AS shipped_on,
    CURRENT_DATE - created_on AS days_unconfirmed,
    recipient AS customer,
    COALESCE((raw ->> 'PackageCount'::text)::numeric, 0::numeric) AS packages,
    raw ->> 'TransporterFacilityName'::text AS transporter,
        CASE
            WHEN (raw ->> 'Id'::text) IS NOT NULL THEN ('https://ma.metrc.com/reports/transfers/'::text || (raw ->> 'Id'::text)) || '/manifest'::text
            ELSE NULL::text
        END AS manifest_link,
    'THE ISSUE: this outbound manifest was never confirmed received. The chain of custody is open on the state record.'::text AS what_is_wrong,
    'Contact the receiving facility and have them confirm receipt in Metrc, or void and reissue.'::text AS what_to_do,
    license
   FROM metrc_transfers t
  WHERE direction = 'outgoing'::text AND (raw ->> 'ReceivedDateTime'::text) IS NULL AND created_on < (CURRENT_DATE - 3)
  ORDER BY (CURRENT_DATE - created_on) DESC;
create or replace view public.v_issue_yield_by_harvest as
 WITH avgc AS (
         SELECT avg(COALESCE((metrc_harvests.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) / NULLIF((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) AS company_avg
           FROM metrc_harvests
          WHERE COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric) > 0::numeric
        )
 SELECT h.name AS harvest,
    COALESCE(h.raw ->> 'SourceStrainNames'::text, 'not recorded'::text) AS strain,
    COALESCE(h.raw ->> 'DryingLocationName'::text, '(no room)'::text) AS room,
    h.harvest_start AS harvest_date,
    (h.raw ->> 'FinishedDate'::text)::date AS finished_date,
        CASE
            WHEN (h.raw ->> 'FinishedDate'::text) IS NOT NULL THEN ((h.raw ->> 'FinishedDate'::text)::date) - h.harvest_start
            ELSE NULL::integer
        END AS dry_days,
    CURRENT_DATE - h.harvest_start AS days_since_harvest,
    COALESCE((h.raw ->> 'PlantCount'::text)::numeric, 0::numeric) AS plants,
    round(COALESCE((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric) / 453.592, 1) AS wet_lbs,
    round(COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) / 453.592, 1) AS saleable_lbs,
    round(COALESCE((h.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric) / 453.592, 1) AS waste_lbs,
    round(100.0 * COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) / NULLIF((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric), 1) AS conversion_pct,
    round(100.0 * (( SELECT avgc_1.company_avg
           FROM avgc avgc_1)), 1) AS company_average_pct,
    ( SELECT industry_benchmarks.average
           FROM industry_benchmarks
          WHERE industry_benchmarks.metric = 'Wet to saleable conversion'::text) AS industry_average_pct,
    round(COALESCE((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric) / 453.592 * ((( SELECT avgc_1.company_avg
           FROM avgc avgc_1)) - COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) / NULLIF((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)), 1) AS pounds_short_of_company_average,
    round(COALESCE((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric) / 453.592 * ((( SELECT avgc_1.company_avg
           FROM avgc avgc_1)) - COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) / NULLIF((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) * (( SELECT cost_model.cost_per_pound
           FROM cost_model
          WHERE cost_model.scope = 'cultivation'::text
          ORDER BY cost_model.effective_from DESC
         LIMIT 1)), 0) AS dollars_short,
    h.raw ->> 'LabTestingState'::text AS laboratory_state,
    h.license,
    ((('THE ISSUE: this harvest converted '::text || round(100.0 * COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) / NULLIF((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric), 1)) || ' percent against a company average of '::text) || round(100.0 * (( SELECT avgc_1.company_avg
           FROM avgc avgc_1)), 1)) || ' percent.'::text AS what_is_wrong,
    'Check dry days and trim practice for this harvest against a high performing one in the same room.'::text AS what_to_do
   FROM metrc_harvests h,
    avgc
  WHERE COALESCE((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric) > 0::numeric AND COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) > 0::numeric AND (COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) / ((h.raw ->> 'TotalWetWeight'::text)::numeric)) < (0.75 * avgc.company_avg)
  ORDER BY (round(COALESCE((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric) / 453.592 * ((( SELECT avgc_1.company_avg
           FROM avgc avgc_1)) - COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) / NULLIF((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) * (( SELECT cost_model.cost_per_pound
           FROM cost_model
          WHERE cost_model.scope = 'cultivation'::text
          ORDER BY cost_model.effective_from DESC
         LIMIT 1)), 0)) DESC NULLS LAST;
create or replace view public.v_lab_analytes as
 SELECT metrc_lab_results.package_tag,
    metrc_lab_results.license AS licence,
    metrc_lab_results.test_name,
    metrc_lab_results.result,
    metrc_lab_results.passed::text AS passed,
    metrc_lab_results.result_date,
    metrc_lab_results.lab_facility,
    metrc_lab_results.units,
    metrc_lab_results.document_file_id,
    'Metrc API'::text AS source,
    'Source of record. Pulled per package from /labtests/v2/results.'::text AS source_note
   FROM metrc_lab_results
UNION ALL
 SELECT r.package_tag,
    r.packaged_licence AS licence,
    r.test_name,
    r.result,
    r.passed,
    r.test_date AS result_date,
    r.lab_facility,
    NULL::text AS units,
    NULL::text AS document_file_id,
    'Metrc report'::text AS source,
    ('Filling a gap the API cannot serve - it answers 401 on this package. Report as-of '::text || COALESCE(r.as_of_date::text, 'not stated'::text)) || '.'::text AS source_note
   FROM metrc_rpt_lab_results r
  WHERE NOT (EXISTS ( SELECT 1
           FROM metrc_lab_results a
          WHERE a.package_tag = r.package_tag));
create or replace view public.v_lab_results as
 SELECT license,
    package_tag,
    item_name,
    strain,
    category,
    origin,
    cultivator_or_manufacturer,
    quantity,
    f_uom_label(unit_of_measure) AS unit_of_measure,
    pounds,
    where_it_is_now,
    source_harvest,
    harvest_cut_on,
    harvest_closed_on,
    dried_in_room,
    harvest_note,
    package_created_on,
    received_on,
    history_last_recorded_on,
    days_since_last_change,
    days_on_hand,
    result,
    submitted_on,
    result_on,
    turnaround_days,
    coa_expires,
    days_until_expiry,
    total_thc,
    total_terpenes,
    supplier,
    manifest_number,
    verdict,
    never_submitted_detail,
    total_thc_unit,
    total_thc_source
   FROM ( SELECT p.license,
            p.tag AS package_tag,
            p.item_name,
            COALESCE(p.raw #>> '{Item,StrainName}'::text[], '—'::text) AS strain,
            p.raw #>> '{Item,ProductCategoryName}'::text[] AS category,
                CASE
                    WHEN COALESCE(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text) = ANY (ARRAY['MC281714'::text, 'MP281909'::text]) THEN 'Grown by us'::text
                    ELSE 'Bought in'::text
                END AS origin,
            COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityName'::text, ''::text), 'not recorded'::text) AS cultivator_or_manufacturer,
            round(p.quantity) AS quantity,
                CASE p.uom
                    WHEN 'g'::text THEN 'grams'::text
                    WHEN 'kg'::text THEN 'kilograms'::text
                    WHEN 'ea'::text THEN 'each'::text
                    WHEN 'oz'::text THEN 'ounces'::text
                    WHEN 'lb'::text THEN 'pounds'::text
                    ELSE COALESCE(p.uom, 'not recorded'::text)
                END AS unit_of_measure,
                CASE p.uom
                    WHEN 'g'::text THEN round(p.quantity / f_rule('grams_per_pound'::text), 2)
                    WHEN 'kg'::text THEN round(p.quantity * 1000.0 / f_rule('grams_per_pound'::text), 2)
                    WHEN 'lb'::text THEN round(p.quantity, 2)
                    WHEN 'oz'::text THEN round(p.quantity / 16.0, 2)
                    ELSE NULL::numeric
                END AS pounds,
            COALESCE(p.location, 'not recorded'::text) AS where_it_is_now,
            NULLIF(p.raw ->> 'SourceHarvestNames'::text, ''::text) AS source_harvest,
            h.harvest_start AS harvest_cut_on,
            (h.raw ->> 'FinishedDate'::text)::date AS harvest_closed_on,
            COALESCE(NULLIF(h.raw ->> 'DryingLocationName'::text, ''::text), 'not recorded'::text) AS dried_in_room,
                CASE
                    WHEN NULLIF(p.raw ->> 'SourceHarvestNames'::text, ''::text) IS NULL THEN
                    CASE
                        WHEN COALESCE(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text) <> ALL (ARRAY['MC281714'::text, 'MP281909'::text]) THEN ('No harvest date. WHY: bought in from '::text || COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityName'::text, ''::text), 'another licence'::text)) || ' — we did not grow it, so there is no harvest of ours. Ask the supplier for their cultivation record.'::text
                        ELSE 'No harvest date. WHY: Metrc records no source harvest on this package. That is a lineage gap to correct.'::text
                    END
                    ELSE NULL::text
                END AS harvest_note,
            p.packaged_on AS package_created_on,
            (p.raw ->> 'ReceivedDateTime'::text)::date AS received_on,
            (p.raw ->> 'LastModified'::text)::date AS history_last_recorded_on,
            CURRENT_DATE - ((p.raw ->> 'LastModified'::text)::date) AS days_since_last_change,
            CURRENT_DATE - p.packaged_on AS days_on_hand,
            p.raw ->> 'LabTestingState'::text AS result,
            (p.raw ->> 'LabTestingStateDate'::text)::date AS submitted_on,
            (p.raw ->> 'LabTestingRecordedDate'::text)::date AS result_on,
            ((p.raw ->> 'LabTestingRecordedDate'::text)::date) - ((p.raw ->> 'LabTestingStateDate'::text)::date) AS turnaround_days,
            (p.raw ->> 'LabTestResultExpirationDateTime'::text)::date AS coa_expires,
            ((p.raw ->> 'LabTestResultExpirationDateTime'::text)::date) - CURRENT_DATE AS days_until_expiry,
            COALESCE(( SELECT round(m.result, 2) AS round
                   FROM metrc_lab_results m
                  WHERE m.package_tag = p.tag AND m.test_name ~~* '%total thc%'::text AND m.result IS NOT NULL
                  ORDER BY m.result_date DESC NULLS LAST, m.result DESC
                 LIMIT 1), ( SELECT round(max(c.total_thc), 2) AS round
                   FROM coa_extract c
                  WHERE c.package_tag = p.tag AND c.total_thc IS NOT NULL)) AS total_thc,
                CASE
                    WHEN (EXISTS ( SELECT 1
                       FROM metrc_lab_results m
                      WHERE m.package_tag = p.tag AND m.test_name ~~* '%total thc%'::text AND m.result IS NOT NULL)) THEN ( SELECT
                            CASE
                                WHEN m.test_name ~~* '%(mg/g)%'::text THEN 'mg/g'::text
                                WHEN m.test_name ~~* '%(\%)%'::text THEN '%'::text
                                ELSE 'unit not stated by Metrc'::text
                            END AS "case"
                       FROM metrc_lab_results m
                      WHERE m.package_tag = p.tag AND m.test_name ~~* '%total thc%'::text AND m.result IS NOT NULL
                      ORDER BY m.result_date DESC NULLS LAST, m.result DESC
                     LIMIT 1)
                    WHEN (EXISTS ( SELECT 1
                       FROM coa_extract c
                      WHERE c.package_tag = p.tag AND c.total_thc IS NOT NULL)) THEN '%'::text
                    ELSE NULL::text
                END AS total_thc_unit,
                CASE
                    WHEN (EXISTS ( SELECT 1
                       FROM metrc_lab_results m
                      WHERE m.package_tag = p.tag AND m.test_name ~~* '%total thc%'::text AND m.result IS NOT NULL)) THEN 'Metrc'::text
                    WHEN (EXISTS ( SELECT 1
                       FROM coa_extract c
                      WHERE c.package_tag = p.tag AND c.total_thc IS NOT NULL)) THEN 'COA - Metrc holds no result'::text
                    ELSE NULL::text
                END AS total_thc_source,
            ( SELECT round(COALESCE(( SELECT max(m.result) AS max
                           FROM metrc_lab_results m
                          WHERE m.package_tag = p.tag AND m.test_name ~~* '%total terpenes%'::text AND m.result IS NOT NULL), ( SELECT sum(m.result) AS sum
                           FROM metrc_lab_results m
                          WHERE m.package_tag = p.tag AND m.test_name ~~* '%terp%'::text AND m.test_name !~~* '%total%'::text AND m.test_name !~~* '%do not use%'::text AND m.result IS NOT NULL)), 2) AS round) AS total_terpenes,
            COALESCE(NULLIF(p.raw ->> 'ReceivedFromFacilityName'::text, ''::text), '—'::text) AS supplier,
            NULLIF(p.raw ->> 'ReceivedFromManifestNumber'::text, ''::text) AS manifest_number,
                CASE
                    WHEN (p.raw ->> 'LabTestingState'::text) = 'TestFailed'::text THEN 'FAILED'::text
                    WHEN (p.raw ->> 'LabTestingState'::text) = 'TestPassed'::text THEN 'Passed'::text
                    WHEN (p.raw ->> 'LabTestingState'::text) = 'NotSubmitted'::text THEN 'NEVER SUBMITTED'::text
                    ELSE 'Awaiting result'::text
                END AS verdict,
                CASE
                    WHEN (p.raw ->> 'LabTestingState'::text) = 'NotSubmitted'::text THEN (((((((('Never submitted. Packaged '::text || p.packaged_on::text) || ', '::text) || (CURRENT_DATE - p.packaged_on)) || ' days ago, sitting in '::text) || COALESCE(p.location, 'an unrecorded location'::text)) || COALESCE(', from harvest '::text || NULLIF(p.raw ->> 'SourceHarvestNames'::text, ''::text), ''::text)) || COALESCE(' cut '::text || h.harvest_start::text, ''::text)) || COALESCE(' dried in '::text || NULLIF(h.raw ->> 'DryingLocationName'::text, ''::text), ''::text)) || '. Cannot legally be sold until it is submitted.'::text
                    ELSE NULL::text
                END AS never_submitted_detail
           FROM metrc_packages p
             LEFT JOIN metrc_harvests h ON h.name = split_part(COALESCE(p.raw ->> 'SourceHarvestNames'::text, ''::text), ','::text, 1)
          WHERE (p.raw ->> 'LabTestingState'::text) IS NOT NULL) q;
create or replace view public.v_lab_turnaround_breaches as
 SELECT package_tag,
    product,
    category,
    strain,
    source_harvest,
    pounds,
    went_out_on,
    came_back_on,
    COALESCE(days_out, CURRENT_DATE - went_out_on) AS days_out,
    f_rule('lab_turnaround_max_days'::text) AS limit_days,
        CASE
            WHEN came_back_on IS NULL THEN ((((('STILL OUT — sent '::text || went_out_on) || ', '::text) || (CURRENT_DATE - went_out_on)) || ' days ago against a '::text) || f_rule('lab_turnaround_max_days'::text)) || ' day limit. Chase the laboratory.'::text
            ELSE ((((('Came back '::text || came_back_on) || ' after '::text) || days_out) || ' days, over the '::text) || f_rule('lab_turnaround_max_days'::text)) || ' day limit.'::text
        END AS what_happened
   FROM lab_turnaround_log
  WHERE breached
  ORDER BY (COALESCE(days_out, CURRENT_DATE - went_out_on)) DESC;
create or replace view public.v_lab_turnaround_report as
 SELECT date_trunc('month'::text, went_out_on::timestamp with time zone)::date AS month,
    category,
    count(*) AS samples,
    round(avg(days_out), 2) AS avg_days,
    percentile_cont(0.5::double precision) WITHIN GROUP (ORDER BY (days_out::double precision)) AS median_days,
    percentile_cont(0.95::double precision) WITHIN GROUP (ORDER BY (days_out::double precision)) AS p95_days,
    max(days_out) AS worst_days,
    count(*) FILTER (WHERE breached) AS over_the_limit,
    round(100.0 * count(*) FILTER (WHERE breached)::numeric / NULLIF(count(*), 0)::numeric, 1) AS pct_over_limit,
    f_rule('lab_turnaround_max_days'::text) AS limit_days
   FROM lab_turnaround_log
  WHERE went_out_on IS NOT NULL
  GROUP BY (date_trunc('month'::text, went_out_on::timestamp with time zone)::date), category
  ORDER BY (date_trunc('month'::text, went_out_on::timestamp with time zone)::date) DESC, category;
create or replace view public.v_lab_turnaround_summary as
 SELECT COALESCE(NULLIF(category, ''::text), 'Not recorded'::text) AS category,
    count(*) AS packages,
    round(avg(days_out) FILTER (WHERE days_out IS NOT NULL), 1) AS avg_turnaround_days,
    max(days_out) AS slowest_turnaround_days,
    min(days_out) AS fastest_turnaround_days,
    count(*) FILTER (WHERE days_out > 14) AS took_over_14_days,
    count(*) FILTER (WHERE came_back_on IS NULL) AS still_out,
    round(sum(pounds), 1) AS pounds,
    min(went_out_on) AS first_sample_on,
    max(came_back_on) AS last_return_on
   FROM lab_turnaround_log
  WHERE went_out_on IS NOT NULL
  GROUP BY (COALESCE(NULLIF(category, ''::text), 'Not recorded'::text));
create or replace view public.v_labour_forecast as
 WITH pol AS (
         SELECT attendance_policy.shift_hours_gross
           FROM attendance_policy
         LIMIT 1
        ), plan AS (
         SELECT s.employee_id,
            s.work_date,
            date_trunc('week'::text, s.work_date::timestamp with time zone)::date AS week_start,
            COALESCE(d.name, 'Unassigned'::text) AS department,
            COALESCE(btrim(s.zone), 'No zone'::text) AS zone,
            EXTRACT(epoch FROM s.planned_end - s.planned_start) / 3600.0 - COALESCE(bw.minutes, 0)::numeric / 60.0 AS planned_hours,
            e.hours_basis,
            r.rate,
            COALESCE(r.burden_pct, 0::numeric) AS burden
           FROM employee_schedules s
             JOIN employees e ON e.id = s.employee_id
             LEFT JOIN departments d ON d.id = COALESCE(s.department_id, e.primary_department_id)
             LEFT JOIN break_windows bw ON bw.active AND (bw.department_id IS NULL OR bw.department_id = s.department_id)
             LEFT JOIN LATERAL ( SELECT r2.id,
                    r2.employee_id,
                    r2.basis,
                    r2.rate,
                    r2.ot_multiplier,
                    r2.burden_pct,
                    r2.effective_from,
                    r2.effective_to,
                    r2.approved_by,
                    r2.note,
                    r2.effective_from_date
                   FROM employee_rates r2
                  WHERE r2.employee_id = s.employee_id AND r2.effective_from <= s.work_date AND (r2.effective_to IS NULL OR r2.effective_to >= s.work_date)
                  ORDER BY r2.effective_from DESC
                 LIMIT 1) r ON true
          WHERE s.planned_start IS NOT NULL AND s.planned_end IS NOT NULL
        )
 SELECT department,
    zone,
    work_date,
    week_start,
    count(DISTINCT employee_id) AS heads_planned,
    round(sum(planned_hours), 2) AS hours_planned,
    round(sum(planned_hours) / NULLIF(( SELECT pol.shift_hours_gross
           FROM pol), 0::numeric), 2) AS shifts_planned,
    round(sum(planned_hours * rate * (1::numeric + burden)), 2) AS cost_planned_loaded,
    round(sum(planned_hours * rate * (1::numeric + burden)) / NULLIF(sum(planned_hours), 0::numeric), 2) AS planned_cost_per_hour
   FROM plan
  GROUP BY department, zone, work_date, week_start;
create or replace view public.v_licence_directory as
 SELECT licence,
    name,
    sources,
    seen
   FROM ( SELECT z.licence,
            z.name,
            count(*) AS seen,
            string_agg(DISTINCT z.src, ', '::text) AS sources,
            row_number() OVER (PARTITION BY z.licence ORDER BY (count(*)) DESC) AS rn
           FROM ( SELECT metrc_transfers.raw ->> 'ShipperFacilityLicenseNumber'::text AS licence,
                    metrc_transfers.raw ->> 'ShipperFacilityName'::text AS name,
                    'transfer shipper'::text AS src
                   FROM metrc_transfers
                  WHERE NULLIF(metrc_transfers.raw ->> 'ShipperFacilityLicenseNumber'::text, ''::text) IS NOT NULL
                UNION ALL
                 SELECT metrc_transfers.raw ->> 'RecipientFacilityLicenseNumber'::text,
                    metrc_transfers.raw ->> 'RecipientFacilityName'::text,
                    'transfer recipient'::text
                   FROM metrc_transfers
                  WHERE NULLIF(metrc_transfers.raw ->> 'RecipientFacilityLicenseNumber'::text, ''::text) IS NOT NULL
                UNION ALL
                 SELECT metrc_packages.raw ->> 'ItemFromFacilityLicenseNumber'::text,
                    metrc_packages.raw ->> 'ItemFromFacilityName'::text,
                    'package item origin'::text
                   FROM metrc_packages
                  WHERE NULLIF(metrc_packages.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text) IS NOT NULL
                UNION ALL
                 SELECT metrc_packages.raw ->> 'ReceivedFromFacilityLicenseNumber'::text,
                    metrc_packages.raw ->> 'ReceivedFromFacilityName'::text,
                    'package received from'::text
                   FROM metrc_packages
                  WHERE NULLIF(metrc_packages.raw ->> 'ReceivedFromFacilityLicenseNumber'::text, ''::text) IS NOT NULL
                UNION ALL
                 SELECT coa_extract.client_license,
                    coa_extract.client_name,
                    'certificate client'::text
                   FROM coa_extract
                  WHERE coa_extract.client_license IS NOT NULL AND coa_extract.client_name IS NOT NULL) z
          WHERE z.name IS NOT NULL AND z.name <> ''::text
          GROUP BY z.licence, z.name) d
  WHERE rn = 1;
create or replace view public.v_lifecycle_open as
 SELECT p.id,
    p.employee_id,
    e.employee_code,
    e.full_name,
    p.phase,
    s.ordinal,
    s.title,
    s.detail,
    s.owner_role,
    s.is_legal,
    s.blocks_start,
    s.blocks_close,
    p.due_on,
    p.due_on IS NOT NULL AND p.due_on < CURRENT_DATE AS overdue,
    CURRENT_DATE - p.due_on AS days_overdue
   FROM lifecycle_progress p
     JOIN lifecycle_steps s ON s.id = p.step_id
     JOIN employees e ON e.id = p.employee_id
  WHERE p.done_at IS NULL AND p.na_reason IS NULL
  ORDER BY s.is_legal DESC, p.due_on, s.ordinal;
create or replace view public.v_location_history as
 SELECT package_tag,
    item_name,
    strain,
    quantity,
    f_uom_label(unit_of_measure) AS unit_of_measure,
    area,
    license,
    came_from_area,
    arrived_from,
    arrived_on_manifest,
    entered_area_on,
    days_in_this_area,
    left_area_on,
    last_recorded_on,
    days_since_anything_was_recorded,
    "position",
    location_story
   FROM ( WITH moves AS (
                 SELECT p.tag AS package_tag,
                    p.item_name,
                    p.raw #>> '{Item,StrainName}'::text[] AS strain,
                    round(p.quantity) AS quantity,
                        CASE p.uom
                            WHEN 'g'::text THEN 'grams'::text
                            WHEN 'kg'::text THEN 'kilograms'::text
                            WHEN 'ea'::text THEN 'each'::text
                            WHEN 'oz'::text THEN 'ounces'::text
                            WHEN 'lb'::text THEN 'pounds'::text
                            ELSE COALESCE(p.uom, 'not recorded'::text)
                        END AS unit_of_measure,
                    COALESCE(p.location, 'not recorded'::text) AS area,
                    p.license,
                    COALESCE((p.raw ->> 'ReceivedDateTime'::text)::date, p.packaged_on) AS entered_area_on,
                    (p.raw ->> 'LastModified'::text)::date AS last_recorded_on,
                    (p.raw ->> 'FinishedDate'::text)::date AS left_area_on,
                    (p.raw ->> 'IsFinished'::text)::boolean AS finished,
                    NULLIF(p.raw ->> 'ReceivedFromManifestNumber'::text, ''::text) AS arrived_on_manifest,
                    NULLIF(p.raw ->> 'ReceivedFromFacilityName'::text, ''::text) AS arrived_from,
                    h.harvest_start AS harvest_cut_on,
                    NULLIF(h.raw ->> 'DryingLocationName'::text, ''::text) AS previous_area
                   FROM metrc_packages p
                     LEFT JOIN metrc_harvests h ON h.name = split_part(COALESCE(p.raw ->> 'SourceHarvestNames'::text, ''::text), ','::text, 1)
                )
         SELECT moves.package_tag,
            moves.item_name,
            moves.strain,
            moves.quantity,
            moves.unit_of_measure,
            moves.area,
            moves.license,
            moves.previous_area AS came_from_area,
            moves.arrived_from,
            moves.arrived_on_manifest,
            moves.entered_area_on,
            COALESCE(moves.left_area_on, CURRENT_DATE) - moves.entered_area_on AS days_in_this_area,
            moves.left_area_on,
            moves.last_recorded_on,
            CURRENT_DATE - moves.last_recorded_on AS days_since_anything_was_recorded,
                CASE
                    WHEN moves.finished AND moves.left_area_on IS NOT NULL THEN ('LEFT on '::text || moves.left_area_on::text) || ' — package closed out'::text
                    WHEN moves.quantity = 0::numeric THEN 'Drawn to zero, not yet closed out'::text
                    ELSE (('STILL HERE — '::text || (CURRENT_DATE - moves.entered_area_on)) || ' days in '::text) || moves.area
                END AS "position",
            (((((((((('Entered '::text || moves.area) || ' on '::text) || moves.entered_area_on::text) || COALESCE(' from '::text || moves.previous_area, ''::text)) || COALESCE(' via manifest '::text || moves.arrived_on_manifest, ''::text)) || ' · '::text) || (COALESCE(moves.left_area_on, CURRENT_DATE) - moves.entered_area_on)) || ' days there'::text) ||
                CASE
                    WHEN moves.left_area_on IS NOT NULL THEN ' · left '::text || moves.left_area_on::text
                    ELSE ' · has not left'::text
                END) || ' · history last recorded '::text) || COALESCE(moves.last_recorded_on::text, 'never'::text) AS location_story
           FROM moves) q;
create or replace view public.v_loop_health as
 WITH recent AS (
         SELECT d.jobid,
            d.status,
            d.start_time,
            d.end_time,
            EXTRACT(epoch FROM d.end_time - d.start_time) AS secs
           FROM cron.job_run_details d
          WHERE d.start_time > (now() - '7 days'::interval)
        ), gaps AS (
         SELECT recent.jobid,
            EXTRACT(epoch FROM recent.start_time - lag(recent.start_time) OVER (PARTITION BY recent.jobid ORDER BY recent.start_time)) AS gap
           FROM recent
          WHERE recent.status = 'succeeded'::text
        ), cadence AS (
         SELECT gaps.jobid,
            percentile_cont(0.5::double precision) WITHIN GROUP (ORDER BY (gaps.gap::double precision)) AS usual_gap
           FROM gaps
          WHERE gaps.gap IS NOT NULL
          GROUP BY gaps.jobid
        ), norm AS (
         SELECT recent.jobid,
            percentile_cont(0.95::double precision) WITHIN GROUP (ORDER BY (recent.secs::double precision)) FILTER (WHERE recent.secs IS NOT NULL) AS p95_secs,
            count(*) FILTER (WHERE recent.status = 'succeeded'::text) AS ok_7d,
            count(*) FILTER (WHERE recent.status = 'failed'::text) AS failed_7d,
            max(recent.start_time) FILTER (WHERE recent.status = 'succeeded'::text) AS last_success,
            max(recent.start_time) FILTER (WHERE recent.status = 'failed'::text) AS last_failure
           FROM recent
          GROUP BY recent.jobid
        ), live AS (
         SELECT recent.jobid,
            min(recent.start_time) AS running_since
           FROM recent
          WHERE recent.status = 'running'::text AND recent.end_time IS NULL
          GROUP BY recent.jobid
        ), shape AS (
         SELECT j_1.jobid,
            split_part(j_1.schedule, ' '::text, 2) !~ '^([*]|[*]/[0-9]+)$'::text AS runs_in_a_window
           FROM cron.job j_1
        )
 SELECT j.jobname,
    j.schedule,
    j.active,
    COALESCE(n.ok_7d, 0::bigint) AS succeeded_7d,
    COALESCE(n.failed_7d, 0::bigint) AS failed_7d,
    n.last_success,
    round(n.p95_secs)::integer AS usual_seconds,
    round(EXTRACT(epoch FROM now() - l.running_since))::integer AS running_for_seconds,
        CASE
            WHEN NOT j.active THEN 'switched off'::text
            WHEN COALESCE(n.ok_7d, 0::bigint) = 0 AND COALESCE(n.failed_7d, 0::bigint) = 0 THEN 'has not run at all in 7 days'::text
            WHEN COALESCE(n.ok_7d, 0::bigint) = 0 THEN 'NEVER SUCCEEDED - every run failed'::text
            WHEN l.running_since IS NOT NULL AND n.p95_secs IS NOT NULL AND EXTRACT(epoch FROM now() - l.running_since)::double precision > GREATEST(n.p95_secs * 4::double precision, 300::double precision) THEN 'HUNG - running far longer than it ever normally takes'::text
            WHEN n.last_failure IS NOT NULL AND n.last_failure > n.last_success THEN 'FAILING - its most recent run failed'::text
            WHEN c.usual_gap IS NOT NULL AND NOT COALESCE(s.runs_in_a_window, false) AND n.last_success < (now() - make_interval(secs => c.usual_gap * 2.5::double precision)) THEN 'LATE - overdue against its own normal interval'::text
            WHEN COALESCE(n.failed_7d, 0::bigint) > 0 THEN 'recovered - failed earlier, succeeding now'::text
            ELSE 'healthy'::text
        END AS verdict,
    round(c.usual_gap)::integer AS usual_gap_seconds,
    n.last_failure,
    COALESCE(s.runs_in_a_window, false) AS runs_only_in_a_window
   FROM cron.job j
     LEFT JOIN norm n ON n.jobid = j.jobid
     LEFT JOIN cadence c ON c.jobid = j.jobid
     LEFT JOIN live l ON l.jobid = j.jobid
     LEFT JOIN shape s ON s.jobid = j.jobid
  ORDER BY (
        CASE
            WHEN NOT j.active THEN 5
            WHEN COALESCE(n.ok_7d, 0::bigint) = 0 THEN 0
            WHEN n.last_failure IS NOT NULL AND n.last_failure > n.last_success THEN 1
            WHEN COALESCE(n.failed_7d, 0::bigint) > 0 THEN 3
            ELSE 4
        END), j.jobname;
create or replace view public.v_loss_ledger as
 SELECT h.license,
    'Harvest waste'::text AS loss_type,
    h.name AS record,
    h.harvest_start AS occurred_on,
    h.raw ->> 'DryingLocationName'::text AS room,
    (h.raw ->> 'TotalWasteWeight'::text)::numeric AS amount,
    h.raw ->> 'UnitOfWeightName'::text AS uom,
    COALESCE(h.raw ->> 'HarvestType'::text, 'Harvest waste'::text) AS reason_code,
    h.raw ->> 'SourceStrainNames'::text AS detail
   FROM metrc_harvests h
  WHERE COALESCE((h.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric) > 0::numeric
UNION ALL
 SELECT p.license,
    'Package adjustment'::text AS loss_type,
    p.tag AS record,
    p.packaged_on AS occurred_on,
    p.location AS room,
    abs(COALESCE((p.raw ->> 'InitialQuantity'::text)::numeric, 0::numeric) - COALESCE(p.quantity, 0::numeric)) AS amount,
    p.uom,
    COALESCE(p.raw ->> 'ArchivedDate'::text, 'Quantity change'::text) AS reason_code,
    p.item_name AS detail
   FROM metrc_packages p
  WHERE COALESCE((p.raw ->> 'InitialQuantity'::text)::numeric, 0::numeric) > COALESCE(p.quantity, 0::numeric)
UNION ALL
 SELECT p.license,
    'Failed testing'::text AS loss_type,
    p.tag AS record,
    p.packaged_on AS occurred_on,
    p.location AS room,
    p.quantity AS amount,
    p.uom,
    'Laboratory test failed'::text AS reason_code,
    p.item_name AS detail
   FROM metrc_packages p
  WHERE p.lab_testing_state = 'TestFailed'::text;
create or replace view public.v_loss_ranking as
 SELECT scope_type,
    scope,
    harvests,
    wet_lbs,
    waste_lbs,
    waste_pct,
    yield_pct,
    verdict
   FROM ( SELECT 'Room'::text AS scope_type,
            COALESCE(metrc_harvests.raw ->> 'DryingLocationName'::text, '(no room)'::text) AS scope,
            count(*)::numeric AS harvests,
            round(sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) / 453.592, 1) AS wet_lbs,
            round(sum(COALESCE((metrc_harvests.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric)) / 453.592, 1) AS waste_lbs,
                CASE
                    WHEN sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) > 0::numeric THEN round(100.0 * sum(COALESCE((metrc_harvests.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric)) / sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)), 1)
                    ELSE NULL::numeric
                END AS waste_pct,
                CASE
                    WHEN sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) > 0::numeric THEN round(100.0 * sum(COALESCE((metrc_harvests.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric)) / sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)), 1)
                    ELSE NULL::numeric
                END AS yield_pct,
                CASE
                    WHEN sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) > 0::numeric AND (100.0 * sum(COALESCE((metrc_harvests.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric)) / sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric))) > 15::numeric THEN 'ABOVE ACCEPTABLE'::text
                    ELSE 'Within range'::text
                END AS verdict
           FROM metrc_harvests
          GROUP BY (COALESCE(metrc_harvests.raw ->> 'DryingLocationName'::text, '(no room)'::text))
        UNION ALL
         SELECT 'Strain'::text,
            COALESCE(metrc_harvests.raw ->> 'SourceStrainNames'::text, '(not recorded)'::text) AS "coalesce",
            count(*)::numeric AS count,
            round(sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) / 453.592, 1) AS round,
            round(sum(COALESCE((metrc_harvests.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric)) / 453.592, 1) AS round,
                CASE
                    WHEN sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) > 0::numeric THEN round(100.0 * sum(COALESCE((metrc_harvests.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric)) / sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)), 1)
                    ELSE NULL::numeric
                END AS "case",
                CASE
                    WHEN sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) > 0::numeric THEN round(100.0 * sum(COALESCE((metrc_harvests.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric)) / sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)), 1)
                    ELSE NULL::numeric
                END AS "case",
                CASE
                    WHEN sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) > 0::numeric AND (100.0 * sum(COALESCE((metrc_harvests.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric)) / sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric))) > 15::numeric THEN 'ABOVE ACCEPTABLE'::text
                    ELSE 'Within range'::text
                END AS "case"
           FROM metrc_harvests
          GROUP BY (COALESCE(metrc_harvests.raw ->> 'SourceStrainNames'::text, '(not recorded)'::text))) x
  WHERE wet_lbs > 0::numeric
  ORDER BY waste_pct DESC NULLS LAST;
create or replace view public.v_manifest_ledger as
 WITH per_manifest AS (
         SELECT metrc_transfers.manifest_number,
            min(metrc_transfers.created_on) AS created_on,
            array_agg(DISTINCT metrc_transfers.license ORDER BY metrc_transfers.license) AS licences,
            array_agg(DISTINCT metrc_transfers.direction ORDER BY metrc_transfers.direction) AS directions,
            (array_agg(metrc_transfers.shipper ORDER BY metrc_transfers.direction))[1] AS shipper,
            (array_agg(metrc_transfers.recipient ORDER BY (metrc_transfers.recipient IS NULL), metrc_transfers.direction))[1] AS recipient,
            count(*) AS row_count,
            (array_agg(metrc_transfers.raw ORDER BY (metrc_transfers.recipient IS NULL), metrc_transfers.direction))[1] AS raw
           FROM metrc_transfers
          GROUP BY metrc_transfers.manifest_number
        ), dest AS (
         SELECT pt.manifest_number,
            max(pt.destination_licence) AS destination_licence
           FROM metrc_rpt_package_transfers pt
          WHERE pt.destination_licence IS NOT NULL
          GROUP BY pt.manifest_number
        ), typed AS (
         SELECT m.manifest_number,
            m.created_on,
            m.licences,
            m.directions,
            m.shipper,
            m.recipient,
            m.row_count,
            m.raw,
            d.destination_licence,
            f_facility_type(d.destination_licence) AS destination_type,
            COALESCE(f_is_transporter(d.destination_licence), false) AS to_transporter,
            COALESCE(m.raw ->> 'ShipmentTypeName'::text, (m.raw -> '_delivery'::text) ->> 'ShipmentTypeName'::text) AS shipment_type,
            COALESCE(m.shipper, ''::text) ~~* '%twisted%'::text AS we_shipped,
            COALESCE(m.recipient, ''::text) ~~* '%twisted%'::text AS we_received
           FROM per_manifest m
             LEFT JOIN dest d ON d.manifest_number = m.manifest_number
        )
 SELECT manifest_number,
    created_on,
    licences,
    directions,
    shipper,
    recipient,
    row_count,
    shipment_type,
        CASE
            WHEN array_length(licences, 1) > 1 OR we_shipped AND we_received THEN 'Internal move'::text
            WHEN we_received AND NOT we_shipped THEN 'Inbound - bought in'::text
            WHEN shipment_type ~~* '%lab%'::text THEN 'Laboratory sample'::text
            WHEN shipment_type ~~* '%vendor sample%'::text THEN 'Vendor sample'::text
            WHEN shipment_type ~~* '%patient%'::text THEN 'Patient supply'::text
            WHEN to_transporter THEN 'Storage/transport movement'::text
            ELSE 'Customer sale'::text
        END AS movement,
        CASE
            WHEN array_length(licences, 1) > 1 THEN 'Both'::text
            ELSE f_operation(licences[1])
        END AS operation,
    licences[1] AS licence,
    array_length(licences, 1) = 1 AND NOT we_received AND COALESCE(shipment_type, ''::text) !~~* '%lab%'::text AND COALESCE(shipment_type, ''::text) !~~* '%vendor sample%'::text AND COALESCE(shipment_type, ''::text) !~~* '%patient%'::text AND NOT to_transporter AS is_customer_sale,
    we_received AND NOT we_shipped AS is_inbound_purchase,
    ( SELECT count(*) AS count
           FROM metrc_documents d
          WHERE d.manifest_number = t.manifest_number AND d.storage_path IS NOT NULL) AS documents,
    raw,
    (((((((manifest_number || ' '::text) || COALESCE(recipient, ''::text)) || ' '::text) || COALESCE(shipper, ''::text)) || ' '::text) || array_to_string(licences, ' '::text)) || ' '::text) || COALESCE(shipment_type, ''::text) AS search_text,
    destination_licence,
    destination_type,
    to_transporter
   FROM typed t;
create or replace view public.v_manifest_line_gaps as
 SELECT t.manifest_number,
    t.direction,
    t.created_on AS shipped_on,
    t.shipper,
    t.recipient,
    f_facility_type(COALESCE(t.raw ->> 'RecipientFacilityLicenseNumber'::text, t.raw ->> 'ShipperFacilityLicenseNumber'::text)) AS counterparty_type,
    COALESCE((t.raw ->> 'PackageCount'::text)::integer, 0) AS packages_metrc_says,
    0 AS package_lines_we_hold,
    d.storage_path AS manifest_document,
        CASE
            WHEN d.storage_path IS NOT NULL THEN (('ANSWERABLE — the manifest PDF is on file. Nothing has parsed it. '::text || 'Run manifest-parse against this manifest and the '::text) || COALESCE(t.raw ->> 'PackageCount'::text, '?'::text)) || ' package lines can be recovered.'::text
            WHEN d.fetch_error IS NOT NULL THEN 'DOCUMENT FAILED TO DOWNLOAD — '::text || "left"(d.fetch_error, 120)
            WHEN d.id IS NOT NULL THEN 'Document row exists but no file was ever stored.'::text
            ELSE 'NO DOCUMENT AND NO LINES — this shipment has no record of its contents anywhere.'::text
        END AS where_the_answer_is,
        CASE
            WHEN t.direction = 'outgoing'::text THEN 1
            ELSE 2
        END AS rank
   FROM metrc_transfers t
     LEFT JOIN metrc_documents d ON d.manifest_number = t.manifest_number AND d.doc_type ~~* '%manifest%'::text
  WHERE NOT (EXISTS ( SELECT 1
           FROM metrc_rpt_package_transfers r
          WHERE r.manifest_number = t.manifest_number));
create or replace view public.v_manifest_unparsed as
 SELECT metrc_id,
    storage_path,
    manifest_number
   FROM metrc_documents d
  WHERE doc_type = 'manifest'::text AND storage_path IS NOT NULL AND NOT (EXISTS ( SELECT 1
           FROM manifest_extract m
          WHERE m.manifest_number = d.manifest_number))
  ORDER BY manifest_number;
create or replace view public.v_material_aging as
 SELECT lot_code,
    supplier,
    material_type,
    strain_description,
    purchase_date,
    received_date,
    uom,
    purchased_qty,
    unit_cost,
    round(COALESCE(purchased_qty, 0::numeric) * COALESCE(unit_cost, 0::numeric) + COALESCE(freight, 0::numeric) + COALESCE(other_landed_cost, 0::numeric), 2) AS total_landed_cost,
        CASE
            WHEN COALESCE(purchased_qty, 0::numeric) > 0::numeric THEN round((COALESCE(purchased_qty, 0::numeric) * COALESCE(unit_cost, 0::numeric) + COALESCE(freight, 0::numeric) + COALESCE(other_landed_cost, 0::numeric)) / purchased_qty, 4)
            ELSE NULL::numeric
        END AS landed_cost_per_uom,
    allocated_qty,
    GREATEST(COALESCE(purchased_qty, 0::numeric) - COALESCE(allocated_qty, 0::numeric), 0::numeric) AS available_qty,
    work_order,
    allocation_date,
        CASE
            WHEN purchase_date IS NOT NULL AND allocation_date IS NOT NULL THEN allocation_date - purchase_date
            ELSE NULL::integer
        END AS days_to_allocation,
        CASE
            WHEN purchase_date IS NOT NULL AND fg_release_date IS NOT NULL THEN fg_release_date - purchase_date
            ELSE NULL::integer
        END AS days_purchase_to_release,
        CASE
            WHEN purchase_date IS NOT NULL AND cash_collected_date IS NOT NULL THEN cash_collected_date - purchase_date
            ELSE NULL::integer
        END AS days_purchase_to_cash,
    revenue_from_lot,
        CASE
            WHEN COALESCE(revenue_from_lot, 0::numeric) > 0::numeric THEN round(revenue_from_lot - (COALESCE(purchased_qty, 0::numeric) * COALESCE(unit_cost, 0::numeric) + COALESCE(freight, 0::numeric) + COALESCE(other_landed_cost, 0::numeric)), 2)
            ELSE NULL::numeric
        END AS gross_return,
        CASE
            WHEN COALESCE(revenue_from_lot, 0::numeric) > 0::numeric AND (COALESCE(purchased_qty, 0::numeric) * COALESCE(unit_cost, 0::numeric) + COALESCE(freight, 0::numeric) + COALESCE(other_landed_cost, 0::numeric)) > 0::numeric THEN round(100.0 * (revenue_from_lot - (COALESCE(purchased_qty, 0::numeric) * COALESCE(unit_cost, 0::numeric) + COALESCE(freight, 0::numeric) + COALESCE(other_landed_cost, 0::numeric))) / (COALESCE(purchased_qty, 0::numeric) * COALESCE(unit_cost, 0::numeric) + COALESCE(freight, 0::numeric) + COALESCE(other_landed_cost, 0::numeric)), 1)
            ELSE NULL::numeric
        END AS roi_pct,
        CASE
            WHEN purchase_date IS NOT NULL THEN CURRENT_DATE - purchase_date
            ELSE NULL::integer
        END AS aging_days,
        CASE
            WHEN GREATEST(COALESCE(purchased_qty, 0::numeric) - COALESCE(allocated_qty, 0::numeric), 0::numeric) > 0::numeric AND purchase_date IS NOT NULL AND (CURRENT_DATE - purchase_date) > COALESCE(( SELECT (configurations.value ->> 'days'::text)::integer AS int4
               FROM configurations
              WHERE configurations.key = 'material_aging_alert_days'::text), 30) THEN 'CAPITAL TIED UP'::text
            ELSE 'OK'::text
        END AS aging_alert,
    status
   FROM material_purchases m
  ORDER BY purchase_date DESC NULLS LAST;
create or replace view public.v_material_ownership_conflict as
 SELECT p.tag AS package_tag,
    "left"(p.item_name, 60) AS item_name,
    p.lab_testing_state,
    p.source_state,
    p.raw ->> 'LocationName'::text AS location,
        CASE
            WHEN f_is_weight(p.uom) THEN round(f_to_pounds(p.quantity, p.uom), 2)
            ELSE NULL::numeric
        END AS pounds,
    p.raw ->> 'ItemFromFacilityLicenseNumber'::text AS item_field_says,
    o.o -> 'origin_names'::text AS material_actually_from,
    o.o -> 'origin_licences'::text AS origin_licences,
    o.o -> 'inbound_manifests'::text AS inbound_manifests,
    (o.o ->> 'lineage_packages'::text)::integer AS lineage_packages,
    'THE ISSUE: the item field names one of our licences, but the material traces to an outside licence. Counting this as our stock overstates on-hand and misattributes any loss, cost or yield derived from it.'::text AS what_is_wrong,
    'Treat as third-party material. Ownership comes from f_material_origin, never from ItemFromFacilityLicenseNumber.'::text AS what_to_do
   FROM metrc_packages p
     CROSS JOIN LATERAL f_material_origin(p.tag) o(o)
  WHERE (p.source_state = ANY (ARRAY['active'::text, 'onhold'::text])) AND f_is_ours(p.raw ->> 'ItemFromFacilityLicenseNumber'::text) AND ((o.o ->> 'any_outside'::text)::boolean) IS TRUE;
create or replace view public.v_metrc_corrections_open as
 SELECT title,
    what_is_wrong,
    why_it_matters,
    how_to_fix_in_metrc,
    packages_affected,
    pounds,
    assigned_to,
    raised_on,
    raised_by,
    CURRENT_DATE - raised_on AS days_open,
    ((((('OPEN IN METRC. This does not clear itself and cannot be closed from this platform. It stays '::text || 'here until the correction is made in Metrc and someone records who did it, when, and what '::text) || 'was done. Raised '::text) || raised_on) || ', '::text) || (CURRENT_DATE - raised_on)) || ' days ago.'::text AS standing
   FROM metrc_corrections
  WHERE NOT fixed_in_metrc
  ORDER BY pounds DESC NULLS LAST;
create or replace view public.v_metrc_credential_risk as
 SELECT full_name,
    metrc_agent_badge AS badge,
    badge_expires,
    badge_expires - CURRENT_DATE AS days_until_expiry,
    status AS our_roster_says,
    metrc_license_status AS metrc_says,
        CASE
            WHEN badge_expires IS NULL AND status = 'active'::employment_status THEN 'ACTIVE STAFF WITH NO BADGE RECORDED - cannot prove they may legally handle product'::text
            WHEN badge_expires < CURRENT_DATE THEN ('EXPIRED '::text || (CURRENT_DATE - badge_expires)) || ' days ago'::text
            WHEN badge_expires <= (CURRENT_DATE + 14) AND status = 'active'::employment_status THEN ('EXPIRES IN '::text || (badge_expires - CURRENT_DATE)) || ' DAYS - active staff, renew now'::text
            WHEN badge_expires <= (CURRENT_DATE + 14) THEN ('EXPIRES IN '::text || (badge_expires - CURRENT_DATE)) || ' DAYS'::text
            ELSE 'ok'::text
        END AS badge_standing,
        CASE
            WHEN status = 'inactive'::employment_status AND metrc_license_status = 'Active'::text THEN 'DISAGREEMENT - we say they left, Metrc says their licence is Active. Either a former employee holds live credentials, or the roster is wrong.'::text
            WHEN status = 'active'::employment_status AND metrc_license_status IS DISTINCT FROM 'Active'::text THEN 'DISAGREEMENT - we say they work here, Metrc does not show an active licence. They may not legally handle product.'::text
            ELSE 'agrees'::text
        END AS roster_vs_metrc
   FROM employees e
  WHERE badge_expires IS NOT NULL OR status = 'active'::employment_status OR status = 'inactive'::employment_status AND metrc_license_status = 'Active'::text
  ORDER BY (
        CASE
            WHEN badge_expires < CURRENT_DATE THEN 0
            WHEN badge_expires <= (CURRENT_DATE + 14) THEN 1
            WHEN status = 'inactive'::employment_status AND metrc_license_status = 'Active'::text THEN 2
            ELSE 3
        END), badge_expires;
create or replace view public.v_metrc_facility_names as
 SELECT COALESCE((raw -> '_delivery'::text) ->> 'RecipientFacilityLicenseNumber'::text, raw ->> 'RecipientFacilityLicenseNumber'::text) AS facility_licence,
    COALESCE((raw -> '_delivery'::text) ->> 'RecipientFacilityName'::text, recipient) AS name_seen,
    created_on,
    manifest_number
   FROM metrc_transfers t
  WHERE COALESCE((raw -> '_delivery'::text) ->> 'RecipientFacilityLicenseNumber'::text, raw ->> 'RecipientFacilityLicenseNumber'::text) IS NOT NULL;
create or replace view public.v_metrc_lab_status as
 SELECT license,
    COALESCE(lab_testing_state, '—'::text) AS lab_testing_state,
    count(*) AS packages,
    round(sum(quantity), 2) AS total_qty,
    count(DISTINCT item_name) AS items
   FROM metrc_packages
  GROUP BY license, lab_testing_state
  ORDER BY license, (count(*)) DESC;
create or replace view public.v_metrc_package_inventory as
 SELECT license,
    item,
    location,
    packages,
    total_qty,
    uom,
    lab_state,
    finished_pkgs,
    oldest,
    newest,
    oldest AS oldest_date
   FROM ( SELECT metrc_packages.license,
            COALESCE(metrc_packages.item_name, '—'::text) AS item,
            COALESCE(metrc_packages.location, '—'::text) AS location,
            count(*) AS packages,
            round(sum(metrc_packages.quantity), 2) AS total_qty,
            min(metrc_packages.uom) AS uom,
            COALESCE(metrc_packages.lab_testing_state, '—'::text) AS lab_state,
            count(*) FILTER (WHERE metrc_packages.finished) AS finished_pkgs,
            min(metrc_packages.packaged_on) AS oldest,
            max(metrc_packages.packaged_on) AS newest
           FROM metrc_packages
          GROUP BY metrc_packages.license, metrc_packages.item_name, metrc_packages.location, metrc_packages.lab_testing_state
          ORDER BY metrc_packages.license, (round(sum(metrc_packages.quantity), 2)) DESC NULLS LAST) q;
create or replace view public.v_metrc_plant_census as
 SELECT license,
    room,
    phase,
    plants,
    strains,
    strain_breakdown,
    oldest_planting,
    newest_planting,
    oldest_days_in_room,
    oldest_planting AS oldest_planting_date
   FROM ( SELECT p.license,
            p.room,
                CASE p.source_state
                    WHEN 'vegetative'::text THEN 'Vegetative'::text
                    WHEN 'flowering'::text THEN 'Flowering'::text
                    WHEN 'onhold'::text THEN 'On hold'::text
                    ELSE 'Harvested or retired'::text
                END AS phase,
            count(*)::numeric AS plants,
            count(DISTINCT p.strain)::numeric AS strains,
            ( SELECT string_agg(x.line, ' · '::text ORDER BY x.n DESC) AS string_agg
                   FROM ( SELECT ((p2.strain || ' ('::text) || count(*)) || ')'::text AS line,
                            count(*) AS n
                           FROM metrc_plants p2
                          WHERE p2.license = p.license AND p2.room = p.room AND p2.source_state = p.source_state
                          GROUP BY p2.strain) x) AS strain_breakdown,
            min(p.planted_on) AS oldest_planting,
            max(p.planted_on) AS newest_planting,
            max(CURRENT_DATE - p.planted_on)::numeric AS oldest_days_in_room
           FROM metrc_plants p
          WHERE p.source_state = ANY (ARRAY['vegetative'::text, 'flowering'::text, 'onhold'::text])
          GROUP BY p.license, p.room, p.source_state
          ORDER BY (count(*)::numeric) DESC) q;
create or replace view public.v_metrc_scan_settings as
 SELECT job_name,
    display_name,
    endpoints,
    enabled,
    run_times,
    timezone,
    min_gap_minutes,
    what_it_pulls,
    why_it_matters,
    when_to_pull_now,
    calls_per_scan,
    cardinality(run_times) AS scans_per_day,
    calls_per_scan * cardinality(run_times) AS calls_per_day,
    last_run_at,
    last_result,
    ( SELECT min((((now() AT TIME ZONE s.timezone)::date + t.t) AT TIME ZONE s.timezone)) AS min
           FROM unnest(s.run_times) t(t)
          WHERE (((now() AT TIME ZONE s.timezone)::date + t.t) AT TIME ZONE s.timezone) > now()) AS next_run_at,
        CASE
            WHEN last_run_at IS NULL THEN 'Never run'::text
            WHEN (now() - last_run_at) < make_interval(mins => min_gap_minutes) THEN ('Pulled recently - manual scan is held for '::text || (min_gap_minutes::numeric - EXTRACT(epoch FROM now() - last_run_at) / 60::numeric)::integer) || ' more minutes'::text
            ELSE 'Ready - can be pulled now'::text
        END AS manual_scan_state,
    sort_order
   FROM metrc_scan_schedule s;
create or replace view public.v_metrc_seed_to_sale as
 SELECT strain,
    plants_growing_now,
    plants_harvested,
    harvest_events,
    wet_weight_lbs,
    waste_lbs,
    waste_pct,
    packaged_lbs,
    yield_pct,
    packages_made,
    manufactured_into,
    on_hand_now,
    sitting_in,
    packages_passed_testing,
    packages_failed_testing,
    packages_shipped_out,
    still_in_rooms,
    last_harvest,
    last_harvest AS last_harvest_date
   FROM ( WITH harv AS (
                 SELECT COALESCE(h_1.raw ->> 'SourceStrainNames'::text, 'Unassigned'::text) AS strain,
                    count(*) AS harvests,
                    sum(COALESCE((h_1.raw ->> 'PlantCount'::text)::numeric, 0::numeric)) AS plants_harvested,
                    sum(COALESCE((h_1.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) AS wet_g,
                    sum(COALESCE((h_1.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric)) AS waste_g,
                    sum(COALESCE((h_1.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric)) AS packaged_g,
                    string_agg(DISTINCT COALESCE(h_1.raw ->> 'DryingLocationName'::text, ''::text), ', '::text) FILTER (WHERE (h_1.raw ->> 'FinishedDate'::text) IS NULL) AS rooms_now,
                    max(h_1.harvest_start) AS last_harvest
                   FROM metrc_harvests h_1
                  GROUP BY (COALESCE(h_1.raw ->> 'SourceStrainNames'::text, 'Unassigned'::text))
                ), pk AS (
                 SELECT COALESCE(NULLIF(p.raw ->> 'SourceHarvestNames'::text, ''::text), '(no source)'::text) AS src,
                    p.tag,
                    p.item_name,
                    p.quantity,
                    p.uom,
                    p.location,
                    p.lab_testing_state,
                    p.source_state,
                    COALESCE(p.raw ->> 'ProductCategoryName'::text, ''::text) AS product_category
                   FROM metrc_packages p
                ), live AS (
                 SELECT x.strain,
                    sum(x.plants) AS plants_live
                   FROM ( SELECT COALESCE(metrc_plants.strain, 'Unassigned'::text) AS strain,
                            count(*) AS plants
                           FROM metrc_plants
                          WHERE metrc_plants.source_state = ANY (ARRAY['vegetative'::text, 'flowering'::text, 'onhold'::text])
                          GROUP BY (COALESCE(metrc_plants.strain, 'Unassigned'::text))) x
                  GROUP BY x.strain
                )
         SELECT h.strain,
            COALESCE(l.plants_live, 0::numeric) AS plants_growing_now,
            h.plants_harvested,
            h.harvests AS harvest_events,
            round(h.wet_g / 453.592, 1) AS wet_weight_lbs,
            round(h.waste_g / 453.592, 1) AS waste_lbs,
                CASE
                    WHEN h.wet_g > 0::numeric THEN round(100.0 * h.waste_g / h.wet_g, 1)
                    ELSE NULL::numeric
                END AS waste_pct,
            round(h.packaged_g / 453.592, 1) AS packaged_lbs,
                CASE
                    WHEN h.wet_g > 0::numeric THEN round(100.0 * h.packaged_g / h.wet_g, 1)
                    ELSE NULL::numeric
                END AS yield_pct,
            ( SELECT count(*) AS count
                   FROM pk
                  WHERE pk.src ~~* (('%'::text || h.strain) || '%'::text)) AS packages_made,
            ( SELECT string_agg(DISTINCT pk.product_category, ', '::text) AS string_agg
                   FROM pk
                  WHERE pk.src ~~* (('%'::text || h.strain) || '%'::text) AND pk.product_category <> ''::text) AS manufactured_into,
            ( SELECT round(sum(COALESCE(pk.quantity, 0::numeric)), 1) AS round
                   FROM pk
                  WHERE pk.src ~~* (('%'::text || h.strain) || '%'::text) AND (pk.source_state = ANY (ARRAY['active'::text, 'onhold'::text]))) AS on_hand_now,
            ( SELECT string_agg(DISTINCT pk.location, ', '::text) AS string_agg
                   FROM pk
                  WHERE pk.src ~~* (('%'::text || h.strain) || '%'::text) AND (pk.source_state = ANY (ARRAY['active'::text, 'onhold'::text])) AND pk.location IS NOT NULL) AS sitting_in,
            ( SELECT count(*) AS count
                   FROM pk
                  WHERE pk.src ~~* (('%'::text || h.strain) || '%'::text) AND pk.lab_testing_state = 'TestPassed'::text) AS packages_passed_testing,
            ( SELECT count(*) AS count
                   FROM pk
                  WHERE pk.src ~~* (('%'::text || h.strain) || '%'::text) AND pk.lab_testing_state = 'TestFailed'::text) AS packages_failed_testing,
            ( SELECT count(*) AS count
                   FROM pk
                  WHERE pk.src ~~* (('%'::text || h.strain) || '%'::text) AND pk.source_state = 'intransit'::text) AS packages_shipped_out,
            NULLIF(h.rooms_now, ''::text) AS still_in_rooms,
            h.last_harvest
           FROM harv h
             LEFT JOIN live l ON l.strain = h.strain
          WHERE h.strain <> 'Unassigned'::text
          ORDER BY h.wet_g DESC NULLS LAST) q;
create or replace view public.v_metrc_strain_census as
 SELECT license,
    strain,
    live_plants_now,
    vegetative_now,
    flowering_now,
    on_hold_now,
    harvested_or_retired,
    total_plants_all_time,
    rooms_now,
    in_rooms,
    first_planted,
    last_planted,
    harvest_events,
    lifetime_wet_lbs,
    lifetime_packaged_lbs,
    first_planted AS first_planted_date
   FROM ( WITH base AS (
                 SELECT p.license,
                    COALESCE(p.strain, 'not recorded'::text) AS strain,
                    count(*) FILTER (WHERE p.source_state = ANY (ARRAY['vegetative'::text, 'flowering'::text, 'onhold'::text]))::numeric AS live_plants_now,
                    count(*) FILTER (WHERE p.source_state = 'vegetative'::text)::numeric AS vegetative_now,
                    count(*) FILTER (WHERE p.source_state = 'flowering'::text)::numeric AS flowering_now,
                    count(*) FILTER (WHERE p.source_state = 'onhold'::text)::numeric AS on_hold_now,
                    count(*) FILTER (WHERE p.source_state = 'inactive'::text)::numeric AS harvested_or_retired,
                    count(*)::numeric AS total_plants_all_time,
                    count(DISTINCT p.room) FILTER (WHERE p.source_state = ANY (ARRAY['vegetative'::text, 'flowering'::text, 'onhold'::text]))::numeric AS rooms_now,
                    string_agg(DISTINCT p.room, ', '::text) FILTER (WHERE p.source_state = ANY (ARRAY['vegetative'::text, 'flowering'::text, 'onhold'::text])) AS in_rooms,
                    min(p.planted_on) AS first_planted,
                    max(p.planted_on) AS last_planted
                   FROM metrc_plants p
                  GROUP BY p.license, (COALESCE(p.strain, 'not recorded'::text))
                )
         SELECT b.license,
            b.strain,
            b.live_plants_now,
            b.vegetative_now,
            b.flowering_now,
            b.on_hold_now,
            b.harvested_or_retired,
            b.total_plants_all_time,
            b.rooms_now,
            b.in_rooms,
            b.first_planted,
            b.last_planted,
            ( SELECT count(*) AS count
                   FROM metrc_harvests h
                  WHERE COALESCE(h.raw ->> 'SourceStrainNames'::text, ''::text) ~~* (('%'::text || b.strain) || '%'::text)) AS harvest_events,
            ( SELECT round(sum(COALESCE((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) / 453.592, 1) AS round
                   FROM metrc_harvests h
                  WHERE COALESCE(h.raw ->> 'SourceStrainNames'::text, ''::text) ~~* (('%'::text || b.strain) || '%'::text)) AS lifetime_wet_lbs,
            ( SELECT round(sum(COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric)) / 453.592, 1) AS round
                   FROM metrc_harvests h
                  WHERE COALESCE(h.raw ->> 'SourceStrainNames'::text, ''::text) ~~* (('%'::text || b.strain) || '%'::text)) AS lifetime_packaged_lbs
           FROM base b
          ORDER BY b.live_plants_now DESC, b.total_plants_all_time DESC) q;
create or replace view public.v_metrc_transfer_ledger as
 SELECT manifest_number,
    direction,
    created_on,
    (raw ->> 'ReceivedDateTime'::text)::date AS received_on,
    shipper,
    recipient,
    raw ->> 'RecipientFacilityLicenseNumber'::text AS recipient_license,
    raw ->> 'ShipperFacilityLicenseNumber'::text AS shipper_license,
    COALESCE((raw ->> 'PackageCount'::text)::numeric, 0::numeric) AS packages,
    COALESCE((raw ->> 'ReceivedPackageCount'::text)::numeric, 0::numeric) AS packages_received,
    raw ->> 'TransporterFacilityName'::text AS transporter,
    raw ->> 'DriverName'::text AS driver,
    raw ->> 'VehicleMake'::text AS vehicle_make,
    raw ->> 'VehicleLicensePlateNumber'::text AS vehicle_plate,
    (raw ->> 'EstimatedDepartureDateTime'::text)::timestamp with time zone AS departed,
    (raw ->> 'EstimatedArrivalDateTime'::text)::timestamp with time zone AS arrival_estimate,
    raw ->> 'ShipmentTypeName'::text AS shipment_type,
        CASE
            WHEN (raw ->> 'Id'::text) IS NOT NULL THEN ('https://ma.metrc.com/reports/transfers/'::text || (raw ->> 'Id'::text)) || '/manifest'::text
            ELSE NULL::text
        END AS manifest_link,
    raw ->> 'Id'::text AS metrc_transfer_id,
    license
   FROM metrc_transfers t
  ORDER BY created_on DESC NULLS LAST;
create or replace view public.v_metrc_vs_os as
 WITH x AS (
         SELECT 'Packages - Inventory'::text AS metrc_report,
            'metrc_rpt_packages_inventory'::text AS report_table,
            'metrc_packages (API sync)'::text AS os_source,
            (( SELECT count(*) AS count
                   FROM metrc_rpt_packages_inventory))::numeric AS report_rows,
            (( SELECT count(DISTINCT metrc_packages.tag) AS count
                   FROM metrc_packages
                  WHERE metrc_packages.source_state = ANY (ARRAY['active'::text, 'onhold'::text])))::numeric AS os_rows,
            'The export is a point-in-time snapshot; the API holds live state. A large gap means the export is stale.'::text AS note
        UNION ALL
         SELECT 'Harvests'::text,
            'metrc_rpt_harvests'::text,
            'metrc_harvests (API sync)'::text,
            ( SELECT count(*) AS count
                   FROM metrc_rpt_harvests) AS count,
            ( SELECT count(*) AS count
                   FROM metrc_harvests) AS count,
            'Must match exactly. Both describe the same harvest population.'::text
        UNION ALL
         SELECT 'Lab Results'::text,
            'metrc_rpt_lab_results'::text,
            'metrc_lab_results (API sync)'::text,
            ( SELECT count(DISTINCT metrc_rpt_lab_results.package_tag) AS count
                   FROM metrc_rpt_lab_results) AS count,
            ( SELECT count(DISTINCT metrc_lab_results.package_tag) AS count
                   FROM metrc_lab_results) AS count,
            'Compared on DISTINCT PACKAGES, not rows - the API holds one row per analyte, the export one per test.'::text
        UNION ALL
         SELECT 'Transfers - Manifests'::text,
            'metrc_rpt_transfer_manifests'::text,
            'metrc_transfers (API sync)'::text,
            ( SELECT count(DISTINCT metrc_rpt_transfer_manifests.manifest_number) AS count
                   FROM metrc_rpt_transfer_manifests) AS count,
            ( SELECT count(DISTINCT metrc_transfers.manifest_number) AS count
                   FROM metrc_transfers) AS count,
            'Every manifest in the API must appear in the export. 49 do not - 42 live incoming covering 277 packages.'::text
        UNION ALL
         SELECT 'Packages - Transferred'::text,
            'metrc_rpt_package_transfers'::text,
            'manifests carrying package lines'::text,
            ( SELECT count(DISTINCT metrc_rpt_package_transfers.manifest_number) AS count
                   FROM metrc_rpt_package_transfers) AS count,
            ( SELECT count(DISTINCT metrc_transfers.manifest_number) AS count
                   FROM metrc_transfers) AS count,
            'This export is the ONLY link between a package and its manifest. Anything it omits loses its custody evidence.'::text
        UNION ALL
         SELECT 'Wholesale Transfers'::text,
            'metrc_rpt_wholesale'::text,
            'metrc_rpt_package_transfers (the other export)'::text,
            ( SELECT count(DISTINCT metrc_rpt_wholesale.manifest_number) AS count
                   FROM metrc_rpt_wholesale) AS count,
            ( SELECT count(DISTINCT metrc_rpt_package_transfers.manifest_number) AS count
                   FROM metrc_rpt_package_transfers) AS count,
            'Two Metrc reports describing the same movements. They differ by $72,828 in value - one is incomplete.'::text
        UNION ALL
         SELECT 'Adjustments'::text,
            'metrc_rpt_adjustments'::text,
            'packages with an adjustment'::text,
            ( SELECT count(DISTINCT metrc_rpt_adjustments.package_tag) AS count
                   FROM metrc_rpt_adjustments) AS count,
            ( SELECT count(DISTINCT metrc_packages.tag) AS count
                   FROM metrc_packages
                  WHERE ((metrc_packages.raw ->> 'CreatedQuantity'::text)::numeric) <> metrc_packages.quantity) AS count,
            'Packages whose quantity changed after creation should appear in the adjustments export.'::text
        UNION ALL
         SELECT 'Harvest Moisture'::text,
            'metrc_rpt_harvest_moisture'::text,
            'metrc_harvests (API sync)'::text,
            ( SELECT count(*) AS count
                   FROM metrc_rpt_harvest_moisture) AS count,
            ( SELECT count(*) AS count
                   FROM metrc_harvests) AS count,
            'Moisture is recorded per harvest. A gap means harvests with no moisture entry.'::text
        UNION ALL
         SELECT 'Test Batches'::text,
            'metrc_rpt_test_batches'::text,
            'distinct lab test batches'::text,
            ( SELECT count(*) AS count
                   FROM metrc_rpt_test_batches) AS count,
            ( SELECT count(DISTINCT metrc_lab_results.raw ->> 'LabTestResultId'::text) AS count
                   FROM metrc_lab_results) AS count,
            'Each test batch should correspond to a lab result set.'::text
        )
 SELECT metrc_report,
    report_table,
    os_source,
    report_rows,
    os_rows,
    report_rows - os_rows AS difference,
        CASE
            WHEN os_rows > 0::numeric THEN round(abs(report_rows - os_rows) / os_rows * 100::numeric, 2)
            ELSE NULL::numeric
        END AS pct_apart,
        CASE
            WHEN report_rows = os_rows THEN 'AGREE'::text
            WHEN report_rows = 0::numeric THEN 'REPORT NOT IMPORTED'::text
            ELSE 'DISCREPANCY'::text
        END AS verdict,
    note,
    'THE ISSUE: a Metrc report export and the Metrc API describe the same facts. Where they differ one is incomplete, and neither figure may be quoted until it is known which.'::text AS what_is_wrong,
    'Re-pull the export for the affected licence and date range, then re-compare. Never reconcile by preferring the larger number.'::text AS what_to_do
   FROM x;
create or replace view public.v_metric_registry_gaps as
 SELECT 'Metrics registered'::text AS measure,
    count(*)::text AS value,
    'One definition each. Every one has a drill - rule C1 is enforced by NOT NULL.'::text AS note
   FROM metric_registry
  WHERE metric_registry.active
UNION ALL
 SELECT 'Needing a declared drill filter'::text AS measure,
    (count(*)::text || ' of '::text) || (( SELECT count(*)::text AS count
           FROM metric_registry metric_registry_1
          WHERE metric_registry_1.active)) AS value,
    'Until declared, the tile cannot be reconciled to its rows automatically. This is the number that justifies the registry.'::text AS note
   FROM metric_registry
  WHERE metric_registry.active AND metric_registry.drill_filter IS NULL
UNION ALL
 SELECT 'Needing a declared target'::text AS measure,
    (count(*)::text || ' of '::text) || (( SELECT count(*)::text AS count
           FROM metric_registry metric_registry_1
          WHERE metric_registry_1.active)) AS value,
    'Without a target the tile cannot turn red on breach, and a movement cannot be judged good or bad. Owner-set - never guessed.'::text AS note
   FROM metric_registry
  WHERE metric_registry.active AND metric_registry.target_rule_key IS NULL
UNION ALL
 SELECT 'Needing a roll-up parent'::text AS measure,
    (count(*)::text || ' of '::text) || (( SELECT count(*)::text AS count
           FROM metric_registry metric_registry_1
          WHERE metric_registry_1.active)) AS value,
    'Until declared, the CEO and Tower boards compute their own version instead of deriving from departments.'::text AS note
   FROM metric_registry
  WHERE metric_registry.active AND metric_registry.rolls_up_to_metric IS NULL
UNION ALL
 SELECT 'DUPLICATED across departments'::text AS measure,
    ( SELECT count(*)::text AS count
           FROM ( SELECT metric_registry.label
                   FROM metric_registry
                  WHERE metric_registry.active
                  GROUP BY metric_registry.label
                 HAVING count(*) > 1) d) AS value,
    'The same fact registered under more than one department, each maintained by repetition rather than derivation. If one changes and the other does not, they diverge silently - this is what rolls_up_to_metric replaces.'::text AS note;
create or replace view public.v_moisture_accounting as
 SELECT harvest,
    strain,
    room,
    harvest_start,
    finished,
    plants,
    stream,
    wet_lb,
    packaged_lb,
    recorded_waste_lb,
    moisture_lb,
    metrc_current_weight_lb,
    reconciliation_gap_lb,
    moisture_pct_of_wet,
    conversion_pct,
    the_arithmetic,
    verdict,
    harvest_start AS harvest_start_date
   FROM ( WITH h AS (
                 SELECT metrc_harvests.name AS harvest,
                    metrc_harvests.harvest_start,
                    (metrc_harvests.raw ->> 'FinishedDate'::text)::date AS finished,
                    COALESCE(NULLIF(metrc_harvests.raw ->> 'DryingLocationName'::text, ''::text), '(not recorded)'::text) AS room,
                    COALESCE(NULLIF(metrc_harvests.raw ->> 'SourceStrainNames'::text, ''::text), '(not recorded)'::text) AS strain,
                    (metrc_harvests.raw ->> 'PlantCount'::text)::integer AS plants,
                    metrc_harvests.wet_weight AS wet_g,
                    metrc_harvests.waste_weight AS waste_g,
                    (metrc_harvests.raw ->> 'TotalPackagedWeight'::text)::numeric AS pkg_g,
                    (metrc_harvests.raw ->> 'CurrentWeight'::text)::numeric AS current_g,
                    metrc_harvests.name ~~* '%FF%'::text OR COALESCE(NULLIF(metrc_harvests.raw ->> 'DryingLocationName'::text, ''::text), ''::text) ~~* '%freezer%'::text AS fresh_frozen
                   FROM metrc_harvests
                )
         SELECT h.harvest,
            h.strain,
            h.room,
            h.harvest_start,
            h.finished,
            h.plants,
                CASE
                    WHEN h.fresh_frozen THEN 'Fresh frozen'::text
                    ELSE 'Dried flower'::text
                END AS stream,
            round(h.wet_g / 453.592, 2) AS wet_lb,
            round(h.pkg_g / 453.592, 2) AS packaged_lb,
            round(h.waste_g / 453.592, 2) AS recorded_waste_lb,
            round((h.wet_g - h.pkg_g - h.waste_g) / 453.592, 2) AS moisture_lb,
            round(h.current_g / 453.592, 2) AS metrc_current_weight_lb,
            round((h.wet_g - h.pkg_g - h.waste_g - h.current_g) / 453.592, 2) AS reconciliation_gap_lb,
                CASE
                    WHEN h.wet_g > 0::numeric THEN round(100::numeric * (h.wet_g - h.pkg_g - h.waste_g) / h.wet_g, 1)
                    ELSE NULL::numeric
                END AS moisture_pct_of_wet,
                CASE
                    WHEN h.wet_g > 0::numeric THEN round(100::numeric * h.pkg_g / h.wet_g, 1)
                    ELSE NULL::numeric
                END AS conversion_pct,
            ((((((round(h.wet_g / 453.592, 2) || ' lb wet = '::text) || round(h.pkg_g / 453.592, 2)) || ' packaged + '::text) || round(h.waste_g / 453.592, 2)) || ' waste + '::text) || round((h.wet_g - h.pkg_g - h.waste_g) / 453.592, 2)) || ' evaporated'::text AS the_arithmetic,
                CASE
                    WHEN h.fresh_frozen THEN 'FRESH FROZEN - packaged at field moisture, so almost no water leaves. Never judge this against a dried-flower conversion.'::text
                    WHEN h.wet_g = 0::numeric THEN 'NO WET WEIGHT RECORDED - cannot be reconciled.'::text
                    WHEN abs(h.wet_g - h.pkg_g - h.waste_g - h.current_g) > (h.wet_g * 0.02) THEN ('DOES NOT RECONCILE - Metrc current weight disagrees by '::text || round(abs(h.wet_g - h.pkg_g - h.waste_g - h.current_g) / 453.592, 2)) || ' lb. Investigate.'::text
                    WHEN (100::numeric * (h.wet_g - h.pkg_g - h.waste_g) / h.wet_g) >= 70::numeric AND (100::numeric * (h.wet_g - h.pkg_g - h.waste_g) / h.wet_g) <= 82::numeric THEN ('NORMAL - '::text || round(100::numeric * (h.wet_g - h.pkg_g - h.waste_g) / h.wet_g, 1)) || ' percent moisture loss, inside the expected 70 to 82 percent.'::text
                    WHEN (100::numeric * (h.wet_g - h.pkg_g - h.waste_g) / h.wet_g) > 82::numeric THEN ('MOISTURE LOSS HIGH at '::text || round(100::numeric * (h.wet_g - h.pkg_g - h.waste_g) / h.wet_g, 1)) || ' percent. Over-dried, or packaged weight recorded low.'::text
                    ELSE ('MOISTURE LOSS LOW at '::text || round(100::numeric * (h.wet_g - h.pkg_g - h.waste_g) / h.wet_g, 1)) || ' percent. Wet weight probably recorded too low at takedown.'::text
                END AS verdict
           FROM h) q;
create or replace view public.v_money_provenance as
 WITH money_cols AS (
         SELECT c.table_name AS view_name,
            c.column_name
           FROM information_schema.columns c
          WHERE c.table_schema::name = 'public'::name AND c.table_name::name ~~ 'v\_%'::text AND (c.column_name::name ~~* '%dollar%'::text OR c.column_name::name ~~* '%value_at%'::text OR c.column_name::name ~~* '%cost_per%'::text OR c.column_name::name ~~* '%_value%'::text OR c.column_name::name ~~* 'value'::text OR c.column_name::name ~~* '%revenue%'::text OR c.column_name::name ~~* '%price%'::text)
        ), defs AS (
         SELECT m.view_name,
            m.column_name,
            pg_get_viewdef(quote_ident(m.view_name::text)::regclass::oid, true) AS body
           FROM money_cols m
        )
 SELECT view_name,
    column_name,
        CASE
            WHEN body ~~* '%f_rate_for%'::text THEN 'Valuation Rates, per stream'::text
            WHEN body ~~* '%target_cost_per_lb%'::text THEN 'Central fallback: conversion_factors.target_cost_per_lb'::text
            WHEN body ~~* '%inventory_values%'::text THEN 'Inventory Values sheet: value per unit'::text
            WHEN body ~~* '%cost_model%'::text THEN 'Cost Model: cost per pound'::text
            WHEN body ~~* '%employee_rates%'::text OR body ~~* '%payroll%'::text THEN 'Payroll: employee rates'::text
            WHEN body ~~* '%unit_cost%'::text OR body ~~* '%landed_cost%'::text THEN 'Purchase records: landed cost'::text
            WHEN body ~~* '%ai_%'::text THEN 'Artificial intelligence usage records'::text
            ELSE 'NOT TRACED — this figure is not derived from any known rate table'::text
        END AS rate_source,
        CASE
            WHEN body ~~* '%f_rate_for%'::text THEN 'Correct — uses the per stream rate and any batch override.'::text
            WHEN body ~~* '%target_cost_per_lb%'::text THEN 'Uses one flat number for every stream. Accurate only where the streams really are worth the same.'::text
            WHEN body ~~* '%ai_%'::text OR body ~~* '%payroll%'::text OR body ~~* '%employee_rates%'::text OR body ~~* '%landed_cost%'::text OR body ~~* '%unit_cost%'::text THEN 'Correct — this is a recorded cost, not an estimated rate.'::text
            ELSE 'Cannot be explained from the definition. Treat this figure as unproven.'::text
        END AS verdict
   FROM defs d
  ORDER BY (
        CASE
            WHEN body ~~* '%f_rate_for%'::text THEN 3
            WHEN body ~~* '%target_cost_per_lb%'::text THEN 2
            ELSE 1
        END), view_name, column_name;
create or replace view public.v_monthly_yield as
 WITH h AS (
         SELECT to_char(date_trunc('month'::text, COALESCE((metrc_harvests.raw ->> 'FinishedDate'::text)::date, metrc_harvests.harvest_start)::timestamp with time zone), 'YYYY-MM'::text) AS month,
            date_trunc('month'::text, COALESCE((metrc_harvests.raw ->> 'FinishedDate'::text)::date, metrc_harvests.harvest_start)::timestamp with time zone)::date AS month_date,
            count(*) AS harvests,
            sum((metrc_harvests.raw ->> 'PlantCount'::text)::numeric) AS plants,
            sum((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric) / 453.592 AS wet_lb,
            sum((metrc_harvests.raw ->> 'TotalWasteWeight'::text)::numeric) / 453.592 AS waste_lb,
            sum(COALESCE((metrc_harvests.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric)) / 453.592 AS packaged_lb,
            sum(COALESCE((metrc_harvests.raw ->> 'CurrentWeight'::text)::numeric, 0::numeric)) / 453.592 AS still_on_harvest_lb
           FROM metrc_harvests
          WHERE COALESCE((metrc_harvests.raw ->> 'FinishedDate'::text)::date, metrc_harvests.harvest_start) IS NOT NULL
          GROUP BY (to_char(date_trunc('month'::text, COALESCE((metrc_harvests.raw ->> 'FinishedDate'::text)::date, metrc_harvests.harvest_start)::timestamp with time zone), 'YYYY-MM'::text)), (date_trunc('month'::text, COALESCE((metrc_harvests.raw ->> 'FinishedDate'::text)::date, metrc_harvests.harvest_start)::timestamp with time zone)::date)
        ), cat AS (
         SELECT to_char(date_trunc('month'::text, p.packaged_on::timestamp with time zone), 'YYYY-MM'::text) AS month,
            sum(f_to_pounds((p.raw ->> 'CreatedQuantity'::text)::numeric, COALESCE(p.raw ->> 'CreatedQuantityUnitOfMeasureAbbreviation'::text, p.uom))) FILTER (WHERE (p.raw #>> '{Item,ProductCategoryName}'::text[]) = 'Buds'::text AND NULLIF(p.raw ->> 'SourcePackageLabels'::text, ''::text) IS NULL) AS flower_lb,
            sum(f_to_pounds((p.raw ->> 'CreatedQuantity'::text)::numeric, COALESCE(p.raw ->> 'CreatedQuantityUnitOfMeasureAbbreviation'::text, p.uom))) FILTER (WHERE (p.raw #>> '{Item,ProductCategoryName}'::text[]) ~~ 'Shake/Trim%'::text AND NULLIF(p.raw ->> 'SourcePackageLabels'::text, ''::text) IS NULL) AS trim_lb,
            sum(f_to_pounds((p.raw ->> 'CreatedQuantity'::text)::numeric, COALESCE(p.raw ->> 'CreatedQuantityUnitOfMeasureAbbreviation'::text, p.uom))) FILTER (WHERE (p.raw #>> '{Item,ProductCategoryName}'::text[]) = 'Fresh Frozen Flower'::text AND NULLIF(p.raw ->> 'SourcePackageLabels'::text, ''::text) IS NULL) AS fresh_frozen_lb
           FROM metrc_packages p
          WHERE p.packaged_on IS NOT NULL
          GROUP BY (to_char(date_trunc('month'::text, p.packaged_on::timestamp with time zone), 'YYYY-MM'::text))
        )
 SELECT h.month,
    h.month_date,
    h.harvests,
    round(h.plants) AS plants,
    round(h.wet_lb, 1) AS wet_lb,
    round(h.waste_lb, 1) AS waste_lb,
    round(h.packaged_lb, 1) AS packaged_lb,
    round(h.still_on_harvest_lb, 1) AS still_on_harvest_lb,
    round(COALESCE(c.flower_lb, 0::numeric), 1) AS dried_flower_lb,
    round(COALESCE(c.trim_lb, 0::numeric), 1) AS trim_lb,
    round(COALESCE(c.fresh_frozen_lb, 0::numeric), 1) AS fresh_frozen_lb,
    380::numeric AS target_lb,
    round(COALESCE(c.flower_lb, 0::numeric) - 380::numeric, 1) AS flower_vs_target_lb,
        CASE
            WHEN COALESCE(c.flower_lb, 0::numeric) >= 380::numeric THEN 'MET'::text
            ELSE 'BELOW TARGET'::text
        END AS target_status,
        CASE
            WHEN h.wet_lb > 0::numeric THEN round(100.0 * COALESCE(c.flower_lb, 0::numeric) / h.wet_lb, 1)
            ELSE NULL::numeric
        END AS flower_pct_of_wet,
    ((('Dried flower, trim and fresh frozen count only packages made DIRECTLY from a '::text || 'harvest - a package repackaged from another package still carries the harvest '::text) || 'name and would be counted twice. Metrc records no split by category on the '::text) || 'harvest itself, so packaged_lb is its authoritative total and the three '::text) || 'categories are directional.'::text AS how_this_is_counted
   FROM h
     LEFT JOIN cat c ON c.month = h.month;
create or replace view public.v_my_alerts as
 SELECT id,
    role,
    severity,
    channel,
    subject,
    body,
    entity_type,
    entity_key,
    source,
    source_ref,
    reminder_number,
    escalated_from,
    raised_on,
    days_open,
    created_at,
    read_at,
    sent_at,
    send_error,
    read_at IS NULL AS unread
   FROM alert_outbox o
  WHERE resolved_at IS NULL AND channel = 'in_app'::text
  ORDER BY (
        CASE severity
            WHEN 'critical'::text THEN 1
            WHEN 'elevated'::text THEN 2
            ELSE 3
        END), created_at DESC;
create or replace view public.v_offboarding_open as
 SELECT o.id,
    e.employee_code,
    e.full_name,
    o.kind,
    o.voluntary,
    o.last_day,
    o.final_pay_due_on,
    o.final_pay_paid_on IS NULL AND o.final_pay_due_on IS NOT NULL AND o.final_pay_due_on <= CURRENT_DATE AS final_pay_overdue,
    o.ccc_deactivated_on IS NULL AS ccc_still_active,
    e.metrc_agent_badge,
    e.badge_expires,
    NOT o.badge_returned OR NOT o.keys_returned OR NOT o.equipment_returned AS property_outstanding,
    o.system_access_revoked_on IS NULL AS access_still_live,
    o.status
   FROM offboarding o
     JOIN employees e ON e.id = o.employee_id
  WHERE o.status <> 'complete'::text;
create or replace view public.v_on_the_floor as
 SELECT t.id AS time_entry_id,
    e.id AS employee_id,
    e.employee_code,
    e.full_name,
    COALESCE(d.name, 'Unassigned'::text) AS department,
    COALESCE(btrim(s.zone), 'No zone'::text) AS zone,
    st.name AS shift,
    t.clock_in,
    t.work_date,
    t.source,
    t.late_minutes,
    t.early_minutes,
    pd.label AS device,
    round(EXTRACT(epoch FROM now() - t.clock_in) / 3600.0, 2) AS hours_so_far,
    s.work_date + s.planned_start AS planned_start,
    s.work_date + s.planned_end AS planned_end,
    round(EXTRACT(epoch FROM s.work_date + s.planned_end - now()::timestamp without time zone) / 3600.0, 2) AS hours_left_scheduled,
    r.rate,
    round(EXTRACT(epoch FROM now() - t.clock_in) / 3600.0 * r.rate * (1::numeric + COALESCE(r.burden_pct, 0::numeric)), 2) AS cost_so_far_loaded,
    bw.name AS break_window,
    bw.starts_at AS break_from,
    bw.ends_at AS break_to,
    now()::time without time zone >= bw.starts_at AND now()::time without time zone <= bw.ends_at AS on_break_now,
    e.badge_expires,
    e.badge_expires IS NOT NULL AND e.badge_expires < CURRENT_DATE AS licence_lapsed
   FROM time_entries t
     JOIN employees e ON e.id = t.employee_id
     LEFT JOIN employee_schedules s ON s.employee_id = t.employee_id AND s.work_date = t.work_date
     LEFT JOIN shift_templates st ON st.id = s.shift_template_id
     LEFT JOIN departments d ON d.id = COALESCE(s.department_id, e.primary_department_id)
     LEFT JOIN punch_devices pd ON pd.id = t.device_id
     LEFT JOIN break_windows bw ON bw.active AND (bw.department_id IS NULL OR bw.department_id = COALESCE(s.department_id, e.primary_department_id))
     LEFT JOIN LATERAL ( SELECT r2.id,
            r2.employee_id,
            r2.basis,
            r2.rate,
            r2.ot_multiplier,
            r2.burden_pct,
            r2.effective_from,
            r2.effective_to,
            r2.approved_by,
            r2.note,
            r2.effective_from_date
           FROM employee_rates r2
          WHERE r2.employee_id = t.employee_id AND r2.effective_from <= t.work_date AND (r2.effective_to IS NULL OR r2.effective_to >= t.work_date)
          ORDER BY r2.effective_from DESC
         LIMIT 1) r ON true
  WHERE t.clock_in IS NOT NULL AND t.clock_out IS NULL;
create or replace view public.v_open_issues as
 WITH latest AS (
         SELECT DISTINCT ON (f.fingerprint) f.id,
            f.run_id,
            f.observed_at,
            f.fingerprint,
            f.severity,
            f.what,
            f.where_it_is,
            f.who_is_accountable,
            f.when_it_started,
            f.why_it_matters,
            f.how_it_was_detected,
            f.what_to_do,
            f.the_arithmetic,
            f.evidence,
            f.record_count,
            f.pounds,
            f.dollars,
            f.drill,
            f.search_text,
            ( SELECT count(*) AS count
                   FROM watchdog_findings x
                  WHERE x.fingerprint = f.fingerprint) AS times_seen,
            ( SELECT min(x.observed_at) AS min
                   FROM watchdog_findings x
                  WHERE x.fingerprint = f.fingerprint) AS first_seen
           FROM watchdog_findings f
          ORDER BY f.fingerprint, f.observed_at DESC
        )
 SELECT l.fingerprint AS issue_key,
    l.severity,
    l.what AS issue,
    l.where_it_is,
    l.who_is_accountable,
    l.when_it_started,
    l.why_it_matters,
    l.what_to_do,
    l.the_arithmetic,
    l.record_count,
    l.pounds,
    l.dollars,
    l.first_seen::date AS first_seen_on,
    l.observed_at::date AS last_seen_on,
    l.times_seen,
    d.decision,
    d.reason AS decision_reason,
    d.decided_by,
    d.decided_at,
    d.review_on,
        CASE
            WHEN d.decision IS NULL THEN 'A DECISION IS REQUIRED'::text
            WHEN d.decision = 'fix'::text THEN (('Being fixed — '::text || COALESCE(d.decided_by, 'someone'::text)) || ', '::text) || d.decided_at::date
            WHEN d.decision = 'leave'::text THEN (('Left as is — '::text || COALESCE(d.decided_by, 'someone'::text)) || ', '::text) || d.decided_at::date
            WHEN d.decision = 'ignore'::text THEN ((('Ignored — '::text || COALESCE(d.decided_by, 'someone'::text)) || ', '::text) || d.decided_at::date) || '. Ignoring is a decision, not a deletion, so it still appears here.'::text
            WHEN d.decision = 'reset'::text THEN 'Reset — awaiting a fresh decision'::text
            ELSE d.decision
        END AS decision_state,
    d.decision IS NULL AS needs_a_decision,
    l.drill,
    l.evidence,
    l.search_text
   FROM latest l
     LEFT JOIN LATERAL ( SELECT x.id,
            x.issue_key,
            x.issue_title,
            x.decision,
            x.reason,
            x.decided_by,
            x.decided_at,
            x.outstanding_when_decided,
            x.detail_when_decided,
            x.review_on,
            x.superseded
           FROM issue_decisions x
          WHERE NOT COALESCE(x.superseded, false) AND (x.issue_key = l.fingerprint OR l.fingerprint ~~ (x.issue_key || '%'::text))
          ORDER BY x.decided_at DESC
         LIMIT 1) d ON true;
create or replace view public.v_open_questions as
 SELECT area,
    question,
    why_it_matters,
    what_is_blocked,
    exposure_lb,
    exposure_dollars,
    days_open,
    first_raised,
    urgency,
    question_key,
    first_raised AS first_raised_date
   FROM ( SELECT open_questions.area,
            open_questions.question,
            open_questions.why_it_matters,
            open_questions.what_is_blocked,
            open_questions.exposure_lb,
            round(open_questions.exposure_lb * (( SELECT conversion_factors.value
                   FROM conversion_factors
                  WHERE conversion_factors.key = 'target_cost_per_lb'::text))) AS exposure_dollars,
            CURRENT_DATE - open_questions.first_seen::date AS days_open,
            open_questions.first_seen::date AS first_raised,
                CASE
                    WHEN (CURRENT_DATE - open_questions.first_seen::date) > 30 THEN 'OPEN OVER A MONTH'::text
                    WHEN COALESCE(open_questions.exposure_lb, 0::numeric) > 100::numeric THEN 'HIGH EXPOSURE'::text
                    ELSE 'Open'::text
                END AS urgency,
            open_questions.question_key
           FROM open_questions
          WHERE open_questions.status = 'open'::text
          ORDER BY (COALESCE(open_questions.exposure_lb, 0::numeric)) DESC, open_questions.first_seen) q;
create or replace view public.v_ot_watch as
 WITH pol AS (
         SELECT attendance_policy.ot_weekly_threshold,
            attendance_policy.approaching_ot_within
           FROM attendance_policy
         LIMIT 1
        ), wk AS (
         SELECT t.employee_id,
            date_trunc('week'::text, t.work_date::timestamp with time zone)::date AS week_start,
            sum(EXTRACT(epoch FROM t.clock_out - t.clock_in) / 3600.0 - COALESCE(t.unpaid_lunch_min, 0)::numeric / 60.0) AS worked_hours
           FROM time_entries t
          WHERE t.clock_in IS NOT NULL AND t.clock_out IS NOT NULL
          GROUP BY t.employee_id, (date_trunc('week'::text, t.work_date::timestamp with time zone)::date)
        )
 SELECT e.id AS employee_id,
    e.employee_code,
    e.full_name,
    d.name AS department,
    wk.week_start,
    round(wk.worked_hours, 2) AS worked_hours,
    COALESCE(e.weekly_target_hours, pol.ot_weekly_threshold)::numeric AS target_hours,
        CASE
            WHEN e.hours_basis = 'shift'::text THEN round(GREATEST(wk.worked_hours - pol.ot_weekly_threshold, 0::numeric), 2)
            ELSE 0::numeric
        END AS ot_hours,
        CASE
            WHEN e.hours_basis = 'shift'::text THEN round(GREATEST(wk.worked_hours - pol.ot_weekly_threshold, 0::numeric) * r.rate * COALESCE(r.ot_multiplier, 1.5) * (1::numeric + COALESCE(r.burden_pct, 0::numeric)), 2)
            ELSE 0::numeric
        END AS ot_cost_loaded,
        CASE
            WHEN e.hours_basis <> 'shift'::text THEN 'salaried'::text
            WHEN wk.worked_hours > pol.ot_weekly_threshold THEN 'over'::text
            WHEN wk.worked_hours >= (pol.ot_weekly_threshold - pol.approaching_ot_within) THEN 'approaching'::text
            ELSE 'clear'::text
        END AS ot_flag,
    e.hours_basis,
    pol.ot_weekly_threshold::numeric AS ot_threshold
   FROM wk
     CROSS JOIN pol
     JOIN employees e ON e.id = wk.employee_id
     LEFT JOIN departments d ON d.id = e.primary_department_id
     LEFT JOIN LATERAL ( SELECT r2.id,
            r2.employee_id,
            r2.basis,
            r2.rate,
            r2.ot_multiplier,
            r2.burden_pct,
            r2.effective_from,
            r2.effective_to,
            r2.approved_by,
            r2.note,
            r2.effective_from_date
           FROM employee_rates r2
          WHERE r2.employee_id = e.id AND r2.effective_from <= wk.week_start AND (r2.effective_to IS NULL OR r2.effective_to >= wk.week_start)
          ORDER BY r2.effective_from DESC
         LIMIT 1) r ON true;
create or replace view public.v_override_divergence as
 SELECT target_table,
    row_key,
    field_name,
    new_value AS what_we_corrected_it_to,
    old_value AS what_it_was,
    reason,
    set_by_name,
    set_at::date AS corrected_on,
    CURRENT_DATE - set_at::date AS days_standing,
        CASE
            WHEN metrc_sourced THEN 'Corrected in Metrc as well - the record agrees'::text
            ELSE 'CORRECTED HERE ONLY. Metrc is the legal record and still says something else. '::text || 'Until it is fixed in Metrc, an inspector reading Metrc sees the old value.'::text
        END AS standing,
    metrc_sourced AS fixed_in_metrc_too
   FROM tg_overrides o
  WHERE active
  ORDER BY metrc_sourced, set_at;
create or replace view public.v_overrides_active as
 SELECT o.id,
    o.target_table,
    o.row_key,
    o.field_name,
    o.old_value AS metrc_says,
    o.new_value AS we_say,
    o.reason,
    COALESCE(o.set_by_name, '—'::text) AS set_by,
    o.set_at::date AS set_on,
    o.metrc_sourced,
        CASE
            WHEN o.metrc_task_id IS NULL THEN 'not a Metrc field'::text
            WHEN mc.fixed_in_metrc THEN 'fixed in Metrc'::text
            ELSE 'AWAITING FIX IN METRC'::text
        END AS metrc_status
   FROM tg_overrides o
     LEFT JOIN metrc_corrections mc ON mc.id = o.metrc_task_id
  WHERE o.active
  ORDER BY o.set_at DESC;
create or replace view public.v_ownership_evidence as
 WITH pkg AS (
         SELECT p.tag,
            p.item_name,
            p.license,
            p.lab_testing_state,
            f_to_pounds(p.quantity, p.uom) AS lb,
            p.quantity,
            f_is_ours(p.raw ->> 'ItemFromFacilityLicenseNumber'::text) AS a_platform_ours,
            p.raw ->> 'ItemFromFacilityLicenseNumber'::text AS a_licence,
            f_package_is_ours(p.tag) AS b_lineage,
            f_material_origin(p.tag) AS b_detail
           FROM metrc_packages p
        ), withcoa AS (
         SELECT pkg.tag,
            pkg.item_name,
            pkg.license,
            pkg.lab_testing_state,
            pkg.lb,
            pkg.quantity,
            pkg.a_platform_ours,
            pkg.a_licence,
            pkg.b_lineage,
            pkg.b_detail,
            c.client_license,
            c.client_name,
            c.report_date,
                CASE
                    WHEN c.client_license IS NULL OR btrim(c.client_license) = ''::text THEN NULL::boolean
                    ELSE (EXISTS ( SELECT 1
                       FROM unnest(string_to_array(c.client_license, ','::text)) lic(lic)
                      WHERE f_is_ours(btrim(lic.lic))))
                END AS c_ours,
            ( SELECT count(*) AS count
                   FROM unnest(string_to_array(COALESCE(c.client_license, ''::text), ','::text)) l(l)
                  WHERE btrim(l.l) <> ''::text) AS c_licence_count
           FROM pkg
             LEFT JOIN LATERAL ( SELECT ce.client_license,
                    ce.client_name,
                    ce.report_date
                   FROM coa_extract ce
                  WHERE ce.package_tag = pkg.tag
                  ORDER BY ce.report_date DESC NULLS LAST
                 LIMIT 1) c ON true
        )
 SELECT tag,
    item_name,
    license,
    lab_testing_state,
    round(lb, 2) AS pounds,
    quantity,
    a_platform_ours AS platform_says_ours,
    a_licence AS platform_read_this_licence,
    b_lineage AS lineage_says,
    b_detail -> 'origin_names'::text AS lineage_origin,
    b_detail -> 'inbound_manifests'::text AS lineage_inbound_manifest,
    c_ours AS certificate_says_ours,
    client_name AS certificate_client,
    client_license AS certificate_licence,
    report_date AS certificate_dated,
        CASE
            WHEN c_ours IS NULL THEN 'NO CERTIFICATE EVIDENCE'::text
            WHEN a_platform_ours = c_ours AND (b_lineage = 'ours'::text) = c_ours THEN 'ALL THREE AGREE'::text
            WHEN (b_lineage = 'ours'::text) = c_ours AND a_platform_ours <> c_ours THEN 'PLATFORM IS THE ODD ONE OUT — lineage and the certificate agree against it'::text
            WHEN a_platform_ours = c_ours AND (b_lineage = 'ours'::text) <> c_ours THEN 'LINEAGE IS THE ODD ONE OUT'::text
            WHEN b_lineage = 'blended'::text THEN 'BLENDED — several origins, no recorded proportions, no single answer exists'::text
            ELSE 'CERTIFICATE DISAGREES WITH BOTH INTERNAL SOURCES'::text
        END AS agreement,
        CASE
            WHEN c_ours IS FALSE AND b_lineage = 'ours'::text THEN ('The certificate names another licensee, but the lineage says we grew it. Most likely '::text || 'the sample was submitted by whoever held it at test time — NOT evidence we do not own '::text) || 'it. Confirm against the inbound manifest before treating this as third party.'::text
            WHEN c_ours IS FALSE AND b_lineage = 'third_party'::text AND a_platform_ours THEN 'Two independent sources say this is not ours and the platform counts it as our '::text || 'production. This is the one to act on.'::text
            WHEN c_ours IS NULL AND (lab_testing_state = ANY (ARRAY['TestPassed'::text, 'TestFailed'::text])) THEN 'It was tested, so a certificate exists in Metrc — it has not been fetched. '::text || 'Until it is, ownership rests on internal fields only, which rule C0 forbids as proof.'::text
            WHEN c_ours AND client_name IS NOT NULL AND client_name !~~* '%twisted%'::text THEN 'The certificate licence is ours but the client NAME is another company. Worth reading '::text || 'the document before relying on it.'::text
            ELSE NULL::text
        END AS how_to_read_it,
    c_licence_count AS licences_named_on_certificate,
        CASE
            WHEN c_licence_count > 1 THEN (('This certificate names '::text || c_licence_count) || ' licences in one field. Any one of '::text) || 'them being ours makes it ours — 621 certificates print both of our licences together.'::text
            ELSE NULL::text
        END AS certificate_parse_note
   FROM withcoa;
create or replace view public.v_ownership_misattribution as
 WITH x AS (
         SELECT p.tag,
            p.item_name,
            p.location,
            p.license,
            p.lab_testing_state,
            f_to_pounds(p.quantity, p.uom) AS lb,
            f_material_origin(p.tag) AS g,
            f_is_ours(p.raw ->> 'ItemFromFacilityLicenseNumber'::text) AS platform_says_ours
           FROM metrc_packages p
          WHERE p.quantity > 0::numeric
        )
 SELECT x.tag,
    x.item_name,
    COALESCE(x.location, '(no location recorded)'::text) AS location,
    x.license,
    x.lab_testing_state,
    round(x.lb, 2) AS pounds,
    x.platform_says_ours,
    (x.g ->> 'all_ours'::text)::boolean AS lineage_says_ours,
    x.g -> 'origin_names'::text AS origins,
    x.g -> 'inbound_manifests'::text AS arrived_on,
    (x.g ->> 'lineage_packages'::text)::integer AS steps_back,
    jsonb_array_length(COALESCE(x.g -> 'origin_licences'::text, '[]'::jsonb)) AS distinct_origins,
        CASE
            WHEN ((x.g ->> 'any_outside'::text)::boolean) AND x.platform_says_ours AND jsonb_array_length(COALESCE(x.g -> 'origin_licences'::text, '[]'::jsonb)) <= 1 THEN 'WRONGLY OURS — wholly theirs'::text
            WHEN ((x.g ->> 'any_outside'::text)::boolean) AND x.platform_says_ours THEN 'WRONGLY OURS — blended, proportion unknown'::text
            WHEN ((x.g ->> 'all_ours'::text)::boolean) AND NOT x.platform_says_ours THEN 'WRONGLY THEIRS — lineage says we grew it'::text
            ELSE 'agrees'::text
        END AS verdict,
        CASE
            WHEN ((x.g ->> 'any_outside'::text)::boolean) AND x.platform_says_ours AND jsonb_array_length(COALESCE(x.g -> 'origin_licences'::text, '[]'::jsonb)) > 1 THEN (('Made from '::text || jsonb_array_length(x.g -> 'origin_licences'::text)) || ' different origins. Nothing records how much came from each, so this cannot be '::text) || 'split between our production and theirs. Do not count the whole weight either way.'::text
            WHEN ((x.g ->> 'any_outside'::text)::boolean) AND x.platform_says_ours THEN 'Single outside origin — this weight is theirs, not our production.'::text
            WHEN ((x.g ->> 'all_ours'::text)::boolean) AND NOT x.platform_says_ours THEN 'We grew it, but the item definition came from another licence, so it reads as bought in.'::text
            ELSE NULL::text
        END AS what_is_wrong,
    d_coa.storage_path AS certificate_link,
        CASE
            WHEN d_coa.storage_path IS NOT NULL THEN 'on file'::text
            WHEN x.lab_testing_state = 'TestPassed'::text THEN 'passed — certificate not yet fetched from Metrc'::text
            WHEN x.lab_testing_state = 'TestFailed'::text THEN 'FAILED testing'::text
            WHEN x.lab_testing_state = 'NotSubmitted'::text THEN 'never submitted for testing'::text
            WHEN x.lab_testing_state IS NULL THEN 'no test state recorded in Metrc'::text
            ELSE x.lab_testing_state
        END AS certificate_says,
    d_man.storage_path AS manifest_link,
        CASE
            WHEN d_man.storage_path IS NOT NULL THEN 'on file'::text
            WHEN ((x.g -> 'inbound_manifests'::text) ->> 0) IS NOT NULL THEN ('inbound manifest '::text || ((x.g -> 'inbound_manifests'::text) ->> 0)) || ' — document not yet fetched'::text
            ELSE 'no manifest — packaged here, never transferred in'::text
        END AS manifest_says
   FROM x
     LEFT JOIN metrc_documents d_coa ON d_coa.package_tag = x.tag AND d_coa.doc_type ~~* '%coa%'::text
     LEFT JOIN metrc_documents d_man ON d_man.manifest_number = ((x.g -> 'inbound_manifests'::text) ->> 0) AND d_man.doc_type ~~* '%manifest%'::text;
create or replace view public.v_ownership_vs_certificate as
 WITH cert AS (
         SELECT e.package_tag,
            max(e.client_license) AS cert_license,
            max(e.client_name) AS cert_client,
            max(e.lab_report_id) AS cert_report,
            count(*) AS certificates
           FROM coa_extract e
          WHERE e.package_tag IS NOT NULL
          GROUP BY e.package_tag
        ), pkg AS (
         SELECT DISTINCT ON (p.tag) p.tag,
            p.item_name,
            p.license,
            p.uom,
            p.quantity,
            p.source_state,
            p.lab_testing_state,
            p.raw ->> 'ItemFromFacilityLicenseNumber'::text AS platform_license,
            p.raw ->> 'ItemFromFacilityName'::text AS platform_name,
            p.raw ->> 'SourcePackageCount'::text AS source_packages,
            p.raw ->> 'ReceivedFromManifestNumber'::text AS inbound_manifest
           FROM metrc_packages p
          ORDER BY p.tag, p.license
        )
 SELECT k.tag AS package_tag,
    "left"(k.item_name, 55) AS item_name,
    k.source_state,
    k.lab_testing_state,
        CASE
            WHEN f_is_weight(k.uom) THEN round(f_to_pounds(k.quantity, k.uom), 2)
            ELSE NULL::numeric
        END AS pounds,
    k.platform_license,
    k.platform_name,
    c.cert_license,
    c.cert_client,
    c.cert_report,
    c.certificates,
    k.source_packages,
    k.inbound_manifest,
        CASE
            WHEN c.package_tag IS NULL THEN 'NO CERTIFICATE'::text
            WHEN c.cert_license IS NULL THEN 'UNPROVEN - certificate carries no client licence'::text
            WHEN POSITION((k.platform_license) IN (c.cert_license)) > 0 THEN 'AGREES'::text
            ELSE 'CONFLICT'::text
        END AS verdict,
        CASE
            WHEN c.cert_license IS NOT NULL AND POSITION((k.platform_license) IN (c.cert_license)) = 0 THEN (((((('THE ISSUE: the platform calls this '::text || k.platform_license) || ' but the laboratory certificate names '::text) || COALESCE(c.cert_client, '?'::text)) || ' ('::text) || c.cert_license) || ') as the client. The certificate is the '::text) || 'independent source and it wins.'::text
            ELSE NULL::text
        END AS what_is_wrong
   FROM pkg k
     LEFT JOIN cert c ON c.package_tag = k.tag;
create or replace view public.v_package_documents as
 SELECT p.license,
    p.tag AS package_tag,
    p.item_name,
    p.lab_testing_state,
    cd.storage_path AS coa_storage_path,
    cd.metrc_id AS coa_document_id,
    cd.byte_size AS coa_bytes,
    lr.lab_facility,
    lr.result_date AS coa_result_date,
        CASE
            WHEN cd.storage_path IS NOT NULL THEN 'Available'::text
            WHEN cd.fetch_error IS NOT NULL THEN 'Could not be retrieved: '::text || cd.fetch_error
            WHEN lr.document_file_id IS NOT NULL THEN 'Certificate exists in Metrc but has not been downloaded yet'::text
            WHEN lr.package_tag IS NOT NULL THEN 'Tested, but this laboratory returned no certificate document'::text
            WHEN p.lab_testing_state = 'NotSubmitted'::text THEN 'No certificate because this package has never been submitted for testing'::text
            WHEN p.lab_testing_state = ANY (ARRAY['SubmittedForTesting'::text, 'TestingInProgress'::text]) THEN 'No certificate yet - currently at the laboratory'::text
            ELSE 'No certificate because no laboratory result has been recorded against this package'::text
        END AS coa_status,
    t.manifest_number,
    t.direction AS manifest_direction,
    t.shipper,
    t.recipient,
    md.storage_path AS manifest_storage_path,
    md.byte_size AS manifest_bytes,
        CASE
            WHEN md.storage_path IS NOT NULL THEN 'Available'::text
            WHEN md.fetch_error IS NOT NULL THEN 'Could not be retrieved: '::text || md.fetch_error
            WHEN t.manifest_number IS NOT NULL THEN 'Manifest exists in Metrc but the document has not been downloaded yet'::text
            ELSE 'No manifest because this package has never moved between licences'::text
        END AS manifest_status
   FROM metrc_packages p
     LEFT JOIN LATERAL ( SELECT r.id,
            r.license,
            r.package_tag,
            r.test_type,
            r.result,
            r.passed,
            r.result_date,
            r.raw,
            r.synced_at,
            r.package_id,
            r.test_name,
            r.units,
            r.notes,
            r.lab_facility,
            r.document_file_id,
            r.coa_link
           FROM metrc_lab_results r
          WHERE r.package_tag = p.tag AND r.document_file_id IS NOT NULL
          ORDER BY r.result_date DESC NULLS LAST
         LIMIT 1) lr ON true
     LEFT JOIN metrc_documents cd ON cd.doc_type = 'coa'::text AND cd.metrc_id = lr.document_file_id
     LEFT JOIN LATERAL ( SELECT tr.id,
            tr.license,
            tr.manifest_number,
            tr.direction,
            tr.shipper,
            tr.recipient,
            tr.created_on,
            tr.raw,
            tr.synced_at
           FROM metrc_transfers tr
          WHERE tr.raw::text ~~ (('%'::text || p.tag) || '%'::text)
          ORDER BY tr.created_on DESC NULLS LAST
         LIMIT 1) t ON true
     LEFT JOIN metrc_documents md ON md.doc_type = 'manifest'::text AND md.manifest_number = t.manifest_number;
create or replace view public.v_package_forensic as
 SELECT package_tag,
    metrc_package_id,
    metrc_label,
    item_name,
    item_id,
    strain,
    strain_id,
    category,
    source_harvest,
    source_packages,
    production_batch,
    harvest_cut_on,
    harvest_closed_on,
    dried_in_room,
    plants_in_harvest,
    harvest_wet_grams,
    harvest_waste_grams,
    harvest_packaged_grams,
    grown_in_rooms,
    quantity_now,
    quantity_created,
    quantity_received,
    quantity_originally,
    f_uom_label(unit_of_measure) AS unit_of_measure,
    package_created_on,
    received_on,
    submitted_for_testing_on,
    result_recorded_on,
    certificate_expires_on,
    finished_on,
    last_changed_on,
    days_since_created,
    located_in,
    held_under_licence,
    made_by,
    maker_licence,
    received_from,
    arrived_on_manifest,
    testing_state,
    on_hold,
    finished,
    on_recall,
    requires_remediation,
    contains_remediated,
    the_full_story
   FROM ( SELECT p.tag AS package_tag,
            p.raw ->> 'Id'::text AS metrc_package_id,
            p.raw ->> 'Label'::text AS metrc_label,
            p.item_name,
            p.raw #>> '{Item,Id}'::text[] AS item_id,
            p.raw #>> '{Item,StrainName}'::text[] AS strain,
            p.raw #>> '{Item,StrainId}'::text[] AS strain_id,
            p.raw #>> '{Item,ProductCategoryName}'::text[] AS category,
            NULLIF(p.raw ->> 'SourceHarvestNames'::text, ''::text) AS source_harvest,
            NULLIF(p.raw ->> 'SourcePackageLabels'::text, ''::text) AS source_packages,
            NULLIF(p.raw ->> 'SourceProductionBatchNumbers'::text, ''::text) AS production_batch,
            h.harvest_start AS harvest_cut_on,
            (h.raw ->> 'FinishedDate'::text)::date AS harvest_closed_on,
            COALESCE(NULLIF(h.raw ->> 'DryingLocationName'::text, ''::text), 'not recorded'::text) AS dried_in_room,
            (h.raw ->> 'PlantCount'::text)::integer AS plants_in_harvest,
            round(h.wet_weight) AS harvest_wet_grams,
            round(h.waste_weight) AS harvest_waste_grams,
            round((h.raw ->> 'TotalPackagedWeight'::text)::numeric) AS harvest_packaged_grams,
            ( SELECT string_agg(DISTINCT pl.raw ->> 'LocationName'::text, ', '::text) AS string_agg
                   FROM metrc_plants pl
                  WHERE (pl.raw ->> 'HarvestedByUserName'::text) IS NOT NULL AND (pl.raw ->> 'PlantBatchName'::text) IS NOT NULL AND COALESCE(pl.raw ->> 'HarvestId'::text, ''::text) = COALESCE(h.raw ->> 'Id'::text, ''::text)) AS grown_in_rooms,
            round(p.quantity) AS quantity_now,
            round((p.raw ->> 'CreatedQuantity'::text)::numeric) AS quantity_created,
            round((p.raw ->> 'ReceivedQuantity'::text)::numeric) AS quantity_received,
            round((p.raw ->> 'OriginalPackageQuantity'::text)::numeric) AS quantity_originally,
                CASE p.uom
                    WHEN 'g'::text THEN 'grams'::text
                    WHEN 'kg'::text THEN 'kilograms'::text
                    WHEN 'ea'::text THEN 'each'::text
                    WHEN 'oz'::text THEN 'ounces'::text
                    WHEN 'lb'::text THEN 'pounds'::text
                    ELSE COALESCE(p.uom, 'not recorded'::text)
                END AS unit_of_measure,
            p.packaged_on AS package_created_on,
            (p.raw ->> 'ReceivedDateTime'::text)::date AS received_on,
            (p.raw ->> 'LabTestingStateDate'::text)::date AS submitted_for_testing_on,
            (p.raw ->> 'LabTestingRecordedDate'::text)::date AS result_recorded_on,
            (p.raw ->> 'LabTestResultExpirationDateTime'::text)::date AS certificate_expires_on,
            (p.raw ->> 'FinishedDate'::text)::date AS finished_on,
            (p.raw ->> 'LastModified'::text)::date AS last_changed_on,
            CURRENT_DATE - p.packaged_on AS days_since_created,
            p.location AS located_in,
            p.license AS held_under_licence,
            COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityName'::text, ''::text), 'not recorded'::text) AS made_by,
            p.raw ->> 'ItemFromFacilityLicenseNumber'::text AS maker_licence,
            COALESCE(NULLIF(p.raw ->> 'ReceivedFromFacilityName'::text, ''::text), 'not applicable'::text) AS received_from,
            NULLIF(p.raw ->> 'ReceivedFromManifestNumber'::text, ''::text) AS arrived_on_manifest,
            p.raw ->> 'LabTestingState'::text AS testing_state,
            (p.raw ->> 'IsOnHold'::text)::boolean AS on_hold,
            (p.raw ->> 'IsFinished'::text)::boolean AS finished,
            (p.raw ->> 'IsOnRecall'::text)::boolean AS on_recall,
            (p.raw ->> 'ProductRequiresRemediation'::text)::boolean AS requires_remediation,
            (p.raw ->> 'ContainsRemediatedProduct'::text)::boolean AS contains_remediated,
            ((((((((((((((('Package '::text || p.tag) || COALESCE(' came from harvest '::text || NULLIF(p.raw ->> 'SourceHarvestNames'::text, ''::text), ''::text)) || COALESCE(' cut '::text || h.harvest_start::text, ''::text)) || COALESCE(' dried in '::text || NULLIF(h.raw ->> 'DryingLocationName'::text, ''::text), ''::text)) || ', created '::text) || p.packaged_on::text) || COALESCE(', arrived on manifest '::text || NULLIF(p.raw ->> 'ReceivedFromManifestNumber'::text, ''::text), ''::text)) || ', now '::text) || round(p.quantity)) || ' '::text) || COALESCE(p.uom, ''::text)) || ' in '::text) || COALESCE(p.location, 'an unrecorded location'::text)) || ', testing state '::text) || COALESCE(p.raw ->> 'LabTestingState'::text, 'unknown'::text)) || COALESCE(', last changed '::text || (((p.raw ->> 'LastModified'::text)::date)::text), ''::text) AS the_full_story
           FROM metrc_packages p
             LEFT JOIN metrc_harvests h ON h.name = split_part(COALESCE(p.raw ->> 'SourceHarvestNames'::text, ''::text), ','::text, 1)) q;
create or replace view public.v_package_manifest as
 SELECT p.raw ->> 'Label'::text AS package_tag,
    NULLIF(p.raw ->> 'ReceivedFromManifestNumber'::text, ''::text) AS manifest_number,
    t.raw ->> 'ShipmentTypeName'::text AS shipment_type,
    t.raw ->> 'Name'::text AS shipper_name,
    t.raw ->> 'RecipientFacilityName'::text AS recipient_name,
    t.raw ->> 'RecipientFacilityLicenseNumber'::text AS recipient_license,
    ((t.raw ->> 'ActualDepartureDateTime'::text)::timestamp with time zone)::date AS departed_on,
    ((t.raw ->> 'ReceivedDateTime'::text)::timestamp with time zone)::date AS received_on,
    ((t.raw ->> 'ActualArrivalDateTime'::text)::timestamp with time zone)::date AS arrived_on,
    t.raw ->> 'DriverName'::text AS driver,
    t.raw ->> 'DriverVehicleLicenseNumber'::text AS vehicle,
    t.raw ->> 'InvoiceNumber'::text AS invoice_number,
    (t.raw ->> 'IsVoided'::text)::boolean AS voided,
        CASE
            WHEN NULLIF(p.raw ->> 'ReceivedFromManifestNumber'::text, ''::text) IS NULL THEN ('No inbound manifest. Why: this package was created here from our own harvest or from another '::text || 'of our packages, so it never travelled between licences. Manifests only exist for material '::text) || 'that moved between companies.'::text
            WHEN t.raw IS NULL THEN ((('Manifest '::text || (p.raw ->> 'ReceivedFromManifestNumber'::text)) || ' is named on the package but the '::text) || 'transfer itself has not been mirrored from Metrc yet, so the shipper, dates and driver '::text) || 'cannot be shown. Run the Metrc transfer sync.'::text
            ELSE (((((('Arrived on manifest '::text || (p.raw ->> 'ReceivedFromManifestNumber'::text)) || ' from '::text) || COALESCE(t.raw ->> 'Name'::text, 'an unnamed shipper'::text)) || COALESCE(', departed '::text || ((t.raw ->> 'ActualDepartureDateTime'::text)::timestamp with time zone)::date::text, ''::text)) || COALESCE(', received '::text || ((t.raw ->> 'ReceivedDateTime'::text)::timestamp with time zone)::date::text, ''::text)) || COALESCE(', driver '::text || (t.raw ->> 'DriverName'::text), ''::text)) || '.'::text
        END AS manifest_story
   FROM metrc_packages p
     LEFT JOIN metrc_transfers t ON (t.raw ->> 'ManifestNumber'::text) = NULLIF(p.raw ->> 'ReceivedFromManifestNumber'::text, ''::text);
create or replace view public.v_page_design_queue as
 SELECT module,
    category,
    subcategory,
    label,
    table_ref,
    page_kind,
    archetype,
        CASE
            WHEN archetype IS NULL THEN 'NEEDS A DESIGN DECISION'::text
            ELSE 'assigned'::text
        END AS state
   FROM nav_registry n
  WHERE enabled
  ORDER BY (archetype IS NOT NULL), module, subcategory NULLS FIRST, label;
create or replace view public.v_page_drilldown_coverage as
 WITH surfaces AS (
         SELECT n.view_key,
            n.label,
            n.category,
            n.subcategory,
            n.surface,
            n.table_ref,
            n.admin_only
           FROM nav_registry n
          WHERE n.enabled AND n.table_ref IS NOT NULL
        ), cols AS (
         SELECT s.view_key,
            s.label,
            s.category,
            s.subcategory,
            s.surface,
            s.table_ref,
            s.admin_only,
            array_agg(lower(a.attname::text) ORDER BY a.attnum) AS columns
           FROM surfaces s
             JOIN pg_class c ON c.relname = s.table_ref AND (c.relkind = ANY (ARRAY['r'::"char", 'v'::"char", 'm'::"char", 'f'::"char", 'p'::"char"]))
             JOIN pg_namespace ns ON ns.oid = c.relnamespace AND ns.nspname = 'public'::name
             JOIN pg_attribute a ON a.attrelid = c.oid AND a.attnum > 0 AND NOT a.attisdropped
          GROUP BY s.view_key, s.label, s.category, s.subcategory, s.surface, s.table_ref, s.admin_only
        )
 SELECT view_key,
    label,
    category,
    subcategory,
    table_ref,
    admin_only,
    columns && ARRAY['package_tag'::text, 'tag'::text, 'package'::text, 'package_label'::text] AS reaches_package,
    columns && ARRAY['manifest_number'::text, 'manifest'::text, 'inbound_manifest'::text] AS reaches_manifest,
    columns && ARRAY['harvest'::text, 'harvest_name'::text, 'harvest_batch'::text, 'source_harvest'::text] AS reaches_harvest,
    columns && ARRAY['licence'::text, 'license'::text] AS carries_licence,
    columns && ARRAY['search_text'::text] AS has_search_text,
        CASE
            WHEN columns && ARRAY['package_tag'::text, 'tag'::text, 'package'::text, 'package_label'::text] THEN 'Package - full documents'::text
            WHEN columns && ARRAY['manifest_number'::text, 'manifest'::text, 'inbound_manifest'::text] THEN 'Manifest only'::text
            WHEN columns && ARRAY['harvest'::text, 'harvest_name'::text, 'harvest_batch'::text, 'source_harvest'::text] THEN 'Harvest - documents via its packages'::text
            ELSE 'No document key'::text
        END AS document_reach
   FROM cols;
create or replace view public.v_page_filter_coverage as
 WITH cols AS (
         SELECT c_1.oid,
            a.attname,
            format_type(a.atttypid, a.atttypmod) AS typ
           FROM pg_class c_1
             JOIN pg_attribute a ON a.attrelid = c_1.oid
          WHERE a.attnum > 0 AND NOT a.attisdropped
        )
 SELECT n.category,
    n.subcategory,
    n.label,
    n.surface,
    n.view_key,
    n.table_ref,
        CASE c.relkind
            WHEN 'r'::"char" THEN 'table'::text
            WHEN 'm'::"char" THEN 'materialized view'::text
            ELSE 'view'::text
        END AS source_kind,
    (EXISTS ( SELECT 1
           FROM cols x
          WHERE x.oid = c.oid AND x.typ ~~ 'text%'::text AND x.attname <> 'raw'::name)) AS has_search,
    (EXISTS ( SELECT 1
           FROM cols x
          WHERE x.oid = c.oid AND x.attname ~ '(_date|_on$|_on_|_at$|^date|^month|period)'::text)) AS has_date_filter,
    (EXISTS ( SELECT 1
           FROM cols x
          WHERE x.oid = c.oid AND (x.typ ~~ 'date%'::text OR x.typ ~~ 'timestamp%'::text))) AS has_a_date_column,
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM cols x
              WHERE x.oid = c.oid AND x.attname ~ '(_date|_on$|_on_|_at$|^date|^month|period)'::text)) THEN 'Date filter available'::text
            WHEN (EXISTS ( SELECT 1
               FROM cols x
              WHERE x.oid = c.oid AND (x.typ ~~ 'date%'::text OR x.typ ~~ 'timestamp%'::text))) THEN 'FIXABLE: holds a date column but not named so the filter can find it. Append an alias ending _date.'::text
            ELSE 'No date filter: this page holds no date at all. For configuration, reference and rate '::text || 'tables that is correct. For anything else a meaningful date needs choosing.'::text
        END AS date_filter_status
   FROM nav_registry n
     JOIN pg_class c ON c.oid = to_regclass('public.'::text || n.table_ref)::oid
  WHERE n.enabled AND n.table_ref IS NOT NULL AND n.table_ref <> ''::text;
create or replace view public.v_page_wiring as
 WITH pages AS (
         SELECT n.view_key,
            n.label,
            n.category,
            n.subcategory,
            n.report_group,
            n.table_ref,
            n.page_kind,
            c_1.oid AS obj_oid,
                CASE c_1.relkind
                    WHEN 'r'::"char" THEN 'table'::text
                    WHEN 'v'::"char" THEN 'view'::text
                    WHEN 'm'::"char" THEN 'materialized view'::text
                    WHEN 'p'::"char" THEN 'partitioned table'::text
                    ELSE NULL::text
                END AS object_kind
           FROM nav_registry n
             LEFT JOIN pg_class c_1 ON c_1.relname = n.table_ref AND c_1.relnamespace = 'public'::regnamespace::oid AND (c_1.relkind = ANY (ARRAY['r'::"char", 'v'::"char", 'm'::"char", 'p'::"char"]))
          WHERE n.enabled
        ), cols AS (
         SELECT p_1.view_key,
            count(*) FILTER (WHERE a.attnum > 0 AND NOT a.attisdropped) AS fields,
            count(*) FILTER (WHERE a.attnum > 0 AND NOT a.attisdropped AND (t.typname = ANY (ARRAY['date'::name, 'timestamp'::name, 'timestamptz'::name]))) AS date_columns
           FROM pages p_1
             LEFT JOIN pg_attribute a ON a.attrelid = p_1.obj_oid
             LEFT JOIN pg_type t ON t.oid = a.atttypid
          GROUP BY p_1.view_key
        )
 SELECT p.view_key,
    p.label,
    p.category,
    p.subcategory,
    p.report_group,
    p.table_ref,
    p.object_kind,
    COALESCE(c.fields, 0::bigint) AS fields,
    ( SELECT count(*) AS count
           FROM nav_role_visibility v
          WHERE v.view_key = p.view_key AND v.visible) AS roles_who_can_see,
    (EXISTS ( SELECT 1
           FROM report_registry r
          WHERE r.fact_view = p.table_ref)) AS in_report_registry,
    COALESCE(c.date_columns, 0::bigint) AS date_columns,
    ( SELECT count(*) AS count
           FROM brain_claims b
          WHERE b.covers_object = p.table_ref) AS claims_proving_it,
        CASE
            WHEN (( SELECT count(*) AS count
               FROM nav_role_visibility v
              WHERE v.view_key = p.view_key AND v.visible)) = 0 THEN 'INVISIBLE - no role can open this page'::text
            WHEN p.page_kind = 'application'::text THEN 'WIRED - application screen, no table_ref by design'::text
            WHEN p.table_ref IS NULL THEN 'NO TARGET - a report page must name a table or view'::text
            WHEN p.object_kind IS NULL THEN 'BROKEN - points at an object that does not exist'::text
            WHEN COALESCE(c.fields, 0::bigint) = 0 THEN 'BROKEN - target has no columns'::text
            ELSE 'WIRED'::text
        END AS wiring,
    'THE ISSUE: a page that points at nothing, has no columns, or that no role can open is a dead link that LOOKS like coverage.'::text AS what_is_wrong,
    'Fix the table_ref, grant visibility, or disable the page. Never leave a dead page enabled - in the menu it is indistinguishable from a working one.'::text AS what_to_do,
    COALESCE(c.date_columns, 0::bigint) = 0 AND p.page_kind = 'report'::text AS no_date_range_possible,
    p.page_kind
   FROM pages p
     LEFT JOIN cols c ON c.view_key = p.view_key;
create or replace view public.v_pay_rate_confidence as
 SELECT count(*) AS rates_on_file,
    count(*) FILTER (WHERE provisional) AS provisional,
    count(*) FILTER (WHERE NOT provisional) AS approved,
    round(100.0 * count(*) FILTER (WHERE provisional)::numeric / NULLIF(count(*), 0)::numeric, 1) AS pct_provisional,
    count(*) FILTER (WHERE provisional) = 0 AS safe_to_quote,
        CASE
            WHEN count(*) FILTER (WHERE provisional) = 0 THEN 'Every rate has been approved by a person. Payroll figures can be quoted.'::text
            ELSE ((('ESTIMATE ONLY. '::text || count(*) FILTER (WHERE provisional)) || ' of '::text) || count(*)) || ' rates are placeholders nobody has approved. Any payroll, labour cost or margin figure built on these is an estimate and must be presented as one. Human Resources replaces them during onboarding.'::text
        END AS how_to_present_it
   FROM employee_rates;
create or replace view public.v_payroll_forecast as
 SELECT e.employee_code,
    e.full_name,
    COALESCE(rc.name, '—'::text) AS "position",
    TRIM(BOTH ' +'::text FROM COALESCE(d.name, ''::text) ||
        CASE
            WHEN d2.name IS NOT NULL THEN ' + '::text || d2.name
            ELSE ''::text
        END) AS departments,
    r.basis,
    r.rate,
    COALESCE(e.weekly_target_hours, 40::numeric) AS planned_hours,
    round(b.base, 2) AS base_weekly_cost,
    round(b.base * (1::numeric + r.burden_pct), 2) AS loaded_weekly_cost,
    round(b.base * (1::numeric + r.burden_pct) * 52::numeric, 0) AS annualized_loaded_cost
   FROM employees e
     JOIN LATERAL ( SELECT r_1.id,
            r_1.employee_id,
            r_1.basis,
            r_1.rate,
            r_1.ot_multiplier,
            r_1.burden_pct,
            r_1.effective_from,
            r_1.effective_to,
            r_1.approved_by,
            r_1.note
           FROM employee_rates r_1
          WHERE r_1.employee_id = e.id AND r_1.effective_from <= CURRENT_DATE AND (r_1.effective_to IS NULL OR r_1.effective_to >= CURRENT_DATE)
          ORDER BY r_1.effective_from DESC
         LIMIT 1) r ON true
     CROSS JOIN LATERAL ( SELECT
                CASE
                    WHEN r.basis = 'weekly_salary'::pay_basis THEN r.rate
                    ELSE LEAST(COALESCE(e.weekly_target_hours, 40::numeric), 40::numeric) * r.rate + GREATEST(COALESCE(e.weekly_target_hours, 40::numeric) - 40::numeric, 0::numeric) * r.rate * r.ot_multiplier
                END AS base) b
     LEFT JOIN roles_catalog rc ON rc.id = e.primary_role_id
     LEFT JOIN departments d ON d.id = e.primary_department_id
     LEFT JOIN departments d2 ON d2.id = e.secondary_department_id
  WHERE e.terminated_on IS NULL;
create or replace view public.v_payroll_journal as
 SELECT r.id AS pay_run_id,
    r.run_no,
    p.pay_date,
    COALESCE(l.cost_class, d.cost_class, 'G_AND_A'::text) AS cost_class,
    cc.cogs,
    cc.irc_280e_deductible,
    COALESCE(d.name, 'Unassigned'::text) AS department,
        CASE
            WHEN l.earning_code IS NOT NULL THEN 'debit'::text
            ELSE 'credit'::text
        END AS side,
    COALESCE(l.earning_code, l.deduction_code) AS code,
    COALESCE(l.gl_account, m.gl_code, m.qbo_account_name) AS gl_account,
    sum(l.amount) AS amount
   FROM pay_run_lines l
     JOIN pay_runs r ON r.id = l.pay_run_id
     JOIN pay_periods p ON p.id = r.pay_period_id
     LEFT JOIN departments d ON d.id = l.department_id
     LEFT JOIN cost_classes cc ON cc.code = COALESCE(l.cost_class, d.cost_class, 'G_AND_A'::text)
     LEFT JOIN qbo_account_map m ON m.purpose =
        CASE COALESCE(l.cost_class, d.cost_class, 'G_AND_A'::text)
            WHEN 'DIRECT_PROD'::text THEN 'wages_direct_production'::text
            WHEN 'INDIRECT_PROD'::text THEN 'wages_indirect_production'::text
            WHEN 'SELLING'::text THEN 'wages_selling'::text
            ELSE 'wages_g_and_a'::text
        END
  WHERE r.status = ANY (ARRAY['approved'::text, 'paid'::text])
  GROUP BY r.id, r.run_no, p.pay_date, l.cost_class, d.cost_class, cc.cogs, cc.irc_280e_deductible, d.name, l.earning_code, l.deduction_code, l.gl_account, m.gl_code, m.qbo_account_name;
create or replace view public.v_payroll_week as
 SELECT e.id AS employee_id,
    e.full_name,
    date_trunc('week'::text, t.work_date::timestamp with time zone)::date AS week_start,
    sum(t.productive_hours) AS hours,
    r.basis,
    r.rate,
    r.ot_multiplier,
    r.burden_pct,
        CASE
            WHEN r.basis = 'weekly_salary'::pay_basis THEN r.rate
            ELSE LEAST(sum(t.productive_hours), 40::numeric) * r.rate + GREATEST(sum(t.productive_hours) - 40::numeric, 0::numeric) * r.rate * r.ot_multiplier
        END * (1::numeric + r.burden_pct) AS loaded_weekly_cost
   FROM time_entries t
     JOIN employees e ON e.id = t.employee_id
     JOIN employee_rates r ON r.employee_id = e.id AND t.work_date >= r.effective_from AND (r.effective_to IS NULL OR t.work_date <= r.effective_to)
  GROUP BY e.id, e.full_name, (date_trunc('week'::text, t.work_date::timestamp with time zone)), r.basis, r.rate, r.ot_multiplier, r.burden_pct;
create or replace view public.v_payroll_ytd as
 SELECT l.employee_id,
    e.employee_code,
    e.full_name,
    EXTRACT(year FROM p.pay_date)::integer AS tax_year,
    sum(l.amount) FILTER (WHERE l.earning_code IS NOT NULL) AS gross_ytd,
    sum(l.amount) FILTER (WHERE l.earning_code IS NOT NULL AND l.taxable) AS taxable_ytd,
    sum(l.amount) FILTER (WHERE l.deduction_code IS NOT NULL) AS deductions_ytd,
    sum(l.hours) FILTER (WHERE l.earning_code = 'REG'::text) AS regular_hours_ytd,
    sum(l.hours) FILTER (WHERE l.earning_code = 'OT'::text) AS ot_hours_ytd,
    sum(l.amount) FILTER (WHERE l.earning_code IS NOT NULL) - COALESCE(sum(l.amount) FILTER (WHERE l.deduction_code IS NOT NULL), 0::numeric) AS net_ytd
   FROM pay_run_lines l
     JOIN pay_runs r ON r.id = l.pay_run_id AND (r.status = ANY (ARRAY['approved'::text, 'paid'::text]))
     JOIN pay_periods p ON p.id = r.pay_period_id
     JOIN employees e ON e.id = l.employee_id
  GROUP BY l.employee_id, e.employee_code, e.full_name, (EXTRACT(year FROM p.pay_date));
create or replace view public.v_pipeline_run_status as
 SELECT id,
    pipeline,
    brand,
    sku,
    category,
    material_name,
    quantity,
    uom,
    source_kind,
    source_ref,
    started,
    current_stage,
    stages_done,
    stages_total,
    hours_in_current_stage,
    total_hours_elapsed,
    stage_target_hours,
    stage_overdue,
    completed,
    finished_good_lot,
    started AS started_date
   FROM ( SELECT r.id,
            p.name AS pipeline,
            r.brand,
            r.sku,
            r.category,
            r.material_name,
            r.quantity,
            r.uom,
            r.source_kind,
            r.source_ref,
            r.started_at::date AS started,
            s.name AS current_stage,
            ( SELECT count(*) AS count
                   FROM pipeline_stage_events e
                  WHERE e.run_id = r.id AND e.exited_at IS NOT NULL) AS stages_done,
            ( SELECT count(*) AS count
                   FROM pipeline_stages ps
                  WHERE ps.pipeline_id = r.pipeline_id) AS stages_total,
            round(EXTRACT(epoch FROM now() - COALESCE(( SELECT max(e.entered_at) AS max
                   FROM pipeline_stage_events e
                  WHERE e.run_id = r.id AND e.exited_at IS NULL), r.started_at)) / 3600::numeric, 1) AS hours_in_current_stage,
            round(EXTRACT(epoch FROM COALESCE(r.completed_at, now()) - r.started_at) / 3600::numeric, 1) AS total_hours_elapsed,
            s.target_hours AS stage_target_hours,
            r.completed_at IS NULL AND s.target_hours IS NOT NULL AND (EXTRACT(epoch FROM now() - COALESCE(( SELECT max(e.entered_at) AS max
                   FROM pipeline_stage_events e
                  WHERE e.run_id = r.id AND e.exited_at IS NULL), r.started_at)) / 3600::numeric) > s.target_hours AS stage_overdue,
            r.completed_at IS NOT NULL AS completed,
            r.finished_good_lot
           FROM pipeline_runs r
             JOIN pipelines p ON p.id = r.pipeline_id
             LEFT JOIN pipeline_stages s ON s.id = r.current_stage_id
          ORDER BY r.started_at DESC) q;
create or replace view public.v_pipeline_stage_aging as
 SELECT p.name AS pipeline,
    ps.stage_no,
    ps.name AS stage,
    ps.target_hours,
    count(e.id) AS times_entered,
    round(avg(EXTRACT(epoch FROM COALESCE(e.exited_at, now()) - e.entered_at) / 3600::numeric), 1) AS avg_hours,
    round(max(EXTRACT(epoch FROM COALESCE(e.exited_at, now()) - e.entered_at) / 3600::numeric), 1) AS max_hours
   FROM pipeline_stages ps
     JOIN pipelines p ON p.id = ps.pipeline_id
     LEFT JOIN pipeline_stage_events e ON e.stage_id = ps.id
  GROUP BY p.name, ps.stage_no, ps.name, ps.target_hours
  ORDER BY p.name, ps.stage_no;
create or replace view public.v_plant_history as
 SELECT license,
    date_trunc('month'::text, planted_on::timestamp with time zone)::date AS month_date,
    to_char(planted_on::timestamp with time zone, 'YYYY-MM'::text) AS month,
    count(*)::numeric AS plants_planted,
    count(DISTINCT strain)::numeric AS strains_planted,
    string_agg(DISTINCT strain, ', '::text) AS strains,
    count(*) FILTER (WHERE source_state = ANY (ARRAY['vegetative'::text, 'flowering'::text, 'onhold'::text]))::numeric AS still_alive,
    count(*) FILTER (WHERE source_state = 'inactive'::text)::numeric AS harvested_or_retired
   FROM metrc_plants
  WHERE planted_on IS NOT NULL
  GROUP BY license, (date_trunc('month'::text, planted_on::timestamp with time zone)), (to_char(planted_on::timestamp with time zone, 'YYYY-MM'::text))
  ORDER BY (date_trunc('month'::text, planted_on::timestamp with time zone)::date) DESC;
create or replace view public.v_production_forecast as
 SELECT to_char(date_trunc('month'::text, projected_availability::timestamp with time zone), 'YYYY-MM'::text) AS month,
    count(*) AS harvest_events,
    count(DISTINCT harvest_date) AS harvests,
    count(DISTINCT flower_room) AS rooms,
    sum(plants) AS plants,
    round(sum(projected_weight_lbs), 1) AS projected_lbs,
    round(sum(fresh_frozen_lbs), 1) AS fresh_frozen_lbs,
    round(sum(flower_after_ff_lbs), 1) AS flower_lbs_after_ff
   FROM harvest_schedule
  WHERE projected_availability IS NOT NULL
  GROUP BY (to_char(date_trunc('month'::text, projected_availability::timestamp with time zone), 'YYYY-MM'::text))
  ORDER BY (to_char(date_trunc('month'::text, projected_availability::timestamp with time zone), 'YYYY-MM'::text));
create or replace view public.v_real_loss as
 SELECT 'Plant attrition'::text AS loss_type,
    COALESCE(p.strain, 'not recorded'::text) AS scope,
    p.room AS location,
    count(*)::numeric AS units,
    'plants'::text AS unit_label,
    NULL::numeric AS pounds,
    'Plants retired without producing a harvest. This is capacity that cost money and returned nothing.'::text AS why_it_is_a_loss,
    'Compare to plants harvested for the same strain. A high count means culls, disease or death.'::text AS what_to_check
   FROM metrc_plants p
  WHERE p.source_state = 'inactive'::text AND NOT (EXISTS ( SELECT 1
           FROM metrc_harvests h
          WHERE COALESCE(h.raw ->> 'SourceStrainNames'::text, ''::text) ~~* (('%'::text || COALESCE(p.strain, '~'::text)) || '%'::text) AND h.harvest_start >= p.planted_on AND h.harvest_start <= (p.planted_on + 200)))
  GROUP BY (COALESCE(p.strain, 'not recorded'::text)), p.room
 HAVING count(*) > 5
UNION ALL
 SELECT 'Yield underperformance'::text AS loss_type,
    COALESCE(h.raw ->> 'SourceStrainNames'::text, 'not recorded'::text) AS scope,
    COALESCE(h.raw ->> 'DryingLocationName'::text, '(no room)'::text) AS location,
    1::numeric AS units,
    'harvest'::text AS unit_label,
    round((( SELECT avg(COALESCE((h2.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) / NULLIF((h2.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) AS avg
           FROM metrc_harvests h2
          WHERE COALESCE((h2.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric) > 0::numeric)) * COALESCE((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric) / 453.592 - COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) / 453.592, 1) AS pounds,
    'This harvest produced fewer saleable pounds than the company average conversion would predict from its wet weight.'::text AS why_it_is_a_loss,
    'Check drying and trim practice for this room, and whether the wet weight was recorded accurately.'::text AS what_to_check
   FROM metrc_harvests h
  WHERE COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) > 0::numeric AND COALESCE((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric) > 0::numeric AND (COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) / ((h.raw ->> 'TotalWetWeight'::text)::numeric)) < (0.75 * (( SELECT avg(COALESCE((h2.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) / NULLIF((h2.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) AS avg
           FROM metrc_harvests h2
          WHERE COALESCE((h2.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric) > 0::numeric)))
UNION ALL
 SELECT 'Destroyed after failing testing'::text AS loss_type,
    COALESCE(p.item_name, '(unnamed)'::text) AS scope,
    COALESCE(p.location, '(no location)'::text) AS location,
    1::numeric AS units,
    'package'::text AS unit_label,
        CASE p.uom
            WHEN 'g'::text THEN round(COALESCE(p.quantity, 0::numeric) / f_rule('grams_per_pound'::text), 2)
            WHEN 'kg'::text THEN round(COALESCE(p.quantity, 0::numeric) * 1000.0 / f_rule('grams_per_pound'::text), 2)
            WHEN 'lb'::text THEN round(COALESCE(p.quantity, 0::numeric), 2)
            WHEN 'oz'::text THEN round(COALESCE(p.quantity, 0::numeric) / 16.0, 2)
            ELSE NULL::numeric
        END AS pounds,
    'Material that failed testing AND was destroyed. Only destroyed material is a loss: per the owner, failed material is remediated in house, sold on for remediation, or destroyed, and this business buys failed material at a discount to remediate it. Failing a test is not losing the value.'::text AS why_it_is_a_loss,
    'Confirm the destruction is recorded in Metrc.'::text AS what_to_check
   FROM metrc_packages p
  WHERE p.lab_testing_state = 'TestFailed'::text AND (p.source_state = ANY (ARRAY['active'::text, 'onhold'::text])) AND (EXISTS ( SELECT 1
           FROM failed_material_disposition fd
          WHERE fd.package_tag = p.tag AND fd.superseded_at IS NULL AND fd.disposition = 'destroy'::text))
UNION ALL
 SELECT 'Missed pull'::text AS loss_type,
    COALESCE(pl.cultivars, 'not recorded'::text) AS scope,
    pl.flower_room AS location,
    1::numeric AS units,
    'scheduled pull'::text AS unit_label,
    round(COALESCE(pl.proj_harvest_weight_lbs, 0::numeric), 1) AS pounds,
    'A pull was scheduled and never recorded. If nothing else was planted in its place, that is a full cycle of room capacity earning nothing.'::text AS why_it_is_a_loss,
    'Confirm whether the room was replanted. If it sat empty, that is the most expensive loss in cultivation.'::text AS what_to_check
   FROM harvest_pulls pl
  WHERE pl.harvest_date < (CURRENT_DATE - 14) AND NOT (EXISTS ( SELECT 1
           FROM metrc_harvests h
          WHERE h.harvest_start >= (pl.harvest_date - 5) AND h.harvest_start <= (pl.harvest_date + 21)));
create or replace view public.v_reason_settings as
 SELECT action_key,
    label,
    plain_english,
    enforced,
    require_code,
    require_note,
    min_note_chars,
    require_review_date,
    require_second_approver,
    ( SELECT count(*) AS count
           FROM reason_code_catalog c
          WHERE c.active AND (c.applies_to = '{}'::text[] OR (p.action_key = ANY (c.applies_to)))) AS codes_available,
    ( SELECT string_agg(c.code, ', '::text ORDER BY c.sort_order) AS string_agg
           FROM reason_code_catalog c
          WHERE c.active AND (c.applies_to = '{}'::text[] OR (p.action_key = ANY (c.applies_to)))) AS codes,
    COALESCE(set_by, 'not recorded'::text) AS set_by,
    updated_at,
        CASE
            WHEN enforced THEN 'ENFORCED - the action is refused without this'::text
            ELSE 'NOT ENFORCED - recorded but not gated'::text
        END AS status
   FROM reason_policy p;
create or replace view public.v_recurring_tasks as
 SELECT t.id AS task_id,
    t.title,
    t.status,
    t.priority,
    t.due_on,
    COALESCE(t.recurrence_parent_id, t.id) AS series_id,
        CASE
            WHEN t.recurrence_parent_id IS NULL THEN 'First task in the series'::text
            ELSE 'Created automatically from an earlier task'::text
        END AS series_position,
    r.every_days AS repeats_every_days,
    (COALESCE(t.due_on, CURRENT_DATE) + ((r.every_days || ' days'::text)::interval))::date AS next_occurrence_due_on,
    employee.full_name AS assigned_to,
    space.name AS space_name,
    t.tags,
    (( SELECT count(*) AS count
           FROM tasks series_member
          WHERE COALESCE(series_member.recurrence_parent_id, series_member.id) = COALESCE(t.recurrence_parent_id, t.id)))::integer AS tasks_in_series,
    t.completed_at,
    t.created_at
   FROM tasks t
     CROSS JOIN LATERAL ( SELECT GREATEST(1,
                CASE
                    WHEN (t.recurrence ->> 'every_days'::text) ~ '^[0-9]+$'::text THEN (t.recurrence ->> 'every_days'::text)::integer
                    ELSE 7
                END) AS every_days) r
     LEFT JOIN employees employee ON employee.id = t.assignee_employee_id
     LEFT JOIN spaces space ON space.id = t.space_id
  WHERE t.recurrence IS NOT NULL;
create or replace view public.v_remediation_owed as
 SELECT d.package_tag,
    p.item_name,
    p.license,
        CASE
            WHEN f_is_ours(p.raw ->> 'ItemFromFacilityLicenseNumber'::text) THEN 'OURS'::text
            ELSE 'BOUGHT IN'::text
        END AS whose_material,
    d.disposition AS promised,
    d.decided_by,
    d.decided_at::date AS decided_on,
    CURRENT_DATE - d.decided_at::date AS days_owed,
        CASE
            WHEN f_is_weight(p.uom) THEN round(f_to_pounds(p.quantity, p.uom), 2)
            ELSE NULL::numeric
        END AS pounds,
    p.lab_testing_state AS metrc_still_reads,
    p.location,
    d.reason,
    'THE ISSUE: a disposition was recorded but the work it promised has not been done. The package left the loss register and the flag board on the strength of an intention.'::text AS what_is_wrong,
    'Do the work, then set completed_at and completed_evidence on the disposition row. Until then this stays here.'::text AS what_to_do
   FROM failed_material_disposition d
     JOIN metrc_packages p ON p.tag = d.package_tag
  WHERE d.superseded_at IS NULL AND d.completed_at IS NULL AND (d.disposition = ANY (ARRAY['remediate_in_house'::text, 'sell_for_remediation'::text, 'destroy'::text]))
  ORDER BY (
        CASE
            WHEN f_is_weight(p.uom) THEN round(f_to_pounds(p.quantity, p.uom), 2)
            ELSE NULL::numeric
        END) DESC NULLS LAST;
create or replace view public.v_report_catalogue as
 SELECT report_key,
    title,
    category,
    fact_view,
    date_column IS NOT NULL AS supports_date_range,
    date_column,
    array_length(dimensions, 1) AS dimension_count,
    array_length(measures, 1) AS measure_count,
    dimensions,
    measures,
    description,
    owner_note,
    array_length(dimensions, 1) * (1 + array_length(dimensions, 1) - 1) * array_length(dimensions, 1) *
        CASE
            WHEN date_column IS NOT NULL THEN 4
            ELSE 1
        END AS report_permutations
   FROM report_registry r
  WHERE enabled;
create or replace view public.v_report_coverage as
 WITH held AS (
         SELECT 'harvests_inactive'::text AS report_key,
            metrc_rpt_harvest_moisture.licence,
            min(metrc_rpt_harvest_moisture.finished_on) AS first_event,
            max(metrc_rpt_harvest_moisture.finished_on) AS last_event,
            count(*) AS rows_held,
            max(metrc_rpt_harvest_moisture.as_of_date) AS last_as_of
           FROM metrc_rpt_harvest_moisture
          GROUP BY metrc_rpt_harvest_moisture.licence
        UNION ALL
         SELECT 'packages_transferred'::text,
            metrc_rpt_package_transfers.licence,
            min(metrc_rpt_package_transfers.received_on) AS min,
            max(metrc_rpt_package_transfers.received_on) AS max,
            count(*) AS count,
            max(metrc_rpt_package_transfers.as_of_date) AS max
           FROM metrc_rpt_package_transfers
          GROUP BY metrc_rpt_package_transfers.licence
        UNION ALL
         SELECT 'wholesale_transfers'::text,
            metrc_rpt_wholesale.licence,
            min(metrc_rpt_wholesale.created_on) AS min,
            max(metrc_rpt_wholesale.created_on) AS max,
            count(*) AS count,
            max(metrc_rpt_wholesale.as_of_date) AS max
           FROM metrc_rpt_wholesale
          GROUP BY metrc_rpt_wholesale.licence
        UNION ALL
         SELECT 'packages_adjustments'::text,
            metrc_rpt_adjustments.licence,
            min(metrc_rpt_adjustments.adjusted_on) AS min,
            max(metrc_rpt_adjustments.adjusted_on) AS max,
            count(*) AS count,
            max(metrc_rpt_adjustments.as_of_date) AS max
           FROM metrc_rpt_adjustments
          GROUP BY metrc_rpt_adjustments.licence
        UNION ALL
         SELECT 'plants_waste'::text,
            metrc_rpt_plant_waste.licence,
            min(metrc_rpt_plant_waste.waste_date) AS min,
            max(metrc_rpt_plant_waste.waste_date) AS max,
            count(*) AS count,
            max(metrc_rpt_plant_waste.as_of_date) AS max
           FROM metrc_rpt_plant_waste
          GROUP BY metrc_rpt_plant_waste.licence
        UNION ALL
         SELECT 'plants_destroyed'::text,
            metrc_rpt_plants_destroyed.licence,
            min(metrc_rpt_plants_destroyed.phase_date) AS min,
            max(metrc_rpt_plants_destroyed.phase_date) AS max,
            count(*) AS count,
            max(metrc_rpt_plants_destroyed.as_of_date) AS max
           FROM metrc_rpt_plants_destroyed
          GROUP BY metrc_rpt_plants_destroyed.licence
        UNION ALL
         SELECT 'test_batches'::text,
            metrc_rpt_test_batches.licence,
            min(metrc_rpt_test_batches.test_date) AS min,
            max(metrc_rpt_test_batches.test_date) AS max,
            count(*) AS count,
            max(metrc_rpt_test_batches.as_of_date) AS max
           FROM metrc_rpt_test_batches
          GROUP BY metrc_rpt_test_batches.licence
        UNION ALL
         SELECT 'harvests'::text,
            metrc_rpt_harvests.licence,
            min(metrc_rpt_harvests.finished_date) AS min,
            max(metrc_rpt_harvests.finished_date) AS max,
            count(*) AS count,
            max(metrc_rpt_harvests.as_of_date) AS max
           FROM metrc_rpt_harvests
          GROUP BY metrc_rpt_harvests.licence
        UNION ALL
         SELECT 'packages_inventory'::text,
            metrc_rpt_packages_inventory.licence,
            min(metrc_rpt_packages_inventory.packaged_on) AS min,
            max(metrc_rpt_packages_inventory.packaged_on) AS max,
            count(*) AS count,
            max(metrc_rpt_packages_inventory.as_of_date) AS max
           FROM metrc_rpt_packages_inventory
          GROUP BY metrc_rpt_packages_inventory.licence
        UNION ALL
         SELECT 'inventory_point_in_time'::text,
            metrc_rpt_point_in_time.licence,
            min(metrc_rpt_point_in_time.as_of_date) AS min,
            max(metrc_rpt_point_in_time.as_of_date) AS max,
            count(*) AS count,
            max(metrc_rpt_point_in_time.as_of_date) AS max
           FROM metrc_rpt_point_in_time
          GROUP BY metrc_rpt_point_in_time.licence
        )
 SELECT t.report_key,
    t.title,
    t.cadence,
    t.menu_path,
    t.upload_priority,
    lic.licence AS required_for_licence,
    h.rows_held,
    h.first_event,
    h.last_event,
    h.last_as_of,
        CASE
            WHEN h.rows_held IS NULL THEN 'Never uploaded'::text
            WHEN t.cadence ~~ 'Monthly%'::text AND h.last_event < (date_trunc('month'::text, CURRENT_DATE::timestamp with time zone)::date - 1) THEN 'Gap - the last month is missing'::text
            WHEN t.cadence ~~ 'Quarterly%'::text AND h.last_event < (date_trunc('quarter'::text, CURRENT_DATE::timestamp with time zone)::date - 1) THEN 'Gap - the last quarter is missing'::text
            ELSE 'Covered'::text
        END AS coverage,
    COALESCE(h.last_event - 14, '2024-01-01'::date) AS export_from,
    CURRENT_DATE AS export_to,
        CASE
            WHEN h.rows_held IS NULL THEN 'Export everything Metrc will give you - nothing is held yet.'::text
            ELSE (('Export from '::text || to_char(COALESCE(h.last_event - 14, '2024-01-01'::date)::timestamp with time zone, 'DD Mon YYYY'::text)) || ' to today. The overlap is deliberate: re-importing a row corrects it, it never '::text) || 'duplicates, so a wider range is always safe.'::text
        END AS what_to_export
   FROM metrc_report_types t
     CROSS JOIN LATERAL unnest(t.required_licences) lic(licence)
     LEFT JOIN held h ON h.report_key = t.report_key AND COALESCE(h.licence, lic.licence) = lic.licence
  WHERE t.cadence !~~ 'On demand%'::text
  ORDER BY t.upload_priority, lic.licence;
create or replace view public.v_report_mapping_status as
 SELECT t.report_key,
    t.title,
    t.upload_priority,
    t.cadence,
    t.menu_path,
    t.what_it_adds,
    t.why_it_matters,
    t.api_covers_this,
    t.licence_scope,
    t.target_table,
    array_length(t.signature_cols, 1) AS detect_columns,
    t.signature_cols,
    t.key_cols,
    COALESCE(i.imports, 0::bigint) AS imports_done,
    i.last_import_at,
    i.last_file,
    i.last_rows,
        CASE
            WHEN i.last_import_at IS NULL THEN 'Never uploaded'::text
            WHEN t.cadence ~~ 'Monthly%'::text AND i.last_import_at < date_trunc('month'::text, CURRENT_DATE::timestamp with time zone) THEN 'Overdue - this month not uploaded'::text
            WHEN t.cadence ~~ 'Yearly%'::text AND i.last_import_at < date_trunc('year'::text, CURRENT_DATE::timestamp with time zone) THEN 'Overdue - this year not uploaded'::text
            ELSE 'Up to date'::text
        END AS upload_status
   FROM metrc_report_types t
     LEFT JOIN LATERAL ( SELECT count(*) AS imports,
            max(m.imported_at) AS last_import_at,
            (array_agg(m.file_name ORDER BY m.imported_at DESC))[1] AS last_file,
            (array_agg(m.row_count ORDER BY m.imported_at DESC))[1] AS last_rows
           FROM metrc_report_imports m
          WHERE m.report_type = t.report_key) i ON true
  ORDER BY t.upload_priority;
create or replace view public.v_report_upload_due as
 WITH expected AS (
         SELECT t.report_key,
            t.title,
            t.upload_priority,
            t.cadence,
            t.menu_path,
            t.why_it_matters,
            t.what_it_adds,
            t.target_table,
            t.api_covers_this,
            lic.lic AS licence,
                CASE
                    WHEN t.cadence ~~ 'Monthly%'::text THEN (date_trunc('month'::text, CURRENT_DATE::timestamp with time zone) - '1 mon'::interval)::date
                    WHEN t.cadence ~~ 'Quarterly%'::text THEN (date_trunc('quarter'::text, CURRENT_DATE::timestamp with time zone) - '3 mons'::interval)::date
                    WHEN t.cadence ~~ 'Yearly%'::text THEN (date_trunc('year'::text, CURRENT_DATE::timestamp with time zone) - '1 year'::interval)::date
                    ELSE NULL::date
                END AS period_start,
                CASE
                    WHEN t.cadence ~~ 'Monthly%'::text THEN date_trunc('month'::text, CURRENT_DATE::timestamp with time zone)::date + 5
                    WHEN t.cadence ~~ 'Quarterly%'::text THEN date_trunc('quarter'::text, CURRENT_DATE::timestamp with time zone)::date + 10
                    WHEN t.cadence ~~ 'Yearly%'::text THEN date_trunc('year'::text, CURRENT_DATE::timestamp with time zone)::date + 31
                    ELSE NULL::date
                END AS due_by
           FROM metrc_report_types t
             CROSS JOIN LATERAL unnest(t.required_licences) lic(lic)
          WHERE t.cadence !~~ 'On demand%'::text
        )
 SELECT e.report_key,
    e.title,
    e.upload_priority,
    e.cadence,
    e.menu_path,
    e.why_it_matters,
    e.what_it_adds,
    e.target_table,
    e.api_covers_this,
    e.licence,
    e.period_start,
    e.due_by,
    to_char(e.period_start::timestamp with time zone,
        CASE
            WHEN e.cadence ~~ 'Monthly%'::text THEN 'FMMonth YYYY'::text
            WHEN e.cadence ~~ 'Quarterly%'::text THEN '"Q"Q YYYY'::text
            ELSE 'YYYY'::text
        END) AS period_label,
    i.imported_at,
    i.file_name,
    i.row_count,
    i.imported_by,
    i.id IS NOT NULL AS received,
    CURRENT_DATE - e.due_by AS days_late,
        CASE
            WHEN i.id IS NOT NULL THEN 'Received'::text
            WHEN CURRENT_DATE <= e.due_by THEN 'Due by '::text || to_char(e.due_by::timestamp with time zone, 'DD Mon'::text)
            ELSE ('OVERDUE by '::text || (CURRENT_DATE - e.due_by)) || ' days'::text
        END AS upload_status,
        CASE
            WHEN i.id IS NOT NULL THEN 'ok'::text
            WHEN CURRENT_DATE <= e.due_by THEN 'due'::text
            WHEN e.cadence ~~ '%required%'::text THEN 'critical'::text
            ELSE 'elevated'::text
        END AS severity
   FROM expected e
     LEFT JOIN LATERAL ( SELECT m.id,
            m.report_type,
            m.license,
            m.file_name,
            m.row_count,
            m.mapped_to,
            m.imported_by,
            m.imported_at,
            m.period_start
           FROM metrc_report_imports m
          WHERE m.report_type = e.report_key AND COALESCE(m.license, e.licence) = e.licence AND m.period_start = e.period_start
          ORDER BY m.imported_at DESC
         LIMIT 1) i ON true
  ORDER BY (i.id IS NOT NULL), e.upload_priority, e.licence;
create or replace view public.v_request_scorecard as
 SELECT owner_requests.status,
    owner_requests.priority,
    count(*) AS requests,
    round(100.0 * count(*)::numeric / NULLIF(( SELECT count(*) AS count
           FROM owner_requests owner_requests_1), 0)::numeric, 1) AS pct_of_all
   FROM owner_requests
  GROUP BY owner_requests.status, owner_requests.priority
UNION ALL
 SELECT 'ALL REQUESTS'::text AS status,
    '-'::text AS priority,
    count(*) AS requests,
    100.0 AS pct_of_all
   FROM owner_requests;
create or replace view public.v_role_clearance_breaches as
 SELECT 'UNCLASSIFIED'::text AS breach_type,
    nr.view_key,
    nr.label,
    COALESCE(nr.surface, 'side'::text) AS surface,
    NULL::text AS role,
    NULL::integer AS role_rank,
    NULL::integer AS needs_rank,
    'This page matches the sensitive pattern but has no sensitive_page_policy row, so every role can see it. useNav hides only what is explicitly marked visible=false.'::text AS detail
   FROM nav_registry nr
  WHERE nr.enabled AND ((nr.surface = ANY (ARRAY['finance'::text, 'tax'::text, 'hr'::text])) OR nr.category ~~* '%human%'::text OR nr.view_key ~* 'payroll|valuation|cost|licence|license|secret|wage|salary|cash|overhead'::text) AND NOT (EXISTS ( SELECT 1
           FROM sensitive_page_policy p
          WHERE p.view_key = nr.view_key))
UNION ALL
 SELECT 'ABOVE CLEARANCE'::text AS breach_type,
    p.view_key,
    nr.label,
    COALESCE(nr.surface, 'side'::text) AS surface,
    r.role,
    r.rank AS role_rank,
    p.min_rank AS needs_rank,
    ((((('Role '::text || r.role) || ' (rank '::text) || r.rank) || ') can see a page needing rank '::text) || p.min_rank) || '. Insert nav_role_visibility (view_key, role, visible=false).'::text AS detail
   FROM sensitive_page_policy p
     JOIN nav_registry nr ON nr.view_key = p.view_key AND nr.enabled
     CROSS JOIN app_roles r
  WHERE r.rank < p.min_rank AND (r.role IN ( SELECT unnest(enum_range(NULL::app_role))::text AS unnest)) AND NOT (EXISTS ( SELECT 1
           FROM nav_role_visibility v
          WHERE v.view_key = p.view_key AND v.role = r.role AND v.visible = false));
create or replace view public.v_role_menu_matrix as
 SELECT n.category,
    n.label,
    n.view_key,
    n.admin_only,
    bool_or(v.visible) FILTER (WHERE v.role = 'owner'::text) AS owner,
    bool_or(v.visible) FILTER (WHERE v.role = 'executive'::text) AS executive,
    bool_or(v.visible) FILTER (WHERE v.role = 'manager'::text) AS manager,
    bool_or(v.visible) FILTER (WHERE v.role = 'member'::text) AS member,
    bool_or(v.visible) FILTER (WHERE v.role = 'limited'::text) AS limited,
    bool_or(v.visible) FILTER (WHERE v.role = 'guest'::text) AS guest
   FROM nav_registry n
     LEFT JOIN nav_role_visibility v ON v.view_key = n.view_key
  GROUP BY n.category, n.label, n.view_key, n.admin_only, n.category_order, n.item_order
  ORDER BY n.category_order, n.item_order;
create or replace view public.v_room_canopy_status as
 SELECT code,
    legacy_label,
    plant_capacity,
    cycle_days,
    sqft,
    sqft_source,
    round(sqft / NULLIF(plant_capacity, 0)::numeric, 2) AS sqft_per_plant,
    ( SELECT round(avg(g.sqft / NULLIF(g.plant_capacity, 0)::numeric), 2) AS round
           FROM grow_rooms g
          WHERE g.sqft IS NOT NULL AND g.active) AS sqft_per_plant_in_measured_rooms,
        CASE
            WHEN sqft IS NULL THEN round(plant_capacity::numeric * (( SELECT avg(g.sqft / NULLIF(g.plant_capacity, 0)::numeric) AS avg
               FROM grow_rooms g
              WHERE g.sqft IS NOT NULL AND g.active)))
            ELSE NULL::numeric
        END AS sqft_if_same_density,
        CASE
            WHEN sqft IS NOT NULL THEN 'Measured. Yield per square foot is calculated for this room.'::text
            ELSE (((((((('CANNOT BE MEASURED. No square footage on file, so this room is excluded from every '::text || 'yield per square foot figure — '::text) || plant_capacity) || ' plants of canopy are invisible '::text) || 'in the benchmark. At the '::text) || (( SELECT round(avg(g.sqft / NULLIF(g.plant_capacity, 0)::numeric), 2) AS round
               FROM grow_rooms g
              WHERE g.sqft IS NOT NULL AND g.active))) || ' square feet per plant the measured rooms run at, it would be about '::text) || round(plant_capacity::numeric * (( SELECT avg(g.sqft / NULLIF(g.plant_capacity, 0)::numeric) AS avg
               FROM grow_rooms g
              WHERE g.sqft IS NOT NULL AND g.active)))) || ' square feet — but that is inferred from two rooms, not measured, and is deliberately '::text) || 'not being used. Measure the room and enter it on Grow Rooms.'::text
        END AS status
   FROM grow_rooms r
  WHERE active
  ORDER BY code;
create or replace view public.v_room_month_comparison as
 WITH rm AS (
         SELECT COALESCE(h.raw ->> 'DryingLocationName'::text, '(no room)'::text) AS room,
            to_char(h.harvest_start::timestamp with time zone, 'YYYY-MM'::text) AS month,
            date_trunc('month'::text, h.harvest_start::timestamp with time zone)::date AS month_date,
            count(*) AS harvests,
            sum(COALESCE((h.raw ->> 'PlantCount'::text)::numeric, 0::numeric)) AS plants,
            sum(COALESCE((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) AS wet_g,
            sum(COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric)) AS packaged_g,
            sum(COALESCE((h.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric)) AS waste_g,
            avg(
                CASE
                    WHEN (h.raw ->> 'FinishedDate'::text) IS NOT NULL THEN ((h.raw ->> 'FinishedDate'::text)::date) - h.harvest_start
                    ELSE NULL::integer
                END) AS avg_dry_days
           FROM metrc_harvests h
          WHERE h.harvest_start IS NOT NULL
          GROUP BY (COALESCE(h.raw ->> 'DryingLocationName'::text, '(no room)'::text)), (to_char(h.harvest_start::timestamp with time zone, 'YYYY-MM'::text)), (date_trunc('month'::text, h.harvest_start::timestamp with time zone)::date)
        ), scored AS (
         SELECT rm.room,
            rm.month,
            rm.month_date,
            rm.harvests,
            rm.plants,
            rm.wet_g,
            rm.packaged_g,
            rm.waste_g,
            rm.avg_dry_days,
                CASE
                    WHEN rm.wet_g > 0::numeric THEN round(100.0 * rm.packaged_g / rm.wet_g, 1)
                    ELSE NULL::numeric
                END AS conversion_pct,
                CASE
                    WHEN rm.plants > 0::numeric THEN round(rm.packaged_g / rm.plants, 1)
                    ELSE NULL::numeric
                END AS grams_per_plant,
            round(rm.avg_dry_days, 1) AS dry_days
           FROM rm
        )
 SELECT room,
    month,
    harvests,
    plants,
    round(wet_g / 453.592, 1) AS wet_lbs,
    round(packaged_g / 453.592, 1) AS saleable_lbs,
    conversion_pct,
    grams_per_plant,
    dry_days,
    max(conversion_pct) OVER (PARTITION BY room) AS room_best_conversion,
    min(conversion_pct) OVER (PARTITION BY room) AS room_worst_conversion,
    round(conversion_pct - avg(conversion_pct) OVER (PARTITION BY room), 1) AS versus_room_average,
    ( SELECT industry_benchmarks.average
           FROM industry_benchmarks
          WHERE industry_benchmarks.metric = 'Wet to saleable conversion'::text) AS industry_average_pct,
        CASE
            WHEN conversion_pct = max(conversion_pct) OVER (PARTITION BY room) THEN 'BEST MONTH for this room'::text
            WHEN conversion_pct = min(conversion_pct) OVER (PARTITION BY room) THEN 'WORST MONTH for this room'::text
            ELSE 'middle of the range'::text
        END AS standing,
    round(wet_g / 453.592 * (max(conversion_pct) OVER (PARTITION BY room) - conversion_pct) / 100.0, 1) AS pounds_lost_versus_room_best,
    round(wet_g / 453.592 * (max(conversion_pct) OVER (PARTITION BY room) - conversion_pct) / 100.0 * (( SELECT cost_model.cost_per_pound
           FROM cost_model
          WHERE cost_model.scope = 'cultivation'::text
          ORDER BY cost_model.effective_from DESC
         LIMIT 1)), 0) AS dollars_lost_versus_room_best,
    ((('This room hit '::text || max(conversion_pct) OVER (PARTITION BY room)) || ' percent in its best month and '::text) || conversion_pct) || ' percent here. Same room, same equipment - the difference is drying time and trim practice, not the building.'::text AS what_this_means,
        CASE
            WHEN dry_days IS NOT NULL THEN ('Average dry ran '::text || dry_days) || ' days this month.'::text
            ELSE 'Dry duration not recorded for this month.'::text
        END AS dry_evidence,
    month_date
   FROM scored s
  ORDER BY (round(wet_g / 453.592 * (max(conversion_pct) OVER (PARTITION BY room) - conversion_pct) / 100.0 * (( SELECT cost_model.cost_per_pound
           FROM cost_model
          WHERE cost_model.scope = 'cultivation'::text
          ORDER BY cost_model.effective_from DESC
         LIMIT 1)), 0)) DESC NULLS LAST;
create or replace view public.v_room_plant_counts as
 SELECT COALESCE(NULLIF(raw ->> 'LocationName'::text, ''::text), 'Not recorded'::text) AS room,
    raw ->> 'GrowthPhase'::text AS growth_phase,
    count(*) AS plants,
    count(DISTINCT NULLIF(raw ->> 'StrainName'::text, ''::text)) AS strains,
    string_agg(DISTINCT NULLIF(raw ->> 'StrainName'::text, ''::text), ', '::text) AS strain_list,
    min((raw ->> 'PlantedDate'::text)::date) AS earliest_planted,
    max((raw ->> 'PlantedDate'::text)::date) AS latest_planted
   FROM metrc_plants
  WHERE (raw ->> 'State'::text) = 'Tracked'::text
  GROUP BY (COALESCE(NULLIF(raw ->> 'LocationName'::text, ''::text), 'Not recorded'::text)), (raw ->> 'GrowthPhase'::text)
  ORDER BY (count(*)) DESC;
create or replace view public.v_route_margin as
 SELECT e.product_route,
    e.product_family,
    e.sell_price_per_unit,
    e.packaging_cost_per_unit + e.labor_cost_per_unit + e.other_cost_per_unit AS conversion_cost_per_unit,
    e.sell_price_per_unit - e.packaging_cost_per_unit - e.labor_cost_per_unit - e.other_cost_per_unit AS contribution_per_unit,
    e.input_grams_per_unit,
    e.yield_pct,
    round((e.sell_price_per_unit - e.packaging_cost_per_unit - e.labor_cost_per_unit - e.other_cost_per_unit) / (e.input_grams_per_unit / (e.yield_pct / 100.0)), 4) AS margin_per_input_gram,
        CASE
            WHEN e.sell_price_per_unit > 0::numeric THEN round(100.0 * (e.sell_price_per_unit - e.packaging_cost_per_unit - e.labor_cost_per_unit - e.other_cost_per_unit) / e.sell_price_per_unit, 1)
            ELSE NULL::numeric
        END AS gross_margin_pct,
    e.cycle_days,
    COALESCE(d.units_demanded, 0::numeric) AS units_demanded,
    COALESCE(d.units_committed, 0::numeric) AS units_committed,
    GREATEST(COALESCE(d.units_demanded, 0::numeric) - COALESCE(d.units_committed, 0::numeric), 0::numeric) AS units_open,
    round(GREATEST(COALESCE(d.units_demanded, 0::numeric) - COALESCE(d.units_committed, 0::numeric), 0::numeric) * e.input_grams_per_unit / (e.yield_pct / 100.0), 1) AS grams_needed_for_open_demand,
    e.active
   FROM product_economics e
     LEFT JOIN LATERAL ( SELECT sum(s.units_demanded) AS units_demanded,
            sum(s.units_committed) AS units_committed
           FROM demand_signals s
          WHERE s.product_route = e.product_route AND (s.period_end IS NULL OR s.period_end >= CURRENT_DATE)) d ON true
  WHERE e.active
  ORDER BY (round((e.sell_price_per_unit - e.packaging_cost_per_unit - e.labor_cost_per_unit - e.other_cost_per_unit) / (e.input_grams_per_unit / (e.yield_pct / 100.0)), 4)) DESC NULLS LAST;
create or replace view public.v_sales_history as
 SELECT created_on AS sold_on,
    to_char(created_on::timestamp with time zone, 'YYYY-MM'::text) AS month,
    manifest_number,
    recipient AS customer,
    raw ->> 'RecipientFacilityLicenseNumber'::text AS customer_license,
    COALESCE((raw ->> 'PackageCount'::text)::numeric, 0::numeric) AS packages_sent,
    COALESCE((raw ->> 'ReceivedPackageCount'::text)::numeric, 0::numeric) AS packages_received,
    raw ->> 'ShipmentTypeName'::text AS shipment_type,
    (raw ->> 'ReceivedDateTime'::text)::date AS received_on,
        CASE
            WHEN (raw ->> 'ReceivedDateTime'::text) IS NOT NULL THEN 'Delivered'::text
            WHEN created_on < (CURRENT_DATE - 3) THEN 'NOT CONFIRMED RECEIVED'::text
            ELSE 'In transit'::text
        END AS delivery_status,
        CASE
            WHEN (raw ->> 'Id'::text) IS NOT NULL THEN ('https://ma.metrc.com/reports/transfers/'::text || (raw ->> 'Id'::text)) || '/manifest'::text
            ELSE NULL::text
        END AS manifest_link,
    license
   FROM metrc_transfers t
  WHERE direction = 'outgoing'::text
  ORDER BY created_on DESC NULLS LAST;
create or replace view public.v_schedulable as
 SELECT e.id AS employee_id,
    e.employee_code,
    e.full_name,
    d.name AS department,
    e.hours_basis,
    e.badge_expires,
    e.badge_expires IS NOT NULL AND e.badge_expires >= CURRENT_DATE AS licence_valid,
    e.status::text = 'active'::text AS employed,
    COALESCE(e.weekly_target_hours, 40::numeric) AS target_hours,
    (EXISTS ( SELECT 1
           FROM employee_availability a
          WHERE a.employee_id = e.id AND a.available = false AND (a.specific_date = CURRENT_DATE OR a.weekday = EXTRACT(dow FROM CURRENT_DATE)::integer))) AS blacked_out,
        CASE
            WHEN e.status::text <> 'active'::text THEN 'not employed'::text
            WHEN e.badge_expires IS NULL THEN 'no licence on file'::text
            WHEN e.badge_expires < CURRENT_DATE THEN 'licence expired'::text
            WHEN (EXISTS ( SELECT 1
               FROM employee_availability a
              WHERE a.employee_id = e.id AND a.available = false AND (a.specific_date = CURRENT_DATE OR a.weekday = EXTRACT(dow FROM CURRENT_DATE)::integer))) THEN 'unavailable today'::text
            ELSE 'schedulable'::text
        END AS schedulable_state
   FROM employees e
     LEFT JOIN departments d ON d.id = e.primary_department_id;
create or replace view public.v_schedule_vs_worked as
 WITH sched AS (
         SELECT employee_schedules.employee_id,
            employee_schedules.work_date,
            employee_schedules.zone,
            sum(EXTRACT(epoch FROM employee_schedules.planned_end - employee_schedules.planned_start) / 3600.0)::numeric(6,2) AS scheduled_hours
           FROM employee_schedules
          WHERE employee_schedules.planned_start IS NOT NULL AND employee_schedules.planned_end IS NOT NULL
          GROUP BY employee_schedules.employee_id, employee_schedules.work_date, employee_schedules.zone
        ), act AS (
         SELECT time_entries.employee_id,
            time_entries.work_date,
            sum(EXTRACT(epoch FROM time_entries.clock_out - time_entries.clock_in) / 3600.0 - COALESCE(time_entries.unpaid_lunch_min, 0)::numeric / 60.0)::numeric(6,2) AS worked_hours,
            count(*) FILTER (WHERE time_entries.clock_out IS NULL) AS open_punches,
            min(time_entries.clock_in) AS first_in,
            max(time_entries.clock_out) AS last_out
           FROM time_entries
          WHERE time_entries.clock_in IS NOT NULL
          GROUP BY time_entries.employee_id, time_entries.work_date
        )
 SELECT e.id AS employee_id,
    e.employee_code,
    e.full_name,
    COALESCE(s.work_date, a.work_date) AS work_date,
    s.zone,
    COALESCE(s.scheduled_hours, 0::numeric) AS scheduled_hours,
    COALESCE(a.worked_hours, 0::numeric) AS worked_hours,
    (COALESCE(a.worked_hours, 0::numeric) - COALESCE(s.scheduled_hours, 0::numeric))::numeric(6,2) AS variance_hours,
        CASE
            WHEN COALESCE(s.scheduled_hours, 0::numeric) = 0::numeric THEN NULL::numeric
            ELSE round(LEAST(COALESCE(a.worked_hours, 0::numeric) / s.scheduled_hours, 2::numeric) * 100::numeric, 1)
        END AS adherence_pct,
    GREATEST(COALESCE(a.worked_hours, 0::numeric) - 8::numeric, 0::numeric)::numeric(6,2) AS daily_ot_hours,
    a.first_in,
    a.last_out,
    COALESCE(a.open_punches, 0::bigint) AS open_punches,
        CASE
            WHEN a.employee_id IS NULL THEN 'no_show_or_unrecorded'::text
            WHEN s.employee_id IS NULL THEN 'unscheduled_work'::text
            WHEN a.open_punches > 0 THEN 'missing_punch'::text
            WHEN a.worked_hours > (s.scheduled_hours + 0.25) THEN 'over'::text
            WHEN a.worked_hours < (s.scheduled_hours - 0.25) THEN 'under'::text
            ELSE 'on_plan'::text
        END AS flag
   FROM sched s
     FULL JOIN act a ON a.employee_id = s.employee_id AND a.work_date = s.work_date
     JOIN employees e ON e.id = COALESCE(s.employee_id, a.employee_id);
create or replace view public.v_secret_status as
 SELECT key,
    label,
    help,
        CASE
            WHEN COALESCE(value, ''::text) = ''::text THEN 'NOT SET'::text
            ELSE 'SET'::text
        END AS status,
        CASE
            WHEN COALESCE(value, ''::text) = ''::text THEN NULL::text
            ELSE ("left"(value, 7) || '…'::text) || "right"(value, 4)
        END AS masked,
    updated_at
   FROM app_secrets s;
create or replace view public.v_seed_to_sale_chain as
 SELECT license,
    harvest,
    package_tag,
    item_name,
    quantity,
    uom,
    current_location,
    packaged_on,
    lab_testing_state,
    category,
    on_hold,
    finished,
    stage,
    manifest_number,
    direction,
    recipient,
    transfer_date,
    source_state,
    f_stock_status(source_state, finished) AS stock_status
   FROM ( SELECT p.license,
            COALESCE(NULLIF(p.raw ->> 'SourceHarvestNames'::text, ''::text), '(no source harvest)'::text) AS harvest,
            p.tag AS package_tag,
            p.item_name,
            p.quantity,
            p.uom,
            p.location AS current_location,
            p.packaged_on,
            p.lab_testing_state,
            p.raw ->> 'ProductCategoryName'::text AS category,
            (p.raw ->> 'IsOnHold'::text)::boolean AS on_hold,
            (p.raw ->> 'IsFinished'::text)::boolean AS finished,
                CASE
                    WHEN (p.raw ->> 'IsOnHold'::text)::boolean THEN 'ON HOLD'::text
                    WHEN p.source_state = 'intransit'::text THEN 'In transit to customer'::text
                    WHEN p.source_state = 'inactive'::text THEN 'Closed / consumed'::text
                    WHEN p.lab_testing_state = 'TestFailed'::text THEN 'FAILED TESTING'::text
                    WHEN p.lab_testing_state = 'TestPassed'::text THEN 'Passed testing - sellable'::text
                    WHEN p.lab_testing_state = ANY (ARRAY['SubmittedForTesting'::text, 'AwaitingConfirmation'::text]) THEN 'Awaiting laboratory result'::text
                    ELSE 'In inventory'::text
                END AS stage,
            t.manifest_number,
            t.direction,
            t.recipient,
            t.created_on AS transfer_date,
            p.source_state
           FROM metrc_packages p
             LEFT JOIN LATERAL ( SELECT t_1.manifest_number,
                    t_1.direction,
                    t_1.recipient,
                    t_1.created_on
                   FROM metrc_transfers t_1
                  WHERE t_1.license = p.license AND t_1.raw::text ~~ (('%'::text || p.tag) || '%'::text)
                  ORDER BY t_1.created_on DESC
                 LIMIT 1) t ON true) q;
create or replace view public.v_sentinel_coverage as
 SELECT j.jobname,
    true AS firing_watched,
    e.source_key IS NOT NULL AS output_watched,
    e.source_key AS output_probe,
        CASE
            WHEN e.source_key IS NOT NULL THEN 'both - the schedule is watched AND the work it produces is checked'::text
            ELSE 'FIRING ONLY - if this job runs and produces nothing, nothing notices'::text
        END AS guarantee
   FROM cron.job j
     LEFT JOIN sentinel_expectation e ON e.enabled AND j.jobname ~~ (('%'::text || replace(e.source_key, '_'::text, '%'::text)) || '%'::text)
  WHERE j.active
  ORDER BY (e.source_key IS NOT NULL), j.jobname;
create or replace view public.v_sentinel_cron_silence as
 WITH runs AS (
         SELECT d.jobid,
            d.status,
            d.start_time
           FROM cron.job_run_details d
          WHERE d.start_time > (now() - '14 days'::interval)
        ), gaps AS (
         SELECT runs.jobid,
            EXTRACT(epoch FROM runs.start_time - lag(runs.start_time) OVER (PARTITION BY runs.jobid ORDER BY runs.start_time)) AS gap
           FROM runs
          WHERE runs.status = 'succeeded'::text
        ), cadence AS (
         SELECT gaps.jobid,
            percentile_cont(0.5::double precision) WITHIN GROUP (ORDER BY (gaps.gap::double precision)) AS usual_gap
           FROM gaps
          WHERE gaps.gap IS NOT NULL
          GROUP BY gaps.jobid
        ), tally AS (
         SELECT runs.jobid,
            count(*) AS runs_ever,
            count(*) FILTER (WHERE runs.status = 'succeeded'::text) AS ok,
            max(runs.start_time) FILTER (WHERE runs.status = 'succeeded'::text) AS last_success
           FROM runs
          GROUP BY runs.jobid
        )
 SELECT j.jobname,
    j.schedule,
    t.last_success,
    round(EXTRACT(epoch FROM now() - t.last_success) / 60::numeric)::integer AS silent_minutes,
    round(c.usual_gap / 60::double precision)::integer AS usual_gap_minutes,
    split_part(j.schedule, ' '::text, 2) !~ '^([*]|[*]/[0-9]+)$'::text AS runs_only_in_a_window,
        CASE
            WHEN COALESCE(t.runs_ever, 0::bigint) = 0 THEN 'not yet due - scheduled, never reached its first run'::text
            WHEN COALESCE(t.ok, 0::bigint) = 0 THEN 'NEVER SUCCEEDED - it has run and failed every time'::text
            WHEN split_part(j.schedule, ' '::text, 2) !~ '^([*]|[*]/[0-9]+)$'::text THEN 'ok (windowed)'::text
            WHEN c.usual_gap IS NULL THEN 'ok (too few runs to judge)'::text
            WHEN EXTRACT(epoch FROM now() - t.last_success)::double precision > (c.usual_gap * 3::double precision) THEN 'SILENT'::text
            ELSE 'ok'::text
        END AS verdict,
    COALESCE(t.runs_ever, 0::bigint) AS runs_ever
   FROM cron.job j
     LEFT JOIN cadence c ON c.jobid = j.jobid
     LEFT JOIN tally t ON t.jobid = j.jobid
  WHERE j.active
  ORDER BY (
        CASE
            WHEN COALESCE(t.runs_ever, 0::bigint) > 0 AND COALESCE(t.ok, 0::bigint) = 0 THEN 0
            WHEN t.last_success IS NOT NULL AND EXTRACT(epoch FROM now() - t.last_success)::double precision > (COALESCE(c.usual_gap, '1000000000'::numeric::double precision) * 3::double precision) THEN 1
            WHEN COALESCE(t.runs_ever, 0::bigint) = 0 THEN 2
            ELSE 3
        END), j.jobname;
create or replace view public.v_sheet_metrc_reconciliation as
 WITH m AS (
         SELECT s_1.id AS source_id,
            s_1.name AS source_name,
            max(
                CASE
                    WHEN c.role = 'package_tag'::text THEN c.sheet_column
                    ELSE NULL::text
                END) AS col_tag,
            max(
                CASE
                    WHEN c.role = 'quantity'::text THEN c.sheet_column
                    ELSE NULL::text
                END) AS col_qty,
            max(
                CASE
                    WHEN c.role = 'item_name'::text THEN c.sheet_column
                    ELSE NULL::text
                END) AS col_item
           FROM sheet_sources s_1
             LEFT JOIN sheet_column_map c ON c.source_id = s_1.id
          GROUP BY s_1.id, s_1.name
        ), sheet AS (
         SELECT m.source_id,
            m.source_name,
            r.row_number,
            NULLIF(TRIM(BOTH FROM r.data ->> m.col_tag), ''::text) AS package_tag,
            NULLIF(TRIM(BOTH FROM r.data ->> m.col_item), ''::text) AS item_name,
            NULLIF(regexp_replace(COALESCE(r.data ->> m.col_qty, ''::text), '[^0-9.\-]'::text, ''::text, 'g'::text), ''::text)::numeric AS quantity
           FROM m
             JOIN sheet_rows r ON r.source_id = m.source_id
          WHERE m.col_tag IS NOT NULL
        ), metrc AS (
         SELECT p.raw ->> 'Label'::text AS package_tag,
            p.raw ->> 'ProductName'::text AS item_name,
            NULLIF(p.raw ->> 'Quantity'::text, ''::text)::numeric AS quantity,
            p.raw ->> 'UnitOfMeasureName'::text AS unit
           FROM metrc_packages p
          WHERE COALESCE((p.raw ->> 'Quantity'::text)::numeric, 0::numeric) > 0::numeric
        )
 SELECT COALESCE(s.source_name, 'unmapped'::text) AS source_name,
    COALESCE(s.package_tag, mt.package_tag) AS package_tag,
    s.row_number AS sheet_row,
    s.item_name AS sheet_item,
    mt.item_name AS metrc_item,
    s.quantity AS sheet_quantity,
    mt.quantity AS metrc_quantity,
    mt.unit AS metrc_unit,
    round(COALESCE(s.quantity, 0::numeric) - COALESCE(mt.quantity, 0::numeric), 3) AS difference,
        CASE
            WHEN mt.package_tag IS NULL THEN 'IN THE SHEET, NOT IN METRC'::text
            WHEN s.package_tag IS NULL THEN 'IN METRC, NOT IN THE SHEET'::text
            WHEN s.quantity IS NULL THEN 'NO QUANTITY IN THE SHEET'::text
            WHEN abs(s.quantity - mt.quantity) < 0.001 THEN 'AGREES'::text
            ELSE 'QUANTITY DISAGREES'::text
        END AS verdict,
        CASE
            WHEN mt.package_tag IS NULL THEN ((((('Row '::text || s.row_number) || ' of the sheet names package '::text) || s.package_tag) || ' which does not exist in Metrc. Either the tag is mistyped in the sheet, or the '::text) || 'package was never created in Metrc. Metrc is the legal record, so the sheet is wrong '::text) || 'until proven otherwise.'::text
            WHEN s.package_tag IS NULL THEN (((((((('Metrc holds package '::text || mt.package_tag) || ' ('::text) || COALESCE(mt.item_name, 'no product name'::text)) || ', '::text) || COALESCE(mt.quantity::text, 'no quantity'::text)) || ' '::text) || COALESCE(mt.unit, ''::text)) || ') and the sheet does not list it at all. Somebody is working from a sheet that is '::text) || 'missing real stock.'::text
            WHEN s.quantity IS NULL THEN (((((('The sheet lists package '::text || s.package_tag) || ' with no quantity, so it cannot be checked '::text) || 'against the '::text) || COALESCE(mt.quantity::text, 'unknown'::text)) || ' '::text) || COALESCE(mt.unit, ''::text)) || ' Metrc holds.'::text
            WHEN abs(s.quantity - mt.quantity) >= 0.001 THEN ((((((((('Package '::text || s.package_tag) || ': the sheet says '::text) || s.quantity) || ' and Metrc says '::text) || mt.quantity) || ' '::text) || COALESCE(mt.unit, ''::text)) || '. That is a difference of '::text) || round(s.quantity - mt.quantity, 3)) || '. Metrc is the legal record.'::text
            ELSE ('The sheet and Metrc agree on package '::text || s.package_tag) || '.'::text
        END AS what_it_means
   FROM sheet s
     FULL JOIN metrc mt ON mt.package_tag = s.package_tag;
create or replace view public.v_sheet_sync_status as
 SELECT id,
    name,
    sheet_tab,
    description,
    enabled,
    auto_poll,
    poll_minutes,
    google_file_id,
    sheet_gid,
    last_pushed_at,
    last_row_count,
    expected_every_minutes,
    ( SELECT count(*) AS count
           FROM sheet_rows r
          WHERE r.source_id = s.id) AS rows_held,
        CASE
            WHEN google_file_id IS NULL THEN 'Not configured — the sheet''s file identifier has not been set, so the bridge does not know what to read.'::text
            WHEN last_pushed_at IS NULL THEN 'Never received. The bridge has not managed a read yet — it may need signing in to Google once.'::text
            WHEN (now() - last_pushed_at) > ((expected_every_minutes || ' minutes'::text)::interval) THEN ((((('OVERDUE — last received '::text || to_char(last_pushed_at, 'DD Mon YYYY HH24:MI'::text)) || ', which is '::text) || round(EXTRACT(epoch FROM now() - last_pushed_at) / 60::numeric)) || ' minutes ago against an expected '::text) || expected_every_minutes) || ' minutes.'::text
            ELSE ((('Current — last received '::text || to_char(last_pushed_at, 'DD Mon YYYY HH24:MI'::text)) || ', '::text) || round(EXTRACT(epoch FROM now() - last_pushed_at) / 60::numeric)) || ' minutes ago.'::text
        END AS status,
    ( SELECT count(*) AS count
           FROM sheet_push_log l
          WHERE l.source_id = s.id AND NOT l.ok) AS failures
   FROM sheet_sources s
  ORDER BY name;
create or replace view public.v_shipped_full as
 WITH lines AS (
         SELECT t.manifest_number,
            t.package_tag,
            t.item,
            NULLIF(t.strain, ''::text) AS strain_recorded,
            f_strain_from_item(t.item) AS strain_from_item,
            t.category,
            t.shipped_qty,
            t.shipped_uom,
            t.shipped_lb,
            t.shipper_wholesale_price,
            t.destination_facility,
            t.destination_licence,
            t.status,
            t.received_on,
            t.licence AS our_licence,
            f_material_origin(t.package_tag) AS origin
           FROM metrc_rpt_package_transfers t
        )
 SELECT tr.created_on AS shipped_on,
    l.manifest_number,
    tr.direction,
    tr.shipper,
    COALESCE(tr.recipient, l.destination_facility) AS recipient,
    f_facility_type(l.destination_licence) AS recipient_type,
    f_is_transporter(l.destination_licence) AS recipient_is_a_transporter,
    l.package_tag,
    l.item,
    COALESCE(l.strain_recorded, l.strain_from_item) AS strain,
    l.category,
    l.shipped_qty,
    l.shipped_uom,
    round(l.shipped_lb, 2) AS pounds,
    l.shipper_wholesale_price AS value_usd,
        CASE
            WHEN (l.origin ->> 'all_ours'::text)::boolean THEN 'OURS — we grew it'::text
            WHEN (l.origin ->> 'any_outside'::text)::boolean THEN 'THIRD PARTY — '::text || COALESCE((l.origin -> 'origin_names'::text) ->> 0, 'origin not named'::text)
            ELSE 'UNRESOLVED — lineage does not say'::text
        END AS whose_material,
    (l.origin ->> 'all_ours'::text)::boolean AS is_ours,
    l.origin -> 'origin_names'::text AS originator,
    l.origin -> 'origin_licences'::text AS originator_licences,
    l.origin ->> 'item_field_says'::text AS item_field_licence,
    l.origin -> 'inbound_manifests'::text AS came_in_on_manifest,
    l.origin -> 'source_harvests'::text AS source_harvests,
    (l.origin ->> 'lineage_packages'::text)::integer AS lineage_depth,
    d_coa.storage_path AS certificate_link,
        CASE
            WHEN d_coa.storage_path IS NOT NULL THEN 'on file'::text
            WHEN p.lab_testing_state = 'TestPassed'::text THEN 'passed, certificate not yet fetched from Metrc'::text
            WHEN p.lab_testing_state = 'TestFailed'::text THEN 'FAILED testing'::text
            WHEN p.lab_testing_state IS NULL THEN 'no test state recorded'::text
            ELSE p.lab_testing_state
        END AS certificate_says,
    d_man.storage_path AS manifest_link,
        CASE
            WHEN d_man.storage_path IS NOT NULL THEN 'on file'::text
            ELSE 'manifest document not yet fetched'::text
        END AS manifest_document,
        CASE
            WHEN l.strain_recorded IS NOT NULL THEN 'recorded on the manifest'::text
            WHEN l.strain_from_item IS NOT NULL THEN 'READ FROM THE ITEM NAME — not recorded'::text
            ELSE 'not stated anywhere — the item names only a product form'::text
        END AS strain_source,
        CASE
            WHEN l.strain_recorded IS NOT NULL AND l.strain_from_item IS NOT NULL AND lower(replace(l.strain_recorded, '.'::text, ''::text)) <> lower(replace(l.strain_from_item, '.'::text, ''::text)) AND lower(l.strain_recorded) !~~ (('%'::text || lower(l.strain_from_item)) || '%'::text) AND lower(l.strain_from_item) !~~ (('%'::text || lower(l.strain_recorded)) || '%'::text) THEN ('CONFLICT — the item name says "'::text || l.strain_from_item) || '"'::text
            ELSE NULL::text
        END AS strain_conflict
   FROM lines l
     LEFT JOIN metrc_transfers tr ON tr.manifest_number = l.manifest_number
     LEFT JOIN metrc_packages p ON p.tag = l.package_tag
     LEFT JOIN metrc_documents d_coa ON d_coa.package_tag = l.package_tag AND d_coa.doc_type ~~* '%coa%'::text
     LEFT JOIN metrc_documents d_man ON d_man.manifest_number = l.manifest_number AND d_man.doc_type ~~* '%manifest%'::text;
create or replace view public.v_standard_history as
 SELECT h.key,
    c.label,
    h.value,
    h.unit,
    h.set_by,
    h.valid_from::date AS in_force_from,
    h.valid_to::date AS in_force_until,
    h.valid_to IS NULL AS current,
    h.superseded_by,
        CASE
            WHEN h.valid_to IS NULL THEN 'In force now'::text
            ELSE ((('Applied from '::text || to_char(h.valid_from, 'DD Mon YYYY'::text)) || ' to '::text) || to_char(h.valid_to, 'DD Mon YYYY'::text)) || ' — anything judged in that window used this value, not the current one.'::text
        END AS standing
   FROM conversion_factor_history h
     LEFT JOIN conversion_factors c ON c.key = h.key
  ORDER BY h.key, h.valid_from DESC;
create or replace view public.v_stock_on_hand as
 SELECT origin,
    stream,
    license,
    lab_state,
    location,
    supplier,
    origin_license,
    packages,
    grams,
    pounds,
    oldest_days,
    oldest_packaged,
    strains,
    units,
    unit_of_measure,
    sold_by_weight,
    quantity_shown,
    'Not recorded'::text AS stock_status
   FROM ( WITH p AS (
                 SELECT p_1.license,
                    p_1.raw #>> '{Item,StrainName}'::text[] AS strain,
                    p_1.raw ->> 'LabTestingState'::text AS lab_state,
                    COALESCE(p_1.location, '(not recorded)'::text) AS location,
                    p_1.quantity,
                    p_1.raw ->> 'UnitOfMeasureName'::text AS uom,
                    f_is_weight(p_1.raw ->> 'UnitOfMeasureName'::text) AS is_weight,
                    f_to_pounds(p_1.quantity, p_1.raw ->> 'UnitOfMeasureName'::text) AS lb,
                    p_1.packaged_on,
                    p_1.tag,
                    p_1.raw ->> 'ItemFromFacilityLicenseNumber'::text AS origin_license,
                    p_1.raw ->> 'ReceivedFromFacilityName'::text AS received_from,
                    p_1.raw ->> 'ReceivedFromManifestNumber'::text AS manifest,
                        CASE
                            WHEN f_is_ours(p_1.raw ->> 'ItemFromFacilityLicenseNumber'::text) THEN 'Grown by us'::text
                            WHEN COALESCE(p_1.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text) = ''::text THEN 'Origin not recorded'::text
                            ELSE 'Bought in'::text
                        END AS origin,
                        CASE
                            WHEN (p_1.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%fresh frozen%'::text THEN 'Fresh frozen'::text
                            WHEN (p_1.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%bud%'::text THEN 'Dried flower'::text
                            WHEN (p_1.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%shake%'::text OR (p_1.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%trim%'::text THEN 'Shake and trim'::text
                            WHEN (p_1.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%concentrate%'::text THEN 'Concentrate'::text
                            WHEN (p_1.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%roll%'::text THEN 'Pre-rolls'::text
                            WHEN (p_1.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%vape%'::text THEN 'Vape'::text
                            ELSE COALESCE(p_1.raw #>> '{Item,ProductCategoryName}'::text[], '(uncategorised)'::text)
                        END AS stream
                   FROM metrc_packages p_1
                  WHERE COALESCE(p_1.quantity, 0::numeric) > 0::numeric AND COALESCE((p_1.raw ->> 'IsFinished'::text)::boolean, false) = false
                )
         SELECT p.origin,
            p.stream,
            p.license,
            p.lab_state,
            p.location,
            COALESCE(NULLIF(p.received_from, ''::text),
                CASE
                    WHEN p.origin = 'Grown by us'::text THEN 'Twisted Growers'::text
                    ELSE '(supplier not recorded)'::text
                END) AS supplier,
            p.origin_license,
            count(*) AS packages,
            round(sum(p.quantity) FILTER (WHERE lower(p.uom) = ANY (ARRAY['g'::text, 'grams'::text]))) AS grams,
            round(sum(p.lb), 1) AS pounds,
            max(CURRENT_DATE - p.packaged_on) AS oldest_days,
            min(p.packaged_on) AS oldest_packaged,
            count(DISTINCT p.strain) AS strains,
            round(sum(p.quantity) FILTER (WHERE NOT p.is_weight)) AS units,
            string_agg(DISTINCT p.uom, ', '::text) AS unit_of_measure,
            bool_and(p.is_weight) AS sold_by_weight,
                CASE
                    WHEN bool_and(p.is_weight) THEN round(sum(p.lb), 1)::text || ' lb'::text
                    ELSE (round(sum(p.quantity) FILTER (WHERE NOT p.is_weight))::text || ' '::text) || COALESCE(string_agg(DISTINCT p.uom, '/'::text) FILTER (WHERE NOT p.is_weight), 'units'::text)
                END AS quantity_shown
           FROM p
          GROUP BY p.origin, p.stream, p.license, p.lab_state, p.location, (COALESCE(NULLIF(p.received_from, ''::text),
                CASE
                    WHEN p.origin = 'Grown by us'::text THEN 'Twisted Growers'::text
                    ELSE '(supplier not recorded)'::text
                END)), p.origin_license
          ORDER BY (sum(p.quantity)) DESC) q;
create or replace view public.v_stock_packages as
 SELECT p.tag AS package_tag,
    p.item_name,
    p.raw #>> '{Item,StrainName}'::text[] AS strain,
        CASE
            WHEN (p.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%fresh frozen%'::text THEN 'Fresh frozen'::text
            WHEN (p.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%bud%'::text THEN 'Dried flower'::text
            WHEN (p.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%shake%'::text OR (p.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%trim%'::text THEN 'Shake and trim'::text
            WHEN (p.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%concentrate%'::text THEN 'Concentrate'::text
            WHEN (p.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%roll%'::text THEN 'Pre-rolls'::text
            WHEN (p.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%vape%'::text THEN 'Vape'::text
            ELSE COALESCE(p.raw #>> '{Item,ProductCategoryName}'::text[], '(uncategorised)'::text)
        END AS stream,
        CASE
            WHEN f_is_ours(p.raw ->> 'ItemFromFacilityLicenseNumber'::text) THEN 'Grown by us'::text
            ELSE 'Bought in'::text
        END AS origin,
    COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityName'::text, ''::text), 'not recorded'::text) AS made_by,
    COALESCE(NULLIF(p.raw ->> 'ReceivedFromFacilityName'::text, ''::text), '—'::text) AS shipped_to_us_by,
    NULLIF(p.raw ->> 'ReceivedFromManifestNumber'::text, ''::text) AS inbound_manifest,
    p.license,
    p.location,
    p.raw ->> 'LabTestingState'::text AS lab_state,
    round(p.quantity) AS quantity,
    p.uom,
    round(f_to_pounds(p.quantity, p.uom), 3) AS pounds,
    p.packaged_on,
    CURRENT_DATE - p.packaged_on AS days_here,
    NULLIF(p.raw ->> 'SourceHarvestNames'::text, ''::text) AS source_harvest,
    NULLIF(p.raw ->> 'SourcePackageLabels'::text, ''::text) AS made_from_packages,
    NULLIF(p.raw ->> 'SourceProductionBatchNumbers'::text, ''::text) AS production_batch,
    (p.raw ->> 'LabTestingStateDate'::text)::date AS submitted_on,
    (p.raw ->> 'LabTestingRecordedDate'::text)::date AS result_on,
    (p.raw ->> 'LabTestResultExpirationDateTime'::text)::date AS coa_expires,
    h.harvest_start AS harvest_cut_on,
    COALESCE(NULLIF(h.raw ->> 'DryingLocationName'::text, ''::text), '—'::text) AS dried_in,
    (h.raw ->> 'FinishedDate'::text)::date AS harvest_closed_on,
        CASE
            WHEN NULLIF(p.raw ->> 'SourceHarvestNames'::text, ''::text) IS NOT NULL THEN 'Traceable to harvest '::text || (p.raw ->> 'SourceHarvestNames'::text)
            WHEN NULLIF(p.raw ->> 'SourcePackageLabels'::text, ''::text) IS NOT NULL THEN 'Made from package '::text || (p.raw ->> 'SourcePackageLabels'::text)
            WHEN NOT f_is_ours(p.raw ->> 'ItemFromFacilityLicenseNumber'::text) THEN (('BOUGHT IN — no harvest of ours to trace to. Its history sits with '::text || COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityName'::text, ''::text), 'the supplier'::text)) || COALESCE(', arrived on manifest '::text || NULLIF(p.raw ->> 'ReceivedFromManifestNumber'::text, ''::text), ''::text)) || '. Ask them for the certificate and cultivation record.'::text
            ELSE 'NO SOURCE RECORDED in Metrc — neither a harvest nor a parent package. This is a lineage gap and should be corrected.'::text
        END AS traceability,
    f_is_weight(p.uom) AS sold_by_weight,
        CASE
            WHEN NOT f_is_weight(p.uom) THEN round(p.quantity)
            ELSE NULL::numeric
        END AS units,
        CASE
            WHEN f_is_weight(p.uom) THEN round(f_to_pounds(p.quantity, p.uom), 3)::text || ' lb'::text
            ELSE (round(p.quantity)::text || ' '::text) || COALESCE(p.uom, 'units'::text)
        END AS quantity_shown
   FROM metrc_packages p
     LEFT JOIN metrc_harvests h ON h.name = split_part(COALESCE(p.raw ->> 'SourceHarvestNames'::text, ''::text), ','::text, 1)
  WHERE COALESCE(p.quantity, 0::numeric) > 0::numeric AND COALESCE((p.raw ->> 'IsFinished'::text)::boolean, false) = false;
create or replace view public.v_strain_conflicts as
 SELECT manifest_number,
    package_tag,
    item,
    strain AS strain_column_says,
    f_strain_from_item(item) AS item_name_says,
    destination_facility,
    shipped_qty,
    shipper_wholesale_price AS value_usd,
    'The item name and the strain field name different strains. One of them is wrong on a '::text || 'compliance document. Neither can be assumed correct — check Metrc.'::text AS what_is_wrong
   FROM metrc_rpt_package_transfers t
  WHERE strain IS NOT NULL AND strain <> ''::text AND f_strain_from_item(item) IS NOT NULL AND lower(replace(strain, '.'::text, ''::text)) <> lower(replace(f_strain_from_item(item), '.'::text, ''::text)) AND lower(strain) !~~ (('%'::text || lower(f_strain_from_item(item))) || '%'::text) AND lower(f_strain_from_item(item)) !~~ (('%'::text || lower(strain)) || '%'::text);
create or replace view public.v_strain_performance as
 WITH h AS (
         SELECT COALESCE(NULLIF(metrc_harvests.raw ->> 'SourceStrainNames'::text, ''::text), '(not recorded)'::text) AS strain,
            (metrc_harvests.raw ->> 'PlantCount'::text)::integer AS plants,
            ((metrc_harvests.raw ->> 'TotalPackagedWeight'::text)::numeric) / 453.592 AS packaged_lb,
            metrc_harvests.wet_weight / 453.592 AS wet_lb,
            metrc_harvests.harvest_start AS cut
           FROM metrc_harvests
          WHERE metrc_harvests.wet_weight > 0::numeric AND (metrc_harvests.raw ->> 'FinishedDate'::text) IS NOT NULL AND NOT (metrc_harvests.name ~~* '%FF%'::text OR COALESCE(metrc_harvests.raw ->> 'DryingLocationName'::text, ''::text) ~~* '%freezer%'::text)
        ), m AS (
         SELECT h.strain,
            count(*) AS harvests,
            sum(h.plants) AS plants,
            round(sum(h.packaged_lb), 1) AS packaged_lb,
            round(sum(h.packaged_lb) * 453.592 / NULLIF(sum(h.plants), 0)::numeric, 1) AS grams_per_plant,
            round(100::numeric * sum(h.packaged_lb) / NULLIF(sum(h.wet_lb), 0::numeric), 1) AS conversion_pct,
            min(h.cut) AS first_grown,
            max(h.cut) AS last_grown
           FROM h
          WHERE h.plants > 0
          GROUP BY h.strain
        )
 SELECT m.strain,
    m.harvests,
    m.plants,
    m.packaged_lb,
    m.grams_per_plant,
    m.conversion_pct,
    m.first_grown,
    m.last_grown,
    round(m.grams_per_plant * 1140::numeric / 453.592, 1) AS lb_from_a_large_room,
    round(m.grams_per_plant * 1050::numeric / 453.592, 1) AS lb_from_a_small_room,
    round(m.grams_per_plant * 1140::numeric / 453.592 - f_rule_at('harvest_goal_lb'::text), 1) AS large_room_vs_goal,
        CASE
            WHEN m.harvests >= 8 THEN 'proven'::text
            WHEN m.harvests >= 4 THEN 'indicative'::text
            ELSE 'UNPROVEN — too few harvests to judge'::text
        END AS confidence,
    GREATEST(1, LEAST(10, round(m.grams_per_plant / (f_rule_at('grams_per_plant_for_contract'::text) / 5.0))::integer)) AS yield_score,
    m.grams_per_plant >= f_rule_at('grams_per_plant_for_contract'::text) AS meets_contract_yield,
        CASE
            WHEN m.last_grown < (CURRENT_DATE - 365) THEN 'not grown in over a year'::text
            WHEN m.last_grown < (CURRENT_DATE - 180) THEN 'not grown in six months'::text
            ELSE 'in rotation'::text
        END AS currency,
    COALESCE(s.status, 'unreviewed'::text) AS status,
    s.manual_score,
    s.sells_well,
    s.notes,
    s.max_plants_per_year,
    s.decided_by,
    s.decided_on,
    COALESCE(s.manual_score, GREATEST(1, LEAST(10, round(m.grams_per_plant / (f_rule_at('grams_per_plant_for_contract'::text) / 5.0))::integer))) AS ranking_score
   FROM m
     LEFT JOIN strain_scorecard s ON s.strain = m.strain
  WHERE m.plants >= 100;
create or replace view public.v_supplier_costs as
 SELECT material_type,
    supplier,
    purchases,
    total_qty,
    avg_landed_cost_per_uom,
    best_landed_cost_per_uom,
    last_purchase,
    cost_rank,
    payment_terms,
    terms_days,
    approved,
    last_purchase AS last_purchase_date
   FROM ( WITH buys AS (
                 SELECT material_purchases.supplier,
                    material_purchases.material_type,
                    count(*) AS purchases,
                    sum(material_purchases.purchased_qty) AS total_qty,
                    round(avg((COALESCE(material_purchases.purchased_qty, 0::numeric) * COALESCE(material_purchases.unit_cost, 0::numeric) + COALESCE(material_purchases.freight, 0::numeric) + COALESCE(material_purchases.other_landed_cost, 0::numeric)) / NULLIF(material_purchases.purchased_qty, 0::numeric)), 4) AS avg_landed_cost_per_uom,
                    round(min((COALESCE(material_purchases.purchased_qty, 0::numeric) * COALESCE(material_purchases.unit_cost, 0::numeric) + COALESCE(material_purchases.freight, 0::numeric) + COALESCE(material_purchases.other_landed_cost, 0::numeric)) / NULLIF(material_purchases.purchased_qty, 0::numeric)), 4) AS best_landed_cost_per_uom,
                    max(material_purchases.purchase_date) AS last_purchase
                   FROM material_purchases
                  WHERE material_purchases.purchased_qty > 0::numeric
                  GROUP BY material_purchases.supplier, material_purchases.material_type
                )
         SELECT b.material_type,
            b.supplier,
            b.purchases,
            b.total_qty,
            b.avg_landed_cost_per_uom,
            b.best_landed_cost_per_uom,
            b.last_purchase,
                CASE
                    WHEN b.avg_landed_cost_per_uom = min(b.avg_landed_cost_per_uom) OVER (PARTITION BY b.material_type) THEN 'BEST COST'::text
                    ELSE NULL::text
                END AS cost_rank,
            v.payment_terms,
            v.terms_days,
            v.approved
           FROM buys b
             LEFT JOIN vendors v ON lower(v.name) = lower(b.supplier)
          ORDER BY b.material_type, b.avg_landed_cost_per_uom) q;
create or replace view public.v_sync_digest as
 SELECT (started_at AT TIME ZONE 'America/New_York'::text)::date AS day,
    endpoint,
    license AS licence,
    count(*) AS attempts,
    count(*) FILTER (WHERE status = 'ok'::text) AS completed,
    count(*) FILTER (WHERE status = 'error'::text) AS failed,
    count(*) FILTER (WHERE status = 'running'::text) AS still_running,
    count(*) FILTER (WHERE status = 'ok'::text AND COALESCE(records, 0) = 0) AS completed_but_empty,
    sum(records) FILTER (WHERE status = 'ok'::text) AS records_in,
    round(100.0 * count(*) FILTER (WHERE status = 'error'::text)::numeric / NULLIF(count(*), 0)::numeric, 1) AS pct_failed,
    max("left"(error, 120)) FILTER (WHERE status = 'error'::text) AS last_error
   FROM metrc_sync_runs
  WHERE system = 'metrc'::text
  GROUP BY ((started_at AT TIME ZONE 'America/New_York'::text)::date), endpoint, license;
create or replace view public.v_sync_report as
 WITH named AS (
         SELECT r.id,
            r.endpoint,
            r.license,
            r.started_at,
            r.finished_at,
            r.status,
            r.records,
            r.error,
                CASE
                    WHEN r.endpoint ~~* 'transfers%'::text THEN 'Manifests sync'::text
                    WHEN r.endpoint ~~* 'packages%'::text THEN 'Packages sync'::text
                    WHEN r.endpoint ~~* 'harvests%'::text OR r.endpoint ~~* 'plants%'::text OR r.endpoint ~~* 'plantbatches%'::text THEN 'Cultivation sync'::text
                    WHEN r.endpoint = ANY (ARRAY['items'::text, 'strains'::text, 'locations'::text]) THEN 'Reference data sync'::text
                    WHEN r.endpoint ~~* 'sales%'::text THEN 'Sales sync'::text
                    WHEN r.endpoint ~~* 'lab%'::text THEN 'Lab results sync'::text
                    WHEN r.endpoint ~~* 'documents%'::text THEN 'Document fetch'::text
                    WHEN r.endpoint ~~* 'google_sheet%'::text THEN 'Google Sheet sync'::text
                    WHEN r.endpoint ~~* 'clickup%'::text THEN 'ClickUp sync'::text
                    ELSE r.endpoint
                END AS agent
           FROM metrc_sync_runs r
          WHERE r.system = 'metrc'::text
        )
 SELECT id AS run_id,
    endpoint,
    agent,
    license AS licence,
    (started_at AT TIME ZONE 'America/New_York'::text) AS started_local,
    (finished_at AT TIME ZONE 'America/New_York'::text) AS finished_local,
    round(EXTRACT(epoch FROM finished_at - started_at))::integer AS seconds,
    status,
    records,
        CASE
            WHEN status = 'ok'::text AND COALESCE(records, 0) > 0 THEN ('Completed — '::text || records) || ' records'::text
            WHEN status = 'ok'::text AND COALESCE(records, 0) = 0 THEN 'Completed but brought back NOTHING — check whether that is correct'::text
            WHEN status = 'running'::text AND started_at < (now() - '01:00:00'::interval) THEN 'STUCK — started over an hour ago and never finished'::text
            WHEN status = 'running'::text THEN 'Running'::text
            WHEN error ~~* '%401%'::text THEN 'FAILED — Metrc refused the credentials (401) for licence '::text || COALESCE(license, '?'::text)
            WHEN error ~~* '%400%'::text THEN 'FAILED — Metrc rejected the request (400). Usually a bad date range or page size.'::text
            WHEN error ~~* '%unique or exclusion%'::text THEN 'FAILED — our own database rejected the rows (missing unique constraint)'::text
            WHEN error ~~* '%timeout%'::text OR error ~~* '%timed out%'::text THEN 'FAILED — timed out'::text
            ELSE 'FAILED — '::text || "left"(COALESCE(error, 'no reason recorded'::text), 90)
        END AS what_happened,
    error AS full_error,
    status = 'ok'::text AND COALESCE(records, 0) = 0 AS completed_empty,
        CASE
            WHEN license = 'MC281714'::text THEN 'Cultivation'::text
            WHEN license = 'MP281909'::text THEN 'Manufacturing'::text
            WHEN license = 'both'::text THEN 'Both licences'::text
            WHEN license = '-'::text THEN 'Not licence-specific'::text
            ELSE 'UNRECOGNISED LICENCE — '::text || COALESCE(license, 'null'::text)
        END AS licence_name
   FROM named;
create or replace view public.v_task_timeline as
 SELECT t.id AS task_id,
    t.title,
    t.status,
    t.priority,
    t.space_id,
    t.team_id,
    t.assignee_employee_id,
    t.start_on,
    t.due_on,
        CASE
            WHEN t.start_on IS NOT NULL AND t.due_on IS NOT NULL THEN t.due_on - t.start_on
            ELSE NULL::integer
        END AS duration_days,
    COALESCE(p.predecessor_count, 0::bigint) AS predecessor_count,
    p.predecessor_names,
    p.blocking_predecessor_names,
        CASE
            WHEN p.unfinished_count > 0 THEN 'BLOCKED - predecessor not finished'::text
            WHEN p.conflict_count > 0 THEN 'SCHEDULE CONFLICT - starts before predecessor finishes'::text
            ELSE NULL::text
        END AS warning,
    t.created_at,
    t.updated_at
   FROM tasks t
     LEFT JOIN LATERAL ( SELECT count(*) AS predecessor_count,
            count(*) FILTER (WHERE pred.status IS DISTINCT FROM 'done'::text) AS unfinished_count,
            count(*) FILTER (WHERE t.start_on IS NOT NULL AND pred.due_on IS NOT NULL AND t.start_on < pred.due_on) AS conflict_count,
            string_agg(pred.title, ', '::text ORDER BY pred.title) AS predecessor_names,
            string_agg(pred.title, ', '::text ORDER BY pred.title) FILTER (WHERE pred.status IS DISTINCT FROM 'done'::text) AS blocking_predecessor_names
           FROM task_dependencies d
             JOIN tasks pred ON pred.id = d.depends_on_id
          WHERE d.task_id = t.id) p ON true;
create or replace view public.v_task_workload as
 SELECT e.id AS employee_id,
    e.full_name AS employee_name,
    t.due_on AS due_date,
    count(*) AS tasks_due,
    count(*) FILTER (WHERE t.priority = ANY (ARRAY['P0'::text, 'P1'::text])) AS high_priority_tasks,
        CASE
            WHEN count(*) > 5 THEN 'OVERLOADED'::text
            WHEN count(*) >= 4 THEN 'HEAVY'::text
            ELSE 'Normal'::text
        END AS workload_status
   FROM tasks t
     JOIN employees e ON e.id = t.assignee_employee_id
  WHERE t.status IS DISTINCT FROM 'done'::text AND t.due_on IS NOT NULL
  GROUP BY e.id, e.full_name, t.due_on
  ORDER BY e.full_name, t.due_on;
create or replace view public.v_testing_sla_matrix as
 SELECT COALESCE(s.rule_code, '—'::text) AS rule_id,
    COALESCE(s.product_family, pf.name, '—'::text) AS product_family,
    s.batch_size_min AS minimum_batch_size,
    s.batch_size_max AS maximum_batch_size,
    s.test_type,
    s.sample_qty AS sample_quantity,
    s.sample_prep_hours,
    s.laboratory,
    s.lead_days AS lab_lead_days,
        CASE
            WHEN s.active THEN 'Yes'::text
            ELSE 'No'::text
        END AS active
   FROM testing_slas s
     LEFT JOIN product_families pf ON pf.id = s.product_family_id
  ORDER BY s.product_family, s.batch_size_min;
create or replace view public.v_third_party_chain as
 WITH inc AS (
         SELECT p.tag,
            p.item_name,
            p.license AS held_under,
            p.location,
            p.quantity,
            p.uom,
            p.packaged_on,
            p.raw ->> 'ItemFromFacilityLicenseNumber'::text AS origin_license,
            COALESCE(NULLIF(p.raw ->> 'ReceivedFromFacilityName'::text, ''::text), '(supplier not recorded)'::text) AS supplier,
            p.raw ->> 'ReceivedFromManifestNumber'::text AS inbound_manifest,
            (p.raw ->> 'ReceivedDateTime'::text)::date AS received_on,
            (p.raw ->> 'ReceivedQuantity'::text)::numeric AS received_qty,
            (p.raw ->> 'CreatedQuantity'::text)::numeric AS created_qty,
            p.raw ->> 'LabTestingState'::text AS lab_state,
            (p.raw ->> 'LabTestingStateDate'::text)::date AS lab_state_on,
            p.raw #>> '{Item,ProductCategoryName}'::text[] AS category,
            p.raw #>> '{Item,StrainName}'::text[] AS strain,
            p.raw ->> 'SourcePackageLabels'::text AS made_from,
            p.raw ->> 'SourceProductionBatchNumbers'::text AS production_batch,
            (p.raw ->> 'IsFinished'::text)::boolean AS finished
           FROM metrc_packages p
          WHERE (COALESCE(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text) <> ALL (ARRAY['MC281714'::text, 'MP281909'::text])) AND COALESCE(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text) <> ''::text
        )
 SELECT supplier,
    origin_license,
    inbound_manifest,
    received_on,
    tag,
    item_name,
    strain,
    category,
    held_under,
    location,
    received_qty,
    quantity AS remaining_qty,
    uom,
    round(COALESCE(received_qty, 0::numeric) - COALESCE(quantity, 0::numeric)) AS consumed_qty,
        CASE
            WHEN COALESCE(received_qty, 0::numeric) > 0::numeric THEN round(100::numeric * (COALESCE(received_qty, 0::numeric) - COALESCE(quantity, 0::numeric)) / received_qty, 1)
            ELSE NULL::numeric
        END AS pct_consumed,
    lab_state,
    lab_state_on,
    production_batch,
    made_from,
    finished,
    CURRENT_DATE - received_on AS days_since_received,
        CASE
            WHEN quantity = 0::numeric AND finished THEN 'FULLY USED - consumed into product or sold'::text
            WHEN quantity = 0::numeric THEN 'Drawn to zero but not marked finished'::text
            WHEN COALESCE(received_qty, 0::numeric) = COALESCE(quantity, 0::numeric) THEN 'UNTOUCHED - nothing drawn from it yet'::text
            ELSE ('PARTLY USED - '::text || round(100::numeric * (COALESCE(received_qty, 0::numeric) - COALESCE(quantity, 0::numeric)) / NULLIF(received_qty, 0::numeric), 1)) || ' percent drawn'::text
        END AS "position",
        CASE
            WHEN lab_state = 'TestFailed'::text THEN ('FAILED TESTING - recover from '::text || supplier) || ' before writing anything off'::text
            WHEN quantity > 0::numeric AND (CURRENT_DATE - received_on) > 90 THEN ('SITTING '::text || (CURRENT_DATE - received_on)) || ' DAYS - purchased material tying up cash'::text
            WHEN lab_state = 'NotSubmitted'::text AND quantity > 0::numeric THEN 'NEVER SUBMITTED FOR TESTING'::text
            ELSE 'Normal'::text
        END AS flag
   FROM inc
  ORDER BY received_on DESC NULLS LAST, supplier;
create or replace view public.v_trap_scan as
 WITH objs AS (
         SELECT c.relname AS object_name,
            pg_get_viewdef(c.oid, true) AS def,
            'view'::text AS kind
           FROM pg_class c
             JOIN pg_namespace n ON n.oid = c.relnamespace
          WHERE n.nspname = 'public'::name AND (c.relkind = ANY (ARRAY['v'::"char", 'm'::"char"])) AND c.relname <> 'v_trap_scan'::name
        UNION ALL
         SELECT p.proname,
            p.prosrc,
            'function'::text
           FROM pg_proc p
             JOIN pg_namespace n ON n.oid = p.pronamespace
          WHERE n.nspname = 'public'::name AND p.prokind = 'f'::"char" AND (p.proname <> ALL (ARRAY['f_quantity_text'::name, 'f_any_ours'::name, 'f_all_ours'::name, 'f_licence_in_set'::name]))
        )
 SELECT objs.object_name,
    'countable-items-dropped'::text AS trap,
    'critical'::text AS severity,
    'Converts to pounds under f_is_weight but never reports the count, so every countable item publishes as nothing and any total excludes it silently.'::text AS what_is_wrong,
    'Add a units column and use f_quantity_text(qty, uom). Cross-check v_countable_inventory.'::text AS what_to_do,
    objs.kind
   FROM objs
  WHERE objs.def ~* 'f_is_weight'::text AND objs.def ~* 'f_to_pounds'::text AND objs.def !~* '(f_quantity_text|as +[a-z_]*units|unit_of_measure)'::text
UNION ALL
 SELECT objs.object_name,
    'licence-list-vs-single-test'::text AS trap,
    'critical'::text AS severity,
    'Applies f_is_ours() to a certificate licence field. That field can hold "MC281714, MP281909" and f_is_ours returns FALSE on a list - it matches neither member and never errors. 621 of 983 certificates are stored that way.'::text AS what_is_wrong,
    'Use f_any_ours() / f_all_ours(), or f_licence_in_set() for membership.'::text AS what_to_do,
    objs.kind
   FROM objs
  WHERE objs.def ~ 'f_is_ours\s*\(\s*[a-z_.]*(client_license|cert_license)'::text
UNION ALL
 SELECT objs.object_name,
    'substring-match-on-licence'::text AS trap,
    'elevated'::text AS severity,
    'Uses position()/LIKE against a licence number. A substring test matches quietly - it will not error, it will answer a slightly different question.'::text AS what_is_wrong,
    'Use f_licence_in_set() for exact membership after splitting on commas.'::text AS what_to_do,
    objs.kind
   FROM objs
  WHERE objs.def ~* 'position\s*\(\s*[("'']*\s*[a-z_.]*licen'::text OR objs.def ~* 'licen[a-z_]*\s+i?like\s+''%'::text
UNION ALL
 SELECT objs.object_name,
    'wet-and-dry-mixed'::text AS trap,
    'critical'::text AS severity,
    'Sums a weight in an object that touches fresh frozen with NO stream, basis or wet/dry separation anywhere in it. Fresh frozen is WET: 603.9 lb wet is 134.2 lb dry-equivalent at the configured 4.5.'::text AS what_is_wrong,
    'Separate the basis, or divide fresh frozen by f_rule(''fresh_frozen_wet_to_dry''). Name the column so the basis cannot be lost.'::text AS what_to_do,
    objs.kind
   FROM objs
  WHERE objs.def ~* 'fresh.?frozen'::text AND objs.def ~* 'sum\s*\('::text AND objs.def !~* '(wet|dry|_equiv|stream|basis|fresh_frozen_lbs|fresh_frozen_wet_to_dry)'::text
UNION ALL
 SELECT objs.object_name,
    'estimate-used-as-count'::text AS trap,
    'critical'::text AS severity,
    'Reads reltuples, a planner ESTIMATE that returns 0 on small or freshly written tables. Five populated tables were reported empty this way.'::text AS what_is_wrong,
    'Use select count(*).'::text AS what_to_do,
    objs.kind
   FROM objs
  WHERE objs.def ~* 'reltuples'::text
UNION ALL
 SELECT objs.object_name,
    'ordering-decides-evidence'::text AS trap,
    'critical'::text AS severity,
    'Uses row_number()/distinct on to pick ONE row from conflicting sources. If those rows disagree on substance the ORDER BY is making the judgement, not the evidence, and it will never say so. On 7 Aug an ordering decided 142 of 191 ownership verdicts - reversing one word moved the answer from 19 packages to 156.'::text AS what_is_wrong,
    'State the reason in the object, and surface the disagreement in a companion view rather than resolving it silently. Disagreement is the finding.'::text AS what_to_do,
    objs.kind
   FROM objs
  WHERE (objs.def ~* 'row_number\s*\(\s*\)\s*over'::text OR objs.def ~* 'distinct\s+on'::text) AND objs.def ~* '(cert|origin|licen|owner|depth|priority)'::text
UNION ALL
 SELECT objs.object_name,
    'transporter-in-revenue'::text AS trap,
    'critical'::text AS severity,
    'Computes revenue or a price without excluding transporter/storage destinations. An MT or MX licence destination is NEVER a sale - material goes to storage and comes back. $901,430 was booked as revenue this way.'::text AS what_is_wrong,
    'Exclude MT/MX destinations, and label every Metrc-derived price a DECLARED transfer price - Apex is the sales source of record.'::text AS what_to_do,
    objs.kind
   FROM objs
  WHERE objs.def ~* '(revenue|sale_price|realised|realized|price_per|total_price)'::text AND objs.def ~* 'sum\s*\('::text AND objs.def !~* '(MT[0-9]|MX[0-9]|transporter|destination_kind)'::text
UNION ALL
 SELECT objs.object_name,
    'truncated-tag'::text AS trap,
    'elevated'::text AS severity,
    'Joins or stores a Metrc tag without requiring the full 24 characters. Truncated tags have already collided - "3136" matches one of OUR packages and an outside one.'::text AS what_is_wrong,
    'Resolve full 24-character tags before any join, and reject an ambiguous match rather than storing it.'::text AS what_to_do,
    objs.kind
   FROM objs
  WHERE objs.def ~* '(right|substr|substring)\s*\(\s*[a-z_.]*(tag|label)'::text
UNION ALL
 SELECT objs.object_name,
    'count-star-on-aggregate'::text AS trap,
    'elevated'::text AS severity,
    'Uses count(*) against a view that is already aggregated, which returns the number of GROUPS, not the number of packages.'::text AS what_is_wrong,
    'Use sum(packages), or count the base rows.'::text AS what_to_do,
    objs.kind
   FROM objs
  WHERE objs.def ~* 'count\s*\(\s*\*\s*\)'::text AND objs.def ~* 'from\s+v_[a-z_]*(summary|by_|totals|position)'::text
UNION ALL
 SELECT objs.object_name,
    'repack-as-primary'::text AS trap,
    'elevated'::text AS severity,
    'Counts production or yield without excluding repackaged material. A repack keeps the original harvest name; counting it inflates production by up to 142%.'::text AS what_is_wrong,
    'Primary production is SourcePackageCount = 0. Filter on it explicitly.'::text AS what_to_do,
    objs.kind
   FROM objs
  WHERE objs.def ~* '(production|yield|harvested|packaged_lb)'::text AND objs.def ~* 'sum\s*\('::text AND objs.def ~* 'sourceharvestnames'::text AND objs.def !~* 'sourcepackagecount'::text
UNION ALL
 SELECT o.object_name,
    'no-registered-proof'::text AS trap,
    'elevated'::text AS severity,
    'Publishes findings to people but no brain_claims row names it in covers_object with a proof that reaches the figure independently. A rule with no check expires.'::text AS what_is_wrong,
    'Register a claim with covers_object set to this object and a proof_sql that derives the number from BASE TABLES. A proof that selects from the view it checks cannot fail and proves nothing.'::text AS what_to_do,
    o.kind
   FROM objs o
  WHERE o.def ~* 'what_is_wrong'::text AND o.kind = 'view'::text AND NOT (EXISTS ( SELECT 1
           FROM brain_claims b
          WHERE b.covers_object = o.object_name AND b.proof_sql !~* ('from\s+'::text || o.object_name::text)));
create or replace view public.v_true_cost_per_pound as
 SELECT to_char(harvest_start::timestamp with time zone, 'YYYY-MM'::text) AS month,
    date_trunc('month'::text, harvest_start::timestamp with time zone)::date AS month_date,
    count(*)::numeric AS harvests,
    sum(COALESCE((raw ->> 'PlantCount'::text)::numeric, 0::numeric)) AS plants_harvested,
    round(sum(COALESCE((raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) / 453.592, 1) AS wet_lbs,
    round(sum(COALESCE((raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric)) / 453.592, 1) AS saleable_lbs,
        CASE
            WHEN sum(COALESCE((raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)) > 0::numeric THEN round(100.0 * sum(COALESCE((raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric)) / sum(COALESCE((raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)), 1)
            ELSE NULL::numeric
        END AS wet_to_saleable_pct,
    ( SELECT cost_model.cost_per_pound
           FROM cost_model
          WHERE cost_model.scope = 'cultivation'::text
          ORDER BY cost_model.effective_from DESC
         LIMIT 1) AS target_cost_per_pound,
    round(sum(COALESCE((raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric)) / 453.592 * (( SELECT cost_model.cost_per_pound
           FROM cost_model
          WHERE cost_model.scope = 'cultivation'::text
          ORDER BY cost_model.effective_from DESC
         LIMIT 1)), 0) AS period_cost_at_target,
        CASE
            WHEN sum(COALESCE((raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric)) > 0::numeric THEN round(sum(COALESCE((raw ->> 'PlantCount'::text)::numeric, 0::numeric)) / (sum(COALESCE((raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric)) / 453.592), 1)
            ELSE NULL::numeric
        END AS plants_per_saleable_pound,
        CASE
            WHEN sum(COALESCE((raw ->> 'PlantCount'::text)::numeric, 0::numeric)) > 0::numeric THEN round(sum(COALESCE((raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric)) / 453.592 / sum(COALESCE((raw ->> 'PlantCount'::text)::numeric, 0::numeric)) * 453.592, 1)
            ELSE NULL::numeric
        END AS grams_per_plant
   FROM metrc_harvests h
  WHERE harvest_start IS NOT NULL
  GROUP BY (to_char(harvest_start::timestamp with time zone, 'YYYY-MM'::text)), (date_trunc('month'::text, harvest_start::timestamp with time zone))
  ORDER BY (date_trunc('month'::text, harvest_start::timestamp with time zone)::date) DESC;
create or replace view public.v_truncate_exposure as
 SELECT table_name,
    string_agg(DISTINCT grantee::text, ', '::text ORDER BY (grantee::text)) AS browser_facing_roles,
    (EXISTS ( SELECT 1
           FROM pg_trigger t
             JOIN pg_class c ON c.oid = t.tgrelid
             JOIN pg_namespace n ON n.oid = c.relnamespace
          WHERE n.nspname = 'public'::name AND c.relname = g.table_name::name AND NOT t.tgisinternal)) AS has_a_trigger_truncate_would_bypass
   FROM information_schema.role_table_grants g
  WHERE table_schema::name = 'public'::name AND privilege_type::text = 'TRUNCATE'::text AND (grantee::name = ANY (ARRAY['anon'::name, 'authenticated'::name, 'PUBLIC'::name]))
  GROUP BY table_name
  ORDER BY ((EXISTS ( SELECT 1
           FROM pg_trigger t
             JOIN pg_class c ON c.oid = t.tgrelid
             JOIN pg_namespace n ON n.oid = c.relnamespace
          WHERE n.nspname = 'public'::name AND c.relname = g.table_name::name AND NOT t.tgisinternal))) DESC, table_name;
create or replace view public.v_turnaround_watch as
 SELECT id,
    pipeline,
    brand,
    sku,
    category,
    material_name,
    source_kind,
    started,
    days_open,
    policy_max_days,
    policy_scope,
    turnaround_violation,
    no_policy_set,
    started AS started_date
   FROM ( SELECT r.id,
            p.name AS pipeline,
            r.brand,
            r.sku,
            r.category,
            r.material_name,
            r.source_kind,
            r.started_at::date AS started,
            round(EXTRACT(epoch FROM now() - r.started_at) / 86400::numeric, 1) AS days_open,
            pol.max_days AS policy_max_days,
            pol.scope AS policy_scope,
            pol.max_days IS NOT NULL AND (EXTRACT(epoch FROM now() - r.started_at) / 86400::numeric) > pol.max_days AS turnaround_violation,
            pol.max_days IS NULL AS no_policy_set
           FROM pipeline_runs r
             JOIN pipelines p ON p.id = r.pipeline_id
             LEFT JOIN LATERAL ( SELECT tp.max_days,
                    tp.scope
                   FROM turnaround_policies tp
                  WHERE tp.active AND (tp.applies_to = 'any'::text OR tp.applies_to = r.source_kind) AND (tp.scope = 'sku'::text AND tp.scope_value = r.sku OR tp.scope = 'item'::text AND tp.scope_value = r.material_name OR tp.scope = 'brand'::text AND tp.scope_value = r.brand OR tp.scope = 'category'::text AND tp.scope_value = r.category OR tp.scope = 'default'::text)
                  ORDER BY (
                        CASE tp.scope
                            WHEN 'sku'::text THEN 1
                            WHEN 'item'::text THEN 2
                            WHEN 'brand'::text THEN 3
                            WHEN 'category'::text THEN 4
                            ELSE 5
                        END)
                 LIMIT 1) pol ON true
          WHERE r.completed_at IS NULL
          ORDER BY (round(EXTRACT(epoch FROM now() - r.started_at) / 86400::numeric, 1)) DESC) q;
create or replace view public.v_unchallenged_findings as
 SELECT id,
    fingerprint,
    severity,
    what,
    the_arithmetic,
    record_count,
    who_is_accountable,
    'Nobody has attempted to refute this. Per brain/INDEX.md the Challenger defaults to REFUTED and makes a claim earn survival - an unchallenged finding has not earned anything yet.'::text AS why_it_matters
   FROM watchdog_findings f
  WHERE challenge_verdict IS NULL
  ORDER BY (
        CASE severity
            WHEN 'critical'::text THEN 1
            WHEN 'elevated'::text THEN 2
            ELSE 3
        END), record_count DESC NULLS LAST;
create or replace view public.v_under_utilised as
 WITH pol AS (
         SELECT attendance_policy.full_time_min_hours,
            attendance_policy.ot_weekly_threshold,
            attendance_policy.shortfall_tolerance_hours
           FROM attendance_policy
         LIMIT 1
        ), wk AS (
         SELECT t.employee_id,
            date_trunc('week'::text, t.work_date::timestamp with time zone)::date AS week_start,
            sum(EXTRACT(epoch FROM t.clock_out - t.clock_in) / 3600.0 - COALESCE(t.unpaid_lunch_min, 0)::numeric / 60.0) AS worked_hours
           FROM time_entries t
          WHERE t.clock_in IS NOT NULL AND t.clock_out IS NOT NULL
          GROUP BY t.employee_id, (date_trunc('week'::text, t.work_date::timestamp with time zone)::date)
        )
 SELECT e.id AS employee_id,
    e.employee_code,
    e.full_name,
    d.name AS department,
    wk.week_start,
    COALESCE(e.weekly_target_hours, pol.ot_weekly_threshold)::numeric AS target_hours,
    round(wk.worked_hours, 2) AS worked_hours,
    round(COALESCE(e.weekly_target_hours, pol.ot_weekly_threshold) - wk.worked_hours, 2) AS short_hours,
    round(100.0 * wk.worked_hours / NULLIF(COALESCE(e.weekly_target_hours, pol.ot_weekly_threshold), 0::numeric), 1) AS utilisation_pct,
        CASE
            WHEN e.hours_basis = 'weekly_minimum'::text THEN round((COALESCE(e.weekly_target_hours, 0::numeric) - wk.worked_hours) * r.rate * (1::numeric + COALESCE(r.burden_pct, 0::numeric)), 2)
            ELSE NULL::numeric
        END AS paid_for_unworked_loaded,
    e.hours_basis,
        CASE
            WHEN e.hours_basis = 'weekly_minimum'::text THEN 'below contracted minimum'::text
            ELSE 'below target'::text
        END AS shortfall_kind
   FROM wk
     CROSS JOIN pol
     JOIN employees e ON e.id = wk.employee_id
     LEFT JOIN departments d ON d.id = e.primary_department_id
     LEFT JOIN LATERAL ( SELECT r2.id,
            r2.employee_id,
            r2.basis,
            r2.rate,
            r2.ot_multiplier,
            r2.burden_pct,
            r2.effective_from,
            r2.effective_to,
            r2.approved_by,
            r2.note,
            r2.effective_from_date
           FROM employee_rates r2
          WHERE r2.employee_id = e.id AND r2.effective_from <= wk.week_start AND (r2.effective_to IS NULL OR r2.effective_to >= wk.week_start)
          ORDER BY r2.effective_from DESC
         LIMIT 1) r ON true
  WHERE COALESCE(e.weekly_target_hours, pol.ot_weekly_threshold) >= pol.full_time_min_hours AND wk.worked_hours < (COALESCE(e.weekly_target_hours, pol.ot_weekly_threshold) - pol.shortfall_tolerance_hours);
create or replace view public.v_unresolved_register as
 SELECT id,
    agent,
    headline,
    detail,
    action,
    drill_to,
    fingerprint,
    detected_at::date AS first_raised,
    CURRENT_DATE - detected_at::date AS days_open,
    severity AS raised_as,
        CASE
            WHEN severity = 'critical'::text AND (CURRENT_DATE - detected_at::date) >= 3 THEN 'critical'::text
            WHEN (CURRENT_DATE - detected_at::date) >= 30 THEN 'critical'::text
            WHEN (CURRENT_DATE - detected_at::date) >= 14 THEN 'elevated'::text
            WHEN severity = 'critical'::text THEN 'critical'::text
            ELSE severity
        END AS severity_now,
        CASE
            WHEN (CURRENT_DATE - detected_at::date) = 0 THEN 'Raised today.'::text
            WHEN (CURRENT_DATE - detected_at::date) >= 30 THEN (('Open '::text || (CURRENT_DATE - detected_at::date)) || ' days. This has been asked every day '::text) || 'for a month and is now treated as critical whatever it was raised as.'::text
            WHEN (CURRENT_DATE - detected_at::date) >= 14 THEN ('Open '::text || (CURRENT_DATE - detected_at::date)) || ' days and escalating.'::text
            ELSE ('Open '::text || (CURRENT_DATE - detected_at::date)) || ' days.'::text
        END AS how_long,
    metric,
    units,
    dollars
   FROM agent_findings f
  WHERE resolved_at IS NULL AND (severity = ANY (ARRAY['critical'::text, 'elevated'::text, 'watch'::text]));
create or replace view public.v_valuation_basis as
 SELECT stream,
    dollars_per_pound,
    basis,
    source_note,
    confirmed,
    set_by,
    set_at::date AS set_on,
    effective_from,
    ( SELECT count(*) AS count
           FROM valuation_overrides o
          WHERE o.stream = r.stream) AS overrides_on_this_stream,
        CASE
            WHEN confirmed THEN ((((((((('Rate of $'::text || dollars_per_pound) || ' per pound for '::text) || stream) || ', set by '::text) || COALESCE(set_by, 'unknown'::text)) || ' on '::text) || to_char(set_at, 'DD Mon YYYY'::text)) || '. Basis: '::text) || basis) || '.'::text
            ELSE ((((('UNCONFIRMED — $'::text || dollars_per_pound) || ' per pound is an inherited default that '::text) || 'nobody has set for '::text) || stream) || '. Every figure using it is an estimate. '::text) || 'Open Valuation Rates to set the real number.'::text
        END AS provenance
   FROM valuation_rates r
  WHERE effective_from = (( SELECT max(x.effective_from) AS max
           FROM valuation_rates x
          WHERE x.stream = r.stream AND x.effective_from <= CURRENT_DATE));
create or replace view public.v_watchdog_log as
 SELECT f.observed_at,
    f.observed_at::date AS observed_on,
    f.severity,
    f.what,
    f.where_it_is,
    f.who_is_accountable,
    f.when_it_started,
    f.why_it_matters,
    f.how_it_was_detected,
    f.what_to_do,
    f.the_arithmetic,
    f.record_count,
    f.pounds,
    f.dollars,
    f.drill,
    f.fingerprint,
    f.evidence,
    f.search_text,
    r.ran_at AS sweep_ran_at,
    r.ran_by AS sweep_ran_by,
    r.duration_ms AS sweep_ms,
    f.id AS finding_id,
    r.id AS run_id
   FROM watchdog_findings f
     LEFT JOIN watchdog_runs r ON r.id = f.run_id
  ORDER BY f.observed_at DESC, f.severity;
create or replace view public.v_watchdog_runs as
 SELECT ran_at,
    ran_at::date AS ran_on,
    ran_by,
    duration_ms,
    findings_raised,
    round(total_pounds_flagged, 1) AS pounds_flagged,
    round(total_dollars_flagged) AS dollars_flagged,
    id AS run_id
   FROM watchdog_runs
  ORDER BY ran_at DESC;
create or replace view public.v_watchdog_timeline as
 SELECT fingerprint,
    first_seen,
    last_seen,
    times_observed,
    days_persisting,
    severity,
    latest_state,
    accountable,
    peak_pounds,
    peak_dollars,
    drill,
    status,
    first_seen AS first_seen_date
   FROM ( SELECT watchdog_findings.fingerprint,
            min(watchdog_findings.observed_at)::date AS first_seen,
            max(watchdog_findings.observed_at)::date AS last_seen,
            count(*) AS times_observed,
            max(watchdog_findings.observed_at)::date - min(watchdog_findings.observed_at)::date AS days_persisting,
            max(watchdog_findings.severity) AS severity,
            (array_agg(watchdog_findings.what ORDER BY watchdog_findings.observed_at DESC))[1] AS latest_state,
            (array_agg(watchdog_findings.who_is_accountable ORDER BY watchdog_findings.observed_at DESC))[1] AS accountable,
            max(watchdog_findings.pounds) AS peak_pounds,
            max(watchdog_findings.dollars) AS peak_dollars,
            (array_agg(watchdog_findings.drill ORDER BY watchdog_findings.observed_at DESC))[1] AS drill,
                CASE
                    WHEN max(watchdog_findings.observed_at) < (now() - '2 days'::interval) THEN 'RESOLVED - last seen '::text || max(watchdog_findings.observed_at)::date
                    ELSE ('STILL OPEN after '::text || (CURRENT_DATE - min(watchdog_findings.observed_at)::date)) || ' days'::text
                END AS status
           FROM watchdog_findings
          GROUP BY watchdog_findings.fingerprint
          ORDER BY (max(watchdog_findings.observed_at)) DESC, (max(watchdog_findings.dollars)) DESC NULLS LAST) q;
create or replace view public.v_weight_audit as
 SELECT raw ->> 'UnitOfMeasureName'::text AS unit_of_measure,
    f_is_weight(raw ->> 'UnitOfMeasureName'::text) AS is_a_weight,
    count(*) AS packages,
    round(sum(NULLIF(raw ->> 'Quantity'::text, ''::text)::numeric), 1) AS total_quantity,
    round(sum(f_to_pounds(NULLIF(raw ->> 'Quantity'::text, ''::text)::numeric, raw ->> 'UnitOfMeasureName'::text)), 1) AS correct_pounds,
    round(sum(NULLIF(raw ->> 'Quantity'::text, ''::text)::numeric) / 453.592, 1) AS pounds_if_all_treated_as_grams,
    round(sum(f_to_pounds(NULLIF(raw ->> 'Quantity'::text, ''::text)::numeric, raw ->> 'UnitOfMeasureName'::text)) - sum(NULLIF(raw ->> 'Quantity'::text, ''::text)::numeric) / 453.592, 1) AS error_in_pounds,
        CASE
            WHEN NOT f_is_weight(raw ->> 'UnitOfMeasureName'::text) THEN ((((((('NOT A WEIGHT. '::text || count(*)) || ' packages counted in '::text) || (raw ->> 'UnitOfMeasureName'::text)) || '. These are units, not grams. Converting them to pounds produced a meaningless figure of '::text) || round(sum(NULLIF(raw ->> 'Quantity'::text, ''::text)::numeric) / 453.592, 1)) || ' lb from '::text) || round(sum(NULLIF(raw ->> 'Quantity'::text, ''::text)::numeric))) || ' units.'::text
            WHEN lower(raw ->> 'UnitOfMeasureName'::text) = ANY (ARRAY['g'::text, 'grams'::text]) THEN 'Correct — grams converted properly.'::text
            ELSE ((((((('WRONG CONVERSION. '::text || count(*)) || ' packages are in '::text) || (raw ->> 'UnitOfMeasureName'::text)) || ' but were divided by 453.592 as if grams. True weight is '::text) || round(sum(f_to_pounds(NULLIF(raw ->> 'Quantity'::text, ''::text)::numeric, raw ->> 'UnitOfMeasureName'::text)), 1)) || ' lb, shown as '::text) || round(sum(NULLIF(raw ->> 'Quantity'::text, ''::text)::numeric) / 453.592, 1)) || ' lb.'::text
        END AS verdict
   FROM metrc_packages p
  WHERE COALESCE((raw ->> 'Quantity'::text)::numeric, 0::numeric) > 0::numeric
  GROUP BY (raw ->> 'UnitOfMeasureName'::text)
  ORDER BY (round(sum(f_to_pounds(NULLIF(raw ->> 'Quantity'::text, ''::text)::numeric, raw ->> 'UnitOfMeasureName'::text)), 1)) DESC NULLS LAST;
create or replace view public.v_weight_basis_gaps as
 SELECT c.relname AS relation,
        CASE c.relkind
            WHEN 'r'::"char" THEN 'table'::text
            WHEN 'v'::"char" THEN 'view'::text
            WHEN 'm'::"char" THEN 'matview'::text
            ELSE NULL::text
        END AS kind,
    a.attname AS column_name,
    w.basis,
    w.basis IS NULL AS undeclared,
    (EXISTS ( SELECT 1
           FROM pg_attribute m
          WHERE m.attrelid = c.oid AND m.attnum > 0 AND NOT m.attisdropped AND m.attname ~ '(dollar|revenue|price|cost|margin|amount|cash|value_at)'::text)) AS relation_also_carries_money
   FROM pg_class c
     JOIN pg_namespace n ON n.oid = c.relnamespace AND n.nspname = 'public'::name
     JOIN pg_attribute a ON a.attrelid = c.oid AND a.attnum > 0 AND NOT a.attisdropped
     LEFT JOIN weight_basis_registry w ON w.relation = c.relname AND w.column_name = a.attname
  WHERE (c.relkind = ANY (ARRAY['r'::"char", 'v'::"char", 'm'::"char"])) AND a.attname ~ '(pounds|_lb$|_lbs|lbs_|grams|weight)'::text AND a.attname !~ '(weighted|weight_in_parent)'::text;
create or replace view public.v_wholesale_reconciliation as
 WITH w AS (
         SELECT metrc_rpt_wholesale.manifest_number,
            max(metrc_rpt_wholesale.licence) AS licence,
            min(metrc_rpt_wholesale.created_on) AS created_on,
            sum(metrc_rpt_wholesale.amount) FILTER (WHERE NOT metrc_rpt_wholesale.voided) AS wholesale_value,
            max(metrc_rpt_wholesale.as_of_date) AS wholesale_as_of,
            count(*) AS wholesale_lines
           FROM metrc_rpt_wholesale
          GROUP BY metrc_rpt_wholesale.manifest_number
        ), p AS (
         SELECT metrc_rpt_package_transfers.manifest_number,
            max(metrc_rpt_package_transfers.licence) AS licence,
            sum(metrc_rpt_package_transfers.shipper_wholesale_price) AS package_value,
            max(metrc_rpt_package_transfers.as_of_date) AS package_as_of,
            count(*) AS package_lines
           FROM metrc_rpt_package_transfers
          GROUP BY metrc_rpt_package_transfers.manifest_number
        )
 SELECT COALESCE(w.manifest_number, p.manifest_number) AS manifest_number,
    COALESCE(w.licence, p.licence) AS licence,
    w.created_on,
    w.wholesale_value,
    p.package_value,
    round(COALESCE(w.wholesale_value, 0::numeric) - COALESCE(p.package_value, 0::numeric), 2) AS difference,
    w.wholesale_as_of,
    p.package_as_of,
    w.wholesale_lines,
    p.package_lines,
        CASE
            WHEN w.manifest_number IS NULL THEN 'In the package export only - no invoice line'::text
            WHEN p.manifest_number IS NULL AND w.created_on > p_max.as_of THEN ('Created after the package export was pulled on '::text || p_max.as_of) || '. Not a disagreement - a newer manifest.'::text
            WHEN p.manifest_number IS NULL THEN 'In the wholesale report only'::text
            WHEN abs(COALESCE(w.wholesale_value, 0::numeric) - COALESCE(p.package_value, 0::numeric)) < 0.01 THEN 'Agrees'::text
            ELSE 'DISAGREES - both report this manifest with a different value'::text
        END AS reading
   FROM w
     FULL JOIN p ON p.manifest_number = w.manifest_number
     CROSS JOIN ( SELECT max(metrc_rpt_package_transfers.as_of_date) AS as_of
           FROM metrc_rpt_package_transfers) p_max;
create or replace view public.v_year_end_2025 as
 SELECT license,
    category,
    item,
    packages,
    quantity_estimate,
    uom,
    cost_per_unit,
    value_at_cost,
    basis,
    confidence
   FROM tg_inventory_as_of('2025-12-31'::date) tg_inventory_as_of(license, category, item, packages, quantity_estimate, uom, cost_per_unit, value_at_cost, basis, confidence);
create or replace view public.v_year_end_2025_coverage as
 SELECT count(*) AS rows_total,
    count(*) FILTER (WHERE COALESCE(quantity_estimate, 0::numeric) > 0::numeric) AS rows_with_a_quantity,
    count(*) FILTER (WHERE COALESCE(quantity_estimate, 0::numeric) = 0::numeric) AS rows_with_no_quantity,
    count(*) FILTER (WHERE value_at_cost IS NULL) AS rows_with_no_value,
    count(*) FILTER (WHERE category = 'Uncategorised'::text) AS rows_with_no_category,
    round(COALESCE(sum(value_at_cost), 0::numeric)) AS value_that_could_be_established,
    (((((((((((('NOT FILEABLE AS IT STANDS. '::text || count(*) FILTER (WHERE COALESCE(quantity_estimate, 0::numeric) = 0::numeric)) || ' of '::text) || count(*)) || ' rows carry no quantity and '::text) || count(*) FILTER (WHERE category = 'Uncategorised'::text)) || ' carry no category, because Metrc''s interface exposes no historical snapshot — this is '::text) || 'rebuilt from the quantity each package was created with, which for most packages as at '::text) || '31 December 2025 is unknown. The $'::text) || round(COALESCE(sum(value_at_cost), 0::numeric))) || ' shown is only the fraction that could be established, not the closing inventory. '::text) || 'For a filed return, export the Inventory Point-in-Time report from the Metrc Reports '::text) || 'Control Panel for 31 December 2025 and import it on the Report Import page. That is the '::text) || 'authoritative figure and nothing here replaces it.'::text AS what_this_means
   FROM tg_inventory_as_of('2025-12-31'::date) tg_inventory_as_of(license, category, item, packages, quantity_estimate, uom, cost_per_unit, value_at_cost, basis, confidence);
create or replace view public.v_yield_by_harvest as
 WITH split AS (
         SELECT TRIM(BOTH FROM x.harvest_name) AS harvest_name,
            p.raw #>> '{Item,ProductCategoryName}'::text[] AS category,
            f_to_pounds((p.raw ->> 'CreatedQuantity'::text)::numeric, COALESCE(p.raw ->> 'CreatedQuantityUnitOfMeasureAbbreviation'::text, p.uom)) / NULLIF(array_length(string_to_array(p.raw ->> 'SourceHarvestNames'::text, ','::text), 1), 0)::numeric AS made_lb,
            array_length(string_to_array(p.raw ->> 'SourceHarvestNames'::text, ','::text), 1) AS harvests_named
           FROM metrc_packages p
             CROSS JOIN LATERAL unnest(string_to_array(p.raw ->> 'SourceHarvestNames'::text, ','::text)) x(harvest_name)
          WHERE NULLIF(p.raw ->> 'SourceHarvestNames'::text, ''::text) IS NOT NULL
        )
 SELECT h.name AS harvest,
    h.raw ->> 'SourceStrainNames'::text AS strain,
    h.raw ->> 'DryingLocationName'::text AS room,
    h.harvest_start AS cut_on,
    (h.raw ->> 'FinishedDate'::text)::date AS finished_on,
    to_char(date_trunc('month'::text, COALESCE((h.raw ->> 'FinishedDate'::text)::date, h.harvest_start)::timestamp with time zone), 'YYYY-MM'::text) AS month,
    (h.raw ->> 'PlantCount'::text)::numeric AS plants,
    round(((h.raw ->> 'TotalWetWeight'::text)::numeric) / 453.592, 1) AS wet_lb,
    round(((h.raw ->> 'TotalWasteWeight'::text)::numeric) / 453.592, 1) AS waste_lb,
    round(COALESCE(sum(s.made_lb) FILTER (WHERE s.category = 'Buds'::text), 0::numeric), 1) AS dried_flower_lb,
    round(COALESCE(sum(s.made_lb) FILTER (WHERE s.category ~~ 'Shake/Trim%'::text), 0::numeric), 1) AS trim_lb,
    round(COALESCE(sum(s.made_lb) FILTER (WHERE s.category = 'Fresh Frozen Flower'::text), 0::numeric), 1) AS fresh_frozen_lb,
    round(COALESCE(sum(s.made_lb) FILTER (WHERE (s.category <> ALL (ARRAY['Buds'::text, 'Fresh Frozen Flower'::text])) AND s.category !~~ 'Shake/Trim%'::text), 0::numeric), 1) AS other_lb,
    round(COALESCE(sum(s.made_lb), 0::numeric), 1) AS total_made_lb,
        CASE
            WHEN ((h.raw ->> 'PlantCount'::text)::numeric) > 0::numeric THEN round(COALESCE(sum(s.made_lb) FILTER (WHERE s.category = 'Buds'::text), 0::numeric) * 453.592 / ((h.raw ->> 'PlantCount'::text)::numeric), 1)
            ELSE NULL::numeric
        END AS grams_per_plant,
        CASE
            WHEN ((h.raw ->> 'TotalWetWeight'::text)::numeric) > 0::numeric THEN round(100.0 * COALESCE(sum(s.made_lb) FILTER (WHERE s.category = 'Buds'::text), 0::numeric) / (((h.raw ->> 'TotalWetWeight'::text)::numeric) / 453.592), 1)
            ELSE NULL::numeric
        END AS flower_yield_pct,
    bool_or(s.harvests_named > 1) AS weight_shared_with_other_harvests,
    h.license
   FROM metrc_harvests h
     LEFT JOIN split s ON s.harvest_name = h.name
  GROUP BY h.name, h.raw, h.harvest_start, h.license;
create or replace view public.v_zone_staffing as
 WITH req AS (
         SELECT z.id AS zone_id,
            z.name AS zone,
            z.department_id,
            r.headcount_required,
            r.hours_per_head,
            r.driver,
            r.weekday,
            r.shift,
            r.effective_from,
            r.effective_to
           FROM zones z
             LEFT JOIN zone_staffing_requirements r ON r.zone_id = z.id
          WHERE z.active
        ), sched AS (
         SELECT btrim(s.zone) AS zone,
            s.work_date,
            count(DISTINCT s.employee_id) AS scheduled_heads,
            sum(EXTRACT(epoch FROM s.planned_end - s.planned_start) / 3600.0) AS scheduled_hours
           FROM employee_schedules s
          WHERE s.zone IS NOT NULL
          GROUP BY (btrim(s.zone)), s.work_date
        ), act AS (
         SELECT btrim(s.zone) AS zone,
            t.work_date,
            count(DISTINCT t.employee_id) AS actual_heads,
            sum(EXTRACT(epoch FROM t.clock_out - t.clock_in) / 3600.0 - COALESCE(t.unpaid_lunch_min, 0)::numeric / 60.0) AS actual_hours,
            sum((EXTRACT(epoch FROM t.clock_out - t.clock_in) / 3600.0 - COALESCE(t.unpaid_lunch_min, 0)::numeric / 60.0) * r.rate * (1::numeric + COALESCE(r.burden_pct, 0::numeric))) AS actual_cost_loaded
           FROM time_entries t
             JOIN employee_schedules s ON s.employee_id = t.employee_id AND s.work_date = t.work_date
             LEFT JOIN LATERAL ( SELECT r2.id,
                    r2.employee_id,
                    r2.basis,
                    r2.rate,
                    r2.ot_multiplier,
                    r2.burden_pct,
                    r2.effective_from,
                    r2.effective_to,
                    r2.approved_by,
                    r2.note,
                    r2.effective_from_date
                   FROM employee_rates r2
                  WHERE r2.employee_id = t.employee_id AND r2.effective_from <= t.work_date AND (r2.effective_to IS NULL OR r2.effective_to >= t.work_date)
                  ORDER BY r2.effective_from DESC
                 LIMIT 1) r ON true
          WHERE t.clock_out IS NOT NULL
          GROUP BY (btrim(s.zone)), t.work_date
        )
 SELECT req.zone,
    req.zone_id,
    d.name AS department,
    COALESCE(sched.work_date, act.work_date) AS work_date,
    req.driver,
    req.headcount_required,
    COALESCE(sched.scheduled_heads, 0::bigint) AS scheduled_heads,
    COALESCE(act.actual_heads, 0::bigint) AS actual_heads,
    COALESCE(sched.scheduled_heads, 0::bigint) - COALESCE(req.headcount_required, 0) AS sched_vs_required,
    COALESCE(act.actual_heads, 0::bigint) - COALESCE(sched.scheduled_heads, 0::bigint) AS actual_vs_sched,
    round(COALESCE(sched.scheduled_hours, 0::numeric), 2) AS scheduled_hours,
    round(COALESCE(act.actual_hours, 0::numeric), 2) AS actual_hours,
    round(COALESCE(act.actual_cost_loaded, 0::numeric), 2) AS actual_cost_loaded,
        CASE
            WHEN req.headcount_required IS NULL THEN 'no requirement set'::text
            WHEN COALESCE(act.actual_heads, 0::bigint) < req.headcount_required THEN 'short'::text
            WHEN COALESCE(act.actual_heads, 0::bigint) > req.headcount_required THEN 'over'::text
            ELSE 'on plan'::text
        END AS staffing_flag
   FROM req
     LEFT JOIN sched ON sched.zone = req.zone
     LEFT JOIN act ON act.zone = req.zone AND act.work_date = sched.work_date
     LEFT JOIN departments d ON d.id = req.department_id;
create materialized view if not exists public.mv_document_search as
 SELECT doc_type,
    document,
    reference,
    package_tag,
    manifest_number,
    item_name,
    shipper,
    customer,
    lab_facility,
    manifest_date,
    tested_on,
    open_download_print,
    direction,
    current_location,
    license,
    lower(COALESCE(search_text, ''::text)) AS search_text
   FROM v_document_library;
create materialized view if not exists public.mv_harvest_pkg_rollup as
 SELECT harvest_name,
    min(packaged_on) AS first_package_on,
    max(packaged_on) AS last_package_on,
    count(DISTINCT package_id) AS packages_made,
    count(DISTINCT package_id) FILTER (WHERE lab_state = 'TestFailed'::text) AS failed_packages,
    count(DISTINCT package_id) FILTER (WHERE lab_state = 'TestPassed'::text) AS passed_packages,
    count(DISTINCT package_id) FILTER (WHERE lab_state = 'NotSubmitted'::text) AS untested_packages,
    round(sum(quantity) FILTER (WHERE category ~~* '%bud%'::text) / 453.592, 2) AS bud_lb,
    round(sum(quantity) FILTER (WHERE category ~~* '%shake%'::text OR category ~~* '%trim%'::text) / 453.592, 2) AS shake_trim_lb,
    string_agg(DISTINCT category, ', '::text) AS categories_made
   FROM mv_package_harvest
  GROUP BY harvest_name;
create materialized view if not exists public.mv_seed_to_sale as
 SELECT strain,
    plants_growing_now,
    plants_harvested,
    harvest_events,
    wet_weight_lbs,
    waste_lbs,
    waste_pct,
    packaged_lbs,
    yield_pct,
    packages_made,
    manufactured_into,
    on_hand_now,
    sitting_in,
    packages_passed_testing,
    packages_failed_testing,
    packages_shipped_out,
    still_in_rooms,
    last_harvest
   FROM v_metrc_seed_to_sale;
create materialized view if not exists public.mv_strain_census as
 SELECT license,
    strain,
    live_plants_now,
    vegetative_now,
    flowering_now,
    on_hold_now,
    harvested_or_retired,
    total_plants_all_time,
    rooms_now,
    in_rooms,
    first_planted,
    last_planted,
    harvest_events,
    lifetime_wet_lbs,
    lifetime_packaged_lbs
   FROM v_metrc_strain_census;
create or replace view public.v_actual_cost_per_pound as
 WITH pay AS (
         SELECT COALESCE(sum(v_payroll_forecast.loaded_weekly_cost), 0::numeric) AS weekly
           FROM v_payroll_forecast
        ), oh AS (
         SELECT COALESCE(sum(overhead_items.monthly_amount), 0::numeric) AS monthly,
            count(*) AS rows_recorded,
            bool_or(overhead_items.description ~~* '%wages included%'::text) AS includes_wages
           FROM overhead_items
        ), "out" AS (
         SELECT COALESCE(sum(v_true_cost_per_pound.saleable_lbs), 0::numeric) AS lbs,
            count(*) AS months
           FROM v_true_cost_per_pound
          WHERE v_true_cost_per_pound.month_date >= (date_trunc('month'::text, CURRENT_DATE::timestamp with time zone) - '6 mons'::interval)
        )
 SELECT ( SELECT "out".months
           FROM "out") AS months_counted,
    round(( SELECT "out".lbs
           FROM "out"), 1) AS saleable_pounds_in_period,
    round((( SELECT pay.weekly
           FROM pay)) * 52::numeric / 12::numeric, 0) AS payroll_per_month,
    round(( SELECT oh.monthly
           FROM oh), 0) AS overhead_per_month,
    round(
        CASE
            WHEN ( SELECT oh.includes_wages
               FROM oh) THEN ( SELECT oh.monthly
               FROM oh)
            ELSE (( SELECT oh.monthly
               FROM oh)) + (( SELECT pay.weekly
               FROM pay)) * 52::numeric / 12::numeric
        END, 0) AS total_cost_per_month,
    round((( SELECT oh.monthly
           FROM oh)) * (( SELECT "out".months
           FROM "out"))::numeric, 0) AS overhead_in_period,
    ( SELECT oh.rows_recorded
           FROM oh) AS overhead_lines_recorded,
        CASE
            WHEN (( SELECT "out".lbs
               FROM "out")) > 0::numeric THEN round(
            CASE
                WHEN ( SELECT oh.includes_wages
                   FROM oh) THEN ( SELECT oh.monthly
                   FROM oh)
                ELSE (( SELECT oh.monthly
                   FROM oh)) + (( SELECT pay.weekly
                   FROM pay)) * 52::numeric / 12::numeric
            END * (( SELECT "out".months
               FROM "out"))::numeric / (( SELECT "out".lbs
               FROM "out")), 2)
            ELSE NULL::numeric
        END AS actual_cost_per_pound,
    ( SELECT conversion_factors.value
           FROM conversion_factors
          WHERE conversion_factors.key = 'target_cost_per_lb'::text) AS assumed_cost_per_pound,
        CASE
            WHEN (( SELECT "out".lbs
               FROM "out")) > 0::numeric THEN round((( SELECT conversion_factors.value
               FROM conversion_factors
              WHERE conversion_factors.key = 'target_cost_per_lb'::text)) -
            CASE
                WHEN ( SELECT oh.includes_wages
                   FROM oh) THEN ( SELECT oh.monthly
                   FROM oh)
                ELSE (( SELECT oh.monthly
                   FROM oh)) + (( SELECT pay.weekly
                   FROM pay)) * 52::numeric / 12::numeric
            END * (( SELECT "out".months
               FROM "out"))::numeric / (( SELECT "out".lbs
               FROM "out")), 2)
            ELSE NULL::numeric
        END AS gap_per_pound,
        CASE
            WHEN ( SELECT oh.includes_wages
               FROM oh) THEN (((((('The $'::text || round(( SELECT oh.monthly
               FROM oh))) || ' a month is the WHOLE operating cost including '::text) || 'wages, confirmed by the owner. Payroll of $'::text) || round((( SELECT pay.weekly
               FROM pay)) * 52::numeric / 12::numeric)) || ' a month is inside that figure and is deliberately not added again. It is not itemised, so '::text) || 'the total is right but nothing can be attributed to a cause — connect QuickBooks or upload '::text) || 'a profit and loss statement to get the real lines.'::text
            ELSE 'Payroll plus recorded overhead.'::text
        END AS what_is_missing,
    ((((('Total operating cost of $'::text || round(( SELECT oh.monthly
           FROM oh))) || ' a month, wages included, over '::text) || (( SELECT "out".months
           FROM "out"))) || ' months, divided by the '::text) || round(( SELECT "out".lbs
           FROM "out"), 1)) || ' saleable pounds packaged in that period.'::text AS the_arithmetic;
create or replace view public.v_alert_email_status as
 SELECT ( SELECT (configurations.value ->> 'enabled'::text)::boolean AS bool
           FROM configurations
          WHERE configurations.key = 'alert_email'::text) AS email_enabled,
    ( SELECT configurations.value ->> 'provider'::text
           FROM configurations
          WHERE configurations.key = 'alert_email'::text) AS provider,
    ( SELECT count(*) AS count
           FROM alert_outbox
          WHERE alert_outbox.channel = 'email'::text AND alert_outbox.sent_at IS NULL AND alert_outbox.resolved_at IS NULL) AS queued_unsent,
    ( SELECT count(*) AS count
           FROM v_alert_email_recipients) AS addresses_on_file,
    ( SELECT count(DISTINCT item_alert_route.role) AS count
           FROM item_alert_route
          WHERE item_alert_route.notify_email AND item_alert_route.active) AS roles_wanting_email,
        CASE
            WHEN NOT COALESCE(( SELECT (configurations.value ->> 'enabled'::text)::boolean AS bool
               FROM configurations
              WHERE configurations.key = 'alert_email'::text), false) THEN ('EMAIL NOT CONFIGURED - '::text || (( SELECT count(*) AS count
               FROM alert_outbox
              WHERE alert_outbox.channel = 'email'::text AND alert_outbox.sent_at IS NULL AND alert_outbox.resolved_at IS NULL))) || ' alerts queued and holding. They are not lost and they are not sent.'::text
            WHEN (( SELECT count(*) AS count
               FROM v_alert_email_recipients)) = 0 THEN 'EMAIL ON BUT NOBODY TO SEND TO - no addresses on file.'::text
            ELSE ((('Email is on. '::text || (( SELECT count(*) AS count
               FROM alert_outbox
              WHERE alert_outbox.channel = 'email'::text AND alert_outbox.sent_at IS NULL AND alert_outbox.resolved_at IS NULL))) || ' waiting to go to '::text) || (( SELECT count(*) AS count
               FROM v_alert_email_recipients))) || ' addresses.'::text
        END AS status;
create or replace view public.v_auditor_verdict as
 SELECT ( SELECT count(*) AS count
           FROM v_conformance_coverage
          WHERE v_conformance_coverage.coverage = 'NEVER CHECKED'::text) AS subjects_never_checked,
    ( SELECT count(*) AS count
           FROM v_conformance_coverage) AS subjects_total,
    round(100.0 * (( SELECT count(*) AS count
           FROM v_conformance_coverage
          WHERE v_conformance_coverage.coverage <> 'NEVER CHECKED'::text))::numeric / NULLIF(( SELECT count(*) AS count
           FROM v_conformance_coverage), 0)::numeric, 1) AS coverage_pct,
    ( SELECT count(*) AS count
           FROM v_auditor_heartbeat
          WHERE v_auditor_heartbeat.heartbeat = ANY (ARRAY['NEVER RUN'::text, 'DARK'::text])) AS checkers_dark,
    ( SELECT count(*) AS count
           FROM v_auditor_heartbeat
          WHERE NOT v_auditor_heartbeat.fixture_proves_it_fails AND v_auditor_heartbeat.enabled) AS checkers_unproven,
    ( SELECT count(*) AS count
           FROM policy_registry
          WHERE policy_registry.active AND NOT policy_registry.enforced) AS policies_on_memory_only,
    ( SELECT count(*) AS count
           FROM finding_remediation
          WHERE finding_remediation.state <> ALL (ARRAY['closed'::text, 'accepted_risk'::text])) AS findings_open,
    ( SELECT count(*) AS count
           FROM finding_remediation
          WHERE (finding_remediation.state <> ALL (ARRAY['closed'::text, 'accepted_risk'::text])) AND finding_remediation.due_by < now()) AS findings_overdue,
    ( SELECT count(*) AS count
           FROM finding_remediation
          WHERE (finding_remediation.state <> ALL (ARRAY['closed'::text, 'accepted_risk'::text])) AND finding_remediation.severity = 'critical'::text) AS findings_critical,
    ( SELECT round(sum(cl.pounds), 1) AS round
           FROM conformance_ledger cl
          WHERE (cl.verdict = ANY (ARRAY['FAIL'::text, 'DISAGREE'::text])) AND cl.ran_at > (now() - '24:00:00'::interval)) AS pounds_in_question_24h,
    ( SELECT round(sum(cl.dollars), 2) AS round
           FROM conformance_ledger cl
          WHERE (cl.verdict = ANY (ARRAY['FAIL'::text, 'DISAGREE'::text])) AND cl.ran_at > (now() - '24:00:00'::interval)) AS dollars_in_question_24h;
create or replace view public.v_certificate_gap as
 WITH p AS (
         SELECT DISTINCT ON (metrc_packages.tag) metrc_packages.tag,
            metrc_packages.item_name,
            metrc_packages.license,
            metrc_packages.uom,
            metrc_packages.quantity,
            metrc_packages.packaged_on,
            metrc_packages.lab_testing_state,
            metrc_packages.source_state,
            metrc_packages.raw
           FROM metrc_packages
          ORDER BY metrc_packages.tag, metrc_packages.license
        )
 SELECT p.tag AS package_tag,
    "left"(p.item_name, 55) AS item_name,
    p.license,
    p.lab_testing_state,
    p.source_state,
        CASE
            WHEN f_is_weight(p.uom) THEN round(f_to_pounds(p.quantity, p.uom), 2)
            ELSE NULL::numeric
        END AS pounds,
    p.packaged_on,
    CURRENT_DATE - p.packaged_on AS days_held,
    p.raw ->> 'LocationName'::text AS location,
    p.raw ->> 'ItemFromFacilityLicenseNumber'::text AS platform_license,
    NULLIF(p.raw ->> 'ReceivedFromManifestNumber'::text, ''::text) AS inbound_manifest,
    NULLIF(p.raw ->> 'ReceivedFromFacilityName'::text, ''::text) AS received_from,
    ( SELECT count(*) AS count
           FROM metrc_lab_results l
          WHERE l.package_tag = p.tag) AS lab_result_rows,
    ( SELECT max(l.document_file_id) AS max
           FROM metrc_lab_results l
          WHERE l.package_tag = p.tag AND l.document_file_id IS NOT NULL) AS coa_document_id,
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM metrc_lab_results l
              WHERE l.package_tag = p.tag AND l.document_file_id IS NOT NULL)) THEN 'A - COA ID HELD'::text
            WHEN (EXISTS ( SELECT 1
               FROM metrc_lab_results l
              WHERE l.package_tag = p.tag)) THEN 'B - NO DOCUMENT ID'::text
            ELSE 'C - NO LAB RESULTS'::text
        END AS bucket,
        CASE
            WHEN (EXISTS ( SELECT 1
               FROM metrc_lab_results l
              WHERE l.package_tag = p.tag AND l.document_file_id IS NOT NULL)) THEN 'Download it: GET /labtests/v2/labtestdocument/<coa_document_id>, store in metrc_documents, parse the Client Info block.'::text
            WHEN (EXISTS ( SELECT 1
               FROM metrc_lab_results l
              WHERE l.package_tag = p.tag)) THEN 'Re-pull the lab result for this package to capture LabTestResultDocumentFileId, then download.'::text
            ELSE 'lab_testing_state says tested but no results are synced. Re-pull this package''s lab results from Metrc before anything else.'::text
        END AS what_to_do,
    'THE ISSUE: this package carries a test result but no certificate is linked to it or to anything in its lineage. Ownership and potency cannot be independently confirmed, so nothing may be posted on it.'::text AS what_is_wrong
   FROM p
     LEFT JOIN v_certificate_resolved r ON r.package_tag = p.tag
  WHERE r.package_tag IS NULL AND (p.lab_testing_state <> ALL (ARRAY['NotSubmitted'::text, 'NotRequired'::text, 'SubmittedForTesting'::text, 'TestingInProgress'::text]));
create or replace view public.v_challenge_overdue as
 SELECT u.id,
    u.severity,
    "left"(u.what, 90) AS what,
    w.observed_at,
    round(EXTRACT(epoch FROM now() - w.observed_at) / 3600::numeric)::integer AS hours_old,
        CASE u.severity
            WHEN 'critical'::text THEN 24
            WHEN 'elevated'::text THEN 72
            ELSE 168
        END AS owed_within_hours,
    round(EXTRACT(epoch FROM now() - w.observed_at) / 3600::numeric)::integer -
        CASE u.severity
            WHEN 'critical'::text THEN 24
            WHEN 'elevated'::text THEN 72
            ELSE 168
        END AS hours_overdue,
    u.the_arithmetic IS NULL AS has_no_arithmetic,
        CASE
            WHEN (EXTRACT(epoch FROM now() - w.observed_at) / 3600::numeric) <=
            CASE u.severity
                WHEN 'critical'::text THEN 24
                WHEN 'elevated'::text THEN 72
                ELSE 168
            END::numeric THEN 'within the window'::text
            WHEN u.severity = 'critical'::text THEN 'OVERDUE - a critical claim nobody has tested'::text
            ELSE 'overdue'::text
        END AS standing
   FROM v_unchallenged_findings u
     JOIN watchdog_findings w ON w.id = u.id
  ORDER BY ((EXTRACT(epoch FROM now() - w.observed_at) / 3600::numeric) >
        CASE u.severity
            WHEN 'critical'::text THEN 24
            WHEN 'elevated'::text THEN 72
            ELSE 168
        END::numeric) DESC, (
        CASE u.severity
            WHEN 'critical'::text THEN 0
            WHEN 'elevated'::text THEN 1
            ELSE 2
        END), w.observed_at;
create or replace view public.v_concentrate_valuation as
 SELECT s.package_tag,
    s.item_name,
    s.strain,
    s.pounds,
    round(s.quantity) AS grams,
    s.lab_state,
    s.location,
    COALESCE(m.sub_type, 'Crude, distillate or isolate'::text) AS sub_type,
    COALESCE(m.dollars_per_gram, round((( SELECT v_cost_of_goods.badder_crude_per_pound
           FROM v_cost_of_goods)) / 453.592, 4)) AS dollars_per_gram,
    round(s.pounds * f_concentrate_rate_per_lb(s.item_name)) AS value_at_cost,
    COALESCE(m.source, 'No sheet rate for this type. Falls back to the crude cost per gram computed '::text || 'by the Production Cost Calculator from the owner''s worksheet.'::text) AS rate_source
   FROM v_stock_packages s
     LEFT JOIN LATERAL ( SELECT m2.id,
            m2.match_pattern,
            m2.sub_type,
            m2.dollars_per_gram,
            m2.source,
            m2.sort
           FROM concentrate_rate_map m2
          WHERE s.item_name ~~* m2.match_pattern
          ORDER BY m2.sort
         LIMIT 1) m ON true
  WHERE s.stream = 'Concentrate'::text;
create or replace view public.v_cost_of_loss as
 SELECT scope_type,
    scope,
    harvests,
    wet_lbs,
    waste_lbs,
    waste_pct,
    yield_pct,
    verdict,
    ( SELECT cost_model.cost_per_pound
           FROM cost_model
          WHERE cost_model.scope = 'cultivation'::text
          ORDER BY cost_model.effective_from DESC
         LIMIT 1) AS cost_per_pound,
    round(waste_lbs * (( SELECT cost_model.cost_per_pound
           FROM cost_model
          WHERE cost_model.scope = 'cultivation'::text
          ORDER BY cost_model.effective_from DESC
         LIMIT 1)), 0) AS cost_of_waste,
    round((waste_pct - (( SELECT round(100.0 * sum(COALESCE((metrc_harvests.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric)) / NULLIF(sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)), 0::numeric), 1) AS round
           FROM metrc_harvests))) / 100.0 * wet_lbs * (( SELECT cost_model.cost_per_pound
           FROM cost_model
          WHERE cost_model.scope = 'cultivation'::text
          ORDER BY cost_model.effective_from DESC
         LIMIT 1)), 0) AS excess_cost_vs_company_average
   FROM v_loss_ranking l
  WHERE wet_lbs > 0::numeric
  ORDER BY (round(waste_lbs * (( SELECT cost_model.cost_per_pound
           FROM cost_model
          WHERE cost_model.scope = 'cultivation'::text
          ORDER BY cost_model.effective_from DESC
         LIMIT 1)), 0)) DESC NULLS LAST;
create or replace view public.v_customers as
 SELECT c.id,
    c.name,
    c.state_license,
    c.terms_days,
    c.credit_limit,
    c.active,
    c.contact_name,
    c.email,
    c.cc_emails,
    c.phone,
        CASE
            WHEN c.email IS NULL THEN 'No email on file. Metrc carries no customer email addresses - this must be entered by a person.'::text
            ELSE 'Ready to send'::text
        END AS contact_status,
    h.shipments,
    h.first_shipment,
    h.last_shipment,
    h.packages_shipped,
    h.last_invoice,
    h.last_manifest,
    h.gross_weight_last,
    h.weight_unit_last,
    d.manifests_held,
        CASE
            WHEN h.shipments IS NULL THEN 'Never shipped to'::text
            WHEN h.last_shipment > (now() - '60 days'::interval) THEN 'Active'::text
            WHEN h.last_shipment > (now() - '180 days'::interval) THEN 'Quiet - no shipment in 60 days'::text
            ELSE 'Dormant - no shipment in 6 months'::text
        END AS trading_status,
    h.lab_samples,
    h.cultivation_shipments,
    h.manufacturing_shipments,
    h.bought_from_them
   FROM customers c
     LEFT JOIN LATERAL ( SELECT count(*) FILTER (WHERE m.is_customer_sale) AS shipments,
            min(m.created_on) FILTER (WHERE m.is_customer_sale) AS first_shipment,
            max(m.created_on) FILTER (WHERE m.is_customer_sale) AS last_shipment,
            sum(((m.raw -> '_delivery'::text) ->> 'DeliveryPackageCount'::text)::integer) FILTER (WHERE m.is_customer_sale) AS packages_shipped,
            max((m.raw -> '_delivery'::text) ->> 'InvoiceNumber'::text) FILTER (WHERE m.is_customer_sale) AS last_invoice,
            max(m.manifest_number) FILTER (WHERE m.is_customer_sale) AS last_manifest,
            max(((m.raw -> '_delivery'::text) ->> 'GrossWeight'::text)::numeric) FILTER (WHERE m.is_customer_sale) AS gross_weight_last,
            max((m.raw -> '_delivery'::text) ->> 'GrossUnitOfWeightName'::text) FILTER (WHERE m.is_customer_sale) AS weight_unit_last,
            count(*) FILTER (WHERE m.movement = 'Laboratory sample'::text) AS lab_samples,
            count(*) FILTER (WHERE m.is_customer_sale AND m.operation = 'Cultivation'::text) AS cultivation_shipments,
            count(*) FILTER (WHERE m.is_customer_sale AND m.operation = 'Manufacturing'::text) AS manufacturing_shipments,
            count(*) FILTER (WHERE m.is_inbound_purchase) AS bought_from_them
           FROM v_manifest_ledger m
          WHERE m.recipient = c.metrc_facility_name OR m.shipper = c.metrc_facility_name) h ON true
     LEFT JOIN LATERAL ( SELECT count(*) AS manifests_held
           FROM metrc_documents md
          WHERE md.doc_type = 'manifest'::text AND md.storage_path IS NOT NULL AND (md.manifest_number IN ( SELECT m2.manifest_number
                   FROM v_manifest_ledger m2
                  WHERE m2.recipient = c.metrc_facility_name))) d ON true
  WHERE (COALESCE(c.state_license, ''::text) <> ALL (ARRAY['MC281714'::text, 'MP281909'::text])) AND c.name !~~* '%twisted growers%'::text;
create or replace view public.v_department_staffing_average as
 WITH daily AS (
         SELECT v_department_labour.department_id,
            v_department_labour.department,
            v_department_labour.shift,
            v_department_labour.work_date,
            v_department_labour.week_start,
            v_department_labour.month_start,
            v_department_labour.heads,
            v_department_labour.hours,
            v_department_labour.total_cost_loaded
           FROM v_department_labour
        )
 SELECT d.department_id,
    d.department,
    d.shift,
    min(d.work_date) AS from_date,
    max(d.work_date) AS to_date,
    count(DISTINCT d.work_date) AS days_run,
    round(avg(d.heads), 2) AS avg_heads,
    min(d.heads) AS min_heads,
    max(d.heads) AS max_heads,
    round(avg(d.hours), 2) AS avg_hours_per_day,
    round(sum(d.total_cost_loaded), 2) AS total_cost_loaded,
    round(avg(d.total_cost_loaded), 2) AS avg_cost_per_day,
    req.headcount_required AS minimum_required,
        CASE
            WHEN req.headcount_required IS NULL THEN 'no minimum set'::text
            WHEN avg(d.heads) < req.headcount_required::numeric THEN 'below minimum'::text
            WHEN avg(d.heads) > req.headcount_required::numeric THEN 'above minimum'::text
            ELSE 'on minimum'::text
        END AS against_minimum
   FROM daily d
     LEFT JOIN LATERAL ( SELECT r.headcount_required
           FROM zone_staffing_requirements r
          WHERE r.department_id = d.department_id AND r.effective_from <= d.work_date AND (r.effective_to IS NULL OR r.effective_to >= d.work_date)
          ORDER BY r.effective_from DESC
         LIMIT 1) req ON true
  GROUP BY d.department_id, d.department, d.shift, req.headcount_required;
create or replace view public.v_document_links as
 SELECT p.tag AS key,
    'package'::text AS key_kind,
    p.item_name AS label,
    NULL::text AS coa_url,
        CASE
            WHEN (p.raw ->> 'LabTestingState'::text) = 'TestPassed'::text THEN (('Passed'::text || COALESCE(' on '::text || (((p.raw ->> 'LabTestingRecordedDate'::text)::date)::text), ''::text)) || COALESCE(', certificate valid to '::text || (((p.raw ->> 'LabTestResultExpirationDateTime'::text)::date)::text), ''::text)) || ' — the certificate document itself is not in the Metrc API. Import it, or fetch it from the laboratory.'::text
            WHEN (p.raw ->> 'LabTestingState'::text) = 'TestFailed'::text THEN ('FAILED'::text || COALESCE(' on '::text || (((p.raw ->> 'LabTestingRecordedDate'::text)::date)::text), ''::text)) || ' — obtain the certificate from the laboratory for the failing analyte.'::text
            WHEN (p.raw ->> 'LabTestingState'::text) = 'NotSubmitted'::text THEN 'Never submitted for testing — no certificate exists.'::text
            ELSE 'Awaiting result'::text || COALESCE(', submitted '::text || (((p.raw ->> 'LabTestingStateDate'::text)::date)::text), ''::text)
        END AS coa_label,
    t.manifest_link AS manifest_url,
        CASE
            WHEN t.manifest_number IS NOT NULL THEN ((((('Manifest '::text || t.manifest_number) || ' — '::text) || COALESCE(t.shipper, '?'::text)) || ' to '::text) || COALESCE(t.recipient, '?'::text)) || COALESCE(' on '::text || t.created_on::text, ''::text)
            ELSE NULL::text
        END AS manifest_label,
    NULLIF(p.raw ->> 'ReceivedFromManifestNumber'::text, ''::text) AS manifest_number
   FROM metrc_packages p
     LEFT JOIN v_metrc_transfer_ledger t ON t.manifest_number = NULLIF(p.raw ->> 'ReceivedFromManifestNumber'::text, ''::text)
UNION ALL
 SELECT t.manifest_number AS key,
    'manifest'::text AS key_kind,
    (COALESCE(t.shipper, ''::text) || ' to '::text) || COALESCE(t.recipient, ''::text) AS label,
    NULL::text AS coa_url,
    NULL::text AS coa_label,
    t.manifest_link AS manifest_url,
    (((('Manifest '::text || t.manifest_number) || ' — '::text) || COALESCE(t.packages::text, '?'::text)) || ' packages'::text) || COALESCE(' on '::text || t.created_on::text, ''::text) AS manifest_label,
    t.manifest_number
   FROM v_metrc_transfer_ledger t
UNION ALL
 SELECT h.name AS key,
    'harvest'::text AS key_kind,
    h.name AS label,
    NULL::text AS coa_url,
    NULL::text AS coa_label,
    t.manifest_link AS manifest_url,
    ('Manifest '::text || t.manifest_number) || ' carried packages from this harvest'::text AS manifest_label,
    t.manifest_number
   FROM metrc_harvests h
     JOIN mv_package_harvest mph ON mph.harvest_name = h.name
     JOIN metrc_packages p2 ON p2.id = mph.package_id
     JOIN v_metrc_transfer_ledger t ON t.manifest_number = NULLIF(p2.raw ->> 'ReceivedFromManifestNumber'::text, ''::text);
create or replace view public.v_document_package_link as
 SELECT d.id AS document_id,
    d.metrc_id,
    d.doc_type,
    d.package_tag,
    d.manifest_number,
    d.storage_path,
    'DIRECT'::text AS link_basis,
    0 AS link_depth
   FROM metrc_documents d
  WHERE d.doc_type = 'coa'::text AND d.package_tag IS NOT NULL
UNION ALL
 SELECT d.id AS document_id,
    d.metrc_id,
    d.doc_type,
    r.package_tag,
    d.manifest_number,
    d.storage_path,
    'INHERITED from '::text || r.certificate_on_package AS link_basis,
    r.found_at_depth AS link_depth
   FROM v_certificate_resolved r
     JOIN metrc_documents d ON d.doc_type = 'coa'::text AND d.package_tag = r.certificate_on_package
  WHERE r.found_at_depth > 0
UNION ALL
 SELECT d.id AS document_id,
    d.metrc_id,
    d.doc_type,
    r.package_tag,
    d.manifest_number,
    d.storage_path,
        CASE
            WHEN r.found_at_depth = 0 THEN 'LAB PAIRING'::text
            ELSE 'LAB PAIRING via '::text || r.certificate_on_package
        END AS link_basis,
    r.found_at_depth AS link_depth
   FROM v_certificate_resolved r
     JOIN metrc_lab_results l ON l.package_tag = r.certificate_on_package AND l.document_file_id IS NOT NULL
     JOIN metrc_documents d ON d.doc_type = 'coa'::text AND d.metrc_id = l.document_file_id
  WHERE NOT (EXISTS ( SELECT 1
           FROM metrc_documents d2
          WHERE d2.doc_type = 'coa'::text AND d2.package_tag = r.certificate_on_package))
UNION ALL
 SELECT d.id AS document_id,
    d.metrc_id,
    d.doc_type,
    t.package_tag,
    d.manifest_number,
    d.storage_path,
    'ON MANIFEST'::text AS link_basis,
    0 AS link_depth
   FROM metrc_documents d
     JOIN metrc_rpt_package_transfers t ON t.manifest_number = d.manifest_number
  WHERE d.doc_type = 'manifest'::text
UNION ALL
 SELECT d.id AS document_id,
    d.metrc_id,
    d.doc_type,
    p.tag AS package_tag,
    d.manifest_number,
    d.storage_path,
    'INBOUND on package record'::text AS link_basis,
    0 AS link_depth
   FROM metrc_documents d
     JOIN ( SELECT DISTINCT ON (metrc_packages.tag) metrc_packages.tag,
            metrc_packages.raw
           FROM metrc_packages
          ORDER BY metrc_packages.tag, metrc_packages.license) p ON NULLIF(p.raw ->> 'ReceivedFromManifestNumber'::text, ''::text) = d.manifest_number
  WHERE d.doc_type = 'manifest'::text;
create or replace view public.v_exposure as
 WITH tagged AS (
         SELECT f.finding_key,
            f.department,
            f.severity,
            f.severity_rank,
            f.pounds,
            f.dollars,
            f.what,
            "substring"(COALESCE(f.what, ''::text), '(M[0-9]{8,})'::text) AS package_tag
           FROM v_findings f
          WHERE f.state = 'open'::text AND NOT f.is_duplicate AND (f.pounds IS NOT NULL OR f.dollars IS NOT NULL)
        ), once_per_package AS (
         SELECT DISTINCT ON (tagged.package_tag) tagged.package_tag,
            tagged.department,
            tagged.severity,
            tagged.pounds,
            tagged.dollars,
            tagged.what
           FROM tagged
          WHERE tagged.package_tag IS NOT NULL
          ORDER BY tagged.package_tag, tagged.severity_rank, tagged.dollars DESC NULLS LAST
        )
 SELECT 'Physical stock flagged'::text AS measure,
    count(*)::numeric AS items,
    round(sum(once_per_package.pounds), 1) AS pounds,
    round(sum(once_per_package.dollars), 0) AS dollars,
    'Each package counted ONCE, at its most serious finding. This is real material we are holding.'::text AS means
   FROM once_per_package
UNION ALL
 SELECT 'Historical / aggregate findings'::text AS measure,
    count(*) AS items,
    round(sum(tagged.pounds), 1) AS pounds,
    round(sum(tagged.dollars), 0) AS dollars,
    'Waste and loss aggregates covering many harvests. NOT stock on hand - never add these to the line above.'::text AS means
   FROM tagged
  WHERE tagged.package_tag IS NULL
UNION ALL
 SELECT 'Naive sum of every finding (WRONG)'::text AS measure,
    count(*) AS items,
    round(sum(tagged.pounds), 1) AS pounds,
    round(sum(tagged.dollars), 0) AS dollars,
    'What you get by summing the column. Double counts packages and mixes history with stock. Shown so the error is visible, never to be quoted.'::text AS means
   FROM tagged;
create or replace view public.v_facility_live_map as
 SELECT 'Drying / Curing'::text AS area,
    m.room AS location,
    m.license,
    count(*)::numeric AS records,
    'harvests'::text AS record_type,
    round(sum(COALESCE(m.current_weight, m.wet_weight, 0::numeric)), 1) AS weight_on_hand,
    min(m.harvest_start) AS oldest_date,
    max(m.days_since_takedown)::numeric AS oldest_days,
    string_agg(DISTINCT m.stage, ' · '::text) AS stages,
    string_agg(DISTINCT m.strains, ', '::text) AS contents
   FROM v_harvest_stage_map m
  WHERE (m.stage <> ALL (ARRAY['Finished'::text, 'Archived'::text])) AND COALESCE(m.room, ''::text) <> ''::text
  GROUP BY 'Drying / Curing'::text, m.room, m.license
UNION ALL
 SELECT 'Packaged inventory'::text AS area,
    COALESCE(p.location, '(no location)'::text) AS location,
    p.license,
    count(*)::numeric AS records,
    'packages'::text AS record_type,
    round(sum(COALESCE(p.quantity, 0::numeric)), 1) AS weight_on_hand,
    min(p.packaged_on) AS oldest_date,
    max(CURRENT_DATE - p.packaged_on)::numeric AS oldest_days,
    string_agg(DISTINCT COALESCE(p.lab_testing_state, '—'::text), ' · '::text) AS stages,
    string_agg(DISTINCT p.item_name, ', '::text) AS contents
   FROM metrc_packages p
  WHERE p.source_state = ANY (ARRAY['active'::text, 'onhold'::text])
  GROUP BY 'Packaged inventory'::text, (COALESCE(p.location, '(no location)'::text)), p.license
UNION ALL
 SELECT 'In transit'::text AS area,
    COALESCE(p.location, '(manifested)'::text) AS location,
    p.license,
    count(*)::numeric AS records,
    'packages'::text AS record_type,
    round(sum(COALESCE(p.quantity, 0::numeric)), 1) AS weight_on_hand,
    min(p.packaged_on) AS oldest_date,
    max(CURRENT_DATE - p.packaged_on)::numeric AS oldest_days,
    'Leaving the facility'::text AS stages,
    string_agg(DISTINCT p.item_name, ', '::text) AS contents
   FROM metrc_packages p
  WHERE p.source_state = 'intransit'::text
  GROUP BY 'In transit'::text, (COALESCE(p.location, '(manifested)'::text)), p.license;
create or replace view public.v_facility_registry as
 WITH ranked AS (
         SELECT v_metrc_facility_names.facility_licence,
            v_metrc_facility_names.name_seen,
            v_metrc_facility_names.created_on,
            row_number() OVER (PARTITION BY v_metrc_facility_names.facility_licence ORDER BY v_metrc_facility_names.created_on DESC NULLS LAST) AS recency
           FROM v_metrc_facility_names
          WHERE v_metrc_facility_names.name_seen IS NOT NULL
        ), canon AS (
         SELECT ranked.facility_licence,
            max(ranked.name_seen) FILTER (WHERE ranked.recency = 1) AS facility_name,
            array_agg(DISTINCT ranked.name_seen ORDER BY ranked.name_seen) AS names_seen,
            count(DISTINCT ranked.name_seen) AS name_variants
           FROM ranked
          GROUP BY ranked.facility_licence
        )
 SELECT facility_licence,
    facility_name,
    f_facility_type(facility_licence) AS facility_type,
    f_company_key(facility_name) AS company_key,
    names_seen,
    name_variants,
    (((((facility_name || ' '::text) || array_to_string(names_seen, ' '::text)) || ' '::text) || facility_licence) || ' '::text) || f_facility_type(facility_licence) AS search_text
   FROM canon c;
create or replace view public.v_failed_by_maker as
 SELECT made_by,
    made_by_license,
    ours_or_theirs,
    failed_packages,
    failed_lb,
    earliest_created,
    latest_created,
    earliest_harvest,
    latest_harvest,
    strains,
    categories,
    value_at_cost,
    earliest_created AS earliest_created_date
   FROM ( SELECT v_failed_provenance.made_by,
            v_failed_provenance.made_by_license,
            v_failed_provenance.ours_or_theirs,
            count(*) AS failed_packages,
            round(sum(v_failed_provenance.pounds), 1) AS failed_lb,
            min(v_failed_provenance.package_created_on) AS earliest_created,
            max(v_failed_provenance.package_created_on) AS latest_created,
            min(v_failed_provenance.harvest_cut_on) AS earliest_harvest,
            max(v_failed_provenance.harvest_cut_on) AS latest_harvest,
            string_agg(DISTINCT v_failed_provenance.strain, ', '::text) AS strains,
            string_agg(DISTINCT v_failed_provenance.category, ', '::text) AS categories,
            round(sum(v_failed_provenance.pounds) * (( SELECT conversion_factors.value
                   FROM conversion_factors
                  WHERE conversion_factors.key = 'target_cost_per_lb'::text))) AS value_at_cost
           FROM v_failed_provenance
          GROUP BY v_failed_provenance.made_by, v_failed_provenance.made_by_license, v_failed_provenance.ours_or_theirs
          ORDER BY (round(sum(v_failed_provenance.pounds), 1)) DESC) q;
create or replace view public.v_failed_testing_by_origin as
 SELECT s.origin,
    s.supplier,
    s.origin_license,
    s.stream,
    s.license AS held_under,
    s.location,
    s.packages,
    s.pounds,
    s.oldest_days,
    s.strains,
    COALESCE(i.bought_as, 'unknown'::text) AS bought_as,
    round(s.pounds * (( SELECT conversion_factors.value
           FROM conversion_factors
          WHERE conversion_factors.key = 'target_cost_per_lb'::text))) AS value_at_our_cost,
        CASE
            WHEN s.origin = 'Grown by us'::text THEN 'OUR FAILURE - a genuine loss. We grew it, packaged it and it failed. Root cause is ours to find.'::text
            WHEN COALESCE(i.bought_as, 'unknown'::text) = 'failed for remediation'::text THEN 'BOUGHT FAILED ON PURPOSE - this is raw material, not a loss. It was purchased to remediate and process. Track the remediation yield, not the failure.'::text
            WHEN COALESCE(i.bought_as, 'unknown'::text) = 'biomass for extraction'::text THEN 'BIOMASS FOR EXTRACTION - bought to be processed, so a fail on flower testing may be irrelevant. Confirm the intended route.'::text
            WHEN COALESCE(i.bought_as, 'unknown'::text) = 'sound material'::text THEN ('SUPPLIER PROBLEM - we bought this as sound material and it failed. Raise it with '::text || s.supplier) || '.'::text
            ELSE 'INTENT NOT RECORDED - we cannot tell whether this was bought sound and failed, or bought failed on purpose to remediate. Set it on the Purchase Intent page before treating it as a loss.'::text
        END AS whose_problem,
        CASE
            WHEN s.origin = 'Grown by us'::text THEN 'Find the root cause, then decide remediate or destroy and record it in Metrc.'::text
            WHEN COALESCE(i.bought_as, 'unknown'::text) = 'failed for remediation'::text THEN 'Move it into remediation and record what comes out the other side.'::text
            WHEN COALESCE(i.bought_as, 'unknown'::text) = 'sound material'::text THEN 'Raise it with the supplier with the package tags and the certificate.'::text
            ELSE ('Set the purchase intent for '::text || COALESCE(s.supplier, 'this supplier'::text)) || ' so this stops being ambiguous.'::text
        END AS what_to_do
   FROM v_stock_on_hand s
     LEFT JOIN purchase_intent i ON i.origin_license = s.origin_license
  WHERE s.lab_state = 'TestFailed'::text
  ORDER BY s.pounds DESC;
create or replace view public.v_findings_live as
 SELECT f.finding_key,
    f.source,
    f.department,
    f.severity,
    f.what,
    f.where_it_is,
    f.who_is_accountable,
    f.why_it_matters,
    f.what_to_do,
    f.the_arithmetic,
    f.how_it_was_detected,
    f.when_it_started,
    f.evidence,
    f.record_count,
    f.pounds,
    f.dollars,
    f.first_raised,
    f.last_seen,
    f.times_seen,
    f.resolved_at,
    f.resolution_note,
    f.fingerprint,
    f.pattern_key,
    f.drill,
    f.state,
    f.severity_rank,
    f.occurrences_6mo,
    f.priority_band,
    f.canonical_key,
    f.is_duplicate,
    f.duplicate_of,
    COALESCE(fs.state, 'open'::text) AS work_state,
    COALESCE(o.owner_name, fs.owner_name, 'UNOWNED'::text) AS owner_name,
    o.escalates_to,
    fs.note AS work_note,
    fs.suppress_until,
    COALESCE(fs.state, 'open'::text) = 'suppressed'::text AND COALESCE(fs.suppress_until, CURRENT_DATE) >= CURRENT_DATE AS currently_suppressed,
    (f.department || ' · '::text) ||
        CASE
            WHEN POSITION((':'::text) IN (COALESCE(f.what, ''::text))) > 0 THEN btrim(split_part(f.what, ':'::text, 1))
            ELSE "left"(COALESCE(f.what, '(no description)'::text), 40)
        END AS group_key
   FROM v_findings f
     LEFT JOIN finding_state fs ON fs.finding_key = f.finding_key
     LEFT JOIN finding_owners o ON o.department = f.department;
create or replace view public.v_findings_priced as
 SELECT finding_key,
    source,
    department,
    severity,
    what,
    where_it_is,
    who_is_accountable,
    why_it_matters,
    what_to_do,
    the_arithmetic,
    how_it_was_detected,
    when_it_started,
    evidence,
    record_count,
    pounds,
    dollars,
    first_raised,
    last_seen,
    times_seen,
    resolved_at,
    resolution_note,
    fingerprint,
    pattern_key,
    drill,
    state,
    severity_rank,
    occurrences_6mo,
    priority_band,
    canonical_key,
    is_duplicate,
    duplicate_of,
    COALESCE(dollars, (( SELECT f_price_per_lb.rate
           FROM f_price_per_lb(f.department) f_price_per_lb(rate, basis)
         LIMIT 1)) * pounds) AS value_dollars,
        CASE
            WHEN dollars IS NOT NULL THEN 'valued by the agent that raised it'::text
            WHEN pounds IS NOT NULL THEN ( SELECT f_price_per_lb.basis
               FROM f_price_per_lb(f.department) f_price_per_lb(rate, basis)
             LIMIT 1)
            ELSE 'CANNOT BE PRICED — no dollars and no pounds recorded'::text
        END AS value_basis,
    dollars IS NULL AND pounds IS NULL AS unpriceable
   FROM v_findings f;
create or replace view public.v_flow_failed_split as
 SELECT round(sum(pounds) FILTER (WHERE origin_license = ANY (ARRAY['MC281714'::text, 'MP281909'::text])), 1) AS failed_ours_lb,
    round(sum(pounds) FILTER (WHERE origin_license IS NULL OR (origin_license <> ALL (ARRAY['MC281714'::text, 'MP281909'::text]))), 1) AS failed_third_party_lb,
    count(*) FILTER (WHERE origin_license = ANY (ARRAY['MC281714'::text, 'MP281909'::text])) AS failed_ours_packages,
    count(*) FILTER (WHERE origin_license IS NULL OR (origin_license <> ALL (ARRAY['MC281714'::text, 'MP281909'::text]))) AS failed_third_party_packages,
    COALESCE(string_agg(DISTINCT supplier, ', '::text) FILTER (WHERE origin_license IS NULL OR (origin_license <> ALL (ARRAY['MC281714'::text, 'MP281909'::text]))), 'none'::text) AS third_party_suppliers,
    max(oldest_days) AS oldest_days
   FROM v_stock_on_hand
  WHERE lab_state = 'TestFailed'::text;
create or replace view public.v_fresh_frozen_equiv as
 SELECT origin,
    supplier,
    license,
    location,
    lab_state,
    packages,
    frozen_lb,
    dry_equivalent_lb,
    ratio_used,
    oldest_days,
    oldest_packaged,
    strains,
    the_arithmetic,
    why,
    oldest_packaged AS oldest_packaged_date
   FROM ( WITH f AS (
                 SELECT conversion_factors.value AS r
                   FROM conversion_factors
                  WHERE conversion_factors.key = 'fresh_frozen_wet_to_dry'::text
                )
         SELECT s.origin,
            s.supplier,
            s.license,
            s.location,
            s.lab_state,
            s.packages,
            s.pounds AS frozen_lb,
            round(s.pounds / (( SELECT f.r
                   FROM f)), 1) AS dry_equivalent_lb,
            ( SELECT f.r
                   FROM f) AS ratio_used,
            s.oldest_days,
            s.oldest_packaged,
            s.strains,
            ((((round(s.pounds, 1) || ' lb frozen / '::text) || (( SELECT f.r
                   FROM f))) || ' = '::text) || round(s.pounds / (( SELECT f.r
                   FROM f)), 1)) || ' lb dry-equivalent'::text AS the_arithmetic,
            'Fresh frozen still contains its water. Only the dry-equivalent figure may be compared with, or added to, dried flower.'::text AS why
           FROM v_stock_on_hand s
          WHERE s.stream = 'Fresh frozen'::text
          ORDER BY s.pounds DESC) q;
create or replace view public.v_guard_queue as
 SELECT 'overdue'::text AS queue,
    10 AS rank,
    s.finding_key AS subject,
    COALESCE(f.what, s.finding_key) AS detail,
    s.owning_agent AS owner,
    s.due_by AS since,
    round(EXTRACT(epoch FROM now() - s.due_by) / 3600::numeric)::integer AS hours,
    'past its deadline and still open'::text AS why
   FROM finding_state s
     LEFT JOIN v_findings f ON f.finding_key = s.finding_key
  WHERE (s.state = ANY (ARRAY['open'::text, 'acknowledged'::text, 'in_progress'::text])) AND s.due_by < now()
UNION ALL
 SELECT 'awaiting second check'::text AS queue,
    20 AS rank,
    c.finding_key AS subject,
    "left"(c.claim, 160) AS detail,
    c.proposed_by AS owner,
    c.proposed_at AS since,
    round(EXTRACT(epoch FROM now() - c.proposed_at) / 3600::numeric)::integer AS hours,
    ('proposed by '::text || c.proposed_by) || ', needs a DIFFERENT agent to derive it another way'::text AS why
   FROM finding_closure c
  WHERE c.verdict = 'pending'::text
UNION ALL
 SELECT
        CASE
            WHEN c.verdict = 'withdrawn'::text THEN 'closure WITHDRAWN'::text
            ELSE 'second check DISAGREED'::text
        END AS queue,
        CASE
            WHEN c.verdict = 'withdrawn'::text THEN 12
            ELSE 5
        END AS rank,
    c.finding_key AS subject,
    "left"(COALESCE(c.verdict_note, c.claim), 160) AS detail,
    COALESCE(c.second_by, c.proposed_by) AS owner,
    COALESCE(c.second_at, c.proposed_at) AS since,
    round(EXTRACT(epoch FROM now() - COALESCE(c.second_at, c.proposed_at)) / 3600::numeric)::integer AS hours,
        CASE
            WHEN c.verdict = 'withdrawn'::text THEN c.proposed_by || ' retracted its own closure; the finding is still open'::text
            ELSE ((c.proposed_by || ' claimed this was resolved and '::text) || COALESCE(c.second_by, 'the checker'::text)) || ' could not confirm it'::text
        END AS why
   FROM finding_closure c
  WHERE c.verdict = ANY (ARRAY['disagrees'::text, 'insufficient'::text, 'withdrawn'::text])
UNION ALL
 SELECT 'closed WITHOUT verification'::text AS queue,
    15 AS rank,
    s.finding_key AS subject,
    "left"(COALESCE(s.override_reason, ''::text), 160) AS detail,
    COALESCE(s.override_by, '?'::text) AS owner,
    s.override_at AS since,
    round(EXTRACT(epoch FROM now() - COALESCE(s.override_at, s.changed_at)) / 3600::numeric)::integer AS hours,
    'administrator override: closed with no independent check behind it'::text AS why
   FROM finding_state s
  WHERE s.override_reason IS NOT NULL
UNION ALL
 SELECT 'check has a known defect'::text AS queue,
    8 AS rank,
    d.check_key AS subject,
    "left"((d.claimed || ' -- actually: '::text) || d.actually, 160) AS detail,
    d.found_by AS owner,
    d.found_at AS since,
    round(EXTRACT(epoch FROM now() - d.found_at) / 3600::numeric)::integer AS hours,
    ((d.defect_kind || ' causing '::text) || d.impact) || '; every reading from this check is suspect until fixed'::text AS why
   FROM check_defect d
  WHERE d.fixed_at IS NULL
UNION ALL
 SELECT 'check never proven to fail'::text AS queue,
    40 AS rank,
    c.checker_key AS subject,
    COALESCE(c.title, c.checker_key) AS detail,
    COALESCE(c.runs_where, '?'::text) AS owner,
    NULL::timestamp with time zone AS since,
    NULL::integer AS hours,
    'no fixture demonstrates this check failing, so nothing shows it would catch the thing it watches'::text AS why
   FROM checker_registry c
  WHERE c.enabled AND NOT COALESCE(c.fixture_proves_it_fails, false)
UNION ALL
 SELECT 'route has no human owner'::text AS queue,
    50 AS rank,
    r.route_key AS subject,
    (r.route_key || ' -> '::text) || r.owning_agent AS detail,
    r.owning_agent AS owner,
    NULL::timestamp with time zone AS since,
    NULL::integer AS hours,
    'findings on this route reach an agent but escalate to nobody named'::text AS why
   FROM finding_route r
  WHERE r.enabled AND COALESCE(r.human_owner, ''::text) = ''::text;
create or replace view public.v_harvest_alerts as
 WITH r AS (
         SELECT harvest_alert_rules.rule_key,
            harvest_alert_rules.label,
            harvest_alert_rules.threshold,
            harvest_alert_rules.severity
           FROM harvest_alert_rules
          WHERE harvest_alert_rules.active
        )
 SELECT m.license,
    m.harvest,
    m.room,
    'Drying'::text AS area,
        CASE
            WHEN m.days_since_takedown::numeric > (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'dry_max_days'::text)) THEN ( SELECT r.severity
               FROM r
              WHERE r.rule_key = 'dry_max_days'::text)
            ELSE ( SELECT r.severity
               FROM r
              WHERE r.rule_key = 'dry_target_days'::text)
        END AS severity,
        CASE
            WHEN m.days_since_takedown::numeric > (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'dry_max_days'::text)) THEN ((('Dry window exceeded - day '::text || m.days_since_takedown) || ' of a '::text) || (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'dry_max_days'::text))::integer) || '-day limit'::text
            ELSE 'Dry target reached - day '::text || m.days_since_takedown
        END AS alert,
    m.days_since_takedown::numeric AS value,
    m.stage,
    m.harvest_start AS reference_date
   FROM v_harvest_stage_map m
  WHERE m.stage ~~ 'Drying%'::text AND m.days_since_takedown::numeric >= (( SELECT r.threshold
           FROM r
          WHERE r.rule_key = 'dry_target_days'::text))
UNION ALL
 SELECT m.license,
    m.harvest,
    m.room,
    'Weight reporting'::text AS area,
    ( SELECT r.severity
           FROM r
          WHERE r.rule_key = 'weights_due_days'::text) AS severity,
    ('No weights reported '::text || m.days_since_takedown) || ' days after takedown'::text AS alert,
    m.days_since_takedown::numeric AS value,
    m.stage,
    m.harvest_start AS reference_date
   FROM v_harvest_stage_map m
  WHERE COALESCE(m.wet_weight, 0::numeric) = 0::numeric AND m.days_since_takedown::numeric >= (( SELECT r.threshold
           FROM r
          WHERE r.rule_key = 'weights_due_days'::text))
UNION ALL
 SELECT m.license,
    m.harvest,
    m.room,
    'Cycle'::text AS area,
    ( SELECT r.severity
           FROM r
          WHERE r.rule_key = 'cure_max_days'::text) AS severity,
    ('Still unfinished '::text || m.days_since_takedown) || ' days after takedown - the next pull for this room is at risk'::text AS alert,
    m.days_since_takedown::numeric AS value,
    m.stage,
    m.harvest_start AS reference_date
   FROM v_harvest_stage_map m
  WHERE (m.stage <> ALL (ARRAY['Finished'::text, 'Archived'::text])) AND m.days_since_takedown::numeric > (( SELECT r.threshold
           FROM r
          WHERE r.rule_key = 'cure_max_days'::text))
UNION ALL
 SELECT m.license,
    m.harvest,
    m.room,
    'Waste'::text AS area,
    ( SELECT r.severity
           FROM r
          WHERE r.rule_key = 'waste_pct_max'::text) AS severity,
    ((('Waste at '::text || m.waste_pct) || ' percent of wet weight - above the '::text) || (( SELECT r.threshold
           FROM r
          WHERE r.rule_key = 'waste_pct_max'::text))::integer) || ' percent limit'::text AS alert,
    m.waste_pct AS value,
    m.stage,
    m.harvest_start AS reference_date
   FROM v_harvest_stage_map m
  WHERE m.waste_pct > (( SELECT r.threshold
           FROM r
          WHERE r.rule_key = 'waste_pct_max'::text))
UNION ALL
 SELECT m.license,
    m.harvest,
    m.room,
    'Yield'::text AS area,
    ( SELECT r.severity
           FROM r
          WHERE r.rule_key = 'yield_pct_min'::text) AS severity,
    ((('Yield at '::text || m.yield_pct) || ' percent of wet weight - below the '::text) || (( SELECT r.threshold
           FROM r
          WHERE r.rule_key = 'yield_pct_min'::text))::integer) || ' percent floor'::text AS alert,
    m.yield_pct AS value,
    m.stage,
    m.harvest_start AS reference_date
   FROM v_harvest_stage_map m
  WHERE COALESCE(m.packaged_weight, 0::numeric) > 0::numeric AND m.yield_pct < (( SELECT r.threshold
           FROM r
          WHERE r.rule_key = 'yield_pct_min'::text))
UNION ALL
 SELECT 'MC281714'::text AS license,
    'Pull #'::text || p.pull_no AS harvest,
    p.flower_room AS room,
    'Planner'::text AS area,
    ( SELECT r.severity
           FROM r
          WHERE r.rule_key = 'pull_overdue_days'::text) AS severity,
    ((('Planned pull on '::text || p.harvest_date) || ' has no harvest recorded - '::text) || (CURRENT_DATE - p.harvest_date)) || ' days late'::text AS alert,
    (CURRENT_DATE - p.harvest_date)::numeric AS value,
    'Planned'::text AS stage,
    p.harvest_date AS reference_date
   FROM harvest_pulls p
  WHERE p.harvest_date < (CURRENT_DATE - (( SELECT r.threshold
           FROM r
          WHERE r.rule_key = 'pull_overdue_days'::text))::integer) AND NOT (EXISTS ( SELECT 1
           FROM metrc_harvests h
          WHERE h.harvest_start >= (p.harvest_date - 3) AND h.harvest_start <= (p.harvest_date + 7)));
create or replace view public.v_harvest_economics as
 SELECT harvest,
    strain,
    room,
    harvest_start,
    plants,
    wet_lbs,
    packaged_lbs,
    waste_lbs,
    waste_pct,
    yield_pct,
    cost_per_pound,
    cost_to_grow,
    cost_lost_to_waste,
    true_cost_per_saleable_pound,
    stage,
    harvest_start AS harvest_start_date
   FROM ( SELECT m.harvest,
            m.strains AS strain,
            m.room,
            m.harvest_start,
            m.plants,
            round(COALESCE(m.wet_weight, 0::numeric) / 453.592, 1) AS wet_lbs,
            round(COALESCE(m.packaged_weight, 0::numeric) / 453.592, 1) AS packaged_lbs,
            round(COALESCE(m.waste_weight, 0::numeric) / 453.592, 1) AS waste_lbs,
            m.waste_pct,
            m.yield_pct,
            ( SELECT cost_model.cost_per_pound
                   FROM cost_model
                  WHERE cost_model.scope = 'cultivation'::text
                  ORDER BY cost_model.effective_from DESC
                 LIMIT 1) AS cost_per_pound,
            round(COALESCE(m.wet_weight, 0::numeric) / 453.592 * (( SELECT cost_model.cost_per_pound
                   FROM cost_model
                  WHERE cost_model.scope = 'cultivation'::text
                  ORDER BY cost_model.effective_from DESC
                 LIMIT 1)), 0) AS cost_to_grow,
            round(COALESCE(m.waste_weight, 0::numeric) / 453.592 * (( SELECT cost_model.cost_per_pound
                   FROM cost_model
                  WHERE cost_model.scope = 'cultivation'::text
                  ORDER BY cost_model.effective_from DESC
                 LIMIT 1)), 0) AS cost_lost_to_waste,
                CASE
                    WHEN COALESCE(m.packaged_weight, 0::numeric) > 0::numeric THEN round(COALESCE(m.wet_weight, 0::numeric) / 453.592 * (( SELECT cost_model.cost_per_pound
                       FROM cost_model
                      WHERE cost_model.scope = 'cultivation'::text
                      ORDER BY cost_model.effective_from DESC
                     LIMIT 1)) / (COALESCE(m.packaged_weight, 0::numeric) / 453.592), 0)
                    ELSE NULL::numeric
                END AS true_cost_per_saleable_pound,
            m.stage
           FROM v_harvest_stage_map m
          WHERE COALESCE(m.wet_weight, 0::numeric) > 0::numeric
          ORDER BY m.harvest_start DESC NULLS LAST) q;
create or replace view public.v_harvest_lifecycle as
 WITH a AS (
         SELECT h.license,
            h.name AS harvest,
            COALESCE(h.raw ->> 'SourceStrainNames'::text, h.name) AS strain,
            COALESCE(h.raw ->> 'DryingLocationName'::text, '(no room)'::text) AS room,
            h.harvest_start AS takedown_actual,
            (h.raw ->> 'FinishedDate'::text)::date AS finished_actual,
            COALESCE((h.raw ->> 'PlantCount'::text)::numeric, 0::numeric) AS plants,
            COALESCE((h.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric) AS wet_g,
            COALESCE((h.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric) AS waste_g,
            COALESCE((h.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) AS packaged_g,
            h.raw ->> 'LabTestingState'::text AS lab_state
           FROM metrc_harvests h
          WHERE h.harvest_start IS NOT NULL
        ), p AS (
         SELECT pl.pull_no,
            pl.harvest_date AS planned_date,
            pl.flower_room,
            pl.cultivars,
            pl.dry_start AS planned_dry_start,
            pl.dry_day_10 AS planned_dry_target,
            pl.dry_day_14 AS planned_dry_deadline,
            pl.day2_replant_date AS planned_replant,
            pl.proj_harvest_weight_lbs AS planned_lbs,
            pl.original_total_plants AS planned_plants
           FROM harvest_pulls pl
        ), r AS (
         SELECT harvest_alert_rules.threshold,
            harvest_alert_rules.rule_key
           FROM harvest_alert_rules
          WHERE harvest_alert_rules.active
        )
 SELECT a.harvest,
    a.strain,
    a.room,
    a.license,
    p.pull_no AS planned_pull,
    p.planned_date,
    p.planned_plants,
    round(COALESCE(p.planned_lbs, 0::numeric), 1) AS planned_lbs,
    a.takedown_actual,
        CASE
            WHEN p.planned_date IS NULL THEN 'No matching plan'::text
            WHEN a.takedown_actual > p.planned_date THEN ('LATE by '::text || (a.takedown_actual - p.planned_date)) || ' days'::text
            WHEN a.takedown_actual < p.planned_date THEN ('Early by '::text || (p.planned_date - a.takedown_actual)) || ' days'::text
            ELSE 'On the planned date'::text
        END AS takedown_status,
    a.plants AS actual_plants,
        CASE
            WHEN p.planned_plants > 0::numeric THEN round(100.0 * a.plants / p.planned_plants, 1)
            ELSE NULL::numeric
        END AS plants_pct_of_plan,
    CURRENT_DATE - a.takedown_actual AS days_since_takedown,
    a.takedown_actual + (( SELECT r.threshold
           FROM r
          WHERE r.rule_key = 'dry_target_days'::text))::integer AS dry_target_date,
    a.takedown_actual + (( SELECT r.threshold
           FROM r
          WHERE r.rule_key = 'dry_max_days'::text))::integer AS dry_deadline_date,
        CASE
            WHEN a.finished_actual IS NOT NULL THEN 'Dry complete on '::text || a.finished_actual
            WHEN (CURRENT_DATE - a.takedown_actual)::numeric > (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'dry_max_days'::text)) THEN (('DRY DEADLINE BLOWN - day '::text || (CURRENT_DATE - a.takedown_actual)) || ' of '::text) || (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'dry_max_days'::text))::integer
            WHEN (CURRENT_DATE - a.takedown_actual)::numeric >= (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'dry_target_days'::text)) THEN ('At dry target - day '::text || (CURRENT_DATE - a.takedown_actual)) || ', finish it'::text
            ELSE 'Drying on track - day '::text || (CURRENT_DATE - a.takedown_actual)
        END AS drying_status,
        CASE
            WHEN a.wet_g > 0::numeric THEN 'Reported'::text
            WHEN (CURRENT_DATE - a.takedown_actual)::numeric >= (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'weights_due_days'::text)) THEN ('WEIGHTS NOT REPORTED - '::text || (CURRENT_DATE - a.takedown_actual)) || ' days after takedown'::text
            ELSE ('Due within '::text || ((( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'weights_due_days'::text))::integer - (CURRENT_DATE - a.takedown_actual))) || ' days'::text
        END AS weights_status,
    round(a.wet_g / 453.592, 1) AS wet_lbs,
    round(a.waste_g / 453.592, 1) AS waste_lbs,
        CASE
            WHEN a.wet_g > 0::numeric THEN round(100.0 * a.waste_g / a.wet_g, 1)
            ELSE NULL::numeric
        END AS waste_pct,
    round(a.packaged_g / 453.592, 1) AS packaged_lbs,
        CASE
            WHEN a.wet_g > 0::numeric THEN round(100.0 * a.packaged_g / a.wet_g, 1)
            ELSE NULL::numeric
        END AS yield_pct,
        CASE
            WHEN COALESCE(p.planned_lbs, 0::numeric) > 0::numeric THEN round(a.packaged_g / 453.592 - p.planned_lbs, 1)
            ELSE NULL::numeric
        END AS lbs_vs_plan,
    ( SELECT count(*) AS count
           FROM mv_package_harvest k
          WHERE k.harvest_name = a.harvest) AS packages_made,
    ( SELECT count(*) AS count
           FROM allocation_requests ar
          WHERE ar.source_ref ~~* (('%'::text || a.harvest) || '%'::text) OR ar.strain ~~* (('%'::text || a.strain) || '%'::text)) AS allocation_requests,
    ( SELECT string_agg(DISTINCT ((((ar.requester_name || ' -> '::text) || COALESCE(ar.decider_name, 'awaiting decision'::text)) || ' ('::text) || ar.status) || ')'::text, '; '::text) AS string_agg
           FROM allocation_requests ar
          WHERE ar.source_ref ~~* (('%'::text || a.harvest) || '%'::text) OR ar.strain ~~* (('%'::text || a.strain) || '%'::text)) AS allocation_chain,
    ( SELECT count(*) AS count
           FROM mv_package_harvest k
             JOIN metrc_packages p2 ON p2.id = k.package_id
          WHERE k.harvest_name = a.harvest AND p2.source_state = 'intransit'::text) AS packages_shipped,
    a.lab_state,
        CASE
            WHEN a.finished_actual IS NULL AND (CURRENT_DATE - a.takedown_actual)::numeric > (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'dry_max_days'::text)) THEN 'BLOCKING THE ROOM'::text
            WHEN a.wet_g = 0::numeric AND (CURRENT_DATE - a.takedown_actual)::numeric >= (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'weights_due_days'::text)) THEN 'MISSING WEIGHTS'::text
            WHEN p.planned_date IS NOT NULL AND a.takedown_actual > (p.planned_date + 2) THEN 'HARVESTED LATE'::text
            WHEN a.wet_g > 0::numeric AND (100.0 * a.waste_g / NULLIF(a.wet_g, 0::numeric)) > (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'waste_pct_max'::text)) THEN 'EXCESS WASTE'::text
            WHEN a.finished_actual IS NOT NULL THEN 'Complete'::text
            ELSE 'On track'::text
        END AS verdict
   FROM a
     LEFT JOIN p ON p.flower_room = a.room AND a.takedown_actual >= (p.planned_date - 4) AND a.takedown_actual <= (p.planned_date + 10)
  ORDER BY (
        CASE
            WHEN a.finished_actual IS NULL THEN 0
            ELSE 1
        END), a.takedown_actual DESC;
create or replace view public.v_harvest_lineage_summary as
 SELECT harvest,
    license,
    room,
    stage,
    strains,
    plants,
    wet_weight,
    waste_weight,
    packaged_weight,
    waste_pct,
    yield_pct,
    days_since_takedown,
    ( SELECT count(*) AS count
           FROM metrc_packages p
          WHERE COALESCE(p.raw ->> 'SourceHarvestNames'::text, ''::text) ~~* (('%'::text || m.harvest) || '%'::text)) AS packages_made,
    ( SELECT count(*) AS count
           FROM metrc_packages p
          WHERE COALESCE(p.raw ->> 'SourceHarvestNames'::text, ''::text) ~~* (('%'::text || m.harvest) || '%'::text) AND p.lab_testing_state = 'TestPassed'::text) AS packages_passed,
    ( SELECT count(*) AS count
           FROM metrc_packages p
          WHERE COALESCE(p.raw ->> 'SourceHarvestNames'::text, ''::text) ~~* (('%'::text || m.harvest) || '%'::text) AND p.source_state = 'intransit'::text) AS packages_shipped,
    ( SELECT round(sum(COALESCE(p.quantity, 0::numeric)), 1) AS round
           FROM metrc_packages p
          WHERE COALESCE(p.raw ->> 'SourceHarvestNames'::text, ''::text) ~~* (('%'::text || m.harvest) || '%'::text) AND (p.source_state = ANY (ARRAY['active'::text, 'onhold'::text]))) AS quantity_on_hand
   FROM v_harvest_stage_map m;
create or replace view public.v_inventory_locator as
 SELECT 'Plants'::text AS category,
    1 AS stage_no,
    'Growing'::text AS stage,
    pl.room AS location,
    pl.license,
    pl.strain AS item,
    pl.tag AS identifier,
    count(*)::numeric AS quantity,
    'plants'::text AS uom,
    min(pl.planted_on) AS since_date,
    max(CURRENT_DATE - pl.planted_on)::numeric AS days_here,
    string_agg(DISTINCT pl.phase, ' · '::text) AS detail,
    NULL::text AS lab_state,
    NULL::text AS source_lineage
   FROM metrc_plants pl
  WHERE pl.source_state = ANY (ARRAY['vegetative'::text, 'flowering'::text, 'onhold'::text])
  GROUP BY 'Plants'::text, 1::integer, 'Growing'::text, pl.room, pl.license, pl.strain, pl.tag
UNION ALL
 SELECT 'Plant batches'::text AS category,
    1 AS stage_no,
    'Propagation'::text AS stage,
    'Propagation area'::text AS location,
    pb.license,
    pb.strain AS item,
    pb.name AS identifier,
    COALESCE(pb.count, 0)::numeric AS quantity,
    'plants'::text AS uom,
    pb.planted_on AS since_date,
    (CURRENT_DATE - pb.planted_on)::numeric AS days_here,
    COALESCE(pb.batch_type, 'batch'::text) AS detail,
    NULL::text AS lab_state,
    NULL::text AS source_lineage
   FROM metrc_plant_batches pb
  WHERE pb.source_state = 'active'::text
UNION ALL
 SELECT 'Harvest lots'::text AS category,
    2 AS stage_no,
    m.stage,
    COALESCE(m.room, '(no room recorded)'::text) AS location,
    m.license,
    COALESCE(m.strains, m.harvest) AS item,
    m.harvest AS identifier,
    round(COALESCE(m.current_weight, m.wet_weight, 0::numeric), 1) AS quantity,
    COALESCE(m.uom, 'g'::text) AS uom,
    m.harvest_start AS since_date,
    m.days_since_takedown::numeric AS days_here,
    COALESCE(m.sub_room, m.harvest_type, 'harvest'::text) AS detail,
    m.lab_state,
    m.harvest AS source_lineage
   FROM v_harvest_stage_map m
  WHERE m.stage <> ALL (ARRAY['Finished'::text, 'Archived'::text])
UNION ALL
 SELECT 'Packages'::text AS category,
    3 AS stage_no,
        CASE
            WHEN (p.raw ->> 'IsOnHold'::text)::boolean THEN 'ON HOLD'::text
            WHEN p.lab_testing_state = 'TestFailed'::text THEN 'FAILED TESTING'::text
            WHEN p.lab_testing_state = 'TestPassed'::text THEN 'Sellable'::text
            WHEN p.lab_testing_state = ANY (ARRAY['SubmittedForTesting'::text, 'AwaitingConfirmation'::text]) THEN 'Awaiting laboratory'::text
            ELSE 'In inventory'::text
        END AS stage,
    COALESCE(p.location, '(no location)'::text) AS location,
    p.license,
    COALESCE(p.item_name, '(unnamed item)'::text) AS item,
    p.tag AS identifier,
    COALESCE(p.quantity, 0::numeric) AS quantity,
    COALESCE(p.uom, 'ea'::text) AS uom,
    p.packaged_on AS since_date,
    (CURRENT_DATE - p.packaged_on)::numeric AS days_here,
    COALESCE(p.raw ->> 'ProductCategoryName'::text, 'package'::text) AS detail,
    p.lab_testing_state AS lab_state,
    NULLIF(p.raw ->> 'SourceHarvestNames'::text, ''::text) AS source_lineage
   FROM metrc_packages p
  WHERE p.source_state = ANY (ARRAY['active'::text, 'onhold'::text])
UNION ALL
 SELECT 'In transit'::text AS category,
    4 AS stage_no,
    'Leaving the facility'::text AS stage,
    COALESCE(p.location, '(manifested)'::text) AS location,
    p.license,
    COALESCE(p.item_name, '(unnamed item)'::text) AS item,
    p.tag AS identifier,
    COALESCE(p.quantity, 0::numeric) AS quantity,
    COALESCE(p.uom, 'ea'::text) AS uom,
    p.packaged_on AS since_date,
    (CURRENT_DATE - p.packaged_on)::numeric AS days_here,
    'On a transfer manifest'::text AS detail,
    p.lab_testing_state AS lab_state,
    NULLIF(p.raw ->> 'SourceHarvestNames'::text, ''::text) AS source_lineage
   FROM metrc_packages p
  WHERE p.source_state = 'intransit'::text;
create or replace view public.v_issue_attribution as
 WITH failed AS (
         SELECT 'Failed testing'::text AS issue,
            v_stock_on_hand.origin,
            v_stock_on_hand.supplier,
            v_stock_on_hand.stream,
            v_stock_on_hand.packages AS items,
            v_stock_on_hand.pounds,
            round(v_stock_on_hand.pounds * (( SELECT conversion_factors.value
                   FROM conversion_factors
                  WHERE conversion_factors.key = 'target_cost_per_lb'::text))) AS dollars
           FROM v_stock_on_hand
          WHERE v_stock_on_hand.lab_state = 'TestFailed'::text
        ), aged AS (
         SELECT 'Sitting over 180 days'::text AS issue,
            v_stock_on_hand.origin,
            v_stock_on_hand.supplier,
            v_stock_on_hand.stream,
            v_stock_on_hand.packages,
            v_stock_on_hand.pounds,
            round(v_stock_on_hand.pounds * (( SELECT conversion_factors.value
                   FROM conversion_factors
                  WHERE conversion_factors.key = 'target_cost_per_lb'::text))) AS dollars
           FROM v_stock_on_hand
          WHERE v_stock_on_hand.oldest_days > 180
        ), untested AS (
         SELECT 'Never submitted for testing'::text AS issue,
            v_stock_on_hand.origin,
            v_stock_on_hand.supplier,
            v_stock_on_hand.stream,
            v_stock_on_hand.packages,
            v_stock_on_hand.pounds,
            round(v_stock_on_hand.pounds * (( SELECT conversion_factors.value
                   FROM conversion_factors
                  WHERE conversion_factors.key = 'target_cost_per_lb'::text))) AS dollars
           FROM v_stock_on_hand
          WHERE v_stock_on_hand.lab_state = 'NotSubmitted'::text
        ), nosupplier AS (
         SELECT 'Bought in with no supplier recorded'::text AS issue,
            v_stock_on_hand.origin,
            v_stock_on_hand.supplier,
            v_stock_on_hand.stream,
            v_stock_on_hand.packages,
            v_stock_on_hand.pounds,
            NULL::numeric AS dollars
           FROM v_stock_on_hand
          WHERE v_stock_on_hand.origin = 'Bought in'::text AND v_stock_on_hand.supplier = '(supplier not recorded)'::text
        )
 SELECT issue,
    origin,
    supplier,
    stream,
    items,
    pounds,
    dollars,
        CASE
            WHEN origin = 'Grown by us'::text THEN 'Ours to fix'::text
            ELSE 'Raise with '::text || supplier
        END AS accountable
   FROM ( SELECT failed.issue,
            failed.origin,
            failed.supplier,
            failed.stream,
            failed.items,
            failed.pounds,
            failed.dollars
           FROM failed
        UNION ALL
         SELECT aged.issue,
            aged.origin,
            aged.supplier,
            aged.stream,
            aged.packages,
            aged.pounds,
            aged.dollars
           FROM aged
        UNION ALL
         SELECT untested.issue,
            untested.origin,
            untested.supplier,
            untested.stream,
            untested.packages,
            untested.pounds,
            untested.dollars
           FROM untested
        UNION ALL
         SELECT nosupplier.issue,
            nosupplier.origin,
            nosupplier.supplier,
            nosupplier.stream,
            nosupplier.packages,
            nosupplier.pounds,
            nosupplier.dollars
           FROM nosupplier) x
  ORDER BY dollars DESC NULLS LAST, pounds DESC;
create or replace view public.v_issue_real_loss as
 SELECT loss_type,
    scope,
    location,
    units,
    unit_label,
    pounds,
    round(COALESCE(pounds, 0::numeric) * (( SELECT cost_model.cost_per_pound
           FROM cost_model
          WHERE cost_model.scope = 'cultivation'::text
          ORDER BY cost_model.effective_from DESC
         LIMIT 1)), 0) AS dollars_at_cost,
    why_it_is_a_loss AS what_is_wrong,
    what_to_check AS what_to_do,
    ( SELECT m.harvest_start
           FROM v_harvest_stage_map m
          WHERE m.strains = r.scope OR m.harvest = r.scope
         LIMIT 1) AS harvest_date,
    ( SELECT m.room
           FROM v_harvest_stage_map m
          WHERE m.strains = r.scope OR m.harvest = r.scope
         LIMIT 1) AS room,
    ( SELECT m.days_since_takedown
           FROM v_harvest_stage_map m
          WHERE m.strains = r.scope OR m.harvest = r.scope
         LIMIT 1) AS days_since_takedown
   FROM v_real_loss r
  ORDER BY (round(COALESCE(pounds, 0::numeric) * (( SELECT cost_model.cost_per_pound
           FROM cost_model
          WHERE cost_model.scope = 'cultivation'::text
          ORDER BY cost_model.effective_from DESC
         LIMIT 1)), 0)) DESC NULLS LAST;
create or replace view public.v_issue_yield_gap as
 SELECT room,
    count(*) AS harvests,
    round(avg(conversion_pct), 1) AS our_conversion_pct,
    round(avg(company_average_pct), 1) AS company_average_pct,
    round(avg(industry_average_pct), 1) AS industry_average_pct,
    round(sum(pounds_short_of_company_average), 1) AS pounds_short,
    round(sum(dollars_short), 0) AS dollars_short,
    round(sum(saleable_lbs), 1) AS saleable_lbs,
    round(sum(plants), 0) AS plants,
    max(harvest_date) AS most_recent_harvest,
    count(*) FILTER (WHERE conversion_pct < company_average_pct) AS harvests_below_our_average,
    max(harvest_date) AS most_recent_harvest_date
   FROM v_issue_yield_by_harvest y
  GROUP BY room;
create or replace view public.v_lab_fail_rate_by_origin as
 SELECT COALESCE(NULLIF(supplier, ''::text),
        CASE
            WHEN origin = 'Grown by us'::text THEN 'Twisted Growers (our own)'::text
            ELSE 'Supplier not recorded'::text
        END) AS supplier,
    origin,
    count(*) AS packages_tested,
    count(*) FILTER (WHERE verdict = 'FAILED'::text) AS failed,
    count(*) FILTER (WHERE verdict = 'Passed'::text) AS passed,
    count(*) FILTER (WHERE verdict = 'Awaiting result'::text) AS awaiting_result,
    count(*) FILTER (WHERE verdict = 'NEVER SUBMITTED'::text) AS never_submitted,
    round(100.0 * count(*) FILTER (WHERE verdict = 'FAILED'::text)::numeric / NULLIF(count(*) FILTER (WHERE verdict = ANY (ARRAY['FAILED'::text, 'Passed'::text])), 0)::numeric, 1) AS fail_rate_pct,
    round(sum(pounds) FILTER (WHERE verdict = 'FAILED'::text), 1) AS failed_pounds,
    round(sum(pounds), 1) AS total_pounds,
    max(result_on) AS most_recent_result_on,
        CASE
            WHEN count(*) FILTER (WHERE verdict = ANY (ARRAY['FAILED'::text, 'Passed'::text])) = 0 THEN 'No completed tests for this supplier yet, so a fail rate cannot be calculated.'::text
            ELSE NULL::text
        END AS why_no_rate
   FROM v_lab_results r
  GROUP BY (COALESCE(NULLIF(supplier, ''::text),
        CASE
            WHEN origin = 'Grown by us'::text THEN 'Twisted Growers (our own)'::text
            ELSE 'Supplier not recorded'::text
        END)), origin;
create or replace view public.v_leadership_cost_vs_output as
 SELECT COALESCE(d.name, 'not assigned'::text) AS department,
    count(e.id)::numeric AS headcount,
    round(sum(COALESCE(pf.loaded_weekly_cost, 0::numeric)), 0) AS weekly_loaded_cost,
    round(sum(COALESCE(pf.loaded_weekly_cost, 0::numeric)) * 52::numeric, 0) AS annual_loaded_cost,
    round(max(COALESCE(pf.loaded_weekly_cost, 0::numeric)), 0) AS highest_paid_weekly,
    ( SELECT string_agg(x.full_name, ', '::text) AS string_agg
           FROM ( SELECT e2.full_name
                   FROM employees e2
                     LEFT JOIN v_payroll_forecast p2 ON p2.full_name = e2.full_name
                  WHERE e2.primary_department_id = d.id AND e2.terminated_on IS NULL
                  ORDER BY (COALESCE(p2.loaded_weekly_cost, 0::numeric)) DESC
                 LIMIT 3) x) AS highest_paid_people,
        CASE
            WHEN d.name ~~* '%cultivation%'::text THEN ( SELECT round(sum(v_true_cost_per_pound.saleable_lbs), 1) AS round
               FROM v_true_cost_per_pound
              WHERE v_true_cost_per_pound.month_date >= (CURRENT_DATE - 90))
            ELSE NULL::numeric
        END AS saleable_lbs_90d,
        CASE
            WHEN d.name ~~* '%cultivation%'::text THEN round(sum(COALESCE(pf.loaded_weekly_cost, 0::numeric)) * 13::numeric / NULLIF(( SELECT sum(v_true_cost_per_pound.saleable_lbs) AS sum
               FROM v_true_cost_per_pound
              WHERE v_true_cost_per_pound.month_date >= (CURRENT_DATE - 90)), 0::numeric), 0)
            ELSE NULL::numeric
        END AS labour_cost_per_saleable_pound_90d
   FROM departments d
     LEFT JOIN employees e ON e.primary_department_id = d.id AND e.terminated_on IS NULL
     LEFT JOIN v_payroll_forecast pf ON pf.full_name = e.full_name
  GROUP BY d.id, d.name
  ORDER BY (round(sum(COALESCE(pf.loaded_weekly_cost, 0::numeric)) * 52::numeric, 0)) DESC NULLS LAST;
create or replace view public.v_loss_analysis as
 WITH h AS (
         SELECT COALESCE(metrc_harvests.raw ->> 'DryingLocationName'::text, '(no room)'::text) AS room,
            COALESCE(metrc_harvests.raw ->> 'SourceStrainNames'::text, '(not recorded)'::text) AS strain,
            to_char(metrc_harvests.harvest_start::timestamp with time zone, 'YYYY-MM'::text) AS month,
            date_trunc('month'::text, metrc_harvests.harvest_start::timestamp with time zone)::date AS month_date,
            metrc_harvests.name AS harvest,
            metrc_harvests.harvest_start,
            COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric) AS wet_g,
            COALESCE((metrc_harvests.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric) AS waste_g,
            COALESCE((metrc_harvests.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) AS packaged_g,
            COALESCE((metrc_harvests.raw ->> 'PlantCount'::text)::numeric, 0::numeric) AS plants
           FROM metrc_harvests
          WHERE metrc_harvests.harvest_start IS NOT NULL
        )
 SELECT room,
    strain,
    month,
    month_date,
    count(*)::numeric AS harvests,
    sum(plants) AS plants,
    round(sum(wet_g) / 453.592, 1) AS wet_lbs,
    round(sum(waste_g) / 453.592, 1) AS waste_lbs,
    round(sum(packaged_g) / 453.592, 1) AS packaged_lbs,
        CASE
            WHEN sum(wet_g) > 0::numeric THEN round(100.0 * sum(waste_g) / sum(wet_g), 1)
            ELSE NULL::numeric
        END AS waste_pct,
        CASE
            WHEN sum(wet_g) > 0::numeric THEN round(100.0 * sum(packaged_g) / sum(wet_g), 1)
            ELSE NULL::numeric
        END AS yield_pct,
        CASE
            WHEN sum(wet_g) > 0::numeric THEN round(100.0 * sum(waste_g) / sum(wet_g) - (( SELECT 100.0 * sum(COALESCE((metrc_harvests.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric)) / NULLIF(sum(COALESCE((metrc_harvests.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric)), 0::numeric)
               FROM metrc_harvests)), 1)
            ELSE NULL::numeric
        END AS waste_pct_vs_company_average,
        CASE
            WHEN sum(wet_g) = 0::numeric THEN 'No weights recorded - cannot analyse'::text
            WHEN (100.0 * sum(waste_g) / sum(wet_g)) > 25::numeric THEN 'SEVERE - investigate this room and crew immediately'::text
            WHEN (100.0 * sum(waste_g) / sum(wet_g)) > 15::numeric THEN 'HIGH - above the acceptable band'::text
            WHEN (100.0 * sum(waste_g) / sum(wet_g)) > 10::numeric THEN 'ELEVATED - watch it'::text
            ELSE 'Within normal range'::text
        END AS loss_verdict,
    ( SELECT round(sum(h.waste_g) / 453.592 * 453.592 * max(v_route_margin.margin_per_input_gram), 0) AS round
           FROM v_route_margin) AS lost_margin_estimate,
    max(harvest_start) AS last_harvest
   FROM h
  GROUP BY room, strain, month, month_date
  ORDER BY (
        CASE
            WHEN sum(wet_g) > 0::numeric THEN round(100.0 * sum(waste_g) / sum(wet_g), 1)
            ELSE NULL::numeric
        END) DESC NULLS LAST;
create or replace view public.v_manifest_custody as
 WITH oriented AS (
         SELECT m.manifest_number,
            m.date_created,
            m.departure,
            m.arrival,
            m.is_lab_run,
            t.direction,
                CASE
                    WHEN t.direction = 'incoming'::text THEN m.destination_license
                    ELSE m.origin_license
                END AS ship_lic,
                CASE
                    WHEN t.direction = 'incoming'::text THEN m.origin_license
                    ELSE m.destination_license
                END AS dest_lic,
                CASE
                    WHEN t.direction = 'incoming'::text THEN m.destination_name
                    ELSE m.origin_name
                END AS ship_nm,
                CASE
                    WHEN t.direction = 'incoming'::text THEN m.origin_name
                    ELSE m.destination_name
                END AS dest_nm,
            m.transporter_name,
            m.transporter_license,
            t.raw ->> 'ShipperFacilityLicenseNumber'::text AS metrc_shipper
           FROM manifest_extract m
             LEFT JOIN metrc_transfers t ON t.manifest_number = m.manifest_number
        )
 SELECT o.manifest_number,
    o.date_created,
    o.direction,
    COALESCE(sd.name, o.ship_nm) AS shipped_by,
    o.ship_lic AS origin_license,
    COALESCE(dd.name, o.dest_nm) AS delivered_to,
    o.dest_lic AS destination_license,
        CASE
            WHEN o.dest_lic IS NULL THEN 'UNKNOWN'::text
            WHEN o.dest_lic ~~ 'IL%'::text THEN 'LABORATORY'::text
            WHEN o.dest_lic ~~ 'MX%'::text THEN 'TRANSPORTER'::text
            WHEN o.dest_lic ~~ 'MT%'::text THEN 'STORAGE / TRANSPORT - never a sale'::text
            WHEN o.dest_lic ~~ 'MR%'::text OR o.dest_lic ~~ 'RMD%'::text THEN 'RETAIL'::text
            ELSE 'LICENSEE'::text
        END AS destination_kind,
    COALESCE(o.transporter_name, td.name) AS carried_by,
    o.transporter_license,
    o.is_lab_run,
    o.departure,
    o.arrival,
    ( SELECT count(*) AS count
           FROM metrc_rpt_package_transfers p
          WHERE p.manifest_number = o.manifest_number) AS packages,
    o.metrc_shipper IS NOT NULL AND o.ship_lic IS NOT NULL AND o.metrc_shipper <> o.ship_lic AS shipper_disagrees_with_metrc
   FROM oriented o
     LEFT JOIN v_licence_directory sd ON sd.licence = o.ship_lic
     LEFT JOIN v_licence_directory dd ON dd.licence = o.dest_lic
     LEFT JOIN v_licence_directory td ON td.licence = o.transporter_license;
create or replace view public.v_metrc_harvest_yields as
 WITH h AS (
         SELECT mh.license,
            mh.name AS harvest_name,
            COALESCE(mh.raw ->> 'SourceStrainNames'::text, 'not recorded'::text) AS strain,
            COALESCE(mh.raw ->> 'DryingLocationName'::text, '(no room)'::text) AS room,
            mh.harvest_start,
            (mh.raw ->> 'FinishedDate'::text)::date AS finished_on,
            COALESCE((mh.raw ->> 'PlantCount'::text)::numeric, 0::numeric) AS plants,
            COALESCE((mh.raw ->> 'TotalWetWeight'::text)::numeric, 0::numeric) AS wet_g,
            COALESCE((mh.raw ->> 'TotalWasteWeight'::text)::numeric, 0::numeric) AS waste_g,
            COALESCE((mh.raw ->> 'TotalPackagedWeight'::text)::numeric, 0::numeric) AS packaged_g,
            COALESCE((mh.raw ->> 'CurrentWeight'::text)::numeric, 0::numeric) AS current_g,
            mh.raw ->> 'LabTestingState'::text AS lab_state
           FROM metrc_harvests mh
        ), plan AS (
         SELECT p.pull_no,
            p.harvest_date,
            p.flower_room,
            p.cultivars,
            p.original_total_plants AS planned_plants,
            p.proj_harvest_weight_lbs AS planned_lbs
           FROM harvest_pulls p
        )
 SELECT h.harvest_name,
    h.strain,
    h.room,
    h.harvest_start AS takedown_date,
    h.finished_on,
    m.stage AS current_stage,
    m.days_since_takedown,
    pl.pull_no AS planned_pull,
    pl.planned_plants,
    h.plants AS actual_plants,
    round(COALESCE(pl.planned_lbs, 0::numeric), 1) AS projected_lbs,
    round(h.wet_g / 453.592, 1) AS actual_wet_lbs,
    round(h.packaged_g / 453.592, 1) AS actual_packaged_lbs,
        CASE
            WHEN COALESCE(pl.planned_lbs, 0::numeric) > 0::numeric THEN round(100.0 * (h.packaged_g / 453.592) / pl.planned_lbs, 1)
            ELSE NULL::numeric
        END AS pct_of_projection,
        CASE
            WHEN COALESCE(pl.planned_lbs, 0::numeric) > 0::numeric THEN round(h.packaged_g / 453.592 - pl.planned_lbs, 1)
            ELSE NULL::numeric
        END AS variance_lbs,
    round(h.waste_g / 453.592, 1) AS waste_lbs,
        CASE
            WHEN h.wet_g > 0::numeric THEN round(100.0 * h.waste_g / h.wet_g, 1)
            ELSE NULL::numeric
        END AS waste_pct,
        CASE
            WHEN h.wet_g > 0::numeric THEN round(100.0 * h.packaged_g / h.wet_g, 1)
            ELSE NULL::numeric
        END AS yield_pct,
    ( SELECT count(*) AS count
           FROM allocation_requests a
          WHERE a.source_ref ~~* (('%'::text || h.harvest_name) || '%'::text) OR a.material_name ~~* (('%'::text || h.strain) || '%'::text)) AS allocation_requests,
    ( SELECT string_agg(DISTINCT a.requester_name, ', '::text) AS string_agg
           FROM allocation_requests a
          WHERE a.source_ref ~~* (('%'::text || h.harvest_name) || '%'::text) OR a.material_name ~~* (('%'::text || h.strain) || '%'::text)) AS requested_by,
    ( SELECT string_agg(DISTINCT a.decider_name, ', '::text) AS string_agg
           FROM allocation_requests a
          WHERE (a.source_ref ~~* (('%'::text || h.harvest_name) || '%'::text) OR a.material_name ~~* (('%'::text || h.strain) || '%'::text)) AND a.status = 'approved'::text) AS approved_by,
    ( SELECT round(sum(COALESCE(a.approved_quantity, a.quantity)), 1) AS round
           FROM allocation_requests a
          WHERE (a.source_ref ~~* (('%'::text || h.harvest_name) || '%'::text) OR a.material_name ~~* (('%'::text || h.strain) || '%'::text)) AND a.status = 'approved'::text) AS allocated_quantity,
    ( SELECT string_agg(DISTINCT a.destination, ', '::text) AS string_agg
           FROM allocation_requests a
          WHERE (a.source_ref ~~* (('%'::text || h.harvest_name) || '%'::text) OR a.material_name ~~* (('%'::text || h.strain) || '%'::text)) AND a.status = 'approved'::text) AS allocated_to,
    ( SELECT string_agg(DISTINCT a.purpose, ' · '::text) AS string_agg
           FROM allocation_requests a
          WHERE (a.source_ref ~~* (('%'::text || h.harvest_name) || '%'::text) OR a.material_name ~~* (('%'::text || h.strain) || '%'::text)) AND a.status = 'approved'::text) AS allocated_for,
    ( SELECT count(*) AS count
           FROM metrc_packages p
          WHERE COALESCE(p.raw ->> 'SourceHarvestNames'::text, ''::text) ~~* (('%'::text || h.harvest_name) || '%'::text)) AS packages_made,
    ( SELECT string_agg(DISTINCT NULLIF(p.raw ->> 'ProductCategoryName'::text, ''::text), ', '::text) AS string_agg
           FROM metrc_packages p
          WHERE COALESCE(p.raw ->> 'SourceHarvestNames'::text, ''::text) ~~* (('%'::text || h.harvest_name) || '%'::text)) AS manufactured_into,
    ( SELECT round(sum(COALESCE(p.quantity, 0::numeric)), 1) AS round
           FROM metrc_packages p
          WHERE COALESCE(p.raw ->> 'SourceHarvestNames'::text, ''::text) ~~* (('%'::text || h.harvest_name) || '%'::text) AND (p.source_state = ANY (ARRAY['active'::text, 'onhold'::text]))) AS still_on_hand,
    ( SELECT string_agg(DISTINCT p.location, ', '::text) AS string_agg
           FROM metrc_packages p
          WHERE COALESCE(p.raw ->> 'SourceHarvestNames'::text, ''::text) ~~* (('%'::text || h.harvest_name) || '%'::text) AND (p.source_state = ANY (ARRAY['active'::text, 'onhold'::text]))) AS sitting_in,
    ( SELECT count(*) AS count
           FROM metrc_packages p
          WHERE COALESCE(p.raw ->> 'SourceHarvestNames'::text, ''::text) ~~* (('%'::text || h.harvest_name) || '%'::text) AND p.lab_testing_state = 'TestPassed'::text) AS passed_testing,
    ( SELECT count(*) AS count
           FROM metrc_packages p
          WHERE COALESCE(p.raw ->> 'SourceHarvestNames'::text, ''::text) ~~* (('%'::text || h.harvest_name) || '%'::text) AND p.source_state = 'intransit'::text) AS shipped_out,
    h.lab_state,
    h.license
   FROM h
     LEFT JOIN v_harvest_stage_map m ON m.harvest = h.harvest_name
     LEFT JOIN plan pl ON pl.flower_room = h.room AND h.harvest_start >= (pl.harvest_date - 4) AND h.harvest_start <= (pl.harvest_date + 10)
  ORDER BY h.harvest_start DESC NULLS LAST;
create or replace view public.v_missing_lab_results as
 SELECT l.package_tag,
    l.product,
    l.category,
    l.strain,
    l.source_harvest,
    l.pounds,
    l.went_out_on,
    CURRENT_DATE - l.went_out_on AS days_missing,
    l.testing_state,
    round(l.pounds * f_rate_for(s.stream)) AS value_at_risk,
    s.location AS where_it_is_now,
    s.origin,
    ((((('Submitted to the laboratory on '::text || l.went_out_on) || ' and still showing '::text) || l.testing_state) || ' after '::text) || (CURRENT_DATE - l.went_out_on)) || ' days. No result has been recorded. Chase the laboratory for the certificate and enter it.'::text AS what_to_do
   FROM lab_turnaround_log l
     LEFT JOIN v_stock_packages s ON s.package_tag = l.package_tag
  WHERE l.came_back_on IS NULL AND (l.testing_state = ANY (ARRAY['SubmittedForTesting'::text, 'TestingInProgress'::text]))
  ORDER BY (CURRENT_DATE - l.went_out_on) DESC;
create or replace view public.v_moisture_summary as
 SELECT stream,
    count(*) AS harvests,
    round(sum(wet_lb), 1) AS wet_lb,
    round(sum(packaged_lb), 1) AS packaged_lb,
    round(sum(recorded_waste_lb), 1) AS waste_lb,
    round(sum(moisture_lb), 1) AS evaporated_lb,
    round(sum(metrc_current_weight_lb), 1) AS metrc_says_lb,
    round(sum(reconciliation_gap_lb), 1) AS gap_lb,
    round(100::numeric * sum(moisture_lb) / NULLIF(sum(wet_lb), 0::numeric), 1) AS moisture_pct,
    round(100::numeric * sum(packaged_lb) / NULLIF(sum(wet_lb), 0::numeric), 1) AS conversion_pct,
    'Every pound of wet weight ends up in exactly one of three places: packaged product, recorded waste, or water that evaporated. This proves the three add back.'::text AS what_this_proves
   FROM v_moisture_accounting
  WHERE finished IS NOT NULL
  GROUP BY stream;
create or replace view public.v_never_tested_proof as
 WITH base AS (
         SELECT DISTINCT ON (p.tag) p.tag,
            p.item_name,
            p.uom,
            p.quantity,
            p.license,
            p.lab_testing_state,
            p.source_state,
            p.packaged_on,
            p.raw
           FROM metrc_packages p
          ORDER BY p.tag, p.license
        )
 SELECT tag AS metrc_tag,
    license AS metrc_licence,
    "left"(item_name, 46) AS item,
    raw #>> '{Item,ProductCategoryName}'::text[] AS category,
    f_quantity_text(quantity, uom) AS metrc_quantity,
    raw ->> 'LocationName'::text AS metrc_room,
    raw ->> 'LocationTypeName'::text AS room_type,
    NULLIF(raw ->> 'SublocationName'::text, ''::text) AS sublocation,
    lab_testing_state AS metrc_lab_state,
    source_state AS metrc_status,
    (raw ->> 'IsOnHold'::text)::boolean AS on_hold,
    (raw ->> 'IsFinished'::text)::boolean AS finished,
    packaged_on AS metrc_packaged_on,
    (raw ->> 'LastModified'::text)::date AS metrc_last_modified,
    CURRENT_DATE - packaged_on AS days_in_facility,
    NULLIF(raw ->> 'SourceHarvestNames'::text, ''::text) AS from_harvest,
    (raw ->> 'SourcePackageCount'::text)::integer AS made_from_n_packages,
    "left"(NULLIF(raw ->> 'SourcePackageLabels'::text, ''::text), 120) AS made_from_packages,
    NULLIF(raw ->> 'ProductionBatchNumber'::text, ''::text) AS production_batch,
    NULLIF(raw ->> 'ReceivedFromManifestNumber'::text, ''::text) AS arrived_on_manifest,
    ( SELECT string_agg(c.tag, ', '::text) AS string_agg
           FROM metrc_packages c
          WHERE (c.raw ->> 'SourcePackageLabels'::text) ~~ (('%'::text || b.tag) || '%'::text)) AS became_packages,
    ( SELECT count(*) AS count
           FROM metrc_lab_results l
          WHERE l.package_tag = b.tag) AS lab_results,
    ( SELECT count(*) AS count
           FROM metrc_rpt_package_transfers t
          WHERE t.package_tag = b.tag) AS manifest_lines,
    ( SELECT count(*) AS count
           FROM v_certificate_resolved r
          WHERE r.package_tag = b.tag AND r.found_at_depth = 0) AS own_certificate,
    ( SELECT max(r.found_at_depth) AS max
           FROM v_certificate_resolved r
          WHERE r.package_tag = b.tag) AS inherited_cert_depth,
        CASE
            WHEN (raw ->> 'LocationName'::text) IS NULL THEN 'FAILS THE RULE - Metrc holds no room for this tag'::text
            WHEN (( SELECT count(*) AS count
               FROM metrc_lab_results l
              WHERE l.package_tag = b.tag)) > 0 THEN 'FAILS THE RULE - claimed untested but laboratory results exist'::text
            WHEN (( SELECT count(*) AS count
               FROM metrc_rpt_package_transfers t
              WHERE t.package_tag = b.tag)) > 0 THEN 'FAILS THE RULE - claimed never shipped but it is on a manifest line'::text
            WHEN (( SELECT count(*) AS count
               FROM v_certificate_resolved r
              WHERE r.package_tag = b.tag AND r.found_at_depth = 0)) > 0 THEN 'FAILS THE RULE - claimed untested but a certificate is filed against it'::text
            ELSE ((('PROVEN - Metrc holds it in '::text || (raw ->> 'LocationName'::text)) || ', state '::text) || lab_testing_state) || ', no results, no manifest, no certificate'::text
        END AS proof
   FROM base b
  WHERE (lab_testing_state = ANY (ARRAY['NotSubmitted'::text, 'NotRequired'::text])) AND (source_state = ANY (ARRAY['active'::text, 'onhold'::text]));
create or replace view public.v_never_tested_reconciliation as
 WITH claimed AS (
         SELECT p.tag,
            p.item_name,
            p.lab_testing_state,
            p.uom,
            p.quantity,
            p.source_state,
            p.raw ->> 'LocationName'::text AS location,
            p.raw #>> '{Item,ProductCategoryName}'::text[] AS category,
            p.packaged_on,
            CURRENT_DATE - p.packaged_on AS days_held
           FROM ( SELECT DISTINCT ON (metrc_packages.tag) metrc_packages.tag,
                    metrc_packages.item_name,
                    metrc_packages.lab_testing_state,
                    metrc_packages.uom,
                    metrc_packages.quantity,
                    metrc_packages.source_state,
                    metrc_packages.packaged_on,
                    metrc_packages.raw
                   FROM metrc_packages
                  ORDER BY metrc_packages.tag, metrc_packages.license) p
          WHERE (p.lab_testing_state = ANY (ARRAY['NotSubmitted'::text, 'NotRequired'::text])) AND (p.source_state = ANY (ARRAY['active'::text, 'onhold'::text]))
        )
 SELECT tag AS package_tag,
    "left"(item_name, 50) AS item_name,
    category,
    location,
    f_quantity_text(quantity, uom) AS how_much,
    lab_testing_state AS metrc_says,
    packaged_on,
    days_held,
    ( SELECT count(*) AS count
           FROM metrc_lab_results l
          WHERE l.package_tag = c.tag) AS lab_results,
    ( SELECT count(*) AS count
           FROM metrc_rpt_package_transfers t
          WHERE t.package_tag = c.tag) AS manifest_lines,
    ( SELECT count(*) AS count
           FROM v_certificate_resolved r
          WHERE r.package_tag = c.tag AND r.found_at_depth = 0) AS direct_certificates,
    ( SELECT max(r.found_at_depth) AS max
           FROM v_certificate_resolved r
          WHERE r.package_tag = c.tag) AS inherited_at_depth,
        CASE
            WHEN (( SELECT count(*) AS count
               FROM metrc_lab_results l
              WHERE l.package_tag = c.tag)) > 0 THEN 'CONTRADICTION - Metrc says never submitted but laboratory results exist'::text
            WHEN (( SELECT count(*) AS count
               FROM v_certificate_resolved r
              WHERE r.package_tag = c.tag AND r.found_at_depth = 0)) > 0 THEN 'CONTRADICTION - Metrc says never submitted but a certificate is filed DIRECTLY against it'::text
            WHEN (( SELECT count(*) AS count
               FROM metrc_rpt_package_transfers t
              WHERE t.package_tag = c.tag)) > 0 THEN 'CONTRADICTION - Metrc says never tested but it travelled on a manifest'::text
            ELSE 'RECONCILED - never tested, never shipped, consistent on all four sources'::text
        END AS reconciliation,
    'THE RULE: a claim of never tested must reconcile against Metrc, the laboratory results, the custody export and the document store. Three of those four are outside this platform''s own reasoning.'::text AS what_is_wrong
   FROM claimed c;
create or replace view public.v_own_vs_bought as
 SELECT stream,
    round(COALESCE(sum(pounds) FILTER (WHERE origin = 'Grown by us'::text), 0::numeric), 1) AS grown_lb,
    round(COALESCE(sum(pounds) FILTER (WHERE origin = 'Bought in'::text), 0::numeric), 1) AS bought_lb,
    round(COALESCE(sum(pounds) FILTER (WHERE origin = 'Origin not recorded'::text), 0::numeric), 1) AS unknown_origin_lb,
    round(sum(pounds), 1) AS total_lb,
    round(100::numeric * COALESCE(sum(pounds) FILTER (WHERE origin = 'Bought in'::text), 0::numeric) / NULLIF(sum(pounds), 0::numeric), 1) AS pct_bought_in
   FROM v_stock_on_hand
  GROUP BY stream
  ORDER BY (round(sum(pounds), 1)) DESC;
create or replace view public.v_ownership_by_custody as
 WITH pkg AS (
         SELECT DISTINCT ON (metrc_packages.tag) metrc_packages.tag,
            metrc_packages.item_name,
            metrc_packages.uom,
            metrc_packages.quantity,
            metrc_packages.source_state,
            metrc_packages.lab_testing_state,
            metrc_packages.raw ->> 'ItemFromFacilityLicenseNumber'::text AS item_license,
            metrc_packages.raw ->> 'SourcePackageCount'::text AS source_packages
           FROM metrc_packages
          ORDER BY metrc_packages.tag, metrc_packages.license
        ), custody AS (
         SELECT t.package_tag,
            string_agg(DISTINCT t.source_row ->> 'Origin Lic.'::text, ', '::text) FILTER (WHERE (t.source_row ->> 'Origin Lic.'::text) IS NOT NULL) AS origin_licences,
            string_agg(DISTINCT t.manifest_number, ', '::text) AS manifests,
            count(*) AS custody_events
           FROM metrc_rpt_package_transfers t
          GROUP BY t.package_tag
        )
 SELECT p.tag AS package_tag,
    "left"(p.item_name, 50) AS item_name,
    p.source_state,
    f_quantity_text(p.quantity, p.uom) AS how_much,
        CASE
            WHEN f_is_weight(p.uom) THEN round(f_to_pounds(p.quantity, p.uom), 2)
            ELSE NULL::numeric
        END AS pounds,
        CASE
            WHEN NOT f_is_weight(p.uom) THEN p.quantity
            ELSE NULL::numeric
        END AS units,
    p.item_license AS item_field_says,
    c.origin_licences AS custody_says,
    c.manifests,
    c.custody_events,
    r.cert_client AS certificate_client,
    r.cert_license AS certificate_licence,
    r.certificate_link,
        CASE
            WHEN c.package_tag IS NULL THEN 'NO CUSTODY RECORD - never appeared on a manifest line. Cannot judge ownership from a testing document; get the manifest.'::text
            WHEN c.origin_licences IS NULL THEN 'CUSTODY RECORD WITHOUT AN ORIGIN LICENCE - the export line is incomplete.'::text
            WHEN f_all_ours(c.origin_licences) THEN 'OURS - every custody origin on the manifests is one of our licences.'::text
            WHEN NOT f_any_ours(c.origin_licences) THEN 'NOT OURS - the manifests name only outside licences as origin.'::text
            ELSE 'MIXED - the manifests name both our licences and outside ones. Needs the line detail.'::text
        END AS custody_verdict,
        CASE
            WHEN r.cert_license IS NULL OR c.origin_licences IS NULL THEN NULL::text
            WHEN f_any_ours(r.cert_license) = f_any_ours(c.origin_licences) THEN 'agree'::text
            ELSE 'DISAGREE - certificate and manifest point different ways'::text
        END AS certificate_vs_custody
   FROM pkg p
     LEFT JOIN custody c ON c.package_tag = p.tag
     LEFT JOIN v_certificate_resolved r ON r.package_tag = p.tag
  WHERE p.source_state = ANY (ARRAY['active'::text, 'onhold'::text]);
create or replace view public.v_ownership_verdict as
 WITH conflicted AS (
         SELECT p.tag,
            p.item_name,
            p.uom,
            p.quantity,
            p.source_state,
            p.lab_testing_state,
            p.raw ->> 'ItemFromFacilityLicenseNumber'::text AS platform_license,
            p.raw ->> 'ItemFromFacilityName'::text AS platform_name,
            o.origin AS lineage
           FROM ( SELECT DISTINCT ON (metrc_packages.tag) metrc_packages.tag,
                    metrc_packages.item_name,
                    metrc_packages.uom,
                    metrc_packages.quantity,
                    metrc_packages.source_state,
                    metrc_packages.lab_testing_state,
                    metrc_packages.raw
                   FROM metrc_packages
                  ORDER BY metrc_packages.tag, metrc_packages.license) p
             CROSS JOIN LATERAL ( SELECT f_material_origin(p.tag) AS origin) o
          WHERE (p.source_state = ANY (ARRAY['active'::text, 'onhold'::text])) AND f_is_ours(p.raw ->> 'ItemFromFacilityLicenseNumber'::text) AND ((o.origin ->> 'any_outside'::text)::boolean) IS TRUE
        ), certed AS (
         SELECT c.tag,
            c.item_name,
            c.uom,
            c.quantity,
            c.source_state,
            c.lab_testing_state,
            c.platform_license,
            c.platform_name,
            c.lineage,
            r.cert_license,
            r.cert_client,
            r.found_at_depth,
            r.certificate_on_package
           FROM conflicted c
             LEFT JOIN v_certificate_resolved r ON r.package_tag = c.tag
        )
 SELECT tag AS package_tag,
    "left"(item_name, 50) AS item_name,
    source_state,
    lab_testing_state,
        CASE
            WHEN f_is_weight(uom) THEN round(f_to_pounds(quantity, uom), 2)
            ELSE NULL::numeric
        END AS pounds,
    platform_license AS platform_says,
    lineage -> 'origin_names'::text AS lineage_says,
    lineage -> 'origin_licences'::text AS lineage_licences,
    lineage -> 'inbound_manifests'::text AS inbound_manifests,
    cert_client AS certificate_says,
    cert_license AS certificate_license,
        CASE
            WHEN found_at_depth IS NULL THEN NULL::text
            WHEN found_at_depth = 0 THEN 'direct'::text
            ELSE 'inherited via '::text || found_at_depth
        END AS certificate_link,
    certificate_on_package,
        CASE
            WHEN cert_license IS NULL AND cert_client IS NULL THEN 'UNPROVEN - no certificate in the lineage. Ownership doubt raised, not settled.'::text
            WHEN cert_license IS NOT NULL AND f_licence_in_set(platform_license, cert_license) THEN ('INCONCLUSIVE - the certificate names us, but the lineage says the '::text || 'material came from outside. Consistent with us paying for a '::text) || 'retest after buying it. NOT proof we grew it.'::text
            WHEN cert_license IS NOT NULL THEN ('CONFIRMED NOT OURS - the laboratory names '::text || COALESCE(cert_client, 'another licensee'::text)) || '. The certificate is independent and it wins.'::text
            ELSE ('NAME ONLY - the certificate names '::text || COALESCE(cert_client, '?'::text)) || ' but prints no licence (MCR Labs does not). Judge on the name.'::text
        END AS verdict,
    'THE ISSUE: this package is counted as ours. Ownership drives yield, cost, loss and on-hand, and every one of those is wrong if this is somebody else''s material.'::text AS what_is_wrong,
        CASE
            WHEN NOT f_is_weight(uom) THEN quantity
            ELSE NULL::numeric
        END AS units,
    uom AS unit_of_measure,
    f_quantity_text(quantity, uom) AS how_much
   FROM certed;
create or replace view public.v_position_by_ownership as
 WITH p AS (
         SELECT mp.tag,
            COALESCE(NULLIF(mp.location, ''::text), '(no location recorded)'::text) AS location,
            mp.license,
            mp.lab_testing_state,
            f_to_pounds(mp.quantity, mp.uom) AS lb,
            f_material_origin(mp.tag) AS g
           FROM metrc_packages mp
          WHERE mp.quantity > 0::numeric
        ), tagged AS (
         SELECT p.tag,
            p.location,
            p.license,
            p.lab_testing_state,
            p.lb,
            p.g,
            jsonb_array_length(COALESCE(p.g -> 'origin_licences'::text, '[]'::jsonb)) AS origins,
                CASE
                    WHEN (p.g ->> 'all_ours'::text)::boolean THEN 'ours'::text
                    WHEN ((p.g ->> 'any_outside'::text)::boolean) AND jsonb_array_length(COALESCE(p.g -> 'origin_licences'::text, '[]'::jsonb)) <= 1 THEN 'third_party'::text
                    WHEN (p.g ->> 'any_outside'::text)::boolean THEN 'blended'::text
                    ELSE 'unresolved'::text
                END AS side
           FROM p
        ), s AS (
         SELECT COALESCE(soh.stream, 'not classified'::text) AS stream,
            soh.license,
            soh.lab_state
           FROM v_stock_on_hand soh
         LIMIT 0
        )
 SELECT license,
    COALESCE(lab_testing_state, 'no test state recorded'::text) AS lab_state,
    location,
    round(sum(lb) FILTER (WHERE side = 'ours'::text), 1) AS ours_lb,
    round(sum(lb) FILTER (WHERE side = 'third_party'::text), 1) AS third_party_lb,
    round(sum(lb) FILTER (WHERE side = 'blended'::text), 1) AS blended_lb,
    round(sum(lb) FILTER (WHERE side = 'unresolved'::text), 1) AS unresolved_lb,
    round(sum(lb), 1) AS collectively_lb,
    count(*) FILTER (WHERE side = 'ours'::text) AS ours_packages,
    count(*) FILTER (WHERE side = 'third_party'::text) AS third_party_packages,
    count(*) FILTER (WHERE side = 'blended'::text) AS blended_packages,
    count(*) FILTER (WHERE side = 'unresolved'::text) AS unresolved_packages,
    count(*) AS collectively_packages,
    round(100.0 * sum(lb) FILTER (WHERE side = 'third_party'::text) / NULLIF(sum(lb), 0::numeric), 1) AS pct_third_party,
        CASE
            WHEN sum(lb) FILTER (WHERE side = ANY (ARRAY['blended'::text, 'unresolved'::text])) > 0::numeric THEN ((round(sum(lb) FILTER (WHERE side = ANY (ARRAY['blended'::text, 'unresolved'::text])), 1) || ' lb cannot be attributed to either side — blended from several origins with no '::text) || 'record of the proportions. ours + third party will NOT equal collectively, and '::text) || 'making them balance would require inventing the split.'::text
            ELSE NULL::text
        END AS why_it_does_not_add_up
   FROM tagged t
  GROUP BY license, (COALESCE(lab_testing_state, 'no test state recorded'::text)), location;
create or replace view public.v_potency_vs_coa as
 SELECT v.package_tag,
    v.license,
    v.item_name,
    v.category,
    v.total_thc AS metrc_value,
    v.total_thc_unit AS metrc_unit,
        CASE
            WHEN v.total_thc_unit = 'mg/g'::text THEN round(v.total_thc / f_rule('mg_per_g_per_percent'::text), 5)
            ELSE v.total_thc
        END AS metrc_as_percent,
    c.total_thc AS coa_percent,
    c.document_id AS coa_document,
    c.sample_id AS coa_sample,
    round(abs(
        CASE
            WHEN v.total_thc_unit = 'mg/g'::text THEN v.total_thc / f_rule('mg_per_g_per_percent'::text)
            ELSE v.total_thc
        END - c.total_thc), 5) AS difference,
        CASE
            WHEN c.total_thc IS NULL THEN 'no COA figure to check against'::text
            WHEN v.total_thc IS NULL THEN 'no Metrc figure'::text
            WHEN abs(
            CASE
                WHEN v.total_thc_unit = 'mg/g'::text THEN v.total_thc / f_rule('mg_per_g_per_percent'::text)
                ELSE v.total_thc
            END - c.total_thc) <= 0.05 THEN 'agrees with the COA'::text
            WHEN v.total_thc = 0::numeric THEN 'METRC HOLDS ZERO, THE COA DOES NOT - raise a correction'::text
            ELSE 'disagrees with the COA - needs a person'::text
        END AS verdict
   FROM v_lab_results v
     JOIN coa_extract c ON c.package_tag = v.package_tag;
create or replace view public.v_product_identity as
 SELECT q.package_tag,
    q.item_name,
    q.strain,
    q.category,
    q.license,
    q.location,
    q.quantity,
    q.unit_of_measure,
    q.pounds,
    q.packaged_on,
    q.cultivator_or_manufacturer,
    q.maker_note,
    q.maker_license,
    q.origin,
    q.received_from,
    q.manifest_number,
    q.manifest_url,
    q.manifest_status,
    q.lab_state,
    q.submitted_on,
    q.result_on,
    q.coa_expires,
    q.total_thc,
    q.total_cbd,
    q.total_terpenes,
    q.analyte_count,
    q.analyte_note,
    q.coa_url,
    q.laboratory,
    q.coa_status,
    q.thc_from_test,
    q.thc_tested_on,
    q.terpenes_from_test,
    q.terpenes_tested_on,
    q.potency_provenance,
        CASE
            WHEN q.thc_from_test ~~* '%mg/g%'::text THEN 'mg/g'::text
            WHEN q.thc_from_test IS NOT NULL THEN '%'::text
            ELSE NULL::text
        END AS total_thc_unit,
        CASE
            WHEN q.terpenes_from_test ~~* '%mg/g%'::text THEN 'mg/g'::text
            WHEN q.terpenes_from_test IS NOT NULL THEN '%'::text
            ELSE NULL::text
        END AS total_terpenes_unit,
    ce.total_thc AS certificate_thc,
    ce.total_cbd AS certificate_cbd,
    ce.total_terpenes AS certificate_terpenes,
    ce.terpene_profile AS certificate_terpene_profile,
    ce.cannabinoid_profile AS certificate_cannabinoid_profile,
    NULLIF(concat_ws(' · '::text,
        CASE
            WHEN ce.microbiology IS NOT NULL THEN 'Microbiology '::text || ce.microbiology
            ELSE NULL::text
        END,
        CASE
            WHEN ce.mycotoxins IS NOT NULL THEN 'Mycotoxins '::text || ce.mycotoxins
            ELSE NULL::text
        END,
        CASE
            WHEN ce.heavy_metals IS NOT NULL THEN 'Heavy metals '::text || ce.heavy_metals
            ELSE NULL::text
        END,
        CASE
            WHEN ce.pesticides IS NOT NULL THEN 'Pesticides '::text || ce.pesticides
            ELSE NULL::text
        END,
        CASE
            WHEN ce.solvents IS NOT NULL THEN 'Solvents '::text || ce.solvents
            ELSE NULL::text
        END,
        CASE
            WHEN ce.pathogens IS NOT NULL THEN 'Pathogens '::text || ce.pathogens
            ELSE NULL::text
        END), ''::text) AS certificate_screens,
    COALESCE(q.total_thc, ce.total_thc) AS thc_shown,
    COALESCE(q.total_cbd, ce.total_cbd) AS cbd_shown,
    COALESCE(q.total_terpenes, ce.total_terpenes) AS terpenes_shown,
        CASE
            WHEN q.total_thc IS NOT NULL THEN 'Metrc laboratory result'::text
            WHEN ce.total_thc IS NOT NULL THEN 'Read from the certificate document'::text
            ELSE NULL::text
        END AS thc_source,
        CASE
            WHEN q.total_terpenes IS NOT NULL THEN 'Metrc laboratory result'::text
            WHEN ce.total_terpenes IS NOT NULL THEN 'Read from the certificate document'::text
            ELSE NULL::text
        END AS terpenes_source
   FROM ( SELECT p.tag AS package_tag,
            p.item_name,
            p.raw #>> '{Item,StrainName}'::text[] AS strain,
            p.raw #>> '{Item,ProductCategoryName}'::text[] AS category,
            p.license,
            p.location,
            round(p.quantity) AS quantity,
                CASE p.uom
                    WHEN 'g'::text THEN 'grams'::text
                    WHEN 'kg'::text THEN 'kilograms'::text
                    WHEN 'ea'::text THEN 'each'::text
                    WHEN 'oz'::text THEN 'ounces'::text
                    WHEN 'lb'::text THEN 'pounds'::text
                    ELSE COALESCE(p.uom, 'not recorded'::text)
                END AS unit_of_measure,
            round(p.quantity / 453.592, 2) AS pounds,
            p.packaged_on,
            COALESCE(NULLIF(p.raw ->> 'ItemFromFacilityName'::text, ''::text), 'Not recorded'::text) AS cultivator_or_manufacturer,
                CASE
                    WHEN NULLIF(p.raw ->> 'ItemFromFacilityName'::text, ''::text) IS NULL THEN 'WHY: Metrc did not return a facility name on this package. The licence number is still recorded, so the maker can be identified from that.'::text
                    ELSE NULL::text
                END AS maker_note,
            p.raw ->> 'ItemFromFacilityLicenseNumber'::text AS maker_license,
                CASE
                    WHEN COALESCE(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text) = ANY (ARRAY['MC281714'::text, 'MP281909'::text]) THEN 'Grown or made by us'::text
                    ELSE 'Bought in'::text
                END AS origin,
            COALESCE(NULLIF(p.raw ->> 'ReceivedFromFacilityName'::text, ''::text), 'Not applicable'::text) AS received_from,
            NULLIF(p.raw ->> 'ReceivedFromManifestNumber'::text, ''::text) AS manifest_number,
            COALESCE(md.download_url, t.manifest_link) AS manifest_url,
                CASE
                    WHEN NULLIF(p.raw ->> 'ReceivedFromManifestNumber'::text, ''::text) IS NULL THEN 'No manifest. WHY: this package has never moved between licences, so no manifest exists yet. One appears here automatically the moment it transfers.'::text
                    WHEN md.download_url IS NOT NULL THEN (((((('Manifest '::text || (p.raw ->> 'ReceivedFromManifestNumber'::text)) || ' — '::text) || COALESCE(t.shipper, '?'::text)) || ' to '::text) || COALESCE(t.recipient, '?'::text)) || COALESCE(' on '::text || t.created_on::text, ''::text)) || ' · copy held, click to open'::text
                    ELSE (((((('Manifest '::text || (p.raw ->> 'ReceivedFromManifestNumber'::text)) || ' — '::text) || COALESCE(t.shipper, '?'::text)) || ' to '::text) || COALESCE(t.recipient, '?'::text)) || COALESCE(' on '::text || t.created_on::text, ''::text)) || ' · document not downloaded yet, pulls overnight'::text
                END AS manifest_status,
            p.raw ->> 'LabTestingState'::text AS lab_state,
            (p.raw ->> 'LabTestingStateDate'::text)::date AS submitted_on,
            (p.raw ->> 'LabTestingRecordedDate'::text)::date AS result_on,
            (p.raw ->> 'LabTestResultExpirationDateTime'::text)::date AS coa_expires,
            round(thc.value, 2) AS total_thc,
            round(cbd.value, 2) AS total_cbd,
            round(terp.value, 2) AS total_terpenes,
            COALESCE(lab.analyte_count, 0::bigint) AS analyte_count,
                CASE
                    WHEN COALESCE(lab.analyte_count, 0::bigint) = 0 THEN
                    CASE
                        WHEN (p.raw ->> 'LabTestingState'::text) = ANY (ARRAY['TestPassed'::text, 'TestFailed'::text, 'RetestPassed'::text, 'RetestFailed'::text]) THEN 'WHY: this package is tested but its results have not been pulled from Metrc yet. The overnight run walks every tested package and they appear here automatically.'::text
                        ELSE 'WHY: this package has no laboratory result yet, so there are no values to show.'::text
                    END
                    ELSE NULL::text
                END AS analyte_note,
            cd.download_url AS coa_url,
            COALESCE(lab.laboratory, 'Not recorded'::text) AS laboratory,
                CASE
                    WHEN cd.download_url IS NOT NULL THEN 'Certificate on file — click to open, print or send'::text
                    WHEN COALESCE(lab.analyte_count, 0::bigint) > 0 THEN 'Results on file. WHY no document: this laboratory returned values but no certificate PDF.'::text
                    WHEN (p.raw ->> 'LabTestingState'::text) = ANY (ARRAY['TestPassed'::text, 'TestFailed'::text, 'RetestPassed'::text, 'RetestFailed'::text]) THEN ('Tested ('::text || (p.raw ->> 'LabTestingState'::text)) || ') — certificate not downloaded yet. It pulls automatically overnight.'::text
                    WHEN (p.raw ->> 'LabTestingState'::text) = 'NotSubmitted'::text THEN 'No certificate. WHY: never submitted for testing, so none exists.'::text
                    ELSE 'No certificate yet. WHY: awaiting the laboratory result.'::text
                END AS coa_status,
            thc.test_name AS thc_from_test,
            thc.result_date AS thc_tested_on,
            terp.test_name AS terpenes_from_test,
            terp.result_date AS terpenes_tested_on,
                CASE
                    WHEN thc.value IS NOT NULL THEN (('From "'::text || thc.test_name) || '" recorded '::text) || thc.result_date
                    ELSE NULL::text
                END AS potency_provenance
           FROM metrc_packages p
             LEFT JOIN LATERAL ( SELECT x.manifest_number,
                    x.direction,
                    x.created_on,
                    x.received_on,
                    x.shipper,
                    x.recipient,
                    x.recipient_license,
                    x.shipper_license,
                    x.packages,
                    x.packages_received,
                    x.transporter,
                    x.driver,
                    x.vehicle_make,
                    x.vehicle_plate,
                    x.departed,
                    x.arrival_estimate,
                    x.shipment_type,
                    x.manifest_link,
                    x.metrc_transfer_id,
                    x.license
                   FROM v_metrc_transfer_ledger x
                  WHERE x.manifest_number = NULLIF(p.raw ->> 'ReceivedFromManifestNumber'::text, ''::text)
                 LIMIT 1) t ON true
             LEFT JOIN LATERAL ( SELECT m.id,
                    m.doc_type,
                    m.metrc_id,
                    m.license,
                    m.package_tag,
                    m.manifest_number,
                    m.storage_path,
                    m.file_hash,
                    m.byte_size,
                    m.source_url,
                    m.fetched_at,
                    m.fetch_error,
                    m.created_at,
                    m.download_url,
                    m.url_expires_at
                   FROM metrc_documents m
                  WHERE m.doc_type = 'manifest'::text AND m.manifest_number = NULLIF(p.raw ->> 'ReceivedFromManifestNumber'::text, ''::text) AND m.download_url IS NOT NULL
                 LIMIT 1) md ON true
             LEFT JOIN LATERAL ( SELECT m2.id,
                    m2.doc_type,
                    m2.metrc_id,
                    m2.license,
                    m2.package_tag,
                    m2.manifest_number,
                    m2.storage_path,
                    m2.file_hash,
                    m2.byte_size,
                    m2.source_url,
                    m2.fetched_at,
                    m2.fetch_error,
                    m2.created_at,
                    m2.download_url,
                    m2.url_expires_at
                   FROM metrc_documents m2
                  WHERE m2.doc_type = 'coa'::text AND m2.package_tag = p.tag AND m2.download_url IS NOT NULL
                  ORDER BY m2.fetched_at DESC
                 LIMIT 1) cd ON true
             LEFT JOIN LATERAL ( SELECT f_lab_value.value,
                    f_lab_value.test_name,
                    f_lab_value.result_date
                   FROM f_lab_value(p.tag, 'Total THC'::text) f_lab_value(value, test_name, result_date)) thc ON true
             LEFT JOIN LATERAL ( SELECT f_lab_value.value,
                    f_lab_value.test_name,
                    f_lab_value.result_date
                   FROM f_lab_value(p.tag, 'Total CBD'::text) f_lab_value(value, test_name, result_date)) cbd ON true
             LEFT JOIN LATERAL ( SELECT f_lab_value.value,
                    f_lab_value.test_name,
                    f_lab_value.result_date
                   FROM f_lab_value(p.tag, 'Total Terpenes'::text) f_lab_value(value, test_name, result_date)) terp ON true
             LEFT JOIN LATERAL ( SELECT ( SELECT count(*) AS count
                           FROM metrc_lab_results r
                          WHERE r.package_tag = p.tag) AS analyte_count,
                    ( SELECT r.lab_facility
                           FROM metrc_lab_results r
                          WHERE r.package_tag = p.tag AND r.lab_facility IS NOT NULL
                         LIMIT 1) AS laboratory) lab ON true) q
     LEFT JOIN LATERAL ( SELECT e.document_id,
            e.package_tag,
            e.total_thc,
            e.total_cbd,
            e.total_terpenes,
            e.total_cannabinoids,
            e.terpene_profile,
            e.terpene_profile_source,
            e.cannabinoid_profile,
            e.cannabinoid_profile_source,
            e.microbiology,
            e.mycotoxins,
            e.heavy_metals,
            e.pesticides,
            e.solvents,
            e.pathogens,
            e.water_activity,
            e.package_tag_on_document,
            e.manifest_on_document,
            e.production_batch,
            e.sample_id,
            e.report_date,
            e.parsed_at,
            e.parser_version,
            e.parse_error,
            e.pages,
            e.characters
           FROM coa_extract e
          WHERE e.package_tag = q.package_tag
          ORDER BY e.parsed_at DESC
         LIMIT 1) ce ON true;
create or replace view public.v_production_tracker as
 SELECT 'Seed / Clone'::text AS material_class,
    'Grown'::text AS origin,
    pb.name AS item,
    pb.strain,
    pb.name AS identifier,
    COALESCE(pb.count, 0)::numeric AS quantity,
    'plants'::text AS uom,
    'Propagation'::text AS location,
    pb.planted_on AS started_on,
    (CURRENT_DATE - pb.planted_on)::numeric AS days_in_system,
    'Propagation'::text AS stage,
    pb.license,
    NULL::text AS vendor,
    NULL::numeric AS cost,
    ( SELECT a.status
           FROM allocation_requests a
          WHERE a.source_ref ~~* (('%'::text || pb.name) || '%'::text)
          ORDER BY a.created_at DESC
         LIMIT 1) AS allocation_status,
    ( SELECT a.decider_name
           FROM allocation_requests a
          WHERE a.source_ref ~~* (('%'::text || pb.name) || '%'::text) AND a.status = 'approved'::text
          ORDER BY a.decided_at DESC
         LIMIT 1) AS approved_by,
    NULL::text AS coa_link
   FROM metrc_plant_batches pb
  WHERE pb.source_state = 'active'::text
UNION ALL
 SELECT 'Plant'::text AS material_class,
    'Grown'::text AS origin,
    (pl.room || ' — '::text) || COALESCE(pl.strain, 'plants'::text) AS item,
    pl.strain,
    pl.room AS identifier,
    count(*)::numeric AS quantity,
    'plants'::text AS uom,
    pl.room AS location,
    min(pl.planted_on) AS started_on,
    max(CURRENT_DATE - pl.planted_on)::numeric AS days_in_system,
    initcap(pl.source_state) AS stage,
    pl.license,
    NULL::text AS vendor,
    NULL::numeric AS cost,
    NULL::text AS allocation_status,
    NULL::text AS approved_by,
    NULL::text AS coa_link
   FROM metrc_plants pl
  WHERE pl.source_state = ANY (ARRAY['vegetative'::text, 'flowering'::text, 'onhold'::text])
  GROUP BY pl.room, pl.strain, pl.license, pl.source_state
UNION ALL
 SELECT
        CASE
            WHEN m.harvest ~~* '%FF%'::text OR m.stage ~~* '%froz%'::text THEN 'Fresh frozen'::text
            ELSE 'Bulk flower / trim'::text
        END AS material_class,
    'Grown'::text AS origin,
    m.harvest AS item,
    m.strains AS strain,
    m.harvest AS identifier,
    round(COALESCE(m.current_weight, m.wet_weight, 0::numeric), 1) AS quantity,
    COALESCE(m.uom, 'g'::text) AS uom,
    COALESCE(m.room, '(no room)'::text) AS location,
    m.harvest_start AS started_on,
    m.days_since_takedown::numeric AS days_in_system,
    m.stage,
    m.license,
    NULL::text AS vendor,
    NULL::numeric AS cost,
    ( SELECT a.status
           FROM allocation_requests a
          WHERE a.source_ref ~~* (('%'::text || m.harvest) || '%'::text)
          ORDER BY a.created_at DESC
         LIMIT 1) AS allocation_status,
    ( SELECT a.decider_name
           FROM allocation_requests a
          WHERE a.source_ref ~~* (('%'::text || m.harvest) || '%'::text) AND a.status = 'approved'::text
          ORDER BY a.decided_at DESC
         LIMIT 1) AS approved_by,
    NULL::text AS coa_link
   FROM v_harvest_stage_map m
  WHERE m.stage <> ALL (ARRAY['Finished'::text, 'Archived'::text])
UNION ALL
 SELECT
        CASE
            WHEN COALESCE(p.raw ->> 'ProductCategoryName'::text, ''::text) ~~* '%concentrate%'::text OR COALESCE(p.item_name, ''::text) ~* '(rosin|hash|distillate|crude|diamond|isolate|badder|sauce)'::text THEN 'Concentrate'::text
            WHEN COALESCE(p.raw ->> 'ProductCategoryName'::text, ''::text) ~~* '%vape%'::text OR COALESCE(p.item_name, ''::text) ~* '(vape|cart)'::text THEN 'Vape'::text
            WHEN COALESCE(p.raw ->> 'ProductCategoryName'::text, ''::text) ~* 'pre.?roll'::text OR COALESCE(p.item_name, ''::text) ~* 'pre.?roll'::text THEN 'Pre-roll'::text
            WHEN COALESCE(p.raw ->> 'ProductCategoryName'::text, ''::text) ~~* '%flower%'::text OR COALESCE(p.item_name, ''::text) ~~* '%flower%'::text THEN 'Packaged flower'::text
            WHEN COALESCE(p.item_name, ''::text) ~~* '%trim%'::text THEN 'Trim'::text
            ELSE 'Other product'::text
        END AS material_class,
    'Grown'::text AS origin,
    COALESCE(p.item_name, '(unnamed)'::text) AS item,
    NULL::text AS strain,
    p.tag AS identifier,
    COALESCE(p.quantity, 0::numeric) AS quantity,
    COALESCE(p.uom, 'ea'::text) AS uom,
    COALESCE(p.location, '(no location)'::text) AS location,
    p.packaged_on AS started_on,
    (CURRENT_DATE - p.packaged_on)::numeric AS days_in_system,
        CASE
            WHEN (p.raw ->> 'IsOnHold'::text)::boolean THEN 'ON HOLD'::text
            WHEN p.source_state = 'intransit'::text THEN 'Shipped'::text
            WHEN p.lab_testing_state = 'TestPassed'::text THEN 'Sellable'::text
            WHEN p.lab_testing_state = 'TestFailed'::text THEN 'FAILED TESTING'::text
            ELSE COALESCE(p.lab_testing_state, 'In inventory'::text)
        END AS stage,
    p.license,
    NULL::text AS vendor,
    NULL::numeric AS cost,
    ( SELECT a.status
           FROM allocation_requests a
          WHERE a.source_ref ~~* (('%'::text || p.tag) || '%'::text)
          ORDER BY a.created_at DESC
         LIMIT 1) AS allocation_status,
    ( SELECT a.decider_name
           FROM allocation_requests a
          WHERE a.source_ref ~~* (('%'::text || p.tag) || '%'::text) AND a.status = 'approved'::text
          ORDER BY a.decided_at DESC
         LIMIT 1) AS approved_by,
    ( SELECT r.coa_link
           FROM metrc_lab_results r
          WHERE r.package_tag = p.tag AND r.coa_link IS NOT NULL
         LIMIT 1) AS coa_link
   FROM metrc_packages p
  WHERE p.source_state = ANY (ARRAY['active'::text, 'onhold'::text, 'intransit'::text])
UNION ALL
 SELECT initcap(t.material_class) || ' (purchased)'::text AS material_class,
    'Third party'::text AS origin,
    t.description AS item,
    t.strain,
    COALESCE(t.metrc_tag, t.id::text) AS identifier,
    t.quantity,
    t.uom,
    COALESCE(t.location, '(no location)'::text) AS location,
    t.received_on AS started_on,
    (CURRENT_DATE - t.received_on)::numeric AS days_in_system,
    initcap(t.status) AS stage,
    'purchased'::text AS license,
    t.vendor,
    COALESCE(t.total_cost, t.quantity * COALESCE(t.unit_cost, 0::numeric)) AS cost,
    ( SELECT a.status
           FROM allocation_requests a
          WHERE a.source_ref ~~* (('%'::text || COALESCE(t.metrc_tag, t.description)) || '%'::text)
          ORDER BY a.created_at DESC
         LIMIT 1) AS allocation_status,
    ( SELECT a.decider_name
           FROM allocation_requests a
          WHERE a.source_ref ~~* (('%'::text || COALESCE(t.metrc_tag, t.description)) || '%'::text) AND a.status = 'approved'::text
          ORDER BY a.decided_at DESC
         LIMIT 1) AS approved_by,
    t.coa_link
   FROM third_party_purchases t
  WHERE t.status <> 'finished'::text;
create or replace view public.v_production_true_position as
 WITH f AS (
         SELECT conversion_factors.value AS r
           FROM conversion_factors
          WHERE conversion_factors.key = 'fresh_frozen_wet_to_dry'::text
        ), o AS (
         SELECT v_stock_on_hand.origin,
            v_stock_on_hand.stream,
            sum(v_stock_on_hand.pounds) AS lb
           FROM v_stock_on_hand
          GROUP BY v_stock_on_hand.origin, v_stock_on_hand.stream
        )
 SELECT origin,
    stream,
    round(lb, 1) AS as_recorded_lb,
        CASE
            WHEN stream = 'Fresh frozen'::text THEN round(lb / (( SELECT f.r
               FROM f)), 1)
            ELSE round(lb, 1)
        END AS dry_equivalent_lb,
        CASE
            WHEN stream = 'Fresh frozen'::text THEN ('Divided by '::text || (( SELECT f.r
               FROM f))) || ' - frozen material still holds its water'::text
            ELSE 'Already dry - no conversion needed'::text
        END AS adjustment,
    round(100::numeric *
        CASE
            WHEN stream = 'Fresh frozen'::text THEN lb / (( SELECT f.r
               FROM f))
            ELSE lb
        END / sum(
        CASE
            WHEN stream = 'Fresh frozen'::text THEN lb / (( SELECT f.r
               FROM f))
            ELSE lb
        END) OVER (), 1) AS pct_of_true_production
   FROM o
  ORDER BY (
        CASE
            WHEN stream = 'Fresh frozen'::text THEN round(lb / (( SELECT f.r
               FROM f)), 1)
            ELSE round(lb, 1)
        END) DESC;
create or replace view public.v_pull_yield as
 WITH linked AS (
         SELECT v_harvest_pull_link.harvest_id,
            v_harvest_pull_link.harvest_name,
            v_harvest_pull_link.takedown_date,
            v_harvest_pull_link.room_actual,
            v_harvest_pull_link.room_planned,
            v_harvest_pull_link.is_fresh_frozen,
            v_harvest_pull_link.pull_no,
            v_harvest_pull_link.pull_planned_date,
            v_harvest_pull_link.days_from_planned_pull,
            v_harvest_pull_link.planned_plants,
            v_harvest_pull_link.projected_flower_after_ff_lb,
            v_harvest_pull_link.wet_weight,
            v_harvest_pull_link.package_count,
            v_harvest_pull_link.link_note,
            v_harvest_pull_link.name_date_disagreement
           FROM v_harvest_pull_link
          WHERE v_harvest_pull_link.pull_no IS NOT NULL
        ), pkg_single AS (
         SELECT l.pull_no,
            l.is_fresh_frozen,
            p.raw #>> '{Item,ProductCategoryName}'::text[] AS category,
            f_to_pounds((p.raw ->> 'CreatedQuantity'::text)::numeric, p.raw ->> 'CreatedQuantityUnitOfMeasureAbbreviation'::text) AS created_lb
           FROM linked l
             JOIN metrc_packages p ON (p.raw ->> 'SourceHarvestNames'::text) = l.harvest_name AND COALESCE((p.raw ->> 'SourceHarvestCount'::text)::integer, 1) = 1
        ), pkg_multi AS (
         SELECT DISTINCT l.pull_no,
            p.id AS package_id,
            f_to_pounds((p.raw ->> 'CreatedQuantity'::text)::numeric, p.raw ->> 'CreatedQuantityUnitOfMeasureAbbreviation'::text) AS created_lb
           FROM metrc_packages p
             CROSS JOIN LATERAL unnest(string_to_array(p.raw ->> 'SourceHarvestNames'::text, ', '::text)) hn(harvest_name)
             JOIN linked l ON l.harvest_name = btrim(hn.harvest_name)
          WHERE COALESCE((p.raw ->> 'SourceHarvestCount'::text)::integer, 1) > 1
        ), agg AS (
         SELECT pkg_single.pull_no,
            sum(pkg_single.created_lb) FILTER (WHERE NOT pkg_single.is_fresh_frozen AND pkg_single.category ~~* '%bud%'::text) AS dried_bud_lb,
            sum(pkg_single.created_lb) FILTER (WHERE NOT pkg_single.is_fresh_frozen AND (pkg_single.category ~~* '%shake%'::text OR pkg_single.category ~~* '%trim%'::text)) AS shake_trim_lb,
            sum(pkg_single.created_lb) FILTER (WHERE pkg_single.is_fresh_frozen) AS fresh_frozen_lb
           FROM pkg_single
          GROUP BY pkg_single.pull_no
        ), multi AS (
         SELECT pkg_multi.pull_no,
            sum(pkg_multi.created_lb) AS multi_lb,
            count(*) AS multi_packages
           FROM pkg_multi
          GROUP BY pkg_multi.pull_no
        ), h AS (
         SELECT linked.pull_no,
            count(*) AS harvests,
            count(*) FILTER (WHERE linked.is_fresh_frozen) AS fresh_frozen_harvests,
            string_agg(DISTINCT linked.room_actual, '/'::text ORDER BY linked.room_actual) AS rooms_actual,
            bool_or(linked.room_actual IS DISTINCT FROM linked.room_planned) AS room_drifted,
            sum(linked.wet_weight) / 453.592 AS wet_lb
           FROM linked
          GROUP BY linked.pull_no
        )
 SELECT pl.pull_no,
    pl.harvest_date AS pull_planned_date,
    pl.flower_room AS room_planned,
    h.rooms_actual,
    h.room_drifted,
    pl.planned_plants,
    h.harvests,
    h.fresh_frozen_harvests,
    round(h.wet_lb, 1) AS wet_lb,
    round(a.dried_bud_lb, 1) AS dried_bud_lb,
    round(a.shake_trim_lb, 1) AS shake_trim_lb,
    round(a.fresh_frozen_lb, 1) AS fresh_frozen_lb,
    round(m.multi_lb, 1) AS multi_harvest_lb_unallocated,
    m.multi_packages AS multi_harvest_packages,
    round(pl.projected_flower_after_ff_lb, 1) AS plan_dried_lb,
    f_rule('pull_target_dried_lb'::text) AS owner_target_dried_lb,
    round(a.dried_bud_lb - pl.projected_flower_after_ff_lb, 1) AS vs_plan_lb,
    round(a.dried_bud_lb - f_rule('pull_target_dried_lb'::text), 1) AS vs_owner_target_lb,
        CASE
            WHEN h.harvests IS NULL THEN 'NO HARVESTS LINKED to this pull. Either it has not happened yet, or it happened and was not recorded in Metrc. If the date has passed, this is urgent.'::text
            WHEN a.dried_bud_lb IS NULL AND h.fresh_frozen_harvests = h.harvests THEN 'No dried flower - every harvest in this pull was taken as fresh frozen, which is packaged wet and must never be added to a dried figure.'::text
            WHEN a.dried_bud_lb IS NULL THEN 'No dried flower packaged yet. Harvest to availability runs about 28 days, so a recent pull reads empty until curing finishes.'::text
            WHEN m.multi_lb > 0::numeric THEN ((('FLOOR, not a total. A further '::text || m.multi_packages) || ' package(s) holding '::text) || round(m.multi_lb, 1)) || ' lb draw on this pull AND others, and are NOT included - splitting them across pulls is an owner decision not yet made. They are listed against every pull they touch, so they must never simply be added.'::text
            ELSE 'Complete for single-harvest packages. No multi-harvest packages touch this pull.'::text
        END AS completeness_note
   FROM harvest_plan_2026 pl
     LEFT JOIN h ON h.pull_no = pl.pull_no
     LEFT JOIN agg a ON a.pull_no = pl.pull_no
     LEFT JOIN multi m ON m.pull_no = pl.pull_no
  ORDER BY pl.pull_no;
create or replace view public.v_real_loss_summary as
 SELECT loss_type,
    count(*)::numeric AS occurrences,
    round(sum(COALESCE(units, 0::numeric)), 0) AS units,
    round(sum(COALESCE(pounds, 0::numeric)), 1) AS pounds_affected,
    round(sum(COALESCE(pounds, 0::numeric)) * (( SELECT cost_model.cost_per_pound
           FROM cost_model
          WHERE cost_model.scope = 'cultivation'::text
          ORDER BY cost_model.effective_from DESC
         LIMIT 1)), 0) AS dollars_at_target_cost,
    max(why_it_is_a_loss) AS why_it_is_a_loss
   FROM v_real_loss
  GROUP BY loss_type
  ORDER BY (round(sum(COALESCE(pounds, 0::numeric)) * (( SELECT cost_model.cost_per_pound
           FROM cost_model
          WHERE cost_model.scope = 'cultivation'::text
          ORDER BY cost_model.effective_from DESC
         LIMIT 1)), 0)) DESC NULLS LAST;
create or replace view public.v_reconciliation_status as
 WITH facts AS (
         SELECT v_cross_source_reconciliation.fact,
            v_cross_source_reconciliation.unit,
            COALESCE(abs(v_cross_source_reconciliation.value_difference), 0::numeric) AS difference,
            COALESCE(v_cross_source_reconciliation.value_not_covered, 0::numeric) AS not_covered,
            v_cross_source_reconciliation.verdict
           FROM v_cross_source_reconciliation
        ), explained AS (
         SELECT reconciliation_exception.fact,
            sum(COALESCE(reconciliation_exception.amount, 0::numeric)) AS explained_amount,
            count(*) AS exceptions
           FROM reconciliation_exception
          WHERE reconciliation_exception.resolved_on IS NULL
          GROUP BY reconciliation_exception.fact
        )
 SELECT f.fact,
    f.unit,
    f.difference,
    COALESCE(e.explained_amount, 0::numeric) AS explained,
    f.difference - COALESCE(e.explained_amount, 0::numeric) AS unexplained,
    COALESCE(e.exceptions, 0::bigint) AS open_exceptions,
        CASE
            WHEN f.difference = 0::numeric AND f.not_covered = 0::numeric THEN 'BALANCES'::text
            WHEN (f.difference - COALESCE(e.explained_amount, 0::numeric)) = 0::numeric THEN 'balances once explained'::text
            ELSE 'UNEXPLAINED DIFFERENCE - this is the one that matters'::text
        END AS status
   FROM facts f
     LEFT JOIN explained e USING (fact)
  ORDER BY (f.difference - COALESCE(e.explained_amount, 0::numeric)) DESC, f.fact;
create or replace view public.v_reconciliation_unresolved as
 SELECT manifest_number,
    licence,
    created_on,
    wholesale_value,
    package_as_of,
    ('Raised on the same day the package export was pulled. An as-of date cannot '::text || 'resolve time of day, so this cannot be judged either way. It resolves itself '::text) || 'on the next package export.'::text AS why
   FROM v_wholesale_reconciliation
  WHERE reading = 'In the wholesale report only'::text AND COALESCE(wholesale_value, 0::numeric) > 0::numeric AND created_on = (( SELECT max(metrc_rpt_package_transfers.as_of_date) AS max
           FROM metrc_rpt_package_transfers));
create or replace view public.v_report_standard as
 SELECT w.view_key,
    w.label,
    w.category,
    w.page_kind,
    w.table_ref,
    w.object_kind,
    w.fields,
    w.date_columns,
    w.roles_who_can_see,
    w.in_report_registry,
    w.page_kind = 'report'::text AS needs_toolbar,
    w.date_columns > 0 AS can_filter_by_date,
    w.fields >= 3 AS worth_filtering,
    w.roles_who_can_see > 0 AS someone_can_open_it,
    w.claims_proving_it > 0 AS figure_is_proven,
        CASE
            WHEN w.page_kind = 'application'::text THEN 'EXEMPT - hand-built screen, no report toolbar'::text
            WHEN w.roles_who_can_see = 0 THEN 'FAILS - nobody can open it'::text
            WHEN n.date_policy = 'not_applicable'::text THEN 'MEETS THE STANDARD - date control OMITTED, a date is meaningless here'::text
            WHEN w.date_columns = 0 THEN 'DEFECT - the source carries a date and this view drops it. Fix the view, do NOT omit the control'::text
            WHEN w.fields < 3 THEN 'THIN - too few fields to be worth filtering'::text
            ELSE 'MEETS THE STANDARD'::text
        END AS standard,
    'THE STANDARD: every report page carries the SAME toolbar - the 27-preset date range with editable From/To, global search, per-column filters, sort, column chooser, group-by with subtotals, export to PDF/CSV/Excel/Sheets carrying the active filters, drill to the raw Metrc record, and owner_note displayed. Same position, same wording, same shortcuts.'::text AS what_good_looks_like,
    'OWNER RULING: where a date is genuinely meaningless, OMIT the control - do not grey it out. Where the source HAS a date the view dropped, that is a defect: fix the view. Never omit to hide a missing date.'::text AS what_to_do,
    n.date_policy
   FROM v_page_wiring w
     JOIN nav_registry n ON n.view_key = w.view_key;
create or replace view public.v_report_upload_alerts as
 SELECT d.report_key,
    d.title,
    d.licence,
    d.period_label,
    d.due_by,
    d.days_late,
    d.severity,
    d.upload_status,
    d.cadence,
    d.menu_path,
    d.why_it_matters,
    u.user_id,
    COALESCE(u.display_name, u.role::text) AS recipient,
    u.role::text AS role,
    r.notify_in_app,
    r.notify_email,
    (((('Metrc report not uploaded: '::text || d.title) || ' ('::text) || d.licence) || ') for '::text) || d.period_label AS subject,
    (((((((((((d.title || ' for '::text) || d.period_label) || ' on licence '::text) || d.licence) || ' has not been uploaded. '::text) || d.upload_status) || '. '::text) || d.why_it_matters) || '  Export it from Metrc at: '::text) || d.menu_path) || '  then upload it on Settings > Metrc Report Imports. No mapping is needed'::text) || ' - the file is identified automatically from its columns.'::text AS body
   FROM v_report_upload_due d
     JOIN report_alert_recipients r ON true
     JOIN app_users u ON u.role::text = r.role
  WHERE NOT d.received AND (r.min_severity = 'due'::text OR r.min_severity = 'elevated'::text AND (d.severity = ANY (ARRAY['elevated'::text, 'critical'::text])) OR r.min_severity = 'critical'::text AND d.severity = 'critical'::text);
create or replace view public.v_room_best_vs_worst as
 SELECT room,
    max(conversion_pct) FILTER (WHERE standing = 'BEST MONTH for this room'::text) AS best_conversion,
    max(month) FILTER (WHERE standing = 'BEST MONTH for this room'::text) AS best_month,
    max(grams_per_plant) FILTER (WHERE standing = 'BEST MONTH for this room'::text) AS best_grams_per_plant,
    max(dry_days) FILTER (WHERE standing = 'BEST MONTH for this room'::text) AS best_dry_days,
    min(conversion_pct) FILTER (WHERE standing = 'WORST MONTH for this room'::text) AS worst_conversion,
    max(month) FILTER (WHERE standing = 'WORST MONTH for this room'::text) AS worst_month,
    max(grams_per_plant) FILTER (WHERE standing = 'WORST MONTH for this room'::text) AS worst_grams_per_plant,
    max(dry_days) FILTER (WHERE standing = 'WORST MONTH for this room'::text) AS worst_dry_days,
    round(max(conversion_pct) FILTER (WHERE standing = 'BEST MONTH for this room'::text) - min(conversion_pct) FILTER (WHERE standing = 'WORST MONTH for this room'::text), 1) AS spread_points,
    round(sum(dollars_lost_versus_room_best), 0) AS total_dollars_lost_versus_own_best,
    ('This room is capable of '::text || max(conversion_pct) FILTER (WHERE standing = 'BEST MONTH for this room'::text)) || ' percent - it has already done it. Everything below that is practice, not capacity.'::text AS what_this_means
   FROM v_room_month_comparison
  GROUP BY room
  ORDER BY (round(sum(dollars_lost_versus_room_best), 0)) DESC NULLS LAST;
create or replace view public.v_room_board as
 SELECT gr.code AS room,
    'Flower room'::text AS room_type,
    (( SELECT count(*) AS count
           FROM metrc_plants p
          WHERE p.room ~~* (('%'::text || replace(gr.code, 'F'::text, 'Flower Room #'::text)) || '%'::text) AND (p.source_state = ANY (ARRAY['vegetative'::text, 'flowering'::text, 'onhold'::text]))))::numeric AS plants_now,
    ( SELECT string_agg(DISTINCT p.strain, ', '::text) AS string_agg
           FROM metrc_plants p
          WHERE p.room ~~* (('%'::text || replace(gr.code, 'F'::text, 'Flower Room #'::text)) || '%'::text) AND (p.source_state = ANY (ARRAY['vegetative'::text, 'flowering'::text, 'onhold'::text]))) AS strains_now,
    NULL::numeric AS weight_on_hand,
    ( SELECT min(hp.harvest_date) AS min
           FROM harvest_pulls hp
          WHERE hp.flower_room = gr.code AND hp.harvest_date >= CURRENT_DATE) AS next_event_date,
    'Next scheduled pull'::text AS next_event,
    (( SELECT hp.harvest_date - CURRENT_DATE
           FROM harvest_pulls hp
          WHERE hp.flower_room = gr.code AND hp.harvest_date >= CURRENT_DATE
          ORDER BY hp.harvest_date
         LIMIT 1))::numeric AS days_until,
    ( SELECT hp.cultivars
           FROM harvest_pulls hp
          WHERE hp.flower_room = gr.code AND hp.harvest_date >= CURRENT_DATE
          ORDER BY hp.harvest_date
         LIMIT 1) AS next_event_detail,
    gr.plant_capacity,
    gr.cycle_days
   FROM grow_rooms gr
  WHERE gr.active
UNION ALL
 SELECT m.room,
    'Post-harvest room'::text AS room_type,
    sum(m.plants) AS plants_now,
    string_agg(DISTINCT m.strains, ', '::text) AS strains_now,
    round(sum(COALESCE(m.current_weight, m.wet_weight, 0::numeric)), 1) AS weight_on_hand,
    min(m.harvest_start + 14) AS next_event_date,
    'Dry deadline (day 14)'::text AS next_event,
    min(m.harvest_start + 14 - CURRENT_DATE)::numeric AS days_until,
    string_agg(DISTINCT m.stage, ' · '::text) AS next_event_detail,
    NULL::integer AS plant_capacity,
    NULL::integer AS cycle_days
   FROM v_harvest_stage_map m
  WHERE (m.stage <> ALL (ARRAY['Finished'::text, 'Archived'::text])) AND COALESCE(m.room, ''::text) <> ''::text
  GROUP BY m.room;
create or replace view public.v_sales_history_monthly as
 SELECT licence AS license,
    f_operation(licence) AS operation,
    to_char(created_on::timestamp with time zone, 'YYYY-MM'::text) AS month,
    date_trunc('month'::text, created_on::timestamp with time zone)::date AS month_date,
    count(*) FILTER (WHERE is_customer_sale)::numeric AS manifests_sent,
    count(DISTINCT recipient) FILTER (WHERE is_customer_sale)::numeric AS customers,
    sum(COALESCE((raw ->> 'PackageCount'::text)::numeric, 0::numeric)) FILTER (WHERE is_customer_sale) AS packages_sold,
    sum(COALESCE((raw ->> 'ReceivedPackageCount'::text)::numeric, 0::numeric)) FILTER (WHERE is_customer_sale) AS packages_confirmed,
    count(*) FILTER (WHERE is_customer_sale AND (raw ->> 'ReceivedDateTime'::text) IS NULL)::numeric AS manifests_unconfirmed,
    count(*) FILTER (WHERE movement = 'Internal move'::text)::numeric AS internal_moves,
    count(*) FILTER (WHERE movement = 'Laboratory sample'::text)::numeric AS lab_samples,
    count(*) FILTER (WHERE is_inbound_purchase)::numeric AS bought_in,
    string_agg(DISTINCT recipient, ', '::text) FILTER (WHERE is_customer_sale) AS customer_list
   FROM v_manifest_ledger m
  WHERE created_on IS NOT NULL
  GROUP BY licence, (to_char(created_on::timestamp with time zone, 'YYYY-MM'::text)), (date_trunc('month'::text, created_on::timestamp with time zone))
  ORDER BY (date_trunc('month'::text, created_on::timestamp with time zone)::date) DESC;
create or replace view public.v_schedule_compliance as
 WITH r AS (
         SELECT harvest_alert_rules.rule_key,
            harvest_alert_rules.threshold
           FROM harvest_alert_rules
          WHERE harvest_alert_rules.active
        ), pulls AS (
         SELECT p.pull_no,
            p.harvest_date AS scheduled_date,
            p.flower_room,
            p.cultivars,
            p.original_total_plants AS planned_plants,
            p.proj_harvest_weight_lbs AS planned_lbs,
            p.facility_days_since_last_pull AS planned_gap_days,
            ( SELECT min(h.harvest_start) AS min
                   FROM metrc_harvests h
                  WHERE COALESCE(h.raw ->> 'DryingLocationName'::text, ''::text) <> ''::text AND h.harvest_start >= (p.harvest_date - 5) AND h.harvest_start <= (p.harvest_date + 21)) AS actual_date
           FROM harvest_pulls p
        )
 SELECT 'Pull'::text AS event_type,
    pl.pull_no,
    pl.flower_room AS room,
    pl.cultivars,
    pl.scheduled_date,
    pl.actual_date,
        CASE
            WHEN pl.actual_date IS NULL AND pl.scheduled_date < CURRENT_DATE THEN CURRENT_DATE - pl.scheduled_date
            WHEN pl.actual_date IS NOT NULL THEN pl.actual_date - pl.scheduled_date
            ELSE NULL::integer
        END AS days_off_schedule,
        CASE
            WHEN pl.actual_date IS NULL AND pl.scheduled_date < (CURRENT_DATE - (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'pull_overdue_days'::text))::integer) THEN ('MISSED - never harvested, '::text || (CURRENT_DATE - pl.scheduled_date)) || ' days past schedule'::text
            WHEN pl.actual_date IS NULL AND pl.scheduled_date >= CURRENT_DATE THEN 'Scheduled'::text
            WHEN pl.actual_date > (pl.scheduled_date + 2) THEN ('LATE by '::text || (pl.actual_date - pl.scheduled_date)) || ' days'::text
            WHEN pl.actual_date < (pl.scheduled_date - 2) THEN ('Early by '::text || (pl.scheduled_date - pl.actual_date)) || ' days'::text
            ELSE 'On schedule'::text
        END AS compliance,
    pl.planned_plants,
    round(COALESCE(pl.planned_lbs, 0::numeric), 1) AS planned_lbs,
    pl.planned_gap_days,
    NULL::text AS room_now,
    NULL::numeric AS days_in_dry
   FROM pulls pl
UNION ALL
 SELECT 'Dry'::text AS event_type,
    NULL::integer AS pull_no,
    m.room,
    m.strains AS cultivars,
    m.harvest_start AS scheduled_date,
    m.harvest_start + (( SELECT r.threshold
           FROM r
          WHERE r.rule_key = 'dry_max_days'::text))::integer AS actual_date,
        CASE
            WHEN m.stage ~~ 'Drying%'::text AND m.days_since_takedown::numeric > (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'dry_max_days'::text)) THEN m.days_since_takedown - (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'dry_max_days'::text))::integer
            ELSE NULL::integer
        END AS days_off_schedule,
        CASE
            WHEN m.stage !~~ 'Drying%'::text AND m.stage <> 'Curing / Trim'::text THEN 'Dry complete'::text
            WHEN m.days_since_takedown::numeric > (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'dry_max_days'::text)) THEN ('DRY DEADLINE BLOWN by '::text || (m.days_since_takedown - (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'dry_max_days'::text))::integer)) || ' days'::text
            WHEN m.days_since_takedown::numeric >= (( SELECT r.threshold
               FROM r
              WHERE r.rule_key = 'dry_target_days'::text)) THEN 'At dry target - finish now'::text
            ELSE 'On schedule'::text
        END AS compliance,
    m.plants AS planned_plants,
    round(COALESCE(m.wet_weight, 0::numeric) / 453.592, 1) AS planned_lbs,
    NULL::numeric AS planned_gap_days,
    m.room AS room_now,
    m.days_since_takedown AS days_in_dry
   FROM v_harvest_stage_map m
  WHERE m.stage <> ALL (ARRAY['Finished'::text, 'Archived'::text]);
create or replace view public.v_sheet_metrc_alerts as
 SELECT source_name,
    verdict,
    count(*) AS rows_affected,
    round(sum(abs(COALESCE(difference, 0::numeric))), 2) AS total_difference,
        CASE verdict
            WHEN 'IN THE SHEET, NOT IN METRC'::text THEN 'critical'::text
            WHEN 'QUANTITY DISAGREES'::text THEN 'critical'::text
            WHEN 'IN METRC, NOT IN THE SHEET'::text THEN 'elevated'::text
            WHEN 'NO QUANTITY IN THE SHEET'::text THEN 'elevated'::text
            ELSE 'watch'::text
        END AS severity,
    min(what_it_means) AS example
   FROM v_sheet_metrc_reconciliation
  WHERE verdict <> 'AGREES'::text
  GROUP BY source_name, verdict
  ORDER BY (
        CASE verdict
            WHEN 'QUANTITY DISAGREES'::text THEN 1
            WHEN 'IN THE SHEET, NOT IN METRC'::text THEN 2
            WHEN 'IN METRC, NOT IN THE SHEET'::text THEN 3
            ELSE 4
        END);
create or replace view public.v_stock_summary as
 SELECT origin,
    stream,
    packages,
    sold_by_weight,
    f_uom_label(unit_of_measure) AS unit_of_measure,
    total_lb,
    units,
    sellable_lb,
    failed_lb,
    failed_ours_lb,
    failed_third_party_lb,
    failed_third_party_suppliers,
    out_for_testing_lb,
    untested_lb,
    sellable_units,
    untested_units,
    oldest_days,
    suppliers
   FROM ( SELECT v_stock_on_hand.origin,
            v_stock_on_hand.stream,
            sum(v_stock_on_hand.packages) AS packages,
            bool_and(v_stock_on_hand.sold_by_weight) AS sold_by_weight,
            max(v_stock_on_hand.unit_of_measure) AS unit_of_measure,
            round(sum(v_stock_on_hand.pounds), 1) AS total_lb,
            sum(v_stock_on_hand.units) AS units,
            round(COALESCE(sum(v_stock_on_hand.pounds) FILTER (WHERE v_stock_on_hand.lab_state = 'TestPassed'::text), 0::numeric), 1) AS sellable_lb,
            round(COALESCE(sum(v_stock_on_hand.pounds) FILTER (WHERE v_stock_on_hand.lab_state = 'TestFailed'::text), 0::numeric), 1) AS failed_lb,
            round(COALESCE(sum(v_stock_on_hand.pounds) FILTER (WHERE v_stock_on_hand.lab_state = 'TestFailed'::text AND f_is_ours(v_stock_on_hand.origin_license)), 0::numeric), 1) AS failed_ours_lb,
            round(COALESCE(sum(v_stock_on_hand.pounds) FILTER (WHERE v_stock_on_hand.lab_state = 'TestFailed'::text AND NOT f_is_ours(v_stock_on_hand.origin_license)), 0::numeric), 1) AS failed_third_party_lb,
            COALESCE(string_agg(DISTINCT v_stock_on_hand.supplier, ', '::text) FILTER (WHERE v_stock_on_hand.lab_state = 'TestFailed'::text AND NOT f_is_ours(v_stock_on_hand.origin_license)), 'none'::text) AS failed_third_party_suppliers,
            round(COALESCE(sum(v_stock_on_hand.pounds) FILTER (WHERE v_stock_on_hand.lab_state ~~ '%ubmitted%'::text AND v_stock_on_hand.lab_state <> 'NotSubmitted'::text), 0::numeric), 1) AS out_for_testing_lb,
            round(COALESCE(sum(v_stock_on_hand.pounds) FILTER (WHERE v_stock_on_hand.lab_state = 'NotSubmitted'::text), 0::numeric), 1) AS untested_lb,
            COALESCE(sum(v_stock_on_hand.units) FILTER (WHERE v_stock_on_hand.lab_state = 'TestPassed'::text), 0::numeric) AS sellable_units,
            COALESCE(sum(v_stock_on_hand.units) FILTER (WHERE v_stock_on_hand.lab_state = 'NotSubmitted'::text), 0::numeric) AS untested_units,
            max(v_stock_on_hand.oldest_days) AS oldest_days,
            string_agg(DISTINCT v_stock_on_hand.supplier, ', '::text) AS suppliers
           FROM v_stock_on_hand
          GROUP BY v_stock_on_hand.origin, v_stock_on_hand.stream
          ORDER BY v_stock_on_hand.origin, (COALESCE(round(sum(v_stock_on_hand.pounds), 1), sum(v_stock_on_hand.units))) DESC) q;
create or replace view public.v_storage_limit_status as
 SELECT l.stream,
    NULLIF(l.location, ''::text) AS location,
    l.max_lb,
    l.max_age_days,
    l.warn_at_pct,
    l.note,
    round(COALESCE(s.on_hand_lb, 0::numeric), 1) AS on_hand_lb,
    COALESCE(s.oldest_days, 0) AS oldest_days,
        CASE
            WHEN l.max_lb IS NULL THEN NULL::numeric
            ELSE round(100::numeric * COALESCE(s.on_hand_lb, 0::numeric) / l.max_lb, 1)
        END AS pct_of_limit,
        CASE
            WHEN l.max_lb IS NULL AND l.max_age_days IS NULL THEN 'NO LIMIT SET - an owner needs to decide this'::text
            WHEN l.max_lb IS NOT NULL AND COALESCE(s.on_hand_lb, 0::numeric) > l.max_lb THEN 'OVER THE STORAGE LIMIT'::text
            WHEN l.max_age_days IS NOT NULL AND COALESCE(s.oldest_days, 0) > l.max_age_days THEN 'MATERIAL OLDER THAN THE LIMIT'::text
            WHEN l.max_lb IS NOT NULL AND COALESCE(s.on_hand_lb, 0::numeric) > (l.max_lb * l.warn_at_pct / 100::numeric) THEN 'APPROACHING THE LIMIT'::text
            ELSE 'Within limits'::text
        END AS status
   FROM storage_limits l
     LEFT JOIN ( SELECT v_stock_on_hand.stream,
            sum(v_stock_on_hand.pounds) AS on_hand_lb,
            max(v_stock_on_hand.oldest_days) AS oldest_days
           FROM v_stock_on_hand
          GROUP BY v_stock_on_hand.stream) s ON s.stream = l.stream;
create or replace view public.v_sync_item as
 SELECT sync_item.source_key,
    sync_item.source_label,
    sync_item.fn,
    sync_item.item_key,
    sync_item.item_label,
    sync_item.query_param,
    sync_item.extra_params,
    sync_item.note,
    sync_item.enabled,
    sync_item.supported,
    sync_item.sort,
    NULL::bigint AS rows_stored,
    NULL::timestamp with time zone AS last_success_at,
    NULL::text AS last_status,
    NULL::boolean AS due,
    NULL::text AS due_text,
    sync_item.system_label,
    sync_item.source_name,
    sync_item.pulls,
    sync_item.target
   FROM sync_item
UNION ALL
 SELECT 'apex'::text AS source_key,
    'Apex Trading (sales)'::text AS source_label,
    'apex-sync'::text AS fn,
    s.entity AS item_key,
    COALESCE(e.label, s.entity) AS item_label,
    'entity'::text AS query_param,
    '{"force": "1"}'::jsonb AS extra_params,
    NULL::text AS note,
    true AS enabled,
    true AS supported,
    70 +
        CASE s.kind
            WHEN 'money'::text THEN 0
            WHEN 'core'::text THEN 1
            WHEN 'crm'::text THEN 2
            WHEN 'document'::text THEN 3
            ELSE 4
        END AS sort,
    s.rows_stored,
    s.last_success_at,
    s.last_status,
    s.due,
    s.due_text,
    'Apex Trading'::text AS system_label,
    'Apex Trading API — app.apextrading.com, the sales source of record'::text AS source_name,
    COALESCE(e.why, 'Apex '::text || s.entity) AS pulls,
    ('apex_raw (entity = '::text || s.entity) || ')'::text AS target
   FROM v_apex_entity_status s
     JOIN apex_entity e ON e.entity = s.entity;
create or replace view public.v_third_party_downstream as
 SELECT src.supplier,
    src.tag AS source_tag,
    src.item_name AS source_item,
    src.strain,
    src.received_qty,
    src.uom AS source_uom,
    child.tag AS made_into_tag,
    child.item_name AS made_into,
    child.raw #>> '{Item,ProductCategoryName}'::text[] AS made_into_category,
    child.quantity AS made_qty,
    child.uom AS made_uom,
    child.packaged_on AS made_on,
    child.raw ->> 'LabTestingState'::text AS made_lab_state,
    child.license AS made_under
   FROM v_third_party_chain src
     JOIN metrc_packages child ON (child.raw ->> 'SourcePackageLabels'::text) ~~ (('%'::text || src.tag) || '%'::text)
  ORDER BY src.supplier, src.received_on DESC NULLS LAST;
create or replace view public.v_third_party_lifecycle as
 WITH inbound AS (
         SELECT p.tag,
            p.item_name,
            p.license AS held_under,
            p.location,
            COALESCE(NULLIF(p.raw ->> 'ReceivedFromFacilityName'::text, ''::text), '(supplier not recorded)'::text) AS supplier,
            p.raw ->> 'ItemFromFacilityLicenseNumber'::text AS origin_license,
            p.raw ->> 'ReceivedFromManifestNumber'::text AS inbound_manifest,
            (p.raw ->> 'ReceivedDateTime'::text)::date AS received_on,
            (p.raw ->> 'ReceivedQuantity'::text)::numeric AS qty_received,
            p.quantity AS qty_remaining,
            p.uom,
            p.raw #>> '{Item,ProductCategoryName}'::text[] AS category,
            p.raw #>> '{Item,StrainName}'::text[] AS strain,
            p.raw ->> 'LabTestingState'::text AS lab_state,
            (p.raw ->> 'LabTestingRecordedDate'::text)::date AS tested_on,
            (p.raw ->> 'IsFinished'::text)::boolean AS finished,
            (p.raw ->> 'FinishedDate'::text)::date AS finished_on
           FROM metrc_packages p
          WHERE (COALESCE(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text) <> ALL (ARRAY['MC281714'::text, 'MP281909'::text])) AND COALESCE(p.raw ->> 'ItemFromFacilityLicenseNumber'::text, ''::text) <> ''::text
        ), made AS (
         SELECT i_1.tag AS parent_tag,
            count(*) AS children,
            min(c.packaged_on) AS first_output_on,
            max(c.packaged_on) AS last_output_on,
            round(sum(c.quantity)) AS output_qty,
            string_agg(DISTINCT c.raw #>> '{Item,ProductCategoryName}'::text[], ', '::text) AS became,
            count(*) FILTER (WHERE (c.raw ->> 'LabTestingState'::text) = 'TestPassed'::text) AS output_passed,
            count(*) FILTER (WHERE (c.raw ->> 'LabTestingState'::text) = 'TestFailed'::text) AS output_failed
           FROM inbound i_1
             JOIN metrc_packages c ON (c.raw ->> 'SourcePackageLabels'::text) ~~ (('%'::text || i_1.tag) || '%'::text)
          GROUP BY i_1.tag
        ), sold AS (
         SELECT i_1.tag AS parent_tag,
            min(t.created_on) AS first_shipped_on,
            count(DISTINCT t.manifest_number) AS outbound_manifests,
            string_agg(DISTINCT t.recipient, ', '::text) AS sold_to
           FROM inbound i_1
             JOIN metrc_packages c ON (c.raw ->> 'SourcePackageLabels'::text) ~~ (('%'::text || i_1.tag) || '%'::text)
             JOIN v_metrc_transfer_ledger t ON t.direction = 'outgoing'::text AND t.created_on >= c.packaged_on
          GROUP BY i_1.tag
        )
 SELECT i.supplier,
    i.origin_license,
    i.inbound_manifest,
    i.received_on,
    i.tag,
    i.item_name,
    i.strain,
    i.category,
    i.held_under,
    i.location,
    i.qty_received,
    i.qty_remaining,
    i.uom,
    round(COALESCE(i.qty_received, 0::numeric) - COALESCE(i.qty_remaining, 0::numeric)) AS qty_consumed,
    i.lab_state,
    i.tested_on,
    i.tested_on - i.received_on AS days_receipt_to_test,
    m.children AS products_made,
    m.became,
    m.output_qty,
    m.output_passed,
    m.output_failed,
    m.first_output_on,
    m.first_output_on - i.received_on AS days_receipt_to_first_output,
        CASE
            WHEN COALESCE(i.qty_received, 0::numeric) > 0::numeric THEN round(100.0 * COALESCE(m.output_qty, 0::numeric) / i.qty_received, 1)
            ELSE NULL::numeric
        END AS recovery_pct,
    s.first_shipped_on,
    s.outbound_manifests,
    s.sold_to,
    s.first_shipped_on - i.received_on AS days_receipt_to_first_sale,
    CURRENT_DATE - i.received_on AS days_since_received,
        CASE
            WHEN i.qty_remaining = 0::numeric AND s.first_shipped_on IS NOT NULL THEN ('COMPLETE - received, processed and sold in '::text || (s.first_shipped_on - i.received_on)) || ' days'::text
            WHEN i.qty_remaining = 0::numeric AND m.children IS NOT NULL THEN 'PROCESSED - made into product, not yet traced to a sale'::text
            WHEN i.qty_remaining = 0::numeric THEN 'DRAWN TO ZERO - no output package traced. Investigate.'::text
            WHEN m.children IS NOT NULL THEN ((('IN PROCESS - part drawn, '::text || round(i.qty_remaining)) || ' '::text) || i.uom) || ' left'::text
            WHEN (CURRENT_DATE - i.received_on) > 90 THEN ('SITTING '::text || (CURRENT_DATE - i.received_on)) || ' DAYS UNTOUCHED - purchased cash doing nothing'::text
            ELSE 'RECEIVED - not yet drawn'::text
        END AS "position"
   FROM inbound i
     LEFT JOIN made m ON m.parent_tag = i.tag
     LEFT JOIN sold s ON s.parent_tag = i.tag
  ORDER BY i.received_on DESC NULLS LAST;
create or replace view public.v_third_party_stock as
 SELECT supplier,
    origin_license,
    stream,
    held_under,
    lab_state,
    location,
    packages,
    pounds,
    oldest_days,
    oldest_packaged,
    strains,
    why_separate,
    oldest_packaged AS oldest_packaged_date
   FROM ( SELECT v_stock_on_hand.supplier,
            v_stock_on_hand.origin_license,
            v_stock_on_hand.stream,
            v_stock_on_hand.license AS held_under,
            v_stock_on_hand.lab_state,
            v_stock_on_hand.location,
            v_stock_on_hand.packages,
            v_stock_on_hand.pounds,
            v_stock_on_hand.oldest_days,
            v_stock_on_hand.oldest_packaged,
            v_stock_on_hand.strains,
            'Bought in from another licence. Must be tracked, allocated and costed separately from what we grow.'::text AS why_separate
           FROM v_stock_on_hand
          WHERE v_stock_on_hand.origin <> 'Grown by us'::text
          ORDER BY v_stock_on_hand.pounds DESC) q;
create or replace view public.v_unit_costs as
 SELECT 'Vape'::text AS stream,
    '0.5 g cartridge'::text AS sku,
    0.5 AS g,
    v_cost_of_goods.vape_05g_unit_cost AS unit_cost,
    round(v_cost_of_goods.vape_05g_unit_cost * 453.592 / 0.5) AS per_pound
   FROM v_cost_of_goods
UNION ALL
 SELECT 'Vape'::text AS stream,
    '1.0 g cartridge'::text AS sku,
    1.0 AS g,
    v_cost_of_goods.vape_10g_unit_cost AS unit_cost,
    round(v_cost_of_goods.vape_10g_unit_cost * 453.592 / 1.0) AS per_pound
   FROM v_cost_of_goods
UNION ALL
 SELECT 'Concentrate'::text AS stream,
    '1.0 g badder'::text AS sku,
    1.0 AS g,
    v_cost_of_goods.badder_1g_unit_cost AS unit_cost,
    round(v_cost_of_goods.badder_1g_unit_cost * 453.592 / 1.0) AS per_pound
   FROM v_cost_of_goods
UNION ALL
 SELECT 'Concentrate'::text AS stream,
    '3.5 g badder'::text AS sku,
    3.5 AS g,
    v_cost_of_goods.badder_35g_unit_cost AS unit_cost,
    round(v_cost_of_goods.badder_35g_unit_cost * 453.592 / 3.5) AS per_pound
   FROM v_cost_of_goods;
create or replace view public.v_unrequested_material as
 SELECT origin,
    supplier,
    stream,
    license,
    location,
    lab_state,
    packages,
    pounds,
    oldest_days,
    'No approved allocation covers this material. Under the owner rule nothing may move until Vincent approves it - and that applies to bought-in material as much as our own.'::text AS why_it_matters
   FROM v_stock_on_hand s
  WHERE NOT (EXISTS ( SELECT 1
           FROM allocation_requests r
          WHERE r.status = 'approved'::text AND (COALESCE(r.stream, ''::text) = s.stream OR COALESCE(r.material_name, ''::text) ~~* (('%'::text || s.stream) || '%'::text))))
  ORDER BY pounds DESC;
create or replace view public.v_watchdog_current as
 SELECT observed_at,
    observed_on,
    severity,
    what,
    where_it_is,
    who_is_accountable,
    when_it_started,
    why_it_matters,
    how_it_was_detected,
    what_to_do,
    the_arithmetic,
    record_count,
    pounds,
    dollars,
    drill,
    fingerprint,
    evidence,
    search_text,
    sweep_ran_at,
    sweep_ran_by,
    sweep_ms,
    finding_id,
    run_id
   FROM v_watchdog_log
  WHERE run_id = (( SELECT max(watchdog_runs.id) AS max
           FROM watchdog_runs))
  ORDER BY (
        CASE severity
            WHEN 'critical'::text THEN 1
            WHEN 'elevated'::text THEN 2
            ELSE 3
        END), (COALESCE(dollars, 0::numeric)) DESC;
create or replace view public.v_weekend_watch as
 SELECT 'Scheduled pull'::text AS event_type,
    p.pull_no,
    p.flower_room AS room,
    p.cultivars AS detail,
    p.harvest_date AS event_date,
    TRIM(BOTH FROM to_char(p.harvest_date::timestamp with time zone, 'Day'::text)) AS falls_on,
    p.harvest_date - CURRENT_DATE AS days_away,
        CASE
            WHEN p.harvest_date < CURRENT_DATE THEN 'PAST - check it was not slipped'::text
            WHEN (p.harvest_date - CURRENT_DATE)::numeric <= (( SELECT harvest_alert_rules.threshold
               FROM harvest_alert_rules
              WHERE harvest_alert_rules.rule_key = 'weekend_warning_days'::text)) THEN 'PLAN A WEEKEND CREW OR SECOND SHIFT NOW'::text
            ELSE 'Upcoming - plan coverage'::text
        END AS action
   FROM harvest_pulls p
  WHERE (EXTRACT(dow FROM p.harvest_date) = ANY (ARRAY[0::numeric, 6::numeric])) AND p.harvest_date >= (CURRENT_DATE - 14)
UNION ALL
 SELECT 'Dry deadline (day 14)'::text AS event_type,
    NULL::integer AS pull_no,
    m.room,
    m.strains AS detail,
    m.harvest_start + 14 AS event_date,
    TRIM(BOTH FROM to_char((m.harvest_start + 14)::timestamp with time zone, 'Day'::text)) AS falls_on,
    m.harvest_start + 14 - CURRENT_DATE AS days_away,
        CASE
            WHEN (m.harvest_start + 14) < CURRENT_DATE THEN 'PAST - confirm it was finished on time'::text
            WHEN (m.harvest_start + 14 - CURRENT_DATE)::numeric <= (( SELECT harvest_alert_rules.threshold
               FROM harvest_alert_rules
              WHERE harvest_alert_rules.rule_key = 'weekend_warning_days'::text)) THEN 'PLAN A WEEKEND CREW OR SECOND SHIFT NOW'::text
            ELSE 'Upcoming - plan coverage'::text
        END AS action
   FROM v_harvest_stage_map m
  WHERE (m.stage <> ALL (ARRAY['Finished'::text, 'Archived'::text])) AND (EXTRACT(dow FROM m.harvest_start + 14) = ANY (ARRAY[0::numeric, 6::numeric]))
  ORDER BY 5;
create or replace view public.v_weight_basis_collisions as
 SELECT relation,
    kind,
    count(DISTINCT basis) AS distinct_bases,
    string_agg(DISTINCT basis, ', '::text ORDER BY basis) AS bases_present,
    count(*) FILTER (WHERE undeclared) AS undeclared_columns,
    bool_or(relation_also_carries_money) AS carries_money
   FROM v_weight_basis_gaps
  GROUP BY relation, kind
 HAVING count(DISTINCT basis) > 1 OR count(*) FILTER (WHERE undeclared) > 0;
create or replace view public.v_year_end_2025_summary as
 SELECT license,
    category,
    count(*)::numeric AS line_items,
    sum(packages) AS packages,
    round(sum(quantity_estimate), 1) AS quantity_estimate,
    round(sum(COALESCE(value_at_cost, 0::numeric)), 2) AS value_at_cost
   FROM v_year_end_2025
  GROUP BY ROLLUP(license, category)
  ORDER BY license, (round(sum(COALESCE(value_at_cost, 0::numeric)), 2)) DESC NULLS LAST;
create or replace view public.v_yield_vs_target as
 SELECT month,
    month_date,
    harvests,
    plants,
    wet_lb,
    waste_lb,
    dried_flower_lb,
    trim_lb,
    fresh_frozen_lb,
    packaged_lb,
    target_lb,
    round(avg(dried_flower_lb) OVER w3, 1) AS rolling_3_month_avg,
    round(avg(dried_flower_lb) OVER w6, 1) AS rolling_6_month_avg,
    round(avg(dried_flower_lb) OVER w3 - target_lb, 1) AS rolling_3_vs_target,
        CASE
            WHEN avg(dried_flower_lb) OVER w3 >= target_lb THEN 'ON TARGET (3-month average)'::text
            ELSE 'BELOW TARGET (3-month average)'::text
        END AS rolling_status,
    flower_vs_target_lb AS this_month_vs_target,
        CASE
            WHEN dried_flower_lb >= target_lb THEN 'met'::text
            ELSE 'below'::text
        END AS this_month_status,
        CASE
            WHEN harvests < 8 THEN (('Only '::text || harvests) || ' harvest(s) closed this month - '::text) || 'the 14-day pull cadence means some months carry fewer. Judge on the rolling average.'::text
            ELSE NULL::text
        END AS caveat,
    how_this_is_counted
   FROM v_monthly_yield m
  WINDOW w3 AS (ORDER BY month_date ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), w6 AS (ORDER BY month_date ROWS BETWEEN 5 PRECEDING AND CURRENT ROW);
create or replace view public.v_zone_now as
 SELECT z.id AS zone_id,
    z.name AS zone,
    COALESCE(d.name, 'Unassigned'::text) AS department,
    count(f.employee_id) AS on_floor_now,
    req.headcount_required AS required,
    count(f.employee_id) - COALESCE(req.headcount_required, 0) AS variance,
    round(COALESCE(sum(f.cost_so_far_loaded), 0::numeric), 2) AS cost_so_far_loaded,
    round(COALESCE(avg(f.hours_so_far), 0::numeric), 2) AS avg_hours_so_far,
    count(*) FILTER (WHERE f.licence_lapsed) AS lapsed_licences,
    count(*) FILTER (WHERE COALESCE(f.late_minutes, 0) > 0) AS late_today,
        CASE
            WHEN req.headcount_required IS NULL THEN 'no requirement set'::text
            WHEN count(f.employee_id) < req.headcount_required THEN 'SHORT'::text
            WHEN count(f.employee_id) > req.headcount_required THEN 'over'::text
            ELSE 'on plan'::text
        END AS coverage_flag
   FROM zones z
     LEFT JOIN departments d ON d.id = z.department_id
     LEFT JOIN v_on_the_floor f ON f.zone = z.name
     LEFT JOIN LATERAL ( SELECT r.headcount_required
           FROM zone_staffing_requirements r
          WHERE (r.zone_id = z.id OR r.department_id = z.department_id) AND r.effective_from <= CURRENT_DATE AND (r.effective_to IS NULL OR r.effective_to >= CURRENT_DATE) AND (r.weekday IS NULL OR r.weekday = EXTRACT(dow FROM CURRENT_DATE)::integer)
          ORDER BY r.zone_id, r.effective_from DESC
         LIMIT 1) req ON true
  WHERE z.active
  GROUP BY z.id, z.name, d.name, req.headcount_required;
create materialized view if not exists public.mv_harvest_yields as
 SELECT harvest_name,
    strain,
    room,
    takedown_date,
    finished_on,
    current_stage,
    days_since_takedown,
    planned_pull,
    planned_plants,
    actual_plants,
    projected_lbs,
    actual_wet_lbs,
    actual_packaged_lbs,
    pct_of_projection,
    variance_lbs,
    waste_lbs,
    waste_pct,
    yield_pct,
    allocation_requests,
    requested_by,
    approved_by,
    allocated_quantity,
    allocated_to,
    allocated_for,
    packages_made,
    manufactured_into,
    still_on_hand,
    sitting_in,
    passed_testing,
    shipped_out,
    lab_state,
    license
   FROM v_metrc_harvest_yields;
create or replace view public.v_awaiting_allocation as
 SELECT material_class,
    origin,
    item,
    strain,
    identifier,
    quantity,
    uom,
    location,
    stage,
    days_in_system,
    vendor,
    cost,
    COALESCE(allocation_status, 'no request'::text) AS allocation_status,
    approved_by,
        CASE
            WHEN allocation_status = 'approved'::text THEN 'Approved by '::text || COALESCE(approved_by, 'an approver'::text)
            WHEN allocation_status = 'pending'::text THEN 'AWAITING APPROVAL'::text
            WHEN allocation_status = 'denied'::text THEN 'DENIED - decide what happens to it'::text
            ELSE 'NO ALLOCATION REQUESTED - this material has no approved destination'::text
        END AS approval_state
   FROM v_production_tracker
  WHERE COALESCE(allocation_status, ''::text) <> 'approved'::text
  ORDER BY days_in_system DESC NULLS LAST;
create or replace view public.v_custody_alerts as
 SELECT 'Lineage break'::text AS flag,
    'critical'::text AS severity,
    p.license,
    p.tag AS identifier,
    COALESCE(p.item_name, '(unnamed)'::text) AS item,
    COALESCE(p.location, '(no location)'::text) AS location,
    COALESCE(p.quantity, 0::numeric) AS quantity,
    COALESCE(p.uom, 'ea'::text) AS uom,
    'Package has no source harvest recorded - the seed to sale chain cannot be proven for this package'::text AS detail,
    p.packaged_on AS reference_date
   FROM metrc_packages p
  WHERE (p.source_state = ANY (ARRAY['active'::text, 'onhold'::text, 'intransit'::text])) AND COALESCE(NULLIF(p.raw ->> 'SourceHarvestNames'::text, ''::text), NULLIF(p.raw ->> 'SourcePackageLabels'::text, ''::text)) IS NULL
UNION ALL
 SELECT 'On hold in Metrc'::text AS flag,
    'critical'::text AS severity,
    p.license,
    p.tag AS identifier,
    COALESCE(p.item_name, '(unnamed)'::text) AS item,
    COALESCE(p.location, '(no location)'::text) AS location,
    COALESCE(p.quantity, 0::numeric) AS quantity,
    COALESCE(p.uom, 'ea'::text) AS uom,
    'Package is on hold in Metrc - resolve the hold or record the disposition'::text AS detail,
    p.packaged_on AS reference_date
   FROM metrc_packages p
  WHERE ((p.raw ->> 'IsOnHold'::text)::boolean) AND (p.source_state = ANY (ARRAY['active'::text, 'onhold'::text]))
UNION ALL
 SELECT 'Failed testing unresolved'::text AS flag,
    'critical'::text AS severity,
    p.license,
    p.tag AS identifier,
    COALESCE(p.item_name, '(unnamed)'::text) AS item,
    COALESCE(p.location, '(no location)'::text) AS location,
    COALESCE(p.quantity, 0::numeric) AS quantity,
    COALESCE(p.uom, 'ea'::text) AS uom,
    'Failed a laboratory test and is still in inventory - remediate or destroy and record it'::text AS detail,
    p.packaged_on AS reference_date
   FROM metrc_packages p
  WHERE p.lab_testing_state = 'TestFailed'::text AND (p.source_state = ANY (ARRAY['active'::text, 'onhold'::text]))
UNION ALL
 SELECT 'Unexplained quantity loss'::text AS flag,
    'elevated'::text AS severity,
    p.license,
    p.tag AS identifier,
    COALESCE(p.item_name, '(unnamed)'::text) AS item,
    COALESCE(p.location, '(no location)'::text) AS location,
    round(COALESCE((p.raw ->> 'InitialQuantity'::text)::numeric, 0::numeric) - COALESCE(p.quantity, 0::numeric), 2) AS quantity,
    COALESCE(p.uom, 'ea'::text) AS uom,
    ((('Quantity dropped from '::text || (p.raw ->> 'InitialQuantity'::text)) || ' to '::text) || COALESCE(p.quantity, 0::numeric)) || ' with no adjustment reason recorded'::text AS detail,
    p.packaged_on AS reference_date
   FROM metrc_packages p
  WHERE (COALESCE((p.raw ->> 'InitialQuantity'::text)::numeric, 0::numeric) - COALESCE(p.quantity, 0::numeric)) > 0.01 AND (p.source_state = ANY (ARRAY['active'::text, 'onhold'::text]))
UNION ALL
 SELECT 'Transfer not received'::text AS flag,
    'elevated'::text AS severity,
    p.license,
    p.tag AS identifier,
    COALESCE(p.item_name, '(unnamed)'::text) AS item,
    COALESCE(p.location, '(manifested)'::text) AS location,
    COALESCE(p.quantity, 0::numeric) AS quantity,
    COALESCE(p.uom, 'ea'::text) AS uom,
    ('In transit for '::text || (CURRENT_DATE - p.packaged_on)) || ' days - confirm the receiving facility accepted it'::text AS detail,
    p.packaged_on AS reference_date
   FROM metrc_packages p
  WHERE p.source_state = 'intransit'::text AND p.packaged_on < (CURRENT_DATE - 3)
UNION ALL
 SELECT 'Under investigation'::text AS flag,
    'critical'::text AS severity,
    h.license,
    h.name AS identifier,
    COALESCE(h.raw ->> 'SourceStrainNames'::text, h.name) AS item,
    COALESCE(h.raw ->> 'DryingLocationName'::text, '(no room)'::text) AS location,
    COALESCE((h.raw ->> 'CurrentWeight'::text)::numeric, 0::numeric) AS quantity,
    COALESCE(h.raw ->> 'UnitOfWeightName'::text, 'g'::text) AS uom,
    'Harvest is flagged under investigation or recall in Metrc - do not move or sell until cleared'::text AS detail,
    h.harvest_start AS reference_date
   FROM metrc_harvests h
  WHERE ((h.raw ->> 'IsOnInvestigation'::text)::boolean) OR ((h.raw ->> 'IsOnInvestigationHold'::text)::boolean) OR ((h.raw ->> 'IsOnInvestigationRecall'::text)::boolean)
UNION ALL
 SELECT 'No location recorded'::text AS flag,
    'critical'::text AS severity,
    l.license,
    l.identifier,
    l.item,
    l.location,
    l.quantity,
    l.uom,
    'This item has no recorded location - custody cannot be proven to the Cannabis Control Commission'::text AS detail,
    l.since_date AS reference_date
   FROM v_inventory_locator l
  WHERE l.location IS NULL OR (l.location = ANY (ARRAY['(no location)'::text, '(no room recorded)'::text]))
UNION ALL
 SELECT 'Metrc data stale'::text AS flag,
    'elevated'::text AS severity,
    'BOTH'::text AS license,
    'sync'::text AS identifier,
    'Metrc mirror'::text AS item,
    'System'::text AS location,
    round(EXTRACT(epoch FROM now() - max(r.started_at)) / 3600::numeric, 1) AS quantity,
    'hours since last sync'::text AS uom,
    'No successful Metrc sync in over 2 hours - the custody picture may be out of date'::text AS detail,
    CURRENT_DATE AS reference_date
   FROM metrc_sync_runs r
 HAVING max(r.started_at) < (now() - '02:00:00'::interval);
create or replace view public.v_custody_compliance as
 SELECT v_inventory_locator.category,
    count(*)::numeric AS items,
    count(*) FILTER (WHERE v_inventory_locator.location IS NULL OR (v_inventory_locator.location = ANY (ARRAY['(no location)'::text, '(no room recorded)'::text, '(manifested)'::text])))::numeric AS items_without_location,
    count(*) FILTER (WHERE v_inventory_locator.identifier IS NULL OR v_inventory_locator.identifier = ''::text)::numeric AS items_without_identifier,
    count(*) FILTER (WHERE v_inventory_locator.since_date IS NULL)::numeric AS items_without_date,
    round(100.0 * count(*) FILTER (WHERE v_inventory_locator.location IS NOT NULL AND (v_inventory_locator.location <> ALL (ARRAY['(no location)'::text, '(no room recorded)'::text])))::numeric / NULLIF(count(*), 0)::numeric, 1) AS location_known_pct,
    round(sum(v_inventory_locator.quantity) FILTER (WHERE v_inventory_locator.location IS NULL OR (v_inventory_locator.location = ANY (ARRAY['(no location)'::text, '(no room recorded)'::text]))), 1) AS quantity_unlocated,
        CASE
            WHEN count(*) FILTER (WHERE v_inventory_locator.location IS NULL OR (v_inventory_locator.location = ANY (ARRAY['(no location)'::text, '(no room recorded)'::text]))) = 0 THEN 'Every item accounted for'::text
            ELSE count(*) FILTER (WHERE v_inventory_locator.location IS NULL OR (v_inventory_locator.location = ANY (ARRAY['(no location)'::text, '(no room recorded)'::text]))) || ' item(s) have no recorded location - resolve in Metrc'::text
        END AS compliance_status
   FROM v_inventory_locator
  GROUP BY v_inventory_locator.category
UNION ALL
 SELECT 'ALL TRACKED INVENTORY'::text AS category,
    count(*)::numeric AS items,
    count(*) FILTER (WHERE v_inventory_locator.location IS NULL OR (v_inventory_locator.location = ANY (ARRAY['(no location)'::text, '(no room recorded)'::text, '(manifested)'::text])))::numeric AS items_without_location,
    count(*) FILTER (WHERE v_inventory_locator.identifier IS NULL OR v_inventory_locator.identifier = ''::text)::numeric AS items_without_identifier,
    count(*) FILTER (WHERE v_inventory_locator.since_date IS NULL)::numeric AS items_without_date,
    round(100.0 * count(*) FILTER (WHERE v_inventory_locator.location IS NOT NULL AND (v_inventory_locator.location <> ALL (ARRAY['(no location)'::text, '(no room recorded)'::text])))::numeric / NULLIF(count(*), 0)::numeric, 1) AS location_known_pct,
    round(sum(v_inventory_locator.quantity) FILTER (WHERE v_inventory_locator.location IS NULL OR (v_inventory_locator.location = ANY (ARRAY['(no location)'::text, '(no room recorded)'::text]))), 1) AS quantity_unlocated,
        CASE
            WHEN count(*) FILTER (WHERE v_inventory_locator.location IS NULL OR (v_inventory_locator.location = ANY (ARRAY['(no location)'::text, '(no room recorded)'::text]))) = 0 THEN 'FULL CUSTODY - every tracked item has a known location'::text
            ELSE ('CUSTODY GAP - '::text || count(*) FILTER (WHERE v_inventory_locator.location IS NULL OR (v_inventory_locator.location = ANY (ARRAY['(no location)'::text, '(no room recorded)'::text])))) || ' item(s) unlocated'::text
        END AS compliance_status
   FROM v_inventory_locator;
create or replace view public.v_customer_directory as
 WITH sales AS (
         SELECT COALESCE((m.raw -> '_delivery'::text) ->> 'RecipientFacilityLicenseNumber'::text, m.raw ->> 'RecipientFacilityLicenseNumber'::text) AS facility_licence,
            m.recipient AS name_on_manifest,
            m.is_customer_sale,
            m.is_inbound_purchase,
            m.movement,
            m.operation,
            m.created_on,
            m.manifest_number,
            m.documents,
            m.raw
           FROM v_manifest_ledger m
          WHERE COALESCE(m.recipient, ''::text) !~~* '%twisted%'::text
        ), agg AS (
         SELECT s.facility_licence,
            count(*) FILTER (WHERE s.is_customer_sale) AS customer_sales,
            count(*) FILTER (WHERE s.movement = 'Laboratory sample'::text) AS lab_samples,
            count(*) FILTER (WHERE s.is_customer_sale AND s.operation = 'Cultivation'::text) AS from_cultivation,
            count(*) FILTER (WHERE s.is_customer_sale AND s.operation = 'Manufacturing'::text) AS from_manufacturing,
            min(s.created_on) FILTER (WHERE s.is_customer_sale) AS first_sale,
            max(s.created_on) FILTER (WHERE s.is_customer_sale) AS last_sale,
            sum(((s.raw -> '_delivery'::text) ->> 'DeliveryPackageCount'::text)::integer) FILTER (WHERE s.is_customer_sale) AS packages_shipped,
            max(s.manifest_number) FILTER (WHERE s.is_customer_sale) AS last_manifest,
            count(*) FILTER (WHERE s.is_customer_sale AND s.documents > 0) AS manifests_with_document,
            max(s.name_on_manifest) AS fallback_name
           FROM sales s
          WHERE s.facility_licence IS NOT NULL
          GROUP BY s.facility_licence
        )
 SELECT r.facility_licence,
    COALESCE(r.facility_name, a.fallback_name) AS facility,
    r.facility_type,
    r.company_key,
    initcap(r.company_key) AS company,
    count(*) OVER (PARTITION BY r.company_key) AS sibling_facilities,
    sum(a.customer_sales) OVER (PARTITION BY r.company_key) AS company_total_sales,
    a.customer_sales,
    a.lab_samples,
    a.from_cultivation,
    a.from_manufacturing,
    a.first_sale,
    a.last_sale,
    a.packages_shipped,
    a.last_manifest,
    a.manifests_with_document,
    fc.ship_to_line1,
    fc.ship_to_line2,
    fc.ship_to_town,
    fc.ship_to_postcode,
    fc.contact_name,
    fc.email,
    fc.cc_emails,
    fc.phone,
    fc.delivery_notes,
    fc.receiving_hours,
    fc.terms_days,
    fc.credit_limit,
    fc.do_not_ship,
    fc.updated_at AS contact_updated_at,
        CASE
            WHEN r.facility_type = 'Independent Testing Laboratory'::text THEN 'Testing laboratory - not a customer'::text
            WHEN fc.email IS NOT NULL AND fc.ship_to_line1 IS NOT NULL THEN 'Ready to send'::text
            WHEN fc.email IS NOT NULL THEN 'Email held, ship-to address still needed'::text
            WHEN fc.facility_licence IS NOT NULL THEN 'Started - email still needed'::text
            ELSE 'Nothing on file - staff add it when building the first order'::text
        END AS record_status,
        CASE
            WHEN a.customer_sales = 0 THEN 'No customer sales'::text
            WHEN a.last_sale > (now() - '60 days'::interval) THEN 'Active'::text
            WHEN a.last_sale > (now() - '180 days'::interval) THEN 'Quiet - nothing in 60 days'::text
            ELSE 'Dormant - nothing in 6 months'::text
        END AS trading_status,
    (((r.search_text || ' '::text) || COALESCE(fc.email, ''::text)) || ' '::text) || COALESCE(fc.ship_to_town, ''::text) AS search_text
   FROM v_facility_registry r
     JOIN agg a ON a.facility_licence = r.facility_licence
     LEFT JOIN facility_contacts fc ON fc.facility_licence = r.facility_licence;
create or replace view public.v_findings_rolled as
 SELECT group_key,
    department,
    min(severity_rank) AS severity_rank,
    (array_agg(severity ORDER BY v_findings_live.severity_rank))[1] AS severity,
    count(*) AS occurrences,
    max(owner_name) AS owner_name,
    round(sum(dollars), 0) AS dollars,
    round(sum(pounds), 1) AS pounds,
    min(first_raised)::date AS first_seen,
    max(last_seen)::date AS last_seen,
    (array_agg(what ORDER BY v_findings_live.severity_rank, first_raised))[1] AS example,
    (array_agg(what_to_do ORDER BY v_findings_live.severity_rank) FILTER (WHERE what_to_do IS NOT NULL))[1] AS what_to_do,
    count(*) FILTER (WHERE work_state <> 'open'::text) AS being_worked,
        CASE
            WHEN count(*) = 1 THEN 'single finding'::text
            ELSE count(*) || ' occurrences — drill in to see each one'::text
        END AS scale
   FROM v_findings_live
  WHERE state = 'open'::text AND NOT is_duplicate AND NOT currently_suppressed
  GROUP BY group_key, department;
create or replace view public.v_harvest_forensic as
 SELECT harvest_name,
    license,
    strain,
    drying_room,
    harvest_type,
    harvest_started,
    first_package_taken_off,
    last_package_taken_off,
    harvest_closed,
    dry_days_to_first_package,
    packaging_window_days,
    total_days_start_to_now,
    plants,
    wet_lb,
    packaged_lb,
    waste_lb,
    still_in_room_lb,
    bud_lb,
    shake_trim_lb,
    categories_made,
    packages_made,
    passed_packages,
    failed_packages,
    untested_packages,
    lab_state,
    on_hold,
    wet_g_per_plant,
    packaged_g_per_plant,
    conversion_pct,
    waste_pct_of_wet,
    wet_to_dry_ratio,
    harvest_state,
    drying_verdict,
    what_is_wrong,
    severity,
    harvest_started AS harvest_started_date
   FROM ( WITH h AS (
                 SELECT metrc_harvests.name AS harvest_name,
                    metrc_harvests.license,
                    COALESCE(NULLIF(metrc_harvests.raw ->> 'SourceStrainNames'::text, ''::text), '(not recorded)'::text) AS strain,
                    COALESCE(NULLIF(metrc_harvests.raw ->> 'DryingLocationName'::text, ''::text), '(not recorded)'::text) AS drying_room,
                    metrc_harvests.raw ->> 'HarvestType'::text AS harvest_type,
                    metrc_harvests.harvest_start,
                    (metrc_harvests.raw ->> 'FinishedDate'::text)::date AS finished_date,
                    (metrc_harvests.raw ->> 'PlantCount'::text)::integer AS plants,
                    metrc_harvests.wet_weight AS wet_g,
                    metrc_harvests.waste_weight AS waste_g,
                    (metrc_harvests.raw ->> 'TotalPackagedWeight'::text)::numeric AS packaged_g,
                    (metrc_harvests.raw ->> 'CurrentWeight'::text)::numeric AS current_g,
                    metrc_harvests.package_count,
                    metrc_harvests.raw ->> 'LabTestingState'::text AS lab_state,
                    (metrc_harvests.raw ->> 'IsOnHold'::text)::boolean AS on_hold
                   FROM metrc_harvests
                )
         SELECT h.harvest_name,
            h.license,
            h.strain,
            h.drying_room,
            h.harvest_type,
            h.harvest_start AS harvest_started,
            pk.first_package_on AS first_package_taken_off,
            pk.last_package_on AS last_package_taken_off,
            h.finished_date AS harvest_closed,
            pk.first_package_on - h.harvest_start AS dry_days_to_first_package,
            pk.last_package_on - pk.first_package_on AS packaging_window_days,
            COALESCE(h.finished_date, CURRENT_DATE) - h.harvest_start AS total_days_start_to_now,
            h.plants,
            round(h.wet_g / 453.592, 2) AS wet_lb,
            round(h.packaged_g / 453.592, 2) AS packaged_lb,
            round(h.waste_g / 453.592, 2) AS waste_lb,
            round(h.current_g / 453.592, 2) AS still_in_room_lb,
            pk.bud_lb,
            pk.shake_trim_lb,
            pk.categories_made,
            COALESCE(pk.packages_made, 0::bigint) AS packages_made,
            COALESCE(pk.passed_packages, 0::bigint) AS passed_packages,
            COALESCE(pk.failed_packages, 0::bigint) AS failed_packages,
            COALESCE(pk.untested_packages, 0::bigint) AS untested_packages,
            h.lab_state,
            h.on_hold,
            round(h.wet_g / NULLIF(h.plants, 0)::numeric, 1) AS wet_g_per_plant,
            round(h.packaged_g / NULLIF(h.plants, 0)::numeric, 1) AS packaged_g_per_plant,
            round(h.packaged_g / NULLIF(h.wet_g, 0::numeric) * 100::numeric, 1) AS conversion_pct,
            round(h.waste_g / NULLIF(h.wet_g, 0::numeric) * 100::numeric, 1) AS waste_pct_of_wet,
            round(h.wet_g / NULLIF(h.packaged_g, 0::numeric), 2) AS wet_to_dry_ratio,
                CASE
                    WHEN h.finished_date IS NULL THEN 'STILL OPEN - not finished'::text
                    ELSE 'Finished'::text
                END AS harvest_state,
                CASE
                    WHEN pk.first_package_on IS NULL THEN 'NOTHING PACKAGED YET - no dry time can be measured'::text
                    WHEN (pk.first_package_on - h.harvest_start) < 7 THEN ('DRIED TOO FAST: '::text || (pk.first_package_on - h.harvest_start)) || ' days. Under 7 days locks in moisture and chlorophyll - harsh smoke and mould risk.'::text
                    WHEN (pk.first_package_on - h.harvest_start) >= 7 AND (pk.first_package_on - h.harvest_start) <= 16 THEN ('DRY TIME NORMAL: '::text || (pk.first_package_on - h.harvest_start)) || ' days, inside the 10 to 14 day target.'::text
                    WHEN (pk.first_package_on - h.harvest_start) >= 17 AND (pk.first_package_on - h.harvest_start) <= 30 THEN ('DRIED TOO LONG: '::text || (pk.first_package_on - h.harvest_start)) || ' days. Every extra day past 14 burns off saleable weight permanently.'::text
                    ELSE ('DRY TIME FAR OVER: '::text || (pk.first_package_on - h.harvest_start)) || ' days from cut to first package. This is not drying, this is product sitting.'::text
                END AS drying_verdict,
                CASE
                    WHEN h.finished_date IS NULL AND (CURRENT_DATE - h.harvest_start) > 21 THEN ((((('OPEN TOO LONG: cut '::text || (CURRENT_DATE - h.harvest_start)) || ' days ago, still not closed. '::text) || round(h.current_g / 453.592, 2)) || ' lb is sitting in '::text) || h.drying_room) || ' unsold, and its unfinished conversion drags the monthly average down.'::text
                    WHEN h.finished_date IS NULL THEN 'IN PROCESS: normal. Exclude from conversion averages until it closes.'::text
                    WHEN h.plants IS NULL OR h.plants = 0 THEN 'NO PLANT COUNT RECORDED: yield per plant cannot be computed.'::text
                    WHEN h.wet_g = 0::numeric THEN 'NO WET WEIGHT RECORDED: conversion cannot be computed.'::text
                    WHEN h.packaged_g = 0::numeric THEN ('CLOSED WITH ZERO PACKAGED: '::text || round(h.wet_g / 453.592, 2)) || ' lb went in and no package came out. Either weight went unrecorded or the close was premature.'::text
                    WHEN (h.packaged_g / NULLIF(h.wet_g, 0::numeric)) > 0.35 THEN ('CONVERSION IMPLAUSIBLY HIGH at '::text || round(h.packaged_g / NULLIF(h.wet_g, 0::numeric) * 100::numeric, 1)) || ' percent. Fresh flower is 75 to 80 percent water, so this means the WET weight was recorded too LOW - not that the harvest did well. Check the takedown scale.'::text
                    WHEN (h.packaged_g / NULLIF(h.wet_g, 0::numeric)) < 0.15 THEN ('CONVERSION LOW at '::text || round(h.packaged_g / NULLIF(h.wet_g, 0::numeric) * 100::numeric, 1)) || ' percent against a 20 to 25 percent norm. Either real loss in dry and trim, or the wet weight was recorded too HIGH.'::text
                    ELSE ('NORMAL: '::text || round(h.packaged_g / NULLIF(h.wet_g, 0::numeric) * 100::numeric, 1)) || ' percent sits inside the 20 to 25 percent wet-to-packaged norm for indoor flower.'::text
                END AS what_is_wrong,
                CASE
                    WHEN h.finished_date IS NULL AND (CURRENT_DATE - h.harvest_start) > 21 THEN 'CRITICAL'::text
                    WHEN h.finished_date IS NOT NULL AND h.packaged_g = 0::numeric THEN 'CRITICAL'::text
                    WHEN h.finished_date IS NULL THEN 'INFO'::text
                    WHEN h.plants IS NULL OR h.plants = 0 OR h.wet_g = 0::numeric THEN 'HIGH'::text
                    WHEN (pk.first_package_on - h.harvest_start) > 16 OR (pk.first_package_on - h.harvest_start) < 7 THEN 'HIGH'::text
                    WHEN (h.packaged_g / NULLIF(h.wet_g, 0::numeric)) > 0.35 OR (h.packaged_g / NULLIF(h.wet_g, 0::numeric)) < 0.15 THEN 'MEDIUM'::text
                    ELSE 'OK'::text
                END AS severity
           FROM h
             LEFT JOIN mv_harvest_pkg_rollup pk ON pk.harvest_name = h.harvest_name) q;
create or replace view public.v_inventory_aging as
 SELECT category,
    stage,
    location,
    license,
    item,
    identifier,
    quantity,
    uom,
    days_here,
        CASE
            WHEN category = 'Harvest lots'::text AND stage ~~ 'Drying%'::text AND days_here > 14::numeric THEN 'critical'::text
            WHEN category = 'Harvest lots'::text AND days_here > 30::numeric THEN 'elevated'::text
            WHEN category = 'Packages'::text AND stage = 'Awaiting laboratory'::text AND days_here > 7::numeric THEN 'elevated'::text
            WHEN category = 'Packages'::text AND stage = 'FAILED TESTING'::text THEN 'critical'::text
            WHEN category = 'Packages'::text AND days_here > 90::numeric THEN 'elevated'::text
            WHEN category = 'Packages'::text AND days_here > 60::numeric THEN 'watch'::text
            WHEN stage = 'ON HOLD'::text THEN 'critical'::text
            ELSE NULL::text
        END AS severity,
        CASE
            WHEN category = 'Harvest lots'::text AND stage ~~ 'Drying%'::text AND days_here > 14::numeric THEN 'Past the 14-day dry limit - move it or record the weights'::text
            WHEN category = 'Harvest lots'::text AND days_here > 30::numeric THEN 'Harvest lot open more than 30 days - the room turn is at risk'::text
            WHEN category = 'Packages'::text AND stage = 'Awaiting laboratory'::text AND days_here > 7::numeric THEN 'Waiting on a laboratory result more than 7 days - chase the laboratory'::text
            WHEN category = 'Packages'::text AND stage = 'FAILED TESTING'::text THEN 'Failed testing - decide remediation or destruction'::text
            WHEN category = 'Packages'::text AND days_here > 90::numeric THEN 'Packaged more than 90 days ago - cash is sitting on the shelf'::text
            WHEN category = 'Packages'::text AND days_here > 60::numeric THEN 'Packaged more than 60 days ago - prioritize it for sale'::text
            WHEN stage = 'ON HOLD'::text THEN 'On hold in Metrc - resolve the hold'::text
            ELSE NULL::text
        END AS action
   FROM v_inventory_locator
  WHERE days_here IS NOT NULL;
create or replace view public.v_inventory_report as
 WITH p AS (
         SELECT DISTINCT ON (metrc_packages.tag) metrc_packages.tag,
            metrc_packages.item_name,
            metrc_packages.license,
            metrc_packages.uom,
            metrc_packages.quantity,
            metrc_packages.source_state,
            metrc_packages.lab_testing_state,
            metrc_packages.packaged_on,
            metrc_packages.raw
           FROM metrc_packages
          ORDER BY metrc_packages.tag, metrc_packages.license
        ), ff AS (
         SELECT f_rule('fresh_frozen_wet_to_dry'::text) AS ratio
        )
 SELECT p.tag AS package_tag,
    p.item_name,
    p.raw #>> '{Item,StrainName}'::text[] AS strain,
    p.raw #>> '{Item,ProductCategoryName}'::text[] AS category,
        CASE
            WHEN (p.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%fresh frozen%'::text THEN 'Fresh frozen'::text
            WHEN (p.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%bud%'::text THEN 'Dried flower'::text
            WHEN (p.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%shake%'::text OR (p.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%trim%'::text THEN 'Shake and trim'::text
            WHEN (p.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%concentrate%'::text THEN 'Concentrate'::text
            WHEN (p.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%pre-roll%'::text OR (p.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%preroll%'::text THEN 'Pre-rolls'::text
            WHEN (p.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%edible%'::text THEN 'Edibles'::text
            WHEN (p.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%vape%'::text THEN 'Vapes'::text
            WHEN (p.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%seed%'::text THEN 'Seeds'::text
            ELSE COALESCE(p.raw #>> '{Item,ProductCategoryName}'::text[], 'Other'::text)
        END AS stream,
    p.raw ->> 'LocationName'::text AS room,
    NULLIF(p.raw ->> 'SublocationName'::text, ''::text) AS sublocation,
    p.license AS licence,
    p.source_state AS status,
    p.lab_testing_state AS lab_state,
    (p.raw ->> 'IsOnHold'::text)::boolean AS on_hold,
    (p.raw ->> 'IsFinished'::text)::boolean AS finished,
    f_is_weight(p.uom) AS is_weighed,
    p.uom AS unit_of_measure,
        CASE
            WHEN f_is_weight(p.uom) THEN round(f_to_pounds(p.quantity, p.uom), 3)
            ELSE NULL::numeric
        END AS pounds,
        CASE
            WHEN NOT f_is_weight(p.uom) THEN p.quantity
            ELSE NULL::numeric
        END AS units,
    f_quantity_text(p.quantity, p.uom) AS quantity_shown,
        CASE
            WHEN f_is_weight(p.uom) AND (p.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%fresh frozen%'::text THEN 'wet'::text
            WHEN f_is_weight(p.uom) THEN 'dry'::text
            ELSE NULL::text
        END AS weight_basis,
        CASE
            WHEN f_is_weight(p.uom) AND (p.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%fresh frozen%'::text THEN round(f_to_pounds(p.quantity, p.uom), 3)
            ELSE NULL::numeric
        END AS pounds_wet,
        CASE
            WHEN f_is_weight(p.uom) AND (p.raw #>> '{Item,ProductCategoryName}'::text[]) !~~* '%fresh frozen%'::text THEN round(f_to_pounds(p.quantity, p.uom), 3)
            ELSE NULL::numeric
        END AS pounds_dry,
        CASE
            WHEN f_is_weight(p.uom) THEN round(
            CASE
                WHEN (p.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%fresh frozen%'::text THEN f_to_pounds(p.quantity, p.uom) / (( SELECT ff.ratio
                   FROM ff))
                ELSE f_to_pounds(p.quantity, p.uom)
            END, 3)
            ELSE NULL::numeric
        END AS pounds_dry_equivalent,
    p.packaged_on,
    CURRENT_DATE - p.packaged_on AS days_held,
        CASE
            WHEN (CURRENT_DATE - p.packaged_on) > 365 THEN 'over a year'::text
            WHEN (CURRENT_DATE - p.packaged_on) > 180 THEN '180-365 days'::text
            WHEN (CURRENT_DATE - p.packaged_on) > 90 THEN '90-180 days'::text
            WHEN (CURRENT_DATE - p.packaged_on) > 30 THEN '30-90 days'::text
            ELSE 'under 30 days'::text
        END AS age_band,
    (CURRENT_DATE - p.packaged_on) > 180 AS past_age_limit,
    p.raw ->> 'ItemFromFacilityLicenseNumber'::text AS item_defined_by,
    p.raw ->> 'ItemFromFacilityName'::text AS item_defined_by_name,
    oc.custody_says AS custody_origin_licences,
    COALESCE(oc.custody_verdict, 'not assessed - only active packages are judged'::text) AS ownership,
    cr.cert_client AS certificate_client,
    cr.cert_license AS certificate_licence,
    NULLIF(p.raw ->> 'SourceHarvestNames'::text, ''::text) AS from_harvest,
    (p.raw ->> 'SourcePackageCount'::text)::integer AS made_from_n_packages,
    ((p.raw ->> 'SourcePackageCount'::text)::integer) = 0 AS is_primary_production,
    NULLIF(p.raw ->> 'ReceivedFromManifestNumber'::text, ''::text) AS arrived_on_manifest,
    NULLIF(p.raw ->> 'ReceivedFromFacilityName'::text, ''::text) AS received_from,
    cr.package_tag IS NOT NULL AS has_certificate,
    cr.certificate_link AS certificate_basis,
    ( SELECT count(DISTINCT l.manifest_number) AS count
           FROM v_document_package_link l
          WHERE l.package_tag = p.tag AND l.doc_type = 'manifest'::text) AS manifests_held,
        CASE
            WHEN cr.package_tag IS NOT NULL AND (EXISTS ( SELECT 1
               FROM v_document_package_link l
              WHERE l.package_tag = p.tag AND l.doc_type = 'manifest'::text)) THEN 'COMPLETE - certificate and manifest'::text
            WHEN cr.package_tag IS NOT NULL THEN 'certificate only'::text
            WHEN (EXISTS ( SELECT 1
               FROM v_document_package_link l
              WHERE l.package_tag = p.tag AND l.doc_type = 'manifest'::text)) THEN 'manifest only'::text
            ELSE 'NEITHER'::text
        END AS document_status,
        CASE
            WHEN f_is_weight(p.uom) AND f_is_ours(p.raw ->> 'ItemFromFacilityLicenseNumber'::text) THEN round(
            CASE
                WHEN (p.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%fresh frozen%'::text THEN f_to_pounds(p.quantity, p.uom) / (( SELECT ff.ratio
                   FROM ff))
                ELSE f_to_pounds(p.quantity, p.uom)
            END * (( SELECT cm.cost_per_pound
               FROM cost_model cm
              WHERE cm.scope = 'cultivation'::text
              ORDER BY cm.effective_from DESC
             LIMIT 1)), 0)
            ELSE NULL::numeric
        END AS value_at_our_cost,
        CASE
            WHEN NOT f_is_weight(p.uom) THEN 'countable - no weight, no cost per pound'::text
            WHEN NOT f_is_ours(p.raw ->> 'ItemFromFacilityLicenseNumber'::text) THEN 'bought in - material_purchases is EMPTY, what was paid exists nowhere'::text
            ELSE 'our cultivation cost per pound, dry-equivalent basis'::text
        END AS cost_basis
   FROM p
     LEFT JOIN v_ownership_by_custody oc ON oc.package_tag = p.tag
     LEFT JOIN v_certificate_resolved cr ON cr.package_tag = p.tag;
create or replace view public.v_issue_attribution_summary as
 SELECT issue,
    round(COALESCE(sum(pounds) FILTER (WHERE origin = 'Grown by us'::text), 0::numeric), 1) AS ours_lb,
    round(COALESCE(sum(dollars) FILTER (WHERE origin = 'Grown by us'::text), 0::numeric)) AS ours_dollars,
    round(COALESCE(sum(pounds) FILTER (WHERE origin <> 'Grown by us'::text), 0::numeric), 1) AS bought_in_lb,
    round(COALESCE(sum(dollars) FILTER (WHERE origin <> 'Grown by us'::text), 0::numeric)) AS recoverable_dollars,
    string_agg(DISTINCT supplier, ', '::text) FILTER (WHERE origin <> 'Grown by us'::text) AS suppliers_involved,
    'Money against bought-in material is potentially recoverable from the supplier. Money against our own material is a genuine loss.'::text AS note
   FROM v_issue_attribution
  GROUP BY issue
  ORDER BY (round(COALESCE(sum(pounds) FILTER (WHERE origin = 'Grown by us'::text), 0::numeric), 1)) DESC;
create or replace view public.v_item_documents as
 SELECT p.tag AS package_tag,
    "left"(p.item_name, 55) AS item_name,
    p.source_state,
    p.lab_testing_state,
        CASE
            WHEN f_is_weight(p.uom) THEN round(f_to_pounds(p.quantity, p.uom), 2)
            ELSE NULL::numeric
        END AS pounds,
    count(*) FILTER (WHERE l.doc_type = 'coa'::text) AS coa_count,
    count(DISTINCT l.manifest_number) AS manifest_count,
    min(l.link_depth) FILTER (WHERE l.doc_type = 'coa'::text) AS coa_depth,
    bool_or(l.doc_type = 'coa'::text AND l.link_depth = 0) AS coa_is_direct,
    string_agg(DISTINCT l.manifest_number, ', '::text) FILTER (WHERE l.doc_type = 'manifest'::text) AS manifests,
    p.lab_testing_state = ANY (ARRAY['TestPassed'::text, 'TestFailed'::text]) AS was_tested,
    (EXISTS ( SELECT 1
           FROM metrc_rpt_package_transfers t
          WHERE t.package_tag = p.tag)) AS was_shipped,
        CASE
            WHEN count(*) FILTER (WHERE l.doc_type = 'coa'::text) > 0 AND count(*) FILTER (WHERE l.doc_type = 'manifest'::text) > 0 THEN 'COMPLETE - COA and manifest'::text
            WHEN count(*) FILTER (WHERE l.doc_type = 'coa'::text) > 0 THEN 'COA only'::text
            WHEN count(*) FILTER (WHERE l.doc_type = 'manifest'::text) > 0 THEN 'MANIFEST only'::text
            ELSE 'NEITHER'::text
        END AS document_status
   FROM ( SELECT DISTINCT ON (metrc_packages.tag) metrc_packages.tag,
            metrc_packages.item_name,
            metrc_packages.uom,
            metrc_packages.quantity,
            metrc_packages.source_state,
            metrc_packages.lab_testing_state
           FROM metrc_packages
          ORDER BY metrc_packages.tag, metrc_packages.license) p
     LEFT JOIN v_document_package_link l ON l.package_tag = p.tag
  GROUP BY p.tag, ("left"(p.item_name, 55)), p.source_state, p.lab_testing_state, (
        CASE
            WHEN f_is_weight(p.uom) THEN round(f_to_pounds(p.quantity, p.uom), 2)
            ELSE NULL::numeric
        END), (p.lab_testing_state = ANY (ARRAY['TestPassed'::text, 'TestFailed'::text])), ((EXISTS ( SELECT 1
           FROM metrc_rpt_package_transfers t
          WHERE t.package_tag = p.tag)));
create or replace view public.v_item_flags_all as
 WITH raw_flags AS (
         SELECT 'package'::text AS entity_type,
            r.row_key AS entity_key,
                CASE
                    WHEN r.agent_confidence = 'needs_a_person'::text THEN 'elevated'::text
                    ELSE 'watch'::text
                END AS severity,
            'Upload disagreement on '::text || r.field_name AS headline,
            (((('The file says '::text || COALESCE(r.value_in_the_file, '(blank)'::text)) || ' where we hold '::text) || COALESCE(r.value_we_hold, '(blank)'::text)) || COALESCE(' - a difference of '::text || round(r.difference, 4), ''::text)) || COALESCE((' ('::text || round(r.pct_difference, 2)) || '%)'::text, ''::text) AS detail,
            COALESCE(r.agent_reasoning, 'No recommendation was recorded.'::text) AS why,
                CASE r.agent_recommendation
                    WHEN 'accept_file'::text THEN 'AgentMapper suggests taking the file value. Confirm or reject.'::text
                    WHEN 'keep_ours'::text THEN 'AgentMapper suggests keeping ours. Confirm or reject.'::text
                    ELSE 'AgentMapper could not decide. Someone who knows this record must choose.'::text
                END AS what_to_do,
            'import_reconciliation'::text AS source,
            r.id::text AS source_ref,
            r.created_at::date AS raised_on,
            r.report_key AS context,
            run.licence
           FROM import_reconciliation r
             LEFT JOIN import_reconciliation_run run ON run.id = r.run_id
          WHERE r.outcome = 'differs'::text AND r.decision IS NULL
        UNION ALL
         SELECT 'package'::text AS text,
            t.tag,
                CASE
                    WHEN c.urgency = 'urgent'::text THEN 'critical'::text
                    ELSE 'elevated'::text
                END AS "case",
            c.title,
            c.what_is_wrong,
            c.why_it_matters,
            c.how_to_fix_in_metrc,
            'metrc_corrections'::text AS text,
            (c.id::text || ':'::text) || t.tag,
            c.raised_on,
            'Metrc record'::text AS text,
            ( SELECT p.license
                   FROM metrc_packages p
                  WHERE p.tag = t.tag
                 LIMIT 1) AS license
           FROM metrc_corrections c
             CROSS JOIN LATERAL ( SELECT btrim(x.x) AS tag
                   FROM unnest(string_to_array(COALESCE(c.packages_affected, ''::text), ','::text)) x(x)) t
          WHERE c.fixed_in_metrc = false AND t.tag ~ '^1A[0-9A-Z]{22}$'::text AND (EXISTS ( SELECT 1
                   FROM metrc_packages p
                  WHERE p.tag = t.tag))
        UNION ALL
         SELECT 'correction'::text AS text,
            c.id::text AS id,
                CASE
                    WHEN c.urgency = 'urgent'::text THEN 'critical'::text
                    ELSE 'elevated'::text
                END AS "case",
            c.title,
            c.what_is_wrong,
            c.why_it_matters,
            c.how_to_fix_in_metrc,
            'metrc_corrections'::text AS text,
            c.id::text AS id,
            c.raised_on,
            COALESCE(NULLIF(btrim(c.packages_affected), ''::text), 'Company-wide'::text) AS "coalesce",
            NULL::text AS text
           FROM metrc_corrections c
          WHERE c.fixed_in_metrc = false AND NOT (EXISTS ( SELECT 1
                   FROM unnest(string_to_array(COALESCE(c.packages_affected, ''::text), ','::text)) x(x)
                  WHERE btrim(x.x) ~ '^1A[0-9A-Z]{22}$'::text AND (EXISTS ( SELECT 1
                           FROM metrc_packages p
                          WHERE p.tag = btrim(x.x)))))
        UNION ALL
         SELECT 'package'::text AS text,
            p.package_tag,
                CASE
                    WHEN p.verdict ~~ 'METRC HOLDS ZERO%'::text THEN 'critical'::text
                    ELSE 'elevated'::text
                END AS "case",
            'Potency disagrees with the COA'::text AS text,
            ((((((((('Metrc records '::text || p.metrc_value) || ' '::text) || COALESCE(p.metrc_unit, ''::text)) || '; COA '::text) || COALESCE(p.coa_document, '(no document id)'::text)) || ' reports '::text) || p.coa_percent) || '%. Difference '::text) || p.difference) || ' percentage points.'::text,
            'The certificate of analysis is independent of Metrc, so it is the only thing that can catch a wrong figure inside Metrc.'::text AS text,
            'Compare against the COA document and raise a Metrc correction if the state record is wrong. Do not edit the figure only here.'::text AS text,
            'v_potency_vs_coa'::text AS text,
            p.package_tag,
            CURRENT_DATE AS "current_date",
            'Lab result'::text AS text,
            p.license
           FROM v_potency_vs_coa p
          WHERE p.verdict = ANY (ARRAY['disagrees with the COA - needs a person'::text, 'METRC HOLDS ZERO, THE COA DOES NOT - raise a correction'::text])
        UNION ALL
         SELECT 'package'::text AS text,
            p.tag,
            'critical'::text AS text,
            ('OUR OWN '::text || upper(COALESCE(p.raw #>> '{Item,ProductCategoryName}'::text[], 'material'::text))) || ' FAILED TESTING - address with the team'::text AS text,
            ((((((((round(COALESCE(p.quantity, 0::numeric) / f_rule('grams_per_pound'::text), 1) || ' lb of '::text) || COALESCE(p.item_name, '(unnamed)'::text)) || COALESCE((' (strain '::text || (p.raw #>> '{Item,StrainName}'::text[])) || ')'::text, ''::text)) || ' in '::text) || COALESCE(p.location, 'no location recorded'::text)) || '. Failed on: '::text) || COALESCE(( SELECT string_agg(DISTINCT r.test_name, '; '::text) AS string_agg
                   FROM metrc_lab_results r
                  WHERE r.package_tag = p.tag AND r.passed = false), 'NO FAILED TEST ON RECORD - the reason was never captured, so nobody can act on it'::text)) || '. Source harvests: '::text) || COALESCE(NULLIF(p.raw ->> 'SourceHarvestNames'::text, ''::text), 'not recorded'::text) AS text,
            (('This is our own production failing, which is a team matter before it is a stock matter. '::text || 'The material is remediated and processed either way, so this is not a money loss - '::text) || 'it is the signal that something in growing, drying or extraction produced it. '::text) || 'Remediating it recovers the value and answers nothing about the cause.'::text AS text,
            ('Raise it with the team responsible, trace it to the source harvest and room, and record '::text || 'what is being changed. THEN remediate and process. Where no failed test is on record, '::text) || 'get the result from the laboratory first - without it the team has nothing to act on.'::text AS text,
            'failed_own_material'::text AS text,
            p.tag,
            CURRENT_DATE AS "current_date",
            COALESCE(p.raw #>> '{Item,ProductCategoryName}'::text[], 'Failed testing'::text) AS "coalesce",
            p.license
           FROM metrc_packages p
          WHERE p.lab_testing_state = 'TestFailed'::text AND (p.source_state = ANY (ARRAY['active'::text, 'onhold'::text])) AND ((p.raw ->> 'ItemFromFacilityLicenseNumber'::text) = ANY (ARRAY['MC281714'::text, 'MP281909'::text]))
        UNION ALL
         SELECT 'package'::text AS text,
            a.package_tag,
            'watch'::text AS text,
            'Conflicting adjustment records'::text AS text,
            ((('We hold '::text || a.rows_held) || ' adjustment rows for this package with '::text) || a.distinct_quantities) || ' different quantities.'::text,
            COALESCE(a.reading, 'The same package was adjusted to more than one quantity.'::text) AS "coalesce",
            'Establish which adjustment is correct and record the decision.'::text AS text,
            'v_adjustment_conflicts'::text AS text,
            a.package_tag,
            COALESCE(a.adjusted_on, CURRENT_DATE) AS "coalesce",
            'Adjustment'::text AS text,
            a.licence
           FROM v_adjustment_conflicts a
          WHERE a.needs_a_decision
        )
 SELECT f.entity_type,
    f.entity_key,
        CASE
            WHEN d.decision = 'fixed'::text THEN 'critical'::text
            ELSE f.severity
        END AS severity,
    f.headline,
    f.detail,
    f.why,
    f.what_to_do,
    f.source,
    f.source_ref,
    f.raised_on,
    f.context,
        CASE
            WHEN d.id IS NULL THEN 'open'::text
            WHEN d.decision = 'fixed'::text THEN 'MARKED FIXED BUT STILL PRESENT'::text
            WHEN d.decision = 'ignored'::text AND d.review_on <= CURRENT_DATE THEN 'ignore expired - back for review'::text
            WHEN d.decision = 'ignored'::text THEN 'ignored until '::text || d.review_on
            ELSE d.decision
        END AS disposition,
    d.reason AS decision_reason,
    d.note AS decision_note,
    d.decided_by,
    d.decided_at,
    d.review_on,
    d.id IS NULL OR d.decision = 'fixed'::text OR d.decision = 'ignored'::text AND d.review_on <= CURRENT_DATE AS needs_a_decision,
    f.licence,
    COALESCE(lp.short_name,
        CASE
            WHEN f.entity_type = 'correction'::text THEN 'Company-wide'::text
            ELSE 'Not attributed to a licence'::text
        END) AS area,
    lp.colour AS area_colour,
    CURRENT_DATE - f.raised_on AS days_open
   FROM raw_flags f
     LEFT JOIN licence_profile lp ON lp.licence = f.licence
     LEFT JOIN item_flag_decision d ON d.entity_type = f.entity_type AND d.entity_key = f.entity_key AND d.source = f.source AND d.source_ref = f.source_ref AND d.superseded_at IS NULL;
create or replace view public.v_late_violations as
 SELECT event_type,
    room,
    cultivars AS detail,
    scheduled_date,
    actual_date,
    days_off_schedule,
        CASE
            WHEN compliance ~~ 'MISSED%'::text THEN 'VIOLATION - never happened'::text
            WHEN compliance ~~ 'LATE%'::text OR compliance ~~ 'DRY DEADLINE%'::text THEN 'VIOLATION - ran late'::text
            WHEN compliance ~~ 'Early%'::text THEN 'Acceptable - early'::text
            ELSE 'On schedule'::text
        END AS rule_verdict,
        CASE
            WHEN compliance ~~ 'MISSED%'::text OR compliance ~~ 'LATE%'::text OR compliance ~~ 'DRY DEADLINE%'::text THEN 'Every day late pushes the next cycle in this room. Weekend crew or second shift is the remedy, never a slipped date.'::text
            ELSE NULL::text
        END AS why_it_matters
   FROM v_schedule_compliance
  WHERE compliance <> 'Scheduled'::text
  ORDER BY (
        CASE
            WHEN compliance ~~ 'MISSED%'::text THEN 0
            WHEN compliance ~~ 'LATE%'::text OR compliance ~~ 'DRY DEADLINE%'::text THEN 1
            ELSE 2
        END), days_off_schedule DESC NULLS LAST;
create or replace view public.v_package_dossier as
 WITH p AS (
         SELECT DISTINCT ON (metrc_packages.tag) metrc_packages.tag,
            metrc_packages.item_name,
            metrc_packages.license,
            metrc_packages.uom,
            metrc_packages.quantity,
            metrc_packages.source_state,
            metrc_packages.lab_testing_state,
            metrc_packages.packaged_on,
            metrc_packages.raw
           FROM metrc_packages
          ORDER BY metrc_packages.tag, metrc_packages.license
        ), cert_doc AS (
         SELECT l_1.package_tag,
            min(d.metrc_id) AS coa_number,
            min(d.storage_path) AS coa_file,
            min(d.byte_size) AS coa_bytes,
            min(d.fetched_at)::date AS coa_fetched
           FROM v_document_package_link l_1
             JOIN metrc_documents d ON d.id = l_1.document_id
          WHERE l_1.doc_type = 'coa'::text
          GROUP BY l_1.package_tag
        ), man_doc AS (
         SELECT l_1.package_tag,
            string_agg(DISTINCT l_1.manifest_number, ', '::text ORDER BY l_1.manifest_number) AS manifest_numbers,
            min(d.storage_path) AS manifest_file,
            count(DISTINCT l_1.manifest_number) AS manifest_count
           FROM v_document_package_link l_1
             JOIN metrc_documents d ON d.id = l_1.document_id
          WHERE l_1.doc_type = 'manifest'::text
          GROUP BY l_1.package_tag
        ), labs AS (
         SELECT metrc_lab_results.package_tag,
            count(*) AS tests_run,
            count(*) FILTER (WHERE metrc_lab_results.passed IS FALSE) AS tests_failed,
            string_agg(DISTINCT metrc_lab_results.test_name, '; '::text) FILTER (WHERE metrc_lab_results.passed IS FALSE) AS failed_analytes,
            max(metrc_lab_results.lab_facility) AS laboratory,
            max(metrc_lab_results.result_date) AS tested_on,
            max((metrc_lab_results.raw ->> 'ExpirationDateTime'::text)::date) AS coa_valid_until,
            min(metrc_lab_results.result_date) AS first_tested_on,
            max(metrc_lab_results.raw ->> 'LabFacilityLicenseNumber'::text) AS lab_licence
           FROM metrc_lab_results
          GROUP BY metrc_lab_results.package_tag
        ), harv AS (
         SELECT h_1.name,
            min(h_1.raw ->> 'HarvestType'::text) AS harvest_type,
            min((h_1.raw ->> 'HarvestStartDate'::text)::date) AS cut_on,
            min(h_1.raw ->> 'DryingRoomName'::text) AS drying_room,
            sum((h_1.raw ->> 'TotalWetWeight'::text)::numeric) AS wet_g,
            sum((h_1.raw ->> 'TotalWasteWeight'::text)::numeric) AS waste_g,
            sum((h_1.raw ->> 'TotalPackagedWeight'::text)::numeric) AS packaged_g,
            sum((h_1.raw ->> 'PlantCount'::text)::numeric) AS plants
           FROM metrc_harvests h_1
          GROUP BY h_1.name
        ), ship AS (
         SELECT t.package_tag,
            string_agg(DISTINCT c.delivered_to, ', '::text) AS shipped_to,
            string_agg(DISTINCT c.destination_kind, ', '::text) AS destination_kind,
            string_agg(DISTINCT c.carried_by, ', '::text) AS transporter,
            max(c.date_created) AS last_shipped_on,
            max(NULLIF(t.source_row ->> 'Shipper Wholesale Price'::text, ''::text)::numeric) AS declared_price
           FROM metrc_rpt_package_transfers t
             JOIN v_manifest_custody c ON c.manifest_number = t.manifest_number
          GROUP BY t.package_tag
        )
 SELECT p.tag AS package_tag,
    p.item_name,
    p.raw #>> '{Item,StrainName}'::text[] AS strain,
    p.raw #>> '{Item,ProductCategoryName}'::text[] AS category,
    p.raw #>> '{Item,ProductCategoryType}'::text[] AS category_type,
        CASE
            WHEN p.license = 'MC281714'::text THEN 'Cultivation'::text
            ELSE 'Manufacturing'::text
        END AS department,
    p.license AS licence,
    f_quantity_text(p.quantity, p.uom) AS quantity,
    p.source_state AS status,
    p.raw ->> 'LocationName'::text AS room,
    e.client_name AS cultivator_on_certificate,
    e.client_license AS cultivator_licence,
    e.client_address AS cultivator_address,
    p.raw ->> 'ItemFromFacilityName'::text AS item_defined_by,
    oc.custody_says AS custody_origin_licences,
    oc.custody_verdict AS ownership_verdict,
    cd.coa_number,
    e.lab_report_id AS lab_report_number,
    cd.coa_file AS coa_storage_path,
    cr.certificate_link AS certificate_basis,
    cr.certificate_on_package AS certificate_sampled_package,
    l.laboratory,
    l.tested_on,
    l.coa_valid_until,
    l.coa_valid_until < CURRENT_DATE AS certificate_expired,
    md.manifest_numbers,
    md.manifest_file AS manifest_storage_path,
    NULLIF(p.raw ->> 'ReceivedFromManifestNumber'::text, ''::text) AS arrived_on_manifest,
    NULLIF(p.raw ->> 'ReceivedFromFacilityName'::text, ''::text) AS received_from,
    e.metrc_batch_id AS batch_on_certificate,
    NULLIF(p.raw ->> 'ProductionBatchNumber'::text, ''::text) AS production_batch,
    NULLIF(p.raw ->> 'SourceHarvestNames'::text, ''::text) AS source_harvest,
    h.cut_on AS harvest_date,
    h.harvest_type,
    h.drying_room,
    p.packaged_on,
    CURRENT_DATE - p.packaged_on AS days_held,
    (p.raw ->> 'SourcePackageCount'::text)::integer AS made_from_n_packages,
    "left"(NULLIF(p.raw ->> 'SourcePackageLabels'::text, ''::text), 160) AS made_from_packages,
    p.lab_testing_state AS lab_state,
    l.tests_run,
    l.tests_failed,
    l.failed_analytes,
    e.total_thc,
    e.total_cbd,
    e.total_terpenes,
    e.total_cannabinoids,
    e.microbiology,
    e.mycotoxins,
    e.heavy_metals,
    e.pesticides,
    e.solvents,
    e.pathogens,
    e.water_activity,
        CASE
            WHEN cd.coa_number IS NOT NULL AND md.manifest_numbers IS NOT NULL THEN 'COMPLETE - certificate and manifest both held'::text
            WHEN cd.coa_number IS NOT NULL THEN 'certificate only - no manifest'::text
            WHEN md.manifest_numbers IS NOT NULL THEN 'manifest only - no certificate'::text
            ELSE 'NEITHER - no legal document held for this package'::text
        END AS proof_status,
    'Open either document with supabase.storage.from(''metrc-documents'').createSignedUrl(path, ttl) at click time. The file is permanent; never store the URL.'::text AS how_to_open,
        CASE
            WHEN f_is_weight(p.uom) THEN round(f_to_pounds(p.quantity, p.uom), 3)
            ELSE NULL::numeric
        END AS pounds,
        CASE
            WHEN NOT f_is_weight(p.uom) THEN p.quantity
            ELSE NULL::numeric
        END AS units,
    p.uom AS unit_of_measure,
    p.quantity AS quantity_raw,
    (p.raw ->> 'CreatedQuantity'::text)::numeric AS created_quantity,
    (p.raw ->> 'OriginalPackageQuantity'::text)::numeric AS original_quantity,
    (p.raw ->> 'ReceivedQuantity'::text)::numeric AS received_quantity,
    round(COALESCE((p.raw ->> 'CreatedQuantity'::text)::numeric, 0::numeric) - COALESCE(p.quantity, 0::numeric), 3) AS consumed_since_creation,
        CASE
            WHEN f_is_weight(p.uom) AND (p.raw #>> '{Item,ProductCategoryName}'::text[]) ~~* '%fresh frozen%'::text THEN 'wet'::text
            WHEN f_is_weight(p.uom) THEN 'dry'::text
            ELSE NULL::text
        END AS weight_basis,
    p.raw #>> '{Item,Id}'::text[] AS item_id,
    p.raw #>> '{Item,UnitWeight}'::text[] AS unit_weight,
    p.raw #>> '{Item,UnitWeightUnitOfMeasureName}'::text[] AS unit_weight_uom,
    p.raw #>> '{Item,UnitThcPercent}'::text[] AS unit_thc_percent,
    p.raw #>> '{Item,ServingSize}'::text[] AS serving_size,
    p.raw #>> '{Item,ItemBrandName}'::text[] AS brand,
    p.raw #>> '{Item,AdministrationMethod}'::text[] AS administration_method,
    p.raw #>> '{Item,QuantityType}'::text[] AS quantity_type,
    (p.raw ->> 'ReceivedDateTime'::text)::date AS received_on,
    (p.raw ->> 'LabTestingStateDate'::text)::date AS lab_state_dated,
    (p.raw ->> 'LabTestingRecordedDate'::text)::date AS lab_result_recorded_on,
    (p.raw ->> 'ExpirationDate'::text)::date AS expiration_date,
    (p.raw ->> 'SellByDate'::text)::date AS sell_by_date,
    (p.raw ->> 'UseByDate'::text)::date AS use_by_date,
    (p.raw ->> 'FinishedDate'::text)::date AS finished_date,
    (p.raw ->> 'ArchivedDate'::text)::date AS archived_date,
    (p.raw ->> 'LastModified'::text)::date AS last_modified,
    (p.raw ->> 'RemediationDate'::text)::date AS remediation_date,
    (p.raw ->> 'DecontaminationDate'::text)::date AS decontamination_date,
    (p.raw ->> 'IsOnHold'::text)::boolean AS on_hold,
    (p.raw ->> 'IsFinished'::text)::boolean AS finished,
    (p.raw ->> 'IsOnRecall'::text)::boolean AS on_recall,
    (p.raw ->> 'IsTradeSample'::text)::boolean AS trade_sample,
    (p.raw ->> 'IsDonation'::text)::boolean AS donation,
    (p.raw ->> 'IsTestingSample'::text)::boolean AS testing_sample,
    (p.raw ->> 'IsProductionBatch'::text)::boolean AS production_batch_flag,
    (p.raw ->> 'ContainsRemediatedProduct'::text)::boolean AS contains_remediated,
    (p.raw ->> 'ProductRequiresRemediation'::text)::boolean AS requires_remediation,
    (p.raw ->> 'IsOnInvestigation'::text)::boolean AS on_investigation,
    NULLIF(p.raw ->> 'SublocationName'::text, ''::text) AS sublocation,
    p.raw ->> 'LocationTypeName'::text AS room_type,
    ((p.raw ->> 'SourcePackageCount'::text)::integer) = 0 AS is_primary_production,
    round(h.wet_g / 453.59237, 1) AS harvest_wet_lb,
    round(h.waste_g / 453.59237, 1) AS harvest_waste_lb,
    round(h.packaged_g / 453.59237, 1) AS harvest_packaged_lb,
    h.plants AS harvest_plants,
        CASE
            WHEN h.wet_g > 0::numeric THEN round((1::numeric - h.packaged_g / h.wet_g) * 100::numeric, 1)
            ELSE NULL::numeric
        END AS harvest_moisture_loss_pct,
    p.packaged_on - h.cut_on AS days_cut_to_package,
    s.shipped_to,
    s.destination_kind,
    s.transporter,
    s.last_shipped_on,
    md.manifest_count AS manifests_held,
    s.declared_price AS declared_transfer_price,
        CASE
            WHEN f_is_weight(p.uom) AND f_is_ours(p.raw ->> 'ItemFromFacilityLicenseNumber'::text) THEN round(f_to_pounds(p.quantity, p.uom) * (( SELECT cm.cost_per_pound
               FROM cost_model cm
              WHERE cm.scope = 'cultivation'::text
              ORDER BY cm.effective_from DESC
             LIMIT 1)), 0)
            ELSE NULL::numeric
        END AS value_at_our_cost,
        CASE
            WHEN NOT f_is_weight(p.uom) THEN 'countable - no cost per pound'::text
            WHEN NOT f_is_ours(p.raw ->> 'ItemFromFacilityLicenseNumber'::text) THEN 'bought in - material_purchases is EMPTY, what was paid exists nowhere'::text
            ELSE 'our cultivation cost per pound'::text
        END AS cost_basis,
    sup.supplier_name,
    sup.bought_as,
    sup.typical_discount_pct,
    l.lab_licence,
    l.first_tested_on,
    cd.coa_bytes,
    cd.coa_fetched,
    e.report_date AS coa_report_date,
    e.metrc_sample_id AS coa_sample_id,
    e.metrc_source_id AS coa_source_package
   FROM p
     LEFT JOIN cert_doc cd ON cd.package_tag = p.tag
     LEFT JOIN man_doc md ON md.package_tag = p.tag
     LEFT JOIN labs l ON l.package_tag = p.tag
     LEFT JOIN v_certificate_resolved cr ON cr.package_tag = p.tag
     LEFT JOIN coa_extract e ON e.document_id = cd.coa_number
     LEFT JOIN v_ownership_by_custody oc ON oc.package_tag = p.tag
     LEFT JOIN harv h ON h.name = split_part(NULLIF(p.raw ->> 'SourceHarvestNames'::text, ''::text), ','::text, 1)
     LEFT JOIN ship s ON s.package_tag = p.tag
     LEFT JOIN suppliers sup ON sup.origin_license = (p.raw ->> 'ItemFromFacilityLicenseNumber'::text);
create or replace view public.v_remediation_yield as
 SELECT src.supplier,
    src.source_tag,
    src.source_item,
    src.strain,
    src.received_qty AS material_in,
    src.source_uom,
    count(*) AS products_made,
    round(sum(child.made_qty)) AS output_qty,
    string_agg(DISTINCT child.made_into_category, ', '::text) AS became,
    round(100.0 * sum(child.made_qty) / NULLIF(src.received_qty, 0::numeric), 1) AS recovery_pct,
    count(*) FILTER (WHERE child.made_lab_state = 'TestPassed'::text) AS output_passed,
    count(*) FILTER (WHERE child.made_lab_state = 'TestFailed'::text) AS output_failed
   FROM v_third_party_downstream src
     JOIN v_third_party_downstream child ON child.source_tag = src.source_tag
  GROUP BY src.supplier, src.source_tag, src.source_item, src.strain, src.received_qty, src.source_uom
  ORDER BY src.received_qty DESC NULLS LAST;
create or replace view public.v_schedule_scorecard as
 SELECT event_type,
    count(*) FILTER (WHERE compliance = 'On schedule'::text OR compliance = 'Dry complete'::text OR compliance = 'Scheduled'::text)::numeric AS on_schedule,
    count(*) FILTER (WHERE compliance ~~ 'LATE%'::text OR compliance ~~ 'DRY DEADLINE%'::text)::numeric AS late,
    count(*) FILTER (WHERE compliance ~~ 'MISSED%'::text)::numeric AS missed,
    count(*) FILTER (WHERE compliance ~~ 'Early%'::text)::numeric AS early,
    count(*)::numeric AS total,
    round(100.0 * count(*) FILTER (WHERE compliance = ANY (ARRAY['On schedule'::text, 'Dry complete'::text, 'Scheduled'::text]))::numeric / NULLIF(count(*), 0)::numeric, 1) AS pct_on_schedule,
    round(avg(days_off_schedule) FILTER (WHERE days_off_schedule > 0), 1) AS average_days_late
   FROM v_schedule_compliance
  GROUP BY event_type;
create or replace view public.v_stock_proof as
 SELECT s.package_tag,
    s.item_name,
    s.strain,
    s.stream,
    s.origin,
    s.made_by,
    s.shipped_to_us_by,
    s.license,
    s.location,
    s.days_here,
    s.packaged_on,
    s.quantity,
    s.uom,
    s.pounds,
    s.units,
    s.quantity_shown,
    s.sold_by_weight,
    s.lab_state,
        CASE s.lab_state
            WHEN 'TestPassed'::text THEN 'Sellable now'::text
            WHEN 'RetestPassed'::text THEN 'Sellable now'::text
            WHEN 'TestFailed'::text THEN 'Failed testing'::text
            WHEN 'RetestFailed'::text THEN 'Failed testing'::text
            WHEN 'NotSubmitted'::text THEN 'Never submitted'::text
            ELSE 'At the laboratory'::text
        END AS band,
    f_test_status(s.lab_state, s.submitted_on, s.result_on) AS test_status,
    s.submitted_on AS went_out_for_testing_on,
    s.result_on AS came_back_on,
        CASE
            WHEN s.result_on IS NOT NULL AND s.submitted_on IS NOT NULL THEN s.result_on - s.submitted_on
            WHEN s.submitted_on IS NOT NULL AND (s.lab_state = ANY (ARRAY['SubmittedForTesting'::text, 'TestingInProgress'::text])) THEN CURRENT_DATE - s.submitted_on
            ELSE NULL::integer
        END AS days_at_the_laboratory,
    s.coa_expires AS certificate_valid_to,
    lr.total_thc,
    lr.total_cbd,
    lr.total_terpenes,
    lr.laboratory,
    lr.coa_url,
    f_potency_status(lr.total_thc, lr.total_terpenes, s.lab_state) AS potency_and_certificate,
    s.inbound_manifest,
        CASE
            WHEN s.inbound_manifest IS NULL THEN 'NO MANIFEST — created here from our own harvest or another of our packages, so it never moved '::text || 'between licences. Manifests exist only for material that changed hands.'::text
            ELSE ('Manifest '::text || s.inbound_manifest) || COALESCE(' from '::text || NULLIF(s.shipped_to_us_by, '—'::text), ''::text)
        END AS manifest_proof,
    s.source_harvest,
    s.harvest_cut_on,
    s.dried_in,
    s.harvest_closed_on,
    s.made_from_packages,
    s.production_batch,
    s.traceability,
    f_rate_for(s.stream) AS rate_per_pound_used,
    round(COALESCE(s.pounds, 0::numeric) * f_rate_for(s.stream)) AS value_at_our_rate
   FROM v_stock_packages s
     LEFT JOIN LATERAL ( SELECT pi.package_tag,
            pi.item_name,
            pi.strain,
            pi.category,
            pi.license,
            pi.location,
            pi.quantity,
            pi.unit_of_measure,
            pi.pounds,
            pi.packaged_on,
            pi.cultivator_or_manufacturer,
            pi.maker_note,
            pi.maker_license,
            pi.origin,
            pi.received_from,
            pi.manifest_number,
            pi.manifest_url,
            pi.manifest_status,
            pi.lab_state,
            pi.submitted_on,
            pi.result_on,
            pi.coa_expires,
            pi.total_thc,
            pi.total_cbd,
            pi.total_terpenes,
            pi.analyte_count,
            pi.analyte_note,
            pi.coa_url,
            pi.laboratory,
            pi.coa_status
           FROM v_product_identity pi
          WHERE pi.package_tag = s.package_tag
         LIMIT 1) lr ON true;
create or replace view public.v_third_party_cycle_time as
 SELECT supplier,
    count(*) AS packages,
    round(sum(qty_received)) AS qty_in,
    round(sum(qty_remaining)) AS qty_still_here,
    round(avg(days_receipt_to_test), 1) AS avg_days_to_test,
    round(avg(days_receipt_to_first_output), 1) AS avg_days_to_first_output,
    round(avg(days_receipt_to_first_sale), 1) AS avg_days_receipt_to_sale,
    max(days_since_received) AS oldest_untouched_days,
    count(*) FILTER (WHERE "position" ~~ 'SITTING%'::text) AS sitting_untouched,
    count(*) FILTER (WHERE "position" ~~ 'COMPLETE%'::text) AS completed,
    round(avg(recovery_pct), 1) AS avg_recovery_pct
   FROM v_third_party_lifecycle
  GROUP BY supplier
  ORDER BY (round(sum(qty_received))) DESC NULLS LAST;
create or replace view public.v_tower_inventory as
 WITH f AS (
         SELECT conversion_factors.value AS r
           FROM conversion_factors
          WHERE conversion_factors.key = 'fresh_frozen_wet_to_dry'::text
        ), s AS MATERIALIZED (
         SELECT v_stock_on_hand.origin,
            v_stock_on_hand.stream,
            v_stock_on_hand.license,
            v_stock_on_hand.lab_state,
            v_stock_on_hand.location,
            v_stock_on_hand.supplier,
            v_stock_on_hand.origin_license,
            v_stock_on_hand.packages,
            v_stock_on_hand.grams,
            v_stock_on_hand.pounds,
            v_stock_on_hand.oldest_days,
            v_stock_on_hand.oldest_packaged,
            v_stock_on_hand.strains,
            v_stock_on_hand.units,
            v_stock_on_hand.unit_of_measure,
            v_stock_on_hand.sold_by_weight,
            v_stock_on_hand.quantity_shown,
            v_stock_on_hand.stock_status
           FROM v_stock_on_hand
        ), tp AS MATERIALIZED (
         SELECT v_third_party_lifecycle.supplier,
            v_third_party_lifecycle.origin_license,
            v_third_party_lifecycle.inbound_manifest,
            v_third_party_lifecycle.received_on,
            v_third_party_lifecycle.tag,
            v_third_party_lifecycle.item_name,
            v_third_party_lifecycle.strain,
            v_third_party_lifecycle.category,
            v_third_party_lifecycle.held_under,
            v_third_party_lifecycle.location,
            v_third_party_lifecycle.qty_received,
            v_third_party_lifecycle.qty_remaining,
            v_third_party_lifecycle.uom,
            v_third_party_lifecycle.qty_consumed,
            v_third_party_lifecycle.lab_state,
            v_third_party_lifecycle.tested_on,
            v_third_party_lifecycle.days_receipt_to_test,
            v_third_party_lifecycle.products_made,
            v_third_party_lifecycle.became,
            v_third_party_lifecycle.output_qty,
            v_third_party_lifecycle.output_passed,
            v_third_party_lifecycle.output_failed,
            v_third_party_lifecycle.first_output_on,
            v_third_party_lifecycle.days_receipt_to_first_output,
            v_third_party_lifecycle.recovery_pct,
            v_third_party_lifecycle.first_shipped_on,
            v_third_party_lifecycle.outbound_manifests,
            v_third_party_lifecycle.sold_to,
            v_third_party_lifecycle.days_receipt_to_first_sale,
            v_third_party_lifecycle.days_since_received,
            v_third_party_lifecycle."position"
           FROM v_third_party_lifecycle
        ), sl AS MATERIALIZED (
         SELECT v_storage_limit_status.stream,
            v_storage_limit_status.location,
            v_storage_limit_status.max_lb,
            v_storage_limit_status.max_age_days,
            v_storage_limit_status.warn_at_pct,
            v_storage_limit_status.note,
            v_storage_limit_status.on_hand_lb,
            v_storage_limit_status.oldest_days,
            v_storage_limit_status.pct_of_limit,
            v_storage_limit_status.status
           FROM v_storage_limit_status
        )
 SELECT 'onhand_dried_flower_lb'::text AS metric,
    round(sum(s.pounds), 1) AS value,
    'Dried flower on hand, all licences'::text AS label,
    'stock'::text AS grp,
    'stock_summary'::text AS drill
   FROM s
  WHERE s.stream = 'Dried flower'::text
UNION ALL
 SELECT 'onhand_fresh_frozen_lb'::text AS metric,
    round(sum(s.pounds), 1) AS value,
    'Fresh frozen on hand, as recorded (still holds its water)'::text AS label,
    'stock'::text AS grp,
    'fresh_frozen_equiv'::text AS drill
   FROM s
  WHERE s.stream = 'Fresh frozen'::text
UNION ALL
 SELECT 'onhand_fresh_frozen_dry_equiv_lb'::text AS metric,
    round(sum(s.pounds) / (( SELECT f.r
           FROM f)), 1) AS value,
    'Fresh frozen in dry-equivalent pounds - the only figure comparable to dried flower'::text AS label,
    'stock'::text AS grp,
    'fresh_frozen_equiv'::text AS drill
   FROM s
  WHERE s.stream = 'Fresh frozen'::text
UNION ALL
 SELECT 'onhand_shake_trim_lb'::text AS metric,
    round(sum(s.pounds), 1) AS value,
    'Shake and trim on hand'::text AS label,
    'stock'::text AS grp,
    'stock_summary'::text AS drill
   FROM s
  WHERE s.stream = 'Shake and trim'::text
UNION ALL
 SELECT 'onhand_concentrate_lb'::text AS metric,
    round(sum(s.pounds), 1) AS value,
    'Concentrate on hand'::text AS label,
    'stock'::text AS grp,
    'stock_summary'::text AS drill
   FROM s
  WHERE s.stream = 'Concentrate'::text
UNION ALL
 SELECT 'onhand_total_dry_equiv_lb'::text AS metric,
    round(sum(
        CASE
            WHEN s.stream = 'Fresh frozen'::text THEN s.pounds / (( SELECT f.r
               FROM f))
            ELSE s.pounds
        END), 1) AS value,
    'Everything on hand in like-for-like dry-equivalent pounds'::text AS label,
    'stock'::text AS grp,
    'production_true_position'::text AS drill
   FROM s
UNION ALL
 SELECT 'onhand_grown_by_us_lb'::text AS metric,
    round(sum(s.pounds), 1) AS value,
    'On hand that we grew'::text AS label,
    'origin'::text AS grp,
    'own_vs_bought'::text AS drill
   FROM s
  WHERE s.origin = 'Grown by us'::text
UNION ALL
 SELECT 'onhand_bought_in_lb'::text AS metric,
    round(sum(s.pounds), 1) AS value,
    'On hand that we bought in'::text AS label,
    'origin'::text AS grp,
    'third_party_stock'::text AS drill
   FROM s
  WHERE s.origin = 'Bought in'::text
UNION ALL
 SELECT 'pct_bought_in'::text AS metric,
    round(100.0 * sum(s.pounds) FILTER (WHERE s.origin = 'Bought in'::text) / NULLIF(sum(s.pounds), 0::numeric), 1) AS value,
    'Percent of everything on hand that was bought in'::text AS label,
    'origin'::text AS grp,
    'own_vs_bought'::text AS drill
   FROM s
UNION ALL
 SELECT 'third_party_suppliers'::text AS metric,
    count(DISTINCT s.supplier)::numeric AS value,
    'Suppliers we currently hold material from'::text AS label,
    'origin'::text AS grp,
    'third_party_stock'::text AS drill
   FROM s
  WHERE s.origin = 'Bought in'::text
UNION ALL
 SELECT 'third_party_untouched_pkgs'::text AS metric,
    count(*)::numeric AS value,
    'Purchased packages received and never drawn from'::text AS label,
    'origin'::text AS grp,
    'third_party_lifecycle'::text AS drill
   FROM tp
  WHERE tp."position" ~~ 'RECEIVED%'::text OR tp."position" ~~ 'SITTING%'::text
UNION ALL
 SELECT 'third_party_sitting_over_90d'::text AS metric,
    count(*)::numeric AS value,
    'Purchased packages sitting untouched over 90 days'::text AS label,
    'origin'::text AS grp,
    'third_party_lifecycle'::text AS drill
   FROM tp
  WHERE tp."position" ~~ 'SITTING%'::text
UNION ALL
 SELECT 'sellable_lb'::text AS metric,
    round(sum(s.pounds), 1) AS value,
    'Test-passed and sellable'::text AS label,
    'quality'::text AS grp,
    'stock_summary'::text AS drill
   FROM s
  WHERE s.lab_state = 'TestPassed'::text
UNION ALL
 SELECT 'failed_testing_lb'::text AS metric,
    round(sum(s.pounds), 1) AS value,
    'Failed testing and held'::text AS label,
    'quality'::text AS grp,
    'failed_testing_by_origin'::text AS drill
   FROM s
  WHERE s.lab_state = 'TestFailed'::text
UNION ALL
 SELECT 'never_submitted_lb'::text AS metric,
    round(sum(s.pounds), 1) AS value,
    'Never submitted for testing'::text AS label,
    'quality'::text AS grp,
    'lab_results'::text AS drill
   FROM s
  WHERE s.lab_state = 'NotSubmitted'::text
UNION ALL
 SELECT 'out_for_testing_lb'::text AS metric,
    round(sum(s.pounds), 1) AS value,
    'Out for testing right now'::text AS label,
    'quality'::text AS grp,
    'lab_results'::text AS drill
   FROM s
  WHERE s.lab_state ~~ '%ubmitted%'::text AND s.lab_state <> 'NotSubmitted'::text
UNION ALL
 SELECT 'oldest_stock_days'::text AS metric,
    max(s.oldest_days)::numeric AS value,
    'Age of the oldest thing we own, in days'::text AS label,
    'ageing'::text AS grp,
    'stock_on_hand'::text AS drill
   FROM s
UNION ALL
 SELECT 'stock_over_180d_lb'::text AS metric,
    round(sum(s.pounds), 1) AS value,
    'On hand sitting over 180 days'::text AS label,
    'ageing'::text AS grp,
    'stock_on_hand'::text AS drill
   FROM s
  WHERE s.oldest_days > 180
UNION ALL
 SELECT 'limits_breached'::text AS metric,
    count(*)::numeric AS value,
    'Storage limits currently breached'::text AS label,
    'control'::text AS grp,
    'storage_limit_status'::text AS drill
   FROM sl
  WHERE sl.status = ANY (ARRAY['OVER THE STORAGE LIMIT'::text, 'MATERIAL OLDER THAN THE LIMIT'::text])
UNION ALL
 SELECT 'limits_not_set'::text AS metric,
    count(*)::numeric AS value,
    'Storage limits nobody has set yet'::text AS label,
    'control'::text AS grp,
    'storage_limits'::text AS drill
   FROM sl
  WHERE sl.status ~~ 'NO LIMIT%'::text
UNION ALL
 SELECT 'open_questions'::text AS metric,
    count(*)::numeric AS value,
    'Questions the platform needs answered'::text AS label,
    'control'::text AS grp,
    'open_questions'::text AS drill
   FROM open_questions
  WHERE open_questions.status = 'open'::text
UNION ALL
 SELECT 'allocations_pending'::text AS metric,
    count(*)::numeric AS value,
    'Allocations waiting on Vincent'::text AS label,
    'control'::text AS grp,
    'allocation_queue'::text AS drill
   FROM allocation_requests
  WHERE allocation_requests.status = 'pending'::text;
create materialized view if not exists public.mv_tower_counts as
 SELECT ( SELECT count(*) AS count
           FROM metrc_packages
          WHERE metrc_packages.source_state = ANY (ARRAY['active'::text, 'onhold'::text])) AS packages_active,
    ( SELECT count(*) AS count
           FROM metrc_packages) AS packages_all,
    ( SELECT count(*) AS count
           FROM metrc_plants
          WHERE metrc_plants.source_state = ANY (ARRAY['vegetative'::text, 'flowering'::text, 'onhold'::text])) AS plants_live,
    ( SELECT count(*) AS count
           FROM metrc_plants) AS plants_all,
    ( SELECT count(*) AS count
           FROM metrc_harvests) AS harvests,
    ( SELECT count(*) AS count
           FROM metrc_transfers) AS transfers,
    ( SELECT count(*) AS count
           FROM metrc_plant_batches) AS plant_batches,
    ( SELECT count(*) AS count
           FROM harvest_schedule) AS harvest_events,
    ( SELECT count(*) AS count
           FROM employees
          WHERE employees.terminated_on IS NULL) AS employees_active,
    ( SELECT count(*) AS count
           FROM actions_register
          WHERE actions_register.status = 'open'::text) AS actions_open,
    ( SELECT count(*) AS count
           FROM actions_register
          WHERE actions_register.status = 'open'::text AND actions_register.priority = 'P0'::text) AS actions_p0,
    ( SELECT count(*) AS count
           FROM golive_items
          WHERE golive_items.status <> 'done'::text) AS golive_open,
    ( SELECT count(*) AS count
           FROM v_custody_alerts) AS custody_flags,
    ( SELECT count(*) AS count
           FROM v_harvest_alerts) AS harvest_alerts,
    ( SELECT count(*) AS count
           FROM v_inventory_aging
          WHERE v_inventory_aging.severity = 'critical'::text) AS aging_critical,
    ( SELECT count(*) AS count
           FROM metrc_packages
          WHERE metrc_packages.lab_testing_state = 'TestFailed'::text AND (metrc_packages.source_state = ANY (ARRAY['active'::text, 'onhold'::text]))) AS failed_testing_on_hand,
    ( SELECT count(*) AS count
           FROM metrc_transfers
          WHERE metrc_transfers.direction = 'outgoing'::text AND (metrc_transfers.raw ->> 'ReceivedDateTime'::text) IS NULL AND metrc_transfers.created_on < (CURRENT_DATE - 3)) AS manifests_unconfirmed,
    ( SELECT max(metrc_sync_runs.started_at) AS max
           FROM metrc_sync_runs) AS last_sync,
    now() AS computed_at;
create materialized view if not exists public.mv_tower_inventory as
 SELECT metric,
    value,
    label,
    grp,
    drill
   FROM v_tower_inventory;
create or replace view public.v_ceo_dashboard as
 SELECT 'Money at stake'::text AS line,
    '$'::text || to_char(COALESCE(( SELECT sum(agent_findings.dollars) AS sum
           FROM agent_findings
          WHERE agent_findings.resolved_at IS NULL), 0::numeric), 'FM999,999,999'::text) AS headline,
    ((( SELECT count(*) AS count
           FROM agent_findings
          WHERE agent_findings.resolved_at IS NULL AND agent_findings.dollars > 0::numeric))::text) || ' findings carry a dollar figure'::text AS detail,
    1 AS sort
UNION ALL
 SELECT 'Critical findings'::text AS line,
    (( SELECT count(*) AS count
           FROM agent_findings
          WHERE agent_findings.resolved_at IS NULL AND agent_findings.severity = 'critical'::text))::text AS headline,
    ( SELECT string_agg(DISTINCT agent_findings.agent, ', '::text) AS string_agg
           FROM agent_findings
          WHERE agent_findings.resolved_at IS NULL AND agent_findings.severity = 'critical'::text) AS detail,
    2 AS sort
UNION ALL
 SELECT 'Schedule violations'::text AS line,
    (( SELECT count(*) AS count
           FROM v_late_violations
          WHERE v_late_violations.rule_verdict ~~ 'VIOLATION%'::text))::text AS headline,
    ('Hard rule: a pull or dry may be early, never late. '::text || COALESCE((( SELECT count(*) AS count
           FROM v_weekend_watch
          WHERE v_weekend_watch.action ~~ 'PLAN A WEEKEND%'::text))::text, '0'::text)) || ' upcoming events land on a weekend and need a crew planned'::text AS detail,
    3 AS sort
UNION ALL
 SELECT 'Compliance exposure'::text AS line,
    (( SELECT count(*) AS count
           FROM v_custody_alerts))::text AS headline,
    ((((( SELECT count(*) AS count
           FROM metrc_packages
          WHERE metrc_packages.lab_testing_state = 'TestFailed'::text AND (metrc_packages.source_state = ANY (ARRAY['active'::text, 'onhold'::text]))))::text) || ' failed-testing packages still in inventory · '::text) || ((( SELECT count(*) AS count
           FROM metrc_transfers
          WHERE metrc_transfers.direction = 'outgoing'::text AND (metrc_transfers.raw ->> 'ReceivedDateTime'::text) IS NULL AND metrc_transfers.created_on < (CURRENT_DATE - 3)))::text)) || ' manifests never confirmed received'::text AS detail,
    4 AS sort
UNION ALL
 SELECT 'Cost of waste to date'::text AS line,
    '$'::text || to_char(COALESCE(( SELECT sum(v_cost_of_loss.cost_of_waste) AS sum
           FROM v_cost_of_loss
          WHERE v_cost_of_loss.scope_type = 'Room'::text), 0::numeric), 'FM999,999,999'::text) AS headline,
    (('At $'::text || COALESCE(( SELECT cost_model.cost_per_pound
           FROM cost_model
          WHERE cost_model.scope = 'cultivation'::text
          ORDER BY cost_model.effective_from DESC
         LIMIT 1), 0::numeric)::text) || ' per pound. Worst room: '::text) || COALESCE(( SELECT v_cost_of_loss.scope
           FROM v_cost_of_loss
          WHERE v_cost_of_loss.scope_type = 'Room'::text
          ORDER BY v_cost_of_loss.cost_of_waste DESC
         LIMIT 1), 'none'::text) AS detail,
    5 AS sort
UNION ALL
 SELECT 'Material without approved allocation'::text AS line,
    (( SELECT count(*) AS count
           FROM v_awaiting_allocation))::text AS headline,
    'Every material grown or bought needs an approved allocation before it moves'::text AS detail,
    6 AS sort
UNION ALL
 SELECT 'Capital sitting too long'::text AS line,
    (( SELECT count(*) AS count
           FROM v_inventory_aging
          WHERE v_inventory_aging.severity = ANY (ARRAY['critical'::text, 'elevated'::text])))::text AS headline,
    'Aging stock flagged critical or elevated'::text AS detail,
    7 AS sort
UNION ALL
 SELECT 'Custody proof'::text AS line,
    COALESCE(( SELECT v_custody_compliance.location_known_pct::text || '%'::text
           FROM v_custody_compliance
          WHERE v_custody_compliance.category = 'ALL TRACKED INVENTORY'::text), '—'::text) AS headline,
    COALESCE(( SELECT v_custody_compliance.compliance_status
           FROM v_custody_compliance
          WHERE v_custody_compliance.category = 'ALL TRACKED INVENTORY'::text), ''::text) AS detail,
    8 AS sort
  ORDER BY 4;
create or replace view public.v_department_board as
 SELECT department,
    items_needing_action,
    open_alerts,
    live_records,
    what_is_wrong,
    next_deadline,
    next_deadline AS next_deadline_date
   FROM ( SELECT 'Cultivation'::text AS department,
            (( SELECT count(*) AS count
                   FROM v_harvest_lifecycle
                  WHERE v_harvest_lifecycle.verdict = ANY (ARRAY['BLOCKING THE ROOM'::text, 'MISSING WEIGHTS'::text, 'HARVESTED LATE'::text])))::numeric AS items_needing_action,
            (( SELECT count(*) AS count
                   FROM v_harvest_alerts))::numeric AS open_alerts,
            (( SELECT count(*) AS count
                   FROM metrc_plants
                  WHERE metrc_plants.source_state = ANY (ARRAY['vegetative'::text, 'flowering'::text, 'onhold'::text])))::numeric AS live_records,
            ( SELECT string_agg(DISTINCT v_harvest_lifecycle.verdict, ' · '::text) AS string_agg
                   FROM v_harvest_lifecycle
                  WHERE v_harvest_lifecycle.verdict <> ALL (ARRAY['Complete'::text, 'On track'::text])) AS what_is_wrong,
            ( SELECT min(harvest_pulls.harvest_date) AS min
                   FROM harvest_pulls
                  WHERE harvest_pulls.harvest_date >= CURRENT_DATE) AS next_deadline
        UNION ALL
         SELECT 'Post-harvest (dry, cure, trim)'::text AS department,
            (( SELECT count(*) AS count
                   FROM v_harvest_stage_map
                  WHERE v_harvest_stage_map.stage ~~ 'Drying%'::text AND v_harvest_stage_map.days_since_takedown > 14))::numeric AS items_needing_action,
            (( SELECT count(*) AS count
                   FROM v_harvest_stage_map
                  WHERE v_harvest_stage_map.stage <> ALL (ARRAY['Finished'::text, 'Archived'::text])))::numeric AS open_alerts,
            (( SELECT count(*) AS count
                   FROM v_harvest_stage_map
                  WHERE v_harvest_stage_map.stage <> ALL (ARRAY['Finished'::text, 'Archived'::text])))::numeric AS live_records,
            ( SELECT string_agg(DISTINCT v_harvest_stage_map.stage, ' · '::text) AS string_agg
                   FROM v_harvest_stage_map
                  WHERE v_harvest_stage_map.stage <> ALL (ARRAY['Finished'::text, 'Archived'::text])) AS what_is_wrong,
            ( SELECT min(v_harvest_stage_map.harvest_start + 14) AS min
                   FROM v_harvest_stage_map
                  WHERE v_harvest_stage_map.stage ~~ 'Drying%'::text) AS next_deadline
        UNION ALL
         SELECT 'Manufacturing'::text AS department,
            (( SELECT count(*) AS count
                   FROM v_turnaround_watch
                  WHERE v_turnaround_watch.turnaround_violation))::numeric AS items_needing_action,
            (( SELECT count(*) AS count
                   FROM v_turnaround_watch
                  WHERE v_turnaround_watch.no_policy_set))::numeric AS open_alerts,
            (( SELECT count(*) AS count
                   FROM pipeline_runs
                  WHERE pipeline_runs.completed_at IS NULL))::numeric AS live_records,
            'Open production runs and turnaround policy gaps'::text AS what_is_wrong,
            NULL::date AS next_deadline
        UNION ALL
         SELECT 'Quality & compliance'::text AS department,
            (( SELECT count(*) AS count
                   FROM metrc_packages
                  WHERE metrc_packages.lab_testing_state = 'TestFailed'::text AND (metrc_packages.source_state = ANY (ARRAY['active'::text, 'onhold'::text]))))::numeric AS items_needing_action,
            (( SELECT count(*) AS count
                   FROM v_custody_alerts))::numeric AS open_alerts,
            (( SELECT count(*) AS count
                   FROM metrc_packages
                  WHERE metrc_packages.lab_testing_state = ANY (ARRAY['SubmittedForTesting'::text, 'TestingInProgress'::text])))::numeric AS live_records,
            'Failed testing on hand and custody red flags'::text AS what_is_wrong,
            NULL::date AS next_deadline
        UNION ALL
         SELECT 'Inventory & fulfilment'::text AS department,
            (( SELECT count(*) AS count
                   FROM v_inventory_aging
                  WHERE v_inventory_aging.severity = 'critical'::text))::numeric AS items_needing_action,
            (( SELECT count(*) AS count
                   FROM v_inventory_aging
                  WHERE v_inventory_aging.severity IS NOT NULL))::numeric AS open_alerts,
            (( SELECT count(*) AS count
                   FROM v_inventory_locator))::numeric AS live_records,
            'Aging stock and unconfirmed manifests'::text AS what_is_wrong,
            NULL::date AS next_deadline
        UNION ALL
         SELECT 'Human resources'::text AS department,
            (( SELECT count(*) AS count
                   FROM employees
                  WHERE employees.terminated_on IS NULL AND employees.primary_role_id IS NULL))::numeric AS items_needing_action,
            0::numeric AS open_alerts,
            (( SELECT count(*) AS count
                   FROM employees
                  WHERE employees.terminated_on IS NULL))::numeric AS live_records,
            'Roster records missing a position'::text AS what_is_wrong,
            NULL::date AS next_deadline) q;
